-- The Personal Intelligence schema and its seed rows in one migration: every schema, table, function, policy and grant a new database needs.

set local search_path = '';
set local check_function_bodies = false;

CREATE SCHEMA knowledge;

CREATE SCHEMA ledger;

CREATE SCHEMA projections;

CREATE SCHEMA queue;

CREATE SCHEMA vault;

CREATE FUNCTION knowledge.anchor_rulings(p_rulings text[]) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  with belief as (
    update knowledge.belief_rulings r
    set claim_type = n.type, evidence_ids = k.evidence_ids,
        entity_ids = array(select e.entity_id from knowledge.claim_entities e where e.claim_id = n.id order by e.entity_id collate "C")
    from knowledge.belief_rulings s
    cross join lateral (
      select array_agg(distinct h.evidence_id order by h.evidence_id) as evidence_ids,
             coalesce(min(h.id) filter (where h.id = s.claim_fp), min(h.id collate "C")) as claim_id
      from (
        select c.id, c.evidence_id from knowledge.claims c where c.fact_key_fp = s.fact_key_fp
        union select c.id, c.evidence_id from knowledge.claims c where c.legacy_fact_key_fp = s.fact_key_fp
        union select c.id, c.evidence_id from knowledge.claims c where c.legacy_alt_fact_key_fp = s.fact_key_fp) h
      join vault.evidence_items i on i.id = h.evidence_id
      where s.verdict <> 'reject' or (i.source_account_id = s.source_account_id and i.source_item_fp = s.source_item_fp)) k
    join knowledge.claims n on n.id = k.claim_id
    where r.ruling_id = s.ruling_id and s.claim_type is null
      and (anchor_rulings.p_rulings is null or s.ruling_id = any (anchor_rulings.p_rulings))
    returning 1),
  pair as (
    update knowledge.fact_rulings r
    set claim_type = n.type, a_evidence_ids = k.a_evidence_ids, b_evidence_ids = k.b_evidence_ids,
        entity_ids = array(select x.entity_id
                           from (select distinct e.entity_id from knowledge.claim_entities e
                                 where e.claim_id in (k.claim_id, k.b_claim_id)) x
                           order by x.entity_id collate "C")
    from knowledge.fact_rulings s
    cross join lateral (
      select array_agg(distinct h.evidence_id order by h.evidence_id) filter (where h.side = 'a') as a_evidence_ids,
             array_agg(distinct h.evidence_id order by h.evidence_id) filter (where h.side = 'b') as b_evidence_ids,
             min(h.id collate "C") filter (where h.side = 'a') as claim_id,
             min(h.id collate "C") filter (where h.side = 'b') as b_claim_id
      from (
        select 'a' as side, c.id, c.evidence_id from knowledge.claims c where c.fact_key_fp = s.a_fp
        union select 'a', c.id, c.evidence_id from knowledge.claims c where c.legacy_fact_key_fp = s.a_fp
        union select 'a', c.id, c.evidence_id from knowledge.claims c where c.legacy_alt_fact_key_fp = s.a_fp
        union select 'b', c.id, c.evidence_id from knowledge.claims c where c.fact_key_fp = s.b_fp
        union select 'b', c.id, c.evidence_id from knowledge.claims c where c.legacy_fact_key_fp = s.b_fp
        union select 'b', c.id, c.evidence_id from knowledge.claims c where c.legacy_alt_fact_key_fp = s.b_fp) h) k
    join knowledge.claims n on n.id = k.claim_id
    where r.ruling_id = s.ruling_id and s.claim_type is null and k.b_evidence_ids is not null
      and (anchor_rulings.p_rulings is null or s.ruling_id = any (anchor_rulings.p_rulings))
    returning 1)
  select ((select count(*) from belief) + (select count(*) from pair))::int
$$;

CREATE FUNCTION knowledge.belief_rulings_rechecks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_lift boolean := tg_op = 'UPDATE';
begin
  if (v_lift and not (old.lifted_at is null and new.lifted_at is not null)) or policy.is_restricted(new.compartments) then
    return null;
  end if;
  insert into ledger.trigger_rechecks (fact_key_fp, cause, exact, added_rulings, removed_rulings, compartments)
  select k.fp, ledger.trigger_cause('ruling'), not v_lift and new.verdict <> 'reject',
         case when v_lift then '{}'::text[] else array[new.ruling_id] end,
         case when v_lift then array[new.ruling_id] else '{}'::text[] end,
         new.compartments
  from (select new.fact_key_fp as fp
        union select c.fact_key_fp from knowledge.claims c where c.legacy_fact_key_fp = new.fact_key_fp
        union select c.fact_key_fp from knowledge.claims c where c.legacy_alt_fact_key_fp = new.fact_key_fp) k;
  return null;
end
$$;

CREATE FUNCTION knowledge.binding_label() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'knowledge'
    AS $$
begin
  select c.compartments, c.readers into new.compartments, new.readers
  from knowledge.claims c where c.id = new.claim_id;
  return new;
end
$$;

CREATE FUNCTION knowledge.card_answers_rechecks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_exact boolean := new.answer is not distinct from 'confirm' and new.supersedes is null;
begin
  insert into ledger.trigger_rechecks (fact_key_fp, cause, exact, decisions, confirmed_claims, compartments)
  select k.fact_key_fp, ledger.trigger_cause('ruling'), v_exact, array[new.id], case when v_exact then array[k.id] else '{}'::text[] end, k.compartments
  from ledger.cards c join knowledge.claims k on k.id = c.target_id
  where c.id = new.card_id and c.target_kind = 'claim' and not policy.is_restricted(k.compartments);
  return null;
end
$$;

CREATE FUNCTION knowledge.claim_entities_label() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  claim_compartments text[];
begin
  if cardinality(new.compartments) = 0 then
    return new;
  end if;
  select c.compartments into claim_compartments from knowledge.claims c where c.id = new.claim_id;
  if not found or new.compartments is distinct from claim_compartments then
    raise exception 'claim entity label differs from its claim' using errcode = '23514';
  end if;
  return new;
end
$$;

