CREATE FUNCTION knowledge.claim_relations_judged_now() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if starts_with(new.judged_by, 'model:') then
    new.judged_at := now();
  end if;
  return new;
end
$$;

CREATE FUNCTION knowledge.claim_relations_label() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_union text[];
begin
  if cardinality(new.compartments) = 0 then
    return new;
  end if;
  if (select count(distinct v.claim_key) from knowledge.claim_values v where v.claim_key in (new.from_claim_key, new.to_claim_key)) <> 2 then
    raise exception 'a relation names a claim the store does not hold' using errcode = '23514';
  end if;
  v_union := ledger.label(array(
    select x from knowledge.claim_values v cross join unnest(v.compartments) as x
    where v.claim_key in (new.from_claim_key, new.to_claim_key)));
  if new.compartments is distinct from v_union then
    raise exception 'a relation''s label is not the union of its claims''' using errcode = '23514';
  end if;
  if exists (
    select 1 from jsonb_array_elements(new.cites) as c (passage)
    left join vault.evidence_items e on e.id = c.passage ->> 'evidenceId'
    where jsonb_typeof(c.passage) <> 'object' or e.id is null or not (e.compartments <@ new.compartments)) then
    raise exception 'a relation cites an item outside its label' using errcode = '23514';
  end if;
  return new;
end
$$;

CREATE FUNCTION knowledge.claim_relations_orphaned() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from knowledge.claim_values v where v.claim_key = old.claim_key) then
    delete from knowledge.claim_relations r where r.from_claim_key = old.claim_key or r.to_claim_key = old.claim_key;
    delete from ledger.relation_checks c where c.claim_key = old.claim_key or c.other_key = old.claim_key;
    delete from ledger.relation_reports p where p.claim_keys @> array[old.claim_key];
  end if;
  return null;
end
$$;

CREATE FUNCTION knowledge.claim_releases_check() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  item_kind text;
  item_compartments text[];
begin
  select e.source_kind, e.compartments into item_kind, item_compartments from vault.evidence_items e where e.id = new.evidence_id;
  if not found or item_kind <> 'agent_record'
     or not ('own' = any (item_compartments))
     or not exists (select 1 from unnest(item_compartments) c where starts_with(c, 'agent:'))
     or exists (select 1 from unnest(item_compartments) c where c <> 'own' and not starts_with(c, 'agent:'))
     or not exists (
       select 1 from knowledge.owner_decisions o
       where o.id = new.ruling_id and o.tainted_at is null
         and not exists (select 1 from knowledge.owner_decisions s where s.supersedes = o.id)
         and ((new.via <> 'grant' and o.kind = 'answer' and o.answer = 'confirm'
               and not exists (select 1 from ledger.card_relays y where y.ruling_id = o.id)
               and exists (select 1 from ledger.cards c
                           where c.id = o.card_id and c.kind = 'about_you' and c.created_by = 'system:extract'
                             and c.compartments @> item_compartments and c.compartments <@ item_compartments
                             and c.target_kind = 'claim'
                             and (exists (select 1 from knowledge.claims k where k.id = c.target_id and k.evidence_id = new.evidence_id)
                               or not exists (select 1 from knowledge.claims k where k.id = c.target_id))))
           or (o.kind = 'owner_answer' and new.via = 'command'
               and exists (select 1 from ledger.agent_writes w where w.id = o.request_id and w.evidence_id = new.evidence_id))
           or (new.via = 'grant' and o.kind = 'release_grant'
               and not exists (select 1 from knowledge.release_lifts l where l.ruling_id = o.id)
               and exists (select 1 from ledger.agent_writes w
                           where w.evidence_id = new.evidence_id and w.tool = 'propose_about_you' and w.kind = 'proposal' and w.flagged_at is null
                             and w.client_id = o.details ->> 'client'
                             and exists (select 1 from knowledge.claims k where k.evidence_id = new.evidence_id and not k.released and k.type = o.details ->> 'kind')
                             and not exists (select 1 from knowledge.claims k where k.evidence_id = new.evidence_id and not k.released and k.type is distinct from o.details ->> 'kind')))))
  then
    raise exception 'release without the owner''s decision on its record' using errcode = '23514';
  end if;
  return new;
end
$$;

