CREATE FUNCTION knowledge.claims_added_rechecks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  insert into ledger.trigger_rechecks (fact_key_fp, cause, exact, added_claims, compartments)
  select n.fact_key_fp, ledger.trigger_cause('claim'), true, array_agg(n.id order by n.id collate "C"), n.compartments
  from new_rows n where not policy.is_restricted(n.compartments)
  group by n.fact_key_fp, n.compartments;
  return null;
end
$$;

CREATE FUNCTION knowledge.claims_label() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  item_compartments text[];
  item_readers text[];
  item_kind text;
begin
  if cardinality(new.compartments) = 0 then
    return new;
  end if;
  select e.compartments, e.readers, e.source_kind into item_compartments, item_readers, item_kind from vault.evidence_items e where e.id = new.evidence_id;
  if not found or new.readers is distinct from item_readers or (not new.released and not new.closes and not new.researched and new.compartments is distinct from item_compartments) then
    raise exception 'claim label differs from its evidence' using errcode = '23514';
  end if;
  if new.closes then
    if item_kind is distinct from 'agent_record' or not (new.compartments <@ item_compartments)
       or not (array(select c from unnest(item_compartments) c where not starts_with(c, 'agent:')) <@ new.compartments) then
      raise exception 'close claim without its commitment''s label' using errcode = '23514';
    end if;
    if not policy.close_claim_allowed(new.evidence_id, new.fact_key_fp, new.compartments) then
      raise exception 'close claim without its commitment''s label' using errcode = '23514';
    end if;
    return new;
  end if;
  if new.researched then
    if new.compartments is distinct from array['own']::text[] or item_kind is distinct from 'agent_record'
       or not ('own' = any (item_compartments))
       or exists (select 1 from unnest(item_compartments) c where c <> 'own' and not starts_with(c, 'agent:'))
       or not exists (select 1 from ledger.agent_writes w where w.evidence_id = new.evidence_id and w.kind = 'fill') then
      raise exception 'researched claim without its fill''s release' using errcode = '23514';
    end if;
    return new;
  end if;
  if not new.released then
    return new;
  end if;
  if new.compartments is distinct from array['own']::text[] or item_kind is distinct from 'agent_record'
     or not ('own' = any (item_compartments))
     or not exists (select 1 from unnest(item_compartments) c where starts_with(c, 'agent:'))
     or exists (select 1 from unnest(item_compartments) c where c <> 'own' and not starts_with(c, 'agent:')) then
    raise exception 'released claim without the owner''s release of its record' using errcode = '23514';
  end if;
  if not exists (select 1 from policy.released_records() r where r.evidence_id = new.evidence_id) then
    raise exception 'released claim without the owner''s release of its record' using errcode = '23514';
  end if;
  return new;
end
$$;

CREATE FUNCTION knowledge.claims_left_key() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  perform pg_advisory_xact_lock(hashtext('intelligence personal trigger'), hashtext(old.fact_key_fp) & 255);
  if exists (select 1 from knowledge.claims c where c.evidence_id = old.evidence_id and c.fact_key_fp = old.fact_key_fp) then
    return null;
  end if;
  delete from ledger.trigger_log t where t.fact_key_fp = old.fact_key_fp and old.compartments <@ string_to_array(t.clearance_key, '|');
  delete from ledger.trigger_rechecks r where r.added_claims && array[old.id] or r.removed_claims && array[old.id] or r.confirmed_claims && array[old.id];
  if not policy.is_restricted(old.compartments) and exists (select 1 from knowledge.claims c where c.fact_key_fp = old.fact_key_fp) then
    insert into ledger.trigger_rechecks (fact_key_fp, cause, exact, compartments) values (old.fact_key_fp, ledger.trigger_cause('claim'), false, old.compartments);
  end if;
  return null;
end
$$;

CREATE FUNCTION knowledge.claims_relabelled_rechecks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  insert into ledger.trigger_rechecks (fact_key_fp, cause, exact, added_claims, removed_claims, compartments)
  select new.fact_key_fp, ledger.trigger_cause('claim'), r.exact, r.added, r.removed, r.compartments
  from (values (false, '{}'::text[], array[new.id], old.compartments), (true, array[new.id], '{}'::text[], new.compartments)) as r (exact, added, removed, compartments)
  where not policy.is_restricted(r.compartments);
  return null;
end
$$;

CREATE FUNCTION knowledge.claims_removed_rechecks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_bucket integer;
begin
  for v_bucket in select distinct hashtext(o.fact_key_fp) & 255 from old_rows o order by 1 loop
    perform pg_advisory_xact_lock(hashtext('intelligence personal trigger'), v_bucket);
  end loop;
  insert into ledger.trigger_rechecks (fact_key_fp, cause, exact, removed_claims, removed_items, compartments)
  select o.fact_key_fp, ledger.trigger_cause('claim'), false, array_agg(o.id order by o.id collate "C"), array_agg(distinct (o.evidence_id collate "C") order by (o.evidence_id collate "C")), o.compartments
  from old_rows o
  where not policy.is_restricted(o.compartments)
  group by o.fact_key_fp, o.compartments;
  return null;
end
$$;

CREATE FUNCTION knowledge.fact_rulings_rechecks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_lift boolean := tg_op = 'UPDATE';
begin
  if (v_lift and not (old.lifted_at is null and new.lifted_at is not null)) or policy.is_restricted(new.compartments) then
    return null;
  end if;
  insert into ledger.trigger_rechecks (fact_key_fp, cause, exact, added_rulings, removed_rulings, compartments)
  select k.fp, ledger.trigger_cause('ruling'), not v_lift,
         case when v_lift then '{}'::text[] else array[new.ruling_id] end,
         case when v_lift then array[new.ruling_id] else '{}'::text[] end,
         new.compartments
  from (values (new.a_fp), (new.b_fp)) as k (fp);
  return null;
end
$$;

CREATE FUNCTION knowledge.forget_ruling_anchors(p_evidence_ids text[], p_entity_ids text[]) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  with belief as (
    update knowledge.belief_rulings r
    set shown_enc = null,
        evidence_ids = case when r.entity_ids && forget_ruling_anchors.p_entity_ids then '{}'::text[] else
                         array(select x from unnest(r.evidence_ids) with ordinality as u (x, n)
                               where not (x = any (forget_ruling_anchors.p_evidence_ids)) order by n) end,
        entity_ids = array(select x from unnest(r.entity_ids) with ordinality as u (x, n)
                           where not (x = any (forget_ruling_anchors.p_entity_ids)) order by n)
    where r.claim_type is not null
      and (r.evidence_ids && forget_ruling_anchors.p_evidence_ids or r.entity_ids && forget_ruling_anchors.p_entity_ids)
    returning 1),
  pair as (
    update knowledge.fact_rulings r
    set shown_enc = null,
        a_evidence_ids = case when r.entity_ids && forget_ruling_anchors.p_entity_ids then '{}'::text[] else
                           array(select x from unnest(r.a_evidence_ids) with ordinality as u (x, n)
                                 where not (x = any (forget_ruling_anchors.p_evidence_ids)) order by n) end,
        b_evidence_ids = case when r.entity_ids && forget_ruling_anchors.p_entity_ids then '{}'::text[] else
                           array(select x from unnest(r.b_evidence_ids) with ordinality as u (x, n)
                                 where not (x = any (forget_ruling_anchors.p_evidence_ids)) order by n) end,
        entity_ids = array(select x from unnest(r.entity_ids) with ordinality as u (x, n)
                           where not (x = any (forget_ruling_anchors.p_entity_ids)) order by n)
    where r.claim_type is not null
      and (r.a_evidence_ids && forget_ruling_anchors.p_evidence_ids or r.b_evidence_ids && forget_ruling_anchors.p_evidence_ids
        or r.entity_ids && forget_ruling_anchors.p_entity_ids)
    returning 1)
  select ((select count(*) from belief) + (select count(*) from pair))::int
$$;

CREATE FUNCTION knowledge.forget_ruling_shown(p_evidence_ids text[]) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  with belief as (
    update knowledge.belief_rulings r set shown_enc = null
    where r.shown_enc is not null and r.evidence_ids && forget_ruling_shown.p_evidence_ids
    returning 1),
  pair as (
    update knowledge.fact_rulings r set shown_enc = null
    where r.shown_enc is not null
      and (r.a_evidence_ids && forget_ruling_shown.p_evidence_ids or r.b_evidence_ids && forget_ruling_shown.p_evidence_ids)
    returning 1)
  select ((select count(*) from belief) + (select count(*) from pair))::int
$$;

CREATE FUNCTION knowledge.goal_ids_label() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  claim_compartments text[];
  claim_evidence text;
  claim_key text;
begin
  if cardinality(new.compartments) = 0 then
    return new;
  end if;
  select c.compartments, c.evidence_id, c.fact_key_fp into claim_compartments, claim_evidence, claim_key from knowledge.claims c where c.id = new.claim_id;
  if not found or new.compartments is distinct from claim_compartments or new.evidence_id is distinct from claim_evidence or new.fact_key_fp is distinct from claim_key then
    raise exception 'goal id row differs from its claim' using errcode = '23514';
  end if;
  return new;
end
$$;

CREATE FUNCTION knowledge.goal_target_ids() RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$ select distinct g.target_entity_id from projections.goal_state g where g.target_entity_id is not null order by 1 $$;

CREATE FUNCTION knowledge.gone_keys(p_keys text[], p_evidence_ids text[], p_claim_ids text[], p_people text[]) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select coalesce(array_agg(k.fp order by k.fp collate "C"), '{}'::text[])
  from (select distinct u.fp from unnest(gone_keys.p_keys) as u (fp)) k
  where not exists (select 1 from knowledge.claims c
                    where (c.fact_key_fp = k.fp or c.legacy_fact_key_fp = k.fp or c.legacy_alt_fact_key_fp = k.fp)
                      and not c.closes
                      and not (c.evidence_id = any (gone_keys.p_evidence_ids)) and not (c.id = any (gone_keys.p_claim_ids)))
    and not exists (select 1 from knowledge.belief_rulings r
                    where r.fact_key_fp = k.fp and r.claim_type is not null and r.lifted_at is null
                      and not (r.entity_ids && gone_keys.p_people)
                      and exists (select 1 from unnest(r.evidence_ids) as x (id) join vault.evidence_items e on e.id = x.id
                                  where not (x.id = any (gone_keys.p_evidence_ids))))
    and not exists (select 1 from knowledge.fact_rulings f
                    cross join lateral (values (f.a_fp, f.a_evidence_ids), (f.b_fp, f.b_evidence_ids)) as s (fp, evidence_ids)
                    where s.fp = k.fp and f.claim_type is not null and f.lifted_at is null
                      and not (f.entity_ids && gone_keys.p_people)
                      and not exists (select 1 from knowledge.claims c join knowledge.claim_entities n on n.claim_id = c.id
                                      where n.entity_id = any (gone_keys.p_people)
                                        and (c.fact_key_fp in (f.a_fp, f.b_fp) or c.legacy_fact_key_fp in (f.a_fp, f.b_fp)
                                          or c.legacy_alt_fact_key_fp in (f.a_fp, f.b_fp)))
                      and exists (select 1 from unnest(s.evidence_ids) as x (id) join vault.evidence_items e on e.id = x.id
                                  where not (x.id = any (gone_keys.p_evidence_ids))))
$$;

CREATE FUNCTION knowledge.hold_fact_key_v2() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if old.fact_key_v2_at is not null and (tg_op = 'DELETE' or new.fact_key_v2_at is distinct from old.fact_key_v2_at) then
    raise exception 'the go is set once' using errcode = '42501';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end
$$;

CREATE FUNCTION knowledge.mark_fact_key_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  update policy.owner_settings set fact_key_v2_at = now() where fact_key_v2_at is null;
  return null;
end
$$;

CREATE FUNCTION knowledge.mark_fact_rulings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  insert into policy.fact_ruling_marks default values;
  return null;
end
$$;

CREATE FUNCTION knowledge.name_ruling_people(p_people text[]) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  with named as (
    update knowledge.fact_rulings f
    set entity_ids = array(select x.id
                           from (select u.id from unnest(f.entity_ids) as u (id)
                                 union
                                 select n.entity_id from knowledge.claims c join knowledge.claim_entities n on n.claim_id = c.id
                                 where n.entity_id = any (name_ruling_people.p_people)
                                   and (c.fact_key_fp in (f.a_fp, f.b_fp) or c.legacy_fact_key_fp in (f.a_fp, f.b_fp)
                                     or c.legacy_alt_fact_key_fp in (f.a_fp, f.b_fp))) x
                           order by x.id collate "C")
    where f.claim_type is not null
      and exists (select 1 from knowledge.claims c join knowledge.claim_entities n on n.claim_id = c.id
                  where n.entity_id = any (name_ruling_people.p_people) and not (n.entity_id = any (f.entity_ids))
                    and (c.fact_key_fp in (f.a_fp, f.b_fp) or c.legacy_fact_key_fp in (f.a_fp, f.b_fp)
                      or c.legacy_alt_fact_key_fp in (f.a_fp, f.b_fp)))
    returning 1)
  select count(*)::int from named
$$;

CREATE FUNCTION knowledge.pages_of_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if not exists (
    select 1 from ledger.research_requests q
    join vault.evidence_items e on e.id = new.evidence_id
    join vault.source_accounts a on a.id = e.source_account_id
    where q.id = new.request_id and q.tainted_at is null and ledger.research_state(q.id) = 'running'
      and a.connector = 'web' and a.compartments = new.compartments
      and new.compartments = case when q.kind = 'link' then array['own'] else array['public'] end
      and new.about_entity_id is not distinct from q.about_entity_id) then
    raise exception 'not a page of a request that runs' using errcode = '42501';
  end if;
  return new;
end
$$;

CREATE FUNCTION knowledge.release_ended_wake() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_ended boolean := true;
begin
  if tg_table_name = 'owner_decisions' then
    v_ended := exists (select 1 from knowledge.claim_releases r
                       where r.ruling_id = case when tg_op = 'INSERT' then new.supersedes else new.id end and r.lifted_at is null);
  elsif tg_table_name = 'belief_rulings' then
    v_ended := exists (select 1 from knowledge.claims c
                       join knowledge.claim_releases r on r.evidence_id = c.evidence_id and r.lifted_at is null
                       where new.fact_key_fp in (c.fact_key_fp, c.legacy_fact_key_fp, c.legacy_alt_fact_key_fp));
  end if;
  if v_ended then
    perform pg_notify('pi_agent_write', '');
  end if;
  return null;
end
$$;

CREATE FUNCTION knowledge.remove_claims(p_ids text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  delete from knowledge.claim_entities n where n.claim_id = any (p_ids);
  delete from knowledge.claims c where c.id = any (p_ids);
end
$$;

CREATE FUNCTION knowledge.remove_extracted_claims() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  delete from knowledge.claim_entities n where exists (
    select 1 from knowledge.claims c join vault.evidence_items e on e.id = c.evidence_id
    where c.id = n.claim_id and e.source_kind <> 'owner_command');
  delete from knowledge.claims c where exists (
    select 1 from vault.evidence_items e where e.id = c.evidence_id and e.source_kind <> 'owner_command');
end
$$;

CREATE FUNCTION knowledge.remove_person_links(p_claim_ids text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  delete from knowledge.claim_entities n
  using knowledge.entities e, knowledge.claims c, vault.evidence_items v
  where e.id = n.entity_id and e.kind = 'person' and n.claim_id = any (p_claim_ids)
    and c.id = n.claim_id and v.id = c.evidence_id and v.source_kind = 'owner_command';
end
$$;

CREATE FUNCTION knowledge.same_fact_judgments_label() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if cardinality(new.compartments) = 0 then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if new.a_claim is not distinct from old.a_claim and new.b_claim is not distinct from old.b_claim
       and new.compartments is not distinct from old.compartments then
      return new;
    end if;
  end if;
  if true then
    if (select count(*) from knowledge.claims c
        where (c.id = new.a_claim and c.fact_key_fp = new.a_fp) or (c.id = new.b_claim and c.fact_key_fp = new.b_fp)) <> 2
       or new.compartments is distinct from (
         select array_agg(distinct x collate "C" order by x collate "C")
         from knowledge.claims c cross join lateral unnest(c.compartments) as x
         where c.id in (new.a_claim, new.b_claim)) then
      raise exception 'judgment label differs from its claims' using errcode = '23514';
    end if;
  end if;
  return new;
end
$$;

CREATE FUNCTION knowledge.scrub_belief_rulings(p_rulings text[], p_claim_ids text[], p_fact_key_fps text[], p_account_ids text[], p_item_fps text[], p_gone_fps text[], p_people text[], p_dry_run boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_n integer := 0;
  v_hit record;
  v_claim text;
  v_key text;
begin
  for v_hit in
    select r.ruling_id, r.claim_fp, r.fact_key_fp, g.item_gone, g.items_gone, g.kept_accounts, g.kept_fps,
      r.claim_fp = any (p_claim_ids)
        or (not exists (select 1 from knowledge.claims c where c.id = r.claim_fp)
            and (r.ruling_id = any (p_rulings) or g.item_gone or g.items_gone)) as claim_gone,
      r.fact_key_fp = any (p_gone_fps) as key_gone
    from knowledge.belief_rulings r
    cross join lateral (
      select coalesce(bool_or(i.gone) filter (where i.own), false) as item_gone,
             coalesce(bool_or(i.gone) filter (where not i.own), false) as items_gone,
             coalesce(array_agg(i.account_id order by i.n) filter (where not i.own and not i.gone), '{}'::text[]) as kept_accounts,
             coalesce(array_agg(i.fp order by i.n) filter (where not i.own and not i.gone), '{}'::text[]) as kept_fps
      from (
        select n.own, n.account_id, n.fp, n.n, t.stored,
          exists (select 1 from unnest(p_account_ids, p_item_fps) as e (account_id, fp) where e.account_id = n.account_id and e.fp = n.fp)
            or exists (select 1 from knowledge.removed_evidence d where d.source_account_id = n.account_id and d.source_item_fp = n.fp)
            or (not t.stored and coalesce(r.entity_ids && p_people, false)) as gone
        from (select true as own, r.source_account_id as account_id, r.source_item_fp as fp, 0::bigint as n
              where r.source_item_fp is not null
              union all
              select false, x.account_id, x.fp, x.n
              from unnest(r.item_account_ids, r.item_fps) with ordinality as x (account_id, fp, n)) n
        cross join lateral (select exists (select 1 from vault.evidence_items e
                                           where e.source_account_id = n.account_id and e.source_item_fp = n.fp) as stored) t) i) g
    where r.ruling_id = any (p_rulings) or r.claim_fp = any (p_claim_ids) or r.fact_key_fp = any (p_fact_key_fps)
       or r.source_item_fp = any (p_item_fps) or r.item_fps && p_item_fps
    order by r.ruling_id collate "C"
  loop
    if not (v_hit.claim_gone or v_hit.key_gone or v_hit.item_gone or v_hit.items_gone) then
      continue;
    end if;
    v_n := v_n + 1;
    if p_dry_run then
      continue;
    end if;
    v_claim := encode(sha256(convert_to(gen_random_uuid()::text, 'UTF8')), 'hex');
    v_key := encode(sha256(convert_to(gen_random_uuid()::text, 'UTF8')), 'hex');
    update knowledge.belief_rulings r
    set claim_fp = case when v_hit.claim_gone then v_claim else r.claim_fp end,
        fact_key_fp = case when v_hit.key_gone then v_key else r.fact_key_fp end,
        source_item_fp = case when v_hit.item_gone then encode(sha256(convert_to(gen_random_uuid()::text, 'UTF8')), 'hex')
                              else r.source_item_fp end,
        item_account_ids = case when v_hit.items_gone then v_hit.kept_accounts else r.item_account_ids end,
        item_fps = case when v_hit.items_gone then v_hit.kept_fps else r.item_fps end
    where r.ruling_id = v_hit.ruling_id;
    update knowledge.owner_decisions o
    set details = o.details
      || case when v_hit.claim_gone and o.details ->> 'claim' = v_hit.claim_fp then jsonb_build_object('claim', v_claim) else '{}'::jsonb end
      || case when v_hit.key_gone and o.details ->> 'factKey' = v_hit.fact_key_fp then jsonb_build_object('factKey', v_key) else '{}'::jsonb end
    where o.id = v_hit.ruling_id
      and ((v_hit.claim_gone and o.details ->> 'claim' = v_hit.claim_fp)
        or (v_hit.key_gone and o.details ->> 'factKey' = v_hit.fact_key_fp));
  end loop;
  return v_n;
end
$$;

CREATE FUNCTION knowledge.scrub_rulings_of_item(p_evidence_ids text[], p_account_id text, p_item_fp text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_rulings text[];
  v_claims text[];
  v_keys text[];
  v_gone text[];
  v_n integer;
begin
  v_rulings := array(select r.ruling_id from knowledge.belief_rulings r where r.evidence_ids && p_evidence_ids);
  v_claims := array(select c.id from knowledge.claims c where c.evidence_id = any (p_evidence_ids));
  v_keys := array(
    select k.fp from knowledge.claims c
    cross join lateral (values (c.fact_key_fp), (c.legacy_fact_key_fp), (c.legacy_alt_fact_key_fp)) as k (fp)
    where c.evidence_id = any (p_evidence_ids) and k.fp is not null
    union
    select r.fact_key_fp from knowledge.belief_rulings r
    where r.ruling_id = any (v_rulings) or r.claim_fp = any (v_claims) or r.source_item_fp = p_item_fp
       or r.item_fps && array[p_item_fp]);
  v_gone := knowledge.gone_keys(v_keys, p_evidence_ids, v_claims, '{}'::text[]);
  v_n := knowledge.scrub_belief_rulings(v_rulings, v_claims, v_keys, array[p_account_id], array[p_item_fp],
                                        v_gone, '{}'::text[], false);
  perform ledger.forget_commitment_keys(v_gone);
  return v_n;
end
$$;

CREATE FUNCTION knowledge.set_ruling_shown(p_ruling text, p_shown jsonb) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  with belief as (
    update knowledge.belief_rulings r set shown_enc = set_ruling_shown.p_shown
    where r.ruling_id = set_ruling_shown.p_ruling and r.shown_enc is null and r.claim_type is not null
      and set_ruling_shown.p_shown is not null
    returning 1),
  pair as (
    update knowledge.fact_rulings r set shown_enc = set_ruling_shown.p_shown
    where r.ruling_id = set_ruling_shown.p_ruling and r.shown_enc is null and r.claim_type is not null
      and set_ruling_shown.p_shown is not null
    returning 1)
  select exists (select 1 from belief) or exists (select 1 from pair)
$$;

CREATE FUNCTION knowledge.settle_named_org_targets() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_item text := coalesce(new.evidence_id, old.evidence_id);
  v_name text := coalesce(new.name_fp, old.name_fp);
begin
  update projections.goal_state g set target_entity_id = (
      select min(o.entity_id) from knowledge.org_names o where o.evidence_id = v_item and o.name_fp = v_name)
  from (
    select distinct on (d.target_id) d.target_id, d.details
    from knowledge.owner_decisions d
    where d.kind = 'goal_target' and d.target_kind = 'goal'
      and d.target_id in (select o.target_id from knowledge.owner_decisions o where o.kind = 'goal_target' and o.details -> 'named' ->> 'item' = v_item)
    order by d.target_id, d.decided_at desc, d.id collate "C" desc
  ) t
  where t.target_id = g.goal_id and t.details -> 'named' ->> 'item' = v_item and t.details -> 'named' ->> 'name' = v_name;
  return null;
end
$$;

CREATE FUNCTION knowledge.settle_named_targets() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_item text := coalesce(new.evidence_id, old.evidence_id);
  v_name text := coalesce(new.mention_fp, old.mention_fp);
begin
  update projections.goal_state g set target_entity_id = (
      select min(a.entity_id) from knowledge.mention_bindings b
      join knowledge.accounts a on a.value_fp = b.address_fp
      join knowledge.entities e on e.id = a.entity_id and e.kind = 'person'
      where b.evidence_id = v_item and b.mention_fp = v_name and b.lifted_at is null)
  from (
    select distinct on (d.target_id) d.target_id, d.details
    from knowledge.owner_decisions d
    where d.kind = 'goal_target' and d.target_kind = 'goal'
      and d.target_id in (select o.target_id from knowledge.owner_decisions o where o.kind = 'goal_target' and o.details -> 'named' ->> 'item' = v_item)
    order by d.target_id, d.decided_at desc, d.id collate "C" desc
  ) t
  where t.target_id = g.goal_id and t.details -> 'named' ->> 'item' = v_item and t.details -> 'named' ->> 'name' = v_name;
  return null;
end
$$;

CREATE FUNCTION ledger.add_agent_claim_basis(card_id text, cites text[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  card_compartments text[];
  kinds text[];
  ids text[];
  found integer;
begin
  select c.compartments into card_compartments
  from ledger.cards c
  where c.id = add_agent_claim_basis.card_id and c.kind in ('agent_claim', 'about_you', 'client_preference') and c.created_by = 'system:extract';
  if card_compartments is null then
    raise exception 'not an agent_claim card' using errcode = '42501';
  end if;
  with cited as (
    select distinct x as evidence_id from unnest(add_agent_claim_basis.cites) as x
  ),
  resolved as (
    select c.evidence_id, 'message' as kind, m.id from cited c join knowledge.messages m on m.evidence_id = c.evidence_id
    union
    select c.evidence_id, 'event', e.id from cited c join knowledge.events e on e.evidence_id = c.evidence_id
  )
  select coalesce(array_agg(r.kind order by r.kind, r.id collate "C"), '{}'::text[]),
         coalesce(array_agg(r.id order by r.kind, r.id collate "C"), '{}'::text[]),
         count(distinct r.evidence_id)
  into kinds, ids, found
  from resolved r;
  return ledger.add_basis('card', add_agent_claim_basis.card_id, card_compartments, kinds, ids, card_compartments)
    and found = (select count(distinct x) from unnest(add_agent_claim_basis.cites) as x);
end
$$;

CREATE FUNCTION ledger.add_basis(row_kind text, row_id text, compartments text[], ref_kinds text[], ref_ids text[], clearance text[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  written integer;
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
  begin
    with refs as (
      select r.kind, r.id, r.ord from unnest(add_basis.ref_kinds, add_basis.ref_ids) with ordinality as r (kind, id, ord)
    ),
    resolved as (
      select r.ord, r.kind, r.id, m.evidence_id,
        case when e.system_originated or e.answers_system then 'system' else 'source' end as source_class
      from refs r
      join knowledge.messages m on m.id = r.id
      join vault.evidence_items e on e.id = m.evidence_id
      where r.kind = 'message' and (add_basis.clearance is null or (m.compartments <@ add_basis.clearance and not m.held))
      union all
      select r.ord, r.kind, r.id, ev.evidence_id, 'source'
      from refs r join knowledge.events ev on ev.id = r.id
      where r.kind = 'event' and (add_basis.clearance is null or ev.compartments <@ add_basis.clearance)
      union all
      select r.ord, r.kind, r.id, null, 'derived'
      from refs r join knowledge.entities en on en.id = r.id
      where r.kind = 'entity' and (add_basis.clearance is null
        or exists (select 1 from knowledge.accounts a where a.entity_id = en.id and a.compartments <@ add_basis.clearance)
        or exists (select 1 from knowledge.domains d where d.entity_id = en.id and d.compartments <@ add_basis.clearance))
      union all
      select r.ord, r.kind, r.id, null, 'owner'
      from refs r join projections.goal_state g on g.goal_id = r.id
      where r.kind = 'goal' and (add_basis.clearance is null or g.compartments <@ add_basis.clearance)
      union all
      select r.ord, r.kind, r.id, null, 'agent'
      from refs r join ledger.hypotheses h on h.id = r.id
      where r.kind = 'hypothesis' and (add_basis.clearance is null or h.compartments <@ add_basis.clearance)
      union all
      select r.ord, r.kind, r.id, null, 'agent'
      from refs r join ledger.opportunities o on o.id = r.id
      where r.kind = 'opportunity' and (add_basis.clearance is null or o.compartments <@ add_basis.clearance)
      union all
      select r.ord, r.kind, r.id, w.evidence_id, 'agent'
      from refs r join ledger.agent_writes w on w.id = r.id
      where r.kind = 'agent_record' and w.evidence_id is not null and w.body_enc is not null and w.tainted_at is null and w.flagged_at is null
        and (add_basis.clearance is null
          or (w.compartments <@ add_basis.clearance
              and w.writer_views <@ coalesce((select c.views from policy.current_client() c), '{}'::text[])))
      union all
      select r.ord, r.kind, r.id, w.evidence_id, 'agent'
      from refs r join ledger.agent_writes w on w.id = r.id
      where r.kind = 'owner_request' and add_basis.row_kind in ('opportunity', 'goal_proposal') and w.kind = 'note' and w.created_at = now()
        and w.body_enc is not null and w.tainted_at is null and w.flagged_at is null
        and w.client_id = (select c.id from policy.current_client() c)
        and add_basis.clearance is not null and w.compartments <@ add_basis.clearance
        and w.writer_views <@ coalesce((select c.views from policy.current_client() c), '{}'::text[])
    )
    insert into ledger.basis (row_kind, row_id, ref_kind, ref_id, evidence_id, source_class, owner_backed, compartments)
    select add_basis.row_kind, add_basis.row_id, s.kind, s.id, s.evidence_id, s.source_class,
      ledger.owner_backed(s.kind, s.id), ledger.label(add_basis.compartments)
    from resolved s order by s.ord;
    get diagnostics written = row_count;
    if written <> coalesce(cardinality(add_basis.ref_kinds), 0) or written <> coalesce(cardinality(add_basis.ref_ids), 0) then
      raise exception 'a ref did not resolve' using errcode = 'PIB01';
    end if;
  exception when sqlstate 'PIB01' then
    return false;
  end;
  return true;
end
$$;

CREATE FUNCTION ledger.add_owner_lesson(lesson_id text, request_id text, body_enc jsonb, applies_kinds text[] DEFAULT NULL::text[], applies_roles text[] DEFAULT NULL::text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_found text;
  v_label text[] := ledger.label('{own}'::text[]);
begin
  select h.id into v_found from ledger.hypotheses h where h.created_by = 'owner' and h.request_id = add_owner_lesson.request_id;
  if v_found is not null then
    return v_found;
  end if;
  if add_owner_lesson.lesson_id !~ '^hyp_[0-9A-HJKMNP-TV-Z]{26}$' or jsonb_typeof(add_owner_lesson.body_enc) is distinct from 'object' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  insert into ledger.cases (id, request_id, created_by, compartments, row_kind, kind, about_kind, about_id, author)
  values ('cas_' || substr(add_owner_lesson.lesson_id, 5), add_owner_lesson.request_id, 'owner', v_label, 'hypothesis', 'lesson', 'owner', null, 'owner');
  insert into ledger.hypotheses (id, request_id, created_by, compartments, body_enc, case_id, kind, about_kind, about_id, about_owner, applies_kinds, applies_roles)
  values (add_owner_lesson.lesson_id, add_owner_lesson.request_id, 'owner', v_label, add_owner_lesson.body_enc, 'cas_' || substr(add_owner_lesson.lesson_id, 5),
          'lesson', 'owner', null, true, add_owner_lesson.applies_kinds, add_owner_lesson.applies_roles);
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  values ('hypothesis', add_owner_lesson.lesson_id, 'open', clock_timestamp(), 'owner', v_label);
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  values ('hypothesis', add_owner_lesson.lesson_id, 'confirmed', clock_timestamp(), 'owner', v_label);
  return add_owner_lesson.lesson_id;
end
$_$;

CREATE FUNCTION ledger.add_watches(move_id text, session_id text, ref_kinds text[], ref_ids text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
  v_author text;
  v_opportunity text;
  v_label text[];
  v_written integer;
begin
  select c.id, c.compartments into v_caller, v_clearance from policy.current_client() c;
  if v_caller is null or not exists (select 1 from ledger.sessions s where s.id = add_watches.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if coalesce(cardinality(add_watches.ref_kinds), 0) not between 1 and 10 or cardinality(add_watches.ref_kinds) <> coalesce(cardinality(add_watches.ref_ids), 0)
     or exists (select 1 from unnest(add_watches.ref_kinds) as k where k is null or k not in ('message', 'entity')) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  v_author := 'client:' || v_caller;
  perform ledger.lock_rows(array[add_watches.move_id]);
  select v.opportunity_id, o.compartments into v_opportunity, v_label from ledger.moves v join ledger.opportunities o on o.id = v.opportunity_id
  where v.id = add_watches.move_id and o.tainted_at is null
    and policy.label_key(v.compartments) = any (v_keys) and policy.label_key(o.compartments) = any (v_keys)
    and exists (select 1 from ledger.record_events r where r.row_kind = 'move' and r.row_id = v.id and r.by = v_author
                and r.session_id = add_watches.session_id and r.at = now() and policy.label_key(r.compartments) = any (v_keys));
  if v_opportunity is null then
    return 0;
  end if;
  perform ledger.lock_rows(array[v_opportunity]);

  with refs as (
    select distinct r.kind, r.id from unnest(add_watches.ref_kinds, add_watches.ref_ids) as r (kind, id)
  ),
  found as (
    select 'thread'::text as kind, m.thread_fp as watch_key, e.source_account_id as account_id, m.evidence_id, ledger.label(v_label || m.compartments || e.compartments) as compartments
    from refs r
    join knowledge.messages m on r.kind = 'message' and m.id = r.id
    join vault.evidence_items e on e.id = m.evidence_id
    where m.thread_fp is not null and not m.held and m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys)
    union all
    select 'entity', r.id, null, null,
      ledger.label(v_label || array(
        select u.one from (
          select a.compartments from knowledge.accounts a where a.entity_id = r.id and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys)
          union all
          select d.compartments from knowledge.domains d where d.entity_id = r.id and d.compartments <@ v_clearance and policy.label_key(d.compartments) = any (v_keys)) s
        cross join lateral unnest(s.compartments) as u (one)))
    from refs r
    where r.kind = 'entity' and ledger.entity_seen(r.id, v_clearance, v_keys)
  ),
  added as (
    insert into ledger.work_watches (opportunity_id, created_by, kind, watch_key, account_id, evidence_id, compartments)
    select distinct on (f.kind, f.account_id, f.watch_key) v_opportunity, v_author, f.kind, f.watch_key, f.account_id, f.evidence_id, f.compartments
    from found f
    where not exists (
      select 1 from (select distinct on (w.kind, w.account_id, w.watch_key) w.until from ledger.work_watches w
                     where w.opportunity_id = v_opportunity and w.kind = f.kind and w.watch_key = f.watch_key and w.account_id is not distinct from f.account_id
                     order by w.kind, w.account_id, w.watch_key, w.id desc) latest
      where latest.until is null or latest.until > now())
    order by f.kind, f.account_id, f.watch_key
    returning 1
  )
  select count(*)::integer into v_written from added;
  return v_written;
end
$$;

CREATE FUNCTION ledger.admit_deferred(author text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  admitted integer := 0;
  next_id text;
  next_compartments text[];
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
  loop
    next_id := null;
    select c.id, c.compartments into next_id, next_compartments
    from ledger.cards c
    where c.created_by = admit_deferred.author and c.tainted_at is null and (c.expires_at is null or c.expires_at > now())
      and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) = 'deferred'
      and not exists (select 1 from ledger.card_name_holds h where h.card_id = c.id)
    order by c.created_at, c.id collate "C"
    limit 1;
    exit when next_id is null;
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
    values ('card', next_id, 'pending', now(), 'system:queue', next_compartments);
    admitted := admitted + 1;
  end loop;
  return admitted;
end
$$;

CREATE FUNCTION ledger.agent_inbox(scope text, thread text, lim integer, mark boolean) RETURNS TABLE(id text, thread_id text, reply_to text, from_name text, to_kind text, to_name text, to_role text, kind text, created_at timestamp with time zone, compartments text[], body_enc jsonb, subject_id text, subject_compartments text[], subject_enc jsonb, mine boolean, read boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_roles text[];
  v_keys text[];
  v_ids text[];
begin
  select r.client_id, r.clearance, r.roles into v_caller, v_clearance, v_roles from ledger.agent_mail_reader('read_agent_inbox') r;
  if agent_inbox.scope is null or agent_inbox.scope not in ('unread', 'all', 'thread') or (agent_inbox.scope = 'thread') <> (agent_inbox.thread is not null)
     or agent_inbox.lim is null or agent_inbox.lim not between 1 and 50 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();

  select coalesce(array_agg(x.id order by x.ord), '{}'::text[]) into v_ids from (
    select m.id,
      row_number() over (order by
        case when agent_inbox.scope = 'all' then null else m.created_at end asc,
        case when agent_inbox.scope = 'all' then m.created_at end desc,
        m.id collate "C") as ord
    from ledger.agent_messages m
    where ledger.agent_message_visible(m, v_caller, v_clearance, v_roles, v_keys)
      and (agent_inbox.scope <> 'thread' or m.thread_id = agent_inbox.thread)
      and (agent_inbox.scope <> 'unread'
           or (m.client_id <> v_caller and not exists (select 1 from ledger.agent_message_reads r where r.message_id = m.id and r.client_id = v_caller)))
    order by ord
    limit agent_inbox.lim + 1
  ) x;

  return query
  select m.id, m.thread_id, m.reply_to, s.name, m.to_kind, t.name, m.to_role, m.kind, m.created_at, m.compartments, m.body_enc,
    root.id, root.compartments, root.subject_enc,
    m.client_id = v_caller,
    m.client_id = v_caller or exists (select 1 from ledger.agent_message_reads r where r.message_id = m.id and r.client_id = v_caller)
  from unnest(v_ids) with ordinality as o (one, ord)
  join ledger.agent_messages m on m.id = o.one
  join policy.clients s on s.id = m.client_id
  left join policy.clients t on t.id = m.to_client_id
  left join lateral (
    select r.id, r.compartments, r.subject_enc from ledger.agent_messages r
    where r.id = m.thread_id and r.tainted_at is null and r.compartments <@ v_clearance and policy.label_key(r.compartments) = any (v_keys)
  ) root on true
  order by o.ord;

  if agent_inbox.mark then
    insert into ledger.agent_message_reads (message_id, client_id)
    select x.one, v_caller from unnest(v_ids[1:agent_inbox.lim]) as x (one)
    on conflict do nothing;
  end if;
end
$$;

CREATE FUNCTION ledger.agent_learnings_for(lim integer) RETURNS TABLE(id text, scope text, compartments text[], statement_enc jsonb, rule_enc jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_clearance text[];
  v_roles text[];
  v_keys text[];
begin
  select r.clearance, r.roles into v_clearance, v_roles from ledger.agent_mail_reader('file_learning') r;
  if agent_learnings_for.lim is null or agent_learnings_for.lim not between 1 and 20 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  return query
  select l.id, l.scope, l.compartments, l.statement_enc, l.rule_enc
  from ledger.agent_learnings l
  where l.tainted_at is null and l.retired_at is null
    and l.compartments <@ v_clearance and policy.label_key(l.compartments) = any (v_keys)
    and (l.scope = 'general' or l.scope = any (v_roles))
    and not exists (select 1 from ledger.agent_learnings n
                    where n.supersedes = l.id and n.tainted_at is null and n.retired_at is null
                      and n.compartments <@ v_clearance and policy.label_key(n.compartments) = any (v_keys))
  order by l.created_at desc, l.id collate "C" desc
  limit agent_learnings_for.lim;
end
$$;

CREATE FUNCTION ledger.agent_mail_caller(tool text, session_id text) RETURNS TABLE(client_id text, clearance text[], roles text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_clearance text[];
  v_roles text[];
begin
  select r.client_id, r.clearance, r.roles into v_caller, v_clearance, v_roles from ledger.agent_mail_reader(agent_mail_caller.tool) r;
  if not exists (select 1 from ledger.sessions s where s.id = agent_mail_caller.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  return query select v_caller, v_clearance, v_roles;
end
$$;

CREATE FUNCTION ledger.agent_mail_reader(tool text) RETURNS TABLE(client_id text, clearance text[], roles text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not (agent_mail_reader.tool = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  return query select v_caller, v_clearance, coalesce((select k.roles from policy.clients k where k.id = v_caller), '{}'::text[]);
end
$$;

CREATE TABLE ledger.agent_messages (
    id text NOT NULL,
    request_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text NOT NULL,
    client_id text NOT NULL,
    session_id text NOT NULL,
    compartments text[] NOT NULL,
    tainted_at timestamp with time zone,
    thread_id text NOT NULL,
    reply_to text,
    to_kind text NOT NULL,
    to_client_id text,
    to_role text,
    kind text NOT NULL,
    subject_enc jsonb,
    body_enc jsonb,
    CONSTRAINT agent_messages_body CHECK (((body_enc IS NULL) OR (jsonb_typeof(body_enc) = 'object'::text))),
    CONSTRAINT agent_messages_id_form CHECK ((id ~ '^amg_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT agent_messages_kind CHECK ((kind = ANY (ARRAY['note'::text, 'question'::text, 'issue'::text, 'answer'::text]))),
    CONSTRAINT agent_messages_request_id_form CHECK ((request_id ~ '^[A-Za-z0-9_-]{8,64}$'::text)),
    CONSTRAINT agent_messages_root CHECK ((((reply_to IS NULL) = (thread_id = id)) AND ((reply_to IS NULL) OR (subject_enc IS NULL)))),
    CONSTRAINT agent_messages_subject CHECK (((subject_enc IS NULL) OR (jsonb_typeof(subject_enc) = 'object'::text))),
    CONSTRAINT agent_messages_thread_form CHECK ((thread_id ~ '^amg_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT agent_messages_to CHECK ((((to_kind = 'client'::text) = (to_client_id IS NOT NULL)) AND ((to_kind = 'role'::text) = (to_role IS NOT NULL)))),
    CONSTRAINT agent_messages_to_kind CHECK ((to_kind = ANY (ARRAY['client'::text, 'role'::text, 'all'::text]))),
    CONSTRAINT agent_messages_to_role_form CHECK ((to_role ~ '^[a-z][a-z0-9-]{1,31}$'::text)),
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1))
);

ALTER TABLE ONLY ledger.agent_messages FORCE ROW LEVEL SECURITY;

CREATE FUNCTION ledger.agent_message_visible(m ledger.agent_messages, caller text, clearance text[], roles text[], keys text[]) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select m.tainted_at is null and m.compartments <@ clearance and policy.label_key(m.compartments) = any (keys)
    and (m.client_id = caller or m.to_kind = 'all' or m.to_client_id = caller or (m.to_kind = 'role' and m.to_role = any (roles)))
$$;

CREATE FUNCTION ledger.agent_questions_within(p_since timestamp with time zone, p_until timestamp with time zone, p_within text[], p_client text) RETURNS TABLE(client_id text, asked integer, paid integer, refused integer, refusals jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with agents as (
    select k.id from policy.clients k where k.kind = 'agent' and (p_client is null or k.id = p_client)
  ),
  handed as (
    select e.row_id, substr(e.by, 8) as client_id, e.at from ledger.record_events e
    where e.row_kind = 'opportunity' and e.event = 'handed_to_owner' and e.by like 'client:%'
      and e.at >= p_since and e.at < p_until and e.compartments <@ p_within
  ),
  questions as (
    select substr(o.created_by, 8) as client_id, o.question_paid_at is not null as paid
    from ledger.opportunities o
    where o.created_by like 'client:%' and o.created_at >= p_since and o.created_at < p_until
      and o.tainted_at is null and o.compartments <@ p_within
      and (o.kind = 'owner_question'
           or (o.question_paid_at is not null
               and not exists (select 1 from ledger.record_events e
                               where e.row_kind = 'opportunity' and e.row_id = o.id and e.event = 'handed_to_owner' and e.by like 'client:%')))
    union all
    select h.client_id, o.question_paid_at is not null
      and o.question_paid_at > coalesce((select max(e.at) from ledger.record_events e
                                         where e.row_kind = 'opportunity' and e.row_id = h.row_id
                                           and e.event = 'handed_to_owner' and e.at < h.at), '-infinity')
    from handed h join ledger.opportunities o on o.id = h.row_id
    where o.tainted_at is null and o.compartments <@ p_within
      and not (o.kind = 'owner_question' and o.created_by like 'client:%')
    union all
    select m.client_id, m.question_paid_at is not null
    from ledger.signal_marks m
    where m.state = 'needs_owner' and m.created_at >= p_since and m.created_at < p_until
      and m.tainted_at is null and m.compartments <@ p_within
  ),
  refused as (
    select x.client_id, x.reason, coalesce(x.reason, x.outcome) as code from policy.calls x
    where x.at >= p_since and x.at < p_until
      and x.outcome in ('unauthorized', 'not_permitted', 'invalid_request', 'unsupported_template', 'unknown_role')
  )
  select a.id,
    (select count(*)::integer from questions q where q.client_id = a.id),
    (select count(*)::integer from questions q where q.client_id = a.id and q.paid),
    (select count(*)::integer from refused r where r.client_id = a.id and r.reason = 'question_unpaid'),
    (select coalesce(jsonb_object_agg(c.code, c.n), '{}'::jsonb)
     from (select r.code, count(*)::integer as n from refused r where r.client_id = a.id group by r.code) c)
  from agents a
  order by a.id
$$;

CREATE FUNCTION ledger.agent_records_within(p_at timestamp with time zone, p_within text[], p_client text) RETURNS TABLE(client_id text, done integer, used integer, raised integer, yes integer, no integer, deferred integer, by_agent integer, waiting integer, other integer, no_codes text[], overturned integer, refused integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with agents as (
    select k.id from policy.clients k where k.kind = 'agent' and (p_client is null or k.id = p_client)
  ),
  tasks as (
    select substr(m.created_by, 8) as client_id, v.used
    from ledger.task_value(p_at - interval '28 days', p_at, p_within) v
    join ledger.moves m on m.id = v.move_id
    where m.created_by like 'client:%'
  ),
  cards as (
    select c.id, c.target_kind, c.target_id,
      case when c.created_by like 'client:%' then substr(c.created_by, 8)
           when t.created_by like 'client:%' then substr(t.created_by, 8) end as client_id,
      d.answer, d.decided_at, s.event, s.code, s.at
    from ledger.cards c
    left join ledger.opportunities t on c.target_kind = 'opportunity' and t.id = c.target_id
    left join lateral (
      select o.answer, o.decided_at from knowledge.owner_decisions o
      where o.card_id = c.id and o.kind = 'answer' and o.tainted_at is null and o.decided_at <= p_at
        and o.compartments <@ p_within
        and not exists (select 1 from knowledge.owner_decisions l where l.supersedes = o.id and l.decided_at <= p_at)
      order by o.decided_at desc, o.id desc limit 1) d on true
    left join lateral (
      select e.event, e.code, e.at from ledger.record_events e
      where e.row_kind = 'card' and e.row_id = c.id and e.at <= p_at and e.compartments <@ p_within
      order by e.id desc limit 1) s on true
    where c.created_at > p_at - interval '28 days' and c.created_at <= p_at
      and c.tainted_at is null and c.compartments <@ p_within
      and (c.created_by like 'client:%' or t.created_by like 'client:%')
  ),
  questions as (
    select q.*,
      case
        when q.answer is not null and q.event in ('pending', 'deferred') and q.at > q.decided_at then 'waiting'
        when q.answer in ('reject', 'no', 'no_go', 'dismiss', 'not_now', 'different', 'decline', 'wrong') then 'no'
        when q.answer in ('later', 'skip', 'snooze', 'leave', 'cant_tell') then 'deferred'
        when q.answer is not null then 'yes'
        when q.event = 'withdrawn' and q.code like 'agent\_%' then 'by_agent'
        when q.event is null or q.event in ('pending', 'deferred') then 'waiting'
        else 'other'
      end as ending
    from cards q
  ),
  reasons as (
    select q.client_id, e.code
    from questions q
    join lateral (
      select r.code, r.event, r.by, r.row_kind from ledger.record_events r
      where r.row_kind = q.target_kind and r.row_id = q.target_id and r.at <= p_at and r.compartments <@ p_within
        and r.tainted_at is null
      order by r.id desc limit 1) e on true
    where q.ending = 'no' and e.by = 'owner' and e.code is not null and e.code <> 'cancelled'
      and ((e.row_kind = 'opportunity' and e.event = 'no_go'
            and exists (select 1 from ledger.opportunities o where o.id = q.target_id and o.tier is distinct from 'task'))
           or (e.row_kind in ('hypothesis', 'goal_proposal') and e.event = 'rejected'))
  )
  select a.id,
    (select count(*)::integer from tasks t where t.client_id = a.id),
    (select count(*)::integer from tasks t where t.client_id = a.id and t.used),
    (select count(*)::integer from questions q where q.client_id = a.id),
    (select count(*)::integer from questions q where q.client_id = a.id and q.ending = 'yes'),
    (select count(*)::integer from questions q where q.client_id = a.id and q.ending = 'no'),
    (select count(*)::integer from questions q where q.client_id = a.id and q.ending = 'deferred'),
    (select count(*)::integer from questions q where q.client_id = a.id and q.ending = 'by_agent'),
    (select count(*)::integer from questions q where q.client_id = a.id and q.ending = 'waiting'),
    (select count(*)::integer from questions q where q.client_id = a.id and q.ending = 'other'),
    (select coalesce(array_agg(d.code order by d.code), '{}'::text[]) from reasons d where d.client_id = a.id),
    (select count(*)::integer from ledger.card_relays y
     where y.client_id = a.id and y.reopened_at > p_at - interval '28 days' and y.reopened_at <= p_at
       and y.compartments <@ p_within),
    (select count(*)::integer from policy.calls x
     where x.client_id = a.id and x.at > p_at - interval '28 days' and x.at <= p_at
       and x.outcome in ('unauthorized', 'not_permitted', 'invalid_request', 'unsupported_template', 'unknown_role'))
  from agents a
  order by a.id
$$;

CREATE FUNCTION ledger.agent_ruling_kinds() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select array['agent_claim']::text[]
$$;

CREATE FUNCTION ledger.agent_weeks_within(p_at timestamp with time zone, p_weeks integer, p_within text[], p_client text) RETURNS TABLE(client_id text, week date, placed integer, used integer, unused integer, open integer, budget integer, bets_left integer, asked integer, paid integer, refused integer, taken_back integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with spans as (
    select starts, starts + interval '7 days' as ends, least(starts + interval '7 days', p_at + interval '1 microsecond') as until
    from (select (date_trunc('week', p_at at time zone 'UTC') - make_interval(days => 7 * i)) at time zone 'UTC' as starts
          from generate_series(0, least(greatest(coalesce(p_weeks, 1), 1), 26) - 1) as i) w
  ),
  bets as (
    select * from ledger.bet_endings((select min(s.starts) from spans s) - interval '1 microsecond', p_at, p_within, p_client)
  )
  select b.client_id, (s.starts at time zone 'UTC')::date,
    (select count(*)::integer from bets e where e.client_id = b.client_id and e.bet_at >= s.starts and e.bet_at < s.ends),
    (select count(*)::integer from bets e where e.client_id = b.client_id and e.bet_at >= s.starts and e.bet_at < s.ends and e.ending = 'used'),
    (select count(*)::integer from bets e where e.client_id = b.client_id and e.bet_at >= s.starts and e.bet_at < s.ends and e.ending = 'unused'),
    (select count(*)::integer from bets e where e.client_id = b.client_id and e.bet_at >= s.starts and e.bet_at < s.ends and e.ending = 'open'),
    b.budget, greatest(0, b.budget - b.placed),
    q.asked, q.paid, q.refused,
    (select count(*)::integer from ledger.card_relays y
     where y.client_id = b.client_id and y.reopened_at >= s.starts and y.reopened_at < s.until
       and y.compartments <@ p_within)
  from spans s
  cross join lateral ledger.bets_within(least(s.ends - interval '1 microsecond', p_at), p_within, p_client) b
  join lateral ledger.agent_questions_within(s.starts, s.until, p_within, p_client) q on q.client_id = b.client_id
  order by b.client_id, s.starts desc
$$;

CREATE FUNCTION ledger.answer_card(p_id text, p_request text, p_opportunity text, p_move text, p_answer text, p_cited_kinds text[], p_cited_ids text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_client record;
  v_card ledger.cards;
  v_keys text[];
  v_own boolean;
begin
  perform ledger.lock_rows('{}'::text[]);
  v_keys := policy.clearance_keys();
  if p_id is null or p_id !~ '^can_[0-9A-HJKMNP-TV-Z]{26}$' or p_request is null or p_request !~ '^[A-Za-z0-9_-]{8,64}$'
     or p_opportunity is null or p_move is null or p_answer is null or p_answer !~ '^[a-z][a-z0-9_]{0,31}$'
     or p_cited_kinds is null or p_cited_ids is null or cardinality(p_cited_kinds) <> cardinality(p_cited_ids)
     or cardinality(p_cited_ids) > 100
     or exists (select 1 from unnest(p_cited_kinds, p_cited_ids) as r (kind, id)
                where r.kind is null or r.kind !~ '^[a-z][a-z0-9_]{0,31}$' or r.id is null or r.id !~ '^[A-Za-z0-9_-]{1,128}$'
                   or starts_with(r.id, 'hdl_')) then
    return 'invalid';
  end if;
  if exists (select 1 from ledger.card_answers a where a.request_id = p_request and policy.label_key(a.compartments) = any (v_keys)) then
    return 'ok';
  end if;
  select c.id, c.name, c.compartments into v_client from policy.current_client() c;
  if not found then
    return 'not_found';
  end if;
  select c.* into v_card from ledger.cards c
  join ledger.opportunities o on o.id = p_opportunity and o.gap_trigger = 'card_question' and o.gap_subject = c.id
    and o.tainted_at is null and policy.label_key(o.compartments) = any (v_keys)
  where c.tainted_at is null and policy.label_key(c.compartments) = any (v_keys)
    and exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = o.id and l.holder = v_client.id and l.lease_until >= now())
    and exists (select 1 from ledger.moves m where m.id = p_move and m.opportunity_id = o.id and m.tainted_at is null
                and policy.label_key(m.compartments) = any (v_keys));
  if not found or not (v_card.compartments <@ v_client.compartments) then
    return 'not_found';
  end if;
  if v_card.kind = any (ledger.card_relay_never()) then
    return 'refused';
  end if;
  perform ledger.lock_rows(array[v_card.id, 'author:' || v_card.created_by]);
  v_own := coalesce(v_card.created_by = 'client:' || v_client.id
    or (v_card.kind = 'agent_claim' and v_card.target_kind = 'claim' and exists (
          select 1 from knowledge.claims kc join ledger.agent_writes w on w.evidence_id = kc.evidence_id
          where kc.id = v_card.target_id and w.client_id = v_client.id)), false);
  if not (v_card.kind = any (ledger.card_attempt_kinds()))
     or v_own
     or not (p_answer = 'cant_tell' or p_answer = any (v_card.options))
     or (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = v_card.id order by r.id desc limit 1)
        not in ('pending', 'deferred') then
    return 'refused';
  end if;
  if exists (select 1 from ledger.card_answers a where a.card_id = v_card.id and a.client_id = v_client.id) then
    return 'already_answered';
  end if;
  insert into ledger.card_answers (id, request_id, card_id, opportunity_id, move_id, client_id, client_name, answer, created_at, compartments)
  values (p_id, p_request, v_card.id, p_opportunity, p_move, v_client.id, v_client.name, p_answer, now(), v_card.compartments);
  if ledger.card_answer_settles(v_card.kind, p_answer)
     and not exists (select 1 from ledger.record_events r where r.row_kind = 'card' and r.row_id = v_card.id and r.by = 'owner') then
    if v_card.kind = any (ledger.agent_ruling_kinds()) then
      insert into ledger.agent_rulings (card_id, answer_id, kind, answer, client_id, client_name, cited_kinds, cited_ids, created_at, compartments)
      values (v_card.id, p_id, v_card.kind, p_answer, v_client.id, v_client.name, p_cited_kinds, p_cited_ids, now(), v_card.compartments);
    end if;
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
    values ('card', v_card.id, 'withdrawn', clock_timestamp(), 'system:agent_attempt', v_card.compartments, 'agent_' || p_answer);
    perform ledger.admit_deferred(v_card.created_by);
    return 'settled';
  end if;
  return 'ok';
end
$_$;

CREATE FUNCTION ledger.answer_owner_question(session_id text, new_id text, request_id text, opportunity_id text, test_id text, decision_id text, effect text, content_fp text, cites_fp text, stamps text[], compartments text[], body_enc jsonb) RETURNS TABLE(outcome text, record_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_name text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_author text;
  v_label text[];
  v_record_label text[];
  v_earlier record;
  v_move text;
  v_hypothesis text;
  v_hypothesis_label text[];
  v_counts boolean;
  v_result text;
  v_status text;
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'an append runs read committed' using errcode = '42501';
  end if;
  select c.id, c.name, c.compartments, c.views, c.tools into v_caller, v_name, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('answer_owner_question' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = answer_owner_question.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if answer_owner_question.effect is null or answer_owner_question.effect not in ('supports', 'refutes', 'neither') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  v_record_label := policy.record_label();
  v_move := (select m.id from ledger.moves m
             where m.opportunity_id = answer_owner_question.opportunity_id and m.created_by = v_author
               and m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys)
             order by m.created_at desc, m.id collate "C" desc limit 1);
  perform ledger.lock_rows(case when v_move is null then '{}'::text[] else array[v_move, answer_owner_question.opportunity_id] end);

  select w.id, w.kind, w.content_fp, w.opportunity_id into v_earlier
  from ledger.agent_writes w where w.client_id = v_caller and w.request_id = answer_owner_question.request_id;
  if found then
    if v_earlier.kind = 'answer' and v_earlier.content_fp = answer_owner_question.content_fp and v_earlier.opportunity_id = answer_owner_question.opportunity_id then
      return query select 'replayed'::text, v_earlier.id;
    else
      return query select 'request_reused'::text, null::text;
    end if;
    return;
  end if;
  if exists (select 1 from ledger.hypothesis_tests t where t.created_by = v_author and t.request_id = answer_owner_question.request_id) then
    return query select 'request_reused'::text, null::text;
    return;
  end if;
  if answer_owner_question.compartments is distinct from v_record_label then
    return query select 'label_mismatch'::text, null::text;
    return;
  end if;
  if answer_owner_question.body_enc is null or not (jsonb_typeof(answer_owner_question.body_enc) = 'object' and answer_owner_question.body_enc ?& array['v', 'nonce', 'ciphertext', 'tag'] and (answer_owner_question.body_enc - array['v', 'nonce', 'ciphertext', 'tag']) = '{}'::jsonb
      and answer_owner_question.body_enc -> 'v' = '1'::jsonb and jsonb_typeof(answer_owner_question.body_enc -> 'nonce') = 'string' and jsonb_typeof(answer_owner_question.body_enc -> 'ciphertext') = 'string' and jsonb_typeof(answer_owner_question.body_enc -> 'tag') = 'string'
      and answer_owner_question.body_enc ->> 'nonce' <> '' and answer_owner_question.body_enc ->> 'tag' <> '' and answer_owner_question.body_enc ->> 'nonce' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' and answer_owner_question.body_enc ->> 'ciphertext' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' and answer_owner_question.body_enc ->> 'tag' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$') then
    return query select 'body_refused'::text, null::text;
    return;
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = answer_owner_question.session_id
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return query select 'read_removed'::text, null::text;
    return;
  end if;
  if cardinality(answer_owner_question.stamps) > 0
     and exists (select 1 from ledger.memory_projections m
                 where m.id = any (answer_owner_question.stamps) and m.client_id = v_caller and m.tainted_at is not null) then
    return query select 'not_found'::text, null::text;
    return;
  end if;

  select o.hypothesis_id into v_hypothesis from ledger.opportunities o
  where o.id = answer_owner_question.opportunity_id and o.kind = 'owner_question' and o.tainted_at is null
    and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys);
  v_status := (select r.event from ledger.record_events r
               where r.row_kind = 'opportunity' and r.row_id = answer_owner_question.opportunity_id and policy.label_key(r.compartments) = any (v_keys)
               order by r.id desc limit 1);
  if v_hypothesis is null or v_move is null or v_status is distinct from 'claimed'
     or not exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = answer_owner_question.opportunity_id
                      and l.holder = v_caller and l.lease_until >= now())
     or (select d.decision || '/' || d.decided_by from ledger.opportunity_decisions d where d.opportunity_id = answer_owner_question.opportunity_id order by d.id desc limit 1)
          is distinct from 'go/owner'
     or (select r.event from ledger.record_events r
         where r.row_kind = 'move' and r.row_id = v_move and r.event <> 'reported' and policy.label_key(r.compartments) = any (v_keys)
         order by r.id desc limit 1) is distinct from 'cleared'
     or exists (select 1 from ledger.agent_writes w where w.opportunity_id = answer_owner_question.opportunity_id) then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  select h.compartments into v_hypothesis_label from ledger.hypotheses h
  where h.id = v_hypothesis and h.compartments <@ v_clearance and policy.label_key(h.compartments) = any (v_keys) and h.tainted_at is null;
  if v_hypothesis_label is null then
    return query select 'not_found'::text, null::text;
    return;
  end if;

  begin
    insert into ledger.agent_writes (id, client_id, client_name, session_id, request_id, tool, kind, compartments, writer_views, content_fp, cites_fp, cites,
      body_enc, opportunity_id)
    values (answer_owner_question.new_id, v_caller, v_name, answer_owner_question.session_id, answer_owner_question.request_id, 'answer_owner_question',
            'answer', v_record_label, v_views, answer_owner_question.content_fp, answer_owner_question.cites_fp, '{}', answer_owner_question.body_enc,
            answer_owner_question.opportunity_id);
    insert into knowledge.owner_decisions (id, request_id, kind, target_kind, target_id, answer, queue_depth, decided_at, compartments)
    values (answer_owner_question.decision_id, answer_owner_question.new_id, 'owner_answer', 'opportunity', answer_owner_question.opportunity_id,
            answer_owner_question.effect, 0, now(), v_record_label);
    v_counts := v_label <@ v_hypothesis_label;
    v_result := case answer_owner_question.effect when 'neither' then 'inconclusive' else answer_owner_question.effect end;
    insert into ledger.hypothesis_tests (id, request_id, created_by, session_id, compartments, hypothesis_id, result, counts)
    values (answer_owner_question.test_id, answer_owner_question.request_id, v_author, answer_owner_question.session_id, v_label, v_hypothesis, v_result, v_counts);
    if not ledger.add_basis('test', answer_owner_question.test_id, v_label, array['opportunity'], array[answer_owner_question.opportunity_id], v_clearance) then
      raise exception 'a ref did not resolve' using errcode = 'PIW01';
    end if;
    if v_counts and v_result <> 'inconclusive'
       and (select r.event from ledger.record_events r
            where r.row_kind = 'hypothesis' and r.row_id = v_hypothesis and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) = 'open' then
      insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
      values ('hypothesis', v_hypothesis, case v_result when 'supports' then 'supported' else 'refuted' end, now(), v_author, v_hypothesis_label,
              answer_owner_question.session_id);
    end if;
    if ledger.report_move(v_move, 'done', answer_owner_question.request_id, answer_owner_question.session_id, null, '{}'::text[], '{}'::text[])
         is distinct from 'done' then
      raise exception 'the move was not reported' using errcode = 'PIW01';
    end if;
  exception when sqlstate 'PIW01' then
    return query select 'not_found'::text, null::text;
    return;
  end;
  return query select 'ok'::text, answer_owner_question.new_id;
end
$_$;

CREATE FUNCTION ledger.answer_same_person(p_id text, p_request text, p_question text, p_opportunity text, p_verdict text, p_because text, p_cites text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_client record;
  v_question ledger.identity_questions;
  v_keys text[];
  v_a text[];
  v_b text[];
  v_seen integer;
  v_wide boolean;
begin
  perform ledger.lock_rows('{}'::text[]);
  v_keys := policy.clearance_keys();
  if p_id is null or p_id !~ '^ida_[0-9A-HJKMNP-TV-Z]{26}$' or p_request is null or p_verdict is null
     or p_verdict not in ('same', 'different', 'cant_tell') or p_cites is null or array_position(p_cites, null) is not null
     or cardinality(p_cites) > 20 or p_because is null or p_because !~ '^[a-z][a-z0-9_]{0,31}$' then
    return 'invalid';
  end if;
  if exists (select 1 from ledger.identity_answers a where a.request_id = p_request and policy.label_key(a.compartments) = any (v_keys)) then
    return 'ok';
  end if;
  if coalesce((select s.identity_agents from policy.work_settings s), 'off') <> 'on' then
    return 'agents_off';
  end if;
  select c.id, c.name, c.compartments into v_client from policy.current_client() c;
  if not found then
    return 'not_found';
  end if;
  select q.* into v_question from ledger.identity_questions q
  join ledger.opportunities o on o.id = p_opportunity and o.gap_trigger = 'same_person' and o.gap_subject = q.batch and policy.label_key(o.compartments) = any (v_keys)
  where q.id = p_question and q.state = 'agents' and policy.label_key(q.compartments) = any (v_keys)
    and exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = o.id and l.holder = v_client.id and l.lease_until >= now());
  if not found or not (v_question.compartments <@ v_client.compartments) then
    return 'not_found';
  end if;
  select count(*), coalesce(bool_or(not (r.compartments <@ v_question.compartments)), false) into v_seen, v_wide from (
    select m.compartments from knowledge.messages m where m.id = any (p_cites) and not m.held and m.compartments <@ v_client.compartments and policy.label_key(m.compartments) = any (v_keys)
    union all
    select c.compartments from knowledge.contacts c where c.id = any (p_cites) and c.compartments <@ v_client.compartments and policy.label_key(c.compartments) = any (v_keys)
    union all
    select l.compartments from knowledge.aliases l where l.id = any (p_cites) and l.compartments <@ v_client.compartments and policy.label_key(l.compartments) = any (v_keys)
    union all
    select a.compartments from knowledge.accounts a where a.id = any (p_cites) and a.compartments <@ v_client.compartments and policy.label_key(a.compartments) = any (v_keys)
  ) as r;
  if v_seen <> (select count(distinct one) from unnest(p_cites) as one) then
    return 'not_found';
  end if;
  if v_wide then
    return 'cite_label';
  end if;
  v_a := ledger.same_person_side(v_question.a_entity, v_keys);
  v_b := ledger.same_person_side(v_question.b_entity, v_keys);
  if p_verdict = 'same' and not (
       (exists (select 1 from knowledge.messages m join knowledge.interaction_log i on i.evidence_id = m.evidence_id and policy.label_key(i.compartments) = any (v_keys)
                where m.id = any (p_cites) and i.entity_id = any (v_a) and policy.label_key(m.compartments) = any (v_keys)
                  and not exists (select 1 from knowledge.interaction_log x where x.evidence_id = m.evidence_id and x.entity_id = any (v_b) and policy.label_key(x.compartments) = any (v_keys)))
        or exists (select 1 from knowledge.contact_addresses x where x.contact_id = any (p_cites) and x.entity_id = any (v_a) and policy.label_key(x.compartments) = any (v_keys)
                   and not exists (select 1 from knowledge.contact_addresses y where y.contact_id = x.contact_id and y.entity_id = any (v_b) and policy.label_key(y.compartments) = any (v_keys)))
        or exists (select 1 from knowledge.aliases l where l.id = any (p_cites) and l.entity_id = any (v_a) and policy.label_key(l.compartments) = any (v_keys))
        or exists (select 1 from knowledge.accounts c where c.id = any (p_cites) and c.entity_id = any (v_a) and policy.label_key(c.compartments) = any (v_keys)))
       and
       (exists (select 1 from knowledge.messages m join knowledge.interaction_log i on i.evidence_id = m.evidence_id and policy.label_key(i.compartments) = any (v_keys)
                where m.id = any (p_cites) and i.entity_id = any (v_b) and policy.label_key(m.compartments) = any (v_keys)
                  and not exists (select 1 from knowledge.interaction_log x where x.evidence_id = m.evidence_id and x.entity_id = any (v_a) and policy.label_key(x.compartments) = any (v_keys)))
        or exists (select 1 from knowledge.contact_addresses x where x.contact_id = any (p_cites) and x.entity_id = any (v_b) and policy.label_key(x.compartments) = any (v_keys)
                   and not exists (select 1 from knowledge.contact_addresses y where y.contact_id = x.contact_id and y.entity_id = any (v_a) and policy.label_key(y.compartments) = any (v_keys)))
        or exists (select 1 from knowledge.aliases l where l.id = any (p_cites) and l.entity_id = any (v_b) and policy.label_key(l.compartments) = any (v_keys))
        or exists (select 1 from knowledge.accounts c where c.id = any (p_cites) and c.entity_id = any (v_b) and policy.label_key(c.compartments) = any (v_keys)))) then
    return 'no_evidence';
  end if;
  if p_verdict = 'different' and (cardinality(p_cites) = 0
       or exists (select 1 from knowledge.messages m where m.id = any (p_cites) and policy.label_key(m.compartments) = any (v_keys)
                  and not exists (select 1 from knowledge.interaction_log i where i.evidence_id = m.evidence_id and i.entity_id = any (v_a || v_b) and policy.label_key(i.compartments) = any (v_keys)))) then
    return 'no_evidence';
  end if;
  if exists (select 1 from ledger.identity_answers a where a.question_id = p_question and a.client_id = v_client.id and a.evidence_fp = v_question.evidence_fp and policy.label_key(a.compartments) = any (v_keys)) then
    return 'already_answered';
  end if;
  insert into ledger.identity_answers (id, request_id, question_id, client_id, client_name, opportunity_id, verdict, because, cites, cite_evidence, cite_address_fps, evidence_fp, created_at, compartments)
  values (p_id, p_request, p_question, v_client.id, v_client.name, p_opportunity, p_verdict, p_because, p_cites,
          array(select m.evidence_id from knowledge.messages m where m.id = any (p_cites) and policy.label_key(m.compartments) = any (v_keys)
                union select c.evidence_id from knowledge.contacts c where c.id = any (p_cites) and policy.label_key(c.compartments) = any (v_keys)
                union select l.evidence_id from knowledge.aliases l where l.id = any (p_cites) and policy.label_key(l.compartments) = any (v_keys)),
          array(select a.value_fp from knowledge.accounts a where a.id = any (p_cites) and policy.label_key(a.compartments) = any (v_keys)),
          v_question.evidence_fp, now(), v_question.compartments);
  return 'ok';
end
$_$;

CREATE FUNCTION ledger.append_draft(id text, request_id text, session_id text, opportunity_id text, reply_to text, account_label text, recipient_fps text[], recipient_domain_fps text[], payload_fp text, body_fp text, body_enc jsonb, ref_kinds text[], ref_ids text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_author text;
  v_label text[];
  v_found text;
  v_account text;
  v_thread text;
  v_evidence text;
  v_recipients text[];
  v_domains text[];
  v_kinds text[];
  v_ids text[];
  v_case text;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  perform ledger.lock_rows(array[v_caller]);
  if v_caller is null or not ('draft_message' = any (v_tools)) or not ('work' = any (v_views))
     or not exists (select 1 from ledger.sessions s where s.id = append_draft.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if append_draft.id is null or append_draft.id !~ '^drf_[0-9A-HJKMNP-TV-Z]{26}$'
     or append_draft.request_id is null or append_draft.request_id !~ '^[A-Za-z0-9_-]{8,64}$'
     or coalesce(cardinality(append_draft.recipient_fps), 0) not between 1 and 10
     or array_to_string(append_draft.recipient_fps, ',') !~ '^[0-9a-f]{64}(,[0-9a-f]{64})*$'
     or array_position(append_draft.recipient_fps, null) is not null
     or coalesce(cardinality(append_draft.recipient_domain_fps), 0) not between 1 and 10
     or array_to_string(append_draft.recipient_domain_fps, ',') !~ '^[0-9a-f]{64}(,[0-9a-f]{64})*$'
     or array_position(append_draft.recipient_domain_fps, null) is not null
     or coalesce(append_draft.payload_fp, '') !~ '^[0-9a-f]{64}$' or coalesce(append_draft.body_fp, '') !~ '^[0-9a-f]{64}$'
     or append_draft.body_enc is null or jsonb_typeof(append_draft.body_enc) <> 'object'
     or coalesce(cardinality(append_draft.ref_kinds), 0) > 20
     or coalesce(cardinality(append_draft.ref_kinds), 0) <> coalesce(cardinality(append_draft.ref_ids), 0) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);

  select d.id into v_found from ledger.drafts d where d.created_by = v_author and d.request_id = append_draft.request_id;
  if v_found is not null then
    return v_found;
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = append_draft.session_id and b.one ~ '^[0-9a-f]{64}$'
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if (select count(*) from ledger.drafts d
      where d.created_by = v_author
        and coalesce((select r.event from ledger.record_events r where r.row_kind = 'draft' and r.row_id = d.id order by r.id desc limit 1), 'new')
            in ('new', 'made', 'held')) >= 50 then
    return 'rate_limited';
  end if;

  if append_draft.reply_to is not null then
    select e.source_account_id, m.thread_fp, m.evidence_id into v_account, v_thread, v_evidence
    from knowledge.messages m
    join vault.evidence_items e on e.id = m.evidence_id
    join vault.source_accounts a on a.id = e.source_account_id
    where m.id = append_draft.reply_to and m.compartments <@ v_clearance and not m.held
      and a.connector = 'google_mail' and a.compartments <@ v_clearance
      and (append_draft.account_label is null or a.label = append_draft.account_label);
  elsif append_draft.account_label is not null then
    select a.id into v_account from vault.source_accounts a
    where a.label = append_draft.account_label and a.connector = 'google_mail' and a.compartments <@ v_clearance;
  end if;
  if v_account is null then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if append_draft.opportunity_id is not null
     and not exists (select 1 from ledger.opportunities o where o.id = append_draft.opportunity_id and o.compartments <@ v_clearance) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if append_draft.opportunity_id is not null
     and exists (select 1 from ledger.opportunities o where o.id = append_draft.opportunity_id and o.compartments <@ v_clearance and o.tier = 'task') then
    raise exception 'a task' using errcode = '22023';
  end if;

  v_recipients := array(select distinct x collate "C" from unnest(append_draft.recipient_fps) as x order by 1);
  v_domains := array(select distinct x collate "C" from unnest(append_draft.recipient_domain_fps) as x order by 1);
  v_case := case when append_draft.opportunity_id is not null then 'opportunity:' || append_draft.opportunity_id
    else encode(sha256(convert_to(coalesce(v_thread, 'new') || E'\n' || array_to_string(v_recipients, ','), 'UTF8')), 'hex') end;

  insert into ledger.drafts (id, request_id, created_by, session_id, compartments, opportunity_id, source_account_id, reply_to_evidence_id,
    thread_fp, recipient_fps, recipient_domain_fps, payload_fp, body_fp, case_key, body_enc)
  values (append_draft.id, append_draft.request_id, v_author, append_draft.session_id, v_label, append_draft.opportunity_id, v_account, v_evidence,
    v_thread, v_recipients, v_domains, append_draft.payload_fp, append_draft.body_fp, v_case, append_draft.body_enc);

  with given as (
    select r.kind, r.id, r.ord from unnest(append_draft.ref_kinds, append_draft.ref_ids) with ordinality as r (kind, id, ord)
  ),
  added as (
    select 'message' as kind, append_draft.reply_to as id, 1000 as ord where append_draft.reply_to is not null
    union all
    select 'entity', p.entity_id, 2000 + row_number() over (order by p.entity_id collate "C")
    from (select distinct a.entity_id from knowledge.accounts a join knowledge.entities en on en.id = a.entity_id and en.kind = 'person'
          where a.value_fp = any (v_recipients) and a.compartments <@ v_clearance) p
  ),
  every as (
    select g.kind, g.id, g.ord from given g
    union all
    select a.kind, a.id, a.ord from added a where not exists (select 1 from given g where g.kind = a.kind and g.id = a.id)
  )
  select coalesce(array_agg(x.kind order by x.ord), '{}'::text[]), coalesce(array_agg(x.id order by x.ord), '{}'::text[]) into v_kinds, v_ids from every x;
  if not ledger.add_basis('draft', append_draft.id, v_label, v_kinds, v_ids, v_clearance) then
    raise exception 'not permitted' using errcode = '42501';
  end if;

  insert into ledger.draft_beliefs (draft_id, fact_key_fp, state_fp, compartments)
  select append_draft.id, k.fact_key_fp, coalesce(t.state_fp, repeat('0', 64)), v_label
  from (
    select distinct c.fact_key_fp from knowledge.claims c
    join vault.evidence_items ce on ce.id = c.evidence_id
    join ledger.basis bs on bs.row_kind = 'draft' and bs.row_id = append_draft.id and bs.evidence_id is not null
    join vault.evidence_items be on be.id = bs.evidence_id
    where policy.label_key(c.compartments) = any (ledger.keys_of(v_label))
      and ce.source_account_id = be.source_account_id and ce.source_item_fp = be.source_item_fp) k
  left join lateral (
    select l.state_fp from ledger.trigger_log l
    where policy.label_key(l.compartments) = any (ledger.keys_of(v_label)) and l.clearance_key = policy.label_key(v_label)
      and l.fact_key_fp = k.fact_key_fp and l.cause not in ('due', 'dropped')
    order by l.id desc limit 1) t on true
  on conflict (draft_id, fact_key_fp) do nothing;

  return append_draft.id;
end
$_$;

CREATE FUNCTION ledger.append_gate_decision(decision_id text, draft_id text, phase text, payload_fp text, checks jsonb, facts jsonb, point_version integer, definition_hash text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_reader boolean := session_user = 'pi_reader';
  v_caller text;
  d ledger.drafts%rowtype;
  v_status text;
  v_rows jsonb;
  v_by text;
  v_kind text;
  v_label text[];
  v_author_name text;
  v_vetoes boolean;
  v_conflict boolean;
  v_cap boolean;
  v_facts jsonb;
  v_disclosure boolean;
begin
  if v_reader then
    select c.id into v_caller from policy.current_client() c;
    if v_caller is null or append_gate_decision.phase is distinct from 'draft' then
      raise exception 'not permitted' using errcode = '42501';
    end if;
    perform ledger.lock_rows(array(select dr.id from ledger.drafts dr
                                   where dr.id = append_gate_decision.draft_id and dr.created_by = 'client:' || v_caller));
  elsif session_user <> 'pi_proxy' then
    raise exception 'not permitted' using errcode = '42501';
  else
    perform ledger.lock_rows(array[append_gate_decision.draft_id]);
  end if;
  select dr.* into d from ledger.drafts dr where dr.id = append_gate_decision.draft_id;
  if v_reader and (d.id is null or d.created_by <> 'client:' || v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if d.id is null or append_gate_decision.phase is null or append_gate_decision.phase not in ('draft', 'send')
     or coalesce(append_gate_decision.decision_id, '') !~ '^gdc_[0-9A-HJKMNP-TV-Z]{26}$'
     or coalesce(append_gate_decision.payload_fp, '') !~ '^[0-9a-f]{64}$'
     or append_gate_decision.point_version is null or coalesce(append_gate_decision.definition_hash, '') !~ '^[0-9a-f]{64}$'
     or append_gate_decision.checks is null or jsonb_typeof(append_gate_decision.checks) <> 'array'
     or jsonb_array_length(append_gate_decision.checks) <> 9
     or exists (select 1 from jsonb_array_elements(append_gate_decision.checks) as x (one)
                where jsonb_typeof(x.one) <> 'object' or jsonb_typeof(x.one -> 'passed') is distinct from 'boolean'
                  or (x.one ->> 'kind') is null or (x.one - array['kind', 'passed']) <> '{}'::jsonb)
     or (select count(distinct x.one ->> 'kind') from jsonb_array_elements(append_gate_decision.checks) as x (one)
         where x.one ->> 'kind' in ('authority', 'vetoes', 'conflict_lists', 'contact_policy', 'disclosure', 'freshness', 'consent', 'channel_cap', 'payload_hash')) <> 9
     or (append_gate_decision.phase = 'send' and (append_gate_decision.facts is null or jsonb_typeof(append_gate_decision.facts) <> 'object')) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_status := coalesce((select r.event from ledger.record_events r where r.row_kind = 'draft' and r.row_id = d.id order by r.id desc limit 1), 'new');
  if append_gate_decision.phase = 'draft' and v_status <> 'new' then
    raise exception 'invalid request' using errcode = '22023';
  end if;

  v_rows := (select jsonb_object_agg(x.one ->> 'kind', (x.one -> 'passed')) from jsonb_array_elements(append_gate_decision.checks) as x (one));
  if v_reader then
    v_kind := coalesce((select o.kind from ledger.opportunities o where o.id = d.opportunity_id), 'proposal');
    v_vetoes := not exists (select 1 from unnest(d.recipient_fps) as r (fp) where policy.vetoed(array['address'], array[r.fp], v_kind))
      and not exists (select 1 from unnest(d.recipient_domain_fps) as r (fp) where policy.vetoed(array['domain'], array[r.fp], v_kind))
      and not policy.vetoed(
        array(select b.ref_kind from ledger.basis b where b.row_kind = 'draft' and b.row_id = d.id order by b.id)
          || coalesce((select array[o.about_kind] from ledger.opportunities o where o.id = d.opportunity_id and o.about_id is not null), '{}'::text[]),
        array(select b.ref_id from ledger.basis b where b.row_kind = 'draft' and b.row_id = d.id order by b.id)
          || coalesce((select array[o.about_id] from ledger.opportunities o where o.id = d.opportunity_id and o.about_id is not null), '{}'::text[]),
        v_kind)
      and not exists (select 1 from knowledge.vetoes v where v.subject = 'any' and v.lifted_at is null and v.work_kind = v_kind);
    v_conflict := not exists (select 1 from unnest(d.recipient_fps) as r (fp)
                              join knowledge.suppressions s on s.kind = 'address' and s.value_fp = r.fp);
    select c.name into v_author_name from policy.clients c where 'client:' || c.id = d.created_by;
    v_cap := v_author_name is not null
      and not exists (select 1 from unnest(d.compartments) as c (one) where c.one not in ('own', 'public') and c.one <> 'agent:' || v_author_name)
      and coalesce((select a.compartments = array['own'] from vault.source_accounts a where a.id = d.source_account_id), false);
    v_rows := v_rows || jsonb_build_object('vetoes', v_vetoes, 'conflict_lists', v_conflict, 'channel_cap', v_cap);
  end if;

  v_by := case when append_gate_decision.phase = 'draft' then d.created_by else 'owner' end;
  if append_gate_decision.phase = 'send' then
    v_facts := jsonb_set(jsonb_set(append_gate_decision.facts, '{draft,ageSeconds}', '0'::jsonb), '{account,syncAgeSeconds}',
      case when append_gate_decision.facts #> '{account,syncAgeSeconds}' = 'null'::jsonb then 'null'::jsonb else '0'::jsonb end);
  end if;
  insert into ledger.gate_checks (created_by, compartments, decision_id, phase, kind, passed, draft_id, payload_fp, facts)
  select v_by, d.compartments, append_gate_decision.decision_id, append_gate_decision.phase, k.kind, (v_rows ->> k.kind)::boolean, d.id,
    append_gate_decision.payload_fp, v_facts
  from unnest(array['authority', 'vetoes', 'conflict_lists', 'contact_policy', 'disclosure', 'freshness', 'consent', 'channel_cap', 'payload_hash']) as k (kind);

  v_disclosure := (v_rows ->> 'disclosure')::boolean;
  insert into ledger.decision_point_calls (id, request_id, created_by, compartments, point, version, definition_hash, rung, input_hash,
    output, effect, effect_class, escalated, card_id, subject_kind, subject_id)
  values ('dpc_' || substr(append_gate_decision.decision_id, 5), append_gate_decision.decision_id, v_by, d.compartments, 'draft_disclosure',
    append_gate_decision.point_version, append_gate_decision.definition_hash, 0,
    encode(sha256(convert_to(jsonb_build_object('draft', d.id, 'phase', append_gate_decision.phase, 'decision', append_gate_decision.decision_id,
      'checks', v_rows)::text, 'UTF8')), 'hex'),
    case when v_disclosure then 'no_finding' else 'hold' end, case when v_disclosure then 'record_silence' else 'hold' end, 'narrow',
    false, null, 'draft', d.id);

  if append_gate_decision.phase = 'draft' then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
    values ('draft', d.id, case when (select bool_and(value::boolean) from jsonb_each_text(v_rows)) then 'made' else 'held' end, now(), d.created_by,
      d.compartments, d.session_id);
  end if;
end
$_$;

CREATE FUNCTION ledger.append_step(run_id text, ordinal integer, session_id text, kind text, status text, tool text, code text, prompt_id text, prompt_version text, model_id text, cost_microusd bigint, input_tokens integer DEFAULT NULL::integer, output_tokens integer DEFAULT NULL::integer, ms integer DEFAULT NULL::integer, result_code_points integer DEFAULT NULL::integer, detail_enc jsonb DEFAULT NULL::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_attempt integer;
  v_attempt_client text;
  v_attempt_label text[];
  v_taken timestamptz;
  v_mark bigint;
  v_run_label text[];
  v_turns integer;
  v_tool_calls integer;
  v_ceiling bigint;
  v_day date;
  v_models integer;
  v_steps integer;
  v_checks integer;
  v_web integer;
  v_bound text;
  v_keys text[];
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('append_step' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'reasoner'
     or not exists (select 1 from ledger.sessions s where s.id = append_step.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if append_step.kind is null or append_step.kind not in ('model_call', 'tool_call', 'output_check', 'web_search', 'web_fetch') or append_step.ordinal is null or append_step.ordinal < 0
     or (append_step.kind in ('web_search', 'web_fetch')) is distinct from (append_step.detail_enc is not null)
     or (append_step.detail_enc is not null and jsonb_typeof(append_step.detail_enc) is distinct from 'object') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform ledger.lock_rows(array(select r.id from ledger.runs r
                                 where r.id = append_step.run_id and r.compartments <@ v_clearance and policy.label_key(r.compartments) = any (v_keys)));

  select a.attempt, a.client_id, a.compartments, a.taken_at, a.erasure_mark into v_attempt, v_attempt_client, v_attempt_label, v_taken, v_mark
  from ledger.run_attempts a where a.run_id = append_step.run_id order by a.attempt desc limit 1;
  v_run_label := (select r.compartments from ledger.runs r where r.id = append_step.run_id);
  if v_attempt is null or v_attempt_client <> v_caller
     or (select r.event from ledger.record_events r where r.row_kind = 'run' and r.row_id = append_step.run_id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1)
        is distinct from 'running'
     or not exists (select 1 from queue.leases l where l.resource_kind = 'run' and l.resource_id = append_step.run_id
                    and l.holder = v_caller and l.lease_until >= least(now(), v_taken + interval '3600 seconds'))
     or coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on'
     or ledger.label(v_clearance) is distinct from v_attempt_label
     or exists (select 1 from knowledge.erasures x where (x.journal_seq > v_mark or x.lift_seq > v_mark)
                and (x.touched is null or x.touched && v_clearance)) then
    return false;
  end if;

  v_day := (now() at time zone 'UTC')::date;
  select s.max_turns, s.max_tool_calls, s.max_microusd_per_day
  into v_turns, v_tool_calls, v_ceiling from policy.work_settings s;
  select count(*) filter (where t.kind = 'model_call'), count(*) filter (where t.kind in ('model_call', 'tool_call')), count(*) filter (where t.kind = 'output_check'),
         count(*) filter (where t.kind in ('web_search', 'web_fetch'))
  into v_models, v_steps, v_checks, v_web
  from ledger.run_steps t where t.run_id = append_step.run_id and t.attempt = v_attempt and policy.label_key(t.compartments) = any (v_keys);
  v_bound := case
    when now() >= v_taken + interval '3600 seconds' then 'timeout'
    when ledger.spend_on(v_day) >= v_ceiling then 'budget'
    when append_step.kind = 'output_check' then case when v_checks >= 80 then 'tool_limit' end
    when append_step.kind in ('web_search', 'web_fetch') then case when v_web >= 2000 then 'tool_limit' end
    when v_models >= v_turns then 'turn_limit'
    when v_steps >= v_turns + v_tool_calls then 'tool_limit'
    else null
  end;
  if v_bound is not null then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
    values ('run', append_step.run_id, 'failed', now(), 'system:bounds', v_run_label, v_bound);
    delete from queue.leases l where l.resource_kind = 'run' and l.resource_id = append_step.run_id;
    return false;
  end if;

  insert into ledger.run_steps (request_id, created_by, run_id, session_id, compartments, attempt, ordinal, client_id, kind, status, tool, code,
    prompt_id, prompt_version, model_id, cost_microusd, input_tokens, output_tokens, ms, result_code_points, detail_enc)
  values ('step_' || v_attempt || '_' || append_step.ordinal, 'run:' || append_step.run_id, append_step.run_id, append_step.session_id, v_attempt_label,
          v_attempt, append_step.ordinal, v_caller, append_step.kind, append_step.status, append_step.tool, append_step.code,
          append_step.prompt_id, append_step.prompt_version, append_step.model_id, append_step.cost_microusd,
          append_step.input_tokens, append_step.output_tokens, append_step.ms, append_step.result_code_points, append_step.detail_enc);
  update queue.leases l set lease_until = least(now() + interval '2400 seconds', v_taken + interval '3600 seconds')
  where l.resource_kind = 'run' and l.resource_id = append_step.run_id;
  return true;
end
$$;

CREATE FUNCTION ledger.apply_outcome_link(link bigint) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with applied as (
    update ledger.outcome_links l set applied = true
    where l.id = apply_outcome_link.link and l.judge like 'model:%' and not l.applied and l.tainted_at is null
      and l.opportunity_id is not null and l.move_result_link_id is null and not policy.is_restricted(l.compartments)
    returning l.id)
  select exists (select 1 from applied)
$$;

CREATE FUNCTION ledger.assess_outcomes(now timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  sends_written integer;
  opportunities_written integer;
begin
  perform ledger.lock_rows('{}'::text[]);

  with subjects as (
    select s.id, s.begun_at, s.compartments,
      array(select l.id from ledger.move_result_links l
            left join knowledge.messages m on l.ref_kind = 'message' and m.id = l.ref_id
            where l.send_id = s.id and l.result_kind = 'reply' and l.tainted_at is null
              and coalesce(m.sent_at, l.observed_at) <= s.begun_at + interval '14 days'
            order by l.id collate "C") as links
    from ledger.sent_messages s
    join ledger.drafts d on d.id = s.draft_id
    where d.opportunity_id is null and s.tainted_at is null and d.tainted_at is null
      and exists (select 1 from ledger.record_events r where r.row_kind = 'send' and r.row_id = s.id and r.event = 'sent')
      and not exists (select 1 from ledger.outcome_assessments a where a.subject_kind = 'send' and a.subject_id = s.id and a."check" = 'answered')
  )
  insert into ledger.outcome_assessments (id, created_by, subject_kind, subject_id, "check", horizon_days, result, decided_by, link_ids, status_event_id, compartments)
  select ledger.new_id('oas'), 'system:outcomes', 'send', x.id, 'answered', 14,
    case when cardinality(x.links) > 0 then 'met' else 'not_met' end, 'code', x.links, null,
    ledger.label(x.compartments || coalesce((select array_agg(c.one) from ledger.move_result_links l cross join lateral unnest(l.compartments) as c (one) where l.id = any (x.links)), '{}'::text[]))
  from subjects x
  where cardinality(x.links) > 0 or assess_outcomes.now >= x.begun_at + interval '14 days' + interval '3 days'
  on conflict do nothing;
  get diagnostics sends_written = row_count;

  with facts as (
    select o.id, o.kind, o.compartments, o.due_at, g.go_at, fs.first_send_at, fs.last_send_at, c.id as close_id, c.event as close_event, c.at as close_at, c.by as close_by,
      case when o.kind in ('follow_up', 'reply') then
        array(select l.id from ledger.outcome_links l join vault.evidence_items e on e.id = l.evidence_id
              where l.opportunity_id = o.id and l.kind = 'met' and l.applied and l.attribution = 'caused' and l.tainted_at is null and l.move_result_link_id is null
                and coalesce((select m.sent_at from knowledge.messages m where m.evidence_id = e.id order by m.id collate "C" limit 1), e.observed_at)
                    <= coalesce(fs.last_send_at, g.go_at) + interval '14 days'
              order by l.id)
      else coalesce(c.outcome_links, '{}'::bigint[]) end as outcome_links,
      coalesce(c.outcome_links, '{}'::bigint[]) as close_links,
      exists (select 1 from ledger.record_events r
              where r.row_kind = 'opportunity' and r.row_id = o.id and r.event in ('outcome_met', 'outcome_not_met')
                and not exists (select 1 from ledger.outcome_links l
                                where l.opportunity_id = o.id and l.kind = case r.event when 'outcome_met' then 'met' else 'not_met' end
                                  and l.applied and l.attribution = 'caused' and l.tainted_at is null and l.move_result_link_id is null)) as observed_close,
      (select dt.starts_at from knowledge.event_details dt where o.about_kind = 'event' and dt.event_id = o.about_id) as starts_at,
      case when o.kind in ('follow_up', 'reply') then
        array(select l.id from ledger.drafts d
              join ledger.sent_messages s on s.draft_id = d.id
              join ledger.move_result_links l on l.send_id = s.id and l.result_kind = 'reply' and l.tainted_at is null
              left join knowledge.messages m on l.ref_kind = 'message' and m.id = l.ref_id
              where d.opportunity_id = o.id and s.tainted_at is null and d.tainted_at is null
                and coalesce(m.sent_at, l.observed_at) <= s.begun_at + interval '14 days'
              order by l.id collate "C")
      else '{}'::text[] end as links
    from ledger.opportunities o
    left join lateral (
      select min(x.created_at) as go_at from ledger.opportunity_decisions x
      where x.opportunity_id = o.id and x.decision = 'go' and x.tainted_at is null) g on true
    left join lateral (
      select min(s.begun_at) as first_send_at, max(s.begun_at) as last_send_at from ledger.drafts d join ledger.sent_messages s on s.draft_id = d.id
      where d.opportunity_id = o.id and s.tainted_at is null and d.tainted_at is null
        and exists (select 1 from ledger.record_events r where r.row_kind = 'send' and r.row_id = s.id and r.event = 'sent')) fs on true
    left join lateral (
      select r.id, case r.event when 'outcome_met' then 'done' when 'outcome_not_met' then 'no_go' else r.event end as event, r.at, r.by,
        array(select l.id from ledger.outcome_links l
              where r.event in ('outcome_met', 'outcome_not_met') and l.opportunity_id = o.id and l.kind = case r.event when 'outcome_met' then 'met' else 'not_met' end
                and l.applied and l.attribution = 'caused' and l.tainted_at is null and l.move_result_link_id is null
              order by l.id) as outcome_links
      from ledger.record_events r
      where r.row_kind = 'opportunity' and r.row_id = o.id
        and (r.event in ('done', 'no_go', 'expired')
             or (r.event in ('outcome_met', 'outcome_not_met')
                 and exists (select 1 from ledger.outcome_links l
                             where l.opportunity_id = o.id and l.kind = case r.event when 'outcome_met' then 'met' else 'not_met' end
                               and l.applied and l.attribution = 'caused' and l.tainted_at is null and l.move_result_link_id is null)))
      order by (r.event in ('outcome_met', 'outcome_not_met')) desc, case when r.event in ('outcome_met', 'outcome_not_met') then -r.id else r.id end limit 1) c on true
    where o.tainted_at is null
      and (g.go_at is not null or fs.first_send_at is not null)
      and not exists (select 1 from ledger.outcome_assessments a where a.subject_kind = 'opportunity' and a.subject_id = o.id)
  ),
  judged as (
    select f.id, f.compartments, f.links, f.outcome_links, f.close_links, f.observed_close, 'answered' as check_name, 14 as horizon_days, f.close_by,
      case when cardinality(f.links) + cardinality(f.outcome_links) > 0 then 'met'
           when f.last_send_at is not null and assess_outcomes.now >= f.last_send_at + interval '14 days' + interval '3 days' then 'not_met'
           when f.first_send_at is null and f.close_event in ('no_go', 'expired') then 'not_met' end as result,
      case when cardinality(f.links) + cardinality(f.outcome_links) = 0 and f.first_send_at is null and f.close_event in ('no_go', 'expired') then f.close_id end as event_id
    from facts f where f.kind in ('follow_up', 'reply')
    union all
    select f.id, f.compartments, f.links, f.outcome_links, f.close_links, f.observed_close, 'done', null, f.close_by,
      case when f.close_event = 'done' and (f.starts_at is null or f.close_at < f.starts_at) then 'met'
           when f.close_event in ('no_go', 'expired') then 'not_met'
           when f.starts_at is not null and assess_outcomes.now >= f.starts_at + interval '3 days' then 'not_met' end,
      case when f.close_event = 'done' and (f.starts_at is null or f.close_at < f.starts_at) then f.close_id
           when f.close_event in ('no_go', 'expired') then f.close_id end
    from facts f where f.kind = 'meeting_prep'
    union all
    select h.id, h.compartments, h.links, h.outcome_links, h.close_links, h.observed_close, 'done', case when h.due_at is null and h.go_at is not null then 30 end, h.close_by,
      case when h.close_event = 'done' and (h.horizon_at is null or h.close_at <= h.horizon_at) then 'met'
           when h.close_event in ('no_go', 'expired') and h.go_at is not null then 'not_met'
           when h.horizon_at is not null and assess_outcomes.now >= h.horizon_at + interval '3 days' then 'not_met' end,
      case when h.close_event = 'done' and (h.horizon_at is null or h.close_at <= h.horizon_at) then h.close_id
           when h.close_event in ('no_go', 'expired') and h.go_at is not null then h.close_id end
    from (select f.*, coalesce(f.due_at, f.go_at + interval '30 days') as horizon_at from facts f where f.kind in ('investigate', 'goal_step', 'life_admin')) h
  )
  insert into ledger.outcome_assessments (id, created_by, subject_kind, subject_id, "check", horizon_days, result, decided_by, link_ids, status_event_id, compartments, outcome_link_ids)
  select ledger.new_id('oas'), 'system:outcomes', 'opportunity', j.id, j.check_name, j.horizon_days, j.result,
    case when j.event_id is not null and j.close_by = 'owner' then 'owner' else 'code' end,
    case when j.result = 'met' then j.links else '{}'::text[] end, j.event_id,
    ledger.label(j.compartments || coalesce((select array_agg(c.one) from ledger.move_result_links l cross join lateral unnest(l.compartments) as c (one)
                                             where j.result = 'met' and l.id = any (j.links)), '{}'::text[])
                 || coalesce((select array_agg(c.one) from ledger.outcome_links l cross join lateral unnest(l.compartments) as c (one)
                              where l.id = any (j.decided_by_links)), '{}'::text[])),
    j.decided_by_links::text[]
  from (select j.*, case when j.check_name = 'answered' and j.result = 'met' then j.outcome_links
                         when j.event_id is not null then j.close_links else '{}'::bigint[] end as decided_by_links
        from judged j where not j.observed_close) j
  where j.result is not null
  on conflict do nothing;
  get diagnostics opportunities_written = row_count;

  return sends_written + opportunities_written;
end
$$;

CREATE FUNCTION ledger.assign_defects(role text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
begin
  if assign_defects.role is not null and assign_defects.role !~ '^[a-z][a-z0-9-]{1,31}$' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if assign_defects.role is not null
     and not exists (select 1 from policy.clients k where k.status = 'active' and k.kind = 'agent' and assign_defects.role = any (k.roles)) then
    return false;
  end if;
  update ledger.improvements i
     set assignee_role = case when exists (select 1 from policy.clients k
                                           where k.status = 'active' and k.kind = 'agent' and assign_defects.role = any (k.roles)
                                             and i.compartments <@ k.compartments)
                              then assign_defects.role end
   where i.owner_role_at is null;
  return true;
end
$_$;

CREATE FUNCTION ledger.autonomy_gaps(at_time timestamp with time zone, meeting_until timestamp with time zone, due_until timestamp with time zone, reply_from timestamp with time zone, reply_until timestamp with time zone) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
begin
  if autonomy_gaps.at_time is null or autonomy_gaps.meeting_until is null or autonomy_gaps.due_until is null
     or autonomy_gaps.reply_from is null or autonomy_gaps.reply_until is null
     or autonomy_gaps.meeting_until < autonomy_gaps.at_time or autonomy_gaps.due_until < autonomy_gaps.at_time
     or autonomy_gaps.reply_until > autonomy_gaps.at_time or autonomy_gaps.reply_from > autonomy_gaps.reply_until then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select c.* from (
    select 'meeting_soon'::text as trigger, v.id as subject, ledger.label(v.compartments) as label, null::text as goal_id,
      'event'::text as about_kind, v.id as about_id, 'event'::text as source_kind, v.id as source_id,
      d.starts_at as at, d.starts_at as due_at, null::integer as facts, null::integer as ties
    from knowledge.events v
    join knowledge.event_details d on d.event_id = v.id and d.compartments <@ v.compartments
    where not d.cancelled and not d.all_day and coalesce(d.owner_response, 'accepted') <> 'declined'
      and d.starts_at > autonomy_gaps.at_time and d.starts_at <= autonomy_gaps.meeting_until
      and not policy.is_restricted(v.compartments)
      and exists (select 1 from knowledge.event_participants p join knowledge.entities e on e.id = p.entity_id and e.kind = 'person'
                  where p.event_id = v.id and p.compartments <@ v.compartments)
    union all
    select 'commitment_due'::text, k.fact_key_fp || '_' || to_char(k.due_at at time zone 'UTC', 'YYYYMMDD'), ledger.label(k.compartments), null::text,
      s.about_kind, s.about_id, s.source_kind, s.source_id, k.valid_from, k.due_at, null::integer, null::integer
    from knowledge.claims k
    cross join lateral (
      (select 'message'::text as about_kind, m.id as about_id, 'message'::text as source_kind, m.id as source_id
       from knowledge.messages m
       where m.evidence_id = k.evidence_id and not m.held and m.compartments <@ k.compartments)
      union all
      (select 'event'::text, v.id, 'event'::text, v.id
       from knowledge.events v where v.evidence_id = k.evidence_id and v.compartments <@ k.compartments)
      union all
      (select 'entity'::text, x.entity_id, 'capture'::text, cp.id
       from knowledge.captures cp
       cross join lateral (select n.entity_id from knowledge.claim_entities n
                           join knowledge.entities e on e.id = n.entity_id and e.kind in ('person', 'organization')
                           where n.claim_id = k.id and n.compartments <@ k.compartments
                           order by e.kind = 'organization', n.entity_id collate "C" limit 1) x
       where cp.evidence_id = k.evidence_id and cp.compartments <@ k.compartments
         and not policy.vetoed(
           array(select 'entity'::text from knowledge.claim_entities n where n.claim_id = k.id and n.compartments <@ k.compartments
                 order by n.entity_id collate "C"),
           array(select n.entity_id from knowledge.claim_entities n where n.claim_id = k.id and n.compartments <@ k.compartments
                 order by n.entity_id collate "C"), 'research'))
      limit 1) s
    where k.type = 'commitment' and not k.closes and k.fact_key_fp ~ '^[0-9a-f]{64}$'
      and k.due_at > autonomy_gaps.at_time and k.due_at <= autonomy_gaps.due_until
      and not policy.is_restricted(k.compartments)
      and not exists (select 1 from knowledge.claims n
                      where n.fact_key_fp = k.fact_key_fp and n.compartments <@ k.compartments and n.id <> k.id
                        and (n.valid_from > k.valid_from or (n.valid_from = k.valid_from and n.id collate "C" > k.id collate "C")))
      and not exists (select 1 from knowledge.belief_rulings b
                      where b.fact_key_fp = k.fact_key_fp and b.verdict = 'veto' and b.lifted_at is null and b.compartments <@ k.compartments)
      and not coalesce((select t.ended from ledger.trigger_log t
                        where t.fact_key_fp = k.fact_key_fp and t.compartments <@ k.compartments and t.cause not in ('due', 'dropped')
                        order by t.id desc limit 1), false)
    union all
    select 'reply_owed'::text, m.id, ledger.label(m.compartments), null::text, 'message'::text, m.id, 'message'::text, m.id,
      m.sent_at, null::timestamptz, null::integer, null::integer
    from knowledge.messages m
    where m.direction = 'inbound' and not m.held and not m.bulk and m.auth <> 'fail'
      and m.thread_fp is not null and m.sender_fp is not null
      and m.sent_at >= autonomy_gaps.reply_from and m.sent_at <= autonomy_gaps.reply_until
      and not policy.is_restricted(m.compartments)
      and not exists (select 1 from knowledge.messages t
                      where t.thread_fp = m.thread_fp and t.id <> m.id and not t.held and t.compartments <@ m.compartments
                        and (t.sent_at > m.sent_at or (t.sent_at = m.sent_at and t.id collate "C" > m.id collate "C")))
      and (exists (select 1 from knowledge.contact_addresses a where a.value_fp = m.sender_fp and a.compartments <@ m.compartments)
           or exists (select 1 from knowledge.interaction_log s
                      join knowledge.contact_addresses a on a.entity_id = s.entity_id and a.compartments <@ m.compartments
                      where s.evidence_id = m.evidence_id and s.entity_role = 'sender' and s.compartments <@ m.compartments)
           or exists (select 1 from knowledge.interaction_log s
                      join knowledge.interaction_log o on o.entity_id = s.entity_id and o.direction = 'outbound' and o.entity_role = 'recipient'
                        and o.compartments <@ m.compartments
                      join knowledge.messages w on w.evidence_id = o.evidence_id and w.direction = 'outbound' and not w.held
                        and w.compartments <@ m.compartments
                      where s.evidence_id = m.evidence_id and s.entity_role = 'sender' and s.compartments <@ m.compartments))
      and exists (select 1 from knowledge.messages o
                  where o.thread_fp = m.thread_fp and o.direction = 'outbound' and not o.held
                    and o.compartments <@ m.compartments and o.sent_at < m.sent_at)
      and not exists (select 1 from knowledge.interaction_log s
                      join knowledge.interaction_log o on o.entity_id = s.entity_id and o.direction = 'outbound' and o.entity_role = 'recipient'
                        and o.compartments <@ m.compartments
                      join knowledge.messages w on w.evidence_id = o.evidence_id and w.direction = 'outbound' and not w.held
                        and w.compartments <@ m.compartments and w.sent_at > m.sent_at
                      where s.evidence_id = m.evidence_id and s.entity_role = 'sender' and s.compartments <@ m.compartments)
  ) c
  where not policy.vetoed(array[c.about_kind, c.source_kind], array[c.about_id, c.source_id], 'research')
  order by 1, 2, 3, 9, 8;
end
$_$;

CREATE FUNCTION ledger.basis_flagged(ref_kinds text[], ref_ids text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with refs as (
    select r.kind, r.id from unnest(basis_flagged.ref_kinds, basis_flagged.ref_ids) as r (kind, id)
  ),
  messages as (
    select r.id, m.held, m.evidence_id from refs r left join knowledge.messages m on m.id = r.id where r.kind = 'message'
  ),
  judged as (
    select w.evidence_id, w.withheld, w.screened
    from policy.withheld_items((select array_agg(m.evidence_id) from messages m where m.evidence_id is not null)) w
  )
  select exists (
      select 1 from messages m left join judged j on j.evidence_id = m.evidence_id
      where m.evidence_id is null or m.held or j.evidence_id is null or j.withheld or not j.screened)
    or exists (
      select 1 from refs r left join ledger.agent_writes a on a.id = r.id
      where r.kind = 'agent_record' and (a.id is null or a.flagged_at is not null))
$$;

CREATE FUNCTION ledger.batch_notice_current(notice_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce((select b.state = 'pending' from ledger.batch_notices b where b.id = batch_notice_current.notice_id), false)
$$;

CREATE FUNCTION ledger.begin_send(send_id text, ruling_id text, draft_id text, decision_id text, payload_fp text, request_id text, first_contact boolean, new_thread boolean, released text[], point text, point_version integer, definition_hash text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  d ledger.drafts%rowtype;
  v_found text;
  v_facts jsonb;
  v_stored jsonb;
  v_rows integer;
  v_card text;
  v_point text;
  v_fields jsonb;
begin
  if session_user <> 'pi_proxy' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if coalesce(begin_send.send_id, '') !~ '^snt_[0-9A-HJKMNP-TV-Z]{26}$' or coalesce(begin_send.ruling_id, '') !~ '^rul_[0-9A-HJKMNP-TV-Z]{26}$'
     or coalesce(begin_send.decision_id, '') !~ '^gdc_[0-9A-HJKMNP-TV-Z]{26}$' or coalesce(begin_send.request_id, '') !~ '^[A-Za-z0-9_-]{8,64}$'
     or coalesce(begin_send.payload_fp, '') !~ '^[0-9a-f]{64}$' or begin_send.first_contact is null or begin_send.new_thread is null
     or begin_send.released is null or cardinality(begin_send.released) > 1000 or array_position(begin_send.released, null) is not null
     or exists (select 1 from unnest(begin_send.released) as x (one)
                where x.one !~ '^[0-9a-f]{64}$' and x.one !~ '^con_[0-9A-HJKMNP-TV-Z]{26}:(phone|organization|title|birthday|link):[0-9]{0,6}$')
     or begin_send.point is null or begin_send.point not in ('send_clear', 'send_first_contact')
     or begin_send.point_version is null or coalesce(begin_send.definition_hash, '') !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_fields := coalesce((
    select jsonb_agg(jsonb_build_object('contact', split_part(x.one, ':', 1), 'field', split_part(x.one, ':', 2),
      'index', case when split_part(x.one, ':', 3) = '' then null else split_part(x.one, ':', 3)::integer end) order by x.n)
    from unnest(begin_send.released) with ordinality as x (one, n) where x.one ~ '^con_'), '[]'::jsonb);
  select dr.* into d from ledger.drafts dr where dr.id = begin_send.draft_id;
  perform ledger.lock_rows(array[begin_send.draft_id]
    || case when d.id is null then '{}'::text[]
       else array['send:' || d.source_account_id || ':' || d.body_fp || ':' || array_to_string(d.recipient_fps, ',')] end);
  select s.id into v_found from ledger.sent_messages s where s.created_by = 'owner' and s.request_id = begin_send.request_id;
  if v_found is not null then
    return v_found;
  end if;
  select dr.* into d from ledger.drafts dr where dr.id = begin_send.draft_id;
  if d.id is null then
    return null;
  end if;
  v_facts := ledger.gate_facts(d.id, 'send');

  if (v_facts #>> '{draft,tainted}')::boolean or d.payload_fp <> begin_send.payload_fp
     or not ((v_facts #>> '{draft,status}') = 'made'
             or ((v_facts #>> '{draft,disclosureOnly}')::boolean and cardinality(begin_send.released) > 0)) then
    return null;
  end if;
  if (v_facts #>> '{work,named}')::boolean
     and ((v_facts #>> '{work,tainted}')::boolean or not (v_facts #>> '{work,open}')::boolean or not (v_facts #>> '{work,go}')::boolean) then
    return null;
  end if;
  if (v_facts #>> '{basis,missing}')::integer > 0 or (v_facts #>> '{basis,tainted}')::integer > 0 or (v_facts #>> '{basis,flagged}')::integer > 0 then
    return null;
  end if;
  if (v_facts #>> '{sent,already}')::boolean or (v_facts ->> 'killSwitch')::boolean
     or (v_facts #>> '{recipients,vetoed}')::integer > 0 or (v_facts #>> '{about,vetoed}')::boolean then
    return null;
  end if;
  v_point := case when (v_facts #>> '{recipients,firstContact}')::integer > 0 then 'send_first_contact' else 'send_clear' end;
  if begin_send.point <> v_point
     or ((v_facts #>> '{recipients,firstContact}')::integer > 0 and not begin_send.first_contact)
     or ((v_facts #>> '{thread,isNew}')::boolean and not begin_send.new_thread) then
    return null;
  end if;
  select count(*), min(g.facts::text)::jsonb into v_rows, v_stored
  from ledger.gate_checks g
  where g.decision_id = begin_send.decision_id and g.phase = 'send' and g.created_by = 'owner' and g.draft_id = d.id
    and g.payload_fp = begin_send.payload_fp and g.passed and g.created_at >= now() - interval '60 seconds';
  if v_rows <> 9 or (select count(*) from ledger.gate_checks g where g.decision_id = begin_send.decision_id) <> 9
     or v_stored is distinct from jsonb_set(jsonb_set(v_facts, '{draft,ageSeconds}', '0'::jsonb), '{account,syncAgeSeconds}',
          case when v_facts #> '{account,syncAgeSeconds}' = 'null'::jsonb then 'null'::jsonb else '0'::jsonb end) then
    return null;
  end if;

  select c.id into v_card from ledger.cards c
  where c.kind = 'draft_waiting' and c.target_kind = 'draft' and c.target_id = d.id order by c.created_at desc, c.id collate "C" desc limit 1;
  insert into knowledge.owner_decisions (id, request_id, kind, target_kind, target_id, answer, card_id, batch, queue_depth, labels, details,
    decided_at, compartments)
  values (begin_send.ruling_id, begin_send.request_id, 'send', 'draft', d.id, 'clear', v_card, false,
    (select count(*) from ledger.cards c
     where (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) = 'pending'),
    '{}'::text[],
    jsonb_build_object('firstContact', begin_send.first_contact, 'newThread', begin_send.new_thread,
      'released', to_jsonb(array(select x.one from unnest(begin_send.released) with ordinality as x (one, n) where x.one ~ '^[0-9a-f]{64}$' order by x.n)))
    || case when v_fields = '[]'::jsonb then '{}'::jsonb else jsonb_build_object('releasedContacts', v_fields) end,
    now(), d.compartments);
  insert into ledger.sent_messages (id, request_id, created_by, compartments, draft_id, ruling_id, decision_id, source_account_id, recipient_fps,
    payload_fp, body_fp, begun_at)
  values (begin_send.send_id, begin_send.request_id, 'owner', d.compartments, d.id, begin_send.ruling_id, begin_send.decision_id,
    d.source_account_id, d.recipient_fps, d.payload_fp, d.body_fp, now());
  insert into ledger.decision_point_calls (id, request_id, created_by, compartments, point, version, definition_hash, rung, input_hash,
    output, effect, effect_class, escalated, card_id, subject_kind, subject_id)
  values ('dpc_' || substr(begin_send.send_id, 5), begin_send.request_id, 'owner', d.compartments, begin_send.point, begin_send.point_version,
    begin_send.definition_hash, 4,
    encode(sha256(convert_to(jsonb_build_object('draft', d.id, 'send', begin_send.send_id, 'point', begin_send.point,
      'firstContact', begin_send.first_contact, 'newThread', begin_send.new_thread, 'released', cardinality(begin_send.released))::text, 'UTF8')), 'hex'),
    'clear', case when begin_send.point = 'send_first_contact' then 'first_contact' else 'clear_external_move' end, 'external', false, v_card,
    'send', begin_send.send_id);
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  values ('send', begin_send.send_id, 'sending', now(), 'owner', d.compartments);
  return begin_send.send_id;
end
$_$;

CREATE FUNCTION ledger.bet_endings(p_since timestamp with time zone, p_at timestamp with time zone, p_within text[], p_client text) RETURNS TABLE(client_id text, bet_at timestamp with time zone, ending text, used_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with agents as (
    select k.id from policy.clients k where k.kind = 'agent' and (p_client is null or k.id = p_client)
  ),
  bets as (
    select a.id as client_id, o.id, o.bet_at,
      (select min(e.at) from ledger.record_events e
       where e.row_kind = 'opportunity' and e.row_id = o.id and e.event = 'done' and e.at <= p_at) as done_at
    from agents a
    join ledger.opportunities o on o.created_by = 'client:' || a.id
    where o.bet_at is not null and o.bet_at > p_since and o.bet_at <= p_at
      and o.tainted_at is null and o.compartments <@ p_within
  ),
  own as (
    select b.*,
      b.done_at is not null and b.done_at <= b.bet_at + interval '7 days' as finished,
      least(b.done_at + interval '7 days', p_at) as until,
      exists (select 1 from ledger.opportunity_decisions d
              where d.opportunity_id = b.id and d.decided_by = 'owner' and d.decision = 'no_go'
                and d.tainted_at is null and d.compartments <@ p_within
                and d.created_at >= b.bet_at and d.created_at <= p_at
                and (b.done_at is null or d.created_at <= b.done_at)) as refused,
      coalesce(array(
        select w.evidence_id from ledger.agent_writes w
        where w.client_id = b.client_id and w.refused_code is null and w.tainted_at is null
          and w.evidence_id is not null and w.compartments <@ p_within
          and w.created_at >= b.bet_at and w.created_at <= b.done_at
          and (w.opportunity_id = b.id
               or w.id in (select s.ref_id from ledger.basis s join ledger.moves m on m.id = s.row_id
                           where s.row_kind = 'move' and s.ref_kind = 'agent_record' and m.opportunity_id = b.id
                             and s.tainted_at is null and m.tainted_at is null and s.compartments <@ p_within))), '{}') as evidence
    from bets b
  ),
  facts as (
    select s.client_id, s.bet_at, s.done_at, s.finished, s.refused,
      j.answer as judged, j.decided_at as judged_at,
      (select min(d.decided_at) from knowledge.claims k join ledger.cards c on c.target_id = k.id
       join knowledge.owner_decisions d on d.card_id = c.id
       where k.evidence_id = any (s.evidence) and d.kind = 'answer' and d.answer = 'confirm'
         and d.tainted_at is null and d.compartments <@ p_within
         and not exists (select 1 from ledger.card_relays y where y.ruling_id = d.id)
         and d.decided_at > s.done_at and d.decided_at <= s.until) as confirmed_at
    from own s
    left join lateral (
      select d.answer, d.decided_at from knowledge.owner_decisions d
      join ledger.moves v on v.id = d.target_id
      where d.kind = 'result_eval' and d.target_kind = 'move' and v.opportunity_id = s.id and d.tainted_at is null
        and d.compartments <@ p_within and d.decided_at > s.done_at and d.decided_at <= s.until
        and d.answer in ('keep', 'not_useful')
      order by d.decided_at desc, d.id collate "C" desc limit 1) j on true
  )
  select f.client_id, f.bet_at,
    case
      when f.refused then 'unused'
      when f.finished and (f.judged = 'keep' or (f.judged is null and f.confirmed_at is not null)) then 'used'
      when f.judged = 'not_useful'
        or (not f.finished and p_at > f.bet_at + interval '7 days')
        or (f.finished and p_at > f.done_at + interval '7 days') then 'unused'
      else 'open'
    end,
    case when f.refused then null when f.judged = 'keep' then f.judged_at else f.confirmed_at end
  from facts f
$$;

CREATE FUNCTION ledger.bets_within(p_at timestamp with time zone, p_within text[], p_client text) RETURNS TABLE(client_id text, open integer, used integer, unused integer, placed integer, earned integer, taken_back integer, budget integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with agents as (
    select k.id from policy.clients k where k.kind = 'agent' and (p_client is null or k.id = p_client)
  ),
  ended as (
    select * from ledger.bet_endings(p_at - interval '28 days', p_at, p_within, p_client)
  ),
  tally as (
    select a.id,
      (select count(*)::integer from ended e where e.client_id = a.id and e.ending = 'open') as open,
      (select count(*)::integer from ended e where e.client_id = a.id and e.ending = 'used') as used,
      (select count(*)::integer from ended e where e.client_id = a.id and e.ending = 'unused') as unused,
      (select count(*)::integer from ended e where e.client_id = a.id and e.bet_at > p_at - interval '7 days') as placed,
      (select count(*)::integer from ended e
       where e.client_id = a.id and e.ending = 'used' and e.used_at > p_at - interval '7 days') as earned,
      (select count(*)::integer from ledger.card_relays y
       where y.client_id = a.id and y.reopened_at > p_at - interval '7 days' and y.reopened_at <= p_at
         and y.compartments <@ p_within) as taken_back
    from agents a
  )
  select t.id, t.open, t.used, t.unused, t.placed, t.earned, t.taken_back,
    least(10, greatest(1, 3 + t.earned - 2 * t.taken_back))
  from tally t
  order by t.id
$$;

CREATE FUNCTION ledger.board_holders(opportunity_ids text[]) RETURNS TABLE(opportunity_id text, holder text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('list_opportunities' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  return query
    select o.id, c.name
    from ledger.opportunities o
    join queue.leases l on l.resource_kind = 'opportunity' and l.resource_id = o.id and l.lease_until >= now()
    join policy.clients c on c.id = l.holder
    where o.id = any (board_holders.opportunity_ids) and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)
      and o.tainted_at is null
    order by o.id collate "C";
end
$$;

CREATE FUNCTION ledger.capture_erased(devices text[], capture_keys text[], compartments jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_written integer;
begin
  if coalesce(cardinality(capture_erased.devices), 0) <> coalesce(cardinality(capture_erased.capture_keys), 0)
     or jsonb_typeof(capture_erased.compartments) is distinct from 'array'
     or jsonb_array_length(capture_erased.compartments) <> coalesce(cardinality(capture_erased.capture_keys), 0)
     or exists (select 1 from unnest(capture_erased.devices, capture_erased.capture_keys) as x (device, capture_key)
                where x.device is null or x.capture_key is null or x.capture_key !~ '^(meeting|moment|block|task):[0-9A-HJKMNP-TV-Z]{26}$')
     or exists (select 1 from jsonb_array_elements(capture_erased.compartments) as c (v)
                where not coalesce(jsonb_typeof(c.v) = 'array' and jsonb_array_length(c.v) >= 1
                                   and not exists (select 1 from jsonb_array_elements(c.v) as y (z) where jsonb_typeof(y.z) <> 'string'), false)) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  insert into ledger.capture_erasures (client_id, capture_key, compartments)
  select d.mirror_client_id, x.capture_key, array(select distinct y.z collate "C" from jsonb_array_elements_text(c.v) as y (z) order by 1)
  from unnest(capture_erased.devices, capture_erased.capture_keys) with ordinality as x (device, capture_key, n)
  join jsonb_array_elements(capture_erased.compartments) with ordinality as c (v, n) on c.n = x.n
  join policy.lens_devices d on d.name = x.device
  order by x.n
  on conflict on constraint capture_erasures_key do nothing;
  get diagnostics v_written = row_count;
  return v_written;
end
$_$;

CREATE FUNCTION ledger.card_answer_settles(p_kind text, p_answer text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select coalesce((p_kind, p_answer) in (('reminder', 'done'), ('agent_claim', 'confirm'), ('agent_claim', 'reject')), false)
$$;

CREATE FUNCTION ledger.card_attempt_kinds() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select array['same_fact', 'shared_address', 'time_effort', 'reminder', 'tier_proposal', 'relation_audit', 'agent_claim']::text[]
$$;

CREATE FUNCTION ledger.card_gaps(at_time timestamp with time zone, wait_hours integer) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
begin
  if card_gaps.at_time is null or card_gaps.wait_hours is null or card_gaps.wait_hours not between 1 and 8760 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select 'card_question'::text, c.id, ledger.label(c.compartments), null::text, 'owner'::text, null::text, 'card'::text, c.id,
    c.created_at, null::timestamptz, null::integer, null::integer
  from ledger.cards c
  where c.kind = any (ledger.card_attempt_kinds()) and c.tainted_at is null and not policy.is_restricted(c.compartments)
    and c.created_at > card_gaps.at_time - make_interval(hours => card_gaps.wait_hours)
    and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1)
        in ('pending', 'deferred')
    and not exists (select 1 from ledger.card_answers a where a.card_id = c.id)
    and not exists (
      select 1 from ledger.opportunities o
      where o.gap_trigger = 'card_question' and o.gap_subject = c.id
        and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id order by r.id desc limit 1)
            not in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner'))
  order by c.id collate "C";
end
$$;

CREATE FUNCTION ledger.card_pattern(p_card text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select case c.kind
    when 'about_you' then 'about_you:' || (select k.type from knowledge.claims k where k.id = c.target_id)
    when 'agent_claim' then 'agent_claim:' || (select k.type from knowledge.claims k where k.id = c.target_id)
    when 'idea' then 'idea:' || (select h.kind from ledger.hypotheses h where h.id = c.target_id)
    when 'opportunity_decision' then 'opportunity_decision:' || (select o.kind from ledger.opportunities o where o.id = c.target_id)
    when 'same_person' then
      (select ledger.pair_shape(min(b.ref_id), max(b.ref_id)) from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id and b.ref_kind = 'entity')
    end
  from ledger.cards c where c.id = p_card
$$;

CREATE FUNCTION ledger.card_question(p_opportunity text) RETURNS TABLE(card_id text, kind text, options text[], target_kind text, target_id text, ref_kinds text[], ref_ids text[], own boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_keys text[];
  v_client text;
begin
  v_keys := policy.clearance_keys();
  select k.id into v_client from policy.current_client() k;
  return query
  select c.id, c.kind, c.options, c.target_kind, c.target_id,
    array(select b.ref_kind from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id and b.tainted_at is null and b.compartments <@ o.compartments
          and policy.label_key(b.compartments) = any (v_keys) order by b.id limit 50),
    array(select b.ref_id from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id and b.tainted_at is null and b.compartments <@ o.compartments
          and policy.label_key(b.compartments) = any (v_keys) order by b.id limit 50),
    coalesce(c.created_by = 'client:' || v_client
      or (c.kind = 'agent_claim' and c.target_kind = 'claim' and exists (
            select 1 from knowledge.claims kc join ledger.agent_writes w on w.evidence_id = kc.evidence_id
            where kc.id = c.target_id and w.client_id = v_client)), false)
  from ledger.opportunities o
  join ledger.cards c on c.id = o.gap_subject and c.tainted_at is null and c.compartments <@ o.compartments
  where o.id = p_opportunity and o.gap_trigger = 'card_question' and o.tainted_at is null
    and o.compartments <@ (select k.compartments from policy.current_client() k)
    and policy.label_key(o.compartments) = any (v_keys);
end
$$;

CREATE TABLE ledger.cards (
    id text NOT NULL,
    request_id text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by text NOT NULL,
    run_id text,
    kind text NOT NULL,
    target_kind text,
    target_id text,
    options text[] NOT NULL,
    expires_at timestamp with time zone,
    expires_after_days integer,
    case_key text,
    body_from text,
    tainted_at timestamp with time zone,
    body_enc jsonb,
    compartments text[] NOT NULL,
    match_fp text,
    CONSTRAINT cards_body_from_form CHECK ((body_from ~ '^[a-z][a-z0-9_]{0,31}$'::text)),
    CONSTRAINT cards_case_key CHECK ((length(case_key) <= 64)),
    CONSTRAINT cards_created_by_form CHECK ((created_by ~ '^(owner|reasoner|system:[a-z][a-z0-9_]*|client:cli_[0-9A-HJKMNP-TV-Z]{26})$'::text)),
    CONSTRAINT cards_expires_after_days CHECK (((expires_after_days >= 1) AND (expires_after_days <= 90))),
    CONSTRAINT cards_id_form CHECK ((id ~ '^crd_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT cards_kind_form CHECK ((kind ~ '^[a-z][a-z0-9_]{0,31}$'::text)),
    CONSTRAINT cards_match_fp_form CHECK ((match_fp ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT cards_one_expiry CHECK (((expires_at IS NULL) OR (expires_after_days IS NULL))),
    CONSTRAINT cards_options CHECK (((cardinality(options) >= 1) AND (cardinality(options) <= 6))),
    CONSTRAINT cards_request_id_form CHECK ((request_id ~ '^[A-Za-z0-9_-]{8,64}$'::text)),
    CONSTRAINT cards_target CHECK (((target_kind IS NULL) = (target_id IS NULL))),
    CONSTRAINT cards_target_kind_form CHECK ((target_kind ~ '^[a-z][a-z0-9_]{0,31}$'::text)),
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1))
);

ALTER TABLE ONLY ledger.cards FORCE ROW LEVEL SECURITY;

CREATE FUNCTION ledger.card_raised_by(c ledger.cards, p_client text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select c.created_by = 'client:' || p_client
    or (c.target_kind = 'opportunity' and exists (select 1 from ledger.opportunities t where t.id = c.target_id and t.created_by = 'client:' || p_client))
    or (c.target_kind = 'agent_record' and exists (select 1 from ledger.agent_writes w where w.id = c.target_id and w.client_id = p_client))
    or (c.target_kind = 'hypothesis' and exists (select 1 from ledger.hypotheses h where h.id = c.target_id and h.created_by = 'client:' || p_client))
    or (c.target_kind = 'claim' and exists (select 1 from knowledge.claims kc join ledger.agent_writes w on w.evidence_id = kc.evidence_id
                                            where kc.id = c.target_id and w.client_id = p_client))
$$;

CREATE FUNCTION ledger.card_relay_gaps(at_time timestamp with time zone, wait_hours integer) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
begin
  if card_relay_gaps.at_time is null or card_relay_gaps.wait_hours is null or card_relay_gaps.wait_hours not between 1 and 8760 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select 'card_relay'::text, c.id, ledger.label(c.compartments), null::text, 'owner'::text, null::text, 'card'::text, c.id,
    c.created_at, null::timestamptz, null::integer, null::integer
  from ledger.cards c
  where c.kind = any (ledger.card_relay_kinds())
    and c.created_at > card_relay_gaps.at_time - make_interval(hours => card_relay_gaps.wait_hours + 48)
    and ledger.card_relayable(c.id, card_relay_gaps.at_time, card_relay_gaps.wait_hours)
    and exists (
      select 1 from policy.work_settings s
      join policy.clients k on k.status = 'active' and k.kind = 'agent' and s.question_role = any (k.roles)
        and 'relay_card_answer' = any (k.tools) and 'work' = any (k.views) and c.compartments <@ k.compartments
        and not ledger.card_raised_by(c, k.id)
      where s.question_role is not null)
    and not exists (
      select 1 from ledger.opportunities o
      where o.gap_trigger = 'card_relay' and o.gap_subject = c.id
        and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id order by r.id desc limit 1)
            not in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner'))
  order by c.id collate "C";
end
$$;

CREATE FUNCTION ledger.card_relay_kinds() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select array['opportunity_decision', 'lesson', 'client_preference', 'owner_question', 'idea', 'about_you', 'same_fact', 'time_effort',
               'tier_proposal', 'agent_claim']::text[]
$$;

CREATE FUNCTION ledger.card_relay_never() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select array['draft_waiting', 'grant_suggestion', 'grant_lift_suggestion', 'research_request', 'goal_proposal',
               'question_rule']::text[]
$$;

CREATE FUNCTION ledger.card_relay_question(p_opportunity text) RETURNS TABLE(card_id text, kind text, options text[], target_kind text, target_id text, ref_kinds text[], ref_ids text[], compartments text[], body_enc jsonb, attempt_agent text, attempt_answer text, attempt_ref_kinds text[], attempt_ref_ids text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_keys text[];
begin
  v_keys := policy.clearance_keys();
  return query
  select c.id, c.kind, c.options, c.target_kind, c.target_id,
    array(select b.ref_kind from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id and b.tainted_at is null and b.compartments <@ o.compartments
          and policy.label_key(b.compartments) = any (v_keys) order by b.id limit 50),
    array(select b.ref_id from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id and b.tainted_at is null and b.compartments <@ o.compartments
          and policy.label_key(b.compartments) = any (v_keys) order by b.id limit 50),
    c.compartments, c.body_enc,
    a.client_name, a.answer,
    array(select b.ref_kind from ledger.basis b where b.row_kind = 'move' and b.row_id = a.move_id and b.tainted_at is null
            and b.compartments <@ o.compartments and policy.label_key(b.compartments) = any (v_keys) order by b.id limit 50),
    array(select b.ref_id from ledger.basis b where b.row_kind = 'move' and b.row_id = a.move_id and b.tainted_at is null
            and b.compartments <@ o.compartments and policy.label_key(b.compartments) = any (v_keys) order by b.id limit 50)
  from ledger.opportunities o
  join ledger.cards c on c.id = o.gap_subject and c.tainted_at is null and c.compartments <@ o.compartments
  left join lateral (select x.client_name, x.answer, x.move_id from ledger.card_answers x
                     join ledger.moves m on m.id = x.move_id and m.tainted_at is null
                     where x.card_id = c.id and x.compartments <@ o.compartments
                     order by x.created_at desc, x.id collate "C" desc limit 1) a on true
  where o.id = p_opportunity and o.gap_trigger = 'card_relay' and o.tainted_at is null
    and o.compartments <@ (select k.compartments from policy.current_client() k)
    and policy.label_key(o.compartments) = any (v_keys);
end
$$;

CREATE FUNCTION ledger.card_relay_routed(c ledger.cards) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select c.kind = any (ledger.card_relay_kinds())
    and (c.kind <> 'opportunity_decision'
         or (c.target_kind = 'opportunity' and exists (
               select 1 from ledger.opportunities t
               where t.id = c.target_id and t.tier = 'task' and t.tainted_at is null and t.gap_trigger is null
                 and (t.due_at is null or t.due_at >= c.created_at + make_interval(hours => 48)))))
    and not (c.kind = any (ledger.card_attempt_kinds()) and c.target_kind = 'opportunity'
             and exists (select 1 from ledger.opportunities t where t.id = c.target_id and t.gap_trigger is not null))
$$;

CREATE FUNCTION ledger.card_relayable(p_card text, at_time timestamp with time zone, wait_hours integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select exists (
    select 1 from ledger.cards c
    cross join lateral (select case when c.kind = any (ledger.card_attempt_kinds()) then wait_hours + 48 else wait_hours end as hours) w
    where c.id = p_card and c.tainted_at is null and not policy.is_restricted(c.compartments)
      and ledger.card_relay_routed(c)
      and c.created_at > at_time - make_interval(hours => w.hours)
      and (c.expires_at is null or c.expires_at >= c.created_at + make_interval(hours => w.hours))
      and (c.expires_after_days is null or c.expires_after_days * 24 >= w.hours)
      and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1)
          in ('pending', 'deferred')
      and not exists (select 1 from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id and r.by = 'owner')
      and not exists (select 1 from ledger.card_relays y where y.card_id = c.id)
      and (not (c.kind = any (ledger.card_attempt_kinds()))
           or ((c.created_at <= at_time - make_interval(hours => 48)
                or not exists (select 1 from ledger.opportunities ao
                               where ao.gap_trigger = 'card_question' and ao.gap_subject = c.id and ao.tainted_at is null
                                 and ao.compartments <@ c.compartments
                                 and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = ao.id
                                      order by r.id desc limit 1) in ('proposed', 'later', 'go', 'claimed')))
               and (c.created_at <= at_time - make_interval(mins => 15)
                    or exists (select 1 from ledger.opportunities ao
                               where ao.gap_trigger = 'card_question' and ao.gap_subject = c.id
                                 and ao.compartments <@ c.compartments)))))
$$;

CREATE FUNCTION ledger.card_rule_stop(p_kind text, p_target_kind text, p_target_id text, p_label text[]) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select r.id from ledger.question_rules r
  where r.status = 'confirmed' and r.kind = p_kind and r.kind <> 'same_person' and p_label <@ r.compartments
    and r.pattern = case p_kind
      when 'about_you' then 'about_you:' || (select k.type from knowledge.claims k where k.id = p_target_id and p_target_kind = 'claim')
      when 'agent_claim' then 'agent_claim:' || (select k.type from knowledge.claims k where k.id = p_target_id and p_target_kind = 'claim')
      when 'idea' then 'idea:' || (select h.kind from ledger.hypotheses h where h.id = p_target_id and p_target_kind = 'hypothesis')
      when 'opportunity_decision' then 'opportunity_decision:' || (select o.kind from ledger.opportunities o where o.id = p_target_id and p_target_kind = 'opportunity')
      end
  order by r.id collate "C" limit 1
$$;

CREATE FUNCTION ledger.card_unopened(card_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select exists (select 1 from ledger.cards c where c.id = card_unopened.card_id and c.created_by = 'system:identity')
    and not exists (select 1 from ledger.record_events e where e.row_kind = 'card' and e.row_id = card_unopened.card_id)
$$;

CREATE FUNCTION ledger.change_feed(p_keys text[], p_kinds text[], p_prints text[], p_ats timestamp with time zone[], p_complete boolean, p_after_at timestamp with time zone, p_after_key text, p_limit integer, p_computed boolean) RETURNS TABLE(signal_key text, kind text, print text, signal_at timestamp with time zone, logged_at text, ref_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_tools text[];
  v_at timestamptz;
  v_key text;
  v_last_at timestamptz;
  v_last_key text;
begin
  select c.id, c.compartments, c.tools into v_caller, v_clearance, v_tools from policy.current_client() c;
  if v_caller is null or not ('get_changes' = any (v_tools)) or policy.current_client_kind() is distinct from 'agent' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if cardinality(p_keys) is distinct from cardinality(p_kinds) or cardinality(p_keys) is distinct from cardinality(p_prints)
     or cardinality(p_keys) is distinct from cardinality(p_ats) or p_limit is null or p_limit not between 1 and 200 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtext('intelligence personal changes'), hashtext(v_caller));
  insert into ledger.change_log as l (client_id, signal_key, kind, print, signal_at, first_at, logged_at, compartments)
  select v_caller, n.key, n.kind, n.print, n.at, clock_timestamp(), clock_timestamp(), ledger.label(v_clearance)
  from unnest(p_keys, p_kinds, p_prints, p_ats) as n (key, kind, print, at)
  on conflict (client_id, signal_key) do update
    set print = excluded.print, kind = excluded.kind, signal_at = excluded.signal_at, logged_at = clock_timestamp()
    where l.print <> excluded.print;
  if p_complete then
    update ledger.change_log l set print = 'cleared', logged_at = clock_timestamp()
    where l.client_id = v_caller and l.print <> 'cleared' and l.kind not in ('write_back', 'message', 'work') and not (l.signal_key = any (p_keys));
  end if;
  if p_after_at is null then
    select c.logged_at, c.signal_key into v_at, v_key from ledger.change_cursors c where c.client_id = v_caller;
  else
    v_at := p_after_at;
    v_key := p_after_key;
  end if;
  select x.logged_at, x.signal_key into v_last_at, v_last_key from (
    select l.logged_at, l.signal_key from ledger.change_log l
    where l.client_id = v_caller and (v_at is null or (l.logged_at, l.signal_key collate "C") > (v_at, v_key collate "C"))
    order by l.logged_at, l.signal_key collate "C" limit p_limit) x
  order by x.logged_at desc, x.signal_key collate "C" desc limit 1;
  if v_last_key is not null then
    insert into ledger.change_cursors as c (client_id, logged_at, signal_key) values (v_caller, v_last_at, v_last_key)
    on conflict (client_id) do update set logged_at = excluded.logged_at, signal_key = excluded.signal_key;
  end if;
  if p_computed then
    insert into ledger.change_cursors as c (client_id, computed_at) values (v_caller, clock_timestamp())
    on conflict (client_id) do update set computed_at = excluded.computed_at;
  end if;
  return query
    select l.signal_key, l.kind, l.print, l.signal_at, l.logged_at::text, l.ref_id from ledger.change_log l
    where l.client_id = v_caller and (v_at is null or (l.logged_at, l.signal_key collate "C") > (v_at, v_key collate "C"))
    order by l.logged_at, l.signal_key collate "C" limit p_limit + 1;
end
$$;

CREATE FUNCTION ledger.changes_quick(p_after_at timestamp with time zone, p_after_key text, p_look_back interval DEFAULT NULL::interval) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_clearance text[];
  v_tools text[];
  v_keys text[];
  v_roles text[];
  v_name text;
  v_since timestamptz;
  v_computed timestamptz;
  v_at timestamptz;
  v_key text;
begin
  select c.id, c.compartments, c.tools into v_caller, v_clearance, v_tools from policy.current_client() c;
  if v_caller is null or not ('get_changes' = any (v_tools)) or policy.current_client_kind() is distinct from 'agent' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtext('intelligence personal changes'), hashtext(v_caller));
  v_keys := policy.clearance_keys();
  select k.roles, k.name into v_roles, v_name from policy.clients k where k.id = v_caller;
  select c.polled_at, c.computed_at, c.logged_at, c.signal_key into v_since, v_computed, v_at, v_key
  from ledger.change_cursors c where c.client_id = v_caller;
  v_since := coalesce(v_since - interval '10 minutes', now() - interval '7 days');
  if p_look_back is not null then
    v_since := greatest(v_since, now() - p_look_back);
  end if;

  insert into ledger.change_log as l (client_id, signal_key, kind, print, signal_at, first_at, logged_at, compartments, ref_id)
  select v_caller, 'sig_' || left(encode(sha256(convert_to('message' || m.id, 'UTF8')), 'hex'), 32), 'message',
    left(encode(sha256(convert_to(m.id, 'UTF8')), 'hex'), 32), m.created_at, clock_timestamp(), clock_timestamp(), ledger.label(v_clearance), m.id
  from ledger.agent_messages m
  where m.created_at > v_since and m.client_id <> v_caller
    and ledger.agent_message_visible(m, v_caller, v_clearance, v_roles, v_keys)
  on conflict (client_id, signal_key) do nothing;

  insert into ledger.change_log as l (client_id, signal_key, kind, print, signal_at, first_at, logged_at, compartments, ref_id)
  select v_caller, 'sig_' || left(encode(sha256(convert_to('work' || x.id, 'UTF8')), 'hex'), 32), 'work',
    left(encode(sha256(convert_to(x.at::text, 'UTF8')), 'hex'), 32), x.at, clock_timestamp(), clock_timestamp(), ledger.label(v_clearance), x.id
  from (
    select o.id, max(e.at) as at from ledger.record_events e join ledger.opportunities o on o.id = e.row_id
    where e.row_kind = 'opportunity' and e.event = 'go' and e.at > v_since and o.tainted_at is null
      and policy.label_key(e.compartments) = any (v_keys)
      and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)
      and o.created_by <> 'client:' || v_caller
      and (o.tier <> 'task' or ledger.route_of(o.id) = any (v_roles || v_name) or (ledger.route_of(o.id) is null and o.gap_trigger is null))
      and ledger.claimable_by(o.id, v_caller)
    group by o.id
  ) x
  on conflict (client_id, signal_key) do update
    set print = excluded.print, signal_at = excluded.signal_at, logged_at = clock_timestamp()
    where l.print <> excluded.print;

  insert into ledger.change_cursors as c (client_id, polled_at) values (v_caller, now())
  on conflict (client_id) do update set polled_at = excluded.polled_at;

  if p_after_at is not null then
    v_at := p_after_at;
    v_key := p_after_key;
  end if;
  return v_computed is null or v_computed < now() - interval '5 minutes'
    or exists (select 1 from ledger.signal_marks m where m.created_at > v_computed and m.client_id <> v_caller
               and m.tainted_at is null and m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys))
    or exists (select 1 from ledger.change_log l
               where l.client_id = v_caller and l.print <> 'cleared' and l.kind not in ('message', 'work')
                 and (v_at is null or (l.logged_at, l.signal_key collate "C") > (v_at, v_key collate "C")));
end
$$;

CREATE FUNCTION ledger.check_back_blocked(opportunity_ids text[]) RETURNS TABLE(opportunity_id text, blocked boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('list_opportunities' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  return query
    select o.id, exists (select 1 from queue.leases l
                         where l.resource_kind = 'opportunity' and l.resource_id = o.id
                           and l.preferred_until > now() and l.holder <> v_caller
                           and exists (select 1 from (select i.compartments from ledger.intentions i
                                                      where i.opportunity_id = o.id and i.kind = 'check_back' and i.client_id = l.holder
                                                      order by (select max(r.id) from ledger.record_events r
                                                                where r.row_kind = 'intention' and r.row_id = i.id and r.event = 'fired') desc nulls last,
                                                               i.created_at desc, i.id collate "C" desc
                                                      limit 1) x
                                       where x.compartments <@ v_clearance and policy.label_key(x.compartments) = any (v_keys)))
    from ledger.opportunities o
    where o.id = any (check_back_blocked.opportunity_ids) and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys) and o.tainted_at is null
    order by o.id collate "C";
end
$$;

CREATE FUNCTION ledger.check_back_holds(opportunity_id text, client_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select exists (
    select 1 from ledger.intentions i
    where i.opportunity_id = check_back_holds.opportunity_id and i.client_id = check_back_holds.client_id
      and i.kind = 'check_back' and i.hold and i.tainted_at is null
      and (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id order by r.id desc limit 1) = 'set')
$$;

CREATE FUNCTION ledger.check_restatement(claim_key text, record_evidence_id text, proposed text, reached text, matched_fact_key_fp text, decision_version integer) RETURNS TABLE(answer text, cleared boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  record_row record;
begin
  select w.id, w.client_id, w.compartments into record_row
  from ledger.agent_writes w where w.evidence_id = check_restatement.record_evidence_id;
  if not found then
    raise exception 'not an agent record' using errcode = '42501';
  end if;
  insert into ledger.restatement_checks (client_id, record_id, claim_key, answer, reached, matched_fact_key_fp, decision_version, checked_at, compartments)
  values (record_row.client_id, record_row.id, check_restatement.claim_key, check_restatement.proposed, check_restatement.reached,
          check_restatement.matched_fact_key_fp, check_restatement.decision_version, now(), record_row.compartments)
  on conflict on constraint restatement_checks_one_per_key do nothing;
  return query
    select r.answer, r.cleared_at is not null
    from ledger.restatement_checks r where r.claim_key = check_restatement.claim_key;
end
$$;

CREATE FUNCTION ledger.cite_claims(p_card text, p_claim_ids text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_n integer;
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
  insert into ledger.basis (row_kind, row_id, ref_kind, ref_id, evidence_id, source_class, owner_backed, compartments)
  select 'card', c.id, 'carry_claim', k.id, k.evidence_id, 'derived', false, c.compartments
  from ledger.cards c join knowledge.claims k on k.id = any (p_claim_ids)
  where c.id = p_card and c.kind = 'ruling_carry' and c.tainted_at is null
    and not exists (select 1 from ledger.basis b
                    where b.row_kind = 'card' and b.row_id = c.id and b.ref_kind = 'carry_claim' and b.ref_id = k.id)
  order by k.id collate "C";
  get diagnostics v_n = row_count;
  return v_n;
end
$$;

CREATE FUNCTION ledger.claim(opportunity_id text, assignment_id text, request_id text, session_id text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_author text;
  v_label text[];
  v_kind text;
  v_compartments text[];
  v_status text;
  v_holder text;
  v_until timestamptz;
  v_first timestamptz;
  v_intent text;
  v_decided text;
  v_result timestamptz;
  v_keys text[];
  v_tier text;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('claim_opportunity' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = claim.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  perform ledger.lock_rows(array(select o.id from ledger.opportunities o
                                 where o.id = claim.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)));

  if exists (select 1 from ledger.assignments a where a.created_by = v_author and a.request_id = claim.request_id) then
    return (select l.lease_until from ledger.assignments a
            join queue.leases l on l.resource_kind = 'opportunity' and l.resource_id = a.opportunity_id and l.holder = v_caller
            where a.created_by = v_author and a.request_id = claim.request_id);
  end if;
  if coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on' then
    return null;
  end if;
  if not ledger.claimable_by(claim.opportunity_id, v_caller) then
    return null;
  end if;
  if ledger.lapse_held_from(claim.opportunity_id, v_caller) then
    return null;
  end if;
  select o.kind, o.compartments, o.tier into v_kind, v_compartments, v_tier
  from ledger.opportunities o where o.id = claim.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys);
  v_status := (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = claim.opportunity_id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1);
  select l.holder, l.lease_until, l.first_taken_at into v_holder, v_until, v_first
  from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = claim.opportunity_id;
  v_decided := (select d.intent_id from ledger.opportunity_decisions d where d.opportunity_id = claim.opportunity_id and policy.label_key(d.compartments) = any (v_keys)
                order by d.id desc limit 1);
  select i.id into v_intent from policy.intents i
  where i.confirmed_at is not null and i.revoked_at is null and v_kind = any (i.opportunity_kinds)
    and (case when v_tier = 'task' then i.for_tasks
         else v_caller = any (i.client_ids)
           or (i.role is not null and i.id = v_decided and exists (select 1 from policy.clients k where k.id = v_caller and i.role = any (k.roles))) end)
  order by i.confirmed_at, i.id collate "C" limit 1;

  if v_status = 'claimed' and v_holder = v_caller and v_until >= now() then
    update queue.leases l set lease_until = greatest(l.lease_until, now() + interval '1800 seconds')
    where l.resource_kind = 'opportunity' and l.resource_id = claim.opportunity_id
    returning l.lease_until into v_result;
    return v_result;
  end if;
  insert into queue.leases as l (resource_kind, resource_id, holder, lease_until, first_taken_at, preferred_until)
  values ('opportunity', claim.opportunity_id, v_caller, now() + interval '1800 seconds', now(), null)
  on conflict (resource_kind, resource_id) do update
    set holder = excluded.holder, lease_until = excluded.lease_until, first_taken_at = excluded.first_taken_at, preferred_until = null
    where l.lease_until < now() or l.holder = excluded.holder
  returning l.lease_until into v_result;
  if v_result is null then
    return null;
  end if;
  if v_status = 'claimed' then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
    values ('opportunity', claim.opportunity_id, 'go', now(), 'system:lease', v_compartments, 'lease_expired');
  end if;
  insert into ledger.assignments (id, request_id, created_by, session_id, compartments, opportunity_id, client_id, intent_id)
  values (claim.assignment_id, claim.request_id, v_author, claim.session_id, v_label, claim.opportunity_id, v_caller,
          coalesce(case when v_tier = 'task' then null else v_decided end, v_intent));
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
  values ('opportunity', claim.opportunity_id, 'claimed', clock_timestamp(), v_author, v_compartments, claim.session_id);
  return v_result;
end
$$;

CREATE FUNCTION ledger.claimable_by(opportunity_id text, client_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_clearance text[];
  v_tools text[];
  v_views text[];
  v_roles text[];
  v_name text;
  v_keys text[];
  v_kind text;
  v_about_kind text;
  v_about_id text;
  v_tier text;
  v_trigger text;
  v_subject text;
  v_route text;
  v_status text;
  v_holder text;
  v_until timestamptz;
  v_first timestamptz;
  v_preferred timestamptz;
  v_next text;
  v_decided text;
begin
  select k.compartments, k.tools, k.views, k.roles, k.name into v_clearance, v_tools, v_views, v_roles, v_name
  from policy.clients k where k.id = claimable_by.client_id and k.status = 'active' and k.kind = 'agent';
  if v_clearance is null or not ('claim_opportunity' = any (v_tools)) or not ('work' = any (v_views)) then
    return false;
  end if;
  v_keys := ledger.keys_of(v_clearance);
  select o.kind, o.about_kind, o.about_id, o.tier, o.gap_trigger, o.gap_subject into v_kind, v_about_kind, v_about_id, v_tier, v_trigger, v_subject
  from ledger.opportunities o
  where o.id = claimable_by.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys) and o.tainted_at is null;
  if v_kind is null then
    return false;
  end if;
  if exists (select 1 from ledger.work_dependencies d
             join ledger.opportunities b on b.id = d.blocked_by and b.tainted_at is null
             where d.opportunity_id = claimable_by.opportunity_id and d.compartments <@ v_clearance and policy.label_key(d.compartments) = any (v_keys)
               and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = d.blocked_by
                    and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1)
                   in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner')) then
    return false;
  end if;
  if v_tier = 'task' then
    v_route := ledger.route_of(claimable_by.opportunity_id);
    if v_route is not null and not (v_route = any (v_roles) or v_route = v_name) then
      return false;
    end if;
  end if;
  v_status := (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = claimable_by.opportunity_id
               and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1);
  select l.holder, l.lease_until, l.first_taken_at, l.preferred_until into v_holder, v_until, v_first, v_preferred
  from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = claimable_by.opportunity_id;
  if policy.vetoed(
       case when v_about_kind = 'owner' then '{}'::text[] else array[v_about_kind] end
         || array(select b.ref_kind from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = claimable_by.opportunity_id order by b.id),
       case when v_about_kind = 'owner' then '{}'::text[] else array[v_about_id] end
         || array(select b.ref_id from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = claimable_by.opportunity_id order by b.id),
       v_kind) then
    return false;
  end if;
  v_next := (select p.stage from policy.stage_plan p
             where p.opportunity_kind = v_kind
               and not exists (select 1 from ledger.moves m where m.opportunity_id = claimable_by.opportunity_id and m.stage = p.stage and policy.label_key(m.compartments) = any (v_keys)
                               and (select r.event from ledger.record_events r where r.row_kind = 'move' and r.row_id = m.id and r.event <> 'reported' and policy.label_key(r.compartments) = any (v_keys)
                                    order by r.id desc limit 1) = 'done')
             order by p.ordinal limit 1);
  v_decided := (select d.intent_id from ledger.opportunity_decisions d where d.opportunity_id = claimable_by.opportunity_id
                and policy.label_key(d.compartments) = any (v_keys) order by d.id desc limit 1);
  if v_next is null or not exists (
       select 1 from policy.intents i
       where i.confirmed_at is not null and i.revoked_at is null and v_kind = any (i.opportunity_kinds)
         and (case when v_tier = 'task' then i.for_tasks
              else i.id = v_decided and (claimable_by.client_id = any (i.client_ids) or (i.role is not null and i.role = any (v_roles))) end)
         and exists (select 1 from policy.harness_modes h
                     where h.client_id = claimable_by.client_id and h.opportunity_kind = v_kind and h.stage = v_next and h.revoked_at is null
                       and (h.mode = 'act' or not coalesce((select p.internal from policy.stage_plan p where p.opportunity_kind = v_kind and p.stage = v_next), false)))) then
    return false;
  end if;
  if v_status = 'claimed' and v_holder = claimable_by.client_id and v_until >= now() then
    return true;
  end if;
  if v_trigger = 'same_person' and not exists (
       select 1 from ledger.identity_questions q
       where q.batch = v_subject and q.state = 'agents'
         and q.compartments <@ v_clearance and policy.label_key(q.compartments) = any (v_keys)
         and not exists (select 1 from ledger.identity_answers a
                         where a.question_id = q.id and a.client_id = claimable_by.client_id and a.evidence_fp = q.evidence_fp)) then
    return false;
  end if;
  if not (v_status = 'go' or (v_status = 'claimed' and v_until < now())) then
    return false;
  end if;
  if ledger.lapse_held_from(claimable_by.opportunity_id, claimable_by.client_id) then
    return false;
  end if;
  if v_preferred is not null and v_preferred > now() and v_holder <> claimable_by.client_id
     and exists (select 1 from (select i.compartments from ledger.intentions i
                                where i.opportunity_id = claimable_by.opportunity_id and i.kind = 'check_back' and i.client_id = v_holder
                                order by (select max(r.id) from ledger.record_events r
                                          where r.row_kind = 'intention' and r.row_id = i.id and r.event = 'fired') desc nulls last,
                                         i.created_at desc, i.id collate "C" desc
                                limit 1) x
                 where x.compartments <@ v_clearance and policy.label_key(x.compartments) = any (v_keys)) then
    return false;
  end if;
  return true;
end
$$;

CREATE FUNCTION ledger.close_commitment(session_id text, new_id text, request_id text, fact_fp text, ending text, evidence_ids text[], related_at timestamp with time zone, content_fp text, cites_fp text, compartments text[], body_enc jsonb, belief_label text[], support text[]) RETURNS TABLE(outcome text, record_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_name text;
  v_views text[];
  v_tools text[];
  v_clearance text[];
  v_keys text[];
  v_label text[];
  v_earlier record;
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'an append runs read committed' using errcode = '42501';
  end if;
  select c.id, c.name, c.views, c.tools into v_caller, v_name, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('close_commitment' = any (v_tools)) or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = close_commitment.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if close_commitment.fact_fp is null or close_commitment.fact_fp !~ '^[0-9a-f]{64}$'
     or close_commitment.ending is null or close_commitment.ending not in ('done', 'cancelled', 'released')
     or coalesce(cardinality(close_commitment.evidence_ids), 0) not between 1 and 10 or close_commitment.related_at is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_clearance := policy.client_clearance();
  v_keys := policy.clearance_keys();
  perform ledger.lock_rows(array['commitment ' || close_commitment.fact_fp]);

  select w.id, w.kind, w.content_fp, w.cites_fp into v_earlier
  from ledger.agent_writes w where w.client_id = v_caller and w.request_id = close_commitment.request_id;
  if found then
    if v_earlier.kind = 'close' and v_earlier.content_fp = close_commitment.content_fp and v_earlier.cites_fp = close_commitment.cites_fp then
      return query select 'replayed'::text, v_earlier.id;
    else
      return query select 'request_reused'::text, null::text;
    end if;
    return;
  end if;
  insert into policy.record_quota as q (client_id) values (v_caller)
  on conflict (client_id) do update set attempts = q.attempts + 1, updated_at = now();
  if (select count(*) from ledger.agent_writes w where w.client_id = v_caller and w.kind <> 'memory_change' and w.created_at > now() - interval '24 hours') >= 200 then
    return query select 'rate_limited'::text, null::text;
    return;
  end if;
  if close_commitment.compartments is distinct from policy.record_label() then
    return query select 'label_mismatch'::text, null::text;
    return;
  end if;
  if close_commitment.body_enc is null or not (jsonb_typeof(close_commitment.body_enc) = 'object' and close_commitment.body_enc ?& array['v', 'nonce', 'ciphertext', 'tag'] and (close_commitment.body_enc - array['v', 'nonce', 'ciphertext', 'tag']) = '{}'::jsonb
      and close_commitment.body_enc -> 'v' = '1'::jsonb and jsonb_typeof(close_commitment.body_enc -> 'nonce') = 'string' and jsonb_typeof(close_commitment.body_enc -> 'ciphertext') = 'string' and jsonb_typeof(close_commitment.body_enc -> 'tag') = 'string'
      and close_commitment.body_enc ->> 'nonce' <> '' and close_commitment.body_enc ->> 'tag' <> '' and close_commitment.body_enc ->> 'nonce' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' and close_commitment.body_enc ->> 'ciphertext' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' and close_commitment.body_enc ->> 'tag' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$') then
    return query select 'body_refused'::text, null::text;
    return;
  end if;
  if exists (select 1 from unnest(close_commitment.evidence_ids) as c (id)
             where not exists (select 1 from vault.evidence_items e where e.id = c.id)) then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = close_commitment.session_id
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return query select 'read_removed'::text, null::text;
    return;
  end if;
  if not policy.agent_closes_on() then
    return query select 'closes_off'::text, null::text;
    return;
  end if;
  if coalesce(cardinality(close_commitment.support), 0) between 1 and 500
     and array_position(close_commitment.support, null) is null
     and (select count(*) from knowledge.claims c
          where c.id = any (close_commitment.support) and c.fact_key_fp = close_commitment.fact_fp
            and c.compartments <@ v_clearance and policy.label_key(c.compartments) = any (v_keys))
         = (select count(distinct x) from unnest(close_commitment.support) as x) then
    v_label := (select ledger.label(array_agg(u.x)) from knowledge.claims c cross join lateral unnest(c.compartments) as u (x)
                where c.id = any (close_commitment.support));
  end if;
  if v_label is null or v_label is distinct from ledger.label(close_commitment.belief_label) then
    return query select 'unknown_commitment'::text, null::text;
    return;
  end if;
  if not (array(select c from unnest(v_clearance) c where not starts_with(c, 'agent:')) <@ v_label)
     or exists (select 1 from vault.evidence_items e where e.id = any (close_commitment.evidence_ids) and not (e.compartments <@ v_label)) then
    return query select 'label_wider'::text, null::text;
    return;
  end if;
  if exists (select 1 from ledger.agent_writes w
             where w.kind = 'close' and w.close_fact_fp = close_commitment.fact_fp and w.body_enc is not null
               and w.compartments <@ v_clearance and policy.label_key(w.compartments) = any (v_keys)
               and (w.evidence_id is null or not exists (select 1 from knowledge.claims c where c.evidence_id = w.evidence_id and policy.label_key(c.compartments) = any (v_keys)))
               and not exists (select 1 from ledger.commitment_reopens r where r.close_id = w.id)) then
    return query select 'already_closed'::text, null::text;
    return;
  end if;
  if exists (select 1 from unnest(close_commitment.evidence_ids) as e (id)
             where not exists (select 1 from ledger.read_log r where r.client_id = v_caller and r.bound @> array[e.id])) then
    return query select 'evidence_not_read'::text, null::text;
    return;
  end if;
  if exists (select 1 from ledger.commitment_reopens r
             where r.fact_fp = close_commitment.fact_fp and r.by = 'owner' and r.at >= close_commitment.related_at
               and r.compartments <@ v_clearance) then
    return query select 'reopened_by_owner'::text, null::text;
    return;
  end if;
  insert into ledger.agent_writes (id, client_id, client_name, session_id, request_id, tool, kind, compartments, writer_views, content_fp, cites_fp, cites,
    body_enc, close_fact_fp, close_ending)
  values (close_commitment.new_id, v_caller, v_name, close_commitment.session_id, close_commitment.request_id, 'close_commitment', 'close',
          policy.record_label(), v_views, close_commitment.content_fp, close_commitment.cites_fp, close_commitment.evidence_ids, close_commitment.body_enc,
          close_commitment.fact_fp, close_commitment.ending);
  return query select 'ok'::text, close_commitment.new_id;
end
$_$;

CREATE FUNCTION ledger.close_gap_flag(p_id text, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_row ledger.opportunities%rowtype;
  v_event text;
  v_unassigned boolean;
begin
  if p_id is null or p_at is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform ledger.lock_rows(array[p_id]);
  select o.* into v_row from ledger.opportunities o where o.id = p_id and o.gap_trigger is not null and o.tainted_at is null;
  if v_row.id is null then
    return false;
  end if;
  if (v_row.gap_trigger in ('close_no_tie', 'close_no_role', 'explore')) <> (session_user = 'pi_pipeline') then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if (select k.state from ledger.kill_switch k order by k.id desc limit 1) = 'on' then
    return false;
  end if;
  v_event := (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = p_id order by r.id desc limit 1);
  v_unassigned := v_row.gap_trigger in ('defect', 'defect_untriaged')
    and not exists (select 1 from policy.work_settings s where s.defect_role is not null);
  if v_event is null or v_event not in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner')
     or (exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = p_id and l.lease_until >= p_at)
         and not v_unassigned) then
    return false;
  end if;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'intention', i.id, 'cancelled', p_at, 'system:gaps', i.compartments
  from ledger.intentions i
  join queue.leases l on l.resource_kind = 'opportunity' and l.resource_id = i.opportunity_id and l.holder = i.client_id
  where i.opportunity_id = p_id and i.kind = 'check_back'
    and (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id order by r.id desc limit 1) = 'set';
  delete from queue.leases where resource_kind = 'opportunity' and resource_id = p_id;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
  values ('opportunity', p_id, 'withdrawn', p_at, 'system:gaps', v_row.compartments, case when v_unassigned then 'no_defect_role' end);
  return true;
end
$$;

CREATE FUNCTION ledger.close_improvement_cause(cause text, event_id text, request_id text, note_enc jsonb, closed_state text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_row ledger.improvements%rowtype;
  v_status text;
begin
  if close_improvement_cause.closed_state is not null and close_improvement_cause.closed_state !~ '^[a-z0-9_:.= -]{1,200}$' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform ledger.lock_rows(array['improvement cause ' || close_improvement_cause.cause]);
  select i.* into v_row from ledger.improvements i where i.cause = close_improvement_cause.cause;
  if v_row.id is null then
    return null;
  end if;
  select coalesce((select e.status from ledger.improvement_events e where e.improvement_id = v_row.id and e.event = 'status'
                   order by e.created_at desc, e.id collate "C" desc limit 1), 'open') into v_status;
  if v_status not in ('open', 'triaged', 'in_progress') then
    return null;
  end if;
  insert into ledger.improvement_events (id, improvement_id, request_id, created_by, compartments, event, status, note_enc)
  values (close_improvement_cause.event_id, v_row.id, close_improvement_cause.request_id, 'system:measure', v_row.compartments, 'status', 'done', close_improvement_cause.note_enc);
  if close_improvement_cause.closed_state is not null then
    update ledger.improvements i set cause_state = close_improvement_cause.closed_state where i.id = v_row.id;
  end if;
  return v_row.id;
end
$_$;

CREATE FUNCTION ledger.close_no_role_gaps(tiers text[], max_people integer, left_out text[], people jsonb) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer, members text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if close_no_role_gaps.tiers is null or cardinality(close_no_role_gaps.tiers) = 0 or array_position(close_no_role_gaps.tiers, null) is not null
     or close_no_role_gaps.max_people is null or close_no_role_gaps.max_people not between 1 and 150
     or close_no_role_gaps.left_out is null
     or close_no_role_gaps.people is null or jsonb_typeof(close_no_role_gaps.people) <> 'array' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select distinct on (r.entity_id, r.label)
    'close_no_role'::text, r.entity_id || '_' || md5(array_to_string(r.label, ',')), r.label, null::text,
    'entity'::text, r.entity_id, 'entity'::text, r.entity_id, r.at, null::timestamptz, null::integer, null::integer, r.members
  from (
    select w.entity_id, ledger.label(w.compartments) as label, w.at,
      array(select distinct m collate "C" from unnest(coalesce(w.members, '{}'::text[]) || w.entity_id) as m order by 1) as members,
      row_number() over (partition by ledger.label(w.audience)
                         order by array_position(close_no_role_gaps.tiers, w.tier), w.warmth desc, w.entity_id collate "C") as place
    from jsonb_to_recordset(close_no_role_gaps.people)
      as w (audience text[], entity_id text, members text[], tier text, tier_source text, warmth double precision, at timestamptz, compartments text[])
    join knowledge.entities e on e.id = w.entity_id and e.kind = 'person'
    where w.tier = any (close_no_role_gaps.tiers) and w.tier_source = 'owner' and cardinality(w.compartments) >= 1 and cardinality(w.audience) >= 1
      and not policy.is_restricted(w.audience) and not policy.is_restricted(w.compartments)
      and not exists (select 1 from knowledge.claim_entities ce
                      join knowledge.claims k on k.id = ce.claim_id
                      where k.type = 'role' and ce.entity_id = any (coalesce(w.members, '{}'::text[]) || w.entity_id)
                        and k.compartments <@ w.compartments and ce.compartments <@ w.compartments)
      and not policy.vetoed(array['entity'], array[w.entity_id], 'research')
      and w.entity_id || '_' || md5(array_to_string(ledger.label(w.compartments), ',')) <> all (close_no_role_gaps.left_out)
  ) r
  where r.place <= close_no_role_gaps.max_people
  order by r.entity_id, r.label, r.at desc;
end
$$;

CREATE FUNCTION ledger.close_no_tie_gaps(tiers text[], max_people integer, people jsonb) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer, members text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if close_no_tie_gaps.tiers is null or cardinality(close_no_tie_gaps.tiers) = 0 or array_position(close_no_tie_gaps.tiers, null) is not null
     or close_no_tie_gaps.max_people is null or close_no_tie_gaps.max_people not between 1 and 150
     or close_no_tie_gaps.people is null or jsonb_typeof(close_no_tie_gaps.people) <> 'array' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select distinct on (r.entity_id, r.label)
    'close_no_tie'::text, r.entity_id || '_' || md5(array_to_string(r.label, ',')), r.label, null::text,
    'entity'::text, r.entity_id, 'entity'::text, r.entity_id, r.at, null::timestamptz, null::integer, null::integer, r.members
  from (
    select w.entity_id, ledger.label(w.compartments) as label, w.at,
      array(select distinct m collate "C" from unnest(coalesce(w.members, '{}'::text[]) || w.entity_id) as m order by 1) as members,
      row_number() over (partition by ledger.label(w.audience)
                         order by array_position(close_no_tie_gaps.tiers, w.tier), w.warmth desc, w.entity_id collate "C") as place
    from jsonb_to_recordset(close_no_tie_gaps.people)
      as w (audience text[], entity_id text, members text[], tier text, tier_source text, warmth double precision, at timestamptz, compartments text[])
    join knowledge.entities e on e.id = w.entity_id and e.kind = 'person'
    where w.tier = any (close_no_tie_gaps.tiers) and cardinality(w.compartments) >= 1 and cardinality(w.audience) >= 1
      and not policy.is_restricted(w.audience) and not policy.is_restricted(w.compartments)
      and not exists (select 1 from knowledge.claim_entities ce
                      join knowledge.claims k on k.id = ce.claim_id
                      where k.type = 'owner_tie' and ce.entity_id = any (coalesce(w.members, '{}'::text[]) || w.entity_id)
                        and k.compartments <@ w.compartments and ce.compartments <@ w.compartments)
      and not policy.vetoed(array['entity'], array[w.entity_id], 'research')
  ) r
  where r.place <= close_no_tie_gaps.max_people
  order by r.entity_id, r.label, r.at desc;
end
$$;

CREATE FUNCTION ledger.close_replayed(request_id text) RETURNS TABLE(record_id text, content_fp text, cites_fp text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select w.id, w.content_fp, w.cites_fp from ledger.agent_writes w
  where w.client_id = (select c.id from policy.current_client() c) and w.request_id = close_replayed.request_id and w.kind = 'close'
$$;

CREATE FUNCTION ledger.close_work_watches() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  insert into ledger.work_watches (opportunity_id, created_by, kind, watch_key, account_id, until, compartments)
  select w.opportunity_id, 'system:work', w.kind, w.watch_key, w.account_id, c.at + interval '90 days', w.compartments
  from (select distinct on (n.row_id) n.row_id, n.at, n.event from new_rows n
        where n.row_kind = 'opportunity' order by n.row_id, n.id desc) c
  cross join lateral (
    select distinct on (x.kind, x.account_id, x.watch_key) x.opportunity_id, x.kind, x.watch_key, x.account_id, x.until, x.compartments
    from ledger.work_watches x where x.opportunity_id = c.row_id
    order by x.kind, x.account_id, x.watch_key, x.id desc) w
  where ledger.closes_work(c.event) and w.until is null;
  return null;
end
$$;

CREATE FUNCTION ledger.closes_work(event text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select closes_work.event in ('done', 'no_go', 'expired', 'withdrawn', 'outcome_met', 'outcome_not_met')
$$;

CREATE FUNCTION ledger.commitment_reopens_rechecks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if not policy.is_restricted(new.compartments) then
    insert into ledger.trigger_rechecks (fact_key_fp, cause, exact, compartments) values (new.fact_fp, ledger.trigger_cause('ruling'), false, new.compartments);
  end if;
  return null;
end
$$;

CREATE FUNCTION ledger.contact_candidates(draft_id text) RETURNS TABLE(contact_id text, compartments text[], facts_enc jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_reader boolean := session_user = 'pi_reader';
  v_caller text;
  v_clearance text[];
  v_keys text[];
  d ledger.drafts%rowtype;
begin
  if session_user not in ('pi_reader', 'pi_proxy') then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if v_reader then
    select c.id into v_caller from policy.current_client() c;
    v_clearance := policy.client_clearance();
    v_keys := policy.clearance_keys();
  end if;
  select dr.* into d from ledger.drafts dr where dr.id = contact_candidates.draft_id;
  if v_reader and (v_caller is null or d.id is null or d.created_by <> 'client:' || v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if d.id is null then
    return;
  end if;
  return query
    with owned as (
      select a.value_fp from knowledge.accounts a join knowledge.entities e on e.id = a.entity_id
      where e.kind = 'owner' and (not v_reader or policy.label_key(a.compartments) = any (v_keys))
    ),
    rulings as (
      select r.a_fp, r.b_fp from knowledge.identity_rulings r
      where r.verdict = 'same' and r.lifted_at is null and r.b_fp is not null
        and not exists (select 1 from owned o where o.value_fp = r.a_fp or o.value_fp = r.b_fp)
        and (not v_reader or (
          exists (select 1 from knowledge.accounts x join knowledge.entities p on p.id = x.entity_id and p.kind = 'person'
                  where x.value_fp = r.a_fp and x.compartments <@ v_clearance and policy.label_key(x.compartments) = any (v_keys))
          and exists (select 1 from knowledge.accounts y join knowledge.entities q on q.id = y.entity_id and q.kind = 'person'
                  where y.value_fp = r.b_fp and y.compartments <@ v_clearance and policy.label_key(y.compartments) = any (v_keys))))
    ),
    visible as (
      select k.id, k.compartments, k.facts_enc, k.address_fps from knowledge.contacts k
      where not v_reader or (k.compartments <@ v_clearance and policy.label_key(k.compartments) = any (v_keys))
    ),
    listing as (
      select v.id, v.address_fps from visible v
      where not exists (
        select 1 from unnest(d.recipient_fps) as r (fp)
        where not exists (select 1 from knowledge.contact_addresses ca where ca.contact_id = v.id and ca.value_fp = r.fp
                          and (not v_reader or policy.label_key(ca.compartments) = any (v_keys))))
    ),
    exempt as (
      select l.id from listing l where cardinality(l.address_fps) = 1
      union
      select l.id from listing l
      cross join lateral (
        with recursive grp (fp) as (
          select l.address_fps[1]
          union
          select case when r.a_fp = g.fp then r.b_fp else r.a_fp end
          from grp g join rulings r on r.a_fp = g.fp or r.b_fp = g.fp
        )
        select array_agg(g.fp) as fps from grp g
      ) j
      where cardinality(l.address_fps) > 1 and l.address_fps <@ j.fps
    )
    select v.id, v.compartments, v.facts_enc from visible v
    where not exists (select 1 from exempt x where x.id = v.id)
    order by v.id collate "C";
end
$$;

CREATE FUNCTION ledger.count_dream_merges(p_evidence_ids text[], p_address_fps text[], p_claim_keys text[]) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select count(*)::integer from ledger.dream_identity_candidates c
  left join ledger.identity_questions q on q.id = c.question_id
  where c.evidence_ids && coalesce(p_evidence_ids, '{}') or c.claim_keys && coalesce(p_claim_keys, '{}')
     or q.a_fp = any (coalesce(p_address_fps, '{}')) or q.b_fp = any (coalesce(p_address_fps, '{}'))
$$;

CREATE FUNCTION ledger.count_session_taint(p_tool text, p_code text, p_enforced boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_tools text[];
begin
  select c.id, c.tools into v_caller, v_tools from policy.current_client() c;
  if v_caller is null or p_tool is null or not (p_tool = any (v_tools)) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if p_code is null or p_code not in ('tainted_session', 'private_session') or p_enforced is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  insert into ledger.session_taint_counts as s (client_id, day, tool, code, enforced, count)
  values (v_caller, (now() at time zone 'utc')::date, p_tool, p_code, p_enforced, 1)
  on conflict (client_id, day, tool, code, enforced) do update set count = s.count + 1;
end
$$;

CREATE FUNCTION ledger.deadline_gaps(at_time timestamp with time zone, until_time timestamp with time zone, max_minutes integer) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if deadline_gaps.at_time is null or deadline_gaps.until_time is null or deadline_gaps.until_time < deadline_gaps.at_time
     or deadline_gaps.max_minutes is null or deadline_gaps.max_minutes not between 0 and 240 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select 'deadline_soon'::text, v.id, ledger.label(v.compartments), null::text, 'event'::text, v.id, 'event'::text, v.id,
    d.starts_at, d.starts_at, null::integer, null::integer
  from knowledge.events v
  join knowledge.event_details d on d.event_id = v.id and d.compartments <@ v.compartments
  where not d.cancelled and coalesce(d.owner_response, 'accepted') <> 'declined' and not coalesce(d.recurring, false)
    and d.starts_at > deadline_gaps.at_time and d.starts_at <= deadline_gaps.until_time
    and not policy.is_restricted(v.compartments)
    and ((d.all_day and d.ends_at <= d.starts_at + interval '1 day')
         or (not d.all_day and d.ends_at <= d.starts_at + make_interval(mins => deadline_gaps.max_minutes)
             and not exists (select 1 from knowledge.event_participants p
                             join knowledge.entities e on e.id = p.entity_id and e.kind = 'person'
                             where p.event_id = v.id and p.compartments <@ v.compartments)))
    and not policy.vetoed(array['event', 'event'], array[v.id, v.id], 'research')
  order by d.starts_at, v.id;
end
$$;

CREATE FUNCTION ledger.declined_by_caller(opportunity_ids text[]) RETURNS TABLE(opportunity_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select d.opportunity_id from ledger.work_declines d
  where d.opportunity_id = any (declined_by_caller.opportunity_ids) and d.expires_at > now()
    and d.client_id = (select c.id from policy.current_client() c)
$$;

CREATE FUNCTION ledger.default_improvement_role() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  new.assignee_role := (select s.defect_role from policy.work_settings s
                        where exists (select 1 from policy.clients k
                                      where k.status = 'active' and k.kind = 'agent' and s.defect_role = any (k.roles)
                                        and new.compartments <@ k.compartments));
  return new;
end
$$;

CREATE FUNCTION ledger.default_task_role() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  new.role := (select s.default_task_role from policy.work_settings s
               where exists (select 1 from policy.clients k
                             where k.status = 'active' and k.kind = 'agent' and s.default_task_role = any (k.roles)
                               and new.compartments <@ k.compartments));
  return new;
end
$$;

CREATE FUNCTION ledger.defect_gaps(at_time timestamp with time zone, stale_hours integer) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
begin
  if defect_gaps.at_time is null or defect_gaps.stale_hours is null or defect_gaps.stale_hours not between 1 and 8760 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  with seen as (
    select i.id, i.created_by = 'system:measure' as filed_by_system, ledger.label(i.compartments) as label,
      coalesce(s.status, 'open') as status, coalesce(s.created_at, i.created_at) as since,
      coalesce(s.fix_ref = 'none:owners_to_change', false) as owners,
      case i.severity when 'critical' then 0 when 'high' then 1 when 'medium' then 2 else 3 end as rank,
      coalesce(i.assignee_role, '') as role, i.created_at as filed_at,
      (select count(*) from ledger.improvement_events e
       where e.improvement_id = i.id and e.event = 'status' and e.status = 'open' and e.created_by = 'system:measure') as openings,
      coalesce((select max(e.created_at) from ledger.improvement_events e
                where e.improvement_id = i.id and e.event = 'status' and e.status = 'open' and e.created_by = 'system:measure'),
               i.created_at) as opened_at
    from ledger.improvements i
    left join lateral (
      select e.status, e.created_at, e.fix_ref from ledger.improvement_events e
      where e.improvement_id = i.id and e.event = 'status' and e.tainted_at is null and e.compartments <@ i.compartments
      order by e.created_at desc, e.id collate "C" desc limit 1
    ) s on true
    where i.tainted_at is null and not policy.is_restricted(i.compartments)
      and exists (select 1 from policy.work_settings w where w.defect_role is not null)
  ),
  flags as (
    select o.id as flag, o.gap_source as defect, o.gap_subject as subject, o.created_at as raised_at, l.event, l.at,
      l.event = 'withdrawn' and l.code is not distinct from 'no_defect_role' as unassigned,
      l.event in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner') as live,
      exists (select 1 from ledger.opportunity_decisions d
              where d.opportunity_id = o.id and d.decision = 'no_go' and d.decided_by = 'owner') as owner_no
    from ledger.opportunities o
    cross join lateral (select r.event, r.at, r.code from ledger.record_events r
                        where r.row_kind = 'opportunity' and r.row_id = o.id order by r.id desc limit 1) l
    where o.gap_trigger = 'defect'
  ),
  system as (
    select x.*, v.subject as live_subject, v.event as live_event, v.flag as live_flag,
      (select count(*) from flags f where f.defect = x.id and not f.live and f.raised_at >= x.opened_at) as ended,
      (select count(*) from flags f where f.defect = x.id and not f.live and not f.unassigned and f.raised_at >= x.opened_at) as waited,
      exists (select 1 from flags f where f.defect = x.id and f.owner_no and f.raised_at >= x.opened_at) as owner_no,
      z.event as last_event, z.at as last_at
    from seen x
    left join lateral (select f.subject, f.event, f.flag from flags f where f.defect = x.id and f.live
                       order by f.raised_at desc, f.flag collate "C" desc limit 1) v on true
    left join lateral (select f.event, f.at from flags f where f.defect = x.id and not f.live and not f.unassigned and f.raised_at >= x.opened_at
                       order by f.at desc, f.flag collate "C" desc limit 1) z on true
    where x.filed_by_system and x.status in ('open', 'triaged', 'in_progress') and not x.owners
      and x.role <> ''
  ),
  wanted as (
    select y.*,
      y.live_subject is not null and (y.live_event <> 'go' or ledger.work_held(y.live_flag, defect_gaps.at_time)) as kept,
      case when y.live_subject is not null then y.live_subject
           when y.ended = 0 then y.id || '_' || y.openings
           else y.id || '_' || ((y.openings + 1) * 1000000 + least(y.ended, 999999)) end as subject
    from system y
    where y.live_subject is not null
       or (not y.owner_no
           and (y.waited = 0
                or defect_gaps.at_time >= y.last_at + case when y.last_event = 'done' or y.waited > 1 then interval '14 days'
                                                           else interval '7 days' end))
  ),
  ranked as (
    select w.*,
      count(*) filter (where w.kept) over (partition by w.role, w.label) as held,
      row_number() over (partition by w.role, w.label, w.kept order by w.rank, w.filed_at, w.id collate "C") as place
    from wanted w
  ),
  gaps as (
    select 'defect'::text as trigger, r.subject, r.label, r.id, r.since
    from ranked r where r.kept or r.place <= 5 - r.held
    union all
    select 'defect_untriaged'::text, x.id, x.label, x.id, x.since
    from seen x where not x.filed_by_system and x.status = 'open'
      and x.since <= defect_gaps.at_time - make_interval(hours => defect_gaps.stale_hours)
      and not exists (
        select 1 from ledger.opportunities o
        where o.gap_trigger = 'defect_untriaged' and o.gap_subject = x.id
          and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id order by r.id desc limit 1)
              not in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner'))
  )
  select g.trigger, g.subject, g.label, null::text, 'owner'::text, null::text, 'improvement'::text, g.id,
    g.since, null::timestamptz, null::integer, null::integer
  from gaps g
  order by g.trigger, g.subject collate "C";
end
$$;

CREATE FUNCTION ledger.draft_accounts(reply_to text, account_label text) RETURNS TABLE(id text, label text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select a.id, a.label
  from vault.source_accounts a
  where a.connector = 'google_mail'
    and exists (select 1 from policy.current_client())
    and a.compartments <@ policy.client_clearance()
    and (draft_accounts.account_label is null or a.label = draft_accounts.account_label)
    and (draft_accounts.reply_to is null or exists (
      select 1 from knowledge.messages m join vault.evidence_items e on e.id = m.evidence_id
      where m.id = draft_accounts.reply_to and e.source_account_id = a.id and not m.held
        and m.compartments <@ policy.client_clearance()))
  order by a.id collate "C"
$$;

CREATE FUNCTION ledger.dream_finding_brief(p_opportunity text) RETURNS TABLE(finding text, subject text, a_claim text, b_claim text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_keys text[];
  v_clearance text[];
begin
  v_keys := policy.clearance_keys();
  v_clearance := (select c.compartments from policy.current_client() c);
  return query
  select f.id, f.subject,
    (select v.claim_id from knowledge.claim_values v where v.claim_key = f.a_key and policy.label_key(v.compartments) = any (v_keys) order by v.claim_id collate "C" limit 1),
    (select v.claim_id from knowledge.claim_values v where v.claim_key = f.b_key and policy.label_key(v.compartments) = any (v_keys) order by v.claim_id collate "C" limit 1)
  from ledger.opportunities o join ledger.dream_findings f on f.id = o.gap_subject
  where o.id = p_opportunity and o.gap_trigger = 'dream_finding' and o.tainted_at is null
    and policy.label_key(o.compartments) = any (v_keys) and policy.label_key(f.compartments) = any (v_keys)
    and f.compartments <@ v_clearance;
end
$$;

CREATE FUNCTION ledger.dream_finding_gaps(at_time timestamp with time zone) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
begin
  if dream_finding_gaps.at_time is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select 'dream_finding'::text, f.id, ledger.label(f.compartments), null::text, 'entity'::text, f.subject, 'entity'::text, f.subject,
    f.created_at, null::timestamptz, null::integer, null::integer
  from ledger.dream_findings f
  where not policy.is_restricted(f.compartments) and f.created_at <= dream_finding_gaps.at_time
    and exists (select 1 from policy.gap_routes r where r.trigger = 'dream_finding')
    and not exists (select 1 from ledger.belief_settlements s where s.finding_id = f.id and s.lifted_at is null)
    and not exists (
      select 1 from ledger.opportunities o
      where o.gap_trigger = 'dream_finding' and o.gap_subject = f.id
        and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id order by r.id desc limit 1)
            not in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner')
        and not exists (select 1 from ledger.belief_settlements s where s.finding_id = f.id and s.lifted_at is not null and s.lifted_at > o.created_at))
  order by f.created_at, f.id collate "C";
end
$$;

CREATE FUNCTION ledger.dream_goal_subjects() RETURNS TABLE(entity_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select g.target_entity_id from projections.goal_state g
  where g.status = 'active' and g.target_entity_id is not null and not policy.is_restricted(g.compartments)
  union
  select p.id from knowledge.projects p where p.status = 'active' and not policy.is_restricted(p.compartments)
  union
  select e.entity_id from knowledge.project_bindings b
  join knowledge.projects p on p.id = b.project_id and p.status = 'active'
  join knowledge.claim_entities e on e.claim_id = b.claim_id
  where b.undone_at is null and not policy.is_restricted(b.compartments) and not policy.is_restricted(e.compartments)
$$;

CREATE FUNCTION ledger.dream_identity_pairs(p_judge text, p_limit integer) RETURNS TABLE(question text, a_entity text, b_entity text, compartments text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select q.id, q.a_entity, q.b_entity, q.compartments
  from ledger.identity_questions q
  where q.state in ('agents', 'owner', 'resting') and not policy.is_restricted(q.compartments)
    and not exists (select 1 from ledger.dream_identity_candidates c where c.question_id = q.id and c.judge = p_judge)
  order by q.created_at, q.id collate "C"
  limit greatest(0, least(coalesce(p_limit, 0), 10000))
$$;

CREATE FUNCTION ledger.dream_lift_merges(p_judge text, p_since timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_ruling text;
  v_n integer := 0;
begin
  perform ledger.lock_rows(array['identity:rulings']);
  for v_ruling in
    select c.ruling_id from ledger.dream_identity_candidates c
    join knowledge.identity_rulings r on r.ruling_id = c.ruling_id
    where c.judge = p_judge and c.state = 'merged' and r.lifted_at is null and r.created_at >= p_since
      and not exists (select 1 from knowledge.owner_decisions o
                      where o.kind = 'identity' and o.answer = 'same' and o.details -> 'affirms' ? r.ruling_id)
    order by c.id
  loop
    v_n := v_n + ledger.dream_lift_one(v_ruling);
  end loop;
  return v_n;
end
$$;

CREATE FUNCTION ledger.dream_lift_one(p_ruling text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_n integer;
begin
  update knowledge.identity_rulings set lifted_at = now(), lift_ruling_id = ruling_id, lifted_by_deletion = true
  where ruling_id = p_ruling and by_dream and lifted_at is null;
  get diagnostics v_n = row_count;
  update ledger.dream_identity_candidates set state = 'lifted', updated_at = now() where ruling_id = p_ruling and state = 'merged';
  update ledger.identity_questions q set state = 'agents', settled_by = null, batch = null, updated_at = now()
  from ledger.dream_identity_candidates c
  where c.ruling_id = p_ruling and q.id = c.question_id and q.state = 'settled';
  return v_n;
end
$$;

CREATE FUNCTION ledger.dream_ruling(p_candidate bigint, p_request text) RETURNS TABLE(code text, ruling text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_c ledger.dream_identity_candidates;
  v_q ledger.identity_questions;
  v_cards text[];
  v_owner text[];
  v_a_fps text[];
  v_b_fps text[];
  v_ga text[];
  v_gb text[];
  v_id text;
  v_fa text;
  v_fb text;
  v_on boolean;
begin
  perform ledger.lock_rows(array['identity:rulings', 'author:system:identity']);
  select d.id into v_id from knowledge.owner_decisions d where d.request_id = p_request and d.kind = 'identity_policy';
  if found then
    return query select 'ruled'::text, v_id;
    return;
  end if;
  select c.* into v_c from ledger.dream_identity_candidates c where c.id = p_candidate;
  if not found or v_c.verdict <> 'same' or v_c.state <> 'filed' then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  select q.* into v_q from ledger.identity_questions q where q.id = v_c.question_id;
  if not found then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  if not coalesce((select s.verdict = 'supported' and s.on_cited and s.live from ledger.source_checks s
                   where s.target = 'identity' and s.relation_id = v_c.id and starts_with(s.judge, 'model:')
                     and split_part(s.judge, '@', 1) <> split_part(v_c.judge, '@', 1)
                   order by s.created_at desc, s.id desc limit 1), false) then
    return query select 'unchecked'::text, null::text;
    return;
  end if;
  v_on := coalesce((select w.switched_on from policy.relation_switches w where w.kind = 'same_person' and w.judge = v_c.judge
                    order by (w.decided_by = 'owner') desc, w.decided_at desc, w.id desc limit 1), false);
  if not v_on then
    return query select 'kind_off'::text, null::text;
    return;
  end if;
  select coalesce(array_agg(c.id order by c.id), '{}') into v_cards
  from ledger.cards c
  where c.created_by = 'system:identity' and c.kind = 'same_person'
    and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) in ('pending', 'deferred')
    and exists (select 1 from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id and b.ref_id = v_q.a_entity)
    and exists (select 1 from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id and b.ref_id = v_q.b_entity);
  perform ledger.lock_rows(v_cards);

  select coalesce(array_agg(distinct a.value_fp), '{}') into v_owner
  from knowledge.accounts a join knowledge.entities e on e.id = a.entity_id where e.kind = 'owner';
  select coalesce(array_agg(distinct a.value_fp), '{}') into v_a_fps from knowledge.accounts a where a.entity_id = v_q.a_entity;
  select coalesce(array_agg(distinct a.value_fp), '{}') into v_b_fps from knowledge.accounts a where a.entity_id = v_q.b_entity;
  if cardinality(v_a_fps) = 0 or cardinality(v_b_fps) = 0 or v_a_fps && v_owner or v_b_fps && v_owner
     or (select count(*) from knowledge.entities e where e.id in (v_q.a_entity, v_q.b_entity) and e.kind = 'person') <> 2
     or exists (select 1 from knowledge.suppressions s where s.kind = 'address' and s.value_fp = any (v_a_fps || v_b_fps))
     or exists (select 1 from knowledge.accounts a where a.entity_id in (v_q.a_entity, v_q.b_entity) and a.kind <> 'email')
     or exists (select 1 from knowledge.identity_rulings r where r.verdict in ('role', 'shared') and r.lifted_at is null and r.a_fp = any (v_a_fps || v_b_fps)) then
    return query select 'not_a_person'::text, null::text;
    return;
  end if;
  with recursive g (fp) as (
    select unnest(v_a_fps)
    union
    select case when r.a_fp = g.fp then r.b_fp else r.a_fp end
    from knowledge.identity_rulings r join g on r.a_fp = g.fp or r.b_fp = g.fp
    where r.verdict = 'same' and r.lifted_at is null and r.b_fp is not null
  ) select array_agg(g.fp) into v_ga from g;
  with recursive g (fp) as (
    select unnest(v_b_fps)
    union
    select case when r.a_fp = g.fp then r.b_fp else r.a_fp end
    from knowledge.identity_rulings r join g on r.a_fp = g.fp or r.b_fp = g.fp
    where r.verdict = 'same' and r.lifted_at is null and r.b_fp is not null
  ) select array_agg(g.fp) into v_gb from g;
  if v_ga && v_gb then
    return query select 'already_settled'::text, null::text;
    return;
  end if;
  if exists (select 1 from knowledge.identity_rulings r
             where r.verdict = 'different' and r.lifted_at is null
               and ((r.a_fp = any (v_ga) and r.b_fp = any (v_gb)) or (r.a_fp = any (v_gb) and r.b_fp = any (v_ga)))) then
    return query select 'ruled_different'::text, null::text;
    return;
  end if;
  if exists (select 1 from knowledge.identity_rulings r
             where r.verdict = 'same' and r.lifted_at is not null and not r.lifted_by_deletion
               and ((r.a_fp = any (v_ga) and r.b_fp = any (v_gb)) or (r.a_fp = any (v_gb) and r.b_fp = any (v_ga)))) then
    return query select 'excepted'::text, null::text;
    return;
  end if;

  select min(x) into v_fa from unnest(v_a_fps) as x;
  select min(x) into v_fb from unnest(v_b_fps) as x;
  v_id := ledger.new_id('rul');
  insert into knowledge.owner_decisions (id, request_id, kind, answer, batch, queue_depth, details, decided_at, compartments)
  values (v_id, p_request, 'identity_policy', 'same', false,
          (select count(*) from ledger.cards c where (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) = 'pending'),
          jsonb_build_object('basis', 'dream', 'judge', v_c.judge, 'candidate', v_c.id), now(), v_q.compartments);
  insert into knowledge.identity_rulings (ruling_id, verdict, a_fp, b_fp, created_at, by_agent, by_dream)
  values (v_id, 'same', least(v_fa collate "C", v_fb collate "C"), greatest(v_fa collate "C", v_fb collate "C"), now(), false, true);
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'card', c.id, 'withdrawn', now(), 'system:identity', c.compartments
  from ledger.cards c where c.id = any (v_cards) order by c.id collate "C";
  perform ledger.admit_deferred('system:identity');
  update ledger.identity_questions q set state = 'settled', settled_by = 'ruling', batch = null, updated_at = now() where q.id = v_q.id;
  update ledger.dream_identity_candidates c set state = 'merged', ruling_id = v_id, code = null, updated_at = now() where c.id = v_c.id;
  return query select 'ruled'::text, v_id;
end
$$;

CREATE FUNCTION ledger.end_mirror(client_id text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_rows integer;
begin
  if end_mirror.client_id is null then
    raise exception 'end_mirror_client_id' using errcode = '23514', constraint = 'end_mirror_client_id';
  end if;
  perform pg_advisory_xact_lock(hashtext('intelligence personal ledger taint'));
  update ledger.mirror_entries m set ended_at = now(), reason = 'withdrawn'
  where m.client_id = end_mirror.client_id and m.ended_at is null;
  get diagnostics v_rows = row_count;
  return v_rows;
end
$$;

CREATE FUNCTION ledger.end_run(run_id text, outcome text, code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_status text;
  v_label text[];
begin
  perform ledger.lock_rows(array[end_run.run_id]);
  if end_run.outcome is null or end_run.outcome not in ('failed', 'stopped', 'queued')
     or (end_run.outcome = 'queued') <> (end_run.code is null) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_label := (select r.compartments from ledger.runs r where r.id = end_run.run_id);
  v_status := (select r.event from ledger.record_events r where r.row_kind = 'run' and r.row_id = end_run.run_id order by r.id desc limit 1);
  if v_label is null or v_status is null or v_status in ('finished', 'failed', 'stopped') or (end_run.outcome = 'queued' and v_status <> 'running') then
    return false;
  end if;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
  values ('run', end_run.run_id, end_run.outcome, now(), 'system:work', v_label, end_run.code);
  delete from queue.leases l where l.resource_kind = 'run' and l.resource_id = end_run.run_id;
  return true;
end
$$;

CREATE FUNCTION ledger.entity_seen(entity_id text, clearance text[], keys text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select exists (select 1 from knowledge.accounts a where a.entity_id = entity_seen.entity_id and a.compartments <@ entity_seen.clearance and policy.label_key(a.compartments) = any (entity_seen.keys))
      or exists (select 1 from knowledge.domains d where d.entity_id = entity_seen.entity_id and d.compartments <@ entity_seen.clearance and policy.label_key(d.compartments) = any (entity_seen.keys))
$$;

CREATE FUNCTION ledger.expect_gap_flag(p_opportunity_id text, p_type text, p_horizon_days integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_row ledger.opportunities%rowtype;
  v_subject_kind text;
  v_subject_id text;
begin
  if p_type is null or p_type not in ('answered', 'meeting_held', 'goal_claim')
     or p_horizon_days is null or p_horizon_days not between 1 and 365 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform ledger.lock_rows(array[p_opportunity_id]);
  select o.* into v_row from ledger.opportunities o
  where o.id = p_opportunity_id and o.created_by = 'system:gaps' and o.gap_trigger is not null and o.tainted_at is null
    and not exists (select 1 from ledger.expected_outcomes x where x.opportunity_id = o.id);
  if v_row.id is null or (p_type = 'goal_claim' and v_row.goal_id is null) then
    return 0;
  end if;
  v_subject_kind := case when p_type = 'goal_claim' then 'goal'
                         when v_row.about_kind in ('entity', 'event', 'goal') then v_row.about_kind
                         else 'counterpart' end;
  v_subject_id := case when p_type = 'goal_claim' then v_row.goal_id
                       when v_row.about_kind in ('entity', 'event', 'goal') then v_row.about_id end;
  insert into ledger.expected_outcomes (opportunity_id, ordinal, created_by, origin, subject_kind, subject_id, outcome_type, horizon_days, compartments)
  values (v_row.id, 0, 'system:gaps', 'default', v_subject_kind, v_subject_id, p_type, p_horizon_days, v_row.compartments);
  if v_subject_kind = 'entity' then
    insert into ledger.work_watches (opportunity_id, created_by, kind, watch_key, compartments)
    values (v_row.id, 'system:gaps', 'entity', v_subject_id, v_row.compartments);
  elsif v_row.about_kind = 'message' then
    insert into ledger.work_watches (opportunity_id, created_by, kind, watch_key, account_id, evidence_id, compartments)
    select v_row.id, 'system:gaps', 'thread', m.thread_fp, e.source_account_id, m.evidence_id,
      ledger.label(v_row.compartments || m.compartments || e.compartments)
    from knowledge.messages m join vault.evidence_items e on e.id = m.evidence_id
    where m.id = v_row.about_id and m.thread_fp is not null and not m.held;
  end if;
  return 1;
end
$$;

CREATE FUNCTION ledger.expire_agent_claims() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  expired integer;
begin
  perform ledger.lock_rows(array['author:system:extract']);
  with states as (
    select c.id, c.compartments, c.expires_at, c.expires_after_days,
      (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) as state,
      (select max(r.at) from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id and r.event = 'pending') as pending_at
    from ledger.cards c
    where c.created_by = 'system:extract' and c.kind in ('agent_claim', 'about_you', 'client_preference', 'time_effort')
  )
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'card', s.id, 'expired', now(), 'system:extract', s.compartments
  from states s
  where s.state = 'pending'
    and coalesce(s.expires_at, s.pending_at + make_interval(days => s.expires_after_days)) <= now()
  order by s.id collate "C";
  get diagnostics expired = row_count;
  perform ledger.admit_deferred('system:extract');
  return expired;
end
$$;

CREATE FUNCTION ledger.explore_gaps(at_time timestamp with time zone, named_hours integer, tiers jsonb) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer, goal_target boolean, goal_path boolean, goals text[], meeting_soon boolean, namer_tiers text[], named_days integer, missing text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if explore_gaps.at_time is null or explore_gaps.named_hours is null or explore_gaps.named_hours not between 1 and 336
     or explore_gaps.tiers is null or jsonb_typeof(explore_gaps.tiers) <> 'object' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select c.* from (
    select 'explore'::text, f.entity_id, array['own']::text[], f.goals[1], 'entity'::text, f.entity_id, 'entity'::text, f.entity_id,
      explore_gaps.at_time, null::timestamptz, f.edges, cardinality(f.namer_tiers),
      f.goal_target, f.goal_path, f.goals, f.meeting_soon, f.namer_tiers, f.named_days, f.missing
    from ledger.gap_frontier(array['own']::text[], explore_gaps.at_time, explore_gaps.named_hours, explore_gaps.tiers) f
  ) c (trigger, subject, label, goal_id, about_kind, about_id, source_kind, source_id, at, due_at, facts, ties, goal_target, goal_path,
       goals, meeting_soon, namer_tiers, named_days, missing)
  where not policy.vetoed(
    array[c.about_kind, c.source_kind] || case when c.goal_id is null then '{}'::text[] else array['goal'] end,
    array[c.about_id, c.source_id] || case when c.goal_id is null then '{}'::text[] else array[c.goal_id] end,
    'research')
  order by c.subject collate "C";
end
$$;

CREATE FUNCTION ledger.fall_back_pings(p_now timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_row record;
  v_dated integer;
  v_other integer;
  v_order text[];
  v_client text;
  v_self text;
  v_place integer;
  v_wrote integer := 0;
begin
  delete from ledger.batch_notices b where b.created_at < p_now - interval '30 days' and b.state <> 'pending';
  delete from ledger.change_log l where l.logged_at < p_now - interval '30 days' and (l.print = 'cleared' or l.kind in ('message', 'work', 'write_back'));
  select s.ping_order, s.ping_dated_minutes, s.ping_other_minutes into v_order, v_dated, v_other from policy.work_settings s;
  delete from ledger.ping_walks w
  where coalesce(cardinality(v_order), 0) = 0
     or not exists (select 1 from ledger.opportunities o where o.id = w.opportunity_id and o.tainted_at is null)
     or (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = w.opportunity_id order by r.id desc limit 1) is distinct from 'go';
  for v_row in
    select w.opportunity_id, w.rung, w.batched, o.tier, o.kind, o.role, o.compartments, o.created_by, o.gap_trigger
    from ledger.ping_walks w join ledger.opportunities o on o.id = w.opportunity_id
    where p_now >= w.told_at + make_interval(mins => case when o.due_at is not null then v_dated else v_other end)
                   - case when w.batched then interval '1 hour' else interval '0' end
  loop
    if v_row.rung = 0 and ledger.route_of(v_row.opportunity_id) is not null then
      if v_row.created_by = 'owner' or v_row.gap_trigger is not distinct from 'defect' then
        delete from ledger.ping_walks w where w.opportunity_id = v_row.opportunity_id;
      else
        insert into ledger.record_events (row_kind, row_id, event, at, "by", compartments, code, role)
        values ('opportunity', v_row.opportunity_id, 'routed', clock_timestamp(), 'system:fallback', v_row.compartments, 'other', null);
        insert into ledger.record_events (row_kind, row_id, event, at, "by", compartments)
        values ('opportunity', v_row.opportunity_id, 'go', clock_timestamp(), 'system:handoff', v_row.compartments);
        v_wrote := v_wrote + 1;
      end if;
      continue;
    end if;
    v_self := case when v_row.created_by like 'client:%' then substr(v_row.created_by, 8) end;
    v_place := ledger.ping_next_place(v_row.opportunity_id, v_self, v_row.rung);
    if v_place is null then
      delete from ledger.ping_walks w where w.opportunity_id = v_row.opportunity_id;
      continue;
    end if;
    perform ledger.ping_walk(v_row.opportunity_id, v_place, v_row.batched);
    for v_client in
      select t.client_id from ledger.ping_clients(v_row.opportunity_id, null, null, v_self, v_place) t
    loop
      insert into ledger.work_notices (id, client_id, opportunity_id, event, tier, kind, role, txid, ping_rung, batched, next_try_at)
      values (ledger.new_id('ntc'), v_client, v_row.opportunity_id, 'fallback', v_row.tier, v_row.kind, v_row.role, txid_current(), v_place, v_row.batched,
              case when v_row.batched then ledger.ping_batch_at(p_now) else p_now end)
      on conflict (client_id, opportunity_id, txid) do nothing;
      v_wrote := v_wrote + 1;
    end loop;
  end loop;
  if v_wrote > 0 then
    perform pg_notify('pi_work_notice', '');
  end if;
  return v_wrote;
end
$$;

CREATE FUNCTION ledger.file_improvement(id text, event_id text, request_id text, cause text, cause_state text, kind text, area text, severity text, compartments text[], title_fp text, title_enc jsonb, detail_enc jsonb, event_note_enc jsonb, measured_at timestamp with time zone) RETURNS TABLE(improvement_id text, action text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_row ledger.improvements%rowtype;
  v_status text;
  v_by text;
  v_at timestamptz;
begin
  perform ledger.lock_rows(array['improvement cause ' || file_improvement.cause]);
  select i.* into v_row from ledger.improvements i where i.cause = file_improvement.cause;
  if v_row.id is null then
    insert into ledger.improvements (id, request_id, created_by, compartments, kind, area, severity, title_fp, title_enc, detail_enc, cause, cause_state)
    values (file_improvement.id, file_improvement.request_id, 'system:measure', file_improvement.compartments, file_improvement.kind, file_improvement.area,
            file_improvement.severity, file_improvement.title_fp, file_improvement.title_enc, file_improvement.detail_enc, file_improvement.cause, file_improvement.cause_state);
    return query select file_improvement.id, 'filed'::text;
    return;
  end if;
  select e.status, e.created_by, e.created_at into v_status, v_by, v_at from ledger.improvement_events e
  where e.improvement_id = v_row.id and e.event = 'status'
  order by e.created_at desc, e.id collate "C" desc limit 1;
  v_status := coalesce(v_status, 'open');
  if v_status in ('wont_do', 'duplicate') and v_by = 'owner' then
    return query select v_row.id, 'vetoed'::text;
    return;
  end if;
  if v_status in ('done', 'wont_do', 'duplicate') then
    if file_improvement.measured_at <= v_at then
      return query select v_row.id, 'unchanged'::text;
      return;
    end if;
    insert into ledger.improvement_events (id, improvement_id, request_id, created_by, compartments, event, status, note_enc)
    values (file_improvement.event_id, v_row.id, file_improvement.request_id, 'system:measure', v_row.compartments, 'status', 'open', file_improvement.event_note_enc);
    update ledger.improvements i set cause_state = file_improvement.cause_state where i.id = v_row.id;
    return query select v_row.id, 'reopened'::text;
    return;
  end if;
  if v_row.cause_state is not distinct from file_improvement.cause_state then
    return query select v_row.id, 'unchanged'::text;
    return;
  end if;
  insert into ledger.improvement_events (id, improvement_id, request_id, created_by, compartments, event, note_enc)
  values (file_improvement.event_id, v_row.id, file_improvement.request_id, 'system:measure', v_row.compartments, 'reported', file_improvement.event_note_enc);
  update ledger.improvements i set cause_state = file_improvement.cause_state,
    severity = case when array_position(array['low', 'medium', 'high', 'critical'], file_improvement.severity)
                       > array_position(array['low', 'medium', 'high', 'critical'], i.severity) then file_improvement.severity else i.severity end
  where i.id = v_row.id;
  return query select v_row.id, 'reported'::text;
end
$$;

CREATE FUNCTION ledger.file_learning(id text, request_id text, session_id text, scope text, supersedes_id text, statement_fp text, statement_enc jsonb, rule_enc jsonb, evidence_enc jsonb) RETURNS TABLE(learning_id text, code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_roles text[];
  v_keys text[];
  v_author text;
  v_same text;
  v_vetoed boolean;
begin
  select c.client_id, c.clearance, c.roles into v_caller, v_clearance, v_roles
  from ledger.agent_mail_caller('file_learning', file_learning.session_id) c;
  if file_learning.id is null or file_learning.id !~ '^lrn_[0-9A-HJKMNP-TV-Z]{26}$'
     or file_learning.request_id is null or file_learning.request_id !~ '^[A-Za-z0-9_-]{8,64}$'
     or file_learning.scope is null or file_learning.scope !~ '^[a-z][a-z0-9-]{1,31}$'
     or (file_learning.scope <> 'general' and not (file_learning.scope = any (v_roles)))
     or file_learning.statement_fp is null or file_learning.statement_fp !~ '^[0-9a-f]{64}$'
     or file_learning.statement_enc is null or jsonb_typeof(file_learning.statement_enc) <> 'object'
     or file_learning.rule_enc is null or jsonb_typeof(file_learning.rule_enc) <> 'object'
     or file_learning.evidence_enc is null or jsonb_typeof(file_learning.evidence_enc) <> 'object' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  v_keys := policy.clearance_keys();
  perform ledger.lock_rows(array['learning ' || file_learning.statement_fp, 'learnings of ' || v_caller]);
  return query select l.id, 'ok'::text from ledger.agent_learnings l
    where l.created_by = v_author and l.request_id = file_learning.request_id;
  if found then
    return;
  end if;
  if file_learning.supersedes_id is not null and not exists (
       select 1 from ledger.agent_learnings l
       where l.id = file_learning.supersedes_id and l.tainted_at is null and l.retired_at is null
         and l.scope = file_learning.scope and l.created_by = v_author
         and l.compartments <@ v_clearance and policy.label_key(l.compartments) = any (v_keys)) then
    return query select null::text, 'not_found'::text;
    return;
  end if;
  select l.id, l.retired_at is not null into v_same, v_vetoed
  from ledger.agent_learnings l
  where l.statement_fp = file_learning.statement_fp and l.scope = file_learning.scope and l.tainted_at is null
    and l.compartments <@ v_clearance and policy.label_key(l.compartments) = any (v_keys)
    and (l.retired_at is not null
         or not exists (select 1 from ledger.agent_learnings n
                        where n.supersedes = l.id and n.tainted_at is null and n.retired_at is null
                          and n.compartments <@ v_clearance and policy.label_key(n.compartments) = any (v_keys)))
  order by (l.retired_at is null), l.created_at, l.id collate "C"
  limit 1;
  if v_same is not null then
    return query select v_same, case when v_vetoed then 'vetoed' else 'merged' end;
    return;
  end if;
  if (select count(*) from ledger.agent_learnings l where l.client_id = v_caller and l.created_at > now() - interval '24 hours') >= 10 then
    return query select null::text, 'rate_limited'::text;
    return;
  end if;
  insert into ledger.agent_learnings (id, request_id, created_by, client_id, session_id, compartments, scope,
    statement_fp, statement_enc, rule_enc, evidence_enc, supersedes)
  values (file_learning.id, file_learning.request_id, v_author, v_caller, file_learning.session_id, ledger.label(v_clearance),
          file_learning.scope, file_learning.statement_fp, file_learning.statement_enc, file_learning.rule_enc,
          file_learning.evidence_enc, file_learning.supersedes_id);
  return query select file_learning.id, 'ok'::text;
end
$_$;

CREATE FUNCTION ledger.file_research(session_id text, new_id text, request_id text, card_id text, kind text, template_id text, template_version integer, about_entity_id text, identifier_kinds text[], identifier_fps text[], message_id text, url_in_text boolean, query_fp text, source_item_fp text, compartments text[], body_enc jsonb) RETURNS TABLE(outcome text, research_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  caller text;
  caller_name text;
  caller_views text[];
  caller_tools text[];
  v_author text;
  v_keys text[];
  label text[];
  settings policy.research_settings;
  earlier record;
  i integer;
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'a filing runs read committed' using errcode = '42501';
  end if;
  select c.id, c.name, c.views, c.tools into caller, caller_name, caller_views, caller_tools from policy.current_client() c;
  if caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  select * into settings from policy.research_settings;
  if file_research.kind = 'link' and not settings.client_link_requests then
    return query select 'not_permitted'::text, null::text;
    return;
  end if;
  if not ('request_research' = any (caller_tools)) or not ('people' = any (caller_views)) then
    return query select 'not_permitted'::text, null::text;
    return;
  end if;
  label := ledger.label(array(select c from unnest(policy.client_clearance()) as c where c <> 'agent:' || caller_name));
  if cardinality(label) = 0 or not (label <@ array['own', 'public']) then
    return query select 'not_permitted'::text, null::text;
    return;
  end if;
  if file_research.compartments is distinct from label then
    raise exception 'not the token''s label' using errcode = '42501';
  end if;
  if not exists (select 1 from ledger.sessions s where s.id = file_research.session_id and s.client_id = caller) then
    raise exception 'not this client''s session' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if file_research.kind not in ('search', 'link') or file_research.query_fp is null
     or (file_research.kind = 'search' and (file_research.template_id is null or file_research.template_version is null or file_research.about_entity_id is null
         or cardinality(file_research.identifier_kinds) not between 1 and 3 or cardinality(file_research.identifier_kinds) <> cardinality(file_research.identifier_fps)
         or not (file_research.identifier_kinds <@ array['person_name', 'organization_name', 'domain'])))
     or (file_research.kind = 'link' and (file_research.message_id is null or file_research.source_item_fp is null))
     or file_research.body_enc is null or jsonb_typeof(file_research.body_enc) <> 'object'
     or not (file_research.body_enc ?& array['v', 'nonce', 'ciphertext', 'tag']) or (file_research.body_enc - array['v', 'nonce', 'ciphertext', 'tag']) <> '{}'::jsonb then
    return query select 'invalid_request'::text, null::text;
    return;
  end if;

  v_author := 'client:' || caller;
  perform pg_advisory_xact_lock(hashtextextended('author:' || v_author, 0));

  select r.id, r.kind, r.query_fp, r.about_entity_id, r.message_id into earlier
  from ledger.research_requests r where r.author = v_author and r.request_id = file_research.request_id;
  if found then
    if earlier.kind = file_research.kind and earlier.query_fp = file_research.query_fp
       and earlier.about_entity_id is not distinct from file_research.about_entity_id and earlier.message_id is not distinct from file_research.message_id then
      return query select 'replayed'::text, earlier.id;
    else
      return query select 'invalid_request'::text, null::text;
    end if;
    return;
  end if;

  if (select count(*) from ledger.cards c
      where c.created_by = v_author
        and (select e.event from ledger.record_events e
             where policy.label_key(e.compartments) = any (v_keys) and e.row_kind = 'card' and e.row_id = c.id order by e.id desc limit 1) = 'pending') >= 10
     or (select count(*) from ledger.research_requests r
         where r.client_id = caller and r.created_at >= date_trunc('day', now(), 'UTC')) >= settings.max_requests_per_client_per_day then
    return query select 'rate_limited'::text, null::text;
    return;
  end if;

  if file_research.kind = 'search' then
    if not exists (
      select 1 from knowledge.entities e
      where e.id = file_research.about_entity_id and e.kind in ('person', 'organization')
        and (exists (select 1 from knowledge.accounts a where policy.label_key(a.compartments) = any (v_keys) and a.entity_id = e.id and a.compartments <@ label)
             or exists (select 1 from knowledge.domains d where policy.label_key(d.compartments) = any (v_keys) and d.entity_id = e.id and d.compartments <@ label))) then
      return query select 'not_found'::text, null::text;
      return;
    end if;
    for i in 1 .. cardinality(file_research.identifier_kinds) loop
      if not (
        (file_research.identifier_kinds[i] in ('person_name', 'organization_name')
         and exists (select 1 from knowledge.aliases s
                     where policy.label_key(s.compartments) = any (v_keys)
                       and s.entity_id = file_research.about_entity_id and s.value_fp = file_research.identifier_fps[i] and s.compartments <@ label))
        or (file_research.identifier_kinds[i] = 'domain'
            and (exists (select 1 from knowledge.domains d
                         where policy.label_key(d.compartments) = any (v_keys)
                           and d.entity_id = file_research.about_entity_id and d.domain_fp = file_research.identifier_fps[i] and d.compartments <@ label)
                 or exists (select 1 from knowledge.accounts a
                            where policy.label_key(a.compartments) = any (v_keys)
                              and a.entity_id = file_research.about_entity_id and a.domain_fp = file_research.identifier_fps[i] and a.compartments <@ label)))) then
        return query select 'not_found'::text, null::text;
        return;
      end if;
    end loop;
  else
    if not exists (select 1 from knowledge.messages m
                   where policy.label_key(m.compartments) = any (v_keys)
                     and m.id = file_research.message_id and m.compartments <@ label and not m.held and not m.restricting)
       or file_research.url_in_text is not true then
      return query select 'not_found'::text, null::text;
      return;
    end if;
    if not exists (select 1 from knowledge.messages m
                   where policy.label_key(m.compartments) = any (v_keys) and m.id = file_research.message_id and m.compartments = array['own']
                     and exists (select 1 from knowledge.messages o
                                 where policy.label_key(o.compartments) = any (v_keys) and o.thread_fp = m.thread_fp and o.direction = 'outbound'))
       or exists (select 1 from ledger.research_requests r where r.client_id = caller and r.message_id = file_research.message_id) then
      return query select 'not_permitted'::text, null::text;
      return;
    end if;
  end if;

  insert into ledger.cards (id, request_id, created_at, created_by, kind, target_kind, target_id, options, expires_after_days, compartments)
  values (file_research.card_id, file_research.request_id, now(), v_author, 'research_request', 'research_request', file_research.new_id,
          array['approve', 'decline'], settings.card_expiry_days, label);
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  values ('card', file_research.card_id, 'pending', now(), v_author, label);
  insert into ledger.research_requests (id, request_id, created_at, author, client_id, session_id, kind, template_id, template_version,
    about_entity_id, message_id, card_id, query_fp, source_item_fp, body_enc, compartments)
  values (file_research.new_id, file_research.request_id, now(), v_author, caller, file_research.session_id, file_research.kind,
          case when file_research.kind = 'search' then file_research.template_id end,
          case when file_research.kind = 'search' then file_research.template_version end,
          case when file_research.kind = 'search' then file_research.about_entity_id end,
          case when file_research.kind = 'link' then file_research.message_id end,
          file_research.card_id, file_research.query_fp,
          case when file_research.kind = 'link' then file_research.source_item_fp end,
          file_research.body_enc, label);
  insert into ledger.record_events (row_kind, row_id, event, at, by, session_id, compartments)
  values ('research_request', file_research.new_id, 'filed', now(), v_author, file_research.session_id, label);
  return query select 'ok'::text, file_research.new_id;
end
$$;

CREATE FUNCTION ledger.finish_run(run_id text, request_id text, session_id text, end_outcome text, code text, point_version integer, definition_hash text, actions jsonb) RETURNS TABLE(recorded integer, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_status text;
  v_attempt integer;
  v_attempt_client text;
  v_label text[];
  v_session text;
  v_mark bigint;
  v_run_label text[];
  v_author text;
  v_wake_source text;
  v_wake_key text;
  v_count integer;
  a record;
  v_refs jsonb;
  v_case text;
  v_open text;
  v_subject_kind text;
  v_subject text;
  v_call text;
  v_effect text;
  v_goal text;
  v_hypothesis_new boolean;
  v_hypotheses jsonb := '{}'::jsonb;
  v_named boolean;
  v_auto boolean;
  v_keys text[];
  v_erased boolean;
  v_prompt text;
  v_idea text;
  v_rests text;
  v_trial text;
  v_lessons text[];
  v_decisions text[];
  v_count_cited integer;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('finish_run' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'reasoner'
     or not exists (select 1 from ledger.sessions s where s.id = finish_run.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if finish_run.end_outcome is null or finish_run.end_outcome not in ('finished', 'failed')
     or (finish_run.code is not null and finish_run.code not in (
       'turn_limit', 'tool_limit', 'bad_output', 'model_unavailable', 'context_limit', 'timeout', 'budget', 'kill_switch', 'erasure', 'withdrawn')) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'run:' || finish_run.run_id;
  perform ledger.lock_rows(array(select r.id from ledger.runs r
                                 where r.id = finish_run.run_id and r.compartments <@ v_clearance and policy.label_key(r.compartments) = any (v_keys)) || array(
    select 'case ' || k.row_kind || ' ' || coalesce(k.kind, '') || ' ' || coalesce(x ->> 'about_kind', '') || ' ' || coalesce(x ->> 'about_id', '')
           || ' ' || coalesce(policy.label_key(v_clearance), '')
    from jsonb_array_elements(case when jsonb_typeof(finish_run.actions) = 'array' then finish_run.actions else '[]'::jsonb end) as x
    cross join lateral (values
      ('intention', 'remind', x ->> 'do' = 'remind'),
      ('hypothesis', x ->> 'kind', x ->> 'do' = 'investigate'),
      ('opportunity', 'investigate', x ->> 'do' = 'investigate' and x ->> 'about_kind' is distinct from 'owner'),
      ('opportunity', x ->> 'kind', x ->> 'do' = 'propose')) as k (row_kind, kind, used)
    where k.used));

  select t.attempt, t.client_id, t.compartments, t.session_id, t.erasure_mark into v_attempt, v_attempt_client, v_label, v_session, v_mark
  from ledger.run_attempts t where t.run_id = finish_run.run_id order by t.attempt desc limit 1;
  select r.compartments, r.wake_source, r.wake_key, r.prompt_id, r.trial_model, r.lessons, r.decisions
    into v_run_label, v_wake_source, v_wake_key, v_prompt, v_trial, v_lessons, v_decisions
  from ledger.runs r where r.id = finish_run.run_id;
  v_status := (select e.event from ledger.record_events e where e.row_kind = 'run' and e.row_id = finish_run.run_id and policy.label_key(e.compartments) = any (v_keys) order by e.id desc limit 1);
  if v_status in ('finished', 'failed', 'stopped') and v_attempt_client = v_caller then
    return query select (select count(*)::integer from ledger.decision_point_calls d
                         where d.created_by = v_author and d.point = 'run_outcome'), v_status;
    return;
  end if;
  if v_attempt is null or v_attempt_client <> v_caller or v_status is distinct from 'running'
     or not exists (select 1 from queue.leases l where l.resource_kind = 'run' and l.resource_id = finish_run.run_id and l.holder = v_caller)
     or ledger.label(v_clearance) is distinct from v_label then
    return;
  end if;
  v_erased := exists (select 1 from knowledge.erasures x where (x.journal_seq > v_mark or x.lift_seq > v_mark)
                      and (x.touched is null or x.touched && v_clearance));
  if v_erased or coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on' then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
    values ('run', finish_run.run_id, 'stopped', now(), v_author, v_run_label,
            case when v_erased then 'erasure' else 'kill_switch' end);
    delete from queue.leases l where l.resource_kind = 'run' and l.resource_id = finish_run.run_id;
    return query select 0, 'stopped'::text;
    return;
  end if;
  if finish_run.end_outcome = 'failed' then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
    values ('run', finish_run.run_id, 'failed', now(), v_author, v_run_label, finish_run.code);
    delete from queue.leases l where l.resource_kind = 'run' and l.resource_id = finish_run.run_id;
    return query select 0, 'failed'::text;
    return;
  end if;

  if jsonb_typeof(finish_run.actions) is distinct from 'array' or jsonb_array_length(finish_run.actions) not between 1 and 100
     or exists (select 1 from jsonb_array_elements(finish_run.actions) x where jsonb_typeof(x) <> 'object')
     or (jsonb_array_length(finish_run.actions) > 1 and exists (select 1 from jsonb_array_elements(finish_run.actions) x where x ->> 'do' = 'ignore'))
     or finish_run.code is not null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = v_session and b.one ~ '^[0-9a-f]{64}$'
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return;
  end if;

  if v_trial is not null then
    if jsonb_array_length(finish_run.actions) <> 1 or finish_run.actions -> 0 ->> 'do' is distinct from 'trial'
       or jsonb_typeof(finish_run.actions -> 0 -> 'body_enc') is distinct from 'object' then
      raise exception 'invalid request' using errcode = '22023';
    end if;
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, body_enc)
    values ('run', finish_run.run_id, 'finished', clock_timestamp(), v_author, v_label, v_session, finish_run.actions -> 0 -> 'body_enc');
    delete from queue.leases l where l.resource_kind = 'run' and l.resource_id = finish_run.run_id;
    return query select 0, 'finished'::text;
    return;
  end if;

  if exists (select 1 from jsonb_array_elements(finish_run.actions) x
             where x ->> 'do' = 'lesson' and x ->> 'supersedes' is not null and not ((x ->> 'supersedes') = any (coalesce(v_lessons, '{}'::text[])))) then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
    values ('run', finish_run.run_id, 'failed', now(), v_author, v_run_label, 'bad_output');
    delete from queue.leases l where l.resource_kind = 'run' and l.resource_id = finish_run.run_id;
    return query select 0, 'failed'::text;
    return;
  end if;
  if exists (select 1 from jsonb_array_elements(finish_run.actions) x
             cross join lateral jsonb_array_elements_text(case when jsonb_typeof(x -> 'ref_kinds') = 'array' then x -> 'ref_kinds' else '[]'::jsonb end) with ordinality as k (kind, ord)
             where x ->> 'do' = 'lesson' and k.kind = 'decision'
               and not (coalesce(x -> 'ref_ids' ->> (k.ord::integer - 1), '') = any (coalesce(v_decisions, '{}'::text[])))) then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
    values ('run', finish_run.run_id, 'failed', now(), v_author, v_run_label, 'bad_output');
    delete from queue.leases l where l.resource_kind = 'run' and l.resource_id = finish_run.run_id;
    return query select 0, 'failed'::text;
    return;
  end if;
  if v_prompt = 'personal_lessons' and v_decisions is not null then
    v_label := v_run_label;
  end if;

  if v_prompt = 'personal_translate' then
    select h.id into v_idea from ledger.basis b join ledger.hypotheses h on h.id = b.ref_id
    where b.row_kind = 'run' and b.row_id = finish_run.run_id and b.ref_kind = 'hypothesis' and policy.label_key(b.compartments) = any (v_keys)
      and h.kind = 'idea' and h.tainted_at is null and policy.label_key(h.compartments) = any (v_keys)
    order by b.id limit 1;
  end if;

  v_count := 0;
  begin
    for a in
      select x."do", x.reason, x.kind, x.about_kind, x.about_id, x.due_at, x.ref_kinds, x.ref_ids, x.probability, x.probability_if_waiting,
             x.id, x.body_enc, x.opportunity_id, x.opportunity_body_enc, x.hypothesis_ord,
             x.applies_kinds, x.applies_roles, x.supersedes, e.ord
      from jsonb_array_elements(finish_run.actions) with ordinality as e (value, ord)
      cross join lateral jsonb_to_record(e.value) as x ("do" text, reason text, kind text, about_kind text, about_id text,
        due_at timestamptz, ref_kinds text[], ref_ids text[], probability real, probability_if_waiting real, id text, body_enc jsonb,
        opportunity_id text, opportunity_body_enc jsonb, hypothesis_ord integer,
        applies_kinds text[], applies_roles text[], supersedes text)
      order by e.ord
    loop
      v_count := v_count + 1;
      v_case := null;
      v_open := null;
      if a."do" is distinct from 'lesson' and (a.applies_kinds is not null or a.applies_roles is not null or a.supersedes is not null) then
        raise exception 'invalid request' using errcode = '22023';
      end if;
      if a."do" = 'ignore' then
        if a.reason is null or a.reason not in ('nothing_to_do', 'below_bar', 'waiting_is_better') then
          raise exception 'invalid request' using errcode = '22023';
        end if;
        insert into ledger.silences (request_id, created_by, run_id, session_id, compartments, reason, wake_source, wake_key, day)
        values ('ignore_' || substr(finish_run.run_id, 5), v_author, finish_run.run_id, v_session, v_label, a.reason, v_wake_source, v_wake_key,
                (now() at time zone 'UTC')::date);
        v_subject_kind := 'run';
        v_subject := finish_run.run_id;
        v_call := 'dpc_' || substr(finish_run.run_id, 5);
        v_effect := 'record_silence';
      elsif a."do" in ('remind', 'investigate', 'propose', 'idea', 'lesson') then
        if (a."do" in ('idea', 'lesson')) <> (coalesce(v_prompt, '') in ('personal_ideas', 'personal_lessons'))
           or v_prompt = 'personal_predict'
           or (a."do" = 'idea' and v_prompt <> 'personal_ideas') or (a."do" = 'lesson' and v_prompt <> 'personal_lessons')
           or (a."do" = 'idea' and a.about_kind = 'owner') or (a."do" = 'lesson' and a.about_kind is distinct from 'owner') then
          raise exception 'invalid request' using errcode = '22023';
        end if;
        if a.about_kind is null or a.about_kind not in ('owner', 'message', 'event', 'entity', 'goal') or (a.about_kind = 'owner') <> (a.about_id is null)
           or a.body_enc is null or coalesce(cardinality(a.ref_kinds), 0) not between 1 and 20
           or cardinality(a.ref_kinds) <> coalesce(cardinality(a.ref_ids), 0)
           or a.id is null or a.id !~ (case a."do" when 'remind' then '^itn_' when 'propose' then '^opp_' else '^hyp_' end)
           or (a."do" = 'remind' and a.due_at is null)
           or (a."do" = 'investigate' and (a.kind is null or a.kind not in ('open_loop', 'needs_preparation', 'at_risk', 'preference')))
           or (a."do" = 'investigate' and a.about_kind <> 'owner' and (a.opportunity_id is null or a.opportunity_id !~ '^opp_' or a.opportunity_body_enc is null))
           or (a."do" = 'propose' and (a.kind is null or a.kind not in ('follow_up', 'reply', 'meeting_prep', 'investigate', 'goal_step', 'life_admin', 'owner_question', 'introduction')))
           or (a."do" = 'propose' and a.kind = 'owner_question' and a.hypothesis_ord is null and v_prompt is distinct from 'personal_translate')
           or (a.hypothesis_ord is not null and (a."do" <> 'propose' or a.hypothesis_ord >= a.ord or not (v_hypotheses ? a.hypothesis_ord::text))) then
          raise exception 'invalid request' using errcode = '22023';
        end if;
        if not (case a.about_kind
            when 'owner' then true
            when 'message' then exists (select 1 from knowledge.messages m where m.id = a.about_id and m.compartments <@ v_label and policy.label_key(m.compartments) = any (v_keys) and not m.held)
            when 'event' then exists (select 1 from knowledge.events e where e.id = a.about_id and e.compartments <@ v_label and policy.label_key(e.compartments) = any (v_keys))
            when 'entity' then exists (select 1 from knowledge.accounts x where x.entity_id = a.about_id and x.compartments <@ v_label and policy.label_key(x.compartments) = any (v_keys))
              or exists (select 1 from knowledge.domains y where y.entity_id = a.about_id and y.compartments <@ v_label and policy.label_key(y.compartments) = any (v_keys))
            when 'goal' then exists (select 1 from projections.goal_state g where g.goal_id = a.about_id and g.compartments <@ v_label and policy.label_key(g.compartments) = any (v_keys))
            else false end) then
          raise exception 'a ref did not resolve' using errcode = 'PIW01';
        end if;
        v_goal := case when a.about_kind = 'goal' then a.about_id
          else (select r.id from unnest(a.ref_kinds, a.ref_ids) with ordinality as r (kind, id, ord) where r.kind = 'goal' order by r.ord limit 1) end;
        v_call := 'dpc_' || substr(a.id, 5);

        if a."do" = 'remind' then
          v_effect := 'set_intention';
          v_subject_kind := 'intention';
          select k.id into v_case from ledger.cases k
          where k.row_kind = 'intention' and k.kind = 'remind' and k.about_kind = a.about_kind and k.about_id is not distinct from a.about_id
            and k.author = 'run' and k.compartments = v_label and policy.label_key(k.compartments) = any (v_keys);
          if v_case is not null then
            select i.id into v_open from ledger.intentions i
            where i.case_id = v_case and policy.label_key(i.compartments) = any (v_keys) and i.tainted_at is null
              and (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) = 'set'
            order by i.created_at, i.id collate "C" limit 1;
          end if;
          if v_open is null then
            if v_case is null then
              v_case := 'cas_' || substr(a.id, 5);
              insert into ledger.cases (id, request_id, created_by, run_id, session_id, compartments, row_kind, kind, about_kind, about_id, author)
              values (v_case, v_case, v_author, finish_run.run_id, v_session, v_label, 'intention', 'remind', a.about_kind, a.about_id, 'run');
            end if;
            insert into ledger.intentions (id, request_id, created_by, run_id, session_id, compartments, body_enc, case_id, kind, due_at, chain_depth)
            values (a.id, a.id, v_author, finish_run.run_id, v_session, v_label, a.body_enc, v_case, 'remind', a.due_at, 0);
            insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
            values ('intention', a.id, 'set', now(), v_author, v_label, v_session);
            v_open := a.id;
          end if;
          v_subject := v_open;

        elsif a."do" = 'investigate' then
          v_effect := 'open_investigation';
          v_subject_kind := 'hypothesis';
          select k.id into v_case from ledger.cases k
          where k.row_kind = 'hypothesis' and k.kind = a.kind and k.about_kind = a.about_kind and k.about_id is not distinct from a.about_id
            and k.author = 'run' and k.compartments = v_label and policy.label_key(k.compartments) = any (v_keys);
          if v_case is not null then
            select h.id into v_open from ledger.hypotheses h
            where h.case_id = v_case and policy.label_key(h.compartments) = any (v_keys) and h.tainted_at is null
              and (select r.event from ledger.record_events r where r.row_kind = 'hypothesis' and r.row_id = h.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1)
                  in ('open', 'supported', 'asked')
            order by h.created_at, h.id collate "C" limit 1;
          end if;
          v_hypothesis_new := v_open is null;
          if v_hypothesis_new then
            if v_case is null then
              v_case := 'cas_' || substr(a.id, 5);
              insert into ledger.cases (id, request_id, created_by, run_id, session_id, compartments, row_kind, kind, about_kind, about_id, author)
              values (v_case, v_case, v_author, finish_run.run_id, v_session, v_label, 'hypothesis', a.kind, a.about_kind, a.about_id, 'run');
            end if;
            insert into ledger.hypotheses (id, request_id, created_by, run_id, session_id, compartments, body_enc, case_id, kind, about_kind, about_id, about_owner)
            values (a.id, a.id, v_author, finish_run.run_id, v_session, v_label, a.body_enc, v_case, a.kind, a.about_kind, a.about_id, a.about_kind = 'owner');
            insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
            values ('hypothesis', a.id, 'open', now(), v_author, v_label, v_session);
            v_open := a.id;
          end if;
          v_subject := v_open;
          if a.about_kind <> 'owner' then
            v_hypotheses := v_hypotheses || jsonb_build_object(a.ord::text, v_open);
          end if;
          v_named := exists (select 1 from jsonb_array_elements(finish_run.actions) x
                             where x ->> 'do' = 'propose' and x ->> 'hypothesis_ord' = a.ord::text);
          v_auto := v_hypothesis_new and a.about_kind <> 'owner' and not v_named;
          if v_auto then
            v_case := null;
            v_open := null;
            select k.id into v_case from ledger.cases k
            where k.row_kind = 'opportunity' and k.kind = 'investigate' and k.about_kind = a.about_kind and k.about_id is not distinct from a.about_id
              and k.hypothesis_id is not distinct from a.id
              and k.author = 'run' and k.compartments = v_label and policy.label_key(k.compartments) = any (v_keys);
            if v_case is not null then
              select o.id into v_open from ledger.opportunities o
              where o.case_id = v_case and policy.label_key(o.compartments) = any (v_keys) and o.tainted_at is null
                and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1)
                    in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner')
              order by o.created_at, o.id collate "C" limit 1;
            end if;
          end if;
          if v_auto and v_open is not null then
            if not ledger.add_basis('opportunity', v_open, v_label,
                 array(select r.kind from unnest(a.ref_kinds, a.ref_ids) with ordinality as r (kind, id, ord)
                       where not exists (select 1 from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = v_open and b.ref_kind = r.kind and b.ref_id = r.id
                                         and policy.label_key(b.compartments) = any (v_keys))
                       order by r.ord),
                 array(select r.id from unnest(a.ref_kinds, a.ref_ids) with ordinality as r (kind, id, ord)
                       where not exists (select 1 from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = v_open and b.ref_kind = r.kind and b.ref_id = r.id
                                         and policy.label_key(b.compartments) = any (v_keys))
                       order by r.ord),
                 v_label) then
              raise exception 'a ref did not resolve' using errcode = 'PIW01';
            end if;
          elsif v_auto then
            if v_case is null then
              v_case := 'cas_' || substr(a.opportunity_id, 5);
              insert into ledger.cases (id, request_id, created_by, run_id, session_id, compartments, row_kind, kind, about_kind, about_id, author, hypothesis_id)
              values (v_case, v_case, v_author, finish_run.run_id, v_session, v_label, 'opportunity', 'investigate', a.about_kind, a.about_id, 'run', a.id);
            end if;
            insert into ledger.opportunities (id, request_id, created_by, run_id, session_id, compartments, body_enc, case_id, kind, hypothesis_id,
              about_kind, about_id, goal_id, proposed_by_class)
            values (a.opportunity_id, a.opportunity_id, v_author, finish_run.run_id, v_session, v_label, a.opportunity_body_enc, v_case, 'investigate',
                    a.id, a.about_kind, a.about_id, v_goal, 'run');
            if not ledger.add_basis('opportunity', a.opportunity_id, v_label, a.ref_kinds, a.ref_ids, v_label) then
              raise exception 'a ref did not resolve' using errcode = 'PIW01';
            end if;
            insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
            values ('opportunity', a.opportunity_id, 'proposed', now(), v_author, v_label, v_session);
          end if;

        elsif a."do" in ('idea', 'lesson') then
          v_effect := case a."do" when 'idea' then 'open_investigation' else 'record_only' end;
          v_subject_kind := 'hypothesis';
          v_case := 'cas_' || substr(a.id, 5);
          insert into ledger.cases (id, request_id, created_by, run_id, session_id, compartments, row_kind, kind, about_kind, about_id, author)
          values (v_case, v_case, v_author, finish_run.run_id, v_session, v_label, 'hypothesis', a."do", a.about_kind, a.about_id, 'run');
          insert into ledger.hypotheses (id, request_id, created_by, run_id, session_id, compartments, body_enc, case_id, kind, about_kind, about_id, about_owner,
            applies_kinds, applies_roles, supersedes)
          values (a.id, a.id, v_author, finish_run.run_id, v_session, v_label, a.body_enc, v_case, a."do", a.about_kind, a.about_id, a.about_kind = 'owner',
                  a.applies_kinds, a.applies_roles, a.supersedes);
          insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
          values ('hypothesis', a.id, 'open', now(), v_author, v_label, v_session);
          v_subject := a.id;

        else
          v_effect := 'propose_opportunity';
          v_subject_kind := 'opportunity';
          if v_prompt = 'personal_translate' and v_idea is null then
            raise exception 'a ref did not resolve' using errcode = 'PIW01';
          end if;
          v_rests := case when a.hypothesis_ord is null then v_idea else v_hypotheses ->> a.hypothesis_ord::text end;
          select k.id into v_case from ledger.cases k
          where k.row_kind = 'opportunity' and k.kind = a.kind and k.about_kind = a.about_kind and k.about_id is not distinct from a.about_id
            and k.hypothesis_id is not distinct from v_rests
            and k.author = 'run' and k.compartments = v_label and policy.label_key(k.compartments) = any (v_keys);
          if v_case is not null then
            select o.id into v_open from ledger.opportunities o
            where o.case_id = v_case and policy.label_key(o.compartments) = any (v_keys) and o.tainted_at is null
              and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1)
                  in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner')
            order by o.created_at, o.id collate "C" limit 1;
          end if;
          if v_open is null then
            if v_case is null then
              v_case := 'cas_' || substr(a.id, 5);
              insert into ledger.cases (id, request_id, created_by, run_id, session_id, compartments, row_kind, kind, about_kind, about_id, author, hypothesis_id)
              values (v_case, v_case, v_author, finish_run.run_id, v_session, v_label, 'opportunity', a.kind, a.about_kind, a.about_id, 'run', v_rests);
            end if;
            insert into ledger.opportunities (id, request_id, created_by, run_id, session_id, compartments, body_enc, case_id, kind, hypothesis_id,
              about_kind, about_id, goal_id, due_at, proposed_by_class, probability, probability_if_waiting)
            values (a.id, a.id, v_author, finish_run.run_id, v_session, v_label, a.body_enc, v_case, a.kind, v_rests,
                    a.about_kind, a.about_id, v_goal, a.due_at, 'run', a.probability, a.probability_if_waiting);
            insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
            values ('opportunity', a.id, 'proposed', now(), v_author, v_label, v_session);
            v_open := a.id;
          end if;
          v_subject := v_open;
        end if;

        if a."do" <> 'lesson' and 'decision' = any (a.ref_kinds) then
          raise exception 'a ref did not resolve' using errcode = 'PIW01';
        end if;
        if not ledger.add_basis(v_subject_kind, v_subject, v_label,
             array(select r.kind from unnest(a.ref_kinds, a.ref_ids) with ordinality as r (kind, id, ord)
                   where r.kind <> 'decision' and not exists (select 1 from ledger.basis b where b.row_kind = v_subject_kind and b.row_id = v_subject and b.ref_kind = r.kind and b.ref_id = r.id
                                     and policy.label_key(b.compartments) = any (v_keys))
                   order by r.ord),
             array(select r.id from unnest(a.ref_kinds, a.ref_ids) with ordinality as r (kind, id, ord)
                   where r.kind <> 'decision' and not exists (select 1 from ledger.basis b where b.row_kind = v_subject_kind and b.row_id = v_subject and b.ref_kind = r.kind and b.ref_id = r.id
                                     and policy.label_key(b.compartments) = any (v_keys))
                   order by r.ord),
             v_label) then
          raise exception 'a ref did not resolve' using errcode = 'PIW01';
        end if;
        if a."do" = 'lesson' and 'decision' = any (a.ref_kinds) then
          with cited as (select distinct r.id from unnest(a.ref_kinds, a.ref_ids) as r (kind, id) where r.kind = 'decision')
          insert into ledger.basis (row_kind, row_id, ref_kind, ref_id, evidence_id, source_class, owner_backed, compartments)
          select 'hypothesis', v_subject, 'decision', d.id, null, 'owner', false, v_label
          from cited k join knowledge.owner_decisions d on d.id = k.id
          where d.tainted_at is null and d.compartments <@ v_label;
          get diagnostics v_count_cited = row_count;
          if v_count_cited <> (select count(distinct r.id) from unnest(a.ref_kinds, a.ref_ids) as r (kind, id) where r.kind = 'decision') then
            raise exception 'a ref did not resolve' using errcode = 'PIW01';
          end if;
        end if;
      else
        raise exception 'invalid request' using errcode = '22023';
      end if;

      v_refs := coalesce((select jsonb_agg(jsonb_build_array(r.kind, r.id) order by r.ord)
                          from unnest(a.ref_kinds, a.ref_ids) with ordinality as r (kind, id, ord)), '[]'::jsonb);
      insert into ledger.decision_point_calls (id, request_id, created_by, run_id, session_id, compartments, point, version, definition_hash, rung,
        input_hash, output, effect, effect_class, escalated, subject_kind, subject_id)
      values (v_call, v_call, v_author, finish_run.run_id, v_session, v_label, 'run_outcome', finish_run.point_version, finish_run.definition_hash, 3,
              encode(sha256(convert_to(jsonb_build_object('run', finish_run.run_id, 'attempt', v_attempt, 'action', a.ord, 'kind', a."do",
                'refs', v_refs)::text, 'UTF8')), 'hex'),
              a."do", v_effect, case when v_effect in ('record_silence', 'record_only') then 'narrow' else 'internal_reversible' end, false, v_subject_kind, v_subject);
    end loop;
  exception when sqlstate 'PIW01' then
    return;
  end;

  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  values ('run', finish_run.run_id, 'finished', clock_timestamp(), v_author, v_run_label);
  delete from queue.leases l where l.resource_kind = 'run' and l.resource_id = finish_run.run_id;
  return query select v_count, 'finished'::text;
end
$_$;

CREATE FUNCTION ledger.finish_send(send_id text, outcome text, status integer, source_item_fp text, thread_fp text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  s ledger.sent_messages%rowtype;
begin
  if session_user <> 'pi_proxy' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if finish_send.outcome is null or finish_send.outcome not in ('sent', 'failed', 'unknown')
     or (finish_send.outcome = 'sent' and (coalesce(finish_send.source_item_fp, '') !~ '^[0-9a-f]{64}$' or finish_send.thread_fp !~ '^[0-9a-f]{64}$'))
     or (finish_send.outcome = 'failed' and (finish_send.status is null or finish_send.status not between 400 and 499 or finish_send.status = 408)) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform ledger.lock_send(finish_send.send_id);
  select x.* into s from ledger.sent_messages x where x.id = finish_send.send_id;
  if s.id is null
     or (select r.event from ledger.record_events r where r.row_kind = 'send' and r.row_id = s.id order by r.id desc limit 1) is distinct from 'sending' then
    return false;
  end if;
  if finish_send.outcome = 'sent' then
    update ledger.sent_messages x set source_item_fp = finish_send.source_item_fp, thread_fp = finish_send.thread_fp, sent_at = now()
    where x.id = s.id and x.source_item_fp is null and x.thread_fp is null and x.sent_at is null;
    if not found then
      return false;
    end if;
    perform ledger.record_sent(s.id);
  else
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
    values ('send', s.id, finish_send.outcome, now(), 'owner', s.compartments,
      case when finish_send.outcome = 'failed' then 'status_' || finish_send.status end);
  end if;
  return true;
end
$_$;

CREATE FUNCTION ledger.first_contacts(draft_id text) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce(array_agg(r.fp collate "C" order by r.fp collate "C"), '{}'::text[])
  from ledger.drafts d cross join lateral unnest(d.recipient_fps) as r (fp)
  where d.id = first_contacts.draft_id
    and not exists (select 1 from vault.sent_recipients s where s.account_id = d.source_account_id and s.address_fp = r.fp)
$$;

CREATE FUNCTION ledger.forget_commitment_keys(p_fact_fps text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_n integer;
begin
  update knowledge.owner_decisions o
  set tainted_at = coalesce(o.tainted_at, now()), body_enc = null, subject_fps = '{}', details = o.details - 'factKey'
  where o.kind in ('commitment_close', 'commitment_reopen') and o.details ->> 'factKey' = any (p_fact_fps);
  delete from ledger.commitment_reopens r
  where r.fact_fp = any (p_fact_fps)
    and not exists (select 1 from ledger.agent_writes w where w.id = r.close_id and w.body_enc is not null);
  update ledger.agent_writes w set close_fact_fp = encode(sha256(convert_to(gen_random_uuid()::text, 'UTF8')), 'hex')
  where w.kind = 'close' and w.close_fact_fp = any (p_fact_fps) and w.body_enc is null;
  get diagnostics v_n = row_count;
  return v_n;
end
$$;

CREATE FUNCTION ledger.forget_dream_merges(p_evidence_ids text[], p_address_fps text[], p_claim_keys text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_c record;
  v_n integer := 0;
begin
  for v_c in
    select c.id, c.ruling_id from ledger.dream_identity_candidates c
    left join ledger.identity_questions q on q.id = c.question_id
    where c.evidence_ids && coalesce(p_evidence_ids, '{}') or c.claim_keys && coalesce(p_claim_keys, '{}')
       or q.a_fp = any (coalesce(p_address_fps, '{}')) or q.b_fp = any (coalesce(p_address_fps, '{}'))
    order by c.id
  loop
    if v_c.ruling_id is not null then
      perform ledger.dream_lift_one(v_c.ruling_id);
    end if;
    delete from ledger.dream_identity_candidates where id = v_c.id;
    v_n := v_n + 1;
  end loop;
  return v_n;
end
$$;

CREATE FUNCTION ledger.forget_fact_cards(p_fact_fps text[], p_dry_run boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_cards text[];
  v_authors text[];
  v_author text;
begin
  if p_dry_run then
    return (select count(*) from ledger.cards c where c.kind = 'same_fact' and c.case_key = any (p_fact_fps));
  end if;
  with hit as (
    update ledger.cards c set tainted_at = coalesce(c.tainted_at, now()), body_enc = null, case_key = null
    where c.kind = 'same_fact' and c.case_key = any (p_fact_fps)
    returning c.id)
  select coalesce(array_agg(h.id), '{}'::text[]) into v_cards from hit h;
  update ledger.record_events e set tainted_at = now(), body_enc = null
  where e.row_kind = 'card' and e.row_id = any (v_cards) and e.tainted_at is null;
  with states as (
    select c.id, c.created_by, c.compartments,
      (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) as state
    from ledger.cards c where c.id = any (v_cards)),
  withdrawn as (
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
    select 'card', s.id, 'withdrawn', now(), 'system:taint', s.compartments from states s where s.state in ('pending', 'deferred')
    returning row_id)
  select coalesce(array_agg(distinct s.created_by), '{}'::text[]) into v_authors
  from states s where s.state = 'pending' and s.id in (select w.row_id from withdrawn w);
  foreach v_author in array v_authors loop
    perform ledger.admit_deferred(v_author);
  end loop;
  return cardinality(v_cards);
end
$$;

CREATE FUNCTION ledger.forget_fact_rulings(fact_key_fps text[]) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with scrubbed as (
    update knowledge.owner_decisions o set details = '{}'::jsonb
    where o.kind in ('fact_join', 'fact_split')
      and (o.details ->> 'a' = any (forget_fact_rulings.fact_key_fps) or o.details ->> 'b' = any (forget_fact_rulings.fact_key_fps))
    returning 1)
  select count(*)::int from scrubbed
$$;

CREATE FUNCTION ledger.forget_fact_settlements(p_claim_ids text[], p_claim_keys text[], p_evidence_ids text[], p_dry_run boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_n integer;
begin
  if p_dry_run then
    return (select count(*) from ledger.fact_settlements s
            where s.claim_id = any (p_claim_ids) or s.claim_key = any (p_claim_keys) or s.evidence_id = any (p_evidence_ids));
  end if;
  delete from ledger.fact_settlements s
  where s.claim_id = any (p_claim_ids) or s.claim_key = any (p_claim_keys) or s.evidence_id = any (p_evidence_ids);
  get diagnostics v_n = row_count;
  return v_n;
end
$$;

CREATE FUNCTION ledger.forget_identity_answers(p_evidence_ids text[], p_address_fps text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_answer record;
  v_n integer := 0;
begin
  for v_answer in
    select a.id, a.ruling_id, a.question_id from ledger.identity_answers a
    where a.cite_evidence && p_evidence_ids or a.cite_address_fps && p_address_fps
    order by a.id collate "C"
  loop
    if v_answer.ruling_id is not null then
      update knowledge.identity_rulings set lifted_at = now(), lift_ruling_id = ruling_id, lifted_by_deletion = true
      where ruling_id = v_answer.ruling_id and lifted_at is null;
      insert into knowledge.identity_rulings (ruling_id, verdict, a_fp, b_fp, created_at)
      select d.id, 'same', r.a_fp, r.b_fp, d.decided_at
      from knowledge.identity_rulings r
      join knowledge.owner_decisions d on d.kind = 'identity' and d.answer = 'same' and d.details ->> 'inPlaceOf' = r.ruling_id
      where r.ruling_id = v_answer.ruling_id and r.verdict = 'same' and r.lifted_by_deletion
        and not exists (select 1 from knowledge.identity_rulings o where o.ruling_id = d.id)
        and not exists (select 1 from knowledge.identity_rulings o
                        where o.lifted_at is null and o.a_fp = r.a_fp and o.b_fp is not distinct from r.b_fp)
      order by d.decided_at, d.id collate "C" limit 1;
    end if;
    delete from ledger.identity_answers where id = v_answer.id;
    update ledger.identity_questions q set state = 'agents', settled_by = null, batch = null
    where q.id = v_answer.question_id and q.state in ('agents', 'settled', 'resting')
      and not exists (select 1 from knowledge.identity_rulings o join knowledge.owner_decisions d on d.id = o.ruling_id
                      where o.lifted_at is null and o.verdict = 'same' and d.kind = 'identity'
                        and ((o.a_fp = q.a_fp and o.b_fp = q.b_fp) or (o.a_fp = q.b_fp and o.b_fp = q.a_fp)));
    v_n := v_n + 1;
  end loop;
  update ledger.identity_answers a set ruling_id = null, applied_at = null
  where a.ruling_id is not null
    and exists (select 1 from knowledge.identity_rulings r where r.ruling_id = a.ruling_id and r.lifted_by_deletion);
  return v_n;
end
$$;

CREATE FUNCTION ledger.forget_question_sources(p_ids text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if coalesce(cardinality(p_ids), 0) = 0 then
    return;
  end if;
  delete from ledger.signal_marks m where m.question_sources && p_ids;
  update ledger.opportunities o
  set question_sources = array(select u.id from unnest(o.question_sources) with ordinality as u (id, n)
                               where not (u.id = any (p_ids)) order by u.n)
  where o.question_sources && p_ids;
end
$$;

CREATE FUNCTION ledger.forget_recipients(address_fps text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_drafts text[];
  v_sends integer;
  v_authors text[];
  v_author text;
begin
  perform pg_advisory_xact_lock(hashtext('intelligence personal ledger taint'));
  with hit as (
    update ledger.drafts d set tainted_at = coalesce(d.tainted_at, now()), body_enc = null, case_key = null,
      recipient_fps = array(select x from unnest(d.recipient_fps) as x where not x = any (forget_recipients.address_fps) order by x collate "C")
    where d.recipient_fps && forget_recipients.address_fps
    returning d.id
  )
  select coalesce(array_agg(h.id), '{}'::text[]) into v_drafts from hit h;

  with states as (
    select c.id, c.created_by, c.compartments,
      (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) as state
    from ledger.cards c where c.target_kind = 'draft' and c.target_id = any (v_drafts)
  ),
  withdrawn as (
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
    select 'card', s.id, 'withdrawn', now(), 'system:taint', s.compartments from states s where s.state in ('pending', 'deferred')
    returning row_id
  )
  select coalesce(array_agg(distinct s.created_by), '{}'::text[]) into v_authors
  from states s where s.state = 'pending' and s.id in (select w.row_id from withdrawn w);
  foreach v_author in array v_authors loop
    perform ledger.admit_deferred(v_author);
  end loop;

  update ledger.sent_messages s
  set recipient_fps = array(select x from unnest(s.recipient_fps) as x where not x = any (forget_recipients.address_fps) order by x collate "C")
  where s.recipient_fps && forget_recipients.address_fps;
  get diagnostics v_sends = row_count;
  return cardinality(v_drafts) + v_sends;
end
$$;

CREATE FUNCTION ledger.forget_relay_quote() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  update ledger.card_relays y set quote_enc = null where y.card_id = new.id and y.quote_enc is not null;
  return null;
end
$$;

CREATE FUNCTION ledger.forget_sent_source(account_ids text[], source_item_fps text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_changed integer;
begin
  if coalesce(cardinality(forget_sent_source.account_ids), 0) <> coalesce(cardinality(forget_sent_source.source_item_fps), 0) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtext('intelligence personal ledger taint'));
  update ledger.sent_messages s set source_item_fp = null
  where exists (select 1 from unnest(forget_sent_source.account_ids, forget_sent_source.source_item_fps) as p (account_id, fp)
                where p.account_id = s.source_account_id and p.fp = s.source_item_fp);
  get diagnostics v_changed = row_count;
  return v_changed;
end
$$;

CREATE FUNCTION ledger.forget_trial_outputs() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with gone as (
    update ledger.record_events e set tainted_at = coalesce(e.tainted_at, now()), body_enc = null
    where e.row_kind = 'run' and e.event = 'finished' and e.body_enc is not null
      and exists (select 1 from ledger.runs r where r.id = e.row_id and r.trial_model is not null)
    returning 1)
  select count(*)::integer from gone
$$;

CREATE FUNCTION ledger.forget_web_requests() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with gone as (
    update ledger.run_steps s set detail_enc = null
    where s.kind in ('web_search', 'web_fetch') and s.detail_enc is not null
    returning 1)
  select count(*)::integer from gone
$$;

CREATE FUNCTION ledger.forget_wrong_merges(p_evidence_ids text[], p_address_fps text[], p_people text[], p_dry_run boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_n integer;
  v_cited text[];
  v_rulings text[];
  v_one record;
  v_group text;
begin
  select count(*) into v_n from ledger.wrong_merge_reports r
  where r.cite_evidence && p_evidence_ids or r.cite_address_fps && p_address_fps or r.members && p_people;
  if p_dry_run or v_n = 0 then
    return v_n;
  end if;
  v_cited := array(select r.id from ledger.wrong_merge_reports r
                   where r.cite_evidence && p_evidence_ids or r.cite_address_fps && p_address_fps);
  v_rulings := array(select distinct x.one from ledger.wrong_merge_reports r cross join lateral unnest(r.ruling_ids) as x (one)
                     where r.id = any (v_cited));
  update knowledge.identity_rulings set lifted_by_deletion = true where lift_ruling_id = any (v_rulings);
  update knowledge.identity_rulings set lifted_at = now(), lift_ruling_id = ruling_id, lifted_by_deletion = true
  where ruling_id = any (v_rulings) and lifted_at is null;
  delete from ledger.wrong_merge_reports r
  where r.id = any (v_cited) or (r.state = 'split' and r.ruling_ids && v_rulings);

  for v_one in
    select r.id, r.state, r.client_id, r.ruling_ids,
      array(select m.one from unnest(r.members) as m (one) where not (m.one = any (p_people)) order by m.one collate "C") as members,
      array(select t.part from (
              select (select string_agg(e.one, ',' order by e.one collate "C") from unnest(string_to_array(p.ents, ',')) as e (one)
                      where not (e.one = any (p_people))) as part
              from unnest(r.parts) as p (ents)) t
            where t.part is not null order by t.part collate "C") as parts
    from ledger.wrong_merge_reports r where r.members && p_people
    order by r.created_at, r.id collate "C"
  loop
    if cardinality(v_one.parts) = 0
       or (cardinality(v_one.parts) < 2
           and not (v_one.state = 'split'
                    and exists (select 1 from knowledge.identity_rulings i where i.ruling_id = any (v_one.ruling_ids)))) then
      delete from ledger.wrong_merge_reports r where r.id = v_one.id;
      continue;
    end if;
    v_group := encode(sha256(convert_to(array_to_string(v_one.members, ','), 'UTF8')), 'hex');
    if v_one.state = 'open' and exists (select 1 from ledger.wrong_merge_reports o
                                        where o.id <> v_one.id and o.state = 'open' and o.client_id = v_one.client_id
                                          and o.group_key = v_group) then
      delete from ledger.wrong_merge_reports r where r.id = v_one.id;
      continue;
    end if;
    update ledger.wrong_merge_reports r
    set members = v_one.members, parts = v_one.parts,
        entity_id = case when r.entity_id = any (p_people) then v_one.members[1] else r.entity_id end,
        partition_key = encode(sha256(convert_to(array_to_string(v_one.parts, '|'), 'UTF8')), 'hex'),
        group_key = v_group
    where r.id = v_one.id;
  end loop;
  return v_n;
end
$$;

CREATE FUNCTION ledger.gap_candidates(at_time timestamp with time zone, meeting_days integer) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if gap_candidates.at_time is null or gap_candidates.meeting_days is null or gap_candidates.meeting_days not between 0 and 30 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select c.* from (
  select * from (
    select distinct on (u.name_fp, ledger.label(coalesce(m.compartments, v.compartments)))
      'unresolved_mention'::text as trigger, u.name_fp as subject, ledger.label(coalesce(m.compartments, v.compartments)) as label,
      null::text as goal_id, case when m.id is not null then 'message' else 'event' end as about_kind, coalesce(m.id, v.id) as about_id,
      case when m.id is not null then 'message' else 'event' end as source_kind, coalesce(m.id, v.id) as source_id,
      coalesce(m.sent_at, d.starts_at) as at, null::timestamptz as due_at, null::integer as facts, null::integer as ties
    from vault.unresolved_mentions u
    left join knowledge.messages m on m.evidence_id = u.evidence_id and not m.held and not m.bulk
    left join knowledge.events v on v.evidence_id = u.evidence_id
    left join knowledge.event_details d on d.event_id = v.id
    where (m.id is not null or v.id is not null) and not policy.is_restricted(coalesce(m.compartments, v.compartments))
      and not (u.relation and u.has_speaker)
    order by u.name_fp, ledger.label(coalesce(m.compartments, v.compartments)), coalesce(m.sent_at, d.starts_at) desc, coalesce(m.id, v.id) collate "C" desc
  ) mentions
  union all
  select 'no_warm_path'::text, g.target_entity_id, ledger.label(g.compartments), g.goal_id, 'entity', g.target_entity_id, 'goal', g.goal_id,
    g.stated_at, null::timestamptz, null::integer, null::integer
  from projections.goal_state g
  join knowledge.entities t on t.id = g.target_entity_id and t.kind in ('person', 'organization')
  where g.status = 'active' and not policy.is_restricted(g.compartments)
    and not ledger.gap_warm(g.target_entity_id, g.compartments, gap_candidates.at_time)
  union all
  select 'intro_path'::text, g.target_entity_id, ledger.label(g.compartments), g.goal_id, 'entity', g.target_entity_id, 'goal', g.goal_id,
    g.stated_at, null::timestamptz, i.introducers, null::integer
  from projections.goal_state g
  join knowledge.entities t on t.id = g.target_entity_id and t.kind = 'person'
  cross join lateral (select count(*)::integer as introducers
                      from ledger.gap_intro_paths(g.target_entity_id, g.compartments, gap_candidates.at_time)) i
  where g.status = 'active' and not policy.is_restricted(g.compartments) and i.introducers >= 1
    and not exists (select 1 from ledger.gap_own(g.compartments, gap_candidates.at_time) o where o.entity_id = g.target_entity_id)
  union all
  select 'unknown_attendee'::text, p.entity_id, ledger.label(v.compartments), g.goal_id, 'entity', p.entity_id, 'event', v.id,
    d.starts_at, d.starts_at,
    (select count(*)::integer from knowledge.claim_entities ce join knowledge.claims c on c.id = ce.claim_id
     where ce.entity_id = p.entity_id and ce.compartments <@ v.compartments and c.compartments <@ v.compartments),
    (select count(distinct i.evidence_id)::integer from knowledge.interaction_log i left join knowledge.messages m on m.evidence_id = i.evidence_id and m.compartments <@ v.compartments and not m.held
     where i.entity_id = p.entity_id and i.direction in ('inbound', 'outbound') and i.compartments <@ v.compartments and (m.id is not null or i.channel = 'mail_headers'))
    + (select count(*)::integer from knowledge.event_participants q join knowledge.event_details e2 on e2.event_id = q.event_id
       where q.entity_id = p.entity_id and q.compartments <@ v.compartments and e2.compartments <@ v.compartments and not e2.cancelled
         and e2.starts_at < gap_candidates.at_time)
  from knowledge.events v
  join knowledge.event_details d on d.event_id = v.id
  join knowledge.event_participants p on p.event_id = v.id
  join knowledge.entities e on e.id = p.entity_id and e.kind = 'person'
  left join lateral (
    select s.goal_id from projections.goal_state s
    where s.status = 'active' and s.target_entity_id = p.entity_id and s.compartments <@ v.compartments
    order by s.stated_at, s.goal_id collate "C" limit 1) g on true
  where not d.cancelled and coalesce(d.owner_response, 'accepted') <> 'declined'
    and d.starts_at > gap_candidates.at_time and d.starts_at <= gap_candidates.at_time + make_interval(days => gap_candidates.meeting_days)
    and not policy.is_restricted(v.compartments)
  ) c
  where not policy.vetoed(
    array[c.about_kind, c.source_kind] || case when c.goal_id is null then '{}'::text[] else array['goal'] end,
    array[c.about_id, c.source_id] || case when c.goal_id is null then '{}'::text[] else array[c.goal_id] end,
    'research')
  order by 1, 2, 3, 9, 8;
end
$$;

CREATE FUNCTION ledger.gap_default_works(opportunity_ids text[]) RETURNS TABLE(opportunity_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select distinct x.opportunity_id from ledger.expected_outcomes x
  where x.opportunity_id = any (gap_default_works.opportunity_ids) and x.created_by = 'system:gaps'
    and not policy.is_restricted(x.compartments)
  order by 1
$$;

CREATE FUNCTION ledger.gap_explored_rows(p_from timestamp with time zone) RETURNS TABLE(subject text, label_key text, at timestamp with time zone, value double precision, goal boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if p_from is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select o.gap_subject, array_to_string(o.compartments, ','), o.created_at, o.gap_value, o.goal_id is not null
  from ledger.opportunities o
  where o.gap_trigger = 'explore' and o.created_at >= p_from
  order by o.created_at, o.id collate "C";
end
$$;

CREATE FUNCTION ledger.gap_flag_rows(p_at timestamp with time zone) RETURNS TABLE(id text, gap_trigger text, gap_subject text, gap_source text, label_key text, event text, at timestamp with time zone, by text, code text, due_at timestamp with time zone, owner_no boolean, held boolean, claimed boolean, went boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if p_at is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select o.id, o.gap_trigger, o.gap_subject, o.gap_source,
    array_to_string(case when coalesce(m.compartments, v.compartments, s.compartments) is null then o.compartments
      else ledger.label(coalesce(m.compartments, v.compartments, s.compartments) || coalesce(g.compartments, '{}'::text[])) end, ','),
    e.event, e.at, e.by, e.code, o.due_at,
    exists (select 1 from ledger.opportunity_decisions d where d.opportunity_id = o.id and d.decision = 'no_go'
            and (d.decided_by = 'owner' or d.reason = 'vetoed')),
    exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = o.id and l.lease_until >= p_at)
      and not (o.gap_trigger in ('defect', 'defect_untriaged')
               and not exists (select 1 from policy.work_settings w where w.defect_role is not null)),
    exists (select 1 from ledger.record_events c where c.row_kind = 'opportunity' and c.row_id = o.id and c.event = 'claimed'),
    exists (select 1 from ledger.record_events c where c.row_kind = 'opportunity' and c.row_id = o.id and c.event = 'go')
  from ledger.opportunities o
  cross join lateral (select r.event, r.at, r.by, r.code from ledger.record_events r
                      where r.row_kind = 'opportunity' and r.row_id = o.id order by r.id desc limit 1) e
  left join knowledge.messages m on m.id = o.gap_source
  left join knowledge.events v on v.id = o.gap_source
  left join projections.goal_state s on s.goal_id = o.gap_source
  left join projections.goal_state g on g.goal_id = o.goal_id
  where o.gap_trigger is not null and (o.tainted_at is null or e.event = 'no_go')
    and (session_user <> 'pi_pipeline' or o.gap_trigger in ('close_no_tie', 'close_no_role', 'explore'))
  order by o.id collate "C";
end
$$;

CREATE FUNCTION ledger.gap_frontier(label text[], at_time timestamp with time zone, named_hours integer, tiers jsonb) RETURNS TABLE(entity_id text, goal_target boolean, goal_path boolean, goals text[], meeting_soon boolean, namer_tiers text[], named_days integer, edges integer, missing text[])
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with own as (
    select o.entity_id from ledger.gap_own(gap_frontier.label, gap_frontier.at_time) o
  ),
  said as (
    select c.id, c.type, c.evidence_id, c.valid_from
    from knowledge.claims c
    where c.type in ('relationship', 'affiliation', 'role', 'intro_offer', 'connection', 'link') and c.compartments <@ gap_frontier.label
      and (c.valid_to is null or c.valid_to > gap_frontier.at_time) and (c.type <> 'connection' or c.released)
      and not exists (select 1 from knowledge.messages m where m.evidence_id = c.evidence_id and m.held)
      and (not c.released or c.evidence_id in (select r.evidence_id from policy.released_records() r))
  ),
  names as (
    select s.id as claim_id, s.type, s.evidence_id, s.valid_from, n.entity_id
    from said s join knowledge.claim_entities n on n.claim_id = s.id and n.compartments <@ gap_frontier.label
    union
    select s.id, s.type, s.evidence_id, s.valid_from, o.entity_id
    from said s
    join knowledge.claim_org_names x on x.claim_id = s.id and x.compartments <@ gap_frontier.label
    join knowledge.org_names o on o.name_fp = x.name_fp and o.compartments @> x.compartments and o.compartments <@ x.compartments
    where not exists (select 1 from vault.evidence_items i where i.id = s.evidence_id and i.source_kind = 'crm')
  ),
  links as (
    select a.claim_id, a.entity_id as a, b.entity_id as b
    from names a
    join names b on b.claim_id = a.claim_id and b.entity_id <> a.entity_id
    join knowledge.entities ea on ea.id = a.entity_id and ea.kind in ('person', 'organization')
    join knowledge.entities eb on eb.id = b.entity_id and eb.kind in ('person', 'organization')
    where a.type <> 'link'
  ),
  tied as (
    select d.entity_id
    from knowledge.domains d
    join knowledge.accounts a on a.domain_fp = d.domain_fp and a.compartments <@ gap_frontier.label
    join own o on o.entity_id = a.entity_id
    where d.compartments <@ gap_frontier.label
  ),
  mine_said as (
    select c.id, c.type
    from knowledge.claims c
    where c.type in ('relationship', 'affiliation', 'role') and c.compartments <@ gap_frontier.label
      and not exists (select 1 from knowledge.messages m where m.evidence_id = c.evidence_id and m.held)
      and (not c.released or c.evidence_id in (select r.evidence_id from policy.released_records() r))
  ),
  mine_named as (
    select s.id as claim_id, s.type, e.id as entity_id, e.kind
    from mine_said s
    join knowledge.claim_entities n on n.claim_id = s.id and n.compartments <@ gap_frontier.label
    join knowledge.entities e on e.id = n.entity_id and e.kind in ('person', 'organization')
    union
    select s.id, s.type, o.entity_id, 'organization'
    from mine_said s
    join knowledge.claim_org_names x on x.claim_id = s.id and x.compartments <@ gap_frontier.label
    join knowledge.org_names o on o.name_fp = x.name_fp and o.compartments @> x.compartments and o.compartments <@ x.compartments
  ),
  mine as (
    select min(m.entity_id) as entity_id
    from mine_named m
    group by m.claim_id, m.type
    having count(distinct m.entity_id) = 1
      and bool_and(m.kind = case when m.type = 'relationship' then 'person' else 'organization' end)
  ),
  nodes as (
    select l.a as entity_id from links l
    where l.a not in (select o.entity_id from own o) and l.a not in (select t.entity_id from tied t)
      and l.a not in (select y.entity_id from mine y)
    union
    select o.entity_id from knowledge.org_names o join knowledge.entities e on e.id = o.entity_id and e.kind = 'organization' and e.named
    where o.compartments <@ gap_frontier.label and o.entity_id not in (select t.entity_id from tied t)
      and o.entity_id not in (select y.entity_id from mine y)
      and not exists (select 1 from vault.evidence_items i where i.id = o.evidence_id and i.source_kind = 'crm')
  ),
  targets as (
    select g.goal_id, g.target_entity_id, g.stated_at
    from projections.goal_state g
    where g.status = 'active' and g.target_entity_id is not null and g.compartments <@ gap_frontier.label
  ),
  reach as (
    select t.target_entity_id as entity_id, t.goal_id, t.stated_at, true as on_target from targets t
    union
    select l.a, t.goal_id, t.stated_at, false from targets t join links l on l.b = t.target_entity_id where l.a <> t.target_entity_id
    union
    select l1.a, t.goal_id, t.stated_at, false
    from targets t join links l2 on l2.b = t.target_entity_id join links l1 on l1.b = l2.a
    where l1.a <> t.target_entity_id and l1.a <> l2.a
  ),
  served as (
    select r.entity_id, bool_or(r.on_target) as goal_target, bool_or(not r.on_target) as goal_path,
      (array_agg(r.goal_id order by r.stated_at, r.goal_id collate "C"))[1:5] as goals
    from (select distinct entity_id, goal_id, stated_at, on_target from reach) r
    group by r.entity_id
  ),
  namers as (
    select distinct x.entity_id as node, a.entity_id as namer
    from names x
    join knowledge.messages m on m.evidence_id = x.evidence_id and not m.held and m.compartments <@ gap_frontier.label
    join knowledge.accounts a on a.value_fp = m.sender_fp and a.compartments <@ gap_frontier.label
    join own o on o.entity_id = a.entity_id
    where a.entity_id <> x.entity_id
  ),
  namer_tiers as (
    select r.node, array_agg(coalesce(gap_frontier.tiers ->> r.namer, 'none') order by r.namer collate "C") as namer_tiers
    from namers r
    group by r.node
  ),
  soon as (
    select distinct r.node
    from namers r
    join knowledge.event_participants p on p.entity_id = r.namer and p.compartments <@ gap_frontier.label
    join knowledge.event_details d on d.event_id = p.event_id and d.compartments <@ gap_frontier.label
    where not d.cancelled and coalesce(d.owner_response, 'accepted') <> 'declined'
      and d.starts_at > gap_frontier.at_time and d.starts_at <= gap_frontier.at_time + make_interval(hours => gap_frontier.named_hours)
  ),
  known as (
    select x.entity_id, max(x.valid_from) as named_at, bool_or(x.type = 'link') as linked, bool_or(x.type = 'role') as has_role,
      bool_or(x.type = 'affiliation') as has_affiliation
    from names x group by x.entity_id
  ),
  counted as (
    select l.a as entity_id, count(distinct l.claim_id)::integer as edges from links l group by l.a
  )
  select n.entity_id, coalesce(s.goal_target, false), coalesce(s.goal_path, false), coalesce(s.goals, '{}'::text[]), q.node is not null,
    coalesce(t.namer_tiers, '{}'::text[]),
    case when k.named_at is null then null else greatest(0, floor(extract(epoch from (gap_frontier.at_time - k.named_at)) / 86400))::integer end,
    coalesce(c.edges, 0),
    array_remove(array[
      case when e.kind = 'person' and not coalesce(k.linked, false)
             and (e.named or not exists (select 1 from knowledge.accounts a where a.entity_id = n.entity_id and a.compartments <@ gap_frontier.label))
           then 'identity' end,
      case when e.kind = 'person' and not coalesce(k.has_role, false) then 'role' end,
      case when e.kind = 'person' and not coalesce(k.has_affiliation, false) then 'affiliation' end,
      case when e.kind = 'organization' and not exists (select 1 from knowledge.domains d where d.entity_id = n.entity_id and d.compartments <@ gap_frontier.label)
           then 'domain' end,
      case when coalesce(c.edges, 0) < 3 then 'relations' end,
      case when not coalesce(k.linked, false) then 'links' end
    ]::text[], null)
  from nodes n
  join knowledge.entities e on e.id = n.entity_id
  left join served s on s.entity_id = n.entity_id
  left join soon q on q.node = n.entity_id
  left join namer_tiers t on t.node = n.entity_id
  left join known k on k.entity_id = n.entity_id
  left join counted c on c.entity_id = n.entity_id
  order by n.entity_id collate "C"
$$;

CREATE FUNCTION ledger.gap_intro_paths(target text, label text[], at_time timestamp with time zone) RETURNS TABLE(entity_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select o.entity_id
  from ledger.gap_own(gap_intro_paths.label, gap_intro_paths.at_time) o
  where o.entity_id <> gap_intro_paths.target and not policy.is_restricted(gap_intro_paths.label)
    and (exists (
           select 1
           from knowledge.claims c
           join knowledge.messages m on m.evidence_id = c.evidence_id and not m.held and m.compartments <@ gap_intro_paths.label
           join knowledge.accounts a on a.value_fp = m.sender_fp and a.entity_id = o.entity_id and a.compartments <@ gap_intro_paths.label
           join knowledge.claim_entities x on x.claim_id = c.id and x.entity_id = o.entity_id and x.compartments <@ gap_intro_paths.label
           join knowledge.claim_entities y on y.claim_id = c.id and y.entity_id = gap_intro_paths.target and y.compartments <@ gap_intro_paths.label
           where c.type in ('relationship', 'intro_offer') and c.compartments <@ gap_intro_paths.label)
         or exists (
           select 1
           from knowledge.claims c
           join knowledge.claim_entities x on x.claim_id = c.id and x.entity_id = o.entity_id and x.compartments <@ gap_intro_paths.label
           join knowledge.claim_entities y on y.claim_id = c.id and y.entity_id = gap_intro_paths.target and y.compartments <@ gap_intro_paths.label
           where c.type = 'connection' and c.released and c.compartments <@ gap_intro_paths.label
             and c.evidence_id in (select r.evidence_id from policy.released_records() r)))
  order by o.entity_id collate "C"
$$;

CREATE FUNCTION ledger.gap_own(label text[], at_time timestamp with time zone) RETURNS TABLE(entity_id text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select x.entity_id from (
    select i.entity_id
    from knowledge.interaction_log i
    left join knowledge.messages m on m.evidence_id = i.evidence_id and m.compartments <@ gap_own.label and not m.held
    where i.compartments <@ gap_own.label and (m.id is not null or i.channel = 'mail_headers')
    group by i.entity_id
    having bool_or(i.direction = 'outbound') and bool_or(i.direction = 'inbound' and i.entity_role = 'sender')
    union
    select p.entity_id
    from knowledge.event_participants p
    join knowledge.event_details d on d.event_id = p.event_id
    where p.compartments <@ gap_own.label and d.compartments <@ gap_own.label and not d.cancelled and d.starts_at <= gap_own.at_time
      and coalesce(d.owner_response, 'accepted') in ('accepted', 'tentative')
    union
    select a.entity_id from knowledge.contact_addresses a where a.compartments <@ gap_own.label
  ) x
  join knowledge.entities e on e.id = x.entity_id and e.kind = 'person' and not e.named
$$;

CREATE FUNCTION ledger.gap_raised_by_trigger(p_day timestamp with time zone) RETURNS TABLE(label_key text, trigger text, n integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if p_day is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select x.key, x.raiser, x.raised from (
    select array_to_string(o.compartments, ',') as key, o.gap_trigger as raiser, count(*)::integer as raised
    from ledger.record_events r join ledger.opportunities o on o.id = r.row_id and o.tier = 'task'
    where r.row_kind = 'opportunity' and r.event = 'go' and r.by = 'system:gaps' and r.at >= p_day and o.gap_trigger is not null
    group by 1, 2
  ) x
  order by x.key collate "C", x.raiser collate "C";
end
$$;

CREATE FUNCTION ledger.gap_supply_rows(p_day timestamp with time zone, p_from timestamp with time zone, p_uncapped text[], p_capped_dated text[]) RETURNS TABLE(label_key text, raised_today integer, claimed integer, done integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if p_day is null or p_from is null or p_uncapped is null or p_capped_dated is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select x.key, x.raised, x.claims, x.dones from (
    select array_to_string(case when coalesce(m.compartments, v.compartments, s.compartments) is null then o.compartments
        else ledger.label(coalesce(m.compartments, v.compartments, s.compartments) || coalesce(g.compartments, '{}'::text[])) end, ',') as key,
      (count(*) filter (where r.event = 'go' and r.by = 'system:gaps' and r.at >= p_day
                          and (o.due_at is null or o.gap_trigger = any (p_capped_dated)) and o.gap_trigger <> all (p_uncapped)))::integer as raised,
      (count(distinct r.row_id) filter (where r.event = 'claimed'))::integer as claims,
      (count(distinct r.row_id) filter (where r.event = 'done'))::integer as dones
    from ledger.record_events r
    join ledger.opportunities o on o.id = r.row_id and o.tier = 'task'
    left join knowledge.messages m on m.id = o.gap_source
    left join knowledge.events v on v.id = o.gap_source
    left join projections.goal_state s on s.goal_id = o.gap_source
    left join projections.goal_state g on g.goal_id = o.goal_id
    where r.row_kind = 'opportunity' and r.event in ('go', 'claimed', 'done') and r.at >= p_from
    group by 1
  ) x
  order by x.key collate "C";
end
$$;

CREATE FUNCTION ledger.gap_warm(target text, label text[], at_time timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with own as (
    select o.entity_id from ledger.gap_own(gap_warm.label, gap_warm.at_time) o
  ),
  links as (
    select a.entity_id as a, b.entity_id as b
    from knowledge.claims c
    join knowledge.claim_entities a on a.claim_id = c.id
    join knowledge.claim_entities b on b.claim_id = c.id and b.entity_id <> a.entity_id
    join knowledge.entities ea on ea.id = a.entity_id and ea.kind in ('person', 'organization')
    join knowledge.entities eb on eb.id = b.entity_id and eb.kind in ('person', 'organization')
    where c.type in ('relationship', 'affiliation', 'intro_offer') and c.compartments <@ gap_warm.label
      and a.compartments <@ gap_warm.label and b.compartments <@ gap_warm.label
  )
  select gap_warm.target in (select o.entity_id from own o)
    or exists (select 1 from links l join own o on o.entity_id = l.b where l.a = gap_warm.target)
    or exists (select 1 from links l1 join links l2 on l2.a = l1.b join own o on o.entity_id = l2.b
               where l1.a = gap_warm.target and l2.b <> gap_warm.target)
$$;

CREATE FUNCTION ledger.gate_facts(draft_id text, phase text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_reader boolean := session_user = 'pi_reader';
  v_caller text;
  d ledger.drafts%rowtype;
  v_status text;
  v_kind text;
  v_author_name text;
  v_author_current boolean;
  v_label text;
  v_account_own boolean;
  v_connected boolean;
  v_copy_missing boolean;
  v_sync_age integer;
  v_opportunity ledger.opportunities%rowtype;
  v_about_kinds text[];
  v_about_ids text[];
  v_answered vault.evidence_items%rowtype;
  v_vetoed integer;
  v_suppressed integer;
  v_first integer;
  v_about_vetoed boolean;
  v_missing integer;
  v_tainted integer;
  v_flagged integer;
  v_unscreened integer;
  v_changed integer;
  v_newer integer;
  v_already boolean;
  v_go boolean;
  v_open boolean;
  v_switch boolean;
  v_disclosure_only boolean;
begin
  if gate_facts.phase is null or gate_facts.phase not in ('draft', 'send') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  select dr.* into d from ledger.drafts dr where dr.id = gate_facts.draft_id;
  if v_reader then
    select c.id into v_caller from policy.current_client() c;
    if v_caller is null or gate_facts.phase <> 'draft' or d.id is null or d.created_by <> 'client:' || v_caller then
      raise exception 'not permitted' using errcode = '42501';
    end if;
  end if;
  v_switch := coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on';
  if d.id is null then
    return jsonb_build_object(
      'draft', jsonb_build_object('found', false, 'tainted', false, 'status', 'new', 'ageSeconds', 0, 'withinCap', false,
        'consentFree', false, 'authorCurrent', false, 'disclosureOnly', false),
      'account', jsonb_build_object('connected', false, 'own', false, 'copyMissing', false, 'syncAgeSeconds', null),
      'recipients', jsonb_build_object('count', 0, 'vetoed', 0, 'suppressed', 0, 'firstContact', 0),
      'about', jsonb_build_object('vetoed', false),
      'basis', jsonb_build_object('missing', 0, 'tainted', 0, 'flagged', 0, 'unscreened', 0),
      'beliefs', jsonb_build_object('changed', 0),
      'thread', jsonb_build_object('isNew', false, 'found', false, 'newer', 0),
      'sent', jsonb_build_object('already', false),
      'work', jsonb_build_object('named', false, 'go', false, 'open', false, 'tainted', false),
      'killSwitch', v_switch);
  end if;

  v_status := coalesce((select r.event from ledger.record_events r where r.row_kind = 'draft' and r.row_id = d.id order by r.id desc limit 1), 'new');
  if d.opportunity_id is not null then
    select o.* into v_opportunity from ledger.opportunities o where o.id = d.opportunity_id;
  end if;
  v_kind := coalesce(v_opportunity.kind, 'proposal');
  select c.name, c.status = 'active' and 'draft_message' = any (c.tools) into v_author_name, v_author_current
  from policy.clients c where 'client:' || c.id = d.created_by;

  select a.label, a.compartments = array['own'],
    case when a.last_outcome = 'ok' and a.last_sync_at is not null
      then greatest(0, floor(extract(epoch from now() - a.last_sync_at)))::integer end
  into v_label, v_account_own, v_sync_age
  from vault.source_accounts a where a.id = d.source_account_id;
  v_connected := exists (select 1 from policy.secrets s where s.name = 'google-send/' || v_label) and policy.read_connected(v_label);
  v_copy_missing := exists (
    select 1 from ledger.sent_messages s
    where s.source_account_id = d.source_account_id and s.sent_at is not null and s.source_item_fp is not null
      and s.sent_at < now() - interval '30 minutes' and s.sent_at >= now() - interval '24 hours'
      and not exists (select 1 from vault.evidence_items e where e.sent_id = s.id)
      and not exists (select 1 from knowledge.owner_decisions o where o.kind = 'send_settle' and o.target_kind = 'send' and o.target_id = s.id));

  v_vetoed := (select count(*) from unnest(d.recipient_fps) as r (fp) where policy.vetoed(array['address'], array[r.fp], v_kind))
    + (select count(*) from unnest(d.recipient_domain_fps) as r (fp) where policy.vetoed(array['domain'], array[r.fp], v_kind));
  v_suppressed := (select count(*) from unnest(d.recipient_fps) as r (fp)
                   where exists (select 1 from knowledge.suppressions s where s.kind = 'address' and s.value_fp = r.fp));
  v_first := (select count(*) from unnest(d.recipient_fps) as r (fp)
              where not exists (select 1 from vault.sent_recipients s where s.account_id = d.source_account_id and s.address_fp = r.fp));

  select coalesce(array_agg(b.ref_kind order by b.id), '{}'::text[]), coalesce(array_agg(b.ref_id order by b.id), '{}'::text[])
  into v_about_kinds, v_about_ids
  from ledger.basis b where b.row_kind = 'draft' and b.row_id = d.id;
  if v_opportunity.about_id is not null then
    v_about_kinds := v_about_kinds || v_opportunity.about_kind;
    v_about_ids := v_about_ids || v_opportunity.about_id;
  end if;
  v_about_vetoed := policy.vetoed(v_about_kinds, v_about_ids, v_kind)
    or exists (select 1 from knowledge.vetoes v where v.subject = 'any' and v.lifted_at is null and v.work_kind = v_kind);

  with refs as (
    select b.ref_kind, b.ref_id, b.tainted_at is not null as tainted,
      case b.ref_kind
        when 'message' then not exists (select 1 from knowledge.messages m where m.id = b.ref_id)
        when 'event' then not exists (select 1 from knowledge.events e where e.id = b.ref_id)
        when 'entity' then not exists (select 1 from knowledge.entities e where e.id = b.ref_id)
        when 'agent_record' then not exists (select 1 from ledger.agent_writes a where a.id = b.ref_id)
        when 'goal' then not exists (select 1 from projections.goal_state g where g.goal_id = b.ref_id)
        when 'hypothesis' then not exists (select 1 from ledger.hypotheses h where h.id = b.ref_id)
        when 'opportunity' then not exists (select 1 from ledger.opportunities o where o.id = b.ref_id)
        else true end as missing
    from ledger.basis b where b.row_kind = 'draft' and b.row_id = d.id
  ),
  messages as (
    select m.id, m.held, m.evidence_id from refs r join knowledge.messages m on m.id = r.ref_id where r.ref_kind = 'message'
  ),
  judged as (
    select w.evidence_id, w.withheld, w.screened
    from policy.withheld_items((select array_agg(m.evidence_id) from messages m)) w
  )
  select (select count(*) from refs r where r.missing),
    (select count(*) from refs r where r.tainted),
    (select count(*) from messages m left join judged j on j.evidence_id = m.evidence_id where m.held or coalesce(j.withheld, false))
      + (select count(*) from refs r join ledger.agent_writes a on a.id = r.ref_id where r.ref_kind = 'agent_record' and a.flagged_at is not null),
    (select count(*) from messages m left join judged j on j.evidence_id = m.evidence_id
     where not m.held and (j.evidence_id is null or (not j.screened and not j.withheld)))
  into v_missing, v_tainted, v_flagged, v_unscreened;

  v_changed := (select count(*) from ledger.draft_beliefs db
                where db.draft_id = d.id
                  and db.state_fp <> coalesce((
                    select l.state_fp from ledger.trigger_log l
                    where policy.label_key(l.compartments) = any (ledger.keys_of(d.compartments))
                      and l.clearance_key = policy.label_key(d.compartments)
                      and l.fact_key_fp = db.fact_key_fp and l.cause not in ('due', 'dropped')
                    order by l.id desc limit 1), repeat('0', 64)));

  if d.thread_fp is not null then
    select e.* into v_answered from vault.evidence_items e
    where e.id = d.reply_to_evidence_id and exists (select 1 from knowledge.messages m where m.evidence_id = e.id);
    v_newer := case when v_answered.id is null then 0 else (
      select count(distinct e.source_item_fp) from vault.evidence_items e
      where e.source_account_id = d.source_account_id and e.thread_fp = d.thread_fp
        and e.source_item_fp <> v_answered.source_item_fp and e.observed_at > v_answered.observed_at
        and exists (select 1 from knowledge.messages m where m.evidence_id = e.id)) end;
  else
    v_newer := 0;
  end if;

  v_already := exists (
      select 1 from ledger.sent_messages s
      where s.draft_id = d.id
        and (select r.event from ledger.record_events r where r.row_kind = 'send' and r.row_id = s.id order by r.id desc limit 1) in ('sending', 'sent', 'unknown'))
    or exists (
      select 1 from ledger.sent_messages s
      cross join lateral (select r.event, r.at from ledger.record_events r where r.row_kind = 'send' and r.row_id = s.id order by r.id desc limit 1) st
      where s.source_account_id = d.source_account_id and s.body_fp = d.body_fp and s.recipient_fps = d.recipient_fps
        and (st.event in ('sending', 'unknown') or (st.event = 'sent' and st.at > d.created_at)))
    or exists (
      select 1 from knowledge.interaction_log i
      join vault.evidence_items e on e.id = i.evidence_id
      where i.direction = 'outbound' and i.body_hash = d.body_fp and e.source_account_id = d.source_account_id and e.observed_at > d.created_at
        and array(select s.address_fp collate "C" from vault.sent_recipients s where s.evidence_id = e.id order by 1) = d.recipient_fps);

  if v_opportunity.id is not null then
    v_go := coalesce((select od.decision = 'go' and od.decided_by = 'owner' from ledger.opportunity_decisions od
                      where od.opportunity_id = v_opportunity.id order by od.id desc limit 1), false);
    v_open := coalesce((select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = v_opportunity.id order by r.id desc limit 1)
                       in ('go', 'claimed', 'handed_to_owner'), false);
  else
    v_go := false;
    v_open := false;
  end if;

  v_disclosure_only := gate_facts.phase = 'send' and v_status = 'held'
    and (select array_agg(g.kind order by g.kind) from ledger.gate_checks g where g.draft_id = d.id and g.phase = 'draft' and not g.passed) = array['disclosure'];

  if v_reader then
    v_vetoed := 0;
    v_suppressed := 0;
    v_about_vetoed := false;
    v_switch := false;
    v_copy_missing := false;
  end if;

  return jsonb_build_object(
    'draft', jsonb_build_object(
      'found', true,
      'tainted', d.tainted_at is not null,
      'status', v_status,
      'ageSeconds', greatest(0, floor(extract(epoch from now() - d.created_at)))::integer,
      'withinCap', coalesce(v_author_name is not null
        and not exists (select 1 from unnest(d.compartments) as c (one) where c.one not in ('own', 'public') and c.one <> 'agent:' || v_author_name), false),
      'consentFree', v_kind in ('reply', 'follow_up', 'proposal'),
      'authorCurrent', coalesce(v_author_current, false),
      'disclosureOnly', coalesce(v_disclosure_only, false)),
    'account', jsonb_build_object('connected', coalesce(v_connected, false), 'own', coalesce(v_account_own, false),
      'copyMissing', v_copy_missing, 'syncAgeSeconds', v_sync_age),
    'recipients', jsonb_build_object('count', cardinality(d.recipient_fps), 'vetoed', v_vetoed, 'suppressed', v_suppressed, 'firstContact', v_first),
    'about', jsonb_build_object('vetoed', v_about_vetoed),
    'basis', jsonb_build_object('missing', v_missing, 'tainted', v_tainted, 'flagged', v_flagged, 'unscreened', v_unscreened),
    'beliefs', jsonb_build_object('changed', v_changed),
    'thread', jsonb_build_object('isNew', d.thread_fp is null, 'found', d.thread_fp is null or v_answered.id is not null, 'newer', v_newer),
    'sent', jsonb_build_object('already', v_already),
    'work', jsonb_build_object('named', d.opportunity_id is not null, 'go', v_go, 'open', v_open, 'tainted', coalesce(v_opportunity.tainted_at is not null, false)),
    'killSwitch', v_switch);
end
$$;

CREATE FUNCTION ledger.goal_review_gaps(at_time timestamp with time zone, quiet_since timestamp with time zone) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
begin
  if goal_review_gaps.at_time is null or goal_review_gaps.quiet_since is null
     or goal_review_gaps.quiet_since >= goal_review_gaps.at_time then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select 'goal_review'::text, g.goal_id, ledger.label(g.compartments), g.goal_id, 'owner'::text, null::text, 'goal'::text, g.goal_id,
    g.updated_at, null::timestamptz, null::integer, null::integer
  from projections.goal_state g
  where g.status = 'active' and g.updated_at < goal_review_gaps.quiet_since
    and not policy.is_restricted(g.compartments)
    and not exists (select 1 from ledger.opportunities o
                    join ledger.record_events r on r.row_kind = 'opportunity' and r.row_id = o.id
                    where o.goal_id = g.goal_id and o.compartments <@ g.compartments
                      and o.gap_trigger is distinct from 'goal_review'
                      and r.at >= goal_review_gaps.quiet_since and (r.by = 'owner' or r.by like 'client:%'))
    and not exists (select 1 from ledger.basis b
                    where b.ref_kind = 'goal' and b.ref_id = g.goal_id and b.compartments <@ g.compartments
                      and b.added_at >= goal_review_gaps.quiet_since
                      and coalesce(case b.row_kind
                            when 'hypothesis' then (select h.created_by from ledger.hypotheses h
                                                    where h.id = b.row_id and h.compartments <@ g.compartments)
                            when 'goal_proposal' then (select q.created_by from ledger.goal_proposals q
                                                       where q.id = b.row_id and q.compartments <@ g.compartments)
                            when 'opportunity' then (select o.created_by from ledger.opportunities o
                                                     where o.id = b.row_id and o.compartments <@ g.compartments)
                            when 'move' then (select m.created_by from ledger.moves m join ledger.opportunities o on o.id = m.opportunity_id
                                              where m.id = b.row_id and m.compartments <@ g.compartments
                                                and o.gap_trigger is distinct from 'goal_review') end, '') ~ '^(owner$|client:)')
    and not exists (select 1 from knowledge.projects p
                    join ledger.agent_writes w on w.project_id = p.id and w.compartments <@ g.compartments
                    where p.goal_id = g.goal_id and p.compartments <@ g.compartments
                      and w.created_at >= goal_review_gaps.quiet_since and w.tainted_at is null and w.flagged_at is null)
    and not exists (select 1 from knowledge.vetoes v
                    where v.lifted_at is null and v.subject = 'any' and (v.work_kind is null or v.work_kind = 'research'))
    and (g.target_entity_id is null or not policy.vetoed(array['entity'], array[g.target_entity_id], 'research'))
  order by g.updated_at, g.goal_id;
end
$_$;

CREATE FUNCTION ledger.goal_target_forms(p_entity text, p_name_fp text, p_org boolean, p_clearance text[], p_keys text[]) RETURNS TABLE(entities text[], names text[])
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with recursive start as (
    select p_entity as id where p_entity is not null
    union
    select s.entity_id from knowledge.aliases s join knowledge.entities e on e.id = s.entity_id and e.kind = 'person'
    where not p_org and s.value_fp = p_name_fp
      and (p_clearance is null or (s.compartments <@ p_clearance and policy.label_key(s.compartments) = any (p_keys)))
    union
    select o.entity_id from knowledge.org_names o
    where p_org and o.name_fp = p_name_fp
      and (p_clearance is null or (o.compartments <@ p_clearance and policy.label_key(o.compartments) = any (p_keys)))
  ),
  fps (fp) as (
    select a.value_fp from knowledge.accounts a join start t on t.id = a.entity_id join knowledge.entities e on e.id = a.entity_id and e.kind = 'person'
    where (p_clearance is null or (a.compartments <@ p_clearance and policy.label_key(a.compartments) = any (p_keys)))
    union
    select case when r.a_fp = f.fp then r.b_fp else r.a_fp end
    from fps f join knowledge.identity_rulings r on r.verdict = 'same' and r.lifted_at is null and r.b_fp is not null and f.fp in (r.a_fp, r.b_fp)
    where not exists (select 1 from knowledge.accounts o join knowledge.entities e on e.id = o.entity_id and e.kind = 'owner' where o.value_fp in (r.a_fp, r.b_fp))
      and (p_clearance is null or exists (
        select 1 from knowledge.accounts x
        where x.value_fp = case when r.a_fp = f.fp then r.b_fp else r.a_fp end
          and x.compartments <@ p_clearance and policy.label_key(x.compartments) = any (p_keys)))
  ),
  people as (
    select id from start
    union
    select a.entity_id from knowledge.accounts a join knowledge.entities e on e.id = a.entity_id and e.kind = 'person'
    where a.value_fp in (select fp from fps)
      and (p_clearance is null or (a.compartments <@ p_clearance and policy.label_key(a.compartments) = any (p_keys)))
  )
  select
    array(select id from people order by id),
    array(
      select p_name_fp where p_name_fp is not null
      union
      select s.value_fp from knowledge.aliases s
      where s.entity_id in (select id from people)
        and (p_clearance is null or (s.compartments <@ p_clearance and policy.label_key(s.compartments) = any (p_keys)))
      union
      select o.name_fp from knowledge.org_names o
      where o.entity_id in (select id from people)
        and (p_clearance is null or (o.compartments <@ p_clearance and policy.label_key(o.compartments) = any (p_keys))));
$$;

CREATE FUNCTION ledger.hand_off(opportunity_id text, request_id text, session_id text, role text, reason text, record_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_author text;
  v_compartments text[];
  v_tier text;
  v_status text;
  v_by text;
  v_owner boolean;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('hand_off' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = hand_off.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if hand_off.reason is null or hand_off.reason not in ('other_role', 'blocked', 'other')
     or (hand_off.role is not null and hand_off.role !~ '^[a-z][a-z0-9-]{1,31}$') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  v_author := 'client:' || v_caller;
  perform ledger.lock_rows(array(select o.id from ledger.opportunities o
                                 where o.id = hand_off.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)));
  select o.compartments, o.tier into v_compartments, v_tier from ledger.opportunities o
  where o.id = hand_off.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys) and o.tainted_at is null;
  if v_compartments is null then
    return false;
  end if;
  v_owner := hand_off.role is not distinct from 'owner';
  select r.event, r.by into v_status, v_by from ledger.record_events r
  where r.row_kind = 'opportunity' and r.row_id = hand_off.opportunity_id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1;
  if not (coalesce(v_status in ('claimed', 'go'), false)
          and exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = hand_off.opportunity_id
                      and l.holder = v_caller)
          and ledger.work_held(hand_off.opportunity_id, now())) then
    return coalesce(
      (v_status = 'go' and v_by = 'system:handoff'
        and (select r.by from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = hand_off.opportunity_id and r.event = 'routed'
             and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) = v_author)
      or (v_owner and v_status = 'handed_to_owner' and v_by = v_author), false);
  end if;
  if v_owner and (hand_off.record_id is null or v_tier = 'task') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if hand_off.role is not null and not v_owner
     and not exists (select 1 from policy.clients k where k.status = 'active' and k.kind = 'agent' and (hand_off.role = any (k.roles) or hand_off.role = k.name)) then
    raise exception 'unknown role' using errcode = 'PIW04';
  end if;
  if hand_off.record_id is not null
     and (not exists (select 1 from ledger.agent_writes w where w.id = hand_off.record_id and w.client_id = v_caller and w.kind = 'handoff' and w.tainted_at is null
                      and policy.label_key(w.compartments) = any (v_keys))
          or not ledger.add_basis('opportunity', hand_off.opportunity_id, v_compartments, array['agent_record'], array[hand_off.record_id], v_compartments)) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
  select 'intention', i.id, 'cancelled', now(), v_author, i.compartments, hand_off.session_id
  from ledger.intentions i
  where i.opportunity_id = hand_off.opportunity_id and i.kind = 'check_back' and i.client_id = v_caller
    and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys)
    and (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) = 'set';
  if v_owner then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
    values ('opportunity', hand_off.opportunity_id, 'handed_to_owner', clock_timestamp(), v_author, v_compartments, hand_off.session_id);
    delete from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = hand_off.opportunity_id;
    return true;
  end if;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, code, role)
  values ('opportunity', hand_off.opportunity_id, 'routed', clock_timestamp(), v_author, v_compartments, hand_off.session_id, hand_off.reason, hand_off.role);
  delete from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = hand_off.opportunity_id;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
  values ('opportunity', hand_off.opportunity_id, 'go', clock_timestamp(), 'system:handoff', v_compartments, hand_off.session_id);
  if hand_off.role is not null then
    delete from ledger.work_declines d
    where d.opportunity_id = hand_off.opportunity_id
      and exists (select 1 from policy.clients k where k.id = d.client_id and (hand_off.role = any (k.roles) or hand_off.role = k.name));
  end if;
  return true;
end
$_$;

CREATE FUNCTION ledger.health_notice(card_id text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_kind text;
  v_about text;
  v_written integer;
begin
  select m[1], m[2] into v_kind, v_about
  from ledger.cards c, regexp_match(c.case_key, '^box:([a-z_]+):(.+)$') as m
  where c.id = health_notice.card_id and c.kind = 'box_health' and c.created_by = 'system:health';
  if v_kind is null then
    return 0;
  end if;
  insert into ledger.health_notices (id, client_id, card_id, kind, about)
  select ledger.new_id('ntc'), k.id, health_notice.card_id, v_kind, ledger.health_notice_about(v_about, k.id)
  from policy.clients k
  where ledger.health_notice_due(health_notice.card_id, k.id)
    and (not exists (select 1 from ledger.health_targets(health_notice.card_id))
         or k.id in (select t.client_id from ledger.health_targets(health_notice.card_id) t))
  order by k.id collate "C"
  on conflict (client_id, card_id) do nothing;
  get diagnostics v_written = row_count;
  if v_written > 0 then
    perform pg_notify('pi_work_notice', '');
  end if;
  return v_written;
end
$_$;

CREATE FUNCTION ledger.health_notice_about(about text, client_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
  select case
    when split_part(health_notice_about.about, '/', 2) !~ '^[a-z]{3}_[0-9A-HJKMNP-TV-Z]{26}(:|$)' then health_notice_about.about
    when split_part(health_notice_about.about, '/', 1) = 'account' and exists (
           select 1 from vault.source_accounts a join policy.clients k on k.id = health_notice_about.client_id
           where a.id = split_part(health_notice_about.about, '/', 2) and a.compartments <@ k.compartments
             and policy.label_key(a.compartments) = any (ledger.keys_of(k.compartments)))
      then health_notice_about.about
    when split_part(health_notice_about.about, '/', 1) <> 'account'
         and split_part(split_part(health_notice_about.about, '/', 2), ':', 1) = health_notice_about.client_id
      then health_notice_about.about
    else split_part(health_notice_about.about, '/', 1)
  end
$_$;

CREATE FUNCTION ledger.health_notice_current(notice_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
  select coalesce((select n.state = 'pending'
                     and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = n.card_id order by r.id desc limit 1) in ('pending', 'deferred')
                     and ledger.health_notice_due(n.card_id, n.client_id)
                     and (strpos(n.about, '/') = 0 or n.about = (select ledger.health_notice_about(m[2], n.client_id)
                                    from ledger.cards c, regexp_match(c.case_key, '^box:([a-z_]+):(.+)$') as m where c.id = n.card_id))
                   from ledger.health_notices n where n.id = health_notice_current.notice_id), false)
$_$;

CREATE FUNCTION ledger.health_notice_due(card_id text, client_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select exists (
    select 1 from policy.clients k join ledger.cards c on c.id = health_notice_due.card_id
    join policy.client_webhooks w on w.client_id = k.id
    where k.id = health_notice_due.client_id and k.status = 'active' and k.kind = 'agent'
      and c.compartments <@ k.compartments and policy.label_key(c.compartments) = any (ledger.keys_of(k.compartments)))
$$;

CREATE FUNCTION ledger.health_read() RETURNS TABLE(section text, key text, code text, value double precision, sample integer, at timestamp with time zone, extra text, parts jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
  v_sees_system boolean;
begin
  select r.client_id, r.clearance into v_caller, v_clearance from ledger.agent_mail_reader('get_health') r;
  v_keys := policy.clearance_keys();
  v_sees_system := exists (select 1 from ledger.measure_readings m
                           where m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys));

  return query
  select 'reading'::text, x.metric, x.state, x.value, x.sample, x.read_at,
    case when x.read_at < now() - interval '48 hours' then 'stale' end, x.parts
  from (select distinct on (m.metric) m.metric, m.state, m.value, m.sample, m.read_at, m.parts from ledger.measure_readings m
        where m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys)
        order by m.metric, m.read_at desc, m.id desc) x
  order by x.metric collate "C";

  return query
  select 'check'::text, x.about, x.code, null::double precision, null::integer, x.ended_at, null::text, null::jsonb
  from (select distinct on (j.about) j.about, j.code, j.ended_at from ledger.job_runs j
        where v_sees_system and j.job = 'canary' and j.about is not null
        order by j.about, j.started_at desc, j.id desc) x
  order by x.about collate "C";

  return query
  select 'job'::text, x.job, x.code, null::double precision, x.failed, x.ended_at, null::text, null::jsonb
  from (select n.job, l.code, l.ended_at,
          (select count(*)::integer from (select r.code from ledger.job_runs r where r.job = n.job
                                          order by r.started_at desc, r.id desc limit 3) t
           where t.code not in ('ok', 'already_running', 'busy', 'budget', 'lane_off')) as failed
        from unnest(array['sync', 'erase_settle', 'work_tick', 'extract', 'dream', 'reasoner', 'executor', 'outcome_test',
                          'improvement_filing', 'backup', 'time_pass']) as n(job)
        cross join lateral (select r.code, r.ended_at from ledger.job_runs r where r.job = n.job
                            order by r.started_at desc, r.id desc limit 1) l
        where v_sees_system) x
  order by x.job collate "C";

  return query
  select 'card'::text, c.id, m[1], null::double precision, null::integer, c.created_at, ledger.health_notice_about(m[2], v_caller), null::jsonb
  from ledger.cards c, regexp_match(c.case_key, '^box:([a-z_]+):(.+)$') as m
  where c.kind = 'box_health' and c.created_by = 'system:health' and c.tainted_at is null
    and c.compartments <@ v_clearance and policy.label_key(c.compartments) = any (v_keys)
    and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id
         order by r.id desc limit 1) in ('pending', 'deferred')
  order by c.created_at, c.id collate "C"
  limit 100;

  return query
  select 'defects'::text, coalesce(i.assignee_role, ''), i.severity, null::double precision, count(*)::integer, null::timestamptz, null::text, null::jsonb
  from ledger.improvements i
  cross join lateral ledger.improvement_status(i.id, v_clearance, v_keys) s
  where i.tainted_at is null and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys)
    and s.status in ('open', 'triaged', 'in_progress')
  group by coalesce(i.assignee_role, ''), i.severity
  order by coalesce(i.assignee_role, '') collate "C", i.severity collate "C";

  return query
  select 'box'::text, b.key, b.code, null::double precision, null::integer, null::timestamptz, null::text, null::jsonb
  from (select 'migration'::text as key, (select substr(max(g.name), 1, 4) from policy.migrations g) as code
        union all
        select w.key, w.code from policy.work_settings s
        cross join lateral (values ('planner', s.planner),
                                   ('identity_merges', s.identity_merges), ('identity_agents', s.identity_agents)) as w (key, code)) b
  where v_sees_system and b.code is not null
  order by b.key collate "C";
end
$_$;

CREATE FUNCTION ledger.health_targets(p_card text) RETURNS TABLE(client_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_place text;
begin
  foreach v_place in array coalesce((select s.ping_order from policy.work_settings s), '{}'::text[]) loop
    return query select t.client_id from ledger.ping_place_agents(v_place) t where ledger.health_notice_due(p_card, t.client_id);
    if found then
      return;
    end if;
  end loop;
end
$$;

CREATE FUNCTION ledger.identity_agents_on() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce((select s.identity_agents = 'on' from policy.work_settings s), false)
$$;

CREATE FUNCTION ledger.improvement_events_of(improvement text) RETURNS TABLE(id text, created_at timestamp with time zone, by_name text, event text, status text, compartments text[], note_enc jsonb, evidence_enc jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
begin
  select r.client_id, r.clearance into v_caller, v_clearance from ledger.agent_mail_reader('list_improvements') r;
  v_keys := policy.clearance_keys();
  return query
  select e.id, e.created_at, case when e.created_by = 'owner' then 'owner' else coalesce(k.name, 'system') end,
    e.event, e.status, e.compartments, e.note_enc, e.evidence_enc
  from ledger.improvement_events e
  join ledger.improvements i on i.id = e.improvement_id
  left join policy.clients k on k.id = e.client_id
  where e.improvement_id = improvement_events_of.improvement and e.tainted_at is null
    and e.compartments <@ v_clearance and policy.label_key(e.compartments) = any (v_keys)
    and i.tainted_at is null and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys)
  order by e.created_at, e.id collate "C"
  limit 200;
end
$$;

CREATE FUNCTION ledger.improvement_label(improvement_id text) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_clearance text[];
  v_keys text[];
begin
  select r.clearance into v_clearance from ledger.agent_mail_reader('update_improvement') r;
  v_keys := policy.clearance_keys();
  return (select ledger.label(i.compartments) from ledger.improvements i
          where i.id = improvement_label.improvement_id and i.tainted_at is null
            and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys));
end
$$;

CREATE FUNCTION ledger.improvement_status(improvement_id text, clearance text[], keys text[]) RETURNS TABLE(status text, duplicate_of text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce(e.status, 'open'), e.duplicate_of
  from (select 1) one
  left join lateral (
    select x.status, x.duplicate_of from ledger.improvement_events x
    where x.improvement_id = improvement_status.improvement_id and x.event = 'status' and x.tainted_at is null
      and x.compartments <@ improvement_status.clearance and policy.label_key(x.compartments) = any (improvement_status.keys)
    order by x.created_at desc, x.id collate "C" desc limit 1
  ) e on true
$$;

CREATE FUNCTION ledger.judge_time_proposal(p_ids text[], p_request_id text, p_session_id text, p_proposal text, p_project_id text) RETURNS TABLE(code text, ruling_ids text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
  v_found text[];
  v_project text;
  v_label text[];
  v_stretch record;
  v_n integer := 0;
begin
  select c.client_id, c.clearance into v_caller, v_clearance from ledger.agent_mail_caller('judge_time_proposal', p_session_id) c;
  if p_ids is null or cardinality(p_ids) = 0 or exists (select 1 from unnest(p_ids) as x where x is null or x !~ '^atr_[0-9A-HJKMNP-TV-Z]{26}$')
     or p_request_id is null or p_request_id !~ '^[A-Za-z0-9_-]{8,64}$'
     or p_proposal is null or p_proposal !~ '^tpr_[0-9A-HJKMNP-TV-Z]{26}$' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  perform ledger.lock_rows(array['agent_ruling ' || v_caller || ' ' || p_request_id]);
  v_found := array(select r.id from knowledge.agent_time_rulings r
                   where r.client_id = v_caller and r.request_id = p_request_id and r.tool = 'judge_time_proposal'
                   order by r.from_at, r.id collate "C");
  if cardinality(v_found) > 0 then
    return query select 'ok'::text, v_found;
    return;
  end if;
  select t.project_id into v_project from knowledge.time_rulings t
  where t.proposal_id = p_proposal and t.source = 'system' and t.lifted_at is null and t.pending_card is null
    and t.project_id is not null
    and t.compartments <@ v_clearance and policy.label_key(t.compartments) = any (v_keys)
  order by t.from_at, t.id collate "C" limit 1;
  if v_project is null then
    return query select 'not_found'::text, null::text[];
    return;
  end if;
  select p.compartments into v_label from knowledge.projects p
  where p.id = coalesce(p_project_id, v_project) and p.status = 'active'
    and p.compartments <@ v_clearance and policy.label_key(p.compartments) = any (v_keys);
  if v_label is null then
    return query select 'not_found'::text, null::text[];
    return;
  end if;
  for v_stretch in
    select t.from_at, t.to_at from knowledge.time_rulings t
    where t.proposal_id = p_proposal and t.source = 'system' and t.lifted_at is null and t.pending_card is null
      and t.compartments <@ v_clearance and policy.label_key(t.compartments) = any (v_keys)
    order by t.from_at, t.id collate "C"
  loop
    v_n := v_n + 1;
    if v_n > cardinality(p_ids) then
      raise exception 'invalid request' using errcode = '22023';
    end if;
    if ledger.time_vetoed(coalesce(p_project_id, v_project), v_stretch.from_at, v_stretch.to_at, v_clearance, v_keys) then
      raise exception 'vetoed' using errcode = 'PIT01';
    end if;
    insert into knowledge.agent_time_rulings (id, project_id, from_at, to_at, proposal_id, tool, client_id, request_id, created_at, compartments, reach)
    values (p_ids[v_n], coalesce(p_project_id, v_project), v_stretch.from_at, v_stretch.to_at, p_proposal, 'judge_time_proposal',
            v_caller, p_request_id, now(), ledger.label(v_label), ledger.label(v_clearance));
  end loop;
  return query select 'ok'::text, p_ids[1:v_n];
exception when sqlstate 'PIT01' then
  return query select 'not_found'::text, null::text[];
end
$_$;

CREATE FUNCTION ledger.keys_of(clearance text[]) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with c as (
    select keys_of.clearance as clearance
    where (select count(distinct one) from unnest(keys_of.clearance) as one) between 1 and 32
  )
  select coalesce(array_agg(k.key order by k.key collate "C"), '{}'::text[])
  from c cross join lateral (
    select l.key from policy.labels l where cardinality(l.compartments) > 0 and l.compartments <@ c.clearance
    union
    select policy.label_key(c.clearance)
  ) k
  where k.key is not null and k.key <> ''
$$;

CREATE FUNCTION ledger.known_issues(lim integer) RETURNS TABLE(id text, area text, status text, severity text, by_system boolean, compartments text[], title_enc jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_clearance text[];
  v_keys text[];
begin
  select r.clearance into v_clearance from ledger.agent_mail_reader('list_improvements') r;
  if known_issues.lim is null or known_issues.lim not between 1 and 20 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  return query
  select i.id, i.area, s.status, i.severity, i.created_by = 'system:measure', i.compartments, i.title_enc
  from ledger.improvements i
  cross join lateral (
    select x.status, x.client_id, x.fix_ref, x.created_at from ledger.improvement_events x
    where x.improvement_id = i.id and x.event = 'status' and x.tainted_at is null
      and x.compartments <@ v_clearance and policy.label_key(x.compartments) = any (v_keys)
    order by x.created_at desc, x.id collate "C" desc limit 1
  ) s
  where i.tainted_at is null and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys)
    and i.area in ('mcp', 'sources')
    and (s.status = 'in_progress'
         or (s.status = 'triaged' and (s.fix_ref is null or s.fix_ref = 'none:owners_to_change')))
    and exists (select 1 from policy.clients k cross join policy.work_settings w
                where k.id = s.client_id and k.status = 'active' and k.kind = 'agent'
                  and w.defect_role is not null and w.defect_role = any (k.roles))
  order by case i.severity when 'critical' then 0 when 'high' then 1 when 'medium' then 2 else 3 end,
    s.created_at desc, i.id collate "C"
  limit known_issues.lim;
end
$$;

CREATE FUNCTION ledger.label(compartments text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce(array_agg(distinct one collate "C" order by one collate "C"), '{}'::text[])
  from unnest(label.compartments) as one
$$;

CREATE FUNCTION ledger.lapse_client_leases(p_client text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_lapsed integer;
begin
  update queue.leases l set lease_until = now() - interval '1 second', preferred_until = null
  where l.holder = p_client and (l.lease_until >= now() or l.preferred_until >= now());
  get diagnostics v_lapsed = row_count;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'intention', i.id, 'cancelled', now(), 'system:work', i.compartments from ledger.intentions i
  where i.client_id = p_client
    and (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id order by r.id desc limit 1) = 'set';
  return v_lapsed;
end
$$;

CREATE FUNCTION ledger.lapse_held(opportunity_ids text[]) RETURNS TABLE(opportunity_id text, held boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('list_opportunities' = any (v_tools) or 'claim_opportunity' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  return query
    select o.id, ledger.lapse_held_from(o.id, v_caller)
    from ledger.opportunities o
    where o.id = any (lapse_held.opportunity_ids) and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys) and o.tainted_at is null
    order by o.id collate "C";
end
$$;

CREATE FUNCTION ledger.lapse_held_from(opportunity_id text, client_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_keys text[];
  v_event text;
  v_code text;
begin
  if not exists (select 1 from queue.leases l
                 join policy.clients h on h.id = l.holder and h.status = 'active'
                 where l.resource_kind = 'opportunity' and l.resource_id = lapse_held_from.opportunity_id
                   and l.holder <> lapse_held_from.client_id
                   and l.lease_until < now()
                   and (l.lease_until + interval '24 hours' > now() or ledger.check_back_holds(l.resource_id, l.holder))) then
    return false;
  end if;
  v_keys := ledger.keys_of((select k.compartments from policy.clients k where k.id = lapse_held_from.client_id));
  select r.event, r.code into v_event, v_code from ledger.record_events r
  where r.row_kind = 'opportunity' and r.row_id = lapse_held_from.opportunity_id and policy.label_key(r.compartments) = any (v_keys)
  order by r.id desc limit 1;
  return coalesce(v_event = 'claimed' or (v_event = 'go' and v_code is not distinct from 'lease_expired')
                  or (v_event = 'go' and ledger.check_back_holds(lapse_held_from.opportunity_id,
                        (select l.holder from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = lapse_held_from.opportunity_id))),
                  false);
end
$$;

CREATE FUNCTION ledger.lift_anchor(p_anchor text, p_request_id text, p_session_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
  v_row record;
begin
  select c.client_id, c.clearance into v_caller, v_clearance from ledger.agent_mail_caller('lift_anchor', p_session_id) c;
  if p_anchor is null or p_anchor !~ '^aan_[0-9A-HJKMNP-TV-Z]{26}$' or p_request_id is null or p_request_id !~ '^[A-Za-z0-9_-]{8,64}$' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  perform ledger.lock_rows(array[p_anchor]);
  select a.lifted_at, a.lifted_by into v_row from knowledge.agent_anchors a
  where a.id = p_anchor and a.client_id = v_caller
    and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys);
  if not found or (v_row.lifted_at is not null and v_row.lifted_by <> 'client:' || v_caller) then
    return 'not_found';
  end if;
  if v_row.lifted_at is null then
    update knowledge.agent_anchors set lifted_at = now(), lifted_by = 'client:' || v_caller where id = p_anchor;
  end if;
  return 'ok';
end
$_$;

CREATE FUNCTION ledger.lift_time_ruling(p_ruling text, p_request_id text, p_session_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
  v_row record;
begin
  select c.client_id, c.clearance into v_caller, v_clearance from ledger.agent_mail_caller('lift_time_ruling', p_session_id) c;
  if p_ruling is null or p_ruling !~ '^atr_[0-9A-HJKMNP-TV-Z]{26}$' or p_request_id is null or p_request_id !~ '^[A-Za-z0-9_-]{8,64}$' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  perform ledger.lock_rows(array[p_ruling]);
  select r.lifted_at, r.lifted_by into v_row from knowledge.agent_time_rulings r
  where r.id = p_ruling and r.client_id = v_caller
    and r.compartments <@ v_clearance and policy.label_key(r.compartments) = any (v_keys);
  if not found or (v_row.lifted_at is not null and v_row.lifted_by <> 'client:' || v_caller) then
    return 'not_found';
  end if;
  if v_row.lifted_at is null then
    update knowledge.agent_time_rulings set lifted_at = now(), lifted_by = 'client:' || v_caller where id = p_ruling;
  end if;
  return 'ok';
end
$_$;

CREATE FUNCTION ledger.list_ideas(lim integer) RETURNS TABLE(id text, filed_by text, created_at timestamp with time zone, latest_at timestamp with time zone, status text, compartments text[], body_enc jsonb, cited integer, evidence_kinds text[], evidence_at timestamp with time zone[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('list_ideas' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if list_ideas.lim is null or list_ideas.lim not between 1 and 50 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
    with seen as (
      select h.id, h.created_by, h.created_at, h.compartments, h.body_enc from ledger.hypotheses h
      where h.kind = 'idea' and h.tainted_at is null
        and h.compartments <@ v_clearance and policy.label_key(h.compartments) = any (v_keys)
    ),
    evidence as (
      select distinct on (b.row_id, b.ref_kind, b.ref_id) b.id, b.row_id, b.ref_kind, b.added_at from ledger.basis b
      where b.row_kind = 'hypothesis' and b.row_id in (select s.id from seen s) and b.tainted_at is null
        and b.compartments <@ v_clearance and policy.label_key(b.compartments) = any (v_keys)
      order by b.row_id, b.ref_kind, b.ref_id, b.added_at nulls last, b.id
    ),
    listed as (
      select s.id, s.created_by, s.created_at, s.compartments, s.body_enc,
        greatest(s.created_at, (select max(e.added_at) from evidence e where e.row_id = s.id)) as latest_at
      from seen s
    )
    select l.id,
      case when l.created_by = 'client:' || v_caller then 'you' when starts_with(l.created_by, 'run:') then 'planner' else 'agent' end,
      l.created_at, l.latest_at,
      coalesce((select r.event from ledger.record_events r where r.row_kind = 'hypothesis' and r.row_id = l.id
                and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1), 'open'),
      l.compartments, l.body_enc,
      (select count(*)::int from evidence e where e.row_id = l.id),
      array(select e.ref_kind from evidence e where e.row_id = l.id order by e.added_at desc nulls last, e.id desc limit 20),
      array(select e.added_at from evidence e where e.row_id = l.id order by e.added_at desc nulls last, e.id desc limit 20)
    from listed l
    order by l.latest_at desc, l.id collate "C" desc
    limit list_ideas.lim;
end
$$;

CREATE FUNCTION ledger.list_improvements(statuses text[], in_area text, improvement text, lim integer, mine boolean, after_rank integer DEFAULT NULL::integer, after_at text DEFAULT NULL::text, after_id text DEFAULT NULL::text) RETURNS TABLE(id text, kind text, area text, severity text, status text, duplicate_of text, by_name text, created_at timestamp with time zone, updated_at timestamp with time zone, reports integer, compartments text[], title_enc jsonb, detail_enc jsonb, evidence_enc jsonb, assignee_role text, cause text, cause_state text, held_by text, held_at timestamp with time zone, fix_ref text, sort_at text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_roles text[];
  v_keys text[];
begin
  select r.client_id, r.clearance, r.roles into v_caller, v_clearance, v_roles from ledger.agent_mail_reader('list_improvements') r;
  if list_improvements.lim is null or list_improvements.lim not between 1 and 50
     or (list_improvements.statuses is not null and not (list_improvements.statuses <@ array['open', 'triaged', 'in_progress', 'done', 'wont_do', 'duplicate']))
     or (list_improvements.after_rank is null) <> (list_improvements.after_at is null)
     or (list_improvements.after_rank is null) <> (list_improvements.after_id is null)
     or list_improvements.after_rank not between 0 and 3
     or list_improvements.after_at !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  return query
  with seen as (
    select i.*, s.status as now_status, s.duplicate_of as now_duplicate_of,
      greatest(i.created_at, (select max(e.created_at) from ledger.improvement_events e
                              where e.improvement_id = i.id and e.tainted_at is null and e.compartments <@ v_clearance
                                and policy.label_key(e.compartments) = any (v_keys))) as changed_at,
      1 + (select count(*)::integer from ledger.improvement_events e
           where e.improvement_id = i.id and e.event = 'reported' and e.tainted_at is null and e.compartments <@ v_clearance
             and policy.label_key(e.compartments) = any (v_keys)) as n_reports,
      case i.severity when 'critical' then 0 when 'high' then 1 when 'medium' then 2 else 3 end as rank
    from ledger.improvements i
    cross join lateral ledger.improvement_status(i.id, v_clearance, v_keys) s
    where i.tainted_at is null and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys)
      and (list_improvements.improvement is null or i.id = list_improvements.improvement)
      and (list_improvements.in_area is null or i.area = list_improvements.in_area)
      and (list_improvements.mine is not true or i.assignee_role = any (v_roles))
  )
  select x.id, x.kind, x.area, x.severity, x.now_status, x.now_duplicate_of, coalesce(k.name, 'system'), x.created_at, x.changed_at, x.n_reports,
    x.compartments, x.title_enc, x.detail_enc, x.evidence_enc,
    x.assignee_role, x.cause, x.cause_state, h.name, h.created_at, f.fix_ref,
    to_char(x.changed_at at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  from seen x left join policy.clients k on k.id = x.client_id
  left join lateral (
    select hk.name, e.created_at from ledger.improvement_events e join policy.clients hk on hk.id = e.client_id
    where x.now_status = 'in_progress' and e.improvement_id = x.id and e.event = 'status' and e.status = 'in_progress' and e.tainted_at is null
      and e.compartments <@ v_clearance and policy.label_key(e.compartments) = any (v_keys)
    order by e.created_at desc, e.id collate "C" desc limit 1
  ) h on true
  left join lateral (
    select e.fix_ref from ledger.improvement_events e
    where e.improvement_id = x.id and e.fix_ref is not null and e.tainted_at is null
      and e.compartments <@ v_clearance and policy.label_key(e.compartments) = any (v_keys)
    order by e.created_at desc, e.id collate "C" desc limit 1
  ) f on true
  where (list_improvements.statuses is null or x.now_status = any (list_improvements.statuses))
    and (list_improvements.after_rank is null
         or x.rank > list_improvements.after_rank
         or (x.rank = list_improvements.after_rank and x.changed_at < list_improvements.after_at::timestamptz)
         or (x.rank = list_improvements.after_rank and x.changed_at = list_improvements.after_at::timestamptz
             and x.id collate "C" > list_improvements.after_id))
  order by x.rank, x.changed_at desc, x.id collate "C"
  limit list_improvements.lim + 1;
end
$_$;

CREATE FUNCTION ledger.live_held_out_questions(session_id text) RETURNS TABLE(id text, class text, compartments text[], question_enc jsonb, key_enc jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_clearance text[];
  v_keys text[];
begin
  select c.clearance into v_clearance from ledger.agent_mail_caller('start_outcome_test', live_held_out_questions.session_id) c;
  v_keys := policy.clearance_keys();
  return query
  select distinct on (q.class) q.id, q.class, q.compartments, q.question_enc, q.key_enc
  from ledger.held_out_questions q
  where q.tainted_at is null and q.created_at > now() - interval '28 days'
    and q.compartments <@ v_clearance and policy.label_key(q.compartments) = any (v_keys)
  order by q.class, q.created_at desc, q.id collate "C";
end
$$;

CREATE FUNCTION ledger.lock_rows(row_ids text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  one text;
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
  for one in select distinct x collate "C" from unnest(lock_rows.row_ids) as x where x is not null order by 1 loop
    perform pg_advisory_xact_lock(hashtextextended(one, 0));
  end loop;
end
$$;

CREATE FUNCTION ledger.lock_send(send_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  perform ledger.lock_rows(
    (select array[d.id, d.opportunity_id] from ledger.sent_messages s join ledger.drafts d on d.id = s.draft_id where s.id = lock_send.send_id)
    || coalesce((select array_agg(x.one) from ledger.sent_messages s join ledger.cards c on c.kind = 'draft_waiting' and c.target_kind = 'draft' and c.target_id = s.draft_id
                 cross join lateral unnest(array[c.id, 'author:' || c.created_by]) as x (one)
                 where s.id = lock_send.send_id), '{}'::text[]));
end
$$;

CREATE FUNCTION ledger.mark_health_seen(card text, request_id text, session_id text) RETURNS TABLE(code text, seen_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
  v_by text;
  v_card ledger.cards;
  v_kind text;
  v_event text;
  v_event_by text;
  v_event_code text;
  v_event_at timestamptz;
  v_before_code text;
begin
  perform ledger.lock_rows('{}'::text[]);
  select c.client_id, c.clearance into v_caller, v_clearance
  from ledger.agent_mail_caller('mark_health_seen', mark_health_seen.session_id) c;
  if mark_health_seen.card is null or mark_health_seen.card !~ '^crd_[0-9A-HJKMNP-TV-Z]{26}$'
     or mark_health_seen.request_id is null or mark_health_seen.request_id !~ '^[A-Za-z0-9_-]{8,64}$' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  v_by := 'client:' || v_caller;
  select c.* into v_card from ledger.cards c
  where c.id = mark_health_seen.card and c.kind = 'box_health' and c.created_by = 'system:health'
    and c.tainted_at is null and c.compartments <@ v_clearance and policy.label_key(c.compartments) = any (v_keys);
  if not found then
    return query select 'not_found'::text, null::timestamptz;
    return;
  end if;
  perform ledger.lock_rows(array[v_card.id, 'author:' || v_card.created_by]);
  select r.event, r.by, r.code, r.at into v_event, v_event_by, v_event_code, v_event_at
  from ledger.record_events r where r.row_kind = 'card' and r.row_id = v_card.id order by r.id desc limit 1;
  if v_event = 'decided' and v_event_by = v_by and v_event_code = 'agent_seen' then
    return query select 'ok'::text, v_event_at;
    return;
  end if;
  if v_event is null or v_event not in ('pending', 'deferred') then
    return query select 'card_closed'::text, null::timestamptz;
    return;
  end if;
  v_kind := (regexp_match(v_card.case_key, '^box:([a-z_]+):'))[1];
  if v_kind is null
     or not (v_kind = any (array['silent', 'timed_out', 'failure_streak', 'stores_nothing', 'budget_stops',
                                 'extract_backlog', 'detector_stopped']))
     or exists (select 1 from ledger.record_events r where r.row_kind = 'card' and r.row_id = v_card.id and r.by = 'owner') then
    return query select 'owners_card'::text, null::timestamptz;
    return;
  end if;
  select e.code into v_before_code
  from ledger.cards p
  cross join lateral (select r.event, r.code from ledger.record_events r
                      where r.row_kind = 'card' and r.row_id = p.id order by r.id desc limit 1) e
  where p.case_key = v_card.case_key and p.kind = 'box_health' and p.created_by = 'system:health'
    and p.tainted_at is null and p.compartments <@ v_clearance and policy.label_key(p.compartments) = any (v_keys)
    and policy.label_key(p.compartments) = policy.label_key(v_card.compartments)
    and (p.created_at, p.id) < (v_card.created_at, v_card.id)
  order by p.created_at desc, p.id collate "C" desc limit 1;
  if v_before_code = 'agent_seen' then
    return query select 'came_back_after_seen'::text, null::timestamptz;
    return;
  end if;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, code)
  values ('card', v_card.id, 'decided', now(), v_by, v_card.compartments, mark_health_seen.session_id, 'agent_seen');
  perform ledger.admit_deferred(v_card.created_by);
  return query select 'ok'::text, now();
end
$_$;

CREATE FUNCTION ledger.match_outcomes(now timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  written integer;
  outputs integer;
  met integer;
begin
  perform ledger.lock_rows('{}'::text[]);

  with sends as (
    select s.id, s.source_account_id, coalesce(s.thread_fp, d.thread_fp) as thread_fp, s.recipient_fps, s.begun_at, s.compartments
    from ledger.sent_messages s
    join ledger.drafts d on d.id = s.draft_id
    where s.begun_at > match_outcomes.now - interval '30 days' and s.begun_at <= match_outcomes.now
      and s.tainted_at is null and d.tainted_at is null
      and (select r.event from ledger.record_events r where r.row_kind = 'send' and r.row_id = s.id order by r.id desc limit 1) is distinct from 'failed'
  ),
  replies as (
    select distinct on (m.id) s.id as send_id, m.id as ref_id, m.evidence_id, f.first_at, ledger.label(s.compartments || m.compartments || e.compartments) as compartments
    from sends s
    join vault.evidence_items e on e.source_account_id = s.source_account_id and e.thread_fp = s.thread_fp
    join knowledge.messages m on m.evidence_id = e.id
    cross join lateral (
      select min(x.observed_at) as first_at from vault.evidence_items x
      where x.source_account_id = e.source_account_id and x.source_item_fp = e.source_item_fp) f
    where s.thread_fp is not null
      and e.answers_system and not e.system_originated
      and m.direction = 'inbound' and not m.bulk and m.thread_fp is not null
      and m.sender_fp = any (s.recipient_fps)
      and not exists (select 1 from ledger.move_result_links l where l.ref_kind = 'message' and l.ref_id = m.id and l.result_kind = 'reply')
      and f.first_at > s.begun_at and f.first_at <= s.begun_at + interval '30 days' and f.first_at <= match_outcomes.now
    order by m.id, s.begun_at desc, s.id collate "C" desc
  ),
  meetings as (
    select distinct on (ev.id) s.id as send_id, ev.id as ref_id, ev.evidence_id, f.first_at,
      ledger.label(s.compartments || ev.compartments || e.compartments || array(
        select u.one from knowledge.event_participants p
        join knowledge.accounts a on a.entity_id = p.entity_id
        cross join lateral unnest(p.compartments || a.compartments) as u (one)
        where p.event_id = ev.id and a.value_fp = any (s.recipient_fps))) as compartments
    from sends s
    join knowledge.event_details dt on dt.starts_at > s.begun_at and dt.starts_at <= s.begun_at + interval '30 days' and not dt.cancelled
    join knowledge.events ev on ev.id = dt.event_id
    join vault.evidence_items e on e.id = ev.evidence_id
    cross join lateral (
      select min(x.observed_at) as first_at from vault.evidence_items x
      where x.source_account_id = e.source_account_id and x.source_item_fp = e.source_item_fp) f
    where f.first_at > s.begun_at and f.first_at <= s.begun_at + interval '30 days' and f.first_at <= match_outcomes.now
      and exists (select 1 from knowledge.event_participants p join knowledge.accounts a on a.entity_id = p.entity_id
                  where p.event_id = ev.id and a.value_fp = any (s.recipient_fps))
      and ledger.owner_backed('event', ev.id)
      and not exists (select 1 from ledger.move_result_links l where l.ref_kind = 'event' and l.ref_id = ev.id and l.result_kind = 'meeting')
    order by ev.id, s.begun_at desc, s.id collate "C" desc
  )
  insert into ledger.move_result_links (id, created_by, send_id, result_kind, ref_kind, ref_id, evidence_id, observed_at, compartments)
  select ledger.new_id('mrl'), 'system:outcomes', x.send_id, x.result_kind, x.ref_kind, x.ref_id, x.evidence_id, x.first_at, x.compartments
  from (
    select r.send_id, 'reply' as result_kind, 'message' as ref_kind, r.ref_id, r.evidence_id, r.first_at, r.compartments from replies r
    union all
    select g.send_id, 'meeting', 'event', g.ref_id, g.evidence_id, g.first_at, g.compartments from meetings g
  ) x
  on conflict do nothing;
  get diagnostics written = row_count;

  insert into ledger.work_watches (opportunity_id, created_by, kind, watch_key, account_id, evidence_id, compartments)
  select distinct on (c.opportunity_id, e.id) c.opportunity_id, 'system:owner_output', 'thread', c.watch_key, c.account_id, e.id,
    ledger.label(c.compartments || m.compartments || e.compartments)
  from ledger.outcome_channels(array(select distinct w.opportunity_id from ledger.work_watches w where w.kind = 'thread'), match_outcomes.now) c
  join vault.evidence_items e on e.source_account_id = c.account_id and e.thread_fp = c.watch_key
  join knowledge.messages m on m.evidence_id = e.id
  cross join lateral (
    select min(x.observed_at) as first_at from vault.evidence_items x
    where x.source_account_id = e.source_account_id and x.source_item_fp = e.source_item_fp) f
  where c.kind = 'thread' and m.direction = 'outbound' and not e.system_originated and not m.held
    and f.first_at >= c.began_at and (c.until is null or f.first_at <= c.until) and f.first_at <= match_outcomes.now
    and not exists (select 1 from ledger.work_watches x where x.opportunity_id = c.opportunity_id and x.evidence_id = e.id)
  order by c.opportunity_id, e.id;
  get diagnostics outputs = row_count;

  insert into ledger.outcome_links (opportunity_id, expected_outcome_id, evidence_id, kind, path, judge, attribution, applied, compartments)
  select distinct on (x.id) c.opportunity_id, x.id, e.id, 'met', 'watched', 'rule', 'caused', true,
    ledger.label(c.compartments || x.compartments || m.compartments || e.compartments || coalesce(a.compartments, '{}'::text[]))
  from ledger.outcome_channels(array(select distinct w.opportunity_id from ledger.work_watches w where w.kind = 'thread'), match_outcomes.now) c
  join ledger.expected_outcomes x on x.opportunity_id = c.opportunity_id and x.outcome_type = 'answered'
  join vault.evidence_items e on e.source_account_id = c.account_id and e.thread_fp = c.watch_key
  join knowledge.messages m on m.evidence_id = e.id
  left join lateral (
    select y.compartments from knowledge.accounts y
    where x.subject_kind = 'entity' and y.entity_id = x.subject_id and y.value_fp = m.sender_fp
    order by y.id collate "C" limit 1) a on true
  cross join lateral (
    select min(z.observed_at) as first_at from vault.evidence_items z
    where z.source_account_id = e.source_account_id and z.source_item_fp = e.source_item_fp) f
  where c.kind = 'thread' and c.moved_at is not null
    and m.direction = 'inbound' and not m.bulk and not m.held and not e.system_originated and m.sender_fp is not null
    and not exists (select 1 from vault.pipeline_items p where p.evidence_id = e.id and (p.withheld or p.waiting))
    and f.first_at > c.moved_at and (c.until is null or f.first_at <= c.until) and f.first_at <= match_outcomes.now
    and ((x.subject_kind = 'counterpart' and m.sender_fp = any (c.counterpart_fps)) or (x.subject_kind = 'entity' and a.compartments is not null))
    and not exists (select 1 from ledger.outcome_links l where l.expected_outcome_id = x.id and l.judge = 'rule' and l.tainted_at is null)
    and not exists (select 1 from ledger.outcome_links l where l.expected_outcome_id = x.id and l.evidence_id = e.id)
  order by x.id, f.first_at, e.id collate "C";
  get diagnostics met = row_count;
  return written + outputs + met;
end
$$;

CREATE FUNCTION ledger.meeting_caller(p_tool text, p_session_id text) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_views text[];
  v_tools text[];
begin
  select c.id, c.views, c.tools into v_caller, v_views, v_tools from policy.current_client() c;
  if v_caller is null or p_tool is null or not (p_tool = any (v_tools))
     or not ((case p_tool when 'read_meeting' then 'work' when 'get_evidence_span' then 'people' end) = any (v_views))
     or (p_tool = 'read_meeting' and policy.current_client_kind() is distinct from 'agent')
     or not exists (select 1 from ledger.sessions s where s.id = p_session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  return policy.client_clearance();
end
$$;

CREATE FUNCTION ledger.meeting_followup_gaps(at_time timestamp with time zone, ended_from timestamp with time zone) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if meeting_followup_gaps.at_time is null or meeting_followup_gaps.ended_from is null
     or meeting_followup_gaps.ended_from >= meeting_followup_gaps.at_time then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
  select 'meeting_followup'::text, v.id, ledger.label(v.compartments), null::text, 'event'::text, v.id, 'event'::text, v.id,
    d.ends_at, null::timestamptz, null::integer, null::integer
  from knowledge.events v
  join knowledge.event_details d on d.event_id = v.id and d.compartments <@ v.compartments
  where not d.cancelled and not d.all_day and coalesce(d.owner_response, 'accepted') = 'accepted' and not coalesce(d.recurring, false)
    and d.ends_at > meeting_followup_gaps.ended_from and d.ends_at <= meeting_followup_gaps.at_time
    and not policy.is_restricted(v.compartments)
    and exists (select 1 from knowledge.event_participants p join knowledge.entities e on e.id = p.entity_id and e.kind = 'person'
                where p.event_id = v.id and p.compartments <@ v.compartments)
    and not policy.vetoed(array['event'], array[v.id], 'research')
  order by d.ends_at, v.id;
end
$$;

CREATE FUNCTION ledger.meeting_transcript(p_session_id text, p_capture_id text, p_evidence_id text) RETURNS TABLE(capture_id text, evidence_id text, started_at timestamp with time zone, ended_at timestamp with time zone, compartments text[], facts_enc jsonb, evidence_compartments text[], blob_ref text, envelope jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_clearance text[];
  v_keys text[];
begin
  if (p_capture_id is null) = (p_evidence_id is null) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_clearance := ledger.meeting_caller(case when p_capture_id is null then 'get_evidence_span' else 'read_meeting' end, p_session_id);
  v_keys := policy.clearance_keys();
  if p_capture_id is not null then
    return query
      select k.id, k.evidence_id, k.started_at, k.ended_at, k.compartments, k.facts_enc, e.compartments, b.blob_ref, b.envelope
      from knowledge.captures k
      join vault.evidence_items e on e.id = k.evidence_id
      join vault.evidence_blobs b on b.blob_ref = e.blob_ref
      where k.id = p_capture_id and k.kind = 'meeting' and e.source_kind = 'transcript'
        and k.compartments <@ v_clearance and policy.label_key(k.compartments) = any (v_keys)
        and e.compartments <@ v_clearance and b.compartments <@ v_clearance;
  else
    return query
      select k.id, k.evidence_id, k.started_at, k.ended_at, k.compartments, k.facts_enc, e.compartments, b.blob_ref, b.envelope
      from knowledge.captures k
      join vault.evidence_items e on e.id = k.evidence_id
      join vault.evidence_blobs b on b.blob_ref = e.blob_ref
      where k.evidence_id = p_evidence_id and k.kind = 'meeting' and e.source_kind = 'transcript'
        and k.compartments <@ v_clearance and policy.label_key(k.compartments) = any (v_keys)
        and e.compartments <@ v_clearance and b.compartments <@ v_clearance;
  end if;
end
$$;

CREATE FUNCTION ledger.merge_audit_gaps(at_time timestamp with time zone, sample integer, days integer) RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_week text;
begin
  if merge_audit_gaps.at_time is null or merge_audit_gaps.sample is null or merge_audit_gaps.sample not between 1 and 100
     or merge_audit_gaps.days is null or merge_audit_gaps.days not between 1 and 365 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if coalesce((select s.identity_agents from policy.work_settings s), 'off') <> 'on' then
    return;
  end if;
  v_week := to_char(merge_audit_gaps.at_time at time zone 'UTC', 'IYYY"W"IW');
  return query
  with merges as (
    select r.ruling_id, ledger.label(d.compartments) as label, r.created_at,
      (select min(a.entity_id collate "C") from knowledge.accounts a join knowledge.entities e on e.id = a.entity_id and e.kind = 'person'
       where a.value_fp = r.a_fp and a.compartments <@ d.compartments) as entity
    from knowledge.identity_rulings r
    join knowledge.owner_decisions d on d.id = r.ruling_id
    where r.verdict = 'same' and r.lifted_at is null and d.kind = 'identity_policy'
      and d.details ->> 'basis' in ('contact', 'name', 'local_part', 'research_identifier', 'dream')
      and not policy.is_restricted(d.compartments)
  ),
  flags as (
    select left(o.gap_subject, 30) as ruling_id, o.gap_subject as subject, length(o.gap_subject) > 30 as is_second, o.compartments, o.created_at,
      (select e.event from ledger.record_events e where e.row_kind = 'opportunity' and e.row_id = o.id order by e.id desc limit 1)
        in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner') as is_open
    from ledger.opportunities o where o.gap_trigger = 'merge_audit'
  ),
  fresh as (
    select m.ruling_id, m.label, m.created_at, m.entity,
      row_number() over (partition by m.label order by md5(m.ruling_id || ' ' || v_week), m.ruling_id collate "C") as place
    from merges m
    where m.entity is not null and m.created_at >= merge_audit_gaps.at_time - make_interval(days => merge_audit_gaps.days)
      and not exists (select 1 from flags f where f.ruling_id = m.ruling_id)
      and not exists (select 1 from ledger.wrong_merge_reports w where m.ruling_id = any (w.cross_rulings) and w.compartments <@ m.label)
  )
  select 'merge_audit'::text, f.subject, m.label, null::text, 'entity'::text, m.entity, 'entity'::text, m.entity,
    m.created_at, null::timestamptz, null::integer, null::integer
  from merges m join flags f on f.ruling_id = m.ruling_id and f.is_open
  where m.entity is not null
    and (not f.is_second
         or exists (select 1 from ledger.wrong_merge_reports w
                    where w.state = 'open' and m.ruling_id = any (w.cross_rulings) and w.compartments <@ m.label))
  union all
  select 'merge_audit'::text, m.ruling_id || '_2', m.label, null::text, 'entity'::text, m.entity, 'entity'::text, m.entity,
    m.created_at, null::timestamptz, null::integer, null::integer
  from merges m
  where m.entity is not null
    and exists (select 1 from ledger.wrong_merge_reports w
                where w.state = 'open' and m.ruling_id = any (w.cross_rulings) and w.compartments <@ m.label)
    and not exists (select 1 from flags f where f.ruling_id = m.ruling_id and (f.is_open or f.is_second))
  union all
  select 'merge_audit'::text, f.ruling_id, f.label, null::text, 'entity'::text, f.entity, 'entity'::text, f.entity,
    f.created_at, null::timestamptz, null::integer, null::integer
  from fresh f
  where f.place <= merge_audit_gaps.sample - (select count(*) from flags g
                                              where g.compartments = f.label and not g.is_second
                                                and to_char(g.created_at at time zone 'UTC', 'IYYY"W"IW') = v_week)
  order by 2;
end
$$;

CREATE FUNCTION ledger.message_wakes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_client text;
  v_wrote boolean := false;
begin
  begin
    for v_client in
      select k.id from policy.clients k join policy.client_webhooks w on w.client_id = k.id
      where k.status = 'active' and k.kind = 'agent' and k.id <> new.client_id
        and ledger.agent_message_visible(new, k.id, k.compartments, k.roles, ledger.keys_of(k.compartments))
        and not exists (
          select 1 from ledger.batch_notices b
          where b.client_id = k.id and b.event = 'agent_message' and b.state in ('pending', 'delivered')
            and b.created_at > now() - interval '1 hour'
            and b.created_at > coalesce((select max(r.read_at) from ledger.agent_message_reads r
                                         join ledger.agent_messages m on m.id = r.message_id
                                         where r.client_id = k.id and m.client_id <> k.id), '-infinity'::timestamptz))
      order by k.id collate "C"
    loop
      insert into ledger.batch_notices (id, client_id, event, count) values (ledger.new_id('ntc'), v_client, 'agent_message', 1);
      v_wrote := true;
    end loop;
    if v_wrote then
      perform pg_notify('pi_work_notice', '');
    end if;
  exception when others then
    null;
  end;
  return null;
end
$$;

CREATE FUNCTION ledger.my_agent_record(p_at timestamp with time zone) RETURNS TABLE(done integer, used integer, raised integer, yes integer, no integer, deferred integer, by_agent integer, waiting integer, other integer, no_codes text[], overturned integer, refused integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select r.done, r.used, r.raised, r.yes, r.no, r.deferred, r.by_agent, r.waiting, r.other, r.no_codes,
    r.overturned, r.refused
  from policy.current_client() c
  cross join lateral ledger.agent_records_within(p_at, policy.client_clearance(), c.id) r
$$;

CREATE FUNCTION ledger.my_bets(p_at timestamp with time zone) RETURNS TABLE(open integer, used integer, unused integer, placed integer, earned integer, taken_back integer, budget integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select b.open, b.used, b.unused, b.placed, b.earned, b.taken_back, b.budget
  from policy.current_client() c
  cross join lateral ledger.bets_within(p_at, policy.client_clearance(), c.id) b
$$;

CREATE FUNCTION ledger.my_standing(p_at timestamp with time zone) RETURNS TABLE(placed integer, earned integer, taken_back integer, asked integer, paid integer, refused integer, refusals jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select b.placed, b.earned, b.taken_back, q.asked, q.paid, q.refused, q.refusals
  from policy.current_client() c
  cross join lateral ledger.bets_within(p_at, policy.client_clearance(), c.id) b
  cross join lateral ledger.agent_questions_within(p_at - interval '7 days' + interval '1 microsecond', p_at + interval '1 microsecond',
    policy.client_clearance(), c.id) q
$$;

CREATE FUNCTION ledger.new_id(prefix text) RETURNS text
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select new_id.prefix || '_'
    || (select string_agg(substr('0123456789ABCDEFGHJKMNPQRSTVWXYZ', ((t.ms >> (5 * (9 - i))) & 31)::integer + 1, 1), '' order by i)
        from (select floor(extract(epoch from clock_timestamp()) * 1000)::bigint as ms) t, generate_series(0, 9) as i)
    || (select string_agg(substr('0123456789ABCDEFGHJKMNPQRSTVWXYZ', (get_byte(r.bytes, p.pos) & 31) + 1, 1), '' order by p.n)
        from (select uuid_send(gen_random_uuid()) || uuid_send(gen_random_uuid()) as bytes) r,
             unnest(array[0, 1, 2, 3, 4, 5, 7, 9, 10, 11, 12, 13, 14, 15, 16, 17]) with ordinality as p (pos, n))
$$;

CREATE FUNCTION ledger.next_run(request_id text, session_id text) RETURNS TABLE(run_id text, attempt integer, compartments text[], max_turns integer, max_tool_calls integer, max_output_tokens integer, max_input_code_points integer, ceiling_microusd_per_token integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_author text;
  v_label text[];
  v_run text;
  v_attempt integer;
  v_attempt_label text[];
  v_run_label text[];
  v_keys text[];
  v_day date := (now() at time zone 'UTC')::date;
  v_planner text;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('next_run' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'reasoner'
     or not exists (select 1 from ledger.sessions s where s.id = next_run.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  perform ledger.lock_rows(array['run_queue']);

  select a.run_id, a.attempt, a.compartments into v_run, v_attempt, v_attempt_label
  from ledger.run_attempts a where a.client_id = v_caller and a.request_id = next_run.request_id;
  if v_run is not null then
    if (select r.event from ledger.record_events r where r.row_kind = 'run' and r.row_id = v_run and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) = 'running'
       and v_attempt = (select max(a.attempt) from ledger.run_attempts a where a.run_id = v_run)
       and exists (select 1 from queue.leases l where l.resource_kind = 'run' and l.resource_id = v_run and l.holder = v_caller) then
      return query select v_run, v_attempt, v_attempt_label, s.max_turns, s.max_tool_calls, s.max_output_tokens, s.max_input_code_points,
        s.ceiling_microusd_per_token from policy.work_settings s;
    end if;
    return;
  end if;
  if coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on'
     or ledger.spend_on(v_day) >= (select s.max_microusd_per_day from policy.work_settings s) then
    return;
  end if;
  v_planner := (select s.planner from policy.work_settings s);
  select r.id into v_run from ledger.runs r
  where r.tainted_at is null and r.compartments <@ v_clearance and policy.label_key(r.compartments) = any (v_keys)
    and (select e.event from ledger.record_events e where e.row_kind = 'run' and e.row_id = r.id and policy.label_key(e.compartments) = any (v_keys) order by e.id desc limit 1) = 'queued'
    and (select count(*) from ledger.run_attempts a where a.run_id = r.id) < 2
    and (v_planner is distinct from 'research_only' or r.prompt_id = 'personal_lessons')
  order by r.created_at, r.id collate "C" limit 1;
  if v_run is null then
    return;
  end if;
  perform ledger.lock_rows(array[v_run]);
  if (select e.event from ledger.record_events e where e.row_kind = 'run' and e.row_id = v_run and policy.label_key(e.compartments) = any (v_keys) order by e.id desc limit 1) is distinct from 'queued' then
    return;
  end if;
  v_attempt := coalesce((select max(a.attempt) from ledger.run_attempts a where a.run_id = v_run), 0) + 1;
  v_run_label := (select r.compartments from ledger.runs r where r.id = v_run);
  insert into ledger.run_attempts (run_id, attempt, request_id, created_by, session_id, compartments, client_id, taken_at, erasure_mark)
  values (v_run, v_attempt, next_run.request_id, v_author, next_run.session_id, v_label, v_caller, now(),
          (select greatest(coalesce(max(x.journal_seq), 0), coalesce(max(x.lift_seq), 0)) from knowledge.erasures x));
  insert into queue.leases as l (resource_kind, resource_id, holder, lease_until, first_taken_at, preferred_until)
  values ('run', v_run, v_caller, now() + interval '2400 seconds', now(), null)
  on conflict (resource_kind, resource_id) do update
    set holder = excluded.holder, lease_until = excluded.lease_until, first_taken_at = excluded.first_taken_at, preferred_until = null;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
  values ('run', v_run, 'running', now(), v_author, v_run_label, next_run.session_id);
  return query select v_run, v_attempt, v_label, s.max_turns, s.max_tool_calls, s.max_output_tokens, s.max_input_code_points,
    s.ceiling_microusd_per_token from policy.work_settings s;
end
$$;

CREATE FUNCTION ledger.note_model_exposure(model_id text, prompt_id text, evidence_ids text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  written integer;
begin
  if note_model_exposure.model_id is null or note_model_exposure.prompt_id is null then
    raise exception 'a model id and a prompt id' using errcode = '23514';
  end if;
  if note_model_exposure.evidence_ids is null or cardinality(note_model_exposure.evidence_ids) not between 1 and 50
     or array_position(note_model_exposure.evidence_ids, null) is not null then
    raise exception 'one to fifty evidence ids' using errcode = '23514';
  end if;
  if exists (select 1 from unnest(note_model_exposure.evidence_ids) as e(id) where e.id !~ '^[0-9a-f]{64}$') then
    raise exception 'not an evidence id' using errcode = '23514';
  end if;
  if exists (select 1 from unnest(note_model_exposure.evidence_ids) as e(id)
             where not exists (select 1 from vault.evidence_items v where v.id = e.id)) then
    raise exception 'no such evidence' using errcode = '23503';
  end if;
  insert into ledger.exposures (recipient_kind, recipient, route, ref_kind, ref, day, retention, compartments)
  select 'model', note_model_exposure.model_id, note_model_exposure.prompt_id, 'evidence', v.id,
         (now() at time zone 'utc')::date, 'unknown', v.compartments
  from vault.evidence_items v
  where v.id = any (note_model_exposure.evidence_ids)
  on conflict on constraint exposures_once do nothing;
  get diagnostics written = row_count;
  return written;
end
$_$;

CREATE FUNCTION ledger.notice_current(notice_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce((select n.state = 'pending'
                     and case when n.event = 'outcome'
                              then ledger.outcome_notice_due(n.opportunity_id, n.client_id)
                                   and exists (select 1 from ledger.outcome_links l join policy.clients k on k.id = n.client_id
                                               where l.id = n.outcome_link_id and l.tainted_at is null
                                                 and l.compartments <@ k.compartments and policy.label_key(l.compartments) = any (ledger.keys_of(k.compartments)))
                              else ledger.notice_due(n.opportunity_id, n.client_id) end
                   from ledger.work_notices n where n.id = notice_current.notice_id and n.client_id is not null), false)
$$;

CREATE FUNCTION ledger.notice_due(opportunity_id text, client_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select not exists (select 1 from ledger.work_declines d
                     where d.opportunity_id = notice_due.opportunity_id and d.client_id = notice_due.client_id and d.expires_at > now())
    and not exists (select 1 from queue.leases l
                    where l.resource_kind = 'opportunity' and l.resource_id = notice_due.opportunity_id
                      and l.holder = notice_due.client_id and l.lease_until >= now() and l.preferred_until is null)
    and ledger.claimable_by(notice_due.opportunity_id, notice_due.client_id)
$$;

CREATE FUNCTION ledger.notice_due_at() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  new.due_at := (select o.due_at from ledger.opportunities o where o.id = new.opportunity_id);
  return new;
end
$$;

CREATE FUNCTION ledger.notify_agent_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  perform pg_notify('pi_agent_write', '');
  return null;
end
$$;

CREATE FUNCTION ledger.opportunity_facts(p_id text, p_at timestamp with time zone) RETURNS TABLE(id text, status text, kind text, proposed_by_class text, bet boolean, about_owner boolean, owner_hypothesis boolean, vetoed boolean, card_pending boolean, ever_carded boolean, closed_by text, closed_at timestamp with time zone, new_source_ref boolean, intents jsonb, basis jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_row record;
  v_closed_at timestamptz;
  v_closes boolean;
  v_closed_by text;
begin
  if p_id is null or p_at is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  select x.* into v_row from (
    select o.id, o.kind, o.case_id, o.about_kind, o.proposed_by_class,
      o.bet_at is not null and o.created_by like 'client:%' as bet,
      coalesce((select h.about_owner from ledger.hypotheses h where h.id = o.hypothesis_id), o.hypothesis_id is not null) as owner_hypothesis,
      policy.vetoed_by(
        (case when o.about_kind = 'owner' then '{}'::text[] else array[o.about_kind] end)
          || array(select b.ref_kind from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = o.id order by b.id),
        (case when o.about_kind = 'owner' then '{}'::text[] else array[o.about_id] end)
          || array(select b.ref_id from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = o.id order by b.id),
        o.kind) is not null as vetoed,
      exists (select 1 from ledger.cards c where c.case_key = o.case_id
              and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1)
                  in ('pending', 'deferred')) as card_pending,
      exists (select 1 from ledger.cases k join ledger.cases s on s.row_kind = k.row_kind and s.kind = k.kind
                and s.about_kind is not distinct from k.about_kind and s.about_id is not distinct from k.about_id
              join ledger.cards c on c.case_key = s.id
              where k.id = o.case_id) as ever_carded,
      (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id order by r.id desc limit 1) as status,
      (select d.check_back_at from ledger.opportunity_decisions d where d.opportunity_id = o.id order by d.id desc limit 1) as check_back_at
    from ledger.opportunities o where o.id = p_id and o.tainted_at is null
  ) x
  where (x.status = 'proposed' and not x.card_pending) or (x.status = 'later' and x.check_back_at <= p_at);
  if v_row.id is null then
    return;
  end if;
  select closings.at, closings.closes, closings.by into v_closed_at, v_closes, v_closed_by from (
    select d.created_at as at, d.decision = 'no_go' as closes, 'owner'::text as by
    from ledger.opportunity_decisions d join ledger.opportunities o on o.id = d.opportunity_id
    where o.case_id = v_row.case_id and d.decided_by = 'owner'
    union all
    select r.at, true, 'expiry' from ledger.cards c
    join lateral (select e.event, e.at from ledger.record_events e where e.row_kind = 'card' and e.row_id = c.id order by e.id desc limit 1) r on true
    where c.case_key = v_row.case_id and r.event = 'expired'
  ) closings order by closings.at desc limit 1;
  return query select v_row.id, v_row.status, v_row.kind, v_row.proposed_by_class, v_row.bet, v_row.about_kind = 'owner',
    v_row.owner_hypothesis, v_row.vetoed, v_row.card_pending, v_row.ever_carded,
    case when v_closes then v_closed_by end,
    case when v_closes then v_closed_at end,
    case when v_closes then exists (
      select 1 from ledger.basis b
      where b.row_kind = 'opportunity' and b.row_id = v_row.id and b.source_class = 'source'
        and not exists (
          select 1 from ledger.basis b2 join ledger.opportunities other on other.id = b2.row_id
          where b2.row_kind = 'opportunity' and other.case_id = v_row.case_id and other.id <> v_row.id
            and b2.ref_kind = b.ref_kind and b2.ref_id = b.ref_id)) end,
    coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'mode', i.mode, 'maxOpen', i.max_open,
                'open', (select count(*)::int from ledger.opportunities o
                         where (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id order by r.id desc limit 1)
                               in ('go', 'claimed')
                           and (select d.intent_id from ledger.opportunity_decisions d where d.opportunity_id = o.id order by d.id desc limit 1) = i.id),
                'activeClients', (select count(*)::int from policy.clients c where c.id = any (i.client_ids) and c.status = 'active' and c.kind = 'agent'))
              order by i.confirmed_at, i.id collate "C")
              from policy.intents i
              where i.confirmed_at is not null and i.revoked_at is null and v_row.kind = any (i.opportunity_kinds) and not i.for_tasks),
             '[]'::jsonb),
    coalesce((select jsonb_agg(jsonb_build_object('refKind', b.ref_kind, 'sourceClass', b.source_class, 'ownerBacked', b.owner_backed,
                'tainted', b.tainted_at is not null, 'flagged', ledger.basis_flagged(array[b.ref_kind], array[b.ref_id]),
                'threadFp', m.thread_fp, 'isAbout', coalesce(b.ref_kind = o.about_kind and b.ref_id = o.about_id, false))
              order by b.id)
              from ledger.basis b
              left join knowledge.messages m on b.ref_kind = 'message' and m.id = b.ref_id
              left join ledger.opportunities o on o.id = b.row_id
              where b.row_kind = 'opportunity' and b.row_id = v_row.id),
             '[]'::jsonb);
end
$$;

CREATE FUNCTION ledger.opportunity_tainted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  update ledger.work_notices n set state = 'stale' where n.opportunity_id = new.id and n.state = 'pending';
  delete from ledger.work_declines d where d.opportunity_id = new.id;
  return null;
end
$$;

CREATE FUNCTION ledger.outcome_channels(opportunity_ids text[], at timestamp with time zone) RETURNS TABLE(opportunity_id text, kind text, account_id text, watch_key text, began_at timestamp with time zone, until timestamp with time zone, moved_at timestamp with time zone, counterpart_fps text[], compartments text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with latest as (
    select o.id, o.compartments, r.event, r.at as event_at
    from ledger.opportunities o
    left join lateral (
      select e.event, e.at from ledger.record_events e where e.row_kind = 'opportunity' and e.row_id = o.id order by e.id desc limit 1) r on true
    where o.id = any (outcome_channels.opportunity_ids) and o.tainted_at is null and not policy.is_restricted(o.compartments)
  ),
  open_work as (
    select l.id, l.compartments, case when coalesce(ledger.closes_work(l.event), false) then l.event_at + interval '90 days' end as until
    from latest l
    where not coalesce(ledger.closes_work(l.event), false) or l.event_at + interval '90 days' > outcome_channels.at
  ),
  watched as (
    select distinct on (x.opportunity_id, x.kind, x.account_id, x.watch_key) x.opportunity_id, x.kind, x.account_id, x.watch_key, x.until, x.compartments
    from ledger.work_watches x join open_work w on w.id = x.opportunity_id
    where not policy.is_restricted(x.compartments)
    order by x.opportunity_id, x.kind, x.account_id, x.watch_key, x.id desc
  ),
  sends as (
    select d.opportunity_id, s.source_account_id as account_id, coalesce(s.thread_fp, d.thread_fp) as thread_fp, s.begun_at, s.recipient_fps,
      s.compartments || d.compartments as compartments
    from ledger.sent_messages s join ledger.drafts d on d.id = s.draft_id join open_work w on w.id = d.opportunity_id
    where s.tainted_at is null and d.tainted_at is null and coalesce(s.thread_fp, d.thread_fp) is not null
      and exists (select 1 from ledger.record_events r where r.row_kind = 'send' and r.row_id = s.id and r.event = 'sent')
  ),
  outputs as (
    select x.opportunity_id, x.account_id, x.watch_key as thread_fp, min(f.first_at) as first_at
    from ledger.work_watches x join open_work w on w.id = x.opportunity_id
    join vault.evidence_items e on e.id = x.evidence_id
    cross join lateral (
      select min(y.observed_at) as first_at from vault.evidence_items y
      where y.source_account_id = e.source_account_id and y.source_item_fp = e.source_item_fp) f
    where x.created_by = 'system:owner_output' and x.kind = 'thread'
    group by x.opportunity_id, x.account_id, x.watch_key
  )
  select w.id, null::text, null::text, null::text, null::timestamptz, w.until, null::timestamptz, '{}'::text[], w.compartments
  from open_work w
  union all
  select v.opportunity_id, v.kind, v.account_id, v.watch_key,
    least((select min(x.created_at) from ledger.work_watches x
           where x.opportunity_id = v.opportunity_id and x.kind = v.kind and x.watch_key = v.watch_key and x.account_id is not distinct from v.account_id),
          t.first_send),
    v.until,
    case when v.kind = 'thread' then least(t.first_send, u.first_at) end,
    coalesce(p.fps, '{}'::text[]),
    ledger.label(v.compartments || coalesce(p.compartments, '{}'::text[]))
  from watched v
  left join lateral (
    select min(s.begun_at) as first_send from sends s
    where v.kind = 'thread' and s.opportunity_id = v.opportunity_id and s.account_id = v.account_id and s.thread_fp = v.watch_key) t on true
  left join outputs u on v.kind = 'thread' and u.opportunity_id = v.opportunity_id and u.account_id = v.account_id and u.thread_fp = v.watch_key
  left join lateral (
    select array_agg(distinct q.fp order by q.fp) as fps, array_agg(distinct q.one order by q.one) as compartments
    from (
      select r.fp, c.one from sends s cross join lateral unnest(s.recipient_fps) as r (fp) cross join lateral unnest(s.compartments) as c (one)
      where s.opportunity_id = v.opportunity_id and s.account_id = v.account_id and s.thread_fp = v.watch_key
      union all
      select m.sender_fp, c.one from vault.evidence_items e join knowledge.messages m on m.evidence_id = e.id
      cross join lateral unnest(m.compartments || e.compartments) as c (one)
      where u.first_at is not null and e.source_account_id = v.account_id and e.thread_fp = v.watch_key
        and m.direction = 'inbound' and not m.bulk and m.sender_fp is not null and e.observed_at < u.first_at
    ) q
    where v.kind = 'thread') p on true
$$;

CREATE FUNCTION ledger.outcome_links_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_needed text[] := '{}'::text[];
  v_goal text;
begin
  if new.opportunity_id is not null then
    select o.compartments, o.goal_id into v_needed, v_goal from ledger.opportunities o where o.id = new.opportunity_id;
  end if;
  new.goal_id := v_goal;
  if new.expected_outcome_id is not null
     and not exists (select 1 from ledger.expected_outcomes x where x.id = new.expected_outcome_id and x.opportunity_id is not distinct from new.opportunity_id) then
    raise exception 'an expectation of another work' using errcode = '23514';
  end if;
  v_needed := coalesce(v_needed, '{}'::text[])
    || coalesce((select s.compartments from ledger.sent_messages s where s.id = new.send_id), '{}'::text[])
    || coalesce((select e.compartments from vault.evidence_items e where e.id = new.evidence_id), '{}'::text[]);
  if cardinality(new.compartments) > 0 and not (new.compartments @> v_needed) then
    raise exception 'a link label must cover its evidence and its work' using errcode = '23514';
  end if;
  return new;
end
$$;

CREATE FUNCTION ledger.outcome_links_gone() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_gone bigint[];
  v_works text[];
begin
  if tg_op = 'DELETE' then
    select coalesce(array_agg(o.id), '{}'::bigint[]), coalesce(array_agg(distinct o.opportunity_id) filter (where o.opportunity_id is not null), '{}'::text[])
    into v_gone, v_works from old_rows o;
  else
    select coalesce(array_agg(n.id), '{}'::bigint[]), coalesce(array_agg(distinct n.opportunity_id) filter (where n.opportunity_id is not null), '{}'::text[])
    into v_gone, v_works from new_rows n join old_rows o on o.id = n.id where o.tainted_at is null and n.tainted_at is not null;
  end if;
  if cardinality(v_gone) = 0 then
    return null;
  end if;
  update ledger.outcome_assessments a set tainted_at = now()
  where a.tainted_at is null and a.outcome_link_ids && array(select g::text from unnest(v_gone) as g);
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'opportunity', o.id, case p.event when 'claimed' then 'go' else p.event end, now(), 'system:taint', o.compartments
  from ledger.opportunities o
  cross join lateral (select e.id, e.event, e.by from ledger.record_events e where e.row_kind = 'opportunity' and e.row_id = o.id order by e.id desc limit 1) l
  cross join lateral (select e.event from ledger.record_events e
                      where e.row_kind = 'opportunity' and e.row_id = o.id and e.id < l.id and e.event not in ('outcome_met', 'outcome_not_met')
                      order by e.id desc limit 1) p
  where o.id = any (v_works) and o.tainted_at is null
    and l.by = 'system:outcomes' and l.event in ('outcome_met', 'outcome_not_met')
    and not exists (select 1 from ledger.outcome_links k
                    where k.opportunity_id = o.id and k.kind = case l.event when 'outcome_met' then 'met' else 'not_met' end
                      and k.applied and k.tainted_at is null and k.move_result_link_id is null);
  return null;
end
$$;

CREATE FUNCTION ledger.outcome_links_raise() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  insert into ledger.trigger_log (fact_key_fp, clearance_key, state_fp, raise, cause, compartments, outcome_link_id)
  select n.opportunity_id, policy.label_key(n.compartments), encode(sha256(convert_to('outcome:' || n.id::text, 'UTF8')), 'hex'), 'outcome', 'outcome', n.compartments, n.id
  from new_rows n
  where (n.applied or n.judge like 'model:%')
    and n.tainted_at is null and n.opportunity_id is not null and n.move_result_link_id is null and not policy.is_restricted(n.compartments)
  order by n.id
  on conflict do nothing;
  return null;
end
$$;

CREATE FUNCTION ledger.outcome_notice(opportunity_id text, link_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_link ledger.outcome_links%rowtype;
  v_client text;
  v_clearance text[];
  v_tier text;
  v_kind text;
  v_role text;
  v_ref_kind text;
  v_ref_id text;
begin
  select l.* into v_link from ledger.outcome_links l
  where l.id = outcome_notice.link_id and l.opportunity_id = outcome_notice.opportunity_id
    and l.applied and l.tainted_at is null and l.move_result_link_id is null;
  if v_link.id is null then
    return null;
  end if;
  v_client := (select substr(r.by, 8) from ledger.record_events r
               where r.row_kind = 'opportunity' and r.row_id = outcome_notice.opportunity_id and r.event = 'claimed' and r.by like 'client:%'
               order by r.id desc limit 1);
  select k.compartments into v_clearance from policy.clients k where k.id = v_client;
  if v_client is null or not ledger.outcome_notice_due(outcome_notice.opportunity_id, v_client)
     or not (v_link.compartments <@ v_clearance and policy.label_key(v_link.compartments) = any (ledger.keys_of(v_clearance)))
     or not exists (select 1 from policy.client_webhooks w where w.client_id = v_client) then
    return null;
  end if;
  select 'message', m.id into v_ref_kind, v_ref_id from knowledge.messages m
  where m.evidence_id = v_link.evidence_id and m.compartments <@ v_clearance order by m.id collate "C" limit 1;
  if v_ref_id is null then
    select 'event', e.id into v_ref_kind, v_ref_id from knowledge.events e
    where e.evidence_id = v_link.evidence_id and e.compartments <@ v_clearance order by e.id collate "C" limit 1;
  end if;
  select o.tier, o.kind into v_tier, v_kind from ledger.opportunities o where o.id = outcome_notice.opportunity_id;
  v_role := case when v_tier = 'task' then ledger.route_of(outcome_notice.opportunity_id)
    else (select i.role from policy.intents i
          where i.id = (select d.intent_id from ledger.opportunity_decisions d where d.opportunity_id = outcome_notice.opportunity_id order by d.id desc limit 1)) end;
  insert into ledger.work_notices (id, client_id, opportunity_id, event, tier, kind, role, txid, outcome_kind, outcome_link_id, outcome_ref_kind, outcome_ref_id)
  values (ledger.new_id('ntc'), v_client, outcome_notice.opportunity_id, 'outcome', v_tier, v_kind, v_role, txid_current(),
          v_link.kind, v_link.id, v_ref_kind, v_ref_id)
  on conflict (client_id, opportunity_id, txid) do nothing;
  perform pg_notify('pi_work_notice', '');
  return v_client;
end
$$;

CREATE FUNCTION ledger.outcome_notice_due(opportunity_id text, client_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select exists (
    select 1 from policy.clients k join ledger.opportunities o on o.id = outcome_notice_due.opportunity_id
    where k.id = outcome_notice_due.client_id and k.status = 'active' and k.kind = 'agent' and 'work' = any (k.views)
      and o.tainted_at is null and o.compartments <@ k.compartments and policy.label_key(o.compartments) = any (ledger.keys_of(k.compartments))
      and (select r.by from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id and r.event = 'claimed'
           order by r.id desc limit 1) = 'client:' || k.id)
$$;

CREATE FUNCTION ledger.owner_backed(ref_kind text, ref_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select case owner_backed.ref_kind
    when 'message' then coalesce((
      select m.direction = 'outbound' and not m.bulk and not e.system_originated and not e.answers_system
      from knowledge.messages m join vault.evidence_items e on e.id = m.evidence_id
      where m.id = owner_backed.ref_id), false)
    when 'event' then coalesce((
      select coalesce(d.owner_response = 'accepted', false) or coalesce(e.sender_member = 'm-owner', false)
      from knowledge.events ev
      join vault.evidence_items e on e.id = ev.evidence_id
      left join knowledge.event_details d on d.event_id = ev.id
      where ev.id = owner_backed.ref_id), false)
    else false
  end
$$;

CREATE FUNCTION ledger.owner_close_improvement(improvement_id text, event_id text, request_id text, status text, duplicate_of text, note_enc jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_row ledger.improvements%rowtype;
begin
  if owner_close_improvement.status is null or owner_close_improvement.status not in ('wont_do', 'duplicate')
     or (owner_close_improvement.status = 'duplicate') <> (owner_close_improvement.duplicate_of is not null)
     or owner_close_improvement.duplicate_of = owner_close_improvement.improvement_id then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  select i.* into v_row from ledger.improvements i where i.id = owner_close_improvement.improvement_id and i.tainted_at is null;
  if v_row.id is null
     or (owner_close_improvement.duplicate_of is not null
         and not exists (select 1 from ledger.improvements i where i.id = owner_close_improvement.duplicate_of and i.tainted_at is null)) then
    return null;
  end if;
  insert into ledger.improvement_events (id, improvement_id, request_id, created_by, compartments, event, status, duplicate_of, note_enc)
  values (owner_close_improvement.event_id, v_row.id, owner_close_improvement.request_id, 'owner', v_row.compartments, 'status',
          owner_close_improvement.status, owner_close_improvement.duplicate_of, owner_close_improvement.note_enc);
  return owner_close_improvement.status;
end
$$;

CREATE FUNCTION ledger.owner_queue_label(p_subject text) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select min(x.label) from (
    select distinct ledger.label(k.compartments) as label from policy.work_settings s
    join policy.clients k on k.status = 'active' and k.kind = 'agent' and s.question_role = any (k.roles) and 'work' = any (k.views)
    where s.owner_page_host is not null and s.question_role is not null
      and p_subject = 'owner_queue_' || to_char(now() at time zone 'UTC', 'YYYYMMDD') || '_'
                      || left(md5(array_to_string(ledger.label(k.compartments), ',')), 8)) x
  having count(*) = 1
$$;

CREATE FUNCTION ledger.owner_queue_question(p_opportunity text, attempts boolean) RETURNS TABLE(kind text, n integer, host text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_keys text[];
  v_clearance text[];
  v_client text;
  v_label text[];
begin
  v_keys := policy.clearance_keys();
  v_clearance := policy.client_clearance();
  v_client := (select k.id from policy.current_client() k);
  select o.compartments into v_label from ledger.opportunities o
  where v_client is not null and o.id = p_opportunity and o.gap_trigger = 'owner_queue' and o.tainted_at is null
    and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)
    and exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = o.id
                and l.holder = v_client and l.lease_until >= now());
  if v_label is null or owner_queue_question.attempts is null then
    return;
  end if;
  return query
  select null::text, 0, s.owner_page_host from policy.work_settings s
  union all
  select c.kind, count(*)::integer, null::text
  from ledger.cards c
  where c.compartments <@ v_label and ledger.owner_queue_waits(c, now(), owner_queue_question.attempts)
  group by c.kind;
end
$$;

CREATE FUNCTION ledger.owner_queue_state(at_time timestamp with time zone, attempts boolean) RETURNS TABLE(host text, label text[], subject text, waiting integer, ended_today boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_day text;
begin
  if owner_queue_state.at_time is null or owner_queue_state.attempts is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_day := 'owner_queue_' || to_char(owner_queue_state.at_time at time zone 'UTC', 'YYYYMMDD');
  return query
  with s as (
    select w.owner_page_host as host, w.question_role as role from policy.work_settings w
    where w.owner_page_host is not null and w.question_role is not null),
  labels as (
    select distinct ledger.label(k.compartments) as label from policy.clients k cross join s
    where k.status = 'active' and k.kind = 'agent' and s.role = any (k.roles) and 'work' = any (k.views)),
  old_today as (
    select o.id, o.compartments,
      (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id order by r.id desc limit 1)
        in ('proposed', 'later', 'go', 'claimed') as open,
      exists (select 1 from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id and r.event = 'done') as told
    from ledger.opportunities o
    where o.gap_trigger = 'owner_queue' and o.gap_subject = v_day and o.tainted_at is null),
  entries as (
    select l.label, v_day || '_' || left(md5(array_to_string(l.label, ',')), 8) as subject, false as old from labels l
    union all
    select t.compartments, v_day, true from old_today t where t.open)
  select s.host, r.label, r.subject,
    (select count(*)::integer from ledger.cards c
     where c.compartments <@ r.label and ledger.owner_queue_waits(c, owner_queue_state.at_time, owner_queue_state.attempts)),
    not r.old and (exists (select 1 from old_today t where t.open or t.told)
                   or exists (select 1 from ledger.opportunities o
                              where o.gap_trigger = 'owner_queue' and o.gap_subject = r.subject and o.compartments = r.label
                                and exists (select 1 from ledger.record_events e
                                            where e.row_kind = 'opportunity' and e.row_id = o.id and e.event = 'done')))
  from s cross join entries r;
end
$$;

CREATE FUNCTION ledger.owner_queue_waits(c ledger.cards, at_time timestamp with time zone, attempts boolean) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce(p.event = 'pending'
    and not exists (select 1 from unnest(c.compartments) as x where not (x <> 'canary' and not starts_with(x, 'agent:canary-')))
    and ((c.kind <> 'box_health' or starts_with(coalesce(c.case_key, ''), 'box:hold:') or c.created_at <= at_time - make_interval(hours => 24)) and not (((c.kind in ('opportunity_decision', 'lesson', 'client_preference', 'owner_question', 'idea', 'about_you')
      and c.created_at > at_time - make_interval(hours => 48)
      and (c.expires_at is null or c.expires_at >= c.created_at + make_interval(hours => 48))
    and (c.expires_after_days is null or c.expires_after_days * 24 >= 48)
      and (c.kind <> 'opportunity_decision'
           or (c.target_kind = 'opportunity'
               and exists (select 1 from ledger.opportunities rt
                           where rt.id = c.target_id and rt.tier = 'task' and rt.tainted_at is null and rt.gap_trigger is null
                             and (rt.due_at is null or rt.due_at >= c.created_at + make_interval(hours => 48))))))
     or (c.kind in ('same_fact', 'time_effort', 'tier_proposal', 'agent_claim')
         and c.created_at > at_time - make_interval(hours => 96)
         and (c.expires_at is null or c.expires_at >= c.created_at + make_interval(hours => 96))
    and (c.expires_after_days is null or c.expires_after_days * 24 >= 96)
         and not (c.target_kind = 'opportunity'
                  and exists (select 1 from ledger.opportunities rt where rt.id = c.target_id and rt.gap_trigger is not null))))
    and not exists (select 1 from ledger.record_events re
                    where re.row_kind = 'card' and re.row_id = c.id and re.by = 'owner' and re.at <= at_time)
    and (exists (select 1 from ledger.opportunities ro
   where ro.gap_trigger = 'card_relay' and ro.gap_subject = c.id and ro.created_at <= at_time
     and ro.compartments <@ c.compartments and ro.tainted_at is null
                   and (select rr.event from ledger.record_events rr
                        where rr.row_kind = 'opportunity' and rr.row_id = ro.id and rr.at <= at_time
                        order by rr.id desc limit 1) in ('proposed', 'later', 'go', 'claimed')
                   and (ro.created_at > at_time - make_interval(hours => 6)
                        or (select rr.event from ledger.record_events rr
                            where rr.row_kind = 'opportunity' and rr.row_id = ro.id and rr.at <= at_time
                            order by rr.id desc limit 1) = 'claimed'))
      or (exists (select 1 from policy.work_settings rs where rs.question_role is not null)
          and not exists (select 1 from ledger.opportunities ro
   where ro.gap_trigger = 'card_relay' and ro.gap_subject = c.id and ro.created_at <= at_time
     and ro.compartments <@ c.compartments)
          and ((c.kind in ('opportunity_decision', 'lesson', 'client_preference', 'owner_question', 'idea', 'about_you')
                and c.created_at > at_time - make_interval(mins => 15))
            or (c.kind in ('same_fact', 'time_effort', 'tier_proposal', 'agent_claim')
                and (exists (select 1 from ledger.opportunities qa
   where qa.gap_trigger = 'card_question' and qa.gap_subject = c.id and qa.created_at <= at_time
     and qa.compartments <@ c.compartments
                               and (select qr.at from ledger.record_events qr
                                    where qr.row_kind = 'opportunity' and qr.row_id = qa.id and qr.at <= at_time
                                    order by qr.id desc limit 1) > at_time - make_interval(mins => 15)
                               and (select qr.event from ledger.record_events qr
                                    where qr.row_kind = 'opportunity' and qr.row_id = qa.id and qr.at <= at_time
                                    order by qr.id desc limit 1) not in ('proposed', 'later', 'go', 'claimed'))
                  or (not exists (select 1 from ledger.opportunities qa
   where qa.gap_trigger = 'card_question' and qa.gap_subject = c.id and qa.created_at <= at_time
     and qa.compartments <@ c.compartments)
                      and c.created_at <= at_time - make_interval(mins => 15)
                      and c.created_at > at_time - make_interval(mins => 30))
                  or (c.created_at <= at_time - make_interval(hours => 48)
                      and c.created_at > at_time - make_interval(hours => 48) - make_interval(mins => 15)))))))))
    and (not attempts or not (c.kind in ('same_fact', 'shared_address', 'time_effort', 'tier_proposal', 'relation_audit', 'agent_claim')
    and c.created_at > at_time - make_interval(hours => 48)
    and not exists (select 1 from ledger.record_events oe
                    where oe.row_kind = 'card' and oe.row_id = c.id and oe.by = 'owner' and oe.at <= at_time)
    and (exists (select 1 from ledger.opportunities ao
   where ao.gap_trigger = 'card_question' and ao.gap_subject = c.id and ao.created_at <= at_time
     and ao.compartments <@ c.compartments and ao.tainted_at is null
                   and (select ar.event from ledger.record_events ar
                        where ar.row_kind = 'opportunity' and ar.row_id = ao.id and ar.at <= at_time
                        order by ar.id desc limit 1) in ('proposed', 'later', 'go', 'claimed'))
      or (c.created_at > at_time - make_interval(mins => 15)
          and exists (select 1 from policy.intents ai where ai.for_tasks and ai.confirmed_at is not null and ai.revoked_at is null)
          and not exists (select 1 from ledger.opportunities ao
   where ao.gap_trigger = 'card_question' and ao.gap_subject = c.id and ao.created_at <= at_time
     and ao.compartments <@ c.compartments)))))
    and coalesce(c.expires_at, p.at + make_interval(days => c.expires_after_days), 'infinity'::timestamptz) > at_time, false)
  from (select r.event, r.at from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) p
$$;

CREATE FUNCTION ledger.owner_request_taken_in() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  update ledger.basis b set evidence_id = new.evidence_id
  where b.ref_kind = 'owner_request' and b.ref_id = new.id and b.evidence_id is null and b.tainted_at is null;
  return null;
end
$$;

CREATE FUNCTION ledger.owner_retire_learning(learning_id text, lift boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_retired timestamptz;
begin
  if owner_retire_learning.lift is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform ledger.lock_rows(array[owner_retire_learning.learning_id]);
  select l.retired_at into v_retired from ledger.agent_learnings l
  where l.id = owner_retire_learning.learning_id and l.tainted_at is null;
  if not found then
    return null;
  end if;
  if (v_retired is null) = owner_retire_learning.lift then
    return 'unchanged';
  end if;
  update ledger.agent_learnings l
     set retired_at = case when owner_retire_learning.lift then null else now() end,
         retired_by = case when owner_retire_learning.lift then null else 'owner' end
   where l.id = owner_retire_learning.learning_id;
  return 'ok';
end
$$;

CREATE FUNCTION ledger.owner_task(id text, request_id text, kind text, role text, about_kind text, about_id text, body_enc jsonb, ref_kinds text[], ref_ids text[], compartments text[], ruling_id text) RETURNS TABLE(opportunity_id text, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_label text[];
  v_found text;
  v_intent text;
  v_case text;
  v_goal text;
begin
  if owner_task.id is null or owner_task.id !~ '^opp_[0-9A-HJKMNP-TV-Z]{26}$'
     or owner_task.request_id is null or owner_task.request_id !~ '^[A-Za-z0-9_-]{8,64}$'
     or owner_task.kind is null or not ledger.task_kind(owner_task.kind)
     or owner_task.role is null or owner_task.role !~ '^[a-z][a-z0-9-]{1,31}$'
     or owner_task.about_kind is null or owner_task.about_kind not in ('owner', 'message', 'event', 'entity', 'goal')
     or (owner_task.about_kind = 'owner') <> (owner_task.about_id is null)
     or owner_task.body_enc is null or jsonb_typeof(owner_task.body_enc) <> 'object'
     or coalesce(cardinality(owner_task.ref_kinds), 0) > 20
     or coalesce(cardinality(owner_task.ref_kinds), 0) <> coalesce(cardinality(owner_task.ref_ids), 0)
     or coalesce(cardinality(owner_task.compartments), 0) = 0
     or owner_task.ruling_id is null
     or not exists (select 1 from knowledge.owner_decisions d where d.id = owner_task.ruling_id and d.kind = 'task_add' and d.target_id = owner_task.id) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_label := ledger.label(owner_task.compartments);
  if policy.is_restricted(v_label) then
    raise exception 'a restricted label' using errcode = '22023';
  end if;
  perform ledger.lock_rows(array['owner task ' || owner_task.request_id]);

  select o.id into v_found from ledger.opportunities o where o.created_by = 'owner' and o.request_id = owner_task.request_id;
  if v_found is not null then
    return query select v_found, (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = v_found order by r.id desc limit 1);
    return;
  end if;

  if not exists (select 1 from policy.clients k where k.status = 'active' and k.kind = 'agent' and (owner_task.role = any (k.roles) or owner_task.role = k.name)) then
    raise exception 'unknown role' using errcode = 'PIW04';
  end if;
  v_intent := (select i.id from policy.intents i where i.for_tasks and i.confirmed_at is not null and i.revoked_at is null
               order by i.confirmed_at desc, i.id collate "C" desc limit 1);
  if v_intent is null or coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on' then
    raise exception 'the task tier is off' using errcode = '42501';
  end if;
  if policy.vetoed(
       case when owner_task.about_kind = 'owner' then '{}'::text[] else array[owner_task.about_kind] end || coalesce(owner_task.ref_kinds, '{}'::text[]),
       case when owner_task.about_kind = 'owner' then '{}'::text[] else array[owner_task.about_id] end || coalesce(owner_task.ref_ids, '{}'::text[]),
       owner_task.kind) then
    raise exception 'vetoed' using errcode = 'PIT01';
  end if;

  v_goal := case when owner_task.about_kind = 'goal' then owner_task.about_id
    else (select r.id from unnest(owner_task.ref_kinds, owner_task.ref_ids) with ordinality as r (kind, id, ord)
          where r.kind = 'goal' order by r.ord limit 1) end;
  insert into ledger.cases (id, request_id, created_by, compartments, row_kind, kind, about_kind, about_id, author)
  values ('cas_' || substr(owner_task.id, 5), owner_task.request_id, 'owner', v_label, 'opportunity', owner_task.kind, owner_task.about_kind, owner_task.about_id, 'owner')
  on conflict do nothing;
  select k.id into v_case from ledger.cases k
  where k.row_kind = 'opportunity' and k.kind = owner_task.kind and k.about_kind = owner_task.about_kind
    and k.about_id is not distinct from owner_task.about_id and k.hypothesis_id is null and k.author = 'owner' and k.compartments = v_label;
  insert into ledger.opportunities (id, request_id, created_by, compartments, body_enc, case_id, kind, about_kind, about_id, goal_id,
    proposed_by_class, tier, role)
  values (owner_task.id, owner_task.request_id, 'owner', v_label, owner_task.body_enc, v_case, owner_task.kind, owner_task.about_kind,
          owner_task.about_id, v_goal, 'owner', 'task', owner_task.role);
  if not ledger.add_basis('opportunity', owner_task.id, v_label, owner_task.ref_kinds, owner_task.ref_ids, v_label) then
    raise exception 'a ref is not visible under the label' using errcode = 'PIW01';
  end if;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  values ('opportunity', owner_task.id, 'proposed', now(), 'owner', v_label);
  insert into ledger.opportunity_decisions (request_id, created_by, compartments, opportunity_id, decision, decided_by, rung, reason, intent_id, ruling_id)
  values (owner_task.request_id, 'owner', v_label, owner_task.id, 'go', 'owner', 4, 'owner_task', v_intent, owner_task.ruling_id);
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  values ('opportunity', owner_task.id, 'go', clock_timestamp(), 'owner', v_label);
  return query select owner_task.id, 'go'::text;
end
$_$;

CREATE FUNCTION ledger.pair_shape(p_a text, p_b text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select 'same_person:' ||
    case
      when exists (select 1 from knowledge.contact_addresses x join knowledge.contact_addresses y on y.contact_id = x.contact_id
                   where x.entity_id = p_a and y.entity_id = p_b) then 'contact'
      when exists (select 1 from knowledge.accounts a join knowledge.aliases l on l.entity_id = p_b and l.value_fp = any (a.local_name_fps) where a.entity_id = p_a)
        or exists (select 1 from knowledge.accounts a join knowledge.aliases l on l.entity_id = p_a and l.value_fp = any (a.local_name_fps) where a.entity_id = p_b) then 'local_part'
      when exists (select 1 from knowledge.aliases x join knowledge.aliases y on y.value_fp = x.value_fp where x.entity_id = p_a and y.entity_id = p_b) then 'name'
      else 'other'
    end || ':' ||
    (select count(*)::text from unnest(array[p_a, p_b]) as side (entity)
     where exists (select 1 from knowledge.contact_addresses c where c.entity_id = side.entity)
        or exists (select 1 from knowledge.accounts a join vault.sent_recipients s on s.address_fp = a.value_fp where a.entity_id = side.entity))
$$;

CREATE FUNCTION ledger.pay_question(session_id text, opportunity_id text, tools text[], sources text[], mark boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_keys text[];
  v_label text[];
begin
  select c.id, c.compartments, c.views into v_caller, v_clearance, v_views from policy.current_client() c;
  if v_caller is null or not ('work' = any (v_views)) or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = pay_question.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if pay_question.mark is null
     or coalesce(cardinality(pay_question.tools), 0) not between 1 and 5 or array_position(pay_question.tools, null) is not null
     or coalesce(cardinality(pay_question.sources), 0) not between 1 and 10 or array_position(pay_question.sources, null) is not null
     or exists (select 1 from unnest(pay_question.tools) t (name)
                where t.name not in ('search', 'find_messages', 'find_facts', 'find_documents', 'find_records', 'find_paths', 'get_timeline', 'build_context_pack', 'context')) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  if pay_question.mark then
    perform ledger.lock_rows(array(select o.id from ledger.opportunities o
                                   where o.id = pay_question.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)));
  end if;
  select o.compartments into v_label from ledger.opportunities o
  where o.id = pay_question.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys) and o.tainted_at is null;
  if v_label is null then
    return 'unseen';
  end if;
  if not ledger.tried_holds(v_caller, pay_question.tools, pay_question.sources, v_label) then
    return 'unpaid';
  end if;
  if pay_question.mark then
    update ledger.opportunities o
    set question_tools = pay_question.tools, question_sources = pay_question.sources, question_paid_at = now()
    where o.id = pay_question.opportunity_id;
  end if;
  return 'paid';
end
$$;

CREATE FUNCTION ledger.ping_batch_at(p_now timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select case when t > p_now then t else t + interval '1 day' end
  from (select (date_trunc('day', p_now at time zone 'UTC') + make_interval(hours => s.ping_batch_hour)) at time zone 'UTC' as t
        from policy.work_settings s) x
$$;

CREATE FUNCTION ledger.ping_clients(p_item text, p_setter text, p_route text, p_self text, p_place integer) RETURNS TABLE(client_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_order text[];
begin
  if p_setter is not null then
    return query select p_setter where ledger.notice_due(p_item, p_setter)
      and exists (select 1 from policy.client_webhooks w join policy.clients k on k.id = w.client_id and k.status = 'active' where w.client_id = p_setter);
    return;
  end if;
  if p_place is not null and p_place > 0 then
    v_order := (select s.ping_order from policy.work_settings s);
    return query select t.client_id from ledger.ping_place_agents(v_order[p_place]) t
      join policy.client_webhooks w on w.client_id = t.client_id
      where t.client_id is distinct from p_self and ledger.notice_due(p_item, t.client_id);
    return;
  end if;
  return query
    select w.client_id
    from policy.client_webhooks w join policy.clients k on k.id = w.client_id and k.status = 'active'
    where w.client_id is distinct from p_self and ledger.notice_due(p_item, w.client_id);
end
$$;

CREATE FUNCTION ledger.ping_next_place(p_item text, p_self text, p_after integer) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_order text[];
  v_place integer;
begin
  v_order := coalesce((select s.ping_order from policy.work_settings s), '{}'::text[]);
  for v_place in greatest(p_after + 1, 1) .. coalesce(cardinality(v_order), 0) loop
    if exists (select 1 from ledger.ping_place_agents(v_order[v_place]) t
               where t.client_id is distinct from p_self and ledger.notice_due(p_item, t.client_id)) then
      return v_place;
    end if;
  end loop;
  return null;
end
$$;

CREATE FUNCTION ledger.ping_place_agents(p_place text) RETURNS TABLE(client_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select k.id from policy.clients k
  where k.status = 'active' and k.kind = 'agent'
    and case split_part(p_place, ':', 1)
          when 'role' then split_part(p_place, ':', 2) = any (k.roles)
          when 'client' then split_part(p_place, ':', 2) = k.name
          else false end
$$;

CREATE FUNCTION ledger.ping_walk(p_item text, p_rung integer, p_batched boolean) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  insert into ledger.ping_walks as w (opportunity_id, rung, told_at, batched)
  values (p_item, p_rung, case when p_batched then ledger.ping_batch_at(now()) else now() end, p_batched)
  on conflict (opportunity_id) do update set rung = excluded.rung, told_at = excluded.told_at, batched = excluded.batched
$$;

CREATE FUNCTION ledger.place_bet(session_id text, opportunity_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_name text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_bet_at timestamptz;
  v_found boolean;
  v_left integer;
  v_tier text;
  v_internal boolean;
begin
  select c.id, c.name, c.compartments, c.views, c.tools into v_caller, v_name, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('propose_task' = any (v_tools) or 'propose_opportunity' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = place_bet.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  perform ledger.lock_rows(array['bet ' || v_caller]);
  select true, o.bet_at, o.tier,
    o.kind <> 'owner_question' and not exists (select 1 from policy.stage_plan p where p.opportunity_kind = o.kind and not p.internal)
    into v_found, v_bet_at, v_tier, v_internal from ledger.opportunities o
  where o.id = place_bet.opportunity_id and o.created_by = 'client:' || v_caller and o.session_id = place_bet.session_id
    and ((o.tier = 'task' and o.role = v_name and 'propose_task' = any (v_tools))
         or (o.tier = 'opportunity' and o.proposed_by_class = 'client' and 'propose_opportunity' = any (v_tools)))
    and o.tainted_at is null
    and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys);
  if v_found is null then
    return 'unseen';
  end if;
  if v_bet_at is not null then
    return 'placed';
  end if;
  if v_tier = 'opportunity' and not v_internal then
    return 'needs_owner';
  end if;
  select b.budget - b.placed into v_left from ledger.bets_within(now(), v_clearance, v_caller) b;
  if coalesce(v_left, 0) <= 0 then
    return 'spent';
  end if;
  update ledger.opportunities o set bet_at = now() where o.id = place_bet.opportunity_id;
  return 'placed';
end
$$;

CREATE FUNCTION ledger.place_work(p_opportunity_id text, p_session_id text, p_project_id text, p_blocked_by text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_work record;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not (v_tools && array['propose_task', 'propose_opportunity']) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = p_session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if coalesce(cardinality(p_blocked_by), 0) > 10 or array_position(p_blocked_by, null) is not null
     or (select count(distinct b) from unnest(p_blocked_by) as b) is distinct from coalesce(cardinality(p_blocked_by), 0)::bigint
     or p_opportunity_id = any (coalesce(p_blocked_by, '{}'::text[])) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  select o.id, o.tier, o.compartments, o.created_at, o.session_id into v_work
  from ledger.opportunities o
  where o.id = p_opportunity_id and o.created_by = 'client:' || v_caller and o.tainted_at is null
    and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys);
  if not found then
    return null;
  end if;
  if v_work.created_at <> now() or v_work.session_id is distinct from p_session_id then
    return 'kept';
  end if;
  if coalesce(cardinality(p_blocked_by), 0) > 0 and v_work.tier <> 'task' then
    raise exception 'only a task waits on other work' using errcode = '22023';
  end if;
  if p_project_id is not null
     and not exists (select 1 from knowledge.projects p
                     where p.id = p_project_id and p.status = 'active'
                       and p.compartments <@ v_clearance and policy.label_key(p.compartments) = any (v_keys)) then
    return null;
  end if;
  if exists (select 1 from unnest(coalesce(p_blocked_by, '{}'::text[])) as b (id)
             where not exists (select 1 from ledger.opportunities o
                               where o.id = b.id and o.tainted_at is null and o.compartments <@ v_work.compartments
                                 and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys))) then
    return null;
  end if;
  perform ledger.lock_rows(array[p_opportunity_id, p_project_id]);
  if p_project_id is not null then
    update ledger.opportunities set project_id = p_project_id where id = p_opportunity_id;
    update knowledge.projects p set updated_at = now() where p.id = p_project_id and v_work.compartments <@ p.compartments;
  end if;
  insert into ledger.work_dependencies (opportunity_id, blocked_by, compartments)
  select p_opportunity_id, b.id, v_work.compartments
  from unnest(coalesce(p_blocked_by, '{}'::text[])) as b (id) order by b.id collate "C";
  return 'placed';
end
$$;

CREATE FUNCTION ledger.plan_move(move_id text, opportunity_id text, stage text, request_id text, session_id text, point_version integer, definition_hash text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_author text;
  v_label text[];
  v_found text;
  v_kind text;
  v_about_kind text;
  v_about_id text;
  v_compartments text[];
  v_tainted timestamptz;
  v_hypothesis text;
  v_gap text;
  v_status text;
  v_decision_id bigint;
  v_decision text;
  v_decided_by text;
  v_intent text;
  v_intent_ok boolean;
  v_intent_kinds text[];
  v_intent_clients text[];
  v_intent_role text;
  v_mode text;
  v_next text;
  v_internal boolean;
  v_broken text;
  v_replay boolean;
  v_assignment text;
  v_keys text[];
  v_tier text;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('plan_move' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = plan_move.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if plan_move.stage is null or plan_move.stage not in ('investigate', 'prepare', 'draft', 'send', 'pay') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  perform ledger.lock_rows(array(select o.id from ledger.opportunities o
                                 where o.id = plan_move.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)));

  select m.id into v_found from ledger.moves m where m.created_by = v_author and m.request_id = plan_move.request_id;
  if v_found is not null then
    return v_found;
  end if;
  v_replay := exists (select 1 from ledger.decision_point_calls d where d.created_by = v_author and d.request_id = plan_move.request_id);

  select o.kind, o.about_kind, o.about_id, o.compartments, o.tainted_at, o.hypothesis_id, o.gap_trigger, o.tier
  into v_kind, v_about_kind, v_about_id, v_compartments, v_tainted, v_hypothesis, v_gap, v_tier
  from ledger.opportunities o where o.id = plan_move.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys);
  v_status := (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = plan_move.opportunity_id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1);
  select d.id, d.decision, d.decided_by, d.intent_id into v_decision_id, v_decision, v_decided_by, v_intent
  from ledger.opportunity_decisions d where d.opportunity_id = plan_move.opportunity_id and policy.label_key(d.compartments) = any (v_keys) order by d.id desc limit 1;
  if v_tier = 'task' then
    select i.id into v_intent from policy.intents i where i.for_tasks
    order by (i.revoked_at is null) desc, i.confirmed_at desc, i.id collate "C" desc limit 1;
  end if;
  select i.confirmed_at is not null and i.revoked_at is null, i.opportunity_kinds, i.client_ids, i.role into v_intent_ok, v_intent_kinds, v_intent_clients, v_intent_role
  from policy.intents i where i.id = v_intent;
  v_next := (select p.stage from policy.stage_plan p
             where p.opportunity_kind = v_kind
               and not exists (select 1 from ledger.moves m where m.opportunity_id = plan_move.opportunity_id and m.stage = p.stage and policy.label_key(m.compartments) = any (v_keys)
                               and (select r.event from ledger.record_events r where r.row_kind = 'move' and r.row_id = m.id and r.event <> 'reported' and policy.label_key(r.compartments) = any (v_keys)
                                    order by r.id desc limit 1) = 'done')
             order by p.ordinal limit 1);
  v_internal := (select p.internal from policy.stage_plan p where p.opportunity_kind = v_kind and p.stage = plan_move.stage);

  v_broken := case
    when coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on' then 'kill_switch'
    when v_kind is null or v_status is distinct from 'claimed'
      or not exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = plan_move.opportunity_id
                     and l.holder = v_caller and l.lease_until >= now()) then 'no_lease'
    when v_decision is distinct from 'go' then 'not_go'
    when v_intent is null or v_intent_ok is null then 'no_intent'
    when not v_intent_ok then 'intent_revoked'
    when not (v_kind = any (v_intent_kinds)) then 'kind_not_listed'
    when v_tier is distinct from 'task' and not (v_caller = any (v_intent_clients)
      or (v_intent_role is not null and exists (select 1 from policy.clients k where k.id = v_caller and v_intent_role = any (k.roles))))
      then 'client_not_listed'
    when not exists (select 1 from policy.harness_modes h where h.client_id = v_caller and h.opportunity_kind = v_kind
                     and h.stage = plan_move.stage and h.revoked_at is null) then 'no_harness_mode'
    when not exists (select 1 from policy.harness_modes h where h.client_id = v_caller and h.opportunity_kind = v_kind
                     and h.stage = plan_move.stage and h.revoked_at is null and h.mode = 'act') then 'not_act'
    when v_next is distinct from plan_move.stage then 'not_next_stage'
    when v_internal is not true then 'not_internal'
    when v_tier = 'task' and plan_move.stage not in ('investigate', 'prepare') then 'not_internal'
    when (v_tier = 'task' or v_decided_by = 'agent') and ledger.basis_flagged(
          array(select b.ref_kind from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = plan_move.opportunity_id and policy.label_key(b.compartments) = any (v_keys)),
          array(select b.ref_id from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = plan_move.opportunity_id and policy.label_key(b.compartments) = any (v_keys))) then 'untrusted_basis'
    when v_decided_by = 'policy' and v_gap is null and v_tier is distinct from 'task' and not (
        exists (select 1 from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = plan_move.opportunity_id and policy.label_key(b.compartments) = any (v_keys)
                and b.source_class = 'source' and ledger.owner_backed(b.ref_kind, b.ref_id))
        and not exists (
          select 1 from ledger.basis b
          where b.row_kind = 'opportunity' and b.row_id = plan_move.opportunity_id and b.ref_kind = 'event' and policy.label_key(b.compartments) = any (v_keys)
            and b.source_class = 'source' and not ledger.owner_backed(b.ref_kind, b.ref_id)
            and not (v_about_kind = 'event' and b.ref_id = v_about_id))
        and not exists (
          select 1 from ledger.basis b join knowledge.messages m on m.id = b.ref_id
          where b.row_kind = 'opportunity' and b.row_id = plan_move.opportunity_id and b.ref_kind = 'message' and policy.label_key(b.compartments) = any (v_keys) and policy.label_key(m.compartments) = any (v_keys)
            and b.source_class in ('source', 'system') and not ledger.owner_backed(b.ref_kind, b.ref_id)
            and not exists (
              select 1 from ledger.basis b2 join knowledge.messages m2 on m2.id = b2.ref_id
              where b2.row_kind = 'opportunity' and b2.row_id = plan_move.opportunity_id and b2.ref_kind = 'message' and policy.label_key(b2.compartments) = any (v_keys) and policy.label_key(m2.compartments) = any (v_keys)
                and m2.thread_fp = m.thread_fp and ledger.owner_backed(b2.ref_kind, b2.ref_id)))
        and not ledger.basis_flagged(
          array(select b.ref_kind from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = plan_move.opportunity_id and policy.label_key(b.compartments) = any (v_keys)),
          array(select b.ref_id from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = plan_move.opportunity_id and policy.label_key(b.compartments) = any (v_keys)))) then 'untrusted_basis'
    when v_tainted is not null
      or exists (select 1 from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = plan_move.opportunity_id and policy.label_key(b.compartments) = any (v_keys) and b.tainted_at is not null) then 'tainted'
    when policy.vetoed(
       case when v_about_kind = 'owner' then '{}'::text[] else array[v_about_kind] end
         || array(select b.ref_kind from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = plan_move.opportunity_id order by b.id),
       case when v_about_kind = 'owner' then '{}'::text[] else array[v_about_id] end
         || array(select b.ref_id from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = plan_move.opportunity_id order by b.id),
       v_kind) then 'vetoed'
    when v_hypothesis is not null and coalesce((select h.about_owner from ledger.hypotheses h where h.id = v_hypothesis and policy.label_key(h.compartments) = any (v_keys)), true) then 'owner_hypothesis'
    else null
  end;

  if v_replay then
    if v_broken in ('kill_switch', 'not_go', 'no_intent', 'intent_revoked', 'kind_not_listed', 'client_not_listed', 'no_harness_mode', 'not_act', 'not_next_stage', 'not_internal') then
      return 'refused:' || v_broken;
    end if;
    return null;
  end if;

  if v_broken is null then
    select m.id into v_found from ledger.moves m
    where m.opportunity_id = plan_move.opportunity_id and m.stage = plan_move.stage and m.created_by = v_author
      and policy.label_key(m.compartments) = any (v_keys)
      and (select r.event from ledger.record_events r where r.row_kind = 'move' and r.row_id = m.id and r.event <> 'reported' and policy.label_key(r.compartments) = any (v_keys)
           order by r.id desc limit 1) = 'cleared'
    order by m.created_at desc, m.id collate "C" desc limit 1;
    if v_found is not null then
      return v_found;
    end if;
  end if;

  insert into ledger.decision_point_calls (id, request_id, created_by, session_id, compartments, point, version, definition_hash, rung,
    input_hash, output, effect, effect_class, escalated, subject_kind, subject_id)
  values ('dpc_' || substr(plan_move.move_id, 5), plan_move.request_id, v_author, plan_move.session_id, coalesce(v_compartments, v_label),
          'move_clear', plan_move.point_version, plan_move.definition_hash, 0,
          encode(sha256(convert_to(jsonb_build_object('opportunity', plan_move.opportunity_id, 'stage', plan_move.stage, 'move', plan_move.move_id,
            'broken', v_broken)::text, 'UTF8')), 'hex'),
          case when v_broken is null then 'clear' else 'refuse' end,
          case when v_broken is null then 'clear_internal_move' else 'hold' end,
          case when v_broken is null then 'internal_reversible' else 'narrow' end,
          false, 'opportunity', plan_move.opportunity_id);
  if v_broken is not null then
    if v_broken in ('kill_switch', 'not_go', 'no_intent', 'intent_revoked', 'kind_not_listed', 'client_not_listed', 'no_harness_mode', 'not_act', 'not_next_stage', 'not_internal') then
      return 'refused:' || v_broken;
    end if;
    return null;
  end if;

  select a.id into v_assignment from ledger.assignments a
  where a.opportunity_id = plan_move.opportunity_id and a.client_id = v_caller and policy.label_key(a.compartments) = any (v_keys) order by a.created_at desc, a.id collate "C" desc limit 1;
  insert into ledger.moves (id, request_id, created_by, session_id, compartments, opportunity_id, assignment_id, stage, harness_mode_id,
    decision_id, intent_id, effect_class)
  values (plan_move.move_id, plan_move.request_id, v_author, plan_move.session_id, v_compartments, plan_move.opportunity_id, v_assignment,
          plan_move.stage,
          (select h.id from policy.harness_modes h where h.client_id = v_caller and h.opportunity_kind = v_kind and h.stage = plan_move.stage
             and h.revoked_at is null and h.mode = 'act' order by h.granted_at, h.id collate "C" limit 1),
          v_decision_id, v_intent, 'internal_reversible');
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
  values ('move', plan_move.move_id, 'cleared', now(), v_author, v_compartments, plan_move.session_id);
  return plan_move.move_id;
end
$$;

CREATE FUNCTION ledger.policy_merge(person_a text, person_b text, basis text, name_fp text, request_id text) RETURNS TABLE(code text, ruling text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_cards text[];
  v_existing record;
  v_owner text[];
  v_a_fps text[];
  v_b_fps text[];
  v_ga text[];
  v_gb text[];
  v_group text[];
  v_labels text[];
  v_id text;
  v_fa text;
  v_fb text;
  v_compartments text[];
begin
  if coalesce((select w.identity_merges from policy.work_settings w), 'off') <> 'on'
     and not exists (select 1 from knowledge.owner_decisions d where d.request_id = policy_merge.request_id and d.kind = 'identity_policy') then
    return query select 'merges_off'::text, null::text;
    return;
  end if;
  select coalesce(array_agg(c.id order by c.id), '{}') into v_cards
  from ledger.cards c
  where c.created_by = 'system:identity' and c.kind = 'same_person'
    and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) in ('pending', 'deferred')
    and exists (select 1 from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id and b.ref_id = policy_merge.person_a)
    and exists (select 1 from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id and b.ref_id = policy_merge.person_b);
  perform ledger.lock_rows(array['identity:rulings', 'author:system:identity'] || v_cards);

  select d.id, d.kind into v_existing from knowledge.owner_decisions d where d.request_id = policy_merge.request_id;
  if found then
    if v_existing.kind = 'identity_policy' then
      return query select 'merged'::text, v_existing.id;
    else
      return query select 'already_settled'::text, null::text;
    end if;
    return;
  end if;

  if coalesce((select w.identity_merges from policy.work_settings w), 'off') <> 'on' then
    return query select 'merges_off'::text, null::text;
    return;
  end if;
  if policy_merge.basis is null or policy_merge.basis not in ('contact', 'name', 'local_part', 'research_identifier')
     or (policy_merge.basis <> 'contact' and policy_merge.name_fp is null) then
    return query select 'basis_absent'::text, null::text;
    return;
  end if;

  select coalesce(array_agg(distinct a.value_fp), '{}') into v_owner
  from knowledge.accounts a join knowledge.entities e on e.id = a.entity_id where e.kind = 'owner';
  select coalesce(array_agg(distinct a.value_fp), '{}') into v_a_fps from knowledge.accounts a where a.entity_id = policy_merge.person_a;
  select coalesce(array_agg(distinct a.value_fp), '{}') into v_b_fps from knowledge.accounts a where a.entity_id = policy_merge.person_b;
  if v_a_fps && v_owner or v_b_fps && v_owner then
    return query select 'owner_address'::text, null::text;
    return;
  end if;
  if exists (select 1 from knowledge.suppressions s where s.kind = 'address' and s.value_fp = any (v_a_fps || v_b_fps)) then
    return query select 'suppressed'::text, null::text;
    return;
  end if;
  if policy_merge.person_a = policy_merge.person_b or cardinality(v_a_fps) = 0 or cardinality(v_b_fps) = 0
     or (select count(*) from knowledge.entities e where e.id in (policy_merge.person_a, policy_merge.person_b) and e.kind = 'person') <> 2
     or exists (select 1 from knowledge.accounts a where a.entity_id in (policy_merge.person_a, policy_merge.person_b) and a.kind <> 'email')
     or exists (select 1 from knowledge.identity_rulings r where r.verdict = 'role' and r.lifted_at is null and r.a_fp = any (v_a_fps || v_b_fps)) then
    return query select 'not_a_person'::text, null::text;
    return;
  end if;

  with recursive g (fp) as (
    select unnest(v_a_fps)
    union
    select case when r.a_fp = g.fp then r.b_fp else r.a_fp end
    from knowledge.identity_rulings r join g on r.a_fp = g.fp or r.b_fp = g.fp
    where r.verdict = 'same' and r.lifted_at is null and r.b_fp is not null
  ) select array_agg(g.fp) into v_ga from g;
  with recursive g (fp) as (
    select unnest(v_b_fps)
    union
    select case when r.a_fp = g.fp then r.b_fp else r.a_fp end
    from knowledge.identity_rulings r join g on r.a_fp = g.fp or r.b_fp = g.fp
    where r.verdict = 'same' and r.lifted_at is null and r.b_fp is not null
  ) select array_agg(g.fp) into v_gb from g;
  if v_ga && v_gb then
    return query select 'already_settled'::text, null::text;
    return;
  end if;
  if exists (select 1 from knowledge.identity_rulings r
             where r.verdict = 'different' and r.lifted_at is null and r.by_agent
               and ((r.a_fp = any (v_ga) and r.b_fp = any (v_gb)) or (r.a_fp = any (v_gb) and r.b_fp = any (v_ga)))) then
    return query select 'already_settled'::text, null::text;
    return;
  end if;
  v_group := v_ga || v_gb;
  if exists (select 1 from knowledge.identity_rulings r
             where ((r.verdict = 'different' and r.lifted_at is null and not r.by_agent) or (r.verdict = 'same' and r.lifted_at is not null and not r.lifted_by_deletion) or (r.verdict = 'shared' and r.lifted_at is null))
               and (r.a_fp = any (v_group) or r.b_fp = any (v_group))) then
    return query select 'excepted'::text, null::text;
    return;
  end if;

  if policy_merge.basis = 'research_identifier' then
    if not exists (select 1 from knowledge.accounts a where a.entity_id = policy_merge.person_b and a.value_fp = policy_merge.name_fp and a.compartments <@ array['own']::text[])
       or exists (select 1 from knowledge.accounts a where a.value_fp = policy_merge.name_fp and not (a.compartments <@ array['own']::text[]))
       or not exists (select 1 from ledger.agent_writes w join vault.evidence_items e on e.id = w.evidence_id
                      where w.kind = 'fill' and w.fill_node = policy_merge.person_a and e.fill_identity_fp = policy_merge.name_fp
                        and w.body_enc is not null and w.flagged_at is null and e.payload_state = 'present') then
      return query select 'basis_absent'::text, null::text;
      return;
    end if;
  elsif policy_merge.basis = 'contact' then
    if not exists (select 1 from knowledge.contact_addresses x join knowledge.contact_addresses y on y.contact_id = x.contact_id
                   where x.entity_id = policy_merge.person_a and y.entity_id = policy_merge.person_b) then
      return query select 'basis_absent'::text, null::text;
      return;
    end if;
  else
    if policy_merge.basis = 'name' then
      select array_agg(distinct one) into v_labels
      from knowledge.aliases l cross join lateral unnest(l.compartments) as one
      where l.entity_id in (policy_merge.person_a, policy_merge.person_b) and l.value_fp = policy_merge.name_fp;
      if not exists (select 1 from knowledge.aliases l where l.entity_id = policy_merge.person_a and l.value_fp = policy_merge.name_fp) then
        v_labels := null;
      end if;
    else
      select array_agg(distinct one) into v_labels
      from (select a.compartments from knowledge.accounts a where a.entity_id = policy_merge.person_a and policy_merge.name_fp = any (a.local_name_fps)
            union all
            select l.compartments from knowledge.aliases l where l.entity_id = policy_merge.person_b and l.value_fp = policy_merge.name_fp) as held
      cross join lateral unnest(held.compartments) as one;
      if not exists (select 1 from knowledge.accounts a where a.entity_id = policy_merge.person_a and policy_merge.name_fp = any (a.local_name_fps)) then
        v_labels := null;
      end if;
    end if;
    if v_labels is null or not exists (select 1 from knowledge.aliases l where l.entity_id = policy_merge.person_b and l.value_fp = policy_merge.name_fp) then
      return query select 'basis_absent'::text, null::text;
      return;
    end if;
    if not (
         (exists (select 1 from knowledge.contact_addresses c
                  where c.entity_id = policy_merge.person_a and c.compartments <@ v_labels)
          or exists (select 1 from vault.sent_recipients s where s.address_fp = any (v_a_fps) and s.compartments <@ v_labels))
         and (exists (select 1 from knowledge.contact_addresses c
                      where c.entity_id = policy_merge.person_b and c.compartments <@ v_labels)
          or exists (select 1 from vault.sent_recipients s where s.address_fp = any (v_b_fps) and s.compartments <@ v_labels))) then
      return query select 'not_established'::text, null::text;
      return;
    end if;
    if policy_merge.basis = 'name' then
      if exists (select 1 from knowledge.identity_rulings r
                 join knowledge.accounts x on x.value_fp = r.a_fp and x.compartments <@ v_labels
                 join knowledge.accounts y on y.value_fp = r.b_fp and y.compartments <@ v_labels and y.entity_id <> x.entity_id
                 where ((r.verdict = 'different' and r.lifted_at is null and not r.by_agent) or (r.verdict = 'same' and r.lifted_at is not null and not r.lifted_by_deletion))
                   and exists (select 1 from knowledge.aliases l where l.entity_id = x.entity_id and l.value_fp = policy_merge.name_fp and l.compartments <@ v_labels)
                   and exists (select 1 from knowledge.aliases l where l.entity_id = y.entity_id and l.value_fp = policy_merge.name_fp and l.compartments <@ v_labels)) then
        return query select 'excepted'::text, null::text;
        return;
      end if;
    end if;
  end if;

  select min(x) into v_fa from unnest(v_a_fps) as x;
  select min(x) into v_fb from unnest(v_b_fps) as x;
  select ledger.label(array_agg(one)) into v_compartments
  from knowledge.accounts a cross join lateral unnest(a.compartments) as one
  where a.entity_id in (policy_merge.person_a, policy_merge.person_b);
  v_id := ledger.new_id('rul');
  insert into knowledge.owner_decisions (id, request_id, kind, answer, batch, queue_depth, details, decided_at, compartments)
  values (v_id, policy_merge.request_id, 'identity_policy', 'same', false,
          (select count(*) from ledger.cards c where (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) = 'pending'),
          jsonb_build_object('basis', policy_merge.basis), now(), v_compartments);
  insert into knowledge.identity_rulings (ruling_id, verdict, a_fp, b_fp, created_at)
  values (v_id, 'same', least(v_fa collate "C", v_fb collate "C"), greatest(v_fa collate "C", v_fb collate "C"), now());

  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'card', c.id, 'withdrawn', now(), 'system:identity', c.compartments
  from ledger.cards c
  where c.created_by = 'system:identity' and c.kind in ('same_person', 'shared_address')
    and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) in ('pending', 'deferred')
    and not exists (select 1 from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id
                    and not exists (select 1 from knowledge.accounts a where a.entity_id = b.ref_id and a.value_fp = any (v_group)))
    and exists (select 1 from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id)
  order by c.id collate "C";
  perform ledger.admit_deferred('system:identity');
  return query select 'merged'::text, v_id;
end
$$;

CREATE FUNCTION ledger.policy_ruling(p_question text, p_answer text, p_rule text, p_request text) RETURNS TABLE(code text, ruling text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_q ledger.identity_questions;
  v_a ledger.identity_answers;
  v_second text;
  v_verdict text;
  v_details jsonb;
  v_cards text[];
  v_owner text[];
  v_a_fps text[];
  v_b_fps text[];
  v_ga text[];
  v_gb text[];
  v_id text;
  v_fa text;
  v_fb text;
begin
  select q.* into v_q from ledger.identity_questions q where q.id = p_question;
  if not found or (p_answer is null) = (p_rule is null) then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  select coalesce(array_agg(c.id order by c.id), '{}') into v_cards
  from ledger.cards c
  where c.created_by = 'system:identity' and c.kind = 'same_person'
    and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) in ('pending', 'deferred')
    and exists (select 1 from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id and b.ref_id = v_q.a_entity)
    and exists (select 1 from ledger.basis b where b.row_kind = 'card' and b.row_id = c.id and b.ref_id = v_q.b_entity);
  perform ledger.lock_rows(array['identity:rulings', 'author:system:identity'] || v_cards);

  select d.id into v_id from knowledge.owner_decisions d where d.request_id = p_request and d.kind = 'identity_policy';
  if found then
    return query select 'ruled'::text, v_id;
    return;
  end if;

  if p_answer is not null then
    select a.* into v_a from ledger.identity_answers a where a.id = p_answer and a.question_id = p_question and a.verdict in ('same', 'different');
    if not found or coalesce((select s.identity_agents from policy.work_settings s), 'off') <> 'on' then
      return query select 'agents_off'::text, null::text;
      return;
    end if;
    v_verdict := v_a.verdict;
    select o.client_name into v_second from ledger.identity_answers o
    where o.question_id = p_question and o.verdict = v_verdict and o.client_id <> v_a.client_id
      and o.evidence_fp = v_a.evidence_fp and o.refused_code is null
    order by o.created_at, o.id collate "C" limit 1;
    if v_second is null then
      return query select 'one_agent'::text, null::text;
      return;
    end if;
    v_details := jsonb_build_object('basis', 'agent', 'client', v_a.client_name, 'because', v_a.because, 'answer', v_a.id)
      || case when v_second is null then '{}'::jsonb else jsonb_build_object('agrees', v_second) end;
  else
    select r.answer into v_verdict from ledger.question_rules r
    where r.id = p_rule and r.kind = 'same_person' and r.status = 'confirmed' and r.pattern = v_q.pattern
      and v_q.compartments <@ r.compartments
      and r.answer in ('same', 'different');
    if v_verdict is null or (v_verdict = 'same' and (v_q.pattern <> 'same_person:local_part:2' or v_q.exception is distinct from 'unestablished')) then
      return query select 'no_rule'::text, null::text;
      return;
    end if;
    v_details := jsonb_build_object('basis', 'rule', 'rule', p_rule);
  end if;

  select coalesce(array_agg(distinct a.value_fp), '{}') into v_owner
  from knowledge.accounts a join knowledge.entities e on e.id = a.entity_id where e.kind = 'owner';
  select coalesce(array_agg(distinct a.value_fp), '{}') into v_a_fps from knowledge.accounts a where a.entity_id = v_q.a_entity;
  select coalesce(array_agg(distinct a.value_fp), '{}') into v_b_fps from knowledge.accounts a where a.entity_id = v_q.b_entity;
  if cardinality(v_a_fps) = 0 or cardinality(v_b_fps) = 0 or v_a_fps && v_owner or v_b_fps && v_owner
     or (select count(*) from knowledge.entities e where e.id in (v_q.a_entity, v_q.b_entity) and e.kind = 'person') <> 2
     or exists (select 1 from knowledge.suppressions s where s.kind = 'address' and s.value_fp = any (v_a_fps || v_b_fps))
     or exists (select 1 from knowledge.accounts a where a.entity_id in (v_q.a_entity, v_q.b_entity) and a.kind <> 'email')
     or exists (select 1 from knowledge.identity_rulings r where r.verdict in ('role', 'shared') and r.lifted_at is null and r.a_fp = any (v_a_fps || v_b_fps)) then
    return query select 'not_a_person'::text, null::text;
    return;
  end if;

  with recursive g (fp) as (
    select unnest(v_a_fps)
    union
    select case when r.a_fp = g.fp then r.b_fp else r.a_fp end
    from knowledge.identity_rulings r join g on r.a_fp = g.fp or r.b_fp = g.fp
    where r.verdict = 'same' and r.lifted_at is null and r.b_fp is not null
  ) select array_agg(g.fp) into v_ga from g;
  with recursive g (fp) as (
    select unnest(v_b_fps)
    union
    select case when r.a_fp = g.fp then r.b_fp else r.a_fp end
    from knowledge.identity_rulings r join g on r.a_fp = g.fp or r.b_fp = g.fp
    where r.verdict = 'same' and r.lifted_at is null and r.b_fp is not null
  ) select array_agg(g.fp) into v_gb from g;
  if v_ga && v_gb then
    return query select 'already_settled'::text, null::text;
    return;
  end if;
  if exists (select 1 from knowledge.identity_rulings r
             where r.verdict = 'different' and r.lifted_at is null
               and ((r.a_fp = any (v_ga) and r.b_fp = any (v_gb)) or (r.a_fp = any (v_gb) and r.b_fp = any (v_ga)))) then
    return query select 'already_settled'::text, null::text;
    return;
  end if;
  if exists (select 1 from knowledge.identity_rulings r
             where r.verdict = 'same' and r.lifted_at is not null and not r.lifted_by_deletion
               and ((r.a_fp = any (v_ga) and r.b_fp = any (v_gb)) or (r.a_fp = any (v_gb) and r.b_fp = any (v_ga)))) then
    return query select 'excepted'::text, null::text;
    return;
  end if;

  select min(x) into v_fa from unnest(v_a_fps) as x;
  select min(x) into v_fb from unnest(v_b_fps) as x;
  v_id := ledger.new_id('rul');
  insert into knowledge.owner_decisions (id, request_id, kind, answer, batch, queue_depth, details, decided_at, compartments)
  values (v_id, p_request, 'identity_policy', v_verdict, false,
          (select count(*) from ledger.cards c where (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) = 'pending'),
          v_details, now(), v_q.compartments);
  insert into knowledge.identity_rulings (ruling_id, verdict, a_fp, b_fp, created_at, by_agent)
  values (v_id, v_verdict, least(v_fa collate "C", v_fb collate "C"), greatest(v_fa collate "C", v_fb collate "C"), now(), p_answer is not null);

  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'card', c.id, 'withdrawn', now(), 'system:identity', c.compartments
  from ledger.cards c where c.id = any (v_cards) order by c.id collate "C";
  perform ledger.admit_deferred('system:identity');
  update ledger.identity_questions q set state = 'settled', settled_by = 'ruling', batch = null, updated_at = now() where q.id = p_question;
  return query select 'ruled'::text, v_id;
end
$$;

CREATE FUNCTION ledger.post_agent_message(id text, request_id text, session_id text, to_kind text, to_client text, to_role text, reply_to text, kind text, subject_enc jsonb, body_enc jsonb) RETURNS TABLE(message_id text, thread_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_roles text[];
  v_keys text[];
  v_author text;
  v_parent ledger.agent_messages;
  v_to_kind text;
  v_to_client text;
  v_to_role text;
  v_thread text;
begin
  select c.client_id, c.clearance, c.roles into v_caller, v_clearance, v_roles from ledger.agent_mail_caller('post_agent_message', post_agent_message.session_id) c;
  if post_agent_message.kind is null or post_agent_message.kind not in ('note', 'question', 'issue', 'answer')
     or post_agent_message.body_enc is null or jsonb_typeof(post_agent_message.body_enc) <> 'object'
     or (post_agent_message.reply_to is null) = (post_agent_message.to_kind is null)
     or (post_agent_message.reply_to is null) <> (post_agent_message.subject_enc is not null)
     or (post_agent_message.to_kind is not null and post_agent_message.to_kind not in ('client', 'role', 'all'))
     or (post_agent_message.to_kind = 'client') <> (post_agent_message.to_client is not null)
     or (post_agent_message.to_kind = 'role') <> (post_agent_message.to_role is not null)
     or (post_agent_message.to_role is not null and post_agent_message.to_role !~ '^[a-z][a-z0-9-]{1,31}$') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  perform ledger.lock_rows(array['agent message ' || v_author || ' ' || post_agent_message.request_id]);
  return query select m.id, m.thread_id from ledger.agent_messages m where m.created_by = v_author and m.request_id = post_agent_message.request_id;
  if found then
    return;
  end if;

  if post_agent_message.reply_to is not null then
    v_keys := policy.clearance_keys();
    select m.* into v_parent from ledger.agent_messages m where m.id = post_agent_message.reply_to;
    if v_parent.id is null or not ledger.agent_message_visible(v_parent, v_caller, v_clearance, v_roles, v_keys) then
      return;
    end if;
    v_thread := v_parent.thread_id;
    if v_parent.client_id <> v_caller then
      v_to_kind := 'client';
      v_to_client := v_parent.client_id;
    else
      v_to_kind := v_parent.to_kind;
      v_to_client := v_parent.to_client_id;
      v_to_role := v_parent.to_role;
    end if;
  else
    v_thread := post_agent_message.id;
    v_to_kind := post_agent_message.to_kind;
    if v_to_kind = 'client' then
      select k.id into v_to_client from policy.clients k where k.name = post_agent_message.to_client and k.status = 'active' and k.kind = 'agent';
      if v_to_client is null then
        return;
      end if;
      if v_to_client = v_caller
         or not (ledger.label(v_clearance) <@ (select k.compartments from policy.clients k where k.id = v_to_client)) then
        raise exception 'invalid request' using errcode = '22023';
      end if;
    elsif v_to_kind = 'role' then
      v_to_role := post_agent_message.to_role;
      if not exists (select 1 from policy.clients k where k.status = 'active' and k.kind = 'agent' and v_to_role = any (k.roles)) then
        raise exception 'unknown role' using errcode = 'PIW04';
      end if;
    end if;
  end if;

  insert into ledger.agent_messages (id, request_id, created_by, client_id, session_id, compartments, thread_id, reply_to,
                                     to_kind, to_client_id, to_role, kind, subject_enc, body_enc)
  values (post_agent_message.id, post_agent_message.request_id, v_author, v_caller, post_agent_message.session_id, ledger.label(v_clearance),
          v_thread, post_agent_message.reply_to, v_to_kind, v_to_client, v_to_role, post_agent_message.kind,
          post_agent_message.subject_enc, post_agent_message.body_enc);
  insert into ledger.agent_message_reads (message_id, client_id) values (post_agent_message.id, v_caller);
  return query select post_agent_message.id, v_thread;
end
$_$;

CREATE FUNCTION ledger.project_creators(p_project_ids text[]) RETURNS TABLE(project_id text, creator text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not (v_tools && array['list_projects', 'get_project', 'update_project']) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  return query
    select p.id, c.name
    from knowledge.projects p
    join policy.clients c on 'client:' || c.id = p.created_by
    where p.id = any (p_project_ids) and p.compartments <@ v_clearance and policy.label_key(p.compartments) = any (v_keys)
    order by p.id collate "C";
end
$$;

CREATE FUNCTION ledger.propose_goal(id text, request_id text, session_id text, change text, goal_id text, statement_enc jsonb, statement_fp text, compartment text, body_enc jsonb, details_enc jsonb, ref_kinds text[], ref_ids text[]) RETURNS TABLE(status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_author text;
  v_label text[];
  v_compartment text;
  v_goal_status text;
  v_card text;
  v_rejected text;
  v_news boolean;
  v_found text;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('propose_goal' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = propose_goal.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if propose_goal.change is null or propose_goal.change not in ('add', 'reword', 'pause', 'done', 'drop')
     or (propose_goal.change = 'add') <> (propose_goal.goal_id is null)
     or (propose_goal.change in ('add', 'reword')) <> (propose_goal.statement_fp is not null)
     or (propose_goal.statement_fp is null) <> (propose_goal.statement_enc is null)
     or (propose_goal.change <> 'add' and propose_goal.compartment is not null)
     or propose_goal.body_enc is null
     or coalesce(cardinality(propose_goal.ref_kinds), 0) not between 1 and 20
     or cardinality(propose_goal.ref_kinds) <> coalesce(cardinality(propose_goal.ref_ids), 0) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  perform ledger.lock_rows(array['goal_proposal ' || propose_goal.change || ' ' || coalesce(propose_goal.goal_id, propose_goal.statement_fp), 'author:' || v_author]);

  select g.id into v_found from ledger.goal_proposals g
  where g.created_by = v_author and g.request_id = propose_goal.request_id and policy.label_key(g.compartments) = any (v_keys);
  if v_found is not null then
    return query select case (select r.event from ledger.record_events r where r.row_kind = 'goal_proposal' and r.row_id = v_found
                              and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1)
                          when 'rejected' then 'rejected' when 'accepted' then 'in_force' else 'proposed' end;
    return;
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = propose_goal.session_id and b.one ~ '^[0-9a-f]{64}$'
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return;
  end if;
  if propose_goal.goal_id is not null then
    select g.status into v_goal_status from projections.goal_state g
    where g.goal_id = propose_goal.goal_id and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys);
    if v_goal_status is null then
      return;
    end if;
  end if;
  if propose_goal.change = 'add' then
    v_compartment := coalesce(propose_goal.compartment,
      case when 'own' = any (v_clearance) then 'own' end,
      (select min(c.one collate "C") from unnest(v_clearance) as c (one) where c.one not like 'agent:%'));
    if v_compartment is null or not (v_compartment = any (v_clearance)) or v_compartment like 'agent:%' then
      raise exception 'invalid request' using errcode = '22023';
    end if;
  end if;
  if propose_goal.change in ('pause', 'done', 'drop')
     and v_goal_status = (case propose_goal.change when 'pause' then 'paused' when 'done' then 'done' else 'dropped' end) then
    return query select 'in_force'::text;
    return;
  end if;
  if exists (select 1 from ledger.goal_proposals g join ledger.cards c on c.id = g.card_id
             where g.change = propose_goal.change and g.goal_id is not distinct from propose_goal.goal_id
               and g.statement_fp is not distinct from propose_goal.statement_fp and g.tainted_at is null
               and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys)
               and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) in ('pending', 'deferred')) then
    return query select 'pending'::text;
    return;
  end if;
  select g.id into v_rejected from ledger.goal_proposals g
  where g.created_by = v_author and g.change = propose_goal.change and g.goal_id is not distinct from propose_goal.goal_id
    and g.statement_fp is not distinct from propose_goal.statement_fp and g.tainted_at is null
    and (select r.event from ledger.record_events r where r.row_kind = 'goal_proposal' and r.row_id = g.id order by r.id desc limit 1) = 'rejected'
  order by g.created_at desc, g.id collate "C" desc limit 1;

  v_card := 'crd_' || substr(propose_goal.id, 5);
  begin
    insert into ledger.goal_proposals (id, request_id, created_by, session_id, change, goal_id, statement_fp, statement_enc, proposed_compartment,
      body_enc, details_enc, card_id, compartments)
    values (propose_goal.id, propose_goal.request_id, v_author, propose_goal.session_id, propose_goal.change, propose_goal.goal_id,
            propose_goal.statement_fp, propose_goal.statement_enc, v_compartment, propose_goal.body_enc, propose_goal.details_enc, v_card, v_label);
    if not ledger.add_basis('goal_proposal', propose_goal.id, v_label, propose_goal.ref_kinds, propose_goal.ref_ids, v_clearance) then
      raise exception 'a ref did not resolve' using errcode = 'PIG01';
    end if;
    if v_rejected is not null then
      v_news := exists (
        select 1 from ledger.basis b
        where b.row_kind = 'goal_proposal' and b.row_id = propose_goal.id and b.source_class = 'source'
          and not exists (select 1 from ledger.basis b2 where b2.row_kind = 'goal_proposal' and b2.row_id = v_rejected
                          and b2.ref_kind = b.ref_kind and b2.ref_id = b.ref_id));
      if not v_news then
        raise exception 'the owner''s no stands' using errcode = 'PIG05';
      end if;
    end if;
  exception
    when sqlstate 'PIG01' then
      return;
    when sqlstate 'PIG05' then
      return query select 'rejected'::text;
      return;
  end;

  insert into ledger.cards (id, request_id, created_at, created_by, kind, target_kind, target_id, options, expires_after_days, compartments)
  values (v_card, propose_goal.id, now(), v_author, 'goal_proposal', 'goal_proposal', propose_goal.id, array['accept', 'reject'], 30, v_label);
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  values ('card', v_card, 'pending', now(), v_author, v_label);
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
  values ('goal_proposal', propose_goal.id, 'proposed', now(), v_author, v_label, propose_goal.session_id);
  return query select 'proposed'::text;
end
$_$;

CREATE FUNCTION ledger.propose_goal_target(id text, request_id text, session_id text, goal_id text, entity_id text, name_fp text, name_enc jsonb, organization boolean, body_enc jsonb, ref_kinds text[], ref_ids text[], open_most integer) RETURNS TABLE(status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_author text;
  v_label text[];
  v_goal_status text;
  v_goal_target text;
  v_card text;
  v_found text;
  v_entities text[];
  v_names text[];
  v_any_entities text[];
  v_any_names text[];
  v_org boolean;
  v_goal_label text[];
  v_holders text[];
  v_absorbed boolean;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('propose_goal_target' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = propose_goal_target.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if propose_goal_target.goal_id is null
     or (propose_goal_target.entity_id is null) = (propose_goal_target.name_fp is null)
     or (propose_goal_target.name_fp is null) <> (propose_goal_target.name_enc is null)
     or (propose_goal_target.organization and propose_goal_target.name_fp is null)
     or propose_goal_target.organization is null
     or propose_goal_target.body_enc is null
     or propose_goal_target.open_most is null
     or coalesce(cardinality(propose_goal_target.ref_kinds), 0) not between 1 and 20
     or cardinality(propose_goal_target.ref_kinds) <> coalesce(cardinality(propose_goal_target.ref_ids), 0) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  perform ledger.lock_rows(array['goal_proposal target ' || propose_goal_target.goal_id, 'author:' || v_author]);

  select g.id into v_found from ledger.goal_proposals g
  where g.created_by = v_author and g.request_id = propose_goal_target.request_id and policy.label_key(g.compartments) = any (v_keys);
  if v_found is not null then
    return query select case (select r.event from ledger.record_events r where r.row_kind = 'goal_proposal' and r.row_id = v_found
                              and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1)
                          when 'rejected' then 'rejected' when 'accepted' then 'in_force' else 'proposed' end;
    return;
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = propose_goal_target.session_id and b.one ~ '^[0-9a-f]{64}$'
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return;
  end if;
  select g.status, g.target_entity_id, g.compartments into v_goal_status, v_goal_target, v_goal_label from projections.goal_state g
  where g.goal_id = propose_goal_target.goal_id and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys);
  if v_goal_status is null then
    return;
  end if;
  if v_goal_status <> 'active' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if propose_goal_target.entity_id is not null then
    if not exists (
      select 1 from knowledge.entities e
      where e.id = propose_goal_target.entity_id and e.kind in ('person', 'organization')
        and (exists (select 1 from knowledge.accounts a where a.entity_id = e.id and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys))
          or exists (select 1 from knowledge.domains d where d.entity_id = e.id and d.compartments <@ v_clearance and policy.label_key(d.compartments) = any (v_keys))
          or exists (select 1 from knowledge.org_names o where o.entity_id = e.id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)))) then
      return;
    end if;
    v_org := (select e.kind = 'organization' from knowledge.entities e where e.id = propose_goal_target.entity_id);
  else
    v_org := propose_goal_target.organization;
    v_holders := array(
      select s.entity_id from knowledge.aliases s join knowledge.entities e on e.id = s.entity_id and e.kind = 'person'
      where not v_org and s.value_fp = propose_goal_target.name_fp and s.compartments <@ v_goal_label
      union
      select o.entity_id from knowledge.org_names o
      where v_org and o.name_fp = propose_goal_target.name_fp and o.compartments <@ v_goal_label);
  end if;
  select f.entities, f.names into v_entities, v_names
  from ledger.goal_target_forms(propose_goal_target.entity_id, propose_goal_target.name_fp, v_org, v_clearance, v_keys) f;
  select f.entities, f.names into v_any_entities, v_any_names
  from ledger.goal_target_forms(propose_goal_target.entity_id, propose_goal_target.name_fp, v_org, null, null) f;
  if v_goal_target is not null and v_goal_target = any (v_entities) then
    return query select 'in_force'::text;
    return;
  end if;
  if v_goal_target is null and exists (
      select 1 from ledger.goal_proposals g
      where g.change = 'target' and g.goal_id = propose_goal_target.goal_id and g.tainted_at is null
        and (g.target_entity_id = any (v_entities) or (g.statement_fp = any (v_names) and g.target_org = v_org))
        and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys)
        and (select r.event from ledger.record_events r where r.row_kind = 'goal_proposal' and r.row_id = g.id order by r.id desc limit 1) = 'accepted') then
    return query select 'in_force'::text;
    return;
  end if;
  if exists (select 1 from ledger.goal_proposals g
             where g.change = 'target' and g.goal_id = propose_goal_target.goal_id and g.tainted_at is null
               and (g.target_entity_id = any (v_entities) or (g.statement_fp = any (v_names) and g.target_org = v_org))
               and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys)
               and ((g.card_id is null and g.created_at > now() - interval '30 days')
                    or (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = g.card_id order by r.id desc limit 1) in ('pending', 'deferred'))) then
    return query select 'pending'::text;
    return;
  end if;
  if exists (select 1 from ledger.goal_proposals g
             where g.change = 'target' and g.goal_id = propose_goal_target.goal_id
               and (g.target_entity_id = any (v_entities) or (g.statement_fp = any (v_names) and g.target_org = v_org))
               and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys)
               and (select r.event from ledger.record_events r where r.row_kind = 'goal_proposal' and r.row_id = g.id order by r.id desc limit 1) = 'rejected') then
    return query select 'rejected'::text;
    return;
  end if;
  if (select count(*) from ledger.goal_proposals g
      where g.change = 'target' and g.goal_id = propose_goal_target.goal_id and g.tainted_at is null
        and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys)
        and ((g.card_id is null and g.created_at > now() - interval '30 days')
                    or (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = g.card_id order by r.id desc limit 1) in ('pending', 'deferred'))) >= propose_goal_target.open_most then
    return query select 'capped'::text;
    return;
  end if;
  v_absorbed := exists (
    select 1 from ledger.goal_proposals g
    where g.change = 'target' and g.goal_id = propose_goal_target.goal_id
      and (g.target_entity_id = any (v_any_entities) or (g.statement_fp = any (v_any_names) and g.target_org = v_org))
      and ((select r.event from ledger.record_events r where r.row_kind = 'goal_proposal' and r.row_id = g.id order by r.id desc limit 1) = 'rejected'
        or (g.tainted_at is null and g.card_id is not null and ((g.card_id is null and g.created_at > now() - interval '30 days')
                    or (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = g.card_id order by r.id desc limit 1) in ('pending', 'deferred')))
        or (g.tainted_at is null and v_goal_target is null and (select r.event from ledger.record_events r where r.row_kind = 'goal_proposal' and r.row_id = g.id order by r.id desc limit 1) = 'accepted')));

  v_card := case when v_absorbed then null else 'crd_' || substr(propose_goal_target.id, 5) end;
  insert into ledger.goal_proposals (id, request_id, created_by, session_id, change, goal_id, target_entity_id, target_org, target_holders, statement_fp, statement_enc, body_enc, card_id, compartments)
  values (propose_goal_target.id, propose_goal_target.request_id, v_author, propose_goal_target.session_id, 'target', propose_goal_target.goal_id,
          propose_goal_target.entity_id, propose_goal_target.organization, v_holders, propose_goal_target.name_fp, propose_goal_target.name_enc, propose_goal_target.body_enc, v_card, v_label);
  if not ledger.add_basis('goal_proposal', propose_goal_target.id, v_label, propose_goal_target.ref_kinds, propose_goal_target.ref_ids, v_clearance) then
    raise exception 'a ref did not resolve' using errcode = 'PIG01';
  end if;
  if propose_goal_target.entity_id is not null then
    insert into ledger.basis (row_kind, row_id, ref_kind, ref_id, evidence_id, source_class, owner_backed, compartments)
    values ('goal_proposal', propose_goal_target.id, 'entity', propose_goal_target.entity_id, null, 'derived',
            ledger.owner_backed('entity', propose_goal_target.entity_id), v_label);
  else
    insert into ledger.basis (row_kind, row_id, ref_kind, ref_id, evidence_id, source_class, owner_backed, compartments)
    values ('goal_proposal', propose_goal_target.id, 'target_name', propose_goal_target.name_fp, null, 'derived', false, v_label);
  end if;
  if not v_absorbed then
    insert into ledger.cards (id, request_id, created_at, created_by, kind, target_kind, target_id, options, expires_after_days, compartments)
    values (v_card, propose_goal_target.id, now(), v_author, 'goal_proposal', 'goal_proposal', propose_goal_target.id, array['accept', 'reject'], 30, v_label);
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
    values ('card', v_card, 'pending', now(), v_author, v_label);
  end if;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
  values ('goal_proposal', propose_goal_target.id, 'proposed', now(), v_author, v_label, propose_goal_target.session_id);
  return query select 'proposed'::text;
exception
  when sqlstate 'PIG01' then
    return;
end
$_$;

CREATE FUNCTION ledger.propose_hypothesis(id text, request_id text, session_id text, kind text, about_kind text, about_id text, body_enc jsonb, ref_kinds text[], ref_ids text[], idea text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_author text;
  v_label text[];
  v_found text;
  v_case text;
  v_open text;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('propose_hypothesis' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = propose_hypothesis.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if propose_hypothesis.kind is null or propose_hypothesis.kind not in ('open_loop', 'needs_preparation', 'at_risk', 'preference', 'idea')
     or propose_hypothesis.about_kind is null or propose_hypothesis.about_kind not in ('owner', 'message', 'event', 'entity', 'goal')
     or (propose_hypothesis.about_kind = 'owner') <> (propose_hypothesis.about_id is null)
     or (propose_hypothesis.kind = 'idea' and propose_hypothesis.about_kind = 'owner')
     or (propose_hypothesis.idea is not null and propose_hypothesis.kind <> 'idea')
     or coalesce(cardinality(propose_hypothesis.ref_kinds), 0) not between 1 and 20
     or cardinality(propose_hypothesis.ref_kinds) <> coalesce(cardinality(propose_hypothesis.ref_ids), 0) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  perform ledger.lock_rows(array['case hypothesis ' || coalesce(propose_hypothesis.kind, '') || ' ' || coalesce(propose_hypothesis.about_kind, '')
                                 || ' ' || coalesce(propose_hypothesis.about_id, '') || ' ' || coalesce(policy.label_key(v_label), ''),
                                 propose_hypothesis.idea]);

  select h.id into v_found from ledger.hypotheses h where h.created_by = v_author and h.request_id = propose_hypothesis.request_id;
  if v_found is not null then
    return v_found;
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = propose_hypothesis.session_id and b.one ~ '^[0-9a-f]{64}$'
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return null;
  end if;
  if not (case propose_hypothesis.about_kind
      when 'owner' then true
      when 'message' then exists (select 1 from knowledge.messages m where m.id = propose_hypothesis.about_id and m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys) and not m.held)
      when 'event' then exists (select 1 from knowledge.events e where e.id = propose_hypothesis.about_id and e.compartments <@ v_clearance and policy.label_key(e.compartments) = any (v_keys))
      when 'entity' then exists (select 1 from knowledge.accounts a where a.entity_id = propose_hypothesis.about_id and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys))
        or exists (select 1 from knowledge.domains d where d.entity_id = propose_hypothesis.about_id and d.compartments <@ v_clearance and policy.label_key(d.compartments) = any (v_keys))
      when 'goal' then exists (select 1 from projections.goal_state g where g.goal_id = propose_hypothesis.about_id and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys))
      else false end) then
    return null;
  end if;

  if propose_hypothesis.idea is not null then
    select h.id into v_open from ledger.hypotheses h
    where h.id = propose_hypothesis.idea and h.kind = 'idea' and h.tainted_at is null
      and h.compartments <@ v_clearance and policy.label_key(h.compartments) = any (v_keys);
    if v_open is null then
      return null;
    end if;
  elsif propose_hypothesis.kind <> 'idea' then
    select k.id into v_case from ledger.cases k
    where k.row_kind = 'hypothesis' and k.kind = propose_hypothesis.kind and k.about_kind = propose_hypothesis.about_kind
      and k.about_id is not distinct from propose_hypothesis.about_id and k.author = v_author and k.compartments = v_label
      and policy.label_key(k.compartments) = any (v_keys);
    if v_case is not null then
      select h.id into v_open from ledger.hypotheses h
      where h.case_id = v_case and policy.label_key(h.compartments) = any (v_keys) and h.tainted_at is null
        and (select r.event from ledger.record_events r where r.row_kind = 'hypothesis' and r.row_id = h.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1)
            in ('open', 'supported', 'asked')
      order by h.created_at, h.id collate "C" limit 1;
    end if;
  end if;

  begin
    if v_open is not null then
      if not ledger.add_basis('hypothesis', v_open, v_label,
           array(select r.kind from unnest(propose_hypothesis.ref_kinds, propose_hypothesis.ref_ids) with ordinality as r (kind, id, ord)
                 where not exists (select 1 from ledger.basis b where b.row_kind = 'hypothesis' and b.row_id = v_open and b.ref_kind = r.kind and b.ref_id = r.id
                                   and policy.label_key(b.compartments) = any (v_keys)) order by r.ord),
           array(select r.id from unnest(propose_hypothesis.ref_kinds, propose_hypothesis.ref_ids) with ordinality as r (kind, id, ord)
                 where not exists (select 1 from ledger.basis b where b.row_kind = 'hypothesis' and b.row_id = v_open and b.ref_kind = r.kind and b.ref_id = r.id
                                   and policy.label_key(b.compartments) = any (v_keys)) order by r.ord),
           v_clearance) then
        raise exception 'a ref did not resolve' using errcode = 'PIW01';
      end if;
      return v_open;
    end if;
    if v_case is null then
      v_case := 'cas_' || substr(propose_hypothesis.id, 5);
      insert into ledger.cases (id, request_id, created_by, session_id, compartments, row_kind, kind, about_kind, about_id, author)
      values (v_case, propose_hypothesis.request_id, v_author, propose_hypothesis.session_id, v_label, 'hypothesis', propose_hypothesis.kind,
              propose_hypothesis.about_kind, propose_hypothesis.about_id, v_author);
    end if;
    insert into ledger.hypotheses (id, request_id, created_by, session_id, compartments, body_enc, case_id, kind, about_kind, about_id, about_owner)
    values (propose_hypothesis.id, propose_hypothesis.request_id, v_author, propose_hypothesis.session_id, v_label, propose_hypothesis.body_enc,
            v_case, propose_hypothesis.kind, propose_hypothesis.about_kind, propose_hypothesis.about_id, propose_hypothesis.about_kind = 'owner');
    if not ledger.add_basis('hypothesis', propose_hypothesis.id, v_label, propose_hypothesis.ref_kinds, propose_hypothesis.ref_ids, v_clearance) then
      raise exception 'a ref did not resolve' using errcode = 'PIW01';
    end if;
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
    values ('hypothesis', propose_hypothesis.id, 'open', now(), v_author, v_label, propose_hypothesis.session_id);
  exception when sqlstate 'PIW01' then
    return null;
  end;
  return propose_hypothesis.id;
end
$_$;

CREATE FUNCTION ledger.propose_opportunity(id text, request_id text, session_id text, kind text, about_kind text, about_id text, hypothesis_id text, due_at timestamp with time zone, body_enc jsonb, ref_kinds text[], ref_ids text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_author text;
  v_label text[];
  v_found text;
  v_about_owner boolean;
  v_case text;
  v_open text;
  v_goal text;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('propose_opportunity' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = propose_opportunity.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if propose_opportunity.kind is null or propose_opportunity.kind not in ('follow_up', 'reply', 'meeting_prep', 'investigate', 'goal_step', 'life_admin', 'owner_question', 'introduction')
     or propose_opportunity.about_kind is null or propose_opportunity.about_kind not in ('owner', 'message', 'event', 'entity', 'goal')
     or (propose_opportunity.about_kind = 'owner') <> (propose_opportunity.about_id is null)
     or (propose_opportunity.kind = 'owner_question' and propose_opportunity.hypothesis_id is null)
     or coalesce(cardinality(propose_opportunity.ref_kinds), 0) not between 1 and 20
     or cardinality(propose_opportunity.ref_kinds) <> coalesce(cardinality(propose_opportunity.ref_ids), 0) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  perform ledger.lock_rows(array['case opportunity ' || coalesce(propose_opportunity.kind, '') || ' ' || coalesce(propose_opportunity.about_kind, '')
                                 || ' ' || coalesce(propose_opportunity.about_id, '') || ' ' || coalesce(policy.label_key(v_label), '')]);

  select o.id into v_found from ledger.opportunities o where o.created_by = v_author and o.request_id = propose_opportunity.request_id;
  if v_found is not null then
    return v_found;
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = propose_opportunity.session_id and b.one ~ '^[0-9a-f]{64}$'
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return null;
  end if;
  if propose_opportunity.hypothesis_id is not null then
    select h.about_owner into v_about_owner from ledger.hypotheses h
    where h.id = propose_opportunity.hypothesis_id and h.compartments <@ v_clearance and policy.label_key(h.compartments) = any (v_keys) and h.tainted_at is null;
    if v_about_owner is null then
      return null;
    end if;
    if v_about_owner then
      raise exception 'a hypothesis about the owner' using errcode = '22023';
    end if;
  end if;
  if not (case propose_opportunity.about_kind
      when 'owner' then true
      when 'message' then exists (select 1 from knowledge.messages m where m.id = propose_opportunity.about_id and m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys) and not m.held)
      when 'event' then exists (select 1 from knowledge.events e where e.id = propose_opportunity.about_id and e.compartments <@ v_clearance and policy.label_key(e.compartments) = any (v_keys))
      when 'entity' then exists (select 1 from knowledge.accounts a where a.entity_id = propose_opportunity.about_id and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys))
        or exists (select 1 from knowledge.domains d where d.entity_id = propose_opportunity.about_id and d.compartments <@ v_clearance and policy.label_key(d.compartments) = any (v_keys))
      when 'goal' then exists (select 1 from projections.goal_state g where g.goal_id = propose_opportunity.about_id and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys))
      else false end) then
    return null;
  end if;
  v_goal := case when propose_opportunity.about_kind = 'goal' then propose_opportunity.about_id
    else (select r.id from unnest(propose_opportunity.ref_kinds, propose_opportunity.ref_ids) with ordinality as r (kind, id, ord)
          where r.kind = 'goal' order by r.ord limit 1) end;

  select k.id into v_case from ledger.cases k
  where k.row_kind = 'opportunity' and k.kind = propose_opportunity.kind and k.about_kind = propose_opportunity.about_kind
    and k.about_id is not distinct from propose_opportunity.about_id and k.hypothesis_id is not distinct from propose_opportunity.hypothesis_id
    and k.author = v_author and k.compartments = v_label
    and policy.label_key(k.compartments) = any (v_keys);
  if v_case is not null then
    select o.id into v_open from ledger.opportunities o
    where o.case_id = v_case and policy.label_key(o.compartments) = any (v_keys) and o.tainted_at is null
      and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1)
          in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner')
    order by o.created_at, o.id collate "C" limit 1;
  end if;

  begin
    if v_open is not null then
      if not ledger.add_basis('opportunity', v_open, v_label,
           array(select r.kind from unnest(propose_opportunity.ref_kinds, propose_opportunity.ref_ids) with ordinality as r (kind, id, ord)
                 where not exists (select 1 from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = v_open and b.ref_kind = r.kind and b.ref_id = r.id
                                   and policy.label_key(b.compartments) = any (v_keys)) order by r.ord),
           array(select r.id from unnest(propose_opportunity.ref_kinds, propose_opportunity.ref_ids) with ordinality as r (kind, id, ord)
                 where not exists (select 1 from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = v_open and b.ref_kind = r.kind and b.ref_id = r.id
                                   and policy.label_key(b.compartments) = any (v_keys)) order by r.ord),
           v_clearance) then
        raise exception 'a ref did not resolve' using errcode = 'PIW01';
      end if;
      return v_open;
    end if;
    if v_case is null then
      v_case := 'cas_' || substr(propose_opportunity.id, 5);
      insert into ledger.cases (id, request_id, created_by, session_id, compartments, row_kind, kind, about_kind, about_id, author, hypothesis_id)
      values (v_case, propose_opportunity.request_id, v_author, propose_opportunity.session_id, v_label, 'opportunity', propose_opportunity.kind,
              propose_opportunity.about_kind, propose_opportunity.about_id, v_author, propose_opportunity.hypothesis_id);
    end if;
    insert into ledger.opportunities (id, request_id, created_by, session_id, compartments, body_enc, case_id, kind, hypothesis_id,
      about_kind, about_id, goal_id, due_at, proposed_by_class)
    values (propose_opportunity.id, propose_opportunity.request_id, v_author, propose_opportunity.session_id, v_label, propose_opportunity.body_enc,
            v_case, propose_opportunity.kind, propose_opportunity.hypothesis_id, propose_opportunity.about_kind, propose_opportunity.about_id,
            v_goal, propose_opportunity.due_at, 'client');
    if not ledger.add_basis('opportunity', propose_opportunity.id, v_label, propose_opportunity.ref_kinds, propose_opportunity.ref_ids, v_clearance) then
      raise exception 'a ref did not resolve' using errcode = 'PIW01';
    end if;
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
    values ('opportunity', propose_opportunity.id, 'proposed', now(), v_author, v_label, propose_opportunity.session_id);
  exception when sqlstate 'PIW01' then
    return null;
  end;
  return propose_opportunity.id;
end
$_$;

CREATE FUNCTION ledger.propose_project(p_id text, p_request_id text, p_session_id text, p_name_enc jsonb, p_goal_id text, p_owner_role text, p_due_at timestamp with time zone, p_area_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_author text;
  v_label text[];
  v_found text;
  v_area text;
  v_area_label text[];
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('propose_project' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = p_session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if p_id is null or p_id !~ '^ent_[0-9A-HJKMNP-TV-Z]{26}$' or p_request_id is null
     or p_name_enc is null or jsonb_typeof(p_name_enc) <> 'object'
     or (p_owner_role is not null and p_owner_role !~ '^[a-z][a-z0-9-]{1,31}$') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  perform ledger.lock_rows(array['project ' || v_author || ' ' || p_request_id]);
  select p.id into v_found from knowledge.projects p where p.created_by = v_author and p.request_id = p_request_id;
  if v_found is not null then
    return v_found;
  end if;
  if p_goal_id is not null
     and not exists (select 1 from projections.goal_state g
                     where g.goal_id = p_goal_id and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys)) then
    return null;
  end if;
  if p_owner_role is not null
     and not exists (select 1 from policy.clients k where k.status = 'active' and k.kind = 'agent' and (p_owner_role = any (k.roles) or p_owner_role = k.name)) then
    raise exception 'unknown role' using errcode = 'PIW04';
  end if;
  if p_area_id is not null then
    select a.id, a.compartments into v_area, v_area_label from knowledge.areas a
    where a.id = p_area_id and a.state = 'active'
      and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys);
    if v_area is null then
      raise exception 'invalid request' using errcode = '22023';
    end if;
  else
    select a.id, a.compartments into v_area, v_area_label
    from policy.clients k
    cross join lateral unnest(k.roles) as r (role)
    cross join policy.work_settings s
    join knowledge.areas a on a.id = s.area_defaults ->> r.role
    where k.id = v_caller and a.state = 'active'
      and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys)
    order by r.role collate "C" limit 1;
  end if;
  insert into knowledge.entities (id, kind) values (p_id, 'project');
  insert into knowledge.projects (id, status, name_enc, compartments, readers, created_at, updated_at, created_by, request_id, owner_role, goal_id, due_at, area_id)
  values (p_id, 'active', p_name_enc, v_label, array['m-owner']::text[], now(), now(), v_author, p_request_id, p_owner_role, p_goal_id, p_due_at, v_area);
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
  values ('project', p_id, 'created', now(), v_author, v_label, p_session_id);
  if v_area is not null then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, code)
    values ('project', p_id, 'updated', clock_timestamp(), v_author, ledger.label(v_label || v_area_label), p_session_id, 'area');
  end if;
  return p_id;
end
$_$;

CREATE FUNCTION ledger.propose_question_rule(p_id text, p_kind text, p_pattern text, p_answer text, p_answers integer, p_card text, p_at timestamp with time zone, p_label text[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  insert into ledger.question_rules (id, kind, pattern, answer, answers, status, card_id, proposed_at, compartments)
  values (p_id, p_kind, p_pattern, p_answer, p_answers, 'proposed', p_card, p_at, ledger.label(p_label))
  on conflict (kind, pattern, answer) do update set answers = excluded.answers, card_id = excluded.card_id, proposed_at = excluded.proposed_at
    where ledger.question_rules.status = 'proposed'
$$;

CREATE FUNCTION ledger.propose_task(id text, request_id text, session_id text, kind text, about_kind text, about_id text, role text, hypothesis_id text, due_at timestamp with time zone, body_enc jsonb, ref_kinds text[], ref_ids text[], point_version integer, definition_hash text, parent_id text) RETURNS TABLE(opportunity_id text, status text, merged boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_author text;
  v_label text[];
  v_found text;
  v_about_owner boolean;
  v_case text;
  v_open text;
  v_goal text;
  v_intent text;
  v_closed_at timestamptz;
  v_closes boolean;
  v_news boolean;
  v_carded boolean;
  v_declined boolean;
  v_vetoed boolean;
  v_output text;
  v_reason text;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('propose_task' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = propose_task.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if propose_task.kind is null or not ledger.task_kind(propose_task.kind) or propose_task.kind = 'research'
     or propose_task.about_kind is null or propose_task.about_kind not in ('owner', 'message', 'event', 'entity', 'goal')
     or (propose_task.about_kind = 'owner') <> (propose_task.about_id is null)
     or (propose_task.role is not null and propose_task.role !~ '^[a-z][a-z0-9-]{1,31}$')
     or coalesce(cardinality(propose_task.ref_kinds), 0) not between 1 and 20
     or cardinality(propose_task.ref_kinds) <> coalesce(cardinality(propose_task.ref_ids), 0) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  perform ledger.lock_rows(array['task ' || case when propose_task.kind in ('investigate', 'research') then 'research' else propose_task.kind end
                                 || ' ' || propose_task.about_kind || ' ' || coalesce(propose_task.about_id, 'owner') || ' ' || coalesce(policy.label_key(v_label), '')]);

  select o.id into v_found from ledger.opportunities o where o.created_by = v_author and o.request_id = propose_task.request_id;
  if v_found is not null then
    return query select v_found, (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = v_found and policy.label_key(r.compartments) = any (v_keys)
                                  order by r.id desc limit 1), false;
    return;
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = propose_task.session_id and b.one ~ '^[0-9a-f]{64}$'
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return;
  end if;
  if propose_task.parent_id is not null
     and not exists (select 1 from ledger.opportunities p
                     where p.id = propose_task.parent_id and p.compartments <@ v_clearance and policy.label_key(p.compartments) = any (v_keys)
                       and p.tainted_at is null) then
    return;
  end if;
  if propose_task.hypothesis_id is not null then
    select h.about_owner into v_about_owner from ledger.hypotheses h
    where h.id = propose_task.hypothesis_id and h.compartments <@ v_clearance and policy.label_key(h.compartments) = any (v_keys) and h.tainted_at is null;
    if v_about_owner is null then
      return;
    end if;
    if v_about_owner then
      raise exception 'a hypothesis about the owner' using errcode = '22023';
    end if;
  end if;
  if not (case propose_task.about_kind
      when 'owner' then true
      when 'message' then exists (select 1 from knowledge.messages m where m.id = propose_task.about_id and m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys) and not m.held)
      when 'event' then exists (select 1 from knowledge.events e where e.id = propose_task.about_id and e.compartments <@ v_clearance and policy.label_key(e.compartments) = any (v_keys))
      when 'entity' then exists (select 1 from knowledge.accounts a where a.entity_id = propose_task.about_id and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys))
        or exists (select 1 from knowledge.domains d where d.entity_id = propose_task.about_id and d.compartments <@ v_clearance and policy.label_key(d.compartments) = any (v_keys))
      when 'goal' then exists (select 1 from projections.goal_state g where g.goal_id = propose_task.about_id and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys))
      else false end) then
    return;
  end if;
  if propose_task.role is not null
     and not exists (select 1 from policy.clients k where k.status = 'active' and k.kind = 'agent' and (propose_task.role = any (k.roles) or propose_task.role = k.name)) then
    raise exception 'unknown role' using errcode = 'PIW04';
  end if;
  v_intent := (select i.id from policy.intents i where i.for_tasks and i.confirmed_at is not null and i.revoked_at is null
               order by i.confirmed_at desc, i.id collate "C" desc limit 1);
  if v_intent is null or coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on' then
    raise exception 'not permitted' using errcode = '42501';
  end if;

  select o.id into v_open from ledger.opportunities o
  where propose_task.parent_id is null
    and (propose_task.about_kind <> 'owner'
         or not exists (select 1 from unnest(propose_task.ref_kinds, propose_task.ref_ids) as g (kind, id)
                        where not exists (select 1 from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = o.id
                                          and b.ref_kind = g.kind and b.ref_id = g.id)))
    and o.tier = 'task' and o.about_kind = propose_task.about_kind and o.about_id is not distinct from propose_task.about_id and o.tainted_at is null
    and (o.kind = propose_task.kind or (o.kind in ('investigate', 'research') and propose_task.kind = 'investigate'))
    and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)
    and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id and policy.label_key(r.compartments) = any (v_keys)
         order by r.id desc limit 1) in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner')
  order by o.created_at, o.id collate "C" limit 1;
  v_goal := case when propose_task.about_kind = 'goal' then propose_task.about_id
    else (select r.id from unnest(propose_task.ref_kinds, propose_task.ref_ids) with ordinality as r (kind, id, ord)
          where r.kind = 'goal' order by r.ord limit 1) end;
  select k.id into v_case from ledger.cases k
  where k.row_kind = 'opportunity' and k.kind = propose_task.kind and k.about_kind = propose_task.about_kind
    and k.about_id is not distinct from propose_task.about_id and k.hypothesis_id is not distinct from propose_task.hypothesis_id
    and k.author = v_author and k.compartments = v_label and policy.label_key(k.compartments) = any (v_keys);
  begin
    if v_case is null then
      v_case := 'cas_' || substr(propose_task.id, 5);
      insert into ledger.cases (id, request_id, created_by, session_id, compartments, row_kind, kind, about_kind, about_id, author, hypothesis_id)
      values (v_case, propose_task.request_id, v_author, propose_task.session_id, v_label, 'opportunity', propose_task.kind,
              propose_task.about_kind, propose_task.about_id, v_author, propose_task.hypothesis_id);
    end if;
    insert into ledger.opportunities (id, request_id, created_by, session_id, compartments, body_enc, case_id, kind, hypothesis_id,
      about_kind, about_id, goal_id, due_at, proposed_by_class, tier, role, parent_id)
    values (propose_task.id, propose_task.request_id, v_author, propose_task.session_id, v_label, propose_task.body_enc,
            v_case, propose_task.kind, propose_task.hypothesis_id, propose_task.about_kind, propose_task.about_id,
            v_goal, propose_task.due_at, 'client', 'task', propose_task.role, propose_task.parent_id);
    if not ledger.add_basis('opportunity', propose_task.id, v_label, propose_task.ref_kinds, propose_task.ref_ids, v_clearance) then
      raise exception 'a ref did not resolve' using errcode = 'PIW01';
    end if;
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
    values ('opportunity', propose_task.id, 'proposed', now(), v_author, v_label, propose_task.session_id);
    if v_open is not null then
      raise exception 'merged' using errcode = 'PIW05';
    end if;
  exception
    when sqlstate 'PIW01' then
      return;
    when sqlstate 'PIW05' then
      return query select v_open, (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = v_open
                                   and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1), true;
      return;
  end;

  v_vetoed := policy.vetoed(
    case when propose_task.about_kind = 'owner' then '{}'::text[] else array[propose_task.about_kind] end || array(select b.ref_kind from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = propose_task.id and policy.label_key(b.compartments) = any (v_keys) order by b.id),
    case when propose_task.about_kind = 'owner' then '{}'::text[] else array[propose_task.about_id] end || array(select b.ref_id from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = propose_task.id and policy.label_key(b.compartments) = any (v_keys) order by b.id),
    propose_task.kind);
  select x.at, x.closes into v_closed_at, v_closes from (
    select d.created_at as at, d.decision = 'no_go' as closes from ledger.opportunity_decisions d join ledger.opportunities o on o.id = d.opportunity_id
    where o.case_id = v_case and d.decided_by = 'owner' and policy.label_key(o.compartments) = any (v_keys) and policy.label_key(d.compartments) = any (v_keys)
      and (propose_task.about_kind <> 'owner' or not exists (
        select 1 from unnest(propose_task.ref_kinds, propose_task.ref_ids) as g (kind, id)
        where not exists (select 1 from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = o.id and b.ref_kind = g.kind and b.ref_id = g.id)))
    union all
    select r.at, true from ledger.cards c
    join lateral (select e.event, e.at from ledger.record_events e where e.row_kind = 'card' and e.row_id = c.id and policy.label_key(e.compartments) = any (v_keys) order by e.id desc limit 1) r on true
    where c.case_key = v_case and r.event = 'expired'
      and (propose_task.about_kind <> 'owner' or not exists (
        select 1 from unnest(propose_task.ref_kinds, propose_task.ref_ids) as g (kind, id)
        where not exists (select 1 from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = c.target_id and b.ref_kind = g.kind and b.ref_id = g.id)))
  ) x order by x.at desc limit 1;
  v_news := exists (
    select 1 from ledger.basis b
    where b.row_kind = 'opportunity' and b.row_id = propose_task.id and (b.source_class = 'source' or propose_task.about_kind = 'owner') and policy.label_key(b.compartments) = any (v_keys)
      and not exists (select 1 from ledger.basis b2 join ledger.opportunities other on other.id = b2.row_id
                      where b2.row_kind = 'opportunity' and other.case_id = v_case and other.id <> propose_task.id
                        and b2.ref_kind = b.ref_kind and b2.ref_id = b.ref_id
                        and policy.label_key(b2.compartments) = any (v_keys) and policy.label_key(other.compartments) = any (v_keys)));
  v_carded := exists (
    select 1 from ledger.cases s join ledger.cards c on c.case_key = s.id
    where s.row_kind = 'opportunity' and s.about_kind = propose_task.about_kind
      and (propose_task.about_kind <> 'owner' or not exists (
        select 1 from unnest(propose_task.ref_kinds, propose_task.ref_ids) as g (kind, id)
        where not exists (select 1 from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = c.target_id and b.ref_kind = g.kind and b.ref_id = g.id)))
      and (s.kind = propose_task.kind or (s.kind in ('investigate', 'research') and propose_task.kind = 'investigate'))
      and s.about_id is not distinct from propose_task.about_id and s.compartments <@ v_clearance and policy.label_key(s.compartments) = any (v_keys)
      and coalesce((select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id and policy.label_key(r.compartments) = any (v_keys)
                    order by r.id desc limit 1), 'pending') in ('pending', 'deferred'));
  v_declined := exists (select 1 from ledger.opportunity_decisions d join ledger.opportunities o on o.id = d.opportunity_id
                        where d.decided_by = 'owner' and d.decision = 'no_go' and o.id <> propose_task.id
                          and (propose_task.about_kind <> 'owner' or not exists (
                            select 1 from unnest(propose_task.ref_kinds, propose_task.ref_ids) as g (kind, id)
                            where not exists (select 1 from ledger.basis b where b.row_kind = 'opportunity' and b.row_id = o.id and b.ref_kind = g.kind and b.ref_id = g.id)))
                          and (o.kind = propose_task.kind or (o.kind in ('investigate', 'research') and propose_task.kind = 'investigate'))
                          and o.about_kind = propose_task.about_kind and o.about_id is not distinct from propose_task.about_id and o.compartments <@ v_label
                          and policy.label_key(o.compartments) = any (v_keys) and policy.label_key(d.compartments) = any (v_keys));
  if v_vetoed then
    v_output := 'no_go';
    v_reason := 'vetoed';
  elsif coalesce(v_closes, false) and (not v_news or v_closed_at > now() - interval '7 days') then
    v_output := 'no_go';
    v_reason := 'owner_declined';
  elsif v_carded or v_declined then
    v_output := null;
  else
    v_output := 'go';
    v_reason := 'task';
  end if;

  insert into ledger.decision_point_calls (id, request_id, created_by, session_id, compartments, point, version, definition_hash, rung,
    input_hash, output, effect, effect_class, escalated, subject_kind, subject_id)
  values ('dpc_' || substr(propose_task.id, 5), propose_task.request_id, v_author, propose_task.session_id, v_label, 'task_go',
          propose_task.point_version, propose_task.definition_hash, 0,
          encode(sha256(convert_to(jsonb_build_object('opportunity', propose_task.id, 'vetoed', v_vetoed, 'closes', coalesce(v_closes, false),
            'news', v_news, 'carded', v_carded, 'declined', v_declined)::text, 'UTF8')), 'hex'),
          v_output, case v_output when 'go' then 'go_internal' when 'no_go' then 'decline' end,
          case v_output when 'go' then 'internal_reversible' when 'no_go' then 'narrow' end,
          v_output is null, 'opportunity', propose_task.id);
  if v_output is not null then
    insert into ledger.opportunity_decisions (request_id, created_by, session_id, compartments, opportunity_id, decision, decided_by, rung, reason,
      intent_id, call_id)
    values (propose_task.request_id, v_author, propose_task.session_id, v_label, propose_task.id, v_output, 'policy', 0, v_reason,
            v_intent, 'dpc_' || substr(propose_task.id, 5));
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
    values ('opportunity', propose_task.id, v_output, clock_timestamp(), v_author, v_label, propose_task.session_id);
  end if;
  return query select propose_task.id, coalesce(v_output, 'proposed'), false;
end
$_$;

CREATE FUNCTION ledger.raise_gap_flag(p_id text, p_trigger text, p_subject text, p_about_kind text, p_about_id text, p_source_kind text, p_source_id text, p_goal_id text, p_due_at timestamp with time zone, p_decide boolean, p_missing text[] DEFAULT NULL::text[], p_value double precision DEFAULT NULL::double precision, p_parts double precision[] DEFAULT NULL::double precision[], p_goals text[] DEFAULT NULL::text[], p_label text[] DEFAULT NULL::text[], p_members text[] DEFAULT NULL::text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_source text[];
  v_goal text[];
  v_label text[];
  v_found text;
  v_case text;
  v_kinds text[];
  v_ids text[];
  v_intent text;
  v_decide boolean := p_decide;
  v_wider text[];
begin
  if p_id is null or p_id !~ '^opp_[0-9A-HJKMNP-TV-Z]{26}$'
     or p_trigger is null or p_trigger not in ('unresolved_mention', 'no_warm_path', 'unknown_attendee', 'close_no_role',
                                                'meeting_soon', 'commitment_due', 'reply_owed', 'close_no_tie', 'intro_path', 'explore', 'deadline_soon', 'same_person',
                                                'defect', 'defect_untriaged', 'card_question', 'merge_audit',
                                                'card_relay',
                                                'dream_finding',
                                                'owner_queue',
                                                'goal_review', 'meeting_followup')
     or p_subject is null or p_subject !~ '^[A-Za-z0-9_]{1,128}$'
     or p_about_kind is null or p_about_kind not in ('message', 'event', 'entity', 'owner') or (p_about_kind = 'owner') <> (p_about_id is null)
     or p_source_kind is null or p_source_kind not in ('message', 'event', 'goal', 'entity', 'improvement', 'card', 'capture', 'queue')
     or p_source_id is null or p_decide is null
     or (p_source_kind = 'capture' and (p_trigger <> 'commitment_due' or p_about_kind <> 'entity'
                                        or p_source_id !~ '^cap_[0-9A-HJKMNP-TV-Z]{26}$' or p_subject !~ '^[0-9a-f]{64}_[0-9]{8}$'
                                        or p_goal_id is not null or p_due_at is null))
     or (p_trigger in ('defect', 'defect_untriaged', 'card_question', 'card_relay', 'owner_queue', 'goal_review')) <> (p_about_kind = 'owner')
     or (p_trigger = 'goal_review' and (p_source_kind <> 'goal' or p_goal_id is distinct from p_source_id
                                        or p_subject <> p_source_id or p_due_at is not null))
     or (p_trigger = 'meeting_followup' and (p_about_kind <> 'event' or p_source_kind <> 'event'
                                             or p_about_id <> p_source_id or p_subject <> p_source_id))
     or (p_trigger = 'owner_queue') <> (p_source_kind = 'queue')
     or (p_source_kind = 'queue' and (p_subject !~ '^owner_queue_[0-9]{8}_[0-9a-f]{8}$' or p_source_id <> p_subject
                                      or p_goal_id is not null or p_due_at is not null))
     or (p_trigger in ('defect', 'defect_untriaged')) <> (p_source_kind = 'improvement')
     or (p_source_kind = 'improvement' and (p_source_id !~ '^imp_[0-9A-HJKMNP-TV-Z]{26}$' or p_goal_id is not null or p_due_at is not null
                                            or (p_trigger = 'defect' and p_subject !~ ('^' || p_source_id || '_[0-9]{1,9}$'))
                                            or (p_trigger = 'defect_untriaged' and p_subject <> p_source_id)))
     or (p_trigger in ('card_question', 'card_relay')) <> (p_source_kind = 'card')
     or (p_source_kind = 'card' and (p_source_id !~ '^crd_[0-9A-HJKMNP-TV-Z]{26}$' or p_subject <> p_source_id
                                     or p_goal_id is not null or p_due_at is not null))
     or (p_source_kind = 'entity' and (p_trigger not in ('close_no_tie', 'close_no_role', 'explore', 'same_person', 'merge_audit', 'dream_finding') or p_about_kind <> 'entity' or p_about_id <> p_source_id))
     or (p_trigger = 'dream_finding' and (p_source_kind <> 'entity' or p_subject !~ '^dfd_[0-9A-HJKMNP-TV-Z]{26}$'
                                          or p_goal_id is not null or p_due_at is not null))
     or (p_trigger = 'intro_path' and (p_about_kind <> 'entity' or p_about_id <> p_subject or p_source_kind <> 'goal'
                                       or p_goal_id is distinct from p_source_id))
     or (p_trigger = 'explore' and (p_about_kind <> 'entity' or p_about_id <> p_subject or p_source_kind <> 'entity'
                                    or p_missing is null or cardinality(p_missing) not between 1 and 6 or array_position(p_missing, null) is not null
                                    or not p_missing <@ array['identity', 'role', 'affiliation', 'domain', 'relations', 'links']::text[]
                                    or p_value is null or not (p_value > 0 and p_value < 'Infinity'::double precision)
                                    or p_parts is null or cardinality(p_parts) <> 5 or array_position(p_parts, null) is not null
                                    or not (0 <= all (p_parts) and 'Infinity'::double precision > all (p_parts))
                                    or coalesce(cardinality(p_goals), 0) > 20))
     or (p_trigger <> 'explore' and (p_missing is not null or p_value is not null or p_parts is not null or p_goals is not null))
     or (p_trigger in ('close_no_tie', 'close_no_role')) <> (p_label is not null)
     or (p_label is not null and (cardinality(p_label) = 0 or array_position(p_label, null) is not null))
     or (p_trigger in ('close_no_tie', 'close_no_role')) <> (p_members is not null)
     or (p_members is not null and (cardinality(p_members) not between 1 and 500 or array_position(p_members, null) is not null
                                    or not (p_source_id = any (p_members)))) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if (p_trigger in ('close_no_tie', 'close_no_role', 'explore')) <> (session_user = 'pi_pipeline') then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if (select k.state from ledger.kill_switch k order by k.id desc limit 1) = 'on' then
    return null;
  end if;
  v_source := case p_source_kind
    when 'message' then (select m.compartments from knowledge.messages m where m.id = p_source_id and not m.held)
    when 'event' then (select v.compartments from knowledge.events v where v.id = p_source_id)
    when 'capture' then
      (select ledger.label(c.compartments || k.compartments) from knowledge.captures c
       join knowledge.claims k on k.evidence_id = c.evidence_id and c.compartments <@ k.compartments
       where c.id = p_source_id and k.type = 'commitment' and not k.closes and k.fact_key_fp = left(p_subject, 64)
         and exists (select 1 from knowledge.claim_entities n
                     where n.claim_id = k.id and n.entity_id = p_about_id and n.compartments <@ k.compartments)
       order by k.valid_from desc, k.id collate "C" desc limit 1)
    when 'entity' then case when p_trigger = 'explore' then
      (select array['own']::text[] where exists (select 1 from knowledge.entities e where e.id = p_subject and e.kind in ('person', 'organization'))
         and (exists (select 1 from knowledge.claim_entities x where x.entity_id = p_subject and x.compartments <@ array['own']::text[])
              or exists (select 1 from knowledge.org_names o where o.entity_id = p_subject and o.compartments <@ array['own']::text[])))
    when p_trigger = 'same_person' then
      (select q.compartments from ledger.identity_questions q where q.batch = p_subject and q.state = 'agents' order by q.id collate "C" limit 1)
    when p_trigger = 'merge_audit' then
      (select ledger.label(d.compartments) from knowledge.identity_rulings r join knowledge.owner_decisions d on d.id = r.ruling_id
       where p_subject ~ '^rul_[0-9A-HJKMNP-TV-Z]{26}(_2)?$' and r.ruling_id = left(p_subject, 30)
         and r.verdict = 'same' and r.lifted_at is null and d.kind = 'identity_policy'
         and exists (select 1 from knowledge.accounts a where a.entity_id = p_source_id and a.value_fp in (r.a_fp, r.b_fp)))
    when p_trigger = 'dream_finding' then
      (select ledger.label(f.compartments) from ledger.dream_findings f
       where f.id = p_subject and f.subject = p_source_id
         and not exists (select 1 from ledger.belief_settlements s where s.finding_id = f.id and s.lifted_at is null))
    else (select ledger.label(p_label)
          where p_subject = p_source_id || '_' || md5(array_to_string(ledger.label(p_label), ','))
            and not policy.is_restricted(p_label)
            and exists (select 1 from knowledge.entities e where e.id = p_source_id and e.kind = 'person')
            and exists (select 1 from (select a from policy.audiences() a union all select null::text[]) x (audience)
                        where (x.audience is null or p_label <@ x.audience)
                          and not exists (select 1 from projections.warmth_days d
                                          where d.entity_id = any (p_members) and not policy.is_restricted(d.compartments)
                                            and (x.audience is null or d.compartments <@ x.audience)
                                            and not d.compartments <@ p_label))) end
    when 'improvement' then (select i.compartments from ledger.improvements i
                             where i.id = p_source_id and i.tainted_at is null and (i.created_by = 'system:measure') = (p_trigger = 'defect'))
    when 'card' then (select c.compartments from ledger.cards c
                      where c.id = p_source_id and c.tainted_at is null
                        and case when p_trigger = 'card_relay'
                                 then ledger.card_relayable(c.id, now(), 48)
                                      and exists (select 1 from policy.work_settings s where s.question_role is not null)
                                 else c.kind = any (ledger.card_attempt_kinds()) end
                        and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1)
                            in ('pending', 'deferred')
                        and (p_trigger = 'card_relay'
                             or not exists (select 1 from ledger.card_answers a where a.card_id = c.id)))
    when 'queue' then ledger.owner_queue_label(p_source_id)
    else (select g.compartments from projections.goal_state g where g.goal_id = p_source_id and g.status = 'active') end;
  if p_goal_id is not null then
    v_goal := (select g.compartments from projections.goal_state g where g.goal_id = p_goal_id and g.status = 'active');
    if v_goal is null then
      return null;
    end if;
  end if;
  if v_source is null or policy.is_restricted(v_source || coalesce(v_goal, '{}'::text[])) then
    return null;
  end if;
  v_label := ledger.label(v_source || coalesce(v_goal, '{}'::text[]));
  v_kinds := case when p_source_kind in ('improvement', 'card', 'capture', 'queue') then '{}'::text[] else array[p_source_kind] end || case when p_about_kind = 'entity' and p_source_kind <> 'entity' then array['entity'] else '{}'::text[] end
    || case when p_goal_id is not null and p_goal_id <> p_source_id then array['goal'] else '{}'::text[] end;
  v_ids := case when p_source_kind in ('improvement', 'card', 'capture', 'queue') then '{}'::text[] else array[p_source_id] end || case when p_about_kind = 'entity' and p_source_kind <> 'entity' then array[p_about_id] else '{}'::text[] end
    || case when p_goal_id is not null and p_goal_id <> p_source_id then array[p_goal_id] else '{}'::text[] end;
  if policy.vetoed(array[p_about_kind] || v_kinds, array[p_about_id] || v_ids, 'research') then
    return null;
  end if;
  if exists (select 1 from ledger.opportunity_decisions d join ledger.opportunities o on o.id = d.opportunity_id
             where d.decided_by = 'owner' and d.decision = 'no_go' and o.kind in ('investigate', 'research')
               and ((o.about_kind = p_about_kind and o.about_id = p_about_id) or o.gap_subject = p_subject)
               and o.compartments <@ v_label) and v_decide then
    return null;
  end if;
  v_wider := array(select distinct c.one from ledger.opportunity_decisions d join ledger.opportunities o on o.id = d.opportunity_id
                   cross join lateral unnest(o.compartments) as c (one)
                   where d.decided_by = 'owner' and d.decision = 'no_go' and o.kind in ('investigate', 'research')
                     and ((o.about_kind = p_about_kind and o.about_id = p_about_id) or o.gap_subject = p_subject)
                     and not o.compartments <@ v_label
                   order by 1);
  if cardinality(v_wider) > 0 then
    if policy.is_restricted(v_label || v_wider) or p_source_kind = 'capture' then
      return null;
    end if;
    v_label := ledger.label(v_label || v_wider);
    v_decide := false;
  end if;
  if p_trigger = 'intro_path' then
    v_kinds := v_kinds
      || array(select 'entity'::text from (select i.entity_id from ledger.gap_intro_paths(p_subject, v_label, now()) i
                                            order by i.entity_id collate "C" limit 15) x)
      || array(select 'goal'::text from (select g.goal_id from projections.goal_state g
                                          where g.status = 'active' and g.target_entity_id = p_subject and g.goal_id <> p_source_id
                                            and g.compartments <@ v_label
                                          order by g.stated_at, g.goal_id collate "C" limit 5) y);
    v_ids := v_ids
      || array(select i.entity_id from ledger.gap_intro_paths(p_subject, v_label, now()) i order by i.entity_id collate "C" limit 15)
      || array(select g.goal_id from projections.goal_state g
               where g.status = 'active' and g.target_entity_id = p_subject and g.goal_id <> p_source_id and g.compartments <@ v_label
               order by g.stated_at, g.goal_id collate "C" limit 5);
  end if;
  if p_trigger = 'explore' then
    v_kinds := v_kinds || array(select 'goal'::text from (select g.goal_id from projections.goal_state g
                                                          where g.goal_id = any (p_goals) and g.status = 'active' and g.goal_id is distinct from p_goal_id
                                                            and g.compartments <@ v_label
                                                          order by g.stated_at, g.goal_id collate "C" limit 5) y);
    v_ids := v_ids || array(select g.goal_id from projections.goal_state g
                            where g.goal_id = any (p_goals) and g.status = 'active' and g.goal_id is distinct from p_goal_id and g.compartments <@ v_label
                            order by g.stated_at, g.goal_id collate "C" limit 5);
  end if;
  perform ledger.lock_rows(array['gap ' || p_trigger || ' ' || p_subject || ' ' || array_to_string(v_label, ',')]);
  select o.id into v_found from ledger.opportunities o
  where o.gap_trigger = p_trigger and o.gap_subject = p_subject and o.compartments = v_label and o.tainted_at is null
    and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id order by r.id desc limit 1)
        in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner')
  order by o.created_at, o.id collate "C" limit 1;
  if v_found is not null then
    return v_found;
  end if;
  if p_trigger = 'defect' and (select i.assignee_role from ledger.improvements i where i.id = p_source_id) is null then
    return null;
  end if;
  v_intent := (select i.id from policy.intents i where i.for_tasks and i.confirmed_at is not null and i.revoked_at is null
               order by i.confirmed_at desc, i.id collate "C" desc limit 1);
  if v_intent is null then
    return null;
  end if;

  begin
    select k.id into v_case from ledger.cases k
    where k.row_kind = 'opportunity' and k.kind = 'research' and k.about_kind = p_about_kind and k.about_id is not distinct from p_about_id
      and k.author = 'system:gaps' and k.compartments = v_label;
    if v_case is null then
      v_case := 'cas_' || substr(p_id, 5);
      insert into ledger.cases (id, request_id, created_by, compartments, row_kind, kind, about_kind, about_id, author)
      values (v_case, substr(p_id, 5), 'system:gaps', v_label, 'opportunity', 'research', p_about_kind, p_about_id, 'system:gaps');
    end if;
    insert into ledger.opportunities (id, request_id, created_by, compartments, case_id, kind, about_kind, about_id, goal_id, due_at,
      proposed_by_class, gap_trigger, gap_subject, gap_source, tier, role, gap_missing, gap_value, gap_parts)
    values (p_id, substr(p_id, 5), 'system:gaps', v_label, v_case, 'research', p_about_kind, p_about_id, p_goal_id, p_due_at,
            'system', p_trigger, p_subject, p_source_id, 'task',
            case when p_trigger = 'defect' then (select i.assignee_role from ledger.improvements i where i.id = p_source_id) else
            coalesce((select r.role from policy.gap_routes r where r.trigger = p_trigger),
                     (select r.role from policy.gap_routes r where r.trigger = 'same_person' and p_trigger = 'merge_audit'),
                     (select i.assignee_role from ledger.improvements i where p_source_kind = 'improvement' and i.id = p_source_id),
                     (select case when p_trigger = 'card_relay' then s.question_role else s.default_task_role end
                      from policy.work_settings s where p_source_kind = 'card'),
                     (select s.question_role from policy.work_settings s where p_source_kind = 'queue')) end,
            p_missing, p_value, p_parts);
    if not ledger.add_basis('opportunity', p_id, v_label, v_kinds, v_ids, null) then
      raise exception 'a ref did not resolve' using errcode = 'PIW01';
    end if;
    if p_source_kind = 'capture' then
      update ledger.basis b set evidence_id = (select c.evidence_id from knowledge.captures c where c.id = p_source_id)
      where b.row_kind = 'opportunity' and b.row_id = p_id and b.ref_kind = 'entity' and b.ref_id = p_about_id;
    end if;
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
    values ('opportunity', p_id, 'proposed', now(), 'system:gaps', v_label);
    if v_decide then
      insert into ledger.opportunity_decisions (request_id, created_by, compartments, opportunity_id, decision, decided_by, rung, reason, intent_id)
      values (substr(p_id, 5), 'system:gaps', v_label, p_id, 'go', 'policy', 0, 'gap_flag', v_intent);
      insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
      values ('opportunity', p_id, 'go', clock_timestamp(), 'system:gaps', v_label);
    end if;
  exception when sqlstate 'PIW01' or unique_violation then
    return null;
  end;
  return p_id;
end
$_$;

CREATE FUNCTION ledger.read_log_exposure() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  kept text;
  read_day date := (new.read_at at time zone 'utc')::date;
  kinds text[];
  ids text[];
begin
  select c.vendor_retention into kept from policy.clients c where c.id = new.client_id;
  if kept is null or kept = 'none' then
    return null;
  end if;
  if kept not in ('limited', 'retains', 'unknown') then
    kept := 'unknown';
  end if;
  select array_agg(r.ref_kind order by r.ref_kind, r.ref), array_agg(r.ref order by r.ref_kind, r.ref) into kinds, ids
  from (
    select case when x.id like 'rec\_%' then 'record' else 'evidence' end as ref_kind, x.id as ref
    from unnest(new.bound || new.shown) as x(id)
    union
    select 'fact', f.fp from unnest(new.fact_key_fps) as f(fp)
  ) r;
  if ids is null then
    return null;
  end if;
  begin
    insert into ledger.exposures (recipient_kind, recipient, route, ref_kind, ref, day, retention, compartments)
    select 'client', new.client_id, new.tool, r.ref_kind, r.ref, read_day, kept, new.compartments from unnest(kinds, ids) as r(ref_kind, ref)
    on conflict on constraint exposures_once do nothing;
  exception when serialization_failure then
    for i in 1 .. cardinality(ids) loop
      begin
        insert into ledger.exposures (recipient_kind, recipient, route, ref_kind, ref, day, retention, compartments)
        values ('client', new.client_id, new.tool, kinds[i], ids[i], read_day, kept, new.compartments)
        on conflict on constraint exposures_once do nothing;
      exception when serialization_failure then
        null;
      end;
    end loop;
  end;
  return null;
end
$$;

CREATE FUNCTION ledger.record_held_out_question(id text, request_id text, session_id text, class text, question_enc jsonb, key_enc jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_id text;
  v_keys text[];
begin
  select c.client_id, c.clearance into v_caller, v_clearance from ledger.agent_mail_caller('record_held_out_question', record_held_out_question.session_id) c;
  v_keys := policy.clearance_keys();
  if record_held_out_question.question_enc is null or record_held_out_question.key_enc is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = record_held_out_question.session_id
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return 'read_removed';
  end if;
  insert into ledger.held_out_questions (id, request_id, client_id, session_id, compartments, class, question_enc, key_enc)
  values (record_held_out_question.id, record_held_out_question.request_id, v_caller, record_held_out_question.session_id, ledger.label(v_clearance),
          record_held_out_question.class, record_held_out_question.question_enc, record_held_out_question.key_enc)
  on conflict (client_id, request_id) do nothing;
  select q.id into v_id from ledger.held_out_questions q
    where q.client_id = v_caller and q.request_id = record_held_out_question.request_id and policy.label_key(q.compartments) = any (v_keys);
  return v_id;
end
$$;

CREATE FUNCTION ledger.record_outcome_task(id text, request_id text, session_id text, run_id text, task text, held_out boolean, score integer, code_cap integer, judge_score integer, answer_model text, judge_model text, failed text[], tool_calls integer, cost_microusd bigint, answer_enc jsonb, scoring_enc jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
begin
  select c.client_id, c.clearance into v_caller, v_clearance from ledger.agent_mail_caller('record_outcome_task', record_outcome_task.session_id) c;
  v_keys := policy.clearance_keys();
  if record_outcome_task.answer_model is not distinct from record_outcome_task.judge_model and record_outcome_task.answer_model is not null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = record_outcome_task.session_id
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return 'read_removed';
  end if;
  if not exists (select 1 from ledger.outcome_test_runs r where r.id = record_outcome_task.run_id and r.client_id = v_caller
                   and policy.label_key(r.compartments) = any (v_keys))
     or (record_outcome_task.held_out and not exists (
           select 1 from ledger.held_out_questions q where q.id = record_outcome_task.task and q.tainted_at is null and q.compartments <@ v_clearance
             and policy.label_key(q.compartments) = any (v_keys))) then
    return 'not_found';
  end if;
  insert into ledger.outcome_test_tasks (id, run_id, request_id, client_id, session_id, compartments, task, held_out, score, code_cap, judge_score,
                                         answer_model, judge_model, failed, tool_calls, cost_microusd, answer_enc, scoring_enc)
  values (record_outcome_task.id, record_outcome_task.run_id, record_outcome_task.request_id, v_caller, record_outcome_task.session_id, ledger.label(v_clearance),
          record_outcome_task.task, record_outcome_task.held_out, record_outcome_task.score, record_outcome_task.code_cap, record_outcome_task.judge_score,
          record_outcome_task.answer_model, record_outcome_task.judge_model, record_outcome_task.failed, record_outcome_task.tool_calls,
          record_outcome_task.cost_microusd, record_outcome_task.answer_enc, record_outcome_task.scoring_enc)
  on conflict (run_id, task) do nothing;
  return 'ok';
end
$$;

CREATE FUNCTION ledger.record_sent(send_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  s ledger.sent_messages%rowtype;
  d ledger.drafts%rowtype;
  v_card ledger.cards%rowtype;
  v_card_state text;
  v_opportunity ledger.opportunities%rowtype;
begin
  select x.* into s from ledger.sent_messages x where x.id = record_sent.send_id;
  select x.* into d from ledger.drafts x where x.id = s.draft_id;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  values ('send', s.id, 'sent', now(), 'owner', s.compartments);
  if (select r.event from ledger.record_events r where r.row_kind = 'draft' and r.row_id = d.id order by r.id desc limit 1) in ('made', 'held') then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
    values ('draft', d.id, 'sent', now(), 'owner', d.compartments);
  end if;
  for v_card in select c.* from ledger.cards c where c.kind = 'draft_waiting' and c.target_kind = 'draft' and c.target_id = d.id loop
    v_card_state := (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = v_card.id order by r.id desc limit 1);
    if v_card_state in ('pending', 'deferred') then
      insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
      values ('card', v_card.id, case when v_card_state = 'pending' then 'decided' else 'withdrawn' end, now(), 'owner', v_card.compartments);
      perform ledger.admit_deferred(v_card.created_by);
    end if;
  end loop;
  if d.opportunity_id is not null then
    select o.* into v_opportunity from ledger.opportunities o where o.id = d.opportunity_id;
    if (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = v_opportunity.id order by r.id desc limit 1) = 'handed_to_owner'
       and (select p.stage from policy.stage_plan p where p.opportunity_kind = v_opportunity.kind order by p.ordinal desc limit 1) = 'send' then
      insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
      values ('opportunity', v_opportunity.id, 'done', now(), 'owner', v_opportunity.compartments);
      insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
      select 'intention', i.id, 'cancelled', now(), 'owner', i.compartments
      from ledger.intentions i
      where i.opportunity_id = v_opportunity.id
        and (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id order by r.id desc limit 1) = 'set';
    end if;
  end if;
end
$$;

CREATE FUNCTION ledger.record_spend(p_request_id text, p_session_id text, p_model_id text, p_cost_microusd bigint, p_input_tokens integer DEFAULT NULL::integer, p_output_tokens integer DEFAULT NULL::integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_tools text[];
  v_views text[];
  v_day date := (now() at time zone 'UTC')::date;
  v_ceiling bigint;
  v_runs integer;
  v_pending integer;
  v_keys text[];
begin
  select c.id, c.tools, c.views into v_caller, v_tools, v_views from policy.current_client() c;
  if v_caller is null or not ('record_spend' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = p_session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if p_cost_microusd is null or p_cost_microusd < 0 or p_model_id is null then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if p_cost_microusd > 0 then
    insert into ledger.agent_spend (client_id, session_id, request_id, model_id, cost_microusd, input_tokens, output_tokens)
    values (v_caller, p_session_id, p_request_id, p_model_id, p_cost_microusd, p_input_tokens, p_output_tokens)
    on conflict (client_id, request_id) do nothing;
  end if;
  v_keys := policy.clearance_keys();
  select s.max_microusd_per_day, s.max_runs_per_day, s.max_pending_cards into v_ceiling, v_runs, v_pending from policy.work_settings s;
  return coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') <> 'on'
    and ledger.spend_on(v_day) < v_ceiling / 2
    and (p_cost_microusd > 0 or
         ((select count(distinct a.opportunity_id) from ledger.assignments a
           where a.client_id = v_caller and policy.label_key(a.compartments) = any (v_keys)
             and a.created_at >= (v_day::timestamp at time zone 'UTC')
             and a.created_at < ((v_day + 1)::timestamp at time zone 'UTC')) < v_runs
          and (select count(*) from ledger.cards c
               where policy.label_key(c.compartments) = any (v_keys) and c.kind <> 'time_effort'
                 and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) = 'pending') < v_pending));
end
$$;

CREATE FUNCTION ledger.record_test(id text, request_id text, session_id text, hypothesis_id text, result text, ref_kinds text[], ref_ids text[]) RETURNS TABLE(test_id text, counts boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_author text;
  v_label text[];
  v_owner_of text;
  v_hypothesis_label text[];
  v_counts boolean;
  v_found text;
  v_found_counts boolean;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('record_test' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = record_test.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if record_test.result is null or record_test.result not in ('supports', 'refutes', 'inconclusive')
     or coalesce(cardinality(record_test.ref_kinds), 0) not between 1 and 20
     or cardinality(record_test.ref_kinds) <> coalesce(cardinality(record_test.ref_ids), 0) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  perform ledger.lock_rows(array(select h.id from ledger.hypotheses h
                                 where h.id = record_test.hypothesis_id and h.compartments <@ v_clearance and policy.label_key(h.compartments) = any (v_keys)));

  select t.id, t.counts into v_found, v_found_counts from ledger.hypothesis_tests t where t.created_by = v_author and t.request_id = record_test.request_id;
  if v_found is not null then
    return query select v_found, v_found_counts;
    return;
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = record_test.session_id and b.one ~ '^[0-9a-f]{64}$'
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return;
  end if;
  select h.created_by, h.compartments into v_owner_of, v_hypothesis_label from ledger.hypotheses h
  where h.id = record_test.hypothesis_id and h.compartments <@ v_clearance and policy.label_key(h.compartments) = any (v_keys) and h.tainted_at is null;
  if v_owner_of is null then
    return;
  end if;
  v_counts := v_owner_of <> v_author and v_label <@ v_hypothesis_label;

  begin
    insert into ledger.hypothesis_tests (id, request_id, created_by, session_id, compartments, hypothesis_id, result, counts)
    values (record_test.id, record_test.request_id, v_author, record_test.session_id, v_label, record_test.hypothesis_id, record_test.result, v_counts);
    if not ledger.add_basis('test', record_test.id, v_label, record_test.ref_kinds, record_test.ref_ids, v_clearance) then
      raise exception 'a ref did not resolve' using errcode = 'PIW01';
    end if;
  exception when sqlstate 'PIW01' then
    return;
  end;
  if v_counts and record_test.result <> 'inconclusive'
     and (select r.event from ledger.record_events r where r.row_kind = 'hypothesis' and r.row_id = record_test.hypothesis_id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) = 'open' then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
    values ('hypothesis', record_test.hypothesis_id, case record_test.result when 'supports' then 'supported' else 'refuted' end, now(), v_author,
            v_hypothesis_label, record_test.session_id);
  end if;
  return query select record_test.id, v_counts;
end
$_$;

CREATE FUNCTION ledger.relay_card_answer(p_id text, p_request text, p_card text, p_option text, p_quote_enc jsonb, p_session text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_client text;
  v_clearance text[];
  v_roles text[];
  v_card ledger.cards;
  v_opportunity text;
  v_label text[];
  v_keys text[];
  v_applied boolean;
  v_seen boolean;
begin
  perform ledger.lock_rows('{}'::text[]);
  select c.client_id, c.clearance, c.roles into v_client, v_clearance, v_roles from ledger.agent_mail_caller('relay_card_answer', p_session) c;
  if p_id is null or p_id !~ '^crl_[0-9A-HJKMNP-TV-Z]{26}$' or p_request is null or p_request !~ '^[A-Za-z0-9_-]{8,64}$'
     or p_card is null or p_card !~ '^crd_[0-9A-HJKMNP-TV-Z]{26}$' or p_option is null or p_option !~ '^[a-z][a-z0-9_]{0,31}$'
     or (p_quote_enc is not null and (jsonb_typeof(p_quote_enc) <> 'object' or octet_length(p_quote_enc::text) > 65536)) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  select y.ruling_id is not null, y.compartments <@ v_clearance and policy.label_key(y.compartments) = any (v_keys)
    into v_applied, v_seen
  from ledger.card_relays y where y.client_id = v_client and y.request_id = p_request;
  if found then
    return case when not v_seen then 'not_found' when v_applied then 'applied' else 'ok' end;
  end if;
  if coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on' then
    return 'kill_switch';
  end if;
  if not exists (select 1 from policy.work_settings s where s.question_role = any (v_roles)) then
    return 'not_question_role';
  end if;
  select c.* into v_card from ledger.cards c
  where c.id = p_card and c.tainted_at is null
    and c.compartments <@ v_clearance and policy.label_key(c.compartments) = any (v_keys);
  if not found then
    return 'not_found';
  end if;
  if v_card.kind = any (ledger.card_relay_never()) then
    return 'card_not_routed';
  end if;
  if not ledger.card_relay_routed(v_card) then
    return 'card_not_routed';
  end if;
  select o.id, o.compartments into v_opportunity, v_label from ledger.opportunities o
  where o.gap_trigger = 'card_relay' and o.gap_subject = p_card and o.tainted_at is null
    and v_card.compartments <@ o.compartments
    and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)
  order by o.created_at desc, o.id collate "C" desc limit 1;
  if v_opportunity is null then
    return 'work_not_held';
  end if;
  perform ledger.lock_rows(array[v_card.id, 'author:' || v_card.created_by, v_opportunity]);
  if exists (select 1 from ledger.card_relays y where y.card_id = v_card.id) then
    return 'already_relayed';
  end if;
  if exists (select 1 from ledger.record_events r where r.row_kind = 'card' and r.row_id = v_card.id and r.by = 'owner')
     or (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = v_card.id order by r.id desc limit 1)
       not in ('pending', 'deferred') then
    return 'owner_answered';
  end if;
  if (select r.event from ledger.record_events r
      where r.row_kind = 'opportunity' and r.row_id = v_opportunity and policy.label_key(r.compartments) = any (v_keys)
      order by r.id desc limit 1)
       not in ('go', 'claimed')
     or not exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = v_opportunity
                    and l.holder = v_client and l.lease_until >= now()) then
    return 'work_not_held';
  end if;
  if ledger.card_raised_by(v_card, v_client) then
    return 'own_card';
  end if;
  if not (p_option = any (v_card.options)) then
    return 'not_an_option';
  end if;
  if p_quote_enc is null then
    return 'not_found';
  end if;
  insert into ledger.card_relays (id, request_id, card_id, opportunity_id, client_id, client_name, option, quote_enc, created_at, compartments)
  values (p_id, p_request, v_card.id, v_opportunity, v_client, (select k.name from policy.clients k where k.id = v_client), p_option, p_quote_enc,
          now(), v_card.compartments);
  delete from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = v_opportunity;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
  values ('opportunity', v_opportunity, 'withdrawn', clock_timestamp(), 'system:gaps', v_label, 'relayed');
  return 'ok';
end
$_$;

CREATE FUNCTION ledger.release(opportunity_id text, request_id text, session_id text, reason text, record_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_author text;
  v_compartments text[];
  v_status text;
  v_by text;
  v_keys text[];
  v_tier text;
  v_mine boolean;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('release_opportunity' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = release.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  v_author := 'client:' || v_caller;
  perform ledger.lock_rows(array(select o.id from ledger.opportunities o
                                 where o.id = release.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)));
  select o.compartments, o.tier into v_compartments, v_tier from ledger.opportunities o
  where o.id = release.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys);
  if v_compartments is null then
    return null;
  end if;
  if (release.reason is null and v_tier = 'task')
     or (release.reason is not null and release.reason not in ('not_my_role', 'blocked', 'no_time', 'duplicate', 'other'))
     or (release.record_id is not null and not exists (
           select 1 from ledger.agent_writes w where w.id = release.record_id and w.client_id = v_caller and w.kind = 'handoff' and w.tainted_at is null
             and policy.label_key(w.compartments) = any (v_keys))) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  select r.event, r.by into v_status, v_by from ledger.record_events r
  where r.row_kind = 'opportunity' and r.row_id = release.opportunity_id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1;
  v_mine := ledger.work_held(release.opportunity_id, now())
            and exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = release.opportunity_id and l.holder = v_caller);
  if (v_status = 'claimed'
      and exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = release.opportunity_id and l.holder = v_caller))
     or (v_status = 'go' and v_mine) then
    insert into ledger.work_declines as d (opportunity_id, client_id, reason, created_at, expires_at)
    values (release.opportunity_id, v_caller, release.reason, now(), now() + interval '7 days')
    on conflict (opportunity_id, client_id) do update set reason = excluded.reason, created_at = excluded.created_at, expires_at = excluded.expires_at;
    delete from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = release.opportunity_id;
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
    select 'intention', i.id, 'cancelled', now(), v_author, i.compartments, release.session_id
    from ledger.intentions i
    where i.opportunity_id = release.opportunity_id and i.kind = 'check_back' and i.client_id = v_caller
      and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys)
      and (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) = 'set';
    if release.record_id is not null
       and not ledger.add_basis('opportunity', release.opportunity_id, v_compartments, array['agent_record'], array[release.record_id], v_compartments) then
      raise exception 'invalid request' using errcode = '22023';
    end if;
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, code)
    values ('opportunity', release.opportunity_id, 'go', now(), v_author, v_compartments, release.session_id, release.reason);
    return 'released';
  end if;
  if v_status = 'go' and v_by = v_author then
    return 'released';
  end if;
  if ledger.claimable_by(release.opportunity_id, v_caller) then
    insert into ledger.work_declines as d (opportunity_id, client_id, reason, created_at, expires_at)
    values (release.opportunity_id, v_caller, release.reason, now(), now() + interval '7 days')
    on conflict (opportunity_id, client_id) do update set reason = excluded.reason, created_at = excluded.created_at, expires_at = excluded.expires_at;
    return 'declined';
  end if;
  return null;
end
$$;

CREATE FUNCTION ledger.reopen_close(session_id text, close_id text, new_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_tools text[];
  v_close record;
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
  select c.id, c.tools into v_caller, v_tools from policy.current_client() c;
  if v_caller is null or not ('reopen_commitment' = any (v_tools)) or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = reopen_close.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  select w.id, w.close_fact_fp, w.compartments into v_close from ledger.agent_writes w
  where w.id = reopen_close.close_id and w.client_id = v_caller and w.kind = 'close' and w.body_enc is not null;
  if not found then
    return 'not_found';
  end if;
  perform ledger.lock_rows(array['commitment ' || v_close.close_fact_fp]);
  if exists (select 1 from ledger.commitment_reopens r where r.close_id = v_close.id) then
    return 'not_found';
  end if;
  insert into ledger.commitment_reopens (id, close_id, fact_fp, by, decision_id, compartments)
  values (reopen_close.new_id, v_close.id, v_close.close_fact_fp, 'client:' || v_caller, null, v_close.compartments);
  perform pg_notify('pi_agent_write', '');
  return 'ok';
end
$$;

CREATE FUNCTION ledger.report_move(move_id text, outcome text, request_id text, session_id text, body_enc jsonb, ref_kinds text[], ref_ids text[]) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  return (select r.status from ledger.report_move(report_move.move_id, report_move.outcome, report_move.request_id, report_move.session_id,
                                                  report_move.body_enc, report_move.ref_kinds, report_move.ref_ids, '{}'::text[]) r);
end
$$;

CREATE FUNCTION ledger.report_move(move_id text, outcome text, request_id text, session_id text, body_enc jsonb, ref_kinds text[], ref_ids text[], lessons_applied text[]) RETURNS TABLE(status text, dropped integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_opportunity text;
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_author text;
  v_label text[];
  v_move_label text[];
  v_planner text;
  v_move_status text;
  v_move_by text;
  v_kind text;
  v_compartments text[];
  v_status text;
  v_next text;
  v_new text;
  v_keys text[];
  v_tier text;
  v_stage text;
  v_kept text[];
  v_reopen boolean;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('report_move' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = report_move.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if report_move.outcome is null or report_move.outcome not in ('done', 'failed', 'blocked', 'progress')
     or (report_move.outcome = 'progress'
         and (report_move.body_enc is null or jsonb_typeof(report_move.body_enc) <> 'object'
              or coalesce(cardinality(report_move.ref_kinds), 0) > 0 or coalesce(cardinality(report_move.lessons_applied), 0) > 0))
     or coalesce(cardinality(report_move.ref_kinds), 0) > 20
     or coalesce(cardinality(report_move.ref_kinds), 0) <> coalesce(cardinality(report_move.ref_ids), 0)
     or coalesce(cardinality(report_move.lessons_applied), 0) > 10
     or array_position(report_move.lessons_applied, null) is not null
     or (select count(distinct x) from unnest(report_move.lessons_applied) as x) <> coalesce(cardinality(report_move.lessons_applied), 0)
     or exists (select 1 from unnest(report_move.lessons_applied) as x where x !~ '^hyp_[0-9A-HJKMNP-TV-Z]{26}$') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  v_opportunity := (select m.opportunity_id from ledger.moves m
                    where m.id = report_move.move_id and m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys));
  perform ledger.lock_rows(case when v_opportunity is null then '{}'::text[] else array[report_move.move_id, v_opportunity] end);

  select m.created_by, m.compartments into v_planner, v_move_label from ledger.moves m
  where m.id = report_move.move_id and m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys);
  if v_planner is distinct from v_author then
    return;
  end if;
  select r.event, r.by into v_move_status, v_move_by from ledger.record_events r
  where r.row_kind = 'move' and r.row_id = report_move.move_id and r.event <> 'reported' and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1;
  select o.kind, o.compartments, o.tier into v_kind, v_compartments, v_tier from ledger.opportunities o
  where o.id = v_opportunity and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys);
  v_status := (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = v_opportunity and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1);
  if v_move_status is distinct from 'cleared' then
    if report_move.outcome <> 'progress' and v_move_status in ('done', 'failed', 'blocked') and v_move_by = v_author then
      return query select v_status, null::integer;
      return;
    end if;
    return;
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = report_move.session_id and b.one ~ '^[0-9a-f]{64}$'
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return;
  end if;
  if report_move.outcome = 'progress' then
    if v_status is distinct from 'claimed'
       or not exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = v_opportunity and l.holder = v_caller
                      and l.lease_until >= now()) then
      return;
    end if;
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, code, body_enc)
    values ('move', report_move.move_id, 'reported', clock_timestamp(), v_author, v_compartments, report_move.session_id, 'progress', report_move.body_enc);
    return query select 'claimed'::text, null::integer;
    return;
  end if;
  v_reopen := coalesce(v_status in ('outcome_met', 'outcome_not_met')
    and (select r.by from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = v_opportunity and r.event = 'claimed'
         and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) is not distinct from v_author
    and (select r.at from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = v_opportunity
         and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) + interval '90 days' > now(), false);
  if not v_reopen and (v_status is distinct from 'claimed'
     or not exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = v_opportunity and l.holder = v_caller
                    and (v_tier is distinct from 'task' or l.lease_until >= now()))) then
    return;
  end if;
  if report_move.outcome = 'done' and v_kind = 'owner_question'
     and not exists (select 1 from ledger.agent_writes w where w.opportunity_id = v_opportunity and w.kind = 'answer') then
    return;
  end if;
  v_stage := (select m.stage from ledger.moves m where m.id = report_move.move_id and policy.label_key(m.compartments) = any (v_keys));
  if report_move.outcome = 'done' and v_tier = 'task'
     and v_stage = (select p.stage from policy.stage_plan p where p.opportunity_kind = v_kind order by p.ordinal desc limit 1)
     and not exists (select 1 from ledger.identity_answers a where a.opportunity_id = v_opportunity and a.client_id = v_caller and policy.label_key(a.compartments) = any (v_keys))
     and not exists (
       select 1 from ledger.agent_writes w
       where w.client_id = v_caller and w.kind = 'finding' and w.tainted_at is null and w.body_enc is not null
         and policy.label_key(w.compartments) = any (v_keys)
         and w.created_at >= (select min(r.at) from ledger.record_events r
                              where r.row_kind = 'opportunity' and r.row_id = v_opportunity and r.event = 'claimed' and r.by = v_author
                                and policy.label_key(r.compartments) = any (v_keys))) then
    return;
  end if;
  if coalesce(cardinality(report_move.ref_kinds), 0) > 0
     and not ledger.add_basis('move', report_move.move_id, v_move_label, report_move.ref_kinds, report_move.ref_ids, v_move_label) then
    return;
  end if;

  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
  values ('move', report_move.move_id, report_move.outcome, now(), v_author, v_move_label, report_move.session_id);
  if report_move.body_enc is not null then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, body_enc)
    values ('move', report_move.move_id, 'reported', clock_timestamp(), v_author, v_label, report_move.session_id, report_move.body_enc);
  end if;
  v_kept := array(select x from unnest(coalesce(report_move.lessons_applied, '{}'::text[])) with ordinality as l (x, ord)
                  where exists (select 1 from ledger.read_log r where r.session_id = report_move.session_id and l.x = any (r.lessons))
                  order by l.ord);
  insert into ledger.move_lessons (created_by, session_id, move_id, lesson_id, compartments)
  select v_author, report_move.session_id, report_move.move_id, k.x, v_move_label from unnest(v_kept) as k (x);

  v_next := (select p.stage from policy.stage_plan p
             where p.opportunity_kind = v_kind
               and not exists (select 1 from ledger.moves m where m.opportunity_id = v_opportunity and m.stage = p.stage and policy.label_key(m.compartments) = any (v_keys)
                               and (select r.event from ledger.record_events r where r.row_kind = 'move' and r.row_id = m.id and r.event <> 'reported' and policy.label_key(r.compartments) = any (v_keys)
                                    order by r.id desc limit 1) = 'done')
             order by p.ordinal limit 1);
  v_new := case
    when v_tier = 'task' and report_move.outcome = 'failed' then 'withdrawn'
    when v_tier = 'task' and report_move.outcome = 'blocked' then 'go'
    when report_move.outcome <> 'done' then 'handed_to_owner'
    when v_next is null then 'done'
    when (select p.internal from policy.stage_plan p where p.opportunity_kind = v_kind and p.stage = v_next) then 'claimed'
    else 'handed_to_owner'
  end;
  if v_reopen and v_new = 'claimed' then
    v_new := 'go';
  end if;
  if v_new <> 'claimed' then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, code)
    values ('opportunity', v_opportunity, v_new, clock_timestamp(), v_author, v_compartments, report_move.session_id,
            case when v_tier = 'task' and report_move.outcome <> 'done' then report_move.outcome end);
    delete from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = v_opportunity;
    if v_tier = 'task' and report_move.outcome = 'blocked' then
      insert into ledger.work_declines as d (opportunity_id, client_id, reason, created_at, expires_at)
      values (v_opportunity, v_caller, 'blocked', now(), now() + interval '7 days')
      on conflict (opportunity_id, client_id) do update set reason = excluded.reason, created_at = excluded.created_at, expires_at = excluded.expires_at;
    end if;
  end if;
  if v_new = 'done' then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
    select 'intention', i.id, 'cancelled', clock_timestamp(), v_author, i.compartments, report_move.session_id
    from ledger.intentions i
    where i.opportunity_id = v_opportunity
      and (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id order by r.id desc limit 1) = 'set';
  end if;
  return query select v_new, nullif(coalesce(cardinality(report_move.lessons_applied), 0) - cardinality(v_kept), 0);
end
$_$;

CREATE FUNCTION ledger.report_wrong_merge(p_id text, p_request text, p_session text, p_entity text, p_parts jsonb, p_because text, p_cites text[]) RETURNS TABLE(code text, report text, state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_client text;
  v_clear text[];
  v_name text;
  v_keys text[];
  v_members text[];
  v_bad integer;
  v_n integer;
  v_distinct integer;
  v_nos integer[];
  v_ents text[];
  v_parts text[];
  v_partition text;
  v_group text;
  v_cross text[];
  v_owner boolean;
  v_label text[];
  v_lift_label text[];
  v_seen integer;
  v_wide boolean;
  v_found record;
begin
  perform ledger.lock_rows(array['identity:wrong_merges']);
  select c.client_id, c.clearance into v_client, v_clear from ledger.agent_mail_caller('report_wrong_merge', p_session) c;
  if p_id is null or p_id !~ '^wmr_[0-9A-HJKMNP-TV-Z]{26}$' or p_request is null or p_request !~ '^[A-Za-z0-9_-]{8,64}$'
     or p_entity is null or p_entity !~ '^ent_[0-9A-HJKMNP-TV-Z]{26}$'
     or p_because is null or p_because !~ '^[a-z][a-z0-9_]{0,31}$'
     or p_cites is null or array_position(p_cites, null) is not null or cardinality(p_cites) > 20
     or p_parts is null or jsonb_typeof(p_parts) <> 'array' or jsonb_array_length(p_parts) not between 2 and 4
     or exists (select 1 from jsonb_array_elements(p_parts) as p (ids)
                where jsonb_typeof(p.ids) <> 'array' or jsonb_array_length(p.ids) not between 1 and 50)
     or exists (select 1 from jsonb_array_elements(p_parts) as p (ids)
                cross join lateral jsonb_array_elements(case when jsonb_typeof(p.ids) = 'array' then p.ids else '[]'::jsonb end) as i (one)
                where jsonb_typeof(i.one) <> 'string' or (i.one #>> '{}') !~ '^[0-9a-f]{64}$') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  select r.id, r.state, r.compartments <@ v_clear and policy.label_key(r.compartments) = any (v_keys) as seen into v_found
  from ledger.wrong_merge_reports r where r.client_id = v_client and r.request_id = p_request;
  if found then
    if v_found.seen then
      return query select 'ok'::text, v_found.id, case when v_found.state = 'open' then 'filed' else v_found.state end;
    else
      return query select 'not_found'::text, null::text, null::text;
    end if;
    return;
  end if;
  if coalesce((select s.identity_agents from policy.work_settings s), 'off') <> 'on' then
    return query select 'agents_off'::text, null::text, null::text;
    return;
  end if;
  select k.name into v_name from policy.clients k where k.id = v_client;
  if not exists (select 1 from knowledge.entities e join knowledge.accounts a on a.entity_id = e.id
                 where e.id = p_entity and e.kind = 'person' and a.compartments <@ v_clear and policy.label_key(a.compartments) = any (v_keys)) then
    return query select 'not_found'::text, null::text, null::text;
    return;
  end if;
  v_members := array(select m.one from unnest(ledger.same_person_side(p_entity, v_keys)) as m (one) order by m.one collate "C");

  select count(*) filter (where r.entity_id is null or not (r.entity_id = any (v_members))), count(*), count(distinct r.id)
    into v_bad, v_n, v_distinct
  from ledger.wrong_merge_parts(p_parts, v_clear, v_keys) r;
  if v_n <> v_distinct then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if v_bad > 0 then
    return query select 'not_found'::text, null::text, null::text;
    return;
  end if;
  if cardinality(v_members) < 2 then
    return query select 'not_merged'::text, null::text, null::text;
    return;
  end if;
  select array_agg(x.part_no order by x.part_no, x.entity_id collate "C"), array_agg(x.entity_id order by x.part_no, x.entity_id collate "C")
    into v_nos, v_ents
  from (select distinct r.part_no, r.entity_id from ledger.wrong_merge_parts(p_parts, v_clear, v_keys) r) x;
  if (select count(*) from unnest(v_ents) as e (one)) <> (select count(distinct e.one) from unnest(v_ents) as e (one)) then
    return query select 'same_record'::text, null::text, null::text;
    return;
  end if;
  if not (v_members <@ v_ents) then
    return query select 'incomplete'::text, null::text, null::text;
    return;
  end if;
  v_parts := array(select string_agg(t.e, ',' order by t.e collate "C") from unnest(v_nos, v_ents) as t (n, e) group by t.n
                   order by string_agg(t.e, ',' order by t.e collate "C") collate "C");
  v_partition := encode(sha256(convert_to(array_to_string(v_parts, '|'), 'UTF8')), 'hex');
  v_group := encode(sha256(convert_to(array_to_string(v_members, ','), 'UTF8')), 'hex');

  select coalesce(array_agg(distinct r.ruling_id), '{}'),
         coalesce(bool_or(d.kind <> 'identity_policy'
                          or exists (select 1 from knowledge.owner_decisions o
                                     where o.kind = 'identity' and o.answer = 'same' and o.details -> 'affirms' ? r.ruling_id)), false)
    into v_cross, v_owner
  from knowledge.identity_rulings r
  join knowledge.owner_decisions d on d.id = r.ruling_id
  join knowledge.accounts xa on xa.value_fp = r.a_fp and policy.label_key(xa.compartments) = any (v_keys)
  join knowledge.accounts xb on xb.value_fp = r.b_fp and policy.label_key(xb.compartments) = any (v_keys)
  join unnest(v_nos, v_ents) as pa (n, e) on pa.e = xa.entity_id
  join unnest(v_nos, v_ents) as pb (n, e) on pb.e = xb.entity_id
  where r.verdict = 'same' and r.lifted_at is null and pa.n <> pb.n;
  if cardinality(v_cross) = 0 then
    return query select 'not_merged'::text, null::text, null::text;
    return;
  end if;
  if v_owner then
    return query select 'owner_ruled'::text, null::text, null::text;
    return;
  end if;
  v_cross := array(select c.one from unnest(v_cross) as c (one) order by c.one collate "C");
  v_lift_label := ledger.label(array(select c.one from knowledge.owner_decisions d cross join lateral unnest(d.compartments) as c (one) where d.id = any (v_cross)));
  v_label := ledger.label(array(select c.one from knowledge.accounts a cross join lateral unnest(a.compartments) as c (one)
                                where a.entity_id = any (v_members) and policy.label_key(a.compartments) = any (v_keys)));

  select count(*), coalesce(bool_or(not (r.compartments <@ v_lift_label)), false) into v_seen, v_wide from (
    select m.compartments from knowledge.messages m where m.id = any (p_cites) and not m.held and m.compartments <@ v_clear and policy.label_key(m.compartments) = any (v_keys)
    union all
    select c.compartments from knowledge.contacts c where c.id = any (p_cites) and c.compartments <@ v_clear and policy.label_key(c.compartments) = any (v_keys)
    union all
    select l.compartments from knowledge.aliases l where l.id = any (p_cites) and l.compartments <@ v_clear and policy.label_key(l.compartments) = any (v_keys)
    union all
    select a.compartments from knowledge.accounts a where a.id = any (p_cites) and a.compartments <@ v_clear and policy.label_key(a.compartments) = any (v_keys)
  ) as r;
  if v_seen <> (select count(distinct c.one) from unnest(p_cites) as c (one)) then
    return query select 'not_found'::text, null::text, null::text;
    return;
  end if;
  if cardinality(p_cites) = 0
     or exists (select 1 from knowledge.messages m where m.id = any (p_cites) and policy.label_key(m.compartments) = any (v_keys)
                and not exists (select 1 from knowledge.interaction_log i where i.evidence_id = m.evidence_id and i.entity_id = any (v_members)
                                  and policy.label_key(i.compartments) = any (v_keys))) then
    return query select 'no_evidence'::text, null::text, null::text;
    return;
  end if;
  if v_wide then
    return query select 'cite_label'::text, null::text, null::text;
    return;
  end if;
  if exists (select 1 from ledger.wrong_merge_reports r where r.group_key = v_group and r.client_id = v_client and r.state = 'open') then
    return query select 'already_reported'::text, null::text, null::text;
    return;
  end if;
  insert into ledger.wrong_merge_reports (id, request_id, entity_id, members, parts, partition_key, group_key, cross_rulings, client_id, client_name,
    session_id, because, cites, cite_evidence, cite_address_fps, state, created_at, compartments)
  values (p_id, p_request, p_entity, v_members, v_parts, v_partition, v_group, v_cross, v_client, v_name, p_session, p_because, p_cites,
          array(select m.evidence_id from knowledge.messages m where m.id = any (p_cites) and policy.label_key(m.compartments) = any (v_keys)
                union select c.evidence_id from knowledge.contacts c where c.id = any (p_cites) and policy.label_key(c.compartments) = any (v_keys)
                union select l.evidence_id from knowledge.aliases l where l.id = any (p_cites) and policy.label_key(l.compartments) = any (v_keys)),
          array(select a.value_fp from knowledge.accounts a where a.id = any (p_cites) and policy.label_key(a.compartments) = any (v_keys)),
          'open', now(), v_label);
  return query select 'ok'::text, p_id,
    case when exists (select 1 from ledger.wrong_merge_reports o
                      where o.partition_key = v_partition and o.state = 'open' and o.client_id <> v_client and o.session_id <> p_session
                        and o.compartments = v_label and policy.label_key(o.compartments) = any (v_keys))
         then 'agreed' else 'filed' end;
end
$_$;

CREATE FUNCTION ledger.report_wrong_relation(p_id text, p_request text, p_session text, p_relation bigint, p_because text, p_cites text[]) RETURNS TABLE(code text, report text, state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_client text;
  v_clear text[];
  v_keys text[];
  v_rel record;
  v_found record;
  v_seen integer;
  v_label text[];
begin
  perform ledger.lock_rows(array['relations:wrong_reports']);
  select c.client_id, c.clearance into v_client, v_clear from ledger.agent_mail_caller('report_wrong_relation', p_session) c;
  if p_id is null or p_id !~ '^rrp_[0-9A-HJKMNP-TV-Z]{26}$' or p_request is null or p_request !~ '^[A-Za-z0-9_-]{8,64}$'
     or p_relation is null or p_relation < 1
     or p_because is null
     or p_because not in ('not_same_fact', 'not_superseded', 'not_contradicting', 'source_misread', 'different_subjects')
     or p_cites is null or array_position(p_cites, null) is not null or cardinality(p_cites) > 20 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  select r.id, r.relation_id, r.session_id, r.compartments,
         r.compartments <@ v_clear and policy.label_key(r.compartments) = any (v_keys) as seen into v_found
  from ledger.relation_reports r where r.client_id = v_client and r.request_id = p_request;
  if found then
    if v_found.seen then
      return query select 'ok'::text, v_found.id,
        case when exists (select 1 from ledger.relation_reports o
                          where o.relation_id = v_found.relation_id and o.client_id <> v_client and o.session_id <> v_found.session_id
                            and o.compartments = v_found.compartments and policy.label_key(o.compartments) = any (v_keys))
             then 'agreed' else 'filed' end;
    else
      return query select 'not_found'::text, null::text, null::text;
    end if;
    return;
  end if;
  if coalesce((select s.identity_agents from policy.work_settings s), 'off') <> 'on' then
    return query select 'agents_off'::text, null::text, null::text;
    return;
  end if;
  select r.id, r.from_claim_key, r.to_claim_key, r.compartments into v_rel
  from knowledge.claim_relations r
  where r.id = p_relation and starts_with(r.judged_by, 'model:') and r.kind in ('same_fact', 'supersedes', 'contradicts')
    and r.compartments <@ v_clear and policy.label_key(r.compartments) = any (v_keys)
    and policy.relation_effective(r.id, r.judged_by, r.kind, r.judged_at, now())
    and coalesce((select w.switched_on from policy.relation_switches w where w.kind = r.kind and w.judge = r.judged_by
                  order by (w.decided_by = 'owner') desc, w.decided_at desc, w.id desc limit 1), false)
    and exists (select 1 from knowledge.claim_values v where v.claim_key = r.from_claim_key
                  and v.compartments <@ v_clear and policy.label_key(v.compartments) = any (v_keys))
    and exists (select 1 from knowledge.claim_values v where v.claim_key = r.to_claim_key
                  and v.compartments <@ v_clear and policy.label_key(v.compartments) = any (v_keys));
  if not found then
    return query select 'not_found'::text, null::text, null::text;
    return;
  end if;
  if exists (select 1 from knowledge.claim_relations o
             where starts_with(o.judged_by, 'owner:')
               and ((o.from_claim_key = v_rel.from_claim_key and o.to_claim_key = v_rel.to_claim_key)
                    or (o.from_claim_key = v_rel.to_claim_key and o.to_claim_key = v_rel.from_claim_key))
               and o.compartments <@ v_clear and policy.label_key(o.compartments) = any (v_keys))
     or exists (select 1 from ledger.source_checks s
                where s.target = 'relation' and s.relation_id = p_relation and starts_with(s.judge, 'owner:')
                  and s.verdict in ('supported', 'wrong')
                  and s.compartments <@ v_clear and policy.label_key(s.compartments) = any (v_keys)) then
    return query select 'owner_ruled'::text, null::text, null::text;
    return;
  end if;
  select count(*) into v_seen from (
    select m.id from knowledge.messages m where m.id = any (p_cites) and not m.held and not m.restricting
      and m.compartments <@ v_clear and policy.label_key(m.compartments) = any (v_keys)
    union all
    select d.id from knowledge.documents d where d.id = any (p_cites) and not d.held
      and d.compartments <@ v_clear and policy.label_key(d.compartments) = any (v_keys)
  ) as x;
  if v_seen <> (select count(distinct c.one) from unnest(p_cites) as c (one)) then
    return query select 'not_found'::text, null::text, null::text;
    return;
  end if;
  if cardinality(p_cites) = 0 then
    return query select 'no_evidence'::text, null::text, null::text;
    return;
  end if;
  if exists (select 1 from ledger.relation_reports r where r.relation_id = p_relation and r.client_id = v_client) then
    return query select 'already_reported'::text, null::text, null::text;
    return;
  end if;
  v_label := ledger.label(v_rel.compartments
    || array(select c.one from knowledge.messages m cross join lateral unnest(m.compartments) as c (one)
             where m.id = any (p_cites) and policy.label_key(m.compartments) = any (v_keys))
    || array(select c.one from knowledge.documents d cross join lateral unnest(d.compartments) as c (one)
             where d.id = any (p_cites) and policy.label_key(d.compartments) = any (v_keys)));
  insert into ledger.relation_reports (id, request_id, relation_id, claim_keys, client_id, session_id, because, cites, evidence_ids,
    created_at, compartments)
  values (p_id, p_request, p_relation, array[v_rel.from_claim_key, v_rel.to_claim_key], v_client, p_session, p_because,
          array(select distinct c.one from unnest(p_cites) as c (one) order by c.one),
          array(select m.evidence_id from knowledge.messages m where m.id = any (p_cites) and policy.label_key(m.compartments) = any (v_keys)
                union select d.evidence_id from knowledge.documents d where d.id = any (p_cites) and policy.label_key(d.compartments) = any (v_keys)),
          now(), v_label);
  return query select 'ok'::text, p_id,
    case when exists (select 1 from ledger.relation_reports o
                      where o.relation_id = p_relation and o.client_id <> v_client and o.session_id <> p_session
                        and o.compartments = v_label and policy.label_key(o.compartments) = any (v_keys))
         then 'agreed' else 'filed' end;
end
$_$;

CREATE FUNCTION ledger.research_state(request text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select e.event from ledger.record_events e where e.row_kind = 'research_request' and e.row_id = research_state.request order by e.id desc limit 1
$$;

CREATE FUNCTION ledger.retire_shown_lessons(ref_kinds text[], ref_ids text[], address_fps text[], dry_run boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  hit text[];
  total integer := 0;
begin
  perform pg_advisory_xact_lock(hashtext('intelligence personal ledger taint'));
  loop
  with gone as (
    select r.kind, r.id from unnest(retire_shown_lessons.ref_kinds, retire_shown_lessons.ref_ids) as r (kind, id)
  )
  select coalesce(array_agg(h.id order by h.id), '{}'::text[]) into hit
  from ledger.hypotheses h join ledger.runs r on r.id = h.run_id
  where h.kind = 'lesson' and h.tainted_at is null and r.decisions is not null
    and exists (
      select 1 from knowledge.owner_decisions d
      where d.id = any (r.decisions)
        and (d.tainted_at is not null
             or d.subject_fps && retire_shown_lessons.address_fps
             or (d.target_kind, d.target_id) in (select g.kind, g.id from gone g)
             or (d.target_kind = 'opportunity' and exists (
                   select 1 from ledger.opportunities o where o.id = d.target_id
                     and (o.tainted_at is not null or (o.about_kind, o.about_id) in (select g.kind, g.id from gone g))))
             or (d.target_kind = 'hypothesis' and exists (select 1 from ledger.hypotheses x where x.id = d.target_id and x.tainted_at is not null))
             or (d.card_id is not null and exists (
                   select 1 from ledger.cards c where c.id = d.card_id
                     and (c.tainted_at is not null or (c.target_kind, c.target_id) in (select g.kind, g.id from gone g)
                          or (c.target_kind = 'opportunity' and exists (
                                select 1 from ledger.opportunities o where o.id = c.target_id and (o.about_kind, o.about_id) in (select g.kind, g.id from gone g))))))));
  if retire_shown_lessons.dry_run or cardinality(hit) = 0 then
    return total + cardinality(hit);
  end if;
  total := total + cardinality(hit);

  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'hypothesis', h.id, case s.latest when 'confirmed' then 'retired' else 'withdrawn' end, now(), 'system:taint', h.compartments
  from ledger.hypotheses h
  cross join lateral (select e.event as latest from ledger.record_events e where e.row_kind = 'hypothesis' and e.row_id = h.id order by e.id desc limit 1) s
  where h.id = any (hit) and s.latest in ('open', 'supported', 'asked', 'confirmed');
  update ledger.hypotheses h set tainted_at = now(), body_enc = null where h.id = any (hit);
  perform ledger.taint_citing('{}'::text[], array_fill('hypothesis'::text, array[cardinality(hit)]), hit);
  end loop;
end
$$;

CREATE FUNCTION ledger.revoke_device_oauth(client_id text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_count integer;
begin
  if not exists (select 1 from policy.lens_devices d where revoke_device_oauth.client_id in (d.capture_client_id, d.mirror_client_id)) then
    return 0;
  end if;
  update policy.oauth_tokens t set revoked_at = now()
  where t.client_id = revoke_device_oauth.client_id and t.revoked_at is null;
  get diagnostics v_count = row_count;
  return v_count;
end
$$;

CREATE FUNCTION ledger.roll_ping_batches(p_now timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_client text;
  v_batch text;
  v_count integer;
  v_made integer := 0;
begin
  for v_client in
    select n.client_id from ledger.work_notices n
    where n.batched and n.state = 'pending' and n.client_id is not null and n.next_try_at <= p_now
    group by n.client_id order by n.client_id collate "C"
  loop
    update ledger.work_notices n set state = 'stale'
    where n.client_id = v_client and n.batched and n.state = 'pending' and n.next_try_at <= p_now
      and not ledger.notice_due(n.opportunity_id, n.client_id);
    select count(distinct n.opportunity_id)::integer into v_count from ledger.work_notices n
    where n.client_id = v_client and n.batched and n.state = 'pending' and n.next_try_at <= p_now;
    if v_count > 0 then
      v_batch := ledger.new_id('ntc');
      insert into ledger.batch_notices (id, client_id, count) values (v_batch, v_client, v_count);
      update ledger.work_notices n set state = 'rolled'
      where n.client_id = v_client and n.batched and n.state = 'pending' and n.next_try_at <= p_now;
      v_made := v_made + 1;
    end if;
  end loop;
  return v_made;
end
$$;

CREATE FUNCTION ledger.route_of(opportunity_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select case
    when exists (select 1 from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = route_of.opportunity_id and r.event = 'routed')
      then (select r.role from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = route_of.opportunity_id and r.event = 'routed' order by r.id desc limit 1)
    else (select o.role from ledger.opportunities o where o.id = route_of.opportunity_id) end
$$;

CREATE FUNCTION ledger.rule_answers() RETURNS TABLE(kind text, pattern text, answer text, at timestamp with time zone, compartments text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select c.kind, ledger.card_pattern(c.id), d.answer, d.decided_at, c.compartments
  from knowledge.owner_decisions d join ledger.cards c on c.id = d.card_id
  where d.kind = 'answer' and d.tainted_at is null and d.answer is not null and c.tainted_at is null and not d.batch
    and not exists (select 1 from knowledge.owner_decisions s where s.supersedes = d.id)
    and c.kind in ('about_you', 'agent_claim', 'idea', 'opportunity_decision', 'same_person')
    and (c.kind <> 'same_person' or coalesce((select s.identity_agents = 'on' from policy.work_settings s), false))
$$;

CREATE FUNCTION ledger.rule_time(p_id text, p_request_id text, p_session_id text, p_project_id text, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(code text, ruling_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
  v_found text;
  v_label text[];
begin
  select c.client_id, c.clearance into v_caller, v_clearance from ledger.agent_mail_caller('rule_time', p_session_id) c;
  if p_id is null or p_id !~ '^atr_[0-9A-HJKMNP-TV-Z]{26}$' or p_request_id is null or p_request_id !~ '^[A-Za-z0-9_-]{8,64}$'
     or p_from is null or p_to is null or p_to <= p_from or p_to - p_from > interval '24 hours' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  perform ledger.lock_rows(array['agent_ruling ' || v_caller || ' ' || p_request_id]);
  select r.id into v_found from knowledge.agent_time_rulings r
  where r.client_id = v_caller and r.request_id = p_request_id and r.tool = 'rule_time' order by r.from_at, r.id collate "C" limit 1;
  if v_found is not null then
    return query select 'ok'::text, v_found;
    return;
  end if;
  select p.compartments into v_label from knowledge.projects p
  where p.id = p_project_id and p.status = 'active'
    and p.compartments <@ v_clearance and policy.label_key(p.compartments) = any (v_keys);
  if v_label is null then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  if ledger.time_vetoed(p_project_id, p_from, p_to, v_clearance, v_keys) then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  insert into knowledge.agent_time_rulings (id, project_id, from_at, to_at, tool, client_id, request_id, created_at, compartments, reach)
  values (p_id, p_project_id, p_from, p_to, 'rule_time', v_caller, p_request_id, now(), ledger.label(v_label), ledger.label(v_clearance));
  return query select 'ok'::text, p_id;
end
$_$;

CREATE FUNCTION ledger.run_owner_actions(run_id text) RETURNS TABLE(decision_id text, decision_kind text, answer text, card_kind text, decided_at timestamp with time zone, compartments text[], body_enc jsonb, target_kind text, object_table text, object_id text, object_column text, object_kind text, object_compartments text[], object_enc jsonb, reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_views text[];
  v_tools text[];
  v_clearance text[];
  v_label text[];
  v_decisions text[];
  v_keys text[];
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('next_run' = any (v_tools)) or not ('work' = any (v_views)) or policy.current_client_kind() is distinct from 'reasoner' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  select r.compartments, r.decisions into v_label, v_decisions from ledger.runs r
  where r.id = run_owner_actions.run_id and r.compartments <@ v_clearance
    and (select t.client_id from ledger.run_attempts t where t.run_id = r.id order by t.attempt desc limit 1) = v_caller;
  if v_decisions is null then
    return;
  end if;
  return query
  select d.id, d.kind, d.answer, c.kind, d.decided_at, d.compartments,
    case when d.kind in ('answer', 'goal_set', 'goal_reword') then d.body_enc end,
    d.target_kind, o.tbl, o.oid, o.col, o.okind, o.comps, o.enc,
    (select e.code from ledger.record_events e
     where e.row_kind = coalesce(c.target_kind, d.target_kind) and e.row_id = coalesce(c.target_id, d.target_id)
       and e.by = 'owner' and e.at = d.decided_at and e.code is not null and e.compartments <@ v_label
       and policy.label_key(e.compartments) = any (v_keys)
     order by e.id desc limit 1)
  from unnest(v_decisions) with ordinality as x (one, ord)
  join knowledge.owner_decisions d on d.id = x.one
  left join ledger.cards c on d.kind = 'answer' and c.id = d.card_id
  left join lateral (
    select 'projections.goal_state'::text, g.goal_id, 'statement_enc'::text, null::text, g.compartments, g.statement_enc
    from projections.goal_state g where d.target_kind = 'goal' and g.goal_id = d.target_id
    union all
    select 'ledger.opportunities', p.id, 'body_enc', p.kind, p.compartments, p.body_enc
    from ledger.opportunities p where d.kind <> 'answer' and d.target_kind = 'opportunity' and p.id = d.target_id and p.tainted_at is null
    union all
    select 'ledger.cards', c.id, 'body_enc', c.kind, c.compartments, c.body_enc where c.id is not null and c.tainted_at is null and c.body_enc is not null
    union all
    select 'ledger.opportunities', p.id, 'body_enc', p.kind, p.compartments, p.body_enc
    from ledger.opportunities p where c.id is not null and c.body_enc is null and c.tainted_at is null and c.target_kind = 'opportunity' and p.id = c.target_id and p.tainted_at is null
    union all
    select 'ledger.hypotheses', h.id, 'body_enc', h.kind, h.compartments, h.body_enc
    from ledger.hypotheses h where c.id is not null and c.body_enc is null and c.tainted_at is null and c.target_kind = 'hypothesis' and h.id = c.target_id and h.tainted_at is null
    union all
    select 'knowledge.projects', j.id, 'name_enc', null, j.compartments, j.name_enc
    from knowledge.projects j where d.kind in ('project_add', 'project_anchor', 'project_unanchor', 'project_close') and d.target_kind = 'entity' and j.id = d.target_id
  ) o (tbl, oid, col, okind, comps, enc) on o.comps <@ v_label
  where d.tainted_at is null and d.compartments <@ v_label
  order by x.ord;
end
$$;

CREATE FUNCTION ledger.same_person_blocked(p_a text, p_b text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select policy.vetoed(array['entity'], array[p_a], 'research') or policy.vetoed(array['entity'], array[p_b], 'research')
    or exists (select 1 from ledger.opportunity_decisions d join ledger.opportunities o on o.id = d.opportunity_id
               where d.decided_by = 'owner' and d.decision = 'no_go' and o.kind in ('investigate', 'research')
                 and o.about_kind = 'entity' and o.about_id in (p_a, p_b))
$$;

CREATE FUNCTION ledger.same_person_clients() RETURNS TABLE(name text, compartments text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select c.name, c.compartments from policy.clients c
  where c.status = 'active' and c.kind = 'agent'
    and coalesce((select r.role from policy.gap_routes r where r.trigger = 'same_person'), (select s.default_task_role from policy.work_settings s)) = any (c.roles)
$$;

CREATE FUNCTION ledger.same_person_gaps() RETURNS TABLE(trigger text, subject text, label text[], goal_id text, about_kind text, about_id text, source_kind text, source_id text, at timestamp with time zone, due_at timestamp with time zone, facts integer, ties integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select 'same_person'::text, q.batch, q.compartments, null::text, 'entity'::text, min(q.a_entity collate "C"), 'entity'::text, min(q.a_entity collate "C"),
    max(q.updated_at), null::timestamptz, null::integer, null::integer
  from ledger.identity_questions q
  where q.state = 'agents' and q.batch is not null
    and coalesce((select s.identity_agents from policy.work_settings s), 'off') = 'on'
  group by q.batch, q.compartments
  order by q.batch
$$;

CREATE FUNCTION ledger.same_person_rebatch() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_n integer;
begin
  update ledger.identity_questions q set state = 'resting', batch = null
  where q.state = 'agents' and q.batch is not null and exists (
    select 1 from ledger.opportunities o join ledger.opportunity_decisions d on d.opportunity_id = o.id
    where o.gap_trigger = 'same_person' and o.gap_subject = q.batch and d.decision = 'no_go' and d.decided_by = 'owner');
  update ledger.identity_questions q set state = 'owner', batch = null
  where q.state = 'agents' and policy.is_restricted(q.compartments);
  update ledger.identity_questions q set batch = null
  where q.state = 'agents' and q.batch is not null and ledger.same_person_blocked(q.a_entity, q.b_entity)
    and not exists (select 1 from ledger.opportunities o where o.gap_trigger = 'same_person' and o.gap_subject = q.batch);
  update ledger.identity_questions q set batch = null, offers = q.offers + 1
  where q.state = 'agents' and q.batch is not null and exists (
    select 1 from ledger.opportunities o where o.gap_trigger = 'same_person' and o.gap_subject = q.batch
      and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id order by r.id desc limit 1)
          in ('done', 'failed', 'expired', 'withdrawn', 'no_go'));
  get diagnostics v_n = row_count;
  return v_n;
end
$$;

CREATE FUNCTION ledger.same_person_side(p_entity text, p_keys text[]) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with recursive fps (fp) as (
    select a.value_fp from knowledge.accounts a where a.entity_id = p_entity and policy.label_key(a.compartments) = any (p_keys)
    union
    select case when r.a_fp = f.fp then r.b_fp else r.a_fp end
    from knowledge.identity_rulings r join fps f on r.a_fp = f.fp or r.b_fp = f.fp
    where r.verdict = 'same' and r.lifted_at is null and r.b_fp is not null
      and exists (select 1 from knowledge.accounts x where x.value_fp = case when r.a_fp = f.fp then r.b_fp else r.a_fp end and policy.label_key(x.compartments) = any (p_keys))
  )
  select array(select distinct one from (
    select p_entity as one
    union all
    select a.entity_id from knowledge.accounts a join fps f on f.fp = a.value_fp
    where policy.label_key(a.compartments) = any (p_keys)) as members)
$$;

CREATE FUNCTION ledger.sent_tag(account_id text, source_item_fp text, thread_fp text, body_fp text, recipient_fps text[], outbound boolean, observed_at timestamp with time zone) RETURNS TABLE(system_originated boolean, answers_system boolean, sent_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_sent text;
  v_recipients text[] := array(select distinct x collate "C" from unnest(coalesce(sent_tag.recipient_fps, '{}'::text[])) as x order by 1);
begin
  if sent_tag.outbound then
    select s.id into v_sent from ledger.sent_messages s
    where s.source_account_id = sent_tag.account_id and s.source_item_fp = sent_tag.source_item_fp
    order by s.begun_at, s.id collate "C" limit 1;
    if v_sent is null and sent_tag.body_fp is not null then
      select s.id into v_sent from ledger.sent_messages s
      where s.source_account_id = sent_tag.account_id and s.sent_at is null and s.body_fp = sent_tag.body_fp and s.recipient_fps = v_recipients
        and s.begun_at <= sent_tag.observed_at
        and (select r.event from ledger.record_events r where r.row_kind = 'send' and r.row_id = s.id order by r.id desc limit 1) <> 'failed'
        and not exists (select 1 from vault.evidence_items e where e.sent_id = s.id and e.source_item_fp <> sent_tag.source_item_fp)
      order by s.begun_at, s.id collate "C" limit 1;
    end if;
    return query select v_sent is not null, false, v_sent;
    return;
  end if;
  return query select false,
    sent_tag.thread_fp is not null and (
      exists (select 1 from ledger.sent_messages s join ledger.drafts d on d.id = s.draft_id
              where s.source_account_id = sent_tag.account_id and coalesce(s.thread_fp, d.thread_fp) = sent_tag.thread_fp
                and s.begun_at < sent_tag.observed_at
                and (select r.event from ledger.record_events r where r.row_kind = 'send' and r.row_id = s.id order by r.id desc limit 1) <> 'failed')
      or exists (select 1 from vault.evidence_items e
                 where e.source_account_id = sent_tag.account_id and e.thread_fp = sent_tag.thread_fp and e.system_originated
                   and e.observed_at < sent_tag.observed_at)),
    null::text;
end
$$;

CREATE FUNCTION ledger.session_path(session_id text) RETURNS TABLE(untrusted boolean, sensitive boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_caller text;
  v_keys text[];
begin
  select c.id into v_caller from policy.current_client() c;
  if v_caller is null
     or not exists (select 1 from ledger.sessions s where s.id = session_path.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  return query
  with served as materialized (
    select distinct b.one as evidence_id
    from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
    where r.session_id = session_path.session_id and r.client_id = v_caller and r.read_at <= now()
      and b.one ~ '^[0-9a-f]{64}$'
  ),
  items as materialized (
    select e.id, e.source_kind, e.compartments
    from served v join vault.evidence_items e on e.id = v.evidence_id
    where policy.label_key(e.compartments) = any (v_keys)
  )
  select
    exists (select 1 from items i where i.source_kind = 'web_research')
    or exists (
      select 1 from items i join knowledge.messages m on m.evidence_id = i.id
      where m.direction = 'inbound' and policy.label_key(m.compartments) = any (v_keys)
        and (m.sender_fp is null or not exists (
          select 1 from vault.sent_recipients t
          where t.address_fp = m.sender_fp and policy.label_key(t.compartments) = any (v_keys)))),
    exists (
      select 1 from items i cross join lateral unnest(i.compartments) as c (one)
      where (c.one like 'employer:%' and c.one not like '%-released') or c.one like 'restricted:%');
end
$_$;

CREATE FUNCTION ledger.session_reads(evidence_id text) RETURNS TABLE(bound text[], fact_key_fps text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  return query
    select
      coalesce((select array_agg(d.x order by d.x collate "C") from (
                  select distinct b.x from ledger.read_log r cross join unnest(r.bound) as b (x)
                  where r.session_id = w.session_id and r.read_at <= w.created_at) d), '{}'::text[]),
      coalesce((select array_agg(d.x order by d.x collate "C") from (
                  select distinct f.x from ledger.read_log r cross join unnest(r.fact_key_fps) as f (x)
                  where r.session_id = w.session_id and r.read_at <= w.created_at) d), '{}'::text[])
    from ledger.agent_writes w
    where w.evidence_id = session_reads.evidence_id and w.body_enc is not null;
end
$$;

CREATE FUNCTION ledger.set_anchor(p_id text, p_request_id text, p_session_id text, p_project_id text, p_kind text, p_anchor_fp text, p_value_enc jsonb) RETURNS TABLE(code text, anchor_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
  v_found text;
  v_label text[];
begin
  select c.client_id, c.clearance into v_caller, v_clearance from ledger.agent_mail_caller('set_anchor', p_session_id) c;
  if p_id is null or p_id !~ '^aan_[0-9A-HJKMNP-TV-Z]{26}$' or p_request_id is null or p_request_id !~ '^[A-Za-z0-9_-]{8,64}$'
     or p_kind is null or p_kind not in ('repository', 'host', 'document', 'app')
     or p_anchor_fp is null or p_anchor_fp !~ '^[0-9a-f]{64}$'
     or p_value_enc is null or jsonb_typeof(p_value_enc) <> 'object' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  perform ledger.lock_rows(array['agent_anchor ' || v_caller || ' ' || p_request_id]);
  select a.id into v_found from knowledge.agent_anchors a where a.client_id = v_caller and a.request_id = p_request_id;
  if v_found is not null then
    return query select 'ok'::text, v_found;
    return;
  end if;
  select p.compartments into v_label from knowledge.projects p
  where p.id = p_project_id and p.status = 'active'
    and p.compartments <@ v_clearance and policy.label_key(p.compartments) = any (v_keys);
  if v_label is null then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  perform ledger.lock_rows(array['agent_anchor_fp ' || p_anchor_fp]);
  if exists (select 1 from knowledge.project_anchors o
             where o.anchor_fp = p_anchor_fp and o.project_id = p_project_id and o.lifted_at is not null
               and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)) then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  select a.id into v_found from knowledge.agent_anchors a
  where a.anchor_fp = p_anchor_fp and a.kind = p_kind and a.project_id = p_project_id and a.lifted_at is null
    and a.client_id = v_caller
    and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys)
  order by a.created_at, a.id collate "C" limit 1;
  if v_found is not null then
    return query select 'ok'::text, v_found;
    return;
  end if;
  if exists (select 1 from knowledge.agent_anchors a
             where a.anchor_fp = p_anchor_fp and a.kind = p_kind and a.lifted_at is null and a.project_id <> p_project_id
               and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys)) then
    return query select 'anchor_taken'::text, null::text;
    return;
  end if;
  insert into knowledge.agent_anchors (id, project_id, kind, anchor_fp, value_enc, client_id, request_id, created_at, compartments)
  values (p_id, p_project_id, p_kind, p_anchor_fp, p_value_enc, v_caller, p_request_id, now(), ledger.label(v_label));
  return query select 'ok'::text, p_id;
end
$_$;

CREATE FUNCTION ledger.set_details(opportunity_id text, session_id text, details_enc jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_done integer;
begin
  select c.id into v_caller from policy.current_client() c;
  if v_caller is null or set_details.details_enc is null
     or not exists (select 1 from ledger.sessions s where s.id = set_details.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  perform ledger.lock_rows(array[set_details.opportunity_id]);
  update ledger.opportunities o set details_enc = set_details.details_enc
  where o.id = set_details.opportunity_id and o.created_by = 'client:' || v_caller and o.session_id = set_details.session_id
    and o.details_enc is null and o.tainted_at is null and o.created_at = now();
  get diagnostics v_done = row_count;
  return v_done = 1;
end
$$;

CREATE FUNCTION ledger.set_expectations(opportunity_id text, session_id text, expects jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
  v_author text;
  v_opportunity ledger.opportunities%rowtype;
  v_written integer;
begin
  select c.id, c.compartments into v_caller, v_clearance from policy.current_client() c;
  if v_caller is null or not exists (select 1 from ledger.sessions s where s.id = set_expectations.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if jsonb_typeof(set_expectations.expects) is distinct from 'array' or jsonb_array_length(set_expectations.expects) not between 1 and 5
     or exists (select 1 from jsonb_array_elements(set_expectations.expects) x
                where jsonb_typeof(x) <> 'object'
                   or not (x ? 'type') or jsonb_typeof(x -> 'type') <> 'string' or not ((x ->> 'type') ~ '^[a-z][a-z0-9_]{0,31}$')
                   or jsonb_typeof(x -> 'horizonDays') is distinct from 'number' or (x ->> 'horizonDays') !~ '^[0-9]{1,3}$' or (x ->> 'horizonDays')::integer not between 1 and 365
                   or (x ->> 'origin') is null or (x ->> 'origin') not in ('stated', 'default')
                   or jsonb_typeof(coalesce(x -> 'subject', 'null'::jsonb)) not in ('null', 'string')
                   or ((x ->> 'subject') is not null and (x ->> 'subject') !~ '^ent_[0-9A-HJKMNP-TV-Z]{26}$')
                   or jsonb_typeof(coalesce(x -> 'success', 'null'::jsonb)) not in ('null', 'object')
                   or jsonb_typeof(coalesce(x -> 'failure', 'null'::jsonb)) not in ('null', 'object')) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  v_author := 'client:' || v_caller;
  perform ledger.lock_rows(array[set_expectations.opportunity_id]);
  select o.* into v_opportunity from ledger.opportunities o
  where o.id = set_expectations.opportunity_id
    and ((o.created_by = v_author and o.session_id = set_expectations.session_id)
         or (o.run_id is not null and o.created_by = 'run:' || o.run_id
             and exists (select 1 from (select t.client_id, t.session_id from ledger.run_attempts t where t.run_id = o.run_id and policy.label_key(t.compartments) = any (v_keys) order by t.attempt desc limit 1) l
                         where l.client_id = v_caller and l.session_id = o.session_id)))
    and o.tainted_at is null and o.created_at = now() and policy.label_key(o.compartments) = any (v_keys)
    and not exists (select 1 from ledger.expected_outcomes x where x.opportunity_id = o.id);
  if v_opportunity.id is null then
    return 0;
  end if;
  if exists (select 1 from jsonb_array_elements(set_expectations.expects) x
             where (x ->> 'subject') is not null and not ledger.entity_seen(x ->> 'subject', v_clearance, v_keys)) then
    raise exception 'invalid request' using errcode = '22023';
  end if;

  with given as (
    select (x.n - 1)::integer as ordinal, x.one,
      case when (x.one ->> 'type') = 'goal_claim' then 'goal'
           when (x.one ->> 'subject') is not null then 'entity'
           when v_opportunity.about_kind in ('entity', 'event', 'goal') then v_opportunity.about_kind
           else 'counterpart' end as subject_kind,
      case when (x.one ->> 'type') = 'goal_claim' then v_opportunity.goal_id
           when (x.one ->> 'subject') is not null then x.one ->> 'subject'
           when v_opportunity.about_kind in ('entity', 'event', 'goal') then v_opportunity.about_id end as subject_id
    from jsonb_array_elements(set_expectations.expects) with ordinality as x (one, n)
  ),
  written as (
    insert into ledger.expected_outcomes (opportunity_id, ordinal, created_by, origin, subject_kind, subject_id, outcome_type, success_enc, failure_enc, horizon_days, compartments)
    select v_opportunity.id, g.ordinal, v_author, g.one ->> 'origin', g.subject_kind, g.subject_id, g.one ->> 'type',
      nullif(g.one -> 'success', 'null'::jsonb), nullif(g.one -> 'failure', 'null'::jsonb), (g.one ->> 'horizonDays')::integer, v_opportunity.compartments
    from given g
    where g.subject_kind = 'counterpart' or g.subject_id is not null
    returning subject_kind, subject_id
  ),
  watched as (
    insert into ledger.work_watches (opportunity_id, created_by, kind, watch_key, compartments)
    select distinct v_opportunity.id, v_author, 'entity', w.subject_id, v_opportunity.compartments
    from written w where w.subject_kind = 'entity'
    returning 1
  )
  select count(*)::integer into v_written from written;
  return v_written;
end
$_$;

CREATE FUNCTION ledger.set_improvement_role(improvement_id text, role text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
begin
  if set_improvement_role.role is not null and set_improvement_role.role !~ '^[a-z][a-z0-9-]{1,31}$' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  update ledger.improvements i set assignee_role = set_improvement_role.role, owner_role_at = now()
  where i.id = set_improvement_role.improvement_id and i.tainted_at is null;
  return found;
end
$_$;

CREATE FUNCTION ledger.set_intention(id text, request_id text, session_id text, opportunity_id text, due_at timestamp with time zone, keep_earlier boolean, park boolean) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  return ledger.set_intention(set_intention.id, set_intention.request_id, set_intention.session_id, set_intention.opportunity_id,
                              set_intention.due_at, set_intention.keep_earlier, set_intention.park, null::jsonb);
end
$$;

CREATE FUNCTION ledger.set_intention(id text, request_id text, session_id text, opportunity_id text, due_at timestamp with time zone, keep_earlier boolean, park boolean, body_enc jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_author text;
  v_label text[];
  v_found text;
  v_live boolean;
  v_hold boolean;
  v_status text;
  v_go timestamptz;
  v_held boolean;
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('set_intention' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = set_intention.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  v_author := 'client:' || v_caller;
  v_label := ledger.label(v_clearance);
  perform ledger.lock_rows(array(select o.id from ledger.opportunities o
                                 where o.id = set_intention.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)));

  select i.id into v_found from ledger.intentions i where i.created_by = v_author and i.request_id = set_intention.request_id;
  if v_found is not null then
    return v_found;
  end if;
  if coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on' then
    return 'kill_switch';
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = set_intention.session_id and b.one ~ '^[0-9a-f]{64}$'
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return null;
  end if;
  v_live := exists (
      select 1 from ledger.opportunities o
      join queue.leases l on l.resource_kind = 'opportunity' and l.resource_id = o.id
      where o.id = set_intention.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys) and o.tainted_at is null
        and l.holder = v_caller and l.lease_until >= now()
        and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) = 'claimed');
  v_hold := coalesce(set_intention.park, true);
  if not v_live and not exists (
      select 1 from ledger.opportunities o
      join queue.leases l on l.resource_kind = 'opportunity' and l.resource_id = o.id
      where o.id = set_intention.opportunity_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys) and o.tainted_at is null
        and l.holder = v_caller
        and ledger.work_held(o.id, now())
        and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) in ('claimed', 'go')) then
    return null;
  end if;
  if set_intention.body_enc is not null and jsonb_typeof(set_intention.body_enc) <> 'object' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if set_intention.due_at is null or set_intention.due_at < now() + interval '1 hour'
     or set_intention.due_at > now() + interval '90 days'
     or (v_hold and set_intention.due_at > now() + interval '30 days') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_go := (select max(d.created_at) from ledger.opportunity_decisions d
           where d.opportunity_id = set_intention.opportunity_id and d.decision = 'go');
  if v_go is not null and set_intention.due_at > v_go + interval '90 days' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if v_hold and (select count(distinct i.opportunity_id) from ledger.intentions i
                 where i.client_id = v_caller and i.kind = 'check_back' and i.hold and i.tainted_at is null
                   and i.opportunity_id <> set_intention.opportunity_id
                   and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys)
                   and (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) = 'set') >= 20 then
    return 'holds_full';
  end if;
  if not coalesce(set_intention.keep_earlier, false) then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
    select 'intention', i.id, 'cancelled', now(), v_author, i.compartments, set_intention.session_id
    from ledger.intentions i
    where i.opportunity_id = set_intention.opportunity_id and i.kind = 'check_back' and i.client_id = v_caller
      and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys)
      and (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) = 'set';
  end if;
  if (select count(*) from ledger.intentions i where i.opportunity_id = set_intention.opportunity_id and i.kind = 'check_back'
      and i.client_id = v_caller
      and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys)
      and (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) = 'set') >= 3 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_held := ledger.check_back_holds(set_intention.opportunity_id, v_caller);
  insert into ledger.intentions (id, request_id, created_by, session_id, compartments, opportunity_id, kind, due_at, client_id, chain_depth, body_enc, hold)
  values (set_intention.id, set_intention.request_id, v_author, set_intention.session_id, v_label, set_intention.opportunity_id, 'check_back',
          set_intention.due_at, v_caller, 0, set_intention.body_enc, v_hold);
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id)
  values ('intention', set_intention.id, 'set', now(), v_author, v_label, set_intention.session_id);
  v_status := (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = set_intention.opportunity_id
               and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1);
  if v_hold and v_status = 'claimed' then
    update queue.leases l set lease_until = set_intention.due_at + interval '10 minutes', preferred_until = null
    where l.resource_kind = 'opportunity' and l.resource_id = set_intention.opportunity_id and l.holder = v_caller;
  elsif not v_hold and v_status = 'claimed' and not v_held then
    update queue.leases l set lease_until = now() + interval '1800 seconds'
    where l.resource_kind = 'opportunity' and l.resource_id = set_intention.opportunity_id and l.holder = v_caller
      and l.lease_until > now() + interval '1800 seconds';
  end if;
  return set_intention.id;
end
$_$;

CREATE FUNCTION ledger.settle_belief(p_id text, p_request text, p_opportunity text, p_move text, p_finding text, p_holds text, p_cited_kinds text[], p_cited_ids text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_client record;
  v_finding ledger.dream_findings;
  v_keys text[];
begin
  perform ledger.lock_rows('{}'::text[]);
  v_keys := policy.clearance_keys();
  if p_id is null or p_id !~ '^bst_[0-9A-HJKMNP-TV-Z]{26}$' or p_request is null or p_request !~ '^[A-Za-z0-9_-]{8,64}$'
     or p_opportunity is null or p_move is null or p_finding is null or p_finding !~ '^dfd_[0-9A-HJKMNP-TV-Z]{26}$'
     or p_holds is null or p_holds not in ('a', 'b')
     or p_cited_kinds is null or p_cited_ids is null or cardinality(p_cited_kinds) <> cardinality(p_cited_ids) or cardinality(p_cited_ids) > 100
     or exists (select 1 from unnest(p_cited_kinds, p_cited_ids) as r (kind, id)
                where r.kind is null or r.kind !~ '^[a-z][a-z0-9_]{0,31}$' or r.id is null or r.id !~ '^[A-Za-z0-9_-]{1,128}$'
                   or starts_with(r.id, 'hdl_')) then
    return 'invalid';
  end if;
  select c.id, c.name, c.compartments into v_client from policy.current_client() c;
  if not found then
    return 'not_found';
  end if;
  if exists (select 1 from ledger.belief_settlements s where s.client_id = v_client.id and s.request_id = p_request
             and policy.label_key(s.compartments) = any (v_keys)) then
    return 'ok';
  end if;
  select f.* into v_finding from ledger.dream_findings f
  join ledger.opportunities o on o.id = p_opportunity and o.gap_trigger = 'dream_finding' and o.gap_subject = f.id
    and o.tainted_at is null and policy.label_key(o.compartments) = any (v_keys)
  where f.id = p_finding and policy.label_key(f.compartments) = any (v_keys)
    and exists (select 1 from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = o.id and l.holder = v_client.id and l.lease_until >= now())
    and exists (select 1 from ledger.moves m where m.id = p_move and m.opportunity_id = o.id and m.tainted_at is null
                and policy.label_key(m.compartments) = any (v_keys));
  if not found or not (v_finding.compartments <@ v_client.compartments) then
    return 'not_found';
  end if;
  perform ledger.lock_rows(array['finding:' || v_finding.id]);
  if exists (select 1 from ledger.belief_settlements s where s.finding_id = v_finding.id and s.lifted_at is null
             and policy.label_key(s.compartments) = any (v_keys)) then
    return 'already_settled';
  end if;
  if exists (select 1 from ledger.belief_settlements s where s.finding_id = v_finding.id and s.lifted_at is not null
             and policy.label_key(s.compartments) = any (v_keys) and s.holds_key = case when p_holds = 'a' then v_finding.a_key else v_finding.b_key end) then
    return 'owner_lifted';
  end if;
  insert into ledger.belief_settlements (id, request_id, finding_id, a_key, b_key, holds_key, client_id, client_name, opportunity_id, move_id,
    cited_kinds, cited_ids, created_at, compartments)
  values (p_id, p_request, v_finding.id, v_finding.a_key, v_finding.b_key, case when p_holds = 'a' then v_finding.a_key else v_finding.b_key end,
    v_client.id, v_client.name, p_opportunity, p_move, p_cited_kinds, p_cited_ids, now(), v_finding.compartments);
  return 'settled';
end
$_$;

CREATE FUNCTION ledger.settle_send(send_id text, ruling_id text, answer text, request_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  s ledger.sent_messages%rowtype;
  v_state text;
  v_open boolean;
  v_copy boolean;
begin
  if session_user <> 'pi_proxy' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if settle_send.answer is null or settle_send.answer not in ('sent', 'not_sent')
     or coalesce(settle_send.ruling_id, '') !~ '^rul_[0-9A-HJKMNP-TV-Z]{26}$' or coalesce(settle_send.request_id, '') !~ '^[A-Za-z0-9_-]{8,64}$' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform ledger.lock_send(settle_send.send_id);
  if exists (select 1 from knowledge.owner_decisions o where o.request_id = settle_send.request_id and o.kind = 'send_settle'
             and o.target_kind = 'send' and o.target_id = settle_send.send_id) then
    return 'settled';
  end if;
  select x.* into s from ledger.sent_messages x where x.id = settle_send.send_id;
  if s.id is null then
    return 'not_settleable';
  end if;
  v_state := (select r.event from ledger.record_events r where r.row_kind = 'send' and r.row_id = s.id order by r.id desc limit 1);
  v_open := v_state = 'unknown' or (v_state = 'sending' and s.begun_at < now() - interval '2 minutes');
  v_copy := exists (select 1 from vault.evidence_items e where e.sent_id = s.id);
  if v_open and settle_send.answer = 'not_sent' then
    if v_copy then
      return 'not_settleable';
    end if;
    if not exists (select 1 from vault.source_accounts a where a.id = s.source_account_id and a.last_outcome = 'ok' and a.last_sync_at > s.begun_at) then
      return 'sync_pending';
    end if;
  elsif not v_open and not (v_state = 'sent' and settle_send.answer = 'sent' and not v_copy
                            and not exists (select 1 from knowledge.owner_decisions o where o.kind = 'send_settle' and o.target_kind = 'send' and o.target_id = s.id)) then
    return 'not_settleable';
  end if;

  insert into knowledge.owner_decisions (id, request_id, kind, target_kind, target_id, answer, card_id, batch, queue_depth, labels, details,
    decided_at, compartments)
  values (settle_send.ruling_id, settle_send.request_id, 'send_settle', 'send', s.id, settle_send.answer, null, false,
    (select count(*) from ledger.cards c
     where (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) = 'pending'),
    '{}'::text[], '{}'::jsonb, now(), s.compartments);
  if v_open and settle_send.answer = 'sent' then
    perform ledger.record_sent(s.id);
  elsif v_open then
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
    values ('send', s.id, 'failed', now(), 'owner', s.compartments);
  end if;
  return 'settled';
end
$_$;

CREATE FUNCTION ledger.signal_marks_evidence_gone() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  delete from ledger.signal_marks m where m.evidence_ids @> array[old.id];
  return null;
end
$$;

CREATE FUNCTION ledger.signal_marks_item_tainted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  update ledger.signal_marks m set tainted_at = now(), note_enc = null where m.ref_id = new.id and m.tainted_at is null;
  return null;
end
$$;

CREATE FUNCTION ledger.signal_marks_source_gone() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  delete from ledger.signal_marks m where m.ref_id = old.id;
  return null;
end
$$;

CREATE FUNCTION ledger.signal_roles() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce((select s.signal_roles from policy.work_settings s where exists (select 1 from policy.current_client() c)), '{}'::jsonb)
$$;

CREATE FUNCTION ledger.spend_on(day date) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce((select sum(s.cost_microusd) from ledger.run_steps s
    where s.kind = 'model_call'
      and s.created_at >= (spend_on.day::timestamp at time zone 'UTC')
      and s.created_at < ((spend_on.day + 1)::timestamp at time zone 'UTC')), 0)::bigint
  + coalesce((select sum(a.cost_microusd) from ledger.agent_spend a
    where a.created_at >= (spend_on.day::timestamp at time zone 'UTC')
      and a.created_at < ((spend_on.day + 1)::timestamp at time zone 'UTC')), 0)::bigint
$$;

CREATE FUNCTION ledger.split_wrong_merge(p_report text, p_request text) RETURNS TABLE(code text, rulings text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_r ledger.wrong_merge_reports;
  v_o ledger.wrong_merge_reports;
  v_keys text[];
  v_now text[];
  v_owner boolean;
  v_lift text[];
  v_pairs integer;
  v_pair record;
  v_id text;
  v_n integer := 0;
  v_made text[] := '{}';
  v_fa text[] := '{}';
  v_fb text[] := '{}';
  v_na integer[] := '{}';
  v_nb integer[] := '{}';
  v_refused text;
begin
  perform ledger.lock_rows(array['identity:rulings', 'author:system:identity', 'identity:wrong_merges']);
  select r.* into v_r from ledger.wrong_merge_reports r where r.id = p_report;
  if not found or p_request is null or p_request !~ '^[A-Za-z0-9_-]{8,60}$' then
    return query select 'not_found'::text, null::text[];
    return;
  end if;
  if v_r.state = 'split' then
    return query select 'split'::text, v_r.ruling_ids;
    return;
  end if;
  if v_r.state <> 'open' then
    return query select 'closed'::text, null::text[];
    return;
  end if;
  if coalesce((select s.identity_agents from policy.work_settings s), 'off') <> 'on' then
    return query select 'agents_off'::text, null::text[];
    return;
  end if;
  select o.* into v_o from ledger.wrong_merge_reports o
  where o.partition_key = v_r.partition_key and o.state = 'open' and o.client_id <> v_r.client_id and o.session_id <> v_r.session_id
    and o.compartments = v_r.compartments
  order by o.created_at, o.id collate "C" limit 1;
  if not found then
    return query select 'one_agent'::text, null::text[];
    return;
  end if;

  v_keys := ledger.keys_of(v_r.compartments);
  v_now := array(select m.one from unnest(ledger.same_person_side(v_r.entity_id, v_keys)) as m (one) order by m.one collate "C");
  select count(*), coalesce(bool_or(x.by_owner), false) into v_pairs, v_owner from (
    select bool_or(d.kind <> 'identity_policy'
                   or exists (select 1 from knowledge.owner_decisions o
                              where o.kind = 'identity' and o.answer = 'same' and o.details -> 'affirms' ? r.ruling_id)) as by_owner
    from knowledge.identity_rulings r
    join knowledge.owner_decisions d on d.id = r.ruling_id
    join knowledge.accounts xa on xa.value_fp = r.a_fp and policy.label_key(xa.compartments) = any (v_keys)
    join knowledge.accounts xb on xb.value_fp = r.b_fp and policy.label_key(xb.compartments) = any (v_keys)
    join unnest(v_r.parts) with ordinality as pa (ents, n) on xa.entity_id = any (string_to_array(pa.ents, ','))
    join unnest(v_r.parts) with ordinality as pb (ents, n) on xb.entity_id = any (string_to_array(pb.ents, ','))
    where r.verdict = 'same' and r.lifted_at is null and pa.n <> pb.n
    group by least(pa.n, pb.n), greatest(pa.n, pb.n)
  ) x;
  v_refused := case when v_now is distinct from v_r.members or v_pairs = 0 then 'changed' when v_owner then 'owner_ruled' end;
  if v_refused is null then
    v_lift := ledger.label(array(
      select c.one
      from knowledge.identity_rulings r
      join knowledge.owner_decisions d on d.id = r.ruling_id
      join knowledge.accounts xa on xa.value_fp = r.a_fp and policy.label_key(xa.compartments) = any (v_keys)
      join knowledge.accounts xb on xb.value_fp = r.b_fp and policy.label_key(xb.compartments) = any (v_keys)
      join unnest(v_r.parts) with ordinality as pa (ents, n) on xa.entity_id = any (string_to_array(pa.ents, ','))
      join unnest(v_r.parts) with ordinality as pb (ents, n) on xb.entity_id = any (string_to_array(pb.ents, ','))
      cross join lateral unnest(d.compartments) as c (one)
      where r.verdict = 'same' and r.lifted_at is null and pa.n <> pb.n));

    begin
      for v_pair in
        select least(pa.n, pb.n) as na, greatest(pa.n, pb.n) as nb, array_agg(distinct r.ruling_id) as ids
        from knowledge.identity_rulings r
        join knowledge.accounts xa on xa.value_fp = r.a_fp and policy.label_key(xa.compartments) = any (v_keys)
        join knowledge.accounts xb on xb.value_fp = r.b_fp and policy.label_key(xb.compartments) = any (v_keys)
        join unnest(v_r.parts) with ordinality as pa (ents, n) on xa.entity_id = any (string_to_array(pa.ents, ','))
        join unnest(v_r.parts) with ordinality as pb (ents, n) on xb.entity_id = any (string_to_array(pb.ents, ','))
        where r.verdict = 'same' and r.lifted_at is null and pa.n <> pb.n
        group by least(pa.n, pb.n), greatest(pa.n, pb.n)
        order by 1, 2
      loop
        v_n := v_n + 1;
        v_id := ledger.new_id('rul');
        insert into knowledge.owner_decisions (id, request_id, kind, answer, batch, queue_depth, details, decided_at, compartments)
        values (v_id, p_request || '_' || v_n, 'identity_policy', 'different', false,
                (select count(*) from ledger.cards c where (select e.event from ledger.record_events e where e.row_kind = 'card' and e.row_id = c.id order by e.id desc limit 1) = 'pending'),
                jsonb_build_object('basis', 'agent', 'client', v_r.client_name, 'agrees', v_o.client_name, 'because', v_r.because,
                                   'report', v_r.id, 'lifts', to_jsonb(v_pair.ids)),
                now(), v_lift);
        update knowledge.identity_rulings r set lifted_at = now(), lift_ruling_id = v_id
        where r.ruling_id = any (v_pair.ids) and r.lifted_at is null;
        v_made := v_made || v_id;
        v_fa := v_fa || (select min(a.value_fp collate "C") from knowledge.accounts a where a.entity_id = any (string_to_array(v_r.parts[v_pair.na::integer], ',')));
        v_fb := v_fb || (select min(a.value_fp collate "C") from knowledge.accounts a where a.entity_id = any (string_to_array(v_r.parts[v_pair.nb::integer], ',')));
        v_na := v_na || v_pair.na::integer;
        v_nb := v_nb || v_pair.nb::integer;
      end loop;
      for i in 1 .. cardinality(v_made) loop
        if exists (
          with recursive g (fp) as (
            select a.value_fp from knowledge.accounts a where a.entity_id = any (string_to_array(v_r.parts[v_na[i]], ','))
            union
            select case when r.a_fp = g.fp then r.b_fp else r.a_fp end
            from knowledge.identity_rulings r join g on r.a_fp = g.fp or r.b_fp = g.fp
            where r.verdict = 'same' and r.lifted_at is null and r.b_fp is not null
          ) select 1 from g join knowledge.accounts b on b.value_fp = g.fp
            where b.entity_id = any (string_to_array(v_r.parts[v_nb[i]], ','))) then
          raise exception 'still joined' using errcode = 'PIW07';
        end if;
        insert into knowledge.identity_rulings (ruling_id, verdict, a_fp, b_fp, created_at, by_agent)
        values (v_made[i], 'different', least(v_fa[i] collate "C", v_fb[i] collate "C"), greatest(v_fa[i] collate "C", v_fb[i] collate "C"), now(), true);
      end loop;
    exception when sqlstate 'PIW07' then
      v_refused := 'owner_ruled';
      v_made := '{}';
    when unique_violation then
      v_refused := 'conflict';
      v_made := '{}';
    end;
  end if;

  if v_refused is not null then
    update ledger.wrong_merge_reports w set state = 'refused', code = v_refused, settled_at = now()
    where w.partition_key = v_r.partition_key and w.state = 'open' and w.compartments = v_r.compartments;
    return query select v_refused, null::text[];
    return;
  end if;
  update ledger.wrong_merge_reports w set state = 'split', ruling_ids = v_made, settled_at = now()
  where w.partition_key = v_r.partition_key and w.state = 'open' and w.compartments = v_r.compartments;
  return query select 'split'::text, v_made;
end
$_$;

CREATE FUNCTION ledger.stale_restatements() RETURNS TABLE(client_id text, fact_key_fp text, count bigint, first_at timestamp with time zone, last_at timestamp with time zone, case_key text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
begin
  return query
    with marks as (
      select r.client_id as client, r.matched_fact_key_fp as fact, r.checked_at as at
      from ledger.restatement_checks r join ledger.agent_writes w on w.id = r.record_id
      where r.answer = 'stale' and r.cleared_at is null and w.body_enc is not null
      union all
      select m.client_id, p.fact, m.created_at
      from ledger.memory_imports m
      join ledger.agent_writes w on w.id = m.record_id
      cross join lateral (select distinct q.fact_key_fp as fact from ledger.memory_projections q where q.id = any (m.matched_projection_ids)) p
      where m.mark = 'stale' and w.body_enc is not null
    ),
    keyed as (
      select k.client, k.fact, k.at, k.client || ':' || left(k.fact, 33) as case_key from marks k
    ),
    decided as (
      select c.case_key, max(e.at) as at
      from ledger.cards c
      join ledger.record_events e on e.row_kind = 'card' and e.row_id = c.id and e.event = 'decided'
      where c.kind = 'stale_restatement' and c.created_by = 'system:memory' and c.case_key is not null
      group by c.case_key
    )
    select k.client, k.fact, count(*), min(k.at), max(k.at), k.case_key
    from keyed k left join decided d on d.case_key = k.case_key
    where d.at is null or k.at > d.at
    group by k.client, k.fact, k.case_key
    order by k.client collate "C", k.fact collate "C";
end
$$;

CREATE FUNCTION ledger.start_outcome_test(id text, request_id text, session_id text, suite text, expected_tasks integer, answer_model text, judge_model text) RETURNS TABLE(run_id text, go boolean, code text, at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_day date := (now() at time zone 'UTC')::date;
  v_ceiling bigint;
  v_at timestamptz;
  v_id text;
  v_keys text[];
begin
  select c.client_id, c.clearance into v_caller, v_clearance from ledger.agent_mail_caller('start_outcome_test', start_outcome_test.session_id) c;
  v_keys := policy.clearance_keys();
  if start_outcome_test.answer_model is null or start_outcome_test.judge_model is null
     or start_outcome_test.answer_model = start_outcome_test.judge_model then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform ledger.lock_rows(array['outcome test ' || v_caller]);
  select r.id, r.created_at into v_id, v_at from ledger.outcome_test_runs r
    where r.client_id = v_caller and r.request_id = start_outcome_test.request_id and policy.label_key(r.compartments) = any (v_keys);
  if v_id is not null then
    return query select v_id, true, null::text, v_at;
    return;
  end if;
  if coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on' then
    return query select null::text, false, 'killed'::text, null::timestamptz;
    return;
  end if;
  select s.max_microusd_per_day into v_ceiling from policy.work_settings s;
  if ledger.spend_on(v_day) >= v_ceiling / 2 then
    return query select null::text, false, 'budget'::text, null::timestamptz;
    return;
  end if;
  if (select count(*) from ledger.outcome_test_runs r where r.client_id = v_caller and r.created_at > now() - interval '6 days' and policy.label_key(r.compartments) = any (v_keys)
        and exists (select 1 from ledger.outcome_test_tasks t where t.run_id = r.id and t.score is not null and policy.label_key(t.compartments) = any (v_keys))) >= 2
     or exists (select 1 from ledger.outcome_test_runs r where r.client_id = v_caller and r.created_at > now() - interval '6 days' and policy.label_key(r.compartments) = any (v_keys)
                  and (select count(*) from ledger.outcome_test_tasks t where t.run_id = r.id and policy.label_key(t.compartments) = any (v_keys)) >= r.expected_tasks) then
    return query select null::text, false, 'not_due'::text, null::timestamptz;
    return;
  end if;
  insert into ledger.outcome_test_runs (id, request_id, client_id, session_id, compartments, suite, expected_tasks, answer_model, judge_model)
  values (start_outcome_test.id, start_outcome_test.request_id, v_caller, start_outcome_test.session_id, ledger.label(v_clearance),
          start_outcome_test.suite, start_outcome_test.expected_tasks, start_outcome_test.answer_model, start_outcome_test.judge_model)
  returning created_at into v_at;
  return query select start_outcome_test.id, true, null::text, v_at;
end
$$;

CREATE FUNCTION ledger.state_wakes(at timestamp with time zone) RETURNS TABLE(wake_source text, wake_key text, compartments text[], vetoed boolean, anchors text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with clearance as materialized (
    select c.compartments, policy.label_key(c.compartments) as key, ledger.keys_of(c.compartments) as keys
    from policy.clients c where c.kind = 'reasoner' and c.status = 'active'
  ),
  rows as (
    select case t.raise when 'due' then 'commitment_due' else 'belief_changed' end as wake_source,
      case t.raise when 'due' then 'commitment:' || t.fact_key_fp else 'belief:' || t.fact_key_fp || ':' || t.state_fp end as wake_key,
      t.fact_key_fp, t.compartments, t.anchors, t.written_at as created_at, t.id
    from ledger.trigger_log t
    cross join clearance k
    cross join policy.work_settings s
    where policy.label_key(t.compartments) = any (k.keys) and t.clearance_key = k.key and t.raise in ('changed', 'due')
      and t.written_at <= state_wakes.at
      and t.written_at > state_wakes.at - make_interval(hours => s.calendar_lead_hours)
  ),
  live as (
    select distinct on (o.wake_key) o.*
    from rows o
    where not exists (select 1 from ledger.runs r where r.wake_key = o.wake_key or o.wake_key = any (r.covered_keys))
      and not exists (select 1 from ledger.silences x where x.wake_key = o.wake_key and x.reason = 'vetoed')
    order by o.wake_key, o.id
  ),
  refs as (
    select l.id, array_agg(r.kind order by r.kind, r.ref_id) as kinds, array_agg(r.ref_id order by r.kind, r.ref_id) as ids
    from live l
    cross join clearance k
    left join lateral (
      select 'entity' as kind, ce.entity_id as ref_id
      from knowledge.claims c join knowledge.claim_entities ce on ce.claim_id = c.id
      where policy.label_key(c.compartments) = any (k.keys) and c.fact_key_fp = l.fact_key_fp and c.compartments <@ l.compartments
      union
      select 'message', m.id
      from knowledge.claims c join knowledge.messages m on m.evidence_id = c.evidence_id
      where policy.label_key(c.compartments) = any (k.keys) and c.fact_key_fp = l.fact_key_fp and c.compartments <@ l.compartments
    ) r on true
    group by l.id
  ),
  anchored as (
    select l.id, coalesce(array_agg(distinct e.id order by e.id) filter (where e.id is not null), '{}'::text[]) as anchors
    from live l
    cross join clearance k
    left join lateral (
      select e.id from knowledge.entities e
      where l.wake_source = 'belief_changed' and e.id = any (l.anchors) and e.kind <> 'owner'
        and (exists (select 1 from knowledge.accounts a where a.entity_id = e.id and a.compartments <@ k.compartments)
             or exists (select 1 from knowledge.domains d where d.entity_id = e.id and d.compartments <@ k.compartments))
    ) e on true
    group by l.id
  )
  select l.wake_source, l.wake_key, l.compartments, policy.vetoed(r.kinds, r.ids, null), a.anchors
  from live l join refs r on r.id = l.id join anchored a on a.id = l.id
  order by l.created_at, l.id
$$;

CREATE FUNCTION ledger.stop_card_by_rule(p_card text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_card ledger.cards;
  v_rule text;
begin
  select c.* into v_card from ledger.cards c where c.id = p_card;
  if not found then
    return null;
  end if;
  v_rule := ledger.card_rule_stop(v_card.kind, v_card.target_kind, v_card.target_id, v_card.compartments);
  if v_rule is null then
    return null;
  end if;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
  values ('card', p_card, 'withdrawn', now(), v_card.created_by, v_card.compartments, 'rule_stopped');
  return v_rule;
end
$$;

CREATE FUNCTION ledger.submit_improvement(id text, event_id text, request_id text, session_id text, kind text, area text, severity text, title_fp text, title_enc jsonb, detail_enc jsonb, evidence_enc jsonb, event_note_enc jsonb, event_evidence_enc jsonb) RETURNS TABLE(improvement_id text, merged boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
  v_author text;
  v_open text;
begin
  select c.client_id, c.clearance into v_caller, v_clearance from ledger.agent_mail_caller('submit_improvement', submit_improvement.session_id) c;
  if submit_improvement.kind is null or submit_improvement.kind not in ('bug', 'improvement')
     or submit_improvement.area is null or submit_improvement.area not in ('mcp', 'extraction', 'knowledge', 'work', 'planner', 'sources', 'deploy', 'docs', 'other')
     or submit_improvement.severity is null or submit_improvement.severity not in ('low', 'medium', 'high', 'critical')
     or submit_improvement.title_fp is null or submit_improvement.title_fp !~ '^[0-9a-f]{64}$'
     or submit_improvement.title_enc is null or submit_improvement.detail_enc is null or submit_improvement.event_note_enc is null
     or (submit_improvement.evidence_enc is null) <> (submit_improvement.event_evidence_enc is null) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  v_keys := policy.clearance_keys();
  perform ledger.lock_rows(array['improvement ' || submit_improvement.title_fp]);
  return query select i.id, false from ledger.improvements i where i.created_by = v_author and i.request_id = submit_improvement.request_id;
  if found then
    return;
  end if;
  return query select e.improvement_id, true from ledger.improvement_events e
    where e.created_by = v_author and e.event = 'reported' and e.request_id = submit_improvement.request_id;
  if found then
    return;
  end if;

  select i.id into v_open from ledger.improvements i
  where i.title_fp = submit_improvement.title_fp and i.tainted_at is null
    and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys)
    and (select s.status from ledger.improvement_status(i.id, v_clearance, v_keys) s) in ('open', 'triaged', 'in_progress')
  order by i.created_at, i.id collate "C" limit 1;
  if v_open is not null then
    insert into ledger.improvement_events (id, improvement_id, request_id, created_by, client_id, session_id, compartments, event, note_enc, evidence_enc)
    values (submit_improvement.event_id, v_open, submit_improvement.request_id, v_author, v_caller, submit_improvement.session_id, ledger.label(v_clearance),
            'reported', submit_improvement.event_note_enc, submit_improvement.event_evidence_enc);
    update ledger.improvements i set severity = submit_improvement.severity
    where i.id = v_open and ledger.label(i.compartments) = ledger.label(v_clearance)
      and array_position(array['low', 'medium', 'high', 'critical'], submit_improvement.severity)
          > array_position(array['low', 'medium', 'high', 'critical'], i.severity);
    return query select v_open, true;
    return;
  end if;

  insert into ledger.improvements (id, request_id, created_by, client_id, session_id, compartments, kind, area, severity, title_fp, title_enc, detail_enc, evidence_enc)
  values (submit_improvement.id, submit_improvement.request_id, v_author, v_caller, submit_improvement.session_id, ledger.label(v_clearance),
          submit_improvement.kind, submit_improvement.area, submit_improvement.severity, submit_improvement.title_fp,
          submit_improvement.title_enc, submit_improvement.detail_enc, submit_improvement.evidence_enc);
  return query select submit_improvement.id, false;
end
$_$;

CREATE FUNCTION ledger.taint_citing(evidence_ids text[], ref_kinds text[], ref_ids text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  marked_kinds text[];
  marked_ids text[];
  t_hypotheses text[];
  t_opportunities text[];
  t_intentions text[];
  t_tests text[];
  t_runs text[];
  t_moves text[];
  t_drafts text[];
  t_research text[];
  t_goals text[];
  t_questions text[];
  work_rows integer;
  tainted_cards text[];
  decisions integer;
  authors text[];
  author text;
  memory_rows integer;
  t_links text[];
  learning_rows integer;
  more_rows integer;
  mirror_rows integer;
  t_links_more integer;
  mail_rows integer;
begin
  perform pg_advisory_xact_lock(hashtext('intelligence personal ledger taint'));

  with gone as (
    select r.kind, r.id from unnest(taint_citing.ref_kinds, taint_citing.ref_ids) as r (kind, id)
  ),
  marked as (
    update ledger.basis b set tainted_at = now(), evidence_id = null
    where b.tainted_at is null
      and (b.evidence_id = any (taint_citing.evidence_ids) or (b.ref_kind, b.ref_id) in (select g.kind, g.id from gone g))
    returning b.row_kind, b.row_id
  )
  select coalesce(array_agg(m.row_kind), '{}'::text[]), coalesce(array_agg(m.row_id), '{}'::text[]) into marked_kinds, marked_ids from marked m;

  with hit as (
    update ledger.hypotheses h set tainted_at = now(), body_enc = null
    where h.tainted_at is null
      and (exists (select 1 from unnest(marked_kinds, marked_ids) as m (kind, id) where m.kind = 'hypothesis' and m.id = h.id)
           or (h.about_kind, h.about_id) in (select r.kind, r.id from unnest(taint_citing.ref_kinds, taint_citing.ref_ids) as r (kind, id))
           or (h.session_id is not null and exists (select 1 from ledger.read_log l where l.session_id = h.session_id
                 and l.bound && taint_citing.evidence_ids and l.read_at <= h.created_at)))
    returning h.id
  )
  select coalesce(array_agg(x.id), '{}'::text[]) into t_hypotheses from hit x;

  with hit as (
    update ledger.opportunities o set tainted_at = now(), body_enc = null
    where o.tainted_at is null
      and (exists (select 1 from unnest(marked_kinds, marked_ids) as m (kind, id) where m.kind = 'opportunity' and m.id = o.id)
           or (o.about_kind, o.about_id) in (select r.kind, r.id from unnest(taint_citing.ref_kinds, taint_citing.ref_ids) as r (kind, id))
           or o.hypothesis_id = any (t_hypotheses)
           or (o.session_id is not null and exists (select 1 from ledger.read_log l where l.session_id = o.session_id
                 and l.bound && taint_citing.evidence_ids and l.read_at <= o.created_at)))
    returning o.id
  )
  select coalesce(array_agg(x.id), '{}'::text[]) into t_opportunities from hit x;

  with hit as (
    update ledger.intentions i set tainted_at = now(), body_enc = null
    where i.tainted_at is null
      and (exists (select 1 from unnest(marked_kinds, marked_ids) as m (kind, id) where m.kind = 'intention' and m.id = i.id)
           or (i.session_id is not null and i.body_enc is not null and exists (select 1 from ledger.read_log l where l.session_id = i.session_id
                 and l.bound && taint_citing.evidence_ids and l.read_at <= i.created_at)))
    returning i.id
  )
  select coalesce(array_agg(x.id), '{}'::text[]) into t_intentions from hit x;

  with hit as (
    update ledger.hypothesis_tests t set tainted_at = now()
    where t.tainted_at is null
      and exists (select 1 from unnest(marked_kinds, marked_ids) as m (kind, id) where m.kind = 'test' and m.id = t.id)
    returning t.id
  )
  select coalesce(array_agg(x.id), '{}'::text[]) into t_tests from hit x;

  with hit as (
    update ledger.runs r set tainted_at = now()
    where r.tainted_at is null
      and exists (select 1 from unnest(marked_kinds, marked_ids) as m (kind, id) where m.kind = 'run' and m.id = r.id)
    returning r.id
  )
  select coalesce(array_agg(x.id), '{}'::text[]) into t_runs from hit x;

  with hit as (
    update ledger.moves v set tainted_at = now()
    where v.tainted_at is null
      and (exists (select 1 from unnest(marked_kinds, marked_ids) as m (kind, id) where m.kind = 'move' and m.id = v.id)
           or v.opportunity_id = any (t_opportunities))
    returning v.id
  )
  select coalesce(array_agg(x.id), '{}'::text[]) into t_moves from hit x;

  with hit as (
    update ledger.drafts d set tainted_at = now(), body_enc = null
    where d.tainted_at is null
      and (exists (select 1 from unnest(marked_kinds, marked_ids) as m (kind, id) where m.kind = 'draft' and m.id = d.id)
           or d.reply_to_evidence_id = any (taint_citing.evidence_ids)
           or (d.session_id is not null and exists (select 1 from ledger.read_log l where l.session_id = d.session_id
                 and l.bound && taint_citing.evidence_ids and l.read_at <= d.created_at)))
    returning d.id
  )
  select coalesce(array_agg(x.id), '{}'::text[]) into t_drafts from hit x;
  update ledger.drafts d set reply_to_evidence_id = null where d.reply_to_evidence_id = any (taint_citing.evidence_ids);

  with hit as (
    update ledger.research_requests q set tainted_at = now(), body_enc = null
    where q.tainted_at is null
      and (('entity', q.about_entity_id) in (select r.kind, r.id from unnest(taint_citing.ref_kinds, taint_citing.ref_ids) as r (kind, id))
           or ('message', q.message_id) in (select r.kind, r.id from unnest(taint_citing.ref_kinds, taint_citing.ref_ids) as r (kind, id))
           or (q.session_id is not null and exists (select 1 from ledger.read_log l where l.session_id = q.session_id
                 and l.bound && taint_citing.evidence_ids and l.read_at <= q.created_at)))
    returning q.id
  )
  select coalesce(array_agg(x.id), '{}'::text[]) into t_research from hit x;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'research_request', q.id, 'tainted', now(), 'system:taint', q.compartments from ledger.research_requests q
  where q.id = any (t_research) and ledger.research_state(q.id) in ('filed', 'approved', 'running', 'waiting');

  with hit as (
    update ledger.goal_proposals g set tainted_at = now(), statement_enc = null, body_enc = null, details_enc = null
    where g.tainted_at is null
      and (exists (select 1 from unnest(marked_kinds, marked_ids) as m (kind, id) where m.kind = 'goal_proposal' and m.id = g.id)
           or ('goal', g.goal_id) in (select r.kind, r.id from unnest(taint_citing.ref_kinds, taint_citing.ref_ids) as r (kind, id))
           or (g.session_id is not null and exists (select 1 from ledger.read_log l where l.session_id = g.session_id
                 and l.bound && taint_citing.evidence_ids and l.read_at <= g.created_at)))
    returning g.id
  )
  select coalesce(array_agg(x.id), '{}'::text[]) into t_goals from hit x;
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'goal_proposal', g.id, 'withdrawn', now(), 'system:taint', g.compartments from ledger.goal_proposals g
  where g.id = any (t_goals)
    and (select r.event from ledger.record_events r where r.row_kind = 'goal_proposal' and r.row_id = g.id order by r.id desc limit 1) = 'proposed';

  update ledger.record_events e set tainted_at = now(), body_enc = null
  where e.tainted_at is null and e.body_enc is not null and e.row_kind <> 'card'
    and ((e.row_kind = 'move' and e.row_id = any (t_moves))
         or (e.session_id is not null and exists (select 1 from ledger.read_log l where l.session_id = e.session_id
               and l.bound && taint_citing.evidence_ids and l.read_at <= e.at)));

  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'hypothesis', h.id, 'withdrawn', now(), 'system:taint', h.compartments from ledger.hypotheses h
  where h.id = any (t_hypotheses)
    and (select r.event from ledger.record_events r where r.row_kind = 'hypothesis' and r.row_id = h.id order by r.id desc limit 1) in ('open', 'supported', 'asked');
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'opportunity', o.id, 'withdrawn', now(), 'system:taint', o.compartments from ledger.opportunities o
  where o.id = any (t_opportunities)
    and (select r.event from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = o.id order by r.id desc limit 1)
        in ('proposed', 'later', 'go', 'claimed', 'handed_to_owner');
  delete from queue.leases l where l.resource_kind = 'opportunity' and l.resource_id = any (t_opportunities);
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'intention', i.id, 'cancelled', now(), 'system:taint', i.compartments from ledger.intentions i
  where (i.id = any (t_intentions) or i.opportunity_id = any (t_opportunities))
    and (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id order by r.id desc limit 1) = 'set';
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, code)
  select 'run', r.id, 'stopped', now(), 'system:taint', r.compartments, 'withdrawn' from ledger.runs r
  where r.id = any (t_runs)
    and (select e.event from ledger.record_events e where e.row_kind = 'run' and e.row_id = r.id order by e.id desc limit 1) in ('queued', 'running');
  delete from queue.leases l where l.resource_kind = 'run' and l.resource_id = any (t_runs);
  work_rows := cardinality(t_hypotheses) + cardinality(t_opportunities) + cardinality(t_intentions) + cardinality(t_tests)
    + cardinality(t_runs) + cardinality(t_moves) + cardinality(t_drafts) + cardinality(t_research) + cardinality(t_goals);

  update ledger.agent_messages m set tainted_at = now(), subject_enc = null, body_enc = null
  where m.tainted_at is null
    and exists (select 1 from ledger.read_log l where l.session_id = m.session_id and l.bound && taint_citing.evidence_ids and l.read_at <= m.created_at);
  get diagnostics mail_rows = row_count;
  update ledger.improvements i set tainted_at = now(), title_enc = null, detail_enc = null, evidence_enc = null
  where i.tainted_at is null
    and exists (select 1 from ledger.read_log l where l.session_id = i.session_id and l.bound && taint_citing.evidence_ids and l.read_at <= i.created_at);
  get diagnostics more_rows = row_count;
  mail_rows := mail_rows + more_rows;
  update ledger.improvement_events e set tainted_at = now(), note_enc = null, evidence_enc = null
  where e.tainted_at is null
    and exists (select 1 from ledger.read_log l where l.session_id = e.session_id and l.bound && taint_citing.evidence_ids and l.read_at <= e.created_at);
  get diagnostics more_rows = row_count;
  mail_rows := mail_rows + more_rows;
  update ledger.agent_learnings x set tainted_at = now(), statement_enc = null, rule_enc = null, evidence_enc = null
  where x.tainted_at is null
    and exists (select 1 from ledger.read_log l where l.session_id = x.session_id and l.bound && taint_citing.evidence_ids and l.read_at <= x.created_at);
  get diagnostics more_rows = row_count;
  mail_rows := mail_rows + more_rows;

  with tainted as (
    update ledger.held_out_questions q set tainted_at = now(), question_enc = null, key_enc = null
    where q.tainted_at is null
      and exists (select 1 from ledger.read_log l where l.session_id = q.session_id and l.bound && taint_citing.evidence_ids and l.read_at <= q.created_at)
    returning q.id
  )
  select coalesce(array_agg(id), '{}') into t_questions from tainted;
  mail_rows := mail_rows + cardinality(t_questions);
  update ledger.outcome_test_tasks t set tainted_at = now(), answer_enc = null, scoring_enc = null
  where t.tainted_at is null
    and (t.task = any (t_questions)
         or exists (select 1 from ledger.read_log l where l.session_id = t.session_id and l.bound && taint_citing.evidence_ids and l.read_at <= t.created_at));
  get diagnostics more_rows = row_count;
  mail_rows := mail_rows + more_rows;

  with tainted as (
    update ledger.cards c set tainted_at = now(), body_enc = null
    where c.tainted_at is null
      and (exists (select 1 from unnest(marked_kinds, marked_ids) as m (kind, id) where m.kind = 'card' and m.id = c.id)
           or (c.target_kind, c.target_id) in (select r.kind, r.id from unnest(taint_citing.ref_kinds, taint_citing.ref_ids) as r (kind, id))
           or (c.target_kind = 'hypothesis' and c.target_id = any (t_hypotheses))
           or (c.target_kind = 'opportunity' and c.target_id = any (t_opportunities))
           or (c.target_kind = 'intention' and c.target_id = any (t_intentions))
           or (c.target_kind = 'run' and c.target_id = any (t_runs))
           or (c.target_kind = 'move' and c.target_id = any (t_moves))
           or (c.target_kind = 'draft' and c.target_id = any (t_drafts))
           or (c.target_kind = 'research_request' and c.target_id = any (t_research))
           or (c.target_kind = 'goal_proposal' and c.target_id = any (t_goals)))
    returning c.id
  )
  select coalesce(array_agg(t.id), '{}'::text[]) into tainted_cards from tainted t;

  update knowledge.owner_decisions o set tainted_at = now(), body_enc = null
  where o.tainted_at is null
    and (o.target_kind, o.target_id) in (select r.kind, r.id from unnest(taint_citing.ref_kinds, taint_citing.ref_ids) as r (kind, id));
  get diagnostics decisions = row_count;

  update ledger.record_events e set tainted_at = now(), body_enc = null
  where e.row_kind = 'card' and e.row_id = any (tainted_cards) and e.tainted_at is null;

  with states as (
    select c.id, c.created_by, c.compartments,
      (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) as state
    from ledger.cards c
    where c.id = any (tainted_cards) or (c.target_kind = 'card' and c.target_id = any (tainted_cards))
  ),
  withdrawn as (
    insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
    select 'card', s.id, 'withdrawn', now(), 'system:taint', s.compartments from states s where s.state in ('pending', 'deferred')
    returning row_id
  )
  select coalesce(array_agg(distinct s.created_by), '{}'::text[]) into authors
  from states s where s.state = 'pending' and s.id in (select w.row_id from withdrawn w);

  foreach author in array authors loop
    perform ledger.admit_deferred(author);
  end loop;

  with tainted as (
    update ledger.memory_projections p
    set tainted_at = now(), belief_id = null, evidence_ids = '{}'::text[],
        ended_at = coalesce(p.ended_at, now()), reason = coalesce(p.reason, 'withdrawn')
    where p.tainted_at is null and p.evidence_ids && taint_citing.evidence_ids
    returning p.id, p.client_id, p.first_served_at, p.compartments
  )
  insert into ledger.memory_exposures (client_id, projection_id, first_served_at, recorded_at, retention, removal, compartments)
  select t.client_id, t.id, t.first_served_at, now(), c.vendor_retention, 'pending', t.compartments
  from tainted t join policy.clients c on c.id = t.client_id;
  get diagnostics memory_rows = row_count;

  update ledger.mirror_entries x
  set tainted_at = now(), last_tainted_at = now(), evidence_ids = '{}'::text[],
      ended_at = coalesce(x.ended_at, now()), reason = coalesce(x.reason, 'withdrawn')
  where x.tainted_at is null and x.evidence_ids && taint_citing.evidence_ids;
  get diagnostics mirror_rows = row_count;

  with hit as (
    update ledger.move_result_links l set tainted_at = now(), evidence_id = null
    where l.tainted_at is null
      and (l.evidence_id = any (taint_citing.evidence_ids)
           or (l.ref_kind, l.ref_id) in (select r.kind, r.id from unnest(taint_citing.ref_kinds, taint_citing.ref_ids) as r (kind, id)))
    returning l.id
  )
  select coalesce(array_agg(h.id), '{}'::text[]) into t_links from hit h;
  with hit as (
    update ledger.move_result_links l set tainted_at = now()
    where l.tainted_at is null
      and exists (select 1 from ledger.sent_messages s join ledger.drafts d on d.id = s.draft_id
                  where s.id = l.send_id and (s.tainted_at is not null or d.tainted_at is not null))
    returning l.id
  )
  select t_links || coalesce(array_agg(h.id), '{}'::text[]) into t_links from hit h;

  update ledger.outcome_links o set tainted_at = now(), evidence_id = null
  where o.tainted_at is null and o.move_result_link_id is null and o.evidence_id = any (taint_citing.evidence_ids);
  get diagnostics more_rows = row_count;
  t_links_more := more_rows;

  update ledger.outcome_assessments a set tainted_at = now()
  where a.tainted_at is null
    and (a.link_ids && t_links
         or (a.subject_kind = 'opportunity' and exists (select 1 from ledger.opportunities o where o.id = a.subject_id and o.tainted_at is not null))
         or (a.subject_kind = 'send' and exists (select 1 from ledger.sent_messages s join ledger.drafts d on d.id = s.draft_id
                                                 where s.id = a.subject_id and (s.tainted_at is not null or d.tainted_at is not null))));
  get diagnostics learning_rows = row_count;

  update ledger.silence_samples x set tainted_at = now()
  where x.tainted_at is null and exists (select 1 from ledger.silences s where s.id = x.silence_id and s.tainted_at is not null);
  get diagnostics more_rows = row_count;
  learning_rows := learning_rows + more_rows;

  update ledger.forecasts f set tainted_at = now()
  where f.tainted_at is null and exists (select 1 from ledger.opportunities o where o.id = f.opportunity_id and o.tainted_at is not null);
  get diagnostics more_rows = row_count;
  learning_rows := learning_rows + more_rows + cardinality(t_links) + t_links_more;

  return cardinality(tainted_cards) + decisions + work_rows + memory_rows + learning_rows + mirror_rows + mail_rows;
end
$$;

CREATE FUNCTION ledger.taint_copied_outcome_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  update ledger.outcome_links o set tainted_at = coalesce(n.tainted_at, now()), evidence_id = null
  from new_rows n
  where o.move_result_link_id = n.id and n.tainted_at is not null and o.tainted_at is null;
  return null;
end
$$;

CREATE FUNCTION ledger.taint_goal_targets(entity_ids text[], evidence_ids text[], dry_run boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  tainted integer;
begin
  if taint_goal_targets.dry_run then
    select count(*)::integer into tainted from knowledge.owner_decisions o
    where o.kind = 'goal_target'
      and (o.details ->> 'entity' = any (taint_goal_targets.entity_ids)
        or o.details -> 'named' ->> 'item' = any (taint_goal_targets.evidence_ids));
    return tainted;
  end if;
  update knowledge.owner_decisions o
  set tainted_at = coalesce(o.tainted_at, now()), body_enc = null, details = (o.details - 'named') || '{"entity": null}'::jsonb
  where o.kind = 'goal_target'
    and (o.details ->> 'entity' = any (taint_goal_targets.entity_ids)
      or o.details -> 'named' ->> 'item' = any (taint_goal_targets.evidence_ids));
  get diagnostics tainted = row_count;
  return tainted;
end
$$;

CREATE FUNCTION ledger.taint_mirror_entities(entity_ids text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_rows integer;
begin
  if taint_mirror_entities.entity_ids is null or array_position(taint_mirror_entities.entity_ids, null) is not null then
    raise exception 'taint_mirror_entities_entity_ids' using errcode = '23514', constraint = 'taint_mirror_entities_entity_ids';
  end if;
  perform pg_advisory_xact_lock(hashtext('intelligence personal ledger taint'));
  update ledger.mirror_entries m
  set tainted_at = now(), last_tainted_at = now(), evidence_ids = '{}'::text[],
      ended_at = coalesce(m.ended_at, now()), reason = coalesce(m.reason, 'withdrawn')
  where m.tainted_at is null and m.entity_ids && taint_mirror_entities.entity_ids;
  get diagnostics v_rows = row_count;
  return v_rows;
end
$$;

CREATE FUNCTION ledger.taint_subject_decisions(address_fps text[], fact_fps text[], removed_claim_ids text[], dry_run boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  gone text[];
  hit text[];
  tainted integer;
begin
  perform pg_advisory_xact_lock(hashtext('intelligence personal ledger taint'));
  gone := array(select distinct u.fp from unnest(taint_subject_decisions.fact_fps) as u (fp)
                where not exists (select 1 from knowledge.claims c
                                  where (c.fact_key_fp = u.fp or c.legacy_fact_key_fp = u.fp or c.legacy_alt_fact_key_fp = u.fp)
                                    and not c.closes
                                    and not (c.id = any (taint_subject_decisions.removed_claim_ids))));
  hit := taint_subject_decisions.address_fps || gone;
  if taint_subject_decisions.dry_run then
    select count(*)::integer into tainted from knowledge.owner_decisions o
    where o.tainted_at is null and cardinality(o.subject_fps) > 0 and o.subject_fps && hit;
    return tainted;
  end if;
  update knowledge.owner_decisions o set tainted_at = now(), body_enc = null, subject_fps = '{}',
    details = case when o.kind in ('open_item_close', 'open_item_reopen') then o.details - 'key' - 'match' - 'due'
                   when o.kind in ('commitment_close', 'commitment_reopen') then o.details - 'factKey'
                   else o.details end
  where o.tainted_at is null and cardinality(o.subject_fps) > 0 and o.subject_fps && hit;
  get diagnostics tainted = row_count;
  perform ledger.forget_commitment_keys(gone);
  return tainted;
end
$$;

CREATE FUNCTION ledger.task_kind(kind text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select kind in ('meeting_prep', 'investigate', 'goal_step', 'life_admin', 'research')
$$;

CREATE FUNCTION ledger.task_standing(p_since timestamp with time zone, p_within text[]) RETURNS TABLE(trigger text, scored integer, used integer, kept integer, dropped integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_within text[] := case when session_user = 'pi_reader' then policy.client_clearance() else p_within end;
begin
  return query
    select v.trigger,
      count(*) filter (where v.scored)::integer,
      count(*) filter (where v.used)::integer,
      count(*) filter (where v.judged = 'keep')::integer,
      count(*) filter (where v.dropped)::integer
    from ledger.task_value(task_standing.p_since, now(), v_within) v
    group by 1;
end
$$;

CREATE FUNCTION ledger.task_value(p_since timestamp with time zone, p_until timestamp with time zone, p_within text[]) RETURNS TABLE(opportunity_id text, move_id text, trigger text, kind text, compartments text[], done_at timestamp with time zone, cited boolean, acted boolean, confirmed boolean, rejected boolean, judged text, reason text, used boolean, dropped boolean, scored boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with finished as (
    select o.id, o.kind, o.gap_trigger, o.about_kind, o.about_id, o.compartments, e.at as done_at,
      m.id as move_id, m.created_by as mover, m.created_at as moved_at
    from ledger.record_events e
    join ledger.opportunities o on o.id = e.row_id
    join lateral (select v.id, v.created_by, v.created_at from ledger.moves v
                  where v.opportunity_id = o.id and v.tainted_at is null order by v.created_at desc, v.id desc limit 1) m on true
    where e.row_kind = 'opportunity' and e.event = 'done' and e.at >= p_since and e.at <= p_until
      and e.id = (select max(r.id) from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = e.row_id)
      and o.tier = 'task' and o.tainted_at is null
      and o.compartments <@ p_within and not policy.is_restricted(o.compartments)
  ), signals as (
    select f.*,
      array(select w.id from ledger.agent_writes w
            where 'client:' || w.client_id = f.mover and w.refused_code is null and w.tainted_at is null
              and w.created_at >= f.moved_at and w.created_at <= f.done_at
              and w.compartments <@ p_within) as records,
      array(select w.evidence_id from ledger.agent_writes w
            where 'client:' || w.client_id = f.mover and w.refused_code is null and w.tainted_at is null and w.evidence_id is not null
              and w.created_at >= f.moved_at and w.created_at <= f.done_at
              and w.compartments <@ p_within) as evidence
    from finished f
  ), facts as (
    select s.*,
      (exists (select 1 from ledger.basis b
               where b.ref_kind = 'agent_record' and b.ref_id = any (s.records) and b.tainted_at is null
                 and b.compartments <@ p_within
                 and not exists (select 1 from ledger.hypotheses h where b.row_kind = 'hypothesis' and h.id = b.row_id and h.created_by = s.mover)
                 and not exists (select 1 from ledger.opportunities o where b.row_kind = 'opportunity' and o.id = b.row_id and o.created_by = s.mover)
                 and not exists (select 1 from ledger.moves v where b.row_kind = 'move' and v.id = b.row_id and v.created_by = s.mover))
       or exists (select 1 from ledger.read_log l
                  where 'client:' || l.client_id <> s.mover and l.read_at > s.done_at and l.read_at <= s.done_at + interval '7 days'
                    and l.compartments <@ p_within
                    and ((l.tool in ('read_record', 'find_records') and l.shown && s.records) or l.bound && s.evidence)
                    and not exists (select 1 from policy.clients k where k.id = l.client_id and 'start_outcome_test' = any (k.tools)))) as cited,
      (case s.about_kind
         when 'entity' then
           exists (select 1 from knowledge.interaction_log i
                   where i.entity_id = s.about_id and i.direction = 'outbound' and i.compartments <@ p_within
                     and i.occurred_at > s.done_at and i.occurred_at <= s.done_at + interval '7 days')
           or exists (select 1 from knowledge.chat_lines c
                      where c.entity_id = s.about_id and c.direction = 'outbound' and c.compartments <@ p_within
                        and c.occurred_at > s.done_at and c.occurred_at <= s.done_at + interval '7 days')
         when 'message' then
           exists (select 1 from knowledge.messages a join knowledge.messages m on m.thread_fp = a.thread_fp
                   where a.id = s.about_id and m.direction = 'outbound' and m.compartments <@ p_within
                     and m.sent_at > s.done_at and m.sent_at <= s.done_at + interval '7 days')
         else false end
       or exists (select 1 from knowledge.owner_decisions d
                  where d.target_id = s.about_id and d.kind <> 'result_eval' and d.tainted_at is null and d.compartments <@ p_within
                    and not exists (select 1 from ledger.card_relays y where y.ruling_id = d.id)
                    and d.decided_at > s.done_at and d.decided_at <= s.done_at + interval '7 days')
       or exists (select 1 from ledger.signal_marks g
                  where g.state = 'handled' and g.tainted_at is null and g.compartments <@ p_within and g.created_by <> s.mover
                    and (g.ref_id = s.id or g.ref_id = s.about_id)
                    and g.created_at >= s.done_at and g.created_at <= s.done_at + interval '7 days')) as acted,
      exists (select 1 from knowledge.claims k join ledger.cards c on c.target_id = k.id
              join knowledge.owner_decisions d on d.card_id = c.id
              where k.evidence_id = any (s.evidence) and d.kind = 'answer' and d.answer = 'confirm'
                and not exists (select 1 from ledger.card_relays y where y.ruling_id = d.id)
                and d.tainted_at is null and d.compartments <@ p_within) as confirmed,
      exists (select 1 from knowledge.claims k join ledger.cards c on c.target_id = k.id
              join knowledge.owner_decisions d on d.card_id = c.id
              where k.evidence_id = any (s.evidence) and d.kind = 'answer' and d.answer = 'reject'
                and d.tainted_at is null and d.compartments <@ p_within) as rejected,
      j.answer as judged, j.reason
    from signals s
    left join lateral (
      select d.answer, d.details ->> 'reason' as reason from knowledge.owner_decisions d
      join ledger.moves v on v.id = d.target_id
      where d.kind = 'result_eval' and d.target_kind = 'move' and v.opportunity_id = s.id and d.tainted_at is null and d.compartments <@ p_within
      order by d.decided_at desc, d.id collate "C" desc limit 1) j on j.answer in ('keep', 'not_useful')
  )
  select f.id, f.move_id, coalesce(f.gap_trigger, f.kind), f.kind, f.compartments, f.done_at,
    f.cited, f.acted, f.confirmed, f.rejected, f.judged, f.reason,
    f.judged is not distinct from 'keep' or (f.judged is null and (f.cited or f.acted or f.confirmed)),
    f.judged is not distinct from 'not_useful',
    f.judged is not null or f.cited or f.acted or f.confirmed or f.done_at <= p_until - interval '7 days'
  from facts f
$$;

CREATE FUNCTION ledger.time_vetoed(p_project_id text, p_from timestamp with time zone, p_to timestamp with time zone, p_clearance text[], p_keys text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select exists (
    select 1 from knowledge.time_rulings t
    where t.source = 'system' and (t.project_id = p_project_id or t.project_id is null) and t.lift_ruling_id is not null
      and t.to_at > p_from and t.from_at < p_to
      and t.compartments <@ p_clearance and policy.label_key(t.compartments) = any (p_keys))
$$;

CREATE FUNCTION ledger.tried_holds(p_caller text, p_tools text[], p_sources text[], p_label text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select
    not exists (select 1 from unnest(p_tools) t (name)
                where not exists (select 1 from policy.calls k
                                  where k.client_id = p_caller and k.tool = t.name and k.outcome = 'ok' and k.at > now() - interval '24 hours'))
    and not exists (select 1 from unnest(p_sources) s (id)
                    where not exists (select 1 from ledger.read_log r
                                      where r.client_id = p_caller and r.read_at > now() - interval '24 hours'
                                        and r.bound @> array[s.id])
                       or not exists (select 1 from ledger.read_log r
                                      where r.client_id = p_caller and r.read_at > now() - interval '24 hours'
                                        and r.tool = any (p_tools) and r.shown @> array[s.id]))
    and not exists (select 1 from unnest(p_sources) s (id)
                    where not exists (select 1 from vault.evidence_items e where e.id = s.id and e.compartments <@ p_label)
                      and not exists (select 1 from ledger.agent_writes w
                                      where w.id = s.id and w.tainted_at is null and w.compartments <@ p_label
                                        and policy.label_key(w.compartments) = any (policy.clearance_keys())))
$$;

CREATE FUNCTION ledger.trigger_cause(fallback text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case when session_user::text in ('pi_pipeline', 'pi_admin', 'pi_restricted', 'pi_writer') and current_setting('pi.trigger_cause', true) in ('backfill', 'erasure')
              then current_setting('pi.trigger_cause', true) else trigger_cause.fallback end
$$;

CREATE FUNCTION ledger.update_improvement(event_id text, improvement_id text, request_id text, session_id text, status text, duplicate_of text, note_enc jsonb, fix_ref text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
  v_author text;
  v_done text;
  v_filed_by text;
  v_label text[];
  v_cause text;
  v_opened timestamptz;
begin
  select c.client_id, c.clearance into v_caller, v_clearance from ledger.agent_mail_caller('update_improvement', update_improvement.session_id) c;
  if update_improvement.status is null or update_improvement.status not in ('open', 'triaged', 'in_progress', 'done', 'wont_do', 'duplicate')
     or (update_improvement.status = 'duplicate') <> (update_improvement.duplicate_of is not null)
     or update_improvement.duplicate_of = update_improvement.improvement_id
     or (update_improvement.fix_ref is not null and update_improvement.fix_ref !~
           '^(pr:[1-9][0-9]{0,6}|commit:[0-9a-f]{7,40}|lever:[a-z][a-z0-9_]{0,31}(\.[a-z][a-z0-9_]{0,31}){1,2}|ops:[a-z][a-z0-9_]{0,31}|none:(not_reproducible|owners_to_change|duplicate))$') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  v_keys := policy.clearance_keys();
  perform ledger.lock_rows(array['improvement event ' || v_author || ' ' || update_improvement.request_id]);
  select e.status into v_done from ledger.improvement_events e
  where e.created_by = v_author and e.event = 'status' and e.request_id = update_improvement.request_id;
  if v_done is not null then
    return v_done;
  end if;
  select i.created_by, ledger.label(i.compartments), i.cause,
    coalesce((select max(e.created_at) from ledger.improvement_events e
              where e.improvement_id = i.id and e.event = 'status' and e.status = 'open' and e.created_by = 'system:measure'
                and e.tainted_at is null and e.compartments <@ v_clearance and policy.label_key(e.compartments) = any (v_keys)), i.created_at)
    into v_filed_by, v_label, v_cause, v_opened from ledger.improvements i
  where i.id = update_improvement.improvement_id and i.tainted_at is null
    and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys);
  if v_filed_by is null
     or (update_improvement.duplicate_of is not null
         and not exists (select 1 from ledger.improvements i where i.id = update_improvement.duplicate_of and i.tainted_at is null
                         and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys)
                         and i.compartments <@ v_label)) then
    return null;
  end if;
  if (update_improvement.fix_ref like 'lever:%'
      and not exists (select 1 from policy.setting_changes c
                      where c.key = substr(update_improvement.fix_ref, 7) and c.changed_by = v_author
                        and c.id = (select max(m.id) from policy.setting_changes m where m.key = c.key)
                        and c.at >= v_opened
                        and (v_cause = 'measure_floor:' || c.measure or v_cause = 'lever_change:' || c.key)))
     or update_improvement.fix_ref like 'ops:%'
     or (update_improvement.fix_ref like 'none:%' and update_improvement.status <> 'triaged') then
    return 'fix_ref_refused';
  end if;
  if v_filed_by = 'system:measure' then
    if update_improvement.status in ('done', 'wont_do', 'duplicate') then
      return 'closes_by_measure';
    end if;
    if update_improvement.status = 'in_progress' and update_improvement.fix_ref is null then
      return 'needs_fix_ref';
    end if;
  end if;
  if update_improvement.duplicate_of is not null
     and (select s.status from ledger.improvement_status(update_improvement.duplicate_of, v_clearance, v_keys) s) = 'duplicate' then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  insert into ledger.improvement_events (id, improvement_id, request_id, created_by, client_id, session_id, compartments, event, status, duplicate_of, note_enc, fix_ref)
  values (update_improvement.event_id, update_improvement.improvement_id, update_improvement.request_id, v_author, v_caller, update_improvement.session_id,
          v_label, 'status', update_improvement.status, update_improvement.duplicate_of,
          update_improvement.note_enc, update_improvement.fix_ref);
  return update_improvement.status;
end
$_$;

CREATE FUNCTION ledger.update_project(p_project_id text, p_session_id text, p_name_enc jsonb, p_set_role boolean, p_owner_role text, p_set_goal boolean, p_goal_id text, p_set_due boolean, p_due_at timestamp with time zone, p_touch boolean, p_set_area boolean, p_area_id text) RETURNS TABLE(found boolean, refused text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_author text;
  v_project record;
  v_refused text[] := '{}';
  v_changed boolean := false;
  v_area_label text[];
  v_event_label text[];
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('update_project' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = p_session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  if (p_name_enc is not null and jsonb_typeof(p_name_enc) <> 'object')
     or (coalesce(p_set_role, false) and p_owner_role is not null and p_owner_role !~ '^[a-z][a-z0-9-]{1,31}$') then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_author := 'client:' || v_caller;
  if not exists (select 1 from knowledge.projects p
                 where p.id = p_project_id and p.compartments <@ v_clearance and policy.label_key(p.compartments) = any (v_keys)) then
    return;
  end if;
  if coalesce(p_set_goal, false) and p_goal_id is not null
     and not exists (select 1 from projections.goal_state g
                     where g.goal_id = p_goal_id and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys)) then
    return;
  end if;
  if coalesce(p_set_role, false) and p_owner_role is not null
     and not exists (select 1 from policy.clients k where k.status = 'active' and k.kind = 'agent' and (p_owner_role = any (k.roles) or p_owner_role = k.name)) then
    raise exception 'unknown role' using errcode = 'PIW04';
  end if;
  if coalesce(p_set_area, false) and p_area_id is not null then
    select a.compartments into v_area_label from knowledge.areas a
    where a.id = p_area_id and a.state = 'active'
      and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys);
    if v_area_label is null then
      raise exception 'invalid request' using errcode = '22023';
    end if;
  end if;
  perform ledger.lock_rows(array[p_project_id]);
  select p.id, p.status, p.created_by, p.compartments, p.owner_role, p.goal_id, p.due_at, p.area_id into v_project
  from knowledge.projects p
  where p.id = p_project_id and p.compartments <@ v_clearance and policy.label_key(p.compartments) = any (v_keys);

  if v_project.status <> 'active' then
    v_refused := array(select x.field || ':not_active' from (values
      ('name', p_name_enc is not null), ('ownerRole', coalesce(p_set_role, false)), ('goal', coalesce(p_set_goal, false)),
      ('dueAt', coalesce(p_set_due, false)), ('area', coalesce(p_set_area, false)), ('status', coalesce(p_touch, false))) as x (field, asked) where x.asked);
    return query select true, v_refused;
    return;
  end if;

  if p_name_enc is not null then
    if v_project.created_by = 'owner'
       or (select r.by from ledger.record_events r where r.row_kind = 'project' and r.row_id = p_project_id and r.event = 'updated' and r.code = 'name'
           and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) is not distinct from 'owner' then
      v_refused := v_refused || 'name:owner_set'::text;
    else
      update knowledge.projects set name_enc = p_name_enc where id = p_project_id;
      insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, code)
      values ('project', p_project_id, 'updated', clock_timestamp(), v_author, v_project.compartments, p_session_id, 'name');
      v_changed := true;
    end if;
  end if;
  if coalesce(p_set_role, false) and v_project.owner_role is distinct from p_owner_role then
    if (select r.by from ledger.record_events r where r.row_kind = 'project' and r.row_id = p_project_id and r.event = 'updated' and r.code = 'owner_role'
        and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) is not distinct from 'owner' then
      v_refused := v_refused || 'ownerRole:owner_set'::text;
    else
      update knowledge.projects set owner_role = p_owner_role where id = p_project_id;
      insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, code)
      values ('project', p_project_id, 'updated', clock_timestamp(), v_author, v_project.compartments, p_session_id, 'owner_role');
      v_changed := true;
    end if;
  end if;
  if coalesce(p_set_goal, false) and v_project.goal_id is distinct from p_goal_id then
    if (select r.by from ledger.record_events r where r.row_kind = 'project' and r.row_id = p_project_id and r.event = 'updated' and r.code = 'goal'
        and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) is not distinct from 'owner' then
      v_refused := v_refused || 'goal:owner_set'::text;
    else
      update knowledge.projects set goal_id = p_goal_id where id = p_project_id;
      insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, code)
      values ('project', p_project_id, 'updated', clock_timestamp(), v_author, v_project.compartments, p_session_id, 'goal');
      v_changed := true;
    end if;
  end if;
  if coalesce(p_set_due, false) and v_project.due_at is distinct from p_due_at then
    if (select r.by from ledger.record_events r where r.row_kind = 'project' and r.row_id = p_project_id and r.event = 'updated' and r.code = 'due_at'
        and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) is not distinct from 'owner' then
      v_refused := v_refused || 'dueAt:owner_set'::text;
    else
      update knowledge.projects set due_at = p_due_at where id = p_project_id;
      insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, code)
      values ('project', p_project_id, 'updated', clock_timestamp(), v_author, v_project.compartments, p_session_id, 'due_at');
      v_changed := true;
    end if;
  end if;
  if coalesce(p_set_area, false) and v_project.area_id is distinct from p_area_id
     and (v_project.area_id is null
          or exists (select 1 from knowledge.areas a where a.id = v_project.area_id
                     and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys))) then
    if (select r.by from ledger.record_events r where r.row_kind = 'project' and r.row_id = p_project_id and r.event = 'updated' and r.code = 'area'
        and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) is not distinct from 'owner' then
      v_refused := v_refused || 'area:owner_set'::text;
    else
      v_event_label := ledger.label(v_project.compartments || coalesce(v_area_label,
        (select a.compartments from knowledge.areas a where a.id = v_project.area_id)));
      update knowledge.projects set area_id = p_area_id where id = p_project_id;
      insert into ledger.record_events (row_kind, row_id, event, at, by, compartments, session_id, code)
      values ('project', p_project_id, 'updated', clock_timestamp(), v_author, v_event_label, p_session_id, 'area');
      if v_event_label = ledger.label(v_project.compartments) then
        v_changed := true;
      end if;
    end if;
  end if;
  if v_changed or (coalesce(p_touch, false) and ledger.label(v_clearance) <@ v_project.compartments) then
    update knowledge.projects set updated_at = now() where id = p_project_id;
  end if;
  return query select true, v_refused;
end
$_$;

CREATE FUNCTION ledger.use_only_candidates(draft_id text) RETURNS TABLE(claim_id text, compartments text[], content_enc jsonb, cited_item boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_reader boolean := session_user = 'pi_reader';
  v_caller text;
  v_clearance text[];
  v_keys text[];
  d ledger.drafts%rowtype;
begin
  if v_reader then
    select c.id, c.compartments into v_caller, v_clearance from policy.current_client() c;
    v_keys := policy.clearance_keys();
  end if;
  select dr.* into d from ledger.drafts dr where dr.id = use_only_candidates.draft_id;
  if v_reader and (v_caller is null or d.id is null or d.created_by <> 'client:' || v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if d.id is null then
    return;
  end if;
  if v_reader then
    return query
      with cited as (
        select be.source_account_id, be.source_item_fp
        from ledger.basis b join vault.evidence_items be on be.id = b.evidence_id
        where b.row_kind = 'draft' and b.row_id = d.id
      )
      select c.id, c.compartments, c.content_enc,
        exists (select 1 from cited x where x.source_account_id = ce.source_account_id and x.source_item_fp = ce.source_item_fp)
      from knowledge.claims c
      join vault.evidence_items ce on ce.id = c.evidence_id
      where c.compartments <@ v_clearance and policy.label_key(c.compartments) = any (v_keys)
        and ce.source_kind <> 'crm'
        and exists (
          select 1 from unnest(d.recipient_fps) as r (fp)
          where not exists (
            with thread as (
              select ce.id as evidence_id
              union
              select e.id from vault.evidence_items e
              where ce.thread_fp is not null and exists (select 1 from knowledge.messages m where m.evidence_id = ce.id and policy.label_key(m.compartments) = any (v_keys))
                and e.source_account_id = ce.source_account_id and e.thread_fp = ce.thread_fp and e.observed_at >= ce.observed_at
            )
            select 1 from thread t
            where exists (select 1 from knowledge.messages m where m.evidence_id = t.evidence_id and m.sender_fp = r.fp and policy.label_key(m.compartments) = any (v_keys))
               or exists (select 1 from vault.sent_recipients s where s.evidence_id = t.evidence_id and s.address_fp = r.fp)
               or exists (select 1 from knowledge.interaction_log i join knowledge.accounts a on a.entity_id = i.entity_id
                          where i.evidence_id = t.evidence_id and policy.label_key(i.compartments) = any (v_keys) and a.value_fp = r.fp and a.compartments <@ c.compartments and policy.label_key(a.compartments) = any (v_keys))))
      order by c.id collate "C";
  else
    return query
      with cited as (
        select be.source_account_id, be.source_item_fp
        from ledger.basis b join vault.evidence_items be on be.id = b.evidence_id
        where b.row_kind = 'draft' and b.row_id = d.id
      )
      select c.id, c.compartments, c.content_enc,
        exists (select 1 from cited x where x.source_account_id = ce.source_account_id and x.source_item_fp = ce.source_item_fp)
      from knowledge.claims c
      join vault.evidence_items ce on ce.id = c.evidence_id
      where ce.source_kind <> 'crm' and exists (
          select 1 from unnest(d.recipient_fps) as r (fp)
          where not exists (
            with thread as (
              select ce.id as evidence_id
              union
              select e.id from vault.evidence_items e
              where ce.thread_fp is not null and exists (select 1 from knowledge.messages m where m.evidence_id = ce.id)
                and e.source_account_id = ce.source_account_id and e.thread_fp = ce.thread_fp and e.observed_at >= ce.observed_at
            )
            select 1 from thread t
            where exists (select 1 from knowledge.messages m where m.evidence_id = t.evidence_id and m.sender_fp = r.fp)
               or exists (select 1 from vault.sent_recipients s where s.evidence_id = t.evidence_id and s.address_fp = r.fp)
               or exists (select 1 from knowledge.interaction_log i join knowledge.accounts a on a.entity_id = i.entity_id
                          where i.evidence_id = t.evidence_id and a.value_fp = r.fp and a.compartments <@ c.compartments)))
      order by c.id collate "C";
  end if;
end
$$;

CREATE FUNCTION ledger.withdraw_empty_batch() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_n integer;
begin
  insert into ledger.record_events (row_kind, row_id, event, at, by, compartments)
  select 'card', c.id, 'withdrawn', now(), 'system:identity', c.compartments
  from ledger.cards c
  where c.kind = 'same_person_batch' and c.created_by = 'system:identity'
    and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) in ('pending', 'deferred')
    and not exists (select 1 from ledger.identity_questions q where q.card_id = c.id and q.state = 'owner');
  get diagnostics v_n = row_count;
  return v_n;
end
$$;

CREATE FUNCTION ledger.work_grants() RETURNS TABLE(intent_id text, opportunity_kind text, stage text, harness_mode_id text, for_tasks boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_views text[];
  v_tools text[];
begin
  select c.id, c.views, c.tools into v_caller, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('list_opportunities' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on' then
    return;
  end if;
  return query
    select i.id, k.kind, h.stage, h.id, i.for_tasks
    from policy.intents i
    cross join lateral unnest(i.opportunity_kinds) as k (kind)
    join policy.harness_modes h on h.client_id = v_caller and h.opportunity_kind = k.kind and h.revoked_at is null
    where i.confirmed_at is not null and i.revoked_at is null
      and (v_caller = any (i.client_ids) or i.for_tasks or (i.role is not null and exists (select 1 from policy.clients k where k.id = v_caller and i.role = any (k.roles))))
    order by i.confirmed_at, i.id collate "C", k.kind collate "C", h.stage collate "C", h.id collate "C";
end
$$;

CREATE FUNCTION ledger.work_held(opportunity_id text, at_time timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select exists (
    select 1 from queue.leases l
    where l.resource_kind = 'opportunity' and l.resource_id = work_held.opportunity_id
      and (l.lease_until >= work_held.at_time
           or (exists (select 1 from policy.clients h where h.id = l.holder and h.status = 'active')
               and (l.lease_until + interval '24 hours' > work_held.at_time or l.preferred_until > work_held.at_time
                    or ledger.check_back_holds(l.resource_id, l.holder)))))
$$;

CREATE FUNCTION ledger.work_progress(opportunity_ids text[]) RETURNS TABLE(opportunity_id text, move_id text, at timestamp with time zone, by_name text, compartments text[], body_enc jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_keys text[];
begin
  select c.id, c.compartments, c.views into v_caller, v_clearance, v_views from policy.current_client() c;
  if v_caller is null then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if not ('work' = any (v_views)) then
    return;
  end if;
  v_keys := policy.clearance_keys();
  return query
    select distinct on (o.id) o.id, m.id, r.at, k.name, r.compartments, r.body_enc
    from ledger.opportunities o
    join ledger.moves m on m.opportunity_id = o.id and m.tainted_at is null
      and m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys)
    join ledger.record_events r on r.row_kind = 'move' and r.row_id = m.id and r.event = 'reported' and r.code = 'progress'
      and r.tainted_at is null and r.body_enc is not null
      and r.compartments <@ v_clearance and policy.label_key(r.compartments) = any (v_keys)
    join policy.clients k on 'client:' || k.id = r.by
    where o.id = any (work_progress.opportunity_ids) and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)
      and o.tainted_at is null
    order by o.id, r.id desc;
end
$$;

CREATE FUNCTION ledger.work_stopped() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_views text[];
  v_tools text[];
begin
  select c.id, c.views, c.tools into v_caller, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('claim_opportunity' = any (v_tools)) or not ('work' = any (v_views))
     or policy.current_client_kind() is distinct from 'agent' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  return coalesce((select k.state from ledger.kill_switch k order by k.id desc limit 1), 'off') = 'on';
end
$$;

CREATE FUNCTION ledger.work_time_title_caller(p_session_id text) RETURNS TABLE(clearance text[], keys text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_clearance text[];
  v_roles text[];
begin
  select c.clearance, c.roles into v_clearance, v_roles from ledger.agent_mail_caller('get_work_time', p_session_id) c;
  if not exists (select 1 from policy.work_settings s where s.title_role = any (v_roles)) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  return query select v_clearance, policy.clearance_keys();
end
$$;

CREATE FUNCTION ledger.work_time_title_suppressed(p_session_id text, p_fps text[]) RETURNS SETOF text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  perform 1 from ledger.work_time_title_caller(p_session_id);
  return query select distinct s.value_fp from knowledge.suppressions s where s.value_fp = any (p_fps);
end
$$;

CREATE FUNCTION ledger.work_time_titles(p_session_id text, p_evidence_ids text[], p_meeting_ids text[]) RETURNS TABLE(kind text, id text, ref text, compartments text[], sealed jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_clearance text[];
  v_keys text[];
begin
  select c.clearance into v_clearance from ledger.work_time_title_caller(p_session_id) c;
  v_keys := policy.clearance_keys();
  if coalesce(cardinality(p_evidence_ids), 0) > 10000 or coalesce(cardinality(p_meeting_ids), 0) > 10000 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  return query
    select 'block'::text, k.evidence_id, b.blob_ref, b.compartments, b.envelope
    from knowledge.captures k
    join vault.evidence_items e on e.id = k.evidence_id
    join vault.evidence_blobs b on b.blob_ref = e.blob_ref
    where k.kind = 'block' and k.evidence_id = any (p_evidence_ids)
      and k.compartments <@ v_clearance and policy.label_key(k.compartments) = any (v_keys)
      and e.compartments <@ v_clearance and b.compartments <@ v_clearance
    union all
    select 'meeting'::text, k.id, k.id, k.compartments, k.facts_enc
    from knowledge.captures k
    where k.kind = 'meeting' and k.id = any (p_meeting_ids)
      and k.compartments <@ v_clearance and policy.label_key(k.compartments) = any (v_keys);
end
$$;

CREATE FUNCTION ledger.work_trail(opportunity_ids text[], most integer) RETURNS TABLE(opportunity_id text, kind text, place integer, ref_id text, at timestamp with time zone, by_name text, due_at timestamp with time zone, code text, role text, compartments text[], body_enc jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_keys text[];
begin
  select c.id, c.compartments, c.views into v_caller, v_clearance, v_views from policy.current_client() c;
  if v_caller is null then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if work_trail.most is null or work_trail.most < 1 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  if not ('work' = any (v_views)) then
    return;
  end if;
  v_keys := policy.clearance_keys();
  return query
    select p.opportunity_id, 'progress'::text, p.place, p.move_id, p.at, p.name, null::timestamptz, null::text, null::text, p.compartments, p.body_enc
    from (
      select o.id as opportunity_id, m.id as move_id, r.at, k.name, r.compartments, r.body_enc,
             (row_number() over (partition by o.id order by r.id desc))::integer as place
      from ledger.opportunities o
      join ledger.moves m on m.opportunity_id = o.id and m.tainted_at is null
        and m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys)
      join ledger.record_events r on r.row_kind = 'move' and r.row_id = m.id and r.event = 'reported' and r.code = 'progress'
        and r.tainted_at is null and r.body_enc is not null
        and r.compartments <@ v_clearance and policy.label_key(r.compartments) = any (v_keys)
      join policy.clients k on 'client:' || k.id = r.by
      where o.id = any (work_trail.opportunity_ids) and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)
        and o.tainted_at is null
    ) p
    where p.place <= work_trail.most
    union all
    select c.opportunity_id, 'check_back'::text, 1, c.intention_id, c.created_at, c.name, c.due_at, c.state, null::text, c.compartments, c.body_enc
    from (
      select distinct on (o.id) o.id as opportunity_id, i.id as intention_id, i.created_at, k.name, i.due_at, i.compartments, i.body_enc,
             (select r.event from ledger.record_events r where r.row_kind = 'intention' and r.row_id = i.id
                and policy.label_key(r.compartments) = any (v_keys) order by r.id desc limit 1) as state
      from ledger.opportunities o
      join ledger.intentions i on i.opportunity_id = o.id and i.kind = 'check_back' and i.tainted_at is null
        and i.compartments <@ v_clearance and policy.label_key(i.compartments) = any (v_keys)
      join policy.clients k on k.id = i.client_id
      where o.id = any (work_trail.opportunity_ids) and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)
        and o.tainted_at is null
      order by o.id, i.created_at desc, i.id desc
    ) c
    union all
    select h.opportunity_id, 'hand_off'::text, 1, null::text, h.at, h.name, null::timestamptz, h.code, h.role, h.compartments, null::jsonb
    from (
      select distinct on (o.id) o.id as opportunity_id, r.at, k.name, r.code,
             case when r.event = 'handed_to_owner' then 'owner' else r.role end as role, r.compartments
      from ledger.opportunities o
      join ledger.record_events r on r.row_kind = 'opportunity' and r.row_id = o.id and r.event in ('routed', 'handed_to_owner')
        and r.tainted_at is null
        and r.compartments <@ v_clearance and policy.label_key(r.compartments) = any (v_keys)
      join policy.clients k on 'client:' || k.id = r.by
      where o.id = any (work_trail.opportunity_ids) and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)
        and o.tainted_at is null
      order by o.id, r.id desc
    ) h;
end
$$;

CREATE FUNCTION ledger.work_watches_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_needed text[];
  v_event text;
  v_at timestamptz;
begin
  select o.compartments into v_needed from ledger.opportunities o where o.id = new.opportunity_id;
  v_needed := coalesce(v_needed, '{}'::text[])
    || coalesce((select s.compartments from ledger.sent_messages s where s.id = new.send_id), '{}'::text[])
    || coalesce((select e.compartments from vault.evidence_items e where e.id = new.evidence_id), '{}'::text[]);
  if cardinality(new.compartments) > 0 and not (new.compartments @> v_needed) then
    raise exception 'a watch label must cover its work and its source' using errcode = '23514';
  end if;
  if new.until is null then
    select r.event, r.at into v_event, v_at from ledger.record_events r
    where r.row_kind = 'opportunity' and r.row_id = new.opportunity_id order by r.id desc limit 1;
    if ledger.closes_work(v_event) then
      new.until := v_at + interval '90 days';
    end if;
  end if;
  return new;
end
$$;

CREATE FUNCTION ledger.write_back(p_id text, p_request_id text, p_session_id text, p_ref_kind text, p_ref_id text, p_state text, p_note_enc jsonb, p_evidence_ids text[], p_tools text[], p_sources text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  v_caller text;
  v_clearance text[];
  v_views text[];
  v_tools text[];
  v_keys text[];
  v_author text;
  v_found text;
  v_label text[];
  v_asks boolean := p_state = 'needs_owner';
begin
  select c.id, c.compartments, c.views, c.tools into v_caller, v_clearance, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('write_back' = any (v_tools)) or policy.current_client_kind() is distinct from 'agent'
     or not exists (select 1 from ledger.sessions s where s.id = p_session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if p_state is null or p_state not in ('handled', 'drafted', 'needs_owner') or p_ref_id is null
     or (p_tools is null) <> (p_sources is null)
     or (p_tools is not null and (
       cardinality(p_tools) not between 1 and 5 or array_position(p_tools, null) is not null
       or cardinality(p_sources) not between 1 and 10 or array_position(p_sources, null) is not null
       or exists (select 1 from unnest(p_tools) t (name)
                  where t.name not in ('search', 'find_messages', 'find_facts', 'find_documents', 'find_records', 'find_paths', 'get_timeline', 'build_context_pack', 'context')))) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  v_author := 'client:' || v_caller;
  select m.id into v_found from ledger.signal_marks m where m.created_by = v_author and m.request_id = p_request_id;
  if v_found is not null then
    return v_found;
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = p_session_id and b.one ~ '^[0-9a-f]{64}$'
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return null;
  end if;
  if not (case p_ref_kind
      when 'message' then exists (select 1 from knowledge.messages m where m.id = p_ref_id and m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys) and not m.held)
      when 'event' then exists (select 1 from knowledge.events e where e.id = p_ref_id and e.compartments <@ v_clearance and policy.label_key(e.compartments) = any (v_keys))
      when 'calendar' then exists (select 1 from knowledge.events e where e.id = p_ref_id and e.compartments <@ v_clearance and policy.label_key(e.compartments) = any (v_keys))
      when 'entity' then exists (select 1 from knowledge.accounts a where a.entity_id = p_ref_id and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys))
        or exists (select 1 from knowledge.domains d where d.entity_id = p_ref_id and d.compartments <@ v_clearance and policy.label_key(d.compartments) = any (v_keys))
      when 'opportunity' then exists (select 1 from ledger.opportunities o where o.id = p_ref_id and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys) and o.tainted_at is null)
      when 'commitment' then p_ref_id ~ '^[0-9a-f]{64}$'
      when 'next_step' then p_ref_id ~ '^[0-9a-f]{64}$'
      when 'plan' then p_ref_id ~ '^[0-9a-f]{64}$'
      else false end) then
    return null;
  end if;
  v_label := ledger.label(v_clearance);
  if v_asks then
    perform ledger.lock_rows('{}'::text[]);
  end if;
  if v_asks and (p_tools is null or not ledger.tried_holds(v_caller, p_tools, p_sources, v_label)) then
    return 'unpaid';
  end if;
  insert into ledger.signal_marks (id, request_id, created_by, client_id, client_name, session_id, compartments, ref_kind, ref_id, state, note_enc, evidence_ids,
    question_tools, question_sources, question_paid_at)
  values (p_id, p_request_id, v_author, v_caller, (select k.name from policy.clients k where k.id = v_caller), p_session_id,
          v_label, p_ref_kind, p_ref_id, p_state, p_note_enc, coalesce(p_evidence_ids, '{}'),
          case when v_asks then p_tools end, case when v_asks then p_sources end, case when v_asks then now() end);
  return p_id;
end
$_$;

CREATE FUNCTION ledger.write_notices() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_item text;
  v_setter text;
  v_tier text;
  v_kind text;
  v_role text;
  v_event text;
  v_client text;
  v_route text;
  v_self text;
  v_rung integer;
  v_due timestamptz;
  v_gap text;
  v_batched boolean;
  v_wrote boolean := false;
begin
  begin
    if new.row_kind = 'intention' then
      select i.opportunity_id, i.client_id into v_item, v_setter from ledger.intentions i where i.id = new.row_id and i.kind = 'check_back';
      if v_item is null or v_setter is null then
        return null;
      end if;
    else
      v_item := new.row_id;
    end if;
    select o.tier, o.kind, o.due_at, o.gap_trigger into v_tier, v_kind, v_due, v_gap from ledger.opportunities o where o.id = v_item;
    v_role := case when v_tier = 'task' then ledger.route_of(v_item)
      else (select i.role from policy.intents i
            where i.id = (select d.intent_id from ledger.opportunity_decisions d where d.opportunity_id = v_item order by d.id desc limit 1)) end;
    if new.row_kind = 'intention' then
      v_event := 'intention_due';
    else
      v_event := case
        when new."by" = 'system:handoff' then 'routed'
        when new.code is not null then 'returned'
        when exists (select 1 from ledger.record_events r where r.row_kind = 'opportunity' and r.row_id = v_item and r.event = 'go' and r.id < new.id) then 'returned'
        when v_tier = 'task' then 'task_go'
        else 'opportunity_go' end;
    end if;
    if new.row_kind <> 'intention' then
      v_self := case when new."by" like 'client:%' then substr(new."by", 8)
                     when new."by" = 'system:handoff' then
                       (select substr(r."by", 8) from ledger.record_events r
                        where r.row_kind = 'opportunity' and r.row_id = v_item and r.event = 'routed' and r."by" like 'client:%'
                          and r.id = (select max(x.id) from ledger.record_events x where x.row_kind = 'opportunity' and x.row_id = v_item and x.event = 'routed'))
                     end;
    end if;
    v_batched := v_tier = 'task' and v_gap is not null and v_due is null;
    v_route := case when v_tier = 'task' then v_role end;
    v_rung := null;
    if v_setter is null and cardinality(coalesce((select s.ping_order from policy.work_settings s), '{}'::text[])) > 0 then
      v_rung := case when v_route is not null then 0 else ledger.ping_next_place(v_item, v_self, 0) end;
      if v_rung is not null then
        perform ledger.ping_walk(v_item, v_rung, v_batched);
      end if;
    end if;
    for v_client in
      select t.client_id from ledger.ping_clients(v_item, v_setter, v_route, v_self, v_rung) t
      order by t.client_id collate "C"
    loop
      insert into ledger.work_notices as n (id, client_id, opportunity_id, event, tier, kind, role, txid, ping_rung, batched, next_try_at)
      values (ledger.new_id('ntc'), v_client, v_item, v_event, v_tier, v_kind, v_role, txid_current(), v_rung, v_batched,
              case when v_batched then ledger.ping_batch_at(now()) else now() end)
      on conflict (client_id, opportunity_id, txid) do update set event = excluded.event, role = excluded.role
        where array_position(array['intention_due', 'stage_cleared', 'routed', 'returned', 'task_go', 'opportunity_go'], excluded.event)
            < array_position(array['intention_due', 'stage_cleared', 'routed', 'returned', 'task_go', 'opportunity_go'], n.event);
      v_wrote := v_wrote or not v_batched;
    end loop;
    if v_wrote then
      perform pg_notify('pi_work_notice', '');
    end if;
  exception when others then
    begin
      insert into ledger.work_notices (id, client_id, opportunity_id, txid, state, last_code)
      values (ledger.new_id('ntc'), null, v_item, txid_current(), 'failed', 'notice_error')
      on conflict (client_id, opportunity_id, txid) do nothing;
    exception when others then
      null;
    end;
  end;
  return null;
end
$$;

CREATE FUNCTION ledger.wrong_merge_parts(p_parts jsonb, p_clearance text[], p_keys text[]) RETURNS TABLE(part_no integer, id text, entity_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select p.ord::integer, i.fp,
    (select min(a.entity_id collate "C") from knowledge.accounts a
     where a.value_fp = i.fp and a.compartments <@ p_clearance and policy.label_key(a.compartments) = any (p_keys))
  from jsonb_array_elements(p_parts) with ordinality as p (fps, ord)
  cross join lateral jsonb_array_elements_text(p.fps) as i (fp)
$$;

CREATE FUNCTION ledger.wrong_merges_to_owner(p_days integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_n integer;
begin
  if p_days is null or p_days not between 0 and 365 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform ledger.lock_rows(array['identity:wrong_merges']);
  update ledger.wrong_merge_reports r set state = 'refused', code = 'changed', settled_at = now()
  where r.state = 'open'
    and exists (select 1 from unnest(r.members) as m (one) where not exists (select 1 from knowledge.entities e where e.id = m.one));
  with closed as (
    update ledger.wrong_merge_reports r
    set state = 'owner', settled_at = now(),
        code = case when exists (select 1 from ledger.wrong_merge_reports o
                                 where o.group_key = r.group_key and o.state = 'open' and o.client_id <> r.client_id
                                   and o.partition_key <> r.partition_key and o.compartments = r.compartments)
                    then 'disagreed' else 'one_agent' end
    where r.state = 'open'
      and (r.created_at <= now() - make_interval(days => p_days)
           or exists (select 1 from ledger.wrong_merge_reports o
                      where o.group_key = r.group_key and o.state = 'open' and o.client_id <> r.client_id
                        and o.partition_key <> r.partition_key and o.compartments = r.compartments))
    returning 1
  ) select count(*) into v_n from closed;
  return v_n;
end
$$;

CREATE FUNCTION policy.agent_app_label(rule_id text) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select case when r.client_id is null then '{}'::text[]
              else (select array(select unnest(c.compartments) order by 1) from policy.clients c where c.id = r.client_id) end
  from policy.capture_scope r
  where r.id = agent_app_label.rule_id and r.agent_app
$$;

CREATE FUNCTION policy.agent_closes_on() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce((select d.answer = 'on' from knowledge.owner_decisions d
                   where d.kind = 'close_release' and d.tainted_at is null
                   order by d.decided_at desc, d.id collate "C" desc limit 1), false)
$$;

CREATE FUNCTION policy.agent_confirmed_claims(claim_keys text[]) RETURNS SETOF text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_reader boolean := session_user = 'pi_reader';
  v_restricted boolean := session_user = 'pi_restricted';
  v_clearance text[];
  v_keys text[];
begin
  if coalesce(cardinality(claim_keys), 0) > 1000 then
    raise exception 'too many keys' using errcode = '22023';
  end if;
  if v_reader then
    v_clearance := policy.client_clearance();
    v_keys := policy.clearance_keys();
  end if;
  return query
    select distinct k.key
    from unnest(agent_confirmed_claims.claim_keys) as k (key)
    where exists (
      select 1
      from ledger.cards c
      join ledger.agent_rulings g on g.card_id = c.id
      where c.kind = 'agent_claim' and c.created_by = 'system:extract' and c.request_id = k.key and c.tainted_at is null
        and g.answer = 'confirm'
        and (select r.code from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1)
            is not distinct from 'agent_confirm'
        and not exists (select 1 from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id and r.by = 'owner')
        and not exists (select 1 from knowledge.owner_decisions o where o.card_id = c.id and o.kind = 'answer' and o.tainted_at is null)
        and (not v_reader or (c.compartments <@ v_clearance and policy.label_key(c.compartments) = any (v_keys)))
        and (not v_restricted or policy.is_restricted(c.compartments))
        and not exists (select 1 from ledger.restatement_checks r
                        where r.claim_key = k.key and r.answer in ('echo', 'stale') and r.cleared_at is null))
    order by 1;
end
$$;

CREATE FUNCTION policy.answered_records(evidence_ids text[]) RETURNS SETOF text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if coalesce(cardinality(evidence_ids), 0) > 1000 then
    raise exception 'too many ids' using errcode = '22023';
  end if;
  return query
    select distinct w.evidence_id
    from ledger.agent_writes w
    where w.evidence_id = any (answered_records.evidence_ids) and w.kind = 'answer' and w.body_enc is not null
      and exists (select 1 from knowledge.owner_decisions o
                  where o.kind = 'owner_answer' and o.request_id = w.id and o.target_kind = 'opportunity' and o.target_id = w.opportunity_id
                    and o.tainted_at is null
                    and not exists (select 1 from knowledge.owner_decisions s where s.supersedes = o.id))
    order by 1;
end
$$;

CREATE FUNCTION policy.append_record(session_id text, new_id text, request_id text, kind text, content_fp text, cites_fp text, cites text[], compartments text[], body_enc jsonb, stamps text[], supersedes_id text DEFAULT NULL::text, project_id text DEFAULT NULL::text) RETURNS TABLE(outcome text, record_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  caller text;
  caller_name text;
  caller_views text[];
  caller_tools text[];
  earlier record;
  v_clearance text[];
  v_keys text[];
  v_view_keys text[];
  v_target boolean;
  v_move text;
  v_node text;
  v_node_label text[];
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'an append runs read committed' using errcode = '42501';
  end if;
  select c.id, c.name, c.views, c.tools into caller, caller_name, caller_views, caller_tools from policy.current_client() c;
  if caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  if not ((case when append_record.kind = 'fill' then 'report_move' else 'record' end) = any (caller_tools)) then
    raise exception 'not this client''s tool' using errcode = '42501';
  end if;
  if not exists (select 1 from ledger.sessions s where s.id = append_record.session_id and s.client_id = caller) then
    raise exception 'not this client''s session' using errcode = '42501';
  end if;
  select w.id, w.kind, w.content_fp, w.cites_fp, w.supersedes, w.project_id into earlier
  from ledger.agent_writes w where w.client_id = caller and w.request_id = append_record.request_id;
  if found then
    if earlier.kind = append_record.kind and earlier.content_fp = append_record.content_fp and earlier.cites_fp = append_record.cites_fp
       and earlier.supersedes is not distinct from append_record.supersedes_id
       and earlier.project_id is not distinct from append_record.project_id then
      return query select 'replayed'::text, earlier.id;
    else
      return query select 'request_reused'::text, null::text;
    end if;
    return;
  end if;
  insert into policy.record_quota as q (client_id) values (caller)
  on conflict (client_id) do update set attempts = q.attempts + 1, updated_at = now();
  if (select count(*) from ledger.agent_writes w where w.client_id = caller and w.kind <> 'memory_change' and w.created_at > now() - interval '24 hours') >= 200 then
    return query select 'rate_limited'::text, null::text;
    return;
  end if;
  if append_record.compartments is distinct from policy.record_label() then
    return query select 'label_mismatch'::text, null::text;
    return;
  end if;
  if append_record.body_enc is null or not (jsonb_typeof(append_record.body_enc) = 'object' and append_record.body_enc ?& array['v', 'nonce', 'ciphertext', 'tag'] and (append_record.body_enc - array['v', 'nonce', 'ciphertext', 'tag']) = '{}'::jsonb
      and append_record.body_enc -> 'v' = '1'::jsonb and jsonb_typeof(append_record.body_enc -> 'nonce') = 'string' and jsonb_typeof(append_record.body_enc -> 'ciphertext') = 'string' and jsonb_typeof(append_record.body_enc -> 'tag') = 'string'
      and append_record.body_enc ->> 'nonce' <> '' and append_record.body_enc ->> 'tag' <> '' and append_record.body_enc ->> 'nonce' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' and append_record.body_enc ->> 'ciphertext' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' and append_record.body_enc ->> 'tag' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$') then
    return query select 'body_refused'::text, null::text;
    return;
  end if;
  if append_record.supersedes_id is not null then
    v_clearance := policy.client_clearance();
    v_keys := policy.clearance_keys();
    v_view_keys := policy.view_keys();
    v_target := exists (
      select 1 from ledger.agent_writes w
      where w.id = append_record.supersedes_id and w.client_id = caller and w.tool = 'record' and w.kind = append_record.kind and w.kind in ('note', 'finding') and w.body_enc is not null
        and w.compartments <@ v_clearance and policy.label_key(w.compartments) = any (v_keys)
        and w.writer_views <@ caller_views and policy.label_key(w.writer_views) = any (v_view_keys)
        and w.flagged_at is null);
    if not v_target then
      return query select 'not_found'::text, null::text;
      return;
    end if;
    if exists (select 1 from policy.live_corrections(array[append_record.supersedes_id])) then
      return query select 'superseded'::text, null::text;
      return;
    end if;
  end if;
  if append_record.project_id is not null then
    if append_record.kind <> 'finding' or not ('work' = any (caller_views))
       or not exists (select 1 from knowledge.projects p
                      where p.id = append_record.project_id and p.compartments <@ policy.client_clearance()) then
      return query select 'not_found'::text, null::text;
      return;
    end if;
  end if;
  if append_record.kind = 'fill' then
    if append_record.supersedes_id is not null or coalesce(cardinality(append_record.stamps), 0) > 0 then
      raise exception 'invalid request' using errcode = '22023';
    end if;
    select m.id, o.about_id, o.compartments into v_move, v_node, v_node_label
    from ledger.record_events r
    join ledger.moves m on m.id = r.row_id
    join ledger.opportunities o on o.id = m.opportunity_id
    where r.row_kind = 'move' and r.event = 'done' and r.by = 'client:' || caller and r.at = now()
      and o.gap_trigger = 'explore' and o.about_kind = 'entity'
    order by r.id desc limit 1;
    if v_node is null then
      return query select 'not_found'::text, null::text;
      return;
    end if;
    if v_node_label is distinct from array['own']::text[]
       or not ('own' = any (policy.record_label()))
       or exists (select 1 from unnest(policy.record_label()) c where c <> 'own' and not starts_with(c, 'agent:')) then
      return query select 'label_wider'::text, null::text;
      return;
    end if;
  end if;
  if exists (select 1 from unnest(append_record.cites) as c (id)
             where not exists (select 1 from vault.evidence_items e where e.id = c.id)) then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  if exists (select 1 from ledger.read_log r cross join lateral unnest(r.bound) as b (one)
             where r.session_id = append_record.session_id
               and not exists (select 1 from vault.evidence_items e where e.id = b.one)) then
    return query select 'read_removed'::text, null::text;
    return;
  end if;
  if cardinality(append_record.stamps) > 0
     and exists (select 1 from ledger.memory_projections m
                 where m.id = any (append_record.stamps) and m.client_id = caller and m.tainted_at is not null) then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  insert into ledger.agent_writes (id, client_id, client_name, session_id, request_id, tool, kind, compartments, writer_views, content_fp, cites_fp, cites, body_enc, supersedes,
    fill_node, fill_move, project_id)
  values (append_record.new_id, caller, caller_name, append_record.session_id, append_record.request_id,
          case when append_record.kind = 'fill' then 'report_move' else 'record' end, append_record.kind,
          policy.record_label(), caller_views, append_record.content_fp, append_record.cites_fp, append_record.cites, append_record.body_enc, append_record.supersedes_id,
          v_node, v_move, append_record.project_id);
  return query select 'ok'::text, append_record.new_id;
end
$_$;

CREATE FUNCTION policy.audiences() RETURNS SETOF text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select distinct (select array_agg(x order by x collate "C") from unnest(c.compartments) x)
  from policy.clients c
  where c.status = 'active' and policy.is_restricted(c.compartments) = (session_user = 'pi_restricted')
    and c.kind <> 'device'
$$;

CREATE FUNCTION policy.belief_inputs(fact_key_fps text[], as_of timestamp with time zone) RETURNS TABLE(part text, id text, evidence_id text, fact_key_fp text, other_fp text, legacy text[], carried text[], word text, at timestamp with time zone, compartments text[], body jsonb, flags text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if coalesce(cardinality(belief_inputs.fact_key_fps), 0) > 1000 then
    raise exception 'too many keys' using errcode = '22023';
  end if;
  if cardinality(policy.clearance_keys()) = 0 then
    return;
  end if;
  return query select * from policy.belief_inputs_under(policy.client_clearance(), belief_inputs.fact_key_fps, belief_inputs.as_of);
end
$$;

CREATE FUNCTION policy.belief_inputs_core(clearance text[], fact_key_fps text[], as_of timestamp with time zone) RETURNS TABLE(part text, id text, evidence_id text, fact_key_fp text, other_fp text, legacy text[], carried text[], word text, at timestamp with time zone, compartments text[], body jsonb, flags text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_keys text[];
  v_audience text[];
  v_asked text[];
  v_more text[];
  v_legacy text[];
  v_round integer;
begin
  if coalesce(cardinality(belief_inputs_core.fact_key_fps), 0) > 1000 then
    raise exception 'too many keys' using errcode = '22023';
  end if;
  v_audience := array(select distinct one collate "C" from unnest(belief_inputs_core.clearance) as one where one is not null order by 1);
  if cardinality(v_audience) not between 1 and 32 or belief_inputs_core.as_of is null then
    return;
  end if;
  v_keys := array(
    select k.key from (
      select l.key from policy.labels l where cardinality(l.compartments) > 0 and l.compartments <@ v_audience
      union select policy.label_key(v_audience)) k
    where k.key is not null and k.key <> '' order by k.key collate "C");

  v_asked := array(select distinct k from unnest(belief_inputs_core.fact_key_fps) as k where k is not null);
  for v_round in 1..5 loop
    v_more := array(
      select distinct x.k from (
        select case when f.a_fp = any (v_asked) then f.b_fp else f.a_fp end as k
        from knowledge.fact_rulings f
        where policy.label_key(f.compartments) = any (v_keys) and f.verdict = 'join'
          and (f.a_fp = any (v_asked) or f.b_fp = any (v_asked))
          and f.created_at <= belief_inputs_core.as_of and (f.lifted_at is null or f.lifted_at > belief_inputs_core.as_of)
        union all
        select case when g.a_fp = any (v_asked) then g.b_fp else g.a_fp end as k
        from knowledge.same_fact_judgments g
        where policy.label_key(g.compartments) = any (v_keys) and g.state = 'accepted'
          and (g.a_fp = any (v_asked) or g.b_fp = any (v_asked))
          and g.updated_at <= belief_inputs_core.as_of
        union all
        select c2.fact_key_fp as k
        from knowledge.claims c1
        join knowledge.claim_values v1 on v1.claim_id = c1.id
        join knowledge.claim_relations r on r.from_claim_key = v1.claim_key
        join knowledge.claim_values v2 on v2.claim_key = r.to_claim_key
        join knowledge.claims c2 on c2.id = v2.claim_id
        where policy.label_key(c1.compartments) = any (v_keys) and c1.fact_key_fp = any (v_asked) and c1.first_known_at <= belief_inputs_core.as_of
          and policy.label_key(v1.compartments) = any (v_keys) and policy.label_key(r.compartments) = any (v_keys) and r.judged_at <= belief_inputs_core.as_of
          and policy.label_key(v2.compartments) = any (v_keys) and policy.label_key(c2.compartments) = any (v_keys) and c2.first_known_at <= belief_inputs_core.as_of
        union all
        select c2.fact_key_fp as k
        from knowledge.claims c1
        join knowledge.claim_values v1 on v1.claim_id = c1.id
        join knowledge.claim_relations r on r.to_claim_key = v1.claim_key
        join knowledge.claim_values v2 on v2.claim_key = r.from_claim_key
        join knowledge.claims c2 on c2.id = v2.claim_id
        where policy.label_key(c1.compartments) = any (v_keys) and c1.fact_key_fp = any (v_asked) and c1.first_known_at <= belief_inputs_core.as_of
          and policy.label_key(v1.compartments) = any (v_keys) and policy.label_key(r.compartments) = any (v_keys) and r.judged_at <= belief_inputs_core.as_of
          and policy.label_key(v2.compartments) = any (v_keys) and policy.label_key(c2.compartments) = any (v_keys) and c2.first_known_at <= belief_inputs_core.as_of) x
      where not x.k = any (v_asked) and cardinality(v_asked) < 1000);
    exit when cardinality(v_more) = 0;
    v_asked := v_asked || v_more[1:greatest(0, 1000 - cardinality(v_asked))];
  end loop;

  v_legacy := array(
    select distinct l.fp
    from knowledge.claims c cross join unnest(array[c.legacy_fact_key_fp, c.legacy_alt_fact_key_fp]) as l (fp)
    where policy.label_key(c.compartments) = any (v_keys) and c.fact_key_fp = any (v_asked) and l.fp is not null);

  return query
    select 'settings'::text, (select e.id from knowledge.entities e where e.kind = 'owner' limit 1), null::text, null::text, null::text, null::text[], null::text[],
           s.grouping, s.fact_key_v2_at, '{}'::text[], null::jsonb, '{}'::text[]
    from policy.owner_settings s;

  return query
    with cand as materialized (
      select c.id, c.evidence_id, c.fact_key_fp, c.type, c.first_known_at, c.compartments, c.content_enc,
             array_remove(array_remove(array[c.legacy_fact_key_fp, c.legacy_alt_fact_key_fp], null), c.fact_key_fp) as legacy,
             e.source_account_id, e.source_item_fp, e.source_kind, e.typed
      from knowledge.claims c join vault.evidence_items e on e.id = c.evidence_id
      where policy.label_key(c.compartments) = any (v_keys) and c.fact_key_fp = any (v_asked) and c.first_known_at <= belief_inputs_core.as_of),
    released as materialized (select d.evidence_id from policy.released_records() d)
    select 'claim'::text, cand.id, cand.evidence_id, cand.fact_key_fp, null::text, cand.legacy,
           array(
             select distinct r.ruling_id
             from knowledge.belief_rulings r cross join unnest(r.item_account_ids, r.item_fps) as i (source_account_id, source_item_fp)
             where policy.label_key(r.compartments) = any (v_keys) and r.fact_key_fp = any (cand.legacy) and r.verdict in ('veto', 'retire')
               and i.source_account_id = cand.source_account_id and i.source_item_fp = cand.source_item_fp
               and r.created_at <= belief_inputs_core.as_of and (r.lifted_at is null or r.lifted_at > belief_inputs_core.as_of)
             order by 1),
           cand.type, cand.first_known_at, cand.compartments, cand.content_enc,
           array_remove(array[
             case when exists (select 1 from knowledge.captures k where policy.label_key(k.compartments) = any (v_keys) and k.evidence_id = cand.evidence_id and k.agent_app) then 'agent_app' end,
             case when exists (select 1 from knowledge.captures k where policy.label_key(k.compartments) = any (v_keys) and k.evidence_id = cand.evidence_id and k.event_id is not null) then 'linked' end,
             case when exists (select 1 from policy.answered_records(array[cand.evidence_id])) then 'answered' end,
             case when exists (
               select 1 from ledger.commitment_reopens o join ledger.agent_writes w on w.id = o.close_id
               where policy.label_key(o.compartments) = any (v_keys) and policy.label_key(w.compartments) = any (v_keys)
                 and w.evidence_id = cand.evidence_id) then 'reopened' end,
             case when exists (select 1 from released d where d.evidence_id = cand.evidence_id) then 'released' end,
             case when cand.source_kind = 'agent_record' then 'agent_item' end,
             case when cand.typed then 'typed' end], null)
    from cand
    where not exists (
      select 1 from knowledge.belief_rulings r
      where policy.label_key(r.compartments) = any (v_keys) and r.fact_key_fp = any (array[cand.fact_key_fp] || cand.legacy) and r.verdict = 'reject'
        and r.source_account_id = cand.source_account_id and r.source_item_fp = cand.source_item_fp
        and r.created_at <= belief_inputs_core.as_of and (r.lifted_at is null or r.lifted_at > belief_inputs_core.as_of));

  return query
    select case when r.verdict in ('domain', 'kind') then 'reclassify' else r.verdict end, r.ruling_id, null::text, r.fact_key_fp, null::text, null::text[], null::text[],
           r.verdict, r.created_at, r.compartments,
           case when r.verdict in ('domain', 'kind') then r.value_enc end, '{}'::text[]
    from knowledge.belief_rulings r
    where policy.label_key(r.compartments) = any (v_keys) and r.fact_key_fp = any (v_asked || v_legacy) and r.verdict in ('veto', 'retire', 'domain', 'kind')
      and r.created_at <= belief_inputs_core.as_of and (r.lifted_at is null or r.lifted_at > belief_inputs_core.as_of)
    order by r.created_at, r.ruling_id collate "C";

  return query
    select 'fact_ruling'::text, f.ruling_id, null::text, f.a_fp, f.b_fp, null::text[], null::text[], f.verdict, f.created_at, f.compartments, null::jsonb, '{}'::text[]
    from knowledge.fact_rulings f
    where policy.label_key(f.compartments) = any (v_keys) and (f.a_fp = any (v_asked) or f.b_fp = any (v_asked))
      and f.created_at <= belief_inputs_core.as_of and (f.lifted_at is null or f.lifted_at > belief_inputs_core.as_of)
    order by f.created_at, f.ruling_id collate "C";

  return query
    select 'grouping'::text, null::text, null::text, g.a_fp, g.b_fp, g.compartments, null::text[], g.band, g.updated_at, g.compartments,
           jsonb_build_object('rung', g.rung, 'calls', to_jsonb(g.calls)), '{}'::text[]
    from knowledge.same_fact_judgments g
    where policy.label_key(g.compartments) = any (v_keys) and g.state = 'accepted'
      and (g.a_fp = any (v_asked) or g.b_fp = any (v_asked)) and g.updated_at <= belief_inputs_core.as_of
    order by g.a_fp, g.b_fp;

  return query
    with held as materialized (
      select distinct v.claim_key
      from knowledge.claims c join knowledge.claim_values v on v.claim_id = c.id
      where policy.label_key(c.compartments) = any (v_keys) and c.fact_key_fp = any (v_asked) and c.first_known_at <= belief_inputs_core.as_of
        and policy.label_key(v.compartments) = any (v_keys))
    select 'relation'::text, r.id::text, null::text, r.from_claim_key, r.to_claim_key, null::text[], null::text[], r.kind, r.judged_at, r.compartments,
           jsonb_build_object('judge', r.judged_by), '{}'::text[]
    from knowledge.claim_relations r
    where policy.label_key(r.compartments) = any (v_keys) and r.judged_at <= belief_inputs_core.as_of
      and r.from_claim_key in (select h.claim_key from held h) and r.to_claim_key in (select h.claim_key from held h)
    order by r.judged_at, r.id;

  return query
    select 'relation_switch'::text, s.id::text, null::text, null::text, null::text, null::text[], null::text[], s.kind, s.decided_at, '{}'::text[],
           jsonb_build_object('judge', s.judge, 'on', s.switched_on, 'by', s.decided_by), '{}'::text[]
    from policy.relation_switches s
    where s.decided_at <= belief_inputs_core.as_of
    order by s.decided_at, s.id;
end
$$;

CREATE FUNCTION policy.belief_inputs_under(clearance text[], fact_key_fps text[], as_of timestamp with time zone) RETURNS TABLE(part text, id text, evidence_id text, fact_key_fp text, other_fp text, legacy text[], carried text[], word text, at timestamp with time zone, compartments text[], body jsonb, flags text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_row record;
  v_claims text[] := '{}';
  v_audience text[];
  v_keys text[];
  v_held text[];
begin
  for v_row in select * from policy.belief_inputs_core(belief_inputs_under.clearance, belief_inputs_under.fact_key_fps, belief_inputs_under.as_of) loop
    if v_row.part = 'claim' then
      v_claims := v_claims || v_row.id;
    end if;
    continue when v_row.part = 'relation_switch' and v_row.word = 'same_person';
    continue when v_row.part = 'relation'
      and not policy.relation_effective(v_row.id::bigint, v_row.body ->> 'judge', v_row.word, v_row.at, belief_inputs_under.as_of);
    part := v_row.part; id := v_row.id; evidence_id := v_row.evidence_id; fact_key_fp := v_row.fact_key_fp; other_fp := v_row.other_fp;
    legacy := v_row.legacy; carried := v_row.carried; word := v_row.word; at := v_row.at; compartments := v_row.compartments;
    body := v_row.body; flags := v_row.flags;
    return next;
  end loop;
  if cardinality(v_claims) = 0 then
    return;
  end if;
  v_audience := array(select distinct one collate "C" from unnest(belief_inputs_under.clearance) as one where one is not null order by 1);
  v_keys := array(
    select k.key from (
      select l.key from policy.labels l where cardinality(l.compartments) > 0 and l.compartments <@ v_audience
      union select policy.label_key(v_audience)) k
    where k.key is not null and k.key <> '' order by k.key collate "C");
  v_held := array(select distinct v.claim_key from knowledge.claim_values v
                  where v.claim_id = any (v_claims) and policy.label_key(v.compartments) = any (v_keys));
  return query
    select 'settlement'::text, s.id, null::text, s.a_key, s.b_key, null::text[], null::text[], s.holds_key, s.created_at, s.compartments, null::jsonb, '{}'::text[]
    from ledger.belief_settlements s
    where policy.label_key(s.compartments) = any (v_keys) and s.a_key = any (v_held) and s.b_key = any (v_held)
      and s.created_at <= belief_inputs_under.as_of and (s.lifted_at is null or s.lifted_at > belief_inputs_under.as_of)
    order by s.created_at, s.id collate "C";
  return query
    select x.part, x.id, x.evidence_id, x.fact_key_fp, x.other_fp, x.legacy, x.carried, x.word, x.at, x.compartments, x.body, x.flags
    from (
      select distinct on (c.target_key) 'belief_check'::text as part, c.id::text as id, null::text as evidence_id, null::text as fact_key_fp,
             null::text as other_fp, c.claim_keys as legacy, null::text[] as carried, c.verdict as word, c.created_at as at, c.compartments,
             null::jsonb as body, '{}'::text[] as flags
      from ledger.source_checks c
      where c.target = 'belief' and starts_with(c.judge, 'model:') and c.verdict is not null and c.on_cited and c.live
        and policy.label_key(c.compartments) = any (v_keys) and c.claim_keys <@ v_held and c.created_at <= belief_inputs_under.as_of
      order by c.target_key, c.created_at desc, c.id desc) x
    order by x.at, x.id;
end
$$;

CREATE FUNCTION policy.belief_rulings_mark() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select (select count(*) + count(r.lifted_at) from knowledge.belief_rulings r)
    + (select coalesce(sum(s.fact_rulings_mark), 0) from policy.owner_settings s)::bigint
    + (select count(*) from policy.fact_ruling_marks)
$$;

CREATE FUNCTION policy.capture_erased_since_push(session_id text) RETURNS TABLE(capture_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_tools text[];
  v_kind text;
  v_mirror text;
begin
  select c.id, c.tools into v_caller, v_tools from policy.current_client() c;
  select k.kind into v_kind from policy.clients k where k.id = v_caller;
  select d.mirror_client_id into v_mirror from policy.lens_devices d where d.capture_client_id = v_caller;
  if v_caller is null or v_kind is distinct from 'device' or not ('push_capture' = any (v_tools)) or v_mirror is null
     or not exists (select 1 from ledger.sessions s where s.id = capture_erased_since_push.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  return query
    with due as (
      select x.id from ledger.capture_erasures x
      where x.client_id = v_mirror and x.confirmed_at is null and x.acked_at is null
      order by x.erased_at, x.id
      limit 500
      for update
    ),
    marked as (
      update ledger.capture_erasures x set acked_at = now() from due where x.id = due.id
      returning x.capture_key, x.erased_at, x.id
    )
    select m.capture_key from marked m order by m.erased_at, m.id;
end
$$;

CREATE FUNCTION policy.carried_ruling_items() RETURNS TABLE(ruling_id text, ruling_kind text, fact_key_fp text, claim_key text, source_account_id text, source_item_fp text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select ruling_id, ruling_kind, fact_key_fp, claim_key, source_account_id, source_item_fp
  from (
    select r.ruling_id, r.verdict as ruling_kind, r.fact_key_fp, null::text as claim_key, i.source_account_id, i.source_item_fp
    from knowledge.belief_rulings r cross join unnest(r.item_account_ids, r.item_fps) as i (source_account_id, source_item_fp)
    where r.verdict in ('veto', 'retire') and r.lifted_at is null
    union
    select f.ruling_id, f.verdict, s.fp, null::text, e.source_account_id, e.source_item_fp
    from knowledge.fact_rulings f
    cross join unnest(array[f.a_fp, f.b_fp]) as s (fp)
    join lateral (
      select c.evidence_id from knowledge.claims c where c.fact_key_fp = s.fp
      union select c.evidence_id from knowledge.claims c where c.legacy_fact_key_fp = s.fp
      union select c.evidence_id from knowledge.claims c where c.legacy_alt_fact_key_fp = s.fp) h on true
    join vault.evidence_items e on e.id = h.evidence_id
    where f.lifted_at is null
    union
    select substr(r.judged_by, 7), 'relation', null::text, k.key, e.source_account_id, e.source_item_fp
    from knowledge.claim_relations r
    cross join unnest(array[r.from_claim_key, r.to_claim_key]) as k (key)
    join knowledge.claim_values v on v.claim_key = k.key
    join knowledge.claims c on c.id = v.claim_id
    join vault.evidence_items e on e.id = c.evidence_id
    where starts_with(r.judged_by, 'owner:')) carried
  order by ruling_id collate "C", ruling_kind collate "C", fact_key_fp collate "C", claim_key collate "C", source_account_id collate "C", source_item_fp collate "C"
$$;

CREATE FUNCTION policy.carry_gate(p_generation integer) RETURNS TABLE(ruling_id text, state text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with side as (
    select r.ruling_id, r.fact_key_fp as key_fp, r.claim_type, r.evidence_ids, r.entity_ids,
           r.verdict = 'reject' as own_item, r.source_account_id, r.source_item_fp, r.item_account_ids, r.item_fps,
           r.created_at, r.shown_enc is not null as has_shown
    from knowledge.belief_rulings r
    where r.lifted_at is null
    union all
    select f.ruling_id, s.fp, f.claim_type, s.evidence_ids, f.entity_ids, false, null, null, null, null,
           f.created_at, f.shown_enc is not null
    from knowledge.fact_rulings f
    cross join lateral (values (f.a_fp, f.a_evidence_ids), (f.b_fp, f.b_evidence_ids)) as s (fp, evidence_ids)
    where f.lifted_at is null),
  later as (
    select b.ruling_id, b.created_at, b.evidence_ids, array[b.fact_key_fp] as key_fps
    from knowledge.belief_rulings b
    where b.lifted_at is null
      and not exists (select 1 from knowledge.owner_decisions d where d.id = b.ruling_id and d.kind = 'ruling_carry')
    union all
    select g.ruling_id, g.created_at, g.a_evidence_ids || g.b_evidence_ids, array[g.a_fp, g.b_fp]
    from knowledge.fact_rulings g
    where g.lifted_at is null
      and not exists (select 1 from knowledge.owner_decisions d where d.id = g.ruling_id and d.kind = 'ruling_carry')),
  open_side as (
    select s.* from side s
    where not exists (select 1 from knowledge.owner_decisions d where d.kind = 'ruling_carry' and d.details ->> 'from' = s.ruling_id)
      and not exists (
        select 1 from ledger.cards c join ledger.record_events v on v.row_kind = 'card' and v.row_id = c.id
        where c.kind = 'ruling_carry' and starts_with(c.case_key, 'ruling_carry:' || s.ruling_id || ':')
          and v.event = 'decided' and v.by = 'owner'
          and not exists (select 1 from ledger.record_events w where w.row_kind = 'card' and w.row_id = c.id and w.id > v.id))
      and not exists (
        select 1 from ledger.improvements i
        where starts_with(i.cause, 'ruling_detached:' || lower(s.ruling_id) || ':')
          and (select v.status in ('wont_do', 'duplicate') and v.created_by = 'owner' from ledger.improvement_events v
               where v.improvement_id = i.id and v.event = 'status'
               order by v.created_at desc, v.id collate "C" desc limit 1))
      and not exists (
        select 1 from later n
        where n.ruling_id <> s.ruling_id and n.created_at > s.created_at and n.evidence_ids && s.evidence_ids
          and s.key_fp = any (n.key_fps))
      and coalesce((
        select bool_or(not exists (select 1 from later n
                                   where n.ruling_id <> s.ruling_id and n.created_at > s.created_at and k.fp = any (n.key_fps)))
        from (
          select distinct c.fact_key_fp as fp from vault.evidence_items a
          join vault.evidence_items e on e.source_account_id = a.source_account_id and e.source_item_fp = a.source_item_fp
          join knowledge.claims c on c.evidence_id = e.id
          where a.id = any (s.evidence_ids) and c.extractor_generation >= carry_gate.p_generation and c.type = s.claim_type
            and array(select n.entity_id from knowledge.claim_entities n where n.claim_id = c.id order by n.entity_id collate "C") = s.entity_ids) k), true)
      and not exists (
        select 1 from knowledge.claims c join vault.evidence_items e on e.id = c.evidence_id
        where c.extractor_generation >= carry_gate.p_generation
          and (c.fact_key_fp = s.key_fp
            or ((c.legacy_fact_key_fp = s.key_fp or c.legacy_alt_fact_key_fp = s.key_fp)
              and (s.item_fps is null
                or exists (select 1 from unnest(s.item_account_ids, s.item_fps) as i (account_id, fp)
                           where i.account_id = e.source_account_id and i.fp = e.source_item_fp))))
          and (not s.own_item or (e.source_account_id = s.source_account_id and e.source_item_fp = s.source_item_fp)))),
  judged as (
    select s.ruling_id,
      case
        when s.claim_type is null and exists (
          select 1 from knowledge.claims c
          where c.fact_key_fp = s.key_fp or c.legacy_fact_key_fp = s.key_fp or c.legacy_alt_fact_key_fp = s.key_fp) then 'unanchored'
        when s.claim_type is null then 'lost'
        when cardinality(s.evidence_ids) = 0 then 'erased'
        when exists (
          select 1 from vault.evidence_items a
          join vault.evidence_items e on e.source_account_id = a.source_account_id and e.source_item_fp = a.source_item_fp
          where a.id = any (s.evidence_ids)
            and (exists (select 1 from knowledge.claims c where c.evidence_id = e.id and c.extractor_generation < carry_gate.p_generation)
              or exists (select 1 from vault.pipeline_items p where p.evidence_id = e.id
                         and (p.waiting or (p.extractor_generation < carry_gate.p_generation and not p.withheld))))) then 'pending'
        when (
          select count(distinct c.fact_key_fp) from vault.evidence_items a
          join vault.evidence_items e on e.source_account_id = a.source_account_id and e.source_item_fp = a.source_item_fp
          join knowledge.claims c on c.evidence_id = e.id
          where a.id = any (s.evidence_ids) and c.extractor_generation >= carry_gate.p_generation and c.type = s.claim_type
            and array(select n.entity_id from knowledge.claim_entities n where n.claim_id = c.id order by n.entity_id collate "C") = s.entity_ids) = 1
          and s.has_shown
          then 'carries'
        when not exists (
          select 1 from vault.evidence_items a
          join vault.evidence_items e on e.source_account_id = a.source_account_id and e.source_item_fp = a.source_item_fp
          join knowledge.claims c on c.evidence_id = e.id
          where a.id = any (s.evidence_ids) and c.extractor_generation >= carry_gate.p_generation and c.type = s.claim_type) then 'gone'
        else 'detached'
      end as state
    from open_side s)
  select j.ruling_id,
    case when bool_or(j.state = 'unanchored') then 'unanchored'
         when bool_or(j.state = 'detached') then 'detached'
         when bool_or(j.state = 'pending') then 'pending'
         when bool_or(j.state = 'lost') then 'lost'
         when bool_or(j.state = 'gone') then 'gone'
         else 'carries' end as state
  from judged j
  where j.state <> 'erased'
  group by j.ruling_id
  order by j.ruling_id collate "C"
$$;

CREATE FUNCTION policy.census_held(p_relation bigint, p_judge text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce((
    select s.verdict = 'supported' and s.on_cited and s.live from ledger.source_checks s
    where s.target = 'relation' and s.relation_id = p_relation and starts_with(s.judge, 'model:') and s.hot is null
      and split_part(s.judge, '@', 1) <> split_part(p_judge, '@', 1)
    order by s.created_at desc, s.id desc limit 1), false)
$$;

CREATE FUNCTION policy.clearance_keys() RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with c as materialized (
    select x.clearance from (select policy.client_clearance() as clearance) x
    where policy.current_client_kind() is distinct from 'device'
      and (select count(distinct one) from unnest(x.clearance) as one) between 1 and 32
  )
  select coalesce(array_agg(k.key order by k.key collate "C"), '{}'::text[])
  from c cross join lateral (
    select l.key from policy.labels l where cardinality(l.compartments) > 0 and l.compartments <@ c.clearance
    union
    select policy.label_key(c.clearance)
  ) k
  where k.key is not null and k.key <> ''
$$;

CREATE FUNCTION policy.client_clearance() RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce((select c.compartments from policy.current_client() c join policy.clients k on k.id = c.id where k.kind <> 'device'), '{}'::text[])
$$;

CREATE FUNCTION policy.close_claim_allowed(evidence_id text, fact_key_fp text, compartments text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select policy.agent_closes_on()
    and exists (select 1 from ledger.agent_writes w
                where w.evidence_id = close_claim_allowed.evidence_id and w.kind = 'close' and w.body_enc is not null
                  and w.close_fact_fp = close_claim_allowed.fact_key_fp)
    and exists (select 1 from knowledge.claims c
                where c.fact_key_fp = close_claim_allowed.fact_key_fp and not c.closes and c.compartments = close_claim_allowed.compartments)
$$;

CREATE FUNCTION policy.commitment_closes(evidence_ids text[]) RETURNS TABLE(evidence_id text, close_id text, client_name text, ending text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_reader boolean := session_user = 'pi_reader';
  v_caller text;
  v_keys text[];
begin
  if v_reader then
    select c.id into v_caller from policy.current_client() c;
    if v_caller is null then
      raise exception 'no current client' using errcode = '42501';
    end if;
  end if;
  v_keys := policy.clearance_keys();
  return query
    select w.evidence_id, w.id, w.client_name, w.close_ending
    from ledger.agent_writes w
    where w.evidence_id = any (commitment_closes.evidence_ids) and w.kind = 'close' and w.body_enc is not null
      and not exists (select 1 from ledger.commitment_reopens r where r.close_id = w.id)
      and exists (select 1 from knowledge.claims c where c.evidence_id = w.evidence_id and c.closes
                  and (not v_reader or (c.compartments <@ policy.client_clearance() and policy.label_key(c.compartments) = any (v_keys))))
    order by w.evidence_id;
end
$$;

CREATE FUNCTION policy.confirm_rates(p_at timestamp with time zone) RETURNS TABLE(client_id text, kind text, granted boolean, answers integer, confirmed integer, kept integer, not_true integer, compartments text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select * from policy.confirm_rates_within(p_at, null, null)
$$;

CREATE FUNCTION policy.confirm_rates_within(p_at timestamp with time zone, p_clearance text[], p_keys text[]) RETURNS TABLE(client_id text, kind text, granted boolean, answers integer, confirmed integer, kept integer, not_true integer, compartments text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with seen_decisions as (
    select o.* from knowledge.owner_decisions o
    where p_clearance is null or (o.compartments <@ p_clearance and policy.label_key(o.compartments) = any (p_keys))
  ),
  since as (
    select min(o.decided_at) as at from seen_decisions o where o.kind = 'facts_clean' and o.tainted_at is null
  ),
  decisions as (
    select o.* from seen_decisions o cross join since s
    where o.kind in ('answer', 'correction') and o.tainted_at is null
      and o.decided_at > s.at and o.decided_at <= p_at and o.decided_at > p_at - interval '60 days'
      and coalesce(o.details ->> 'via', '') <> 'cleanup'
      and not exists (select 1 from knowledge.owner_decisions l where l.supersedes = o.id)
      and not exists (select 1 from ledger.card_relays y where y.ruling_id = o.id)
  ),
  edits as (
    select rtrim(translate(encode(sha256(convert_to(a.request_id || ':correct', 'UTF8')), 'base64'), '+/', '-_'), '=') as request_id
    from seen_decisions a where a.kind = 'answer'
  ),
  grants as (
    select o.id, o.decided_at, o.details ->> 'client' as client_id, o.details ->> 'kind' as kind
    from seen_decisions o
    where o.kind = 'release_grant' and o.tainted_at is null
      and not exists (select 1 from knowledge.owner_decisions s where s.supersedes = o.id)
      and not exists (select 1 from knowledge.release_lifts l where l.ruling_id = o.id)
  ),
  records as (
    select w.evidence_id, w.client_id from ledger.agent_writes w
    where w.tool = 'propose_about_you' and w.tainted_at is null and w.flagged_at is null and w.evidence_id is not null
      and (p_clearance is null or (w.compartments <@ p_clearance and policy.label_key(w.compartments) = any (p_keys)))
  ),
  claims as (
    select k.id, k.type, k.evidence_id, k.compartments from knowledge.claims k
    where p_clearance is null or (k.compartments <@ p_clearance and policy.label_key(k.compartments) = any (p_keys))
  ),
  card_answers as (
    select w.client_id, k.type as kind, o.decided_at, c.compartments, c.created_at, c.case_key like 'held:%' as held,
      o.answer = 'confirm'
        and not exists (
          select 1 from seen_decisions e
          where e.kind = 'correction'
            and e.request_id = rtrim(translate(encode(sha256(convert_to(o.request_id || ':correct', 'UTF8')), 'base64'), '+/', '-_'), '=')
        ) as confirmed
    from decisions o
    join ledger.cards c on c.id = o.card_id and c.kind = 'about_you' and c.created_by = 'system:extract' and c.target_kind = 'claim'
      and (p_clearance is null or (c.compartments <@ p_clearance and policy.label_key(c.compartments) = any (p_keys)))
    join claims k on k.id = c.target_id
    join records w on w.evidence_id = k.evidence_id
    where o.kind = 'answer' and o.answer in ('confirm', 'reject')
  ),
  sample as (
    select a.* from card_answers a
    left join grants g on g.client_id = a.client_id and g.kind = a.kind
    where g.id is null or (a.held and a.created_at >= g.decided_at)
  ),
  ranked as (
    select t.*, row_number() over (partition by t.client_id, t.kind order by t.decided_at desc) as n from sample t
  ),
  rates as (
    select r.client_id, r.kind, count(*)::integer as answers, (count(*) filter (where r.confirmed))::integer as confirmed,
      (select array_agg(distinct x) from ranked q cross join unnest(q.compartments) as x
       where q.client_id = r.client_id and q.kind = r.kind and q.n <= 50) as compartments
    from ranked r
    where r.n <= 50
    group by r.client_id, r.kind
  ),
  kept as (
    select g.client_id, g.kind, r.evidence_id, r.compartments from grants g
    join knowledge.claim_releases r on r.ruling_id = g.id and r.via = 'grant'
    cross join since s
    where r.created_at > s.at and r.created_at <= p_at and r.created_at > p_at - interval '60 days'
      and (p_clearance is null or (r.compartments <@ p_clearance and policy.label_key(r.compartments) = any (p_keys)))
      and exists (select 1 from records w where w.evidence_id = r.evidence_id)
  ),
  not_true as (
    select distinct p.client_id, p.kind, o.id from decisions o
    join claims k on k.id = o.details ->> 'claim'
    join kept p on p.evidence_id = k.evidence_id
    where o.kind = 'correction' and not exists (select 1 from edits e where e.request_id = o.request_id)
  ),
  pairs as (
    select q.client_id, q.kind from rates q union select g.client_id, g.kind from grants g
  )
  select p.client_id, p.kind,
    exists (select 1 from grants g where g.client_id = p.client_id and g.kind = p.kind),
    coalesce(q.answers, 0), coalesce(q.confirmed, 0),
    (select count(distinct m.evidence_id)::integer from kept m where m.client_id = p.client_id and m.kind = p.kind),
    (select count(*)::integer from not_true t where t.client_id = p.client_id and t.kind = p.kind),
    (select array_agg(distinct x order by x) from (
       select unnest(q.compartments) as x
       union select unnest(m.compartments) from kept m where m.client_id = p.client_id and m.kind = p.kind) u)
  from pairs p left join rates q on q.client_id = p.client_id and q.kind = p.kind
  order by p.client_id, p.kind
$$;

CREATE FUNCTION policy.confirmed_claims(claim_keys text[]) RETURNS SETOF text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_reader boolean := session_user = 'pi_reader';
  v_restricted boolean := session_user = 'pi_restricted';
  v_clearance text[];
  v_keys text[];
begin
  if coalesce(cardinality(claim_keys), 0) > 1000 then
    raise exception 'too many keys' using errcode = '22023';
  end if;
  if v_reader then
    v_clearance := policy.client_clearance();
    v_keys := policy.clearance_keys();
  end if;
  return query
    select distinct k.key
    from unnest(confirmed_claims.claim_keys) as k (key)
    where exists (
      select 1
      from ledger.cards c
      join knowledge.owner_decisions o on o.card_id = c.id
      where c.kind in ('agent_claim', 'about_you') and c.created_by = 'system:extract' and c.request_id = k.key
        and (not v_reader or (c.compartments <@ v_clearance and policy.label_key(c.compartments) = any (v_keys)))
        and (not v_restricted or policy.is_restricted(c.compartments))
        and o.kind = 'answer' and o.answer = 'confirm' and o.tainted_at is null
        and not exists (select 1 from knowledge.owner_decisions s where s.supersedes = o.id)
        and not exists (select 1 from ledger.card_relays y where y.ruling_id = o.id)
        and not exists (select 1 from ledger.restatement_checks r
                        where r.claim_key = k.key and r.answer in ('echo', 'stale') and r.cleared_at is null
                          and o.decided_at >= r.checked_at))
    order by 1;
end
$$;

CREATE FUNCTION policy.confirmed_preferences() RETURNS TABLE(record_id text, evidence_id text, confirmed_at timestamp with time zone, compartments text[], body_enc jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  caller text;
  caller_views text[];
  clearance text[];
begin
  select c.id, c.views into caller, caller_views from policy.current_client() c;
  if caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  clearance := policy.client_clearance();
  return query
    select w.id, w.evidence_id, x.at, w.compartments, w.body_enc
    from ledger.agent_writes w
    cross join lateral (
      select max(o.decided_at) as at
      from ledger.cards c
      join knowledge.owner_decisions o on o.card_id = c.id
      where c.kind = 'client_preference' and c.created_by = 'system:extract'
        and c.target_kind = 'agent_record' and c.target_id = w.id and c.tainted_at is null
        and o.kind = 'answer' and o.answer = 'confirm' and o.tainted_at is null
        and not exists (select 1 from knowledge.owner_decisions s where s.supersedes = o.id)
    ) x
    where w.client_id = caller and w.kind = 'proposal' and w.proposal_scope = 'this_client'
      and w.body_enc is not null and w.flagged_at is null
      and w.compartments <@ clearance and w.writer_views <@ caller_views
      and x.at is not null
    order by x.at desc, w.id collate "C"
    limit 20;
end
$$;

CREATE FUNCTION policy.current_client() RETURNS TABLE(id text, name text, compartments text[], views text[], tools text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select c.id, c.name, c.compartments, c.views, c.tools
  from policy.clients c
  where c.status = 'active' and c.expires_at > now()
    and c.token_hash = encode(sha256(convert_to(nullif(current_setting('pi.client_token', true), ''), 'UTF8')), 'hex')
  union all
  select c.id, c.name, c.compartments, c.views, c.tools
  from policy.oauth_tokens t join policy.clients c on c.id = t.client_id
  where t.token_hash = encode(sha256(convert_to(nullif(current_setting('pi.client_token', true), ''), 'UTF8')), 'hex')
    and t.kind = 'access' and t.revoked_at is null and t.expires_at > now()
    and c.status = 'active'
$$;

CREATE FUNCTION policy.current_client_kind() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select k.kind from policy.clients k join policy.current_client() c on c.id = k.id
$$;

CREATE FUNCTION policy.current_id_mode() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select k.id_mode from policy.clients k join policy.current_client() c on c.id = k.id
$$;

CREATE FUNCTION policy.current_roles() RETURNS TABLE(mine text[], all_roles text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce((select k.roles from policy.clients k join policy.current_client() c on c.id = k.id and k.kind = 'agent'), '{}'::text[]),
         coalesce((select array_agg(distinct one order by one) from policy.clients k cross join lateral unnest(k.roles) as one
                   where k.status = 'active' and k.kind = 'agent'
                     and exists (select 1 from policy.current_client() c)), '{}'::text[])
$$;

CREATE FUNCTION policy.declined_goal_proposals(p_limit integer) RETURNS TABLE(id text, change text, at timestamp with time zone, code text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_views text[];
  v_tools text[];
  v_clearance text[];
  v_keys text[];
begin
  select c.id, c.views, c.tools into v_caller, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('get_suggestions' = any (v_tools)) or not ('work' = any (v_views)) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if declined_goal_proposals.p_limit is null or declined_goal_proposals.p_limit < 1 or declined_goal_proposals.p_limit > 51 then
    raise exception 'invalid argument' using errcode = '22023';
  end if;
  v_keys := policy.clearance_keys();
  v_clearance := policy.client_clearance();
  return query
    select g.id, g.change, s.at, s.code
    from ledger.record_events s
    join ledger.goal_proposals g on g.id = s.row_id
    where s.row_kind = 'goal_proposal' and s.event = 'rejected' and s.by = 'owner'
      and g.created_by = 'client:' || v_caller and g.tainted_at is null
      and g.compartments <@ v_clearance and policy.label_key(g.compartments) = any (v_keys)
      and s.compartments <@ v_clearance and policy.label_key(s.compartments) = any (v_keys)
      and not exists (select 1 from ledger.record_events r where r.row_kind = 'goal_proposal' and r.row_id = g.id and r.id > s.id
        and r.compartments <@ v_clearance and policy.label_key(r.compartments) = any (v_keys))
    order by s.at desc, g.id collate "C" desc
    limit declined_goal_proposals.p_limit;
end;
$$;

CREATE FUNCTION policy.entity_withheld(entity_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select entity_withheld.entity_id = any (policy.withheld_entities())
$$;

CREATE FUNCTION policy.erasure_mark() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select greatest(coalesce(max(e.journal_seq), 0), coalesce(max(e.lift_seq), 0)) from knowledge.erasures e
  where e.touched is null or not exists (select 1 from policy.current_client()) or e.touched && policy.client_clearance()
$$;

CREATE FUNCTION policy.fact_answer(match_fp text, compartments text[]) RETURNS TABLE(settling_card text, settled_answer text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_card text;
  v_answer text;
  v_request text;
  v_evidence text;
  v_keys text[];
begin
  if fact_answer.match_fp is null or fact_answer.compartments is null then
    return;
  end if;
  select c.id into v_card
  from ledger.cards c
  where c.match_fp = fact_answer.match_fp and c.created_by = 'system:extract' and c.kind in ('about_you', 'agent_claim')
    and c.compartments <@ fact_answer.compartments and c.tainted_at is null
    and (select r.event from ledger.record_events r where r.row_kind = 'card' and r.row_id = c.id order by r.id desc limit 1) in ('pending', 'deferred')
  order by c.created_at, c.id collate "C"
  limit 1;
  if v_card is not null then
    return query select v_card, 'waiting'::text;
    return;
  end if;

  select c.id, o.answer, c.request_id, k.evidence_id into v_card, v_answer, v_request, v_evidence
  from ledger.cards c
  join knowledge.owner_decisions o on o.card_id = c.id and o.kind = 'answer' and o.tainted_at is null
    and not exists (select 1 from knowledge.owner_decisions s where s.supersedes = o.id)
  left join knowledge.claims k on k.id = c.target_id
  where c.match_fp = fact_answer.match_fp and c.created_by = 'system:extract' and c.kind in ('about_you', 'agent_claim')
    and c.compartments <@ fact_answer.compartments
    and exists (select 1 from ledger.record_events e where e.row_kind = 'card' and e.row_id = c.id and e.event = 'decided' and e.by = 'owner')
  order by o.decided_at desc, o.id collate "C" desc
  limit 1;
  if v_card is null then
    return;
  end if;

  select coalesce(array_agg(x.fp), '{}') into v_keys
  from knowledge.claims q cross join lateral unnest(array[q.fact_key_fp, q.legacy_fact_key_fp, q.legacy_alt_fact_key_fp]) as x (fp)
  where q.evidence_id = v_evidence and x.fp is not null;
  v_keys := v_keys || fact_answer.match_fp;
  if exists (select 1 from knowledge.belief_rulings b where b.verdict = 'retire' and b.lifted_at is null and b.fact_key_fp = any (v_keys)) then
    return;
  end if;
  if exists (select 1 from knowledge.belief_rulings b where b.verdict = 'veto' and b.lifted_at is null and b.fact_key_fp = any (v_keys)) then
    return query select v_card, 'vetoed'::text;
    return;
  end if;
  if v_answer = 'reject' then
    return query select v_card, 'rejected'::text;
    return;
  end if;
  if v_answer = 'confirm' and exists (select 1 from policy.confirmed_claims(array[v_request])) then
    return query select v_card, 'confirmed'::text;
  end if;
  return;
end
$$;

CREATE FUNCTION policy.fact_reclassifications() RETURNS TABLE(ruling_id text, verdict text, fact_key_fp text, created_at timestamp with time zone, compartments text[], value_enc jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select r.ruling_id, r.verdict, r.fact_key_fp, r.created_at, r.compartments, r.value_enc
  from knowledge.belief_rulings r
  where r.verdict in ('domain', 'kind') and r.lifted_at is null
  order by r.created_at, r.ruling_id collate "C"
$$;

CREATE FUNCTION policy.fact_retirements() RETURNS TABLE(ruling_id text, fact_key_fp text, created_at timestamp with time zone, compartments text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select r.ruling_id, r.fact_key_fp, r.created_at, r.compartments
  from knowledge.belief_rulings r
  where r.verdict = 'retire' and r.lifted_at is null
  order by r.created_at, r.ruling_id collate "C"
$$;

CREATE FUNCTION policy.fact_ruled(fact_fps text[], compartments text[]) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select case
    when exists (select 1 from knowledge.belief_rulings b
                 where b.fact_key_fp = any (fact_ruled.fact_fps) and b.lifted_at is null and b.verdict = 'veto'
                   and b.compartments <@ fact_ruled.compartments) then 'veto'
    when exists (select 1 from knowledge.belief_rulings b
                 where b.fact_key_fp = any (fact_ruled.fact_fps) and b.lifted_at is null and b.verdict = 'reject'
                   and b.compartments <@ fact_ruled.compartments) then 'reject'
  end
$$;

CREATE FUNCTION policy.fact_rulings() RETURNS TABLE(ruling_id text, verdict text, a_fp text, b_fp text, created_at timestamp with time zone, compartments text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select r.ruling_id, r.verdict, r.a_fp, r.b_fp, r.created_at, r.compartments
  from knowledge.fact_rulings r
  where r.lifted_at is null
  order by r.created_at, r.ruling_id collate "C"
$$;

CREATE FUNCTION policy.fact_vetoes() RETURNS TABLE(ruling_id text, fact_key_fp text, created_at timestamp with time zone, compartments text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select r.ruling_id, r.fact_key_fp, r.created_at, r.compartments
  from knowledge.belief_rulings r
  where r.verdict = 'veto' and r.lifted_at is null
  order by r.created_at, r.ruling_id collate "C"
$$;

CREATE FUNCTION policy.grant_release(evidence_id text, claim_type text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_ruling text;
  v_client text;
  v_label text[];
begin
  if grant_release.evidence_id is null or grant_release.claim_type is null then
    return null;
  end if;
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal release grants'));
  select r.ruling_id into v_ruling from policy.released_records() r where r.evidence_id = grant_release.evidence_id;
  if v_ruling is not null then
    return v_ruling;
  end if;
  select w.client_id, e.compartments into v_client, v_label
  from ledger.agent_writes w join vault.evidence_items e on e.id = w.evidence_id
  where w.evidence_id = grant_release.evidence_id and w.tool = 'propose_about_you' and w.kind = 'proposal' and w.flagged_at is null;
  if v_client is null
     or not ('own' = any (v_label))
     or not exists (select 1 from unnest(v_label) c where starts_with(c, 'agent:'))
     or exists (select 1 from unnest(v_label) c where c <> 'own' and not starts_with(c, 'agent:')) then
    return null;
  end if;
  select o.id into v_ruling
  from knowledge.owner_decisions o
  where o.kind = 'release_grant' and o.tainted_at is null
    and not exists (select 1 from knowledge.owner_decisions s where s.supersedes = o.id)
    and not exists (select 1 from knowledge.release_lifts l where l.ruling_id = o.id)
    and o.details ->> 'client' = v_client and o.details ->> 'kind' = grant_release.claim_type
  order by o.decided_at, o.id collate "C"
  limit 1;
  if v_ruling is null then
    return null;
  end if;
  if exists (select 1 from knowledge.claims k where k.evidence_id = grant_release.evidence_id and not k.released and k.type is distinct from grant_release.claim_type) then
    return null;
  end if;
  if exists (select 1 from knowledge.claims c join knowledge.belief_rulings b on b.fact_key_fp in (c.fact_key_fp, c.legacy_fact_key_fp, c.legacy_alt_fact_key_fp)
             where c.evidence_id = grant_release.evidence_id and b.verdict in ('veto', 'retire') and b.lifted_at is null) then
    return null;
  end if;
  if exists (select 1 from knowledge.claim_releases r where r.evidence_id = grant_release.evidence_id and r.lifted_at is null) then
    return null;
  end if;
  insert into knowledge.claim_releases (ruling_id, evidence_id, via, created_at, compartments)
  values (v_ruling, grant_release.evidence_id, 'grant', now(), array['own']::text[]);
  return v_ruling;
end
$$;

CREATE FUNCTION policy.granted_releases() RETURNS TABLE(evidence_id text, ruling_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select r.evidence_id, r.ruling_id
  from policy.released_records() r
  join knowledge.claim_releases c on c.ruling_id = r.ruling_id and c.evidence_id = r.evidence_id
  where c.via = 'grant' and c.lifted_at is null
  order by r.evidence_id collate "C"
$$;

CREATE FUNCTION policy.group_chat_newer(member_ids text[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_clearance text[];
  v_keys text[];
  v_built timestamptz;
begin
  select c.id into v_caller from policy.current_client() c;
  if v_caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  if group_chat_newer.member_ids is null or cardinality(group_chat_newer.member_ids) > 500 then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  v_clearance := policy.client_clearance();
  v_keys := policy.clearance_keys();
  select max(b.built_at) into v_built
  from projections.warmth_day_builds b
  where b.compartments <@ v_clearance and policy.label_key(b.compartments) = any (v_keys) and b.removed_at is null;
  if v_built is null then
    return false;
  end if;
  return exists (
    select 1 from knowledge.chat_lines l
    where policy.label_key(l.compartments) = any (v_keys) and l.compartments <@ v_clearance
      and l.entity_id = any (group_chat_newer.member_ids) and l.created_at > v_built);
end
$$;

CREATE FUNCTION policy.ignored_people_in(p_clearance text[]) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with live as (select r.subject, r.value_fps, r.address_fps from knowledge.ignore_rulings r where r.lifted_at is null)
  select coalesce(array_agg(distinct w.entity_id), '{}'::text[]) from (
    select a.entity_id from live r, unnest(r.value_fps) as f (fp), knowledge.accounts a
    where r.subject = 'address' and a.value_fp = f.fp and a.compartments <@ p_clearance
    union
    select a.entity_id from live r, unnest(r.value_fps) as f (fp), knowledge.accounts a
    where r.subject = 'domain' and a.domain_fp = f.fp and a.compartments <@ p_clearance
    union
    select a.entity_id from live r, unnest(r.address_fps) as f (fp), knowledge.accounts a
    where r.subject = 'domain' and a.value_fp = f.fp and a.compartments <@ p_clearance) w
  join knowledge.entities e on e.id = w.entity_id and e.kind = 'person'
$$;

CREATE FUNCTION policy.import_memory(session_id text, changes jsonb, compartments text[]) RETURNS TABLE(outcome text, received integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  caller text;
  caller_name text;
  caller_views text[];
  caller_tools text[];
  total integer;
  fresh integer;
  gone boolean;
  item jsonb;
  matched_ids text[];
  any_tainted boolean;
  any_live boolean;
  item_mark text;
  stored_id text;
  envelope jsonb;
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'an append runs read committed' using errcode = '42501';
  end if;
  select c.id, c.name, c.views, c.tools into caller, caller_name, caller_views, caller_tools from policy.current_client() c;
  if caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  if not ('import_memory' = any (caller_tools)) then
    raise exception 'not this client''s tool' using errcode = '42501';
  end if;
  if not exists (select 1 from ledger.sessions s where s.id = import_memory.session_id and s.client_id = caller) then
    raise exception 'not this client''s session' using errcode = '42501';
  end if;

  if import_memory.changes is null or jsonb_typeof(import_memory.changes) <> 'array' or jsonb_array_length(import_memory.changes) not between 1 and 50 then
    raise exception 'import_memory_changes' using errcode = '23514', constraint = 'import_memory_changes';
  end if;
  total := jsonb_array_length(import_memory.changes);
  if exists (select 1 from jsonb_array_elements(import_memory.changes) e where jsonb_typeof(e) <> 'object') then
    raise exception 'import_memory_changes' using errcode = '23514', constraint = 'import_memory_changes';
  end if;
  if exists (
    select 1 from jsonb_array_elements(import_memory.changes) e
    where case
      when e ->> 'change' = 'added' then
        not (e ?& array['request_id', 'locator_fp', 'change', 'entry_time', 'stamps', 'line_fps', 'record_id', 'content_fp', 'cites_fp', 'body_enc']
             and (e - array['request_id', 'locator_fp', 'change', 'entry_time', 'stamps', 'line_fps', 'record_id', 'content_fp', 'cites_fp', 'body_enc']) = '{}'::jsonb)
        or jsonb_typeof(e -> 'record_id') <> 'string' or e ->> 'record_id' !~ '^rec_[0-9A-HJKMNP-TV-Z]{26}$'
        or jsonb_typeof(e -> 'content_fp') <> 'string' or e ->> 'content_fp' !~ '^[0-9a-f]{64}$'
        or jsonb_typeof(e -> 'cites_fp') <> 'string' or e ->> 'cites_fp' !~ '^[0-9a-f]{64}$'
      when e ->> 'change' = 'removed' then
        not (e ?& array['request_id', 'locator_fp', 'change', 'entry_time', 'stamps', 'line_fps']
             and (e - array['request_id', 'locator_fp', 'change', 'entry_time', 'stamps', 'line_fps']) = '{}'::jsonb)
        or e -> 'stamps' <> '[]'::jsonb or e -> 'line_fps' <> '[]'::jsonb
      else true
    end) then
    raise exception 'import_memory_changes' using errcode = '23514', constraint = 'import_memory_changes';
  end if;
  if exists (
    select 1 from jsonb_array_elements(import_memory.changes) e
    where jsonb_typeof(e -> 'request_id') <> 'string' or e ->> 'request_id' !~ '^[A-Za-z0-9_-]{8,64}$'
       or jsonb_typeof(e -> 'locator_fp') <> 'string' or e ->> 'locator_fp' !~ '^[0-9a-f]{64}$'
       or jsonb_typeof(e -> 'entry_time') not in ('string', 'null')
       or (jsonb_typeof(e -> 'entry_time') = 'string'
           and e ->> 'entry_time' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]{1,9})?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$')
       or jsonb_typeof(e -> 'stamps') <> 'array' or jsonb_array_length(e -> 'stamps') > 100
       or jsonb_typeof(e -> 'line_fps') <> 'array' or jsonb_array_length(e -> 'line_fps') > 1000) then
    raise exception 'import_memory_changes' using errcode = '23514', constraint = 'import_memory_changes';
  end if;
  if exists (
    select 1 from jsonb_array_elements(import_memory.changes) e, jsonb_array_elements(e -> 'stamps') s
    where jsonb_typeof(s) <> 'string' or s #>> '{}' !~ '^mpr_[0-9a-f]{40}$') then
    raise exception 'import_memory_changes' using errcode = '23514', constraint = 'import_memory_changes';
  end if;
  if exists (
    select 1 from jsonb_array_elements(import_memory.changes) e, jsonb_array_elements(e -> 'line_fps') f
    where jsonb_typeof(f) <> 'string' or f #>> '{}' !~ '^[0-9a-f]{64}$') then
    raise exception 'import_memory_changes' using errcode = '23514', constraint = 'import_memory_changes';
  end if;
  if (select count(distinct e ->> 'request_id') from jsonb_array_elements(import_memory.changes) e) <> total
     or (select count(distinct e ->> 'record_id') from jsonb_array_elements(import_memory.changes) e where e ->> 'change' = 'added')
        <> (select count(*) from jsonb_array_elements(import_memory.changes) e where e ->> 'change' = 'added') then
    raise exception 'import_memory_changes' using errcode = '23514', constraint = 'import_memory_changes';
  end if;
  perform (e ->> 'entry_time')::timestamptz from jsonb_array_elements(import_memory.changes) e where e ->> 'entry_time' is not null;

  insert into policy.record_quota as q (client_id) values (caller)
  on conflict (client_id) do update set attempts = q.attempts + 1, updated_at = now();
  select count(*) into fresh from jsonb_array_elements(import_memory.changes) e
  where not exists (select 1 from ledger.memory_imports m where m.client_id = caller and m.request_id = e ->> 'request_id')
    and not exists (select 1 from ledger.agent_writes w where w.client_id = caller and w.request_id = e ->> 'request_id');
  if (select count(*) from ledger.memory_imports m where m.client_id = caller and m.created_at > now() - interval '24 hours') + fresh > 500 then
    return query select 'rate_limited'::text, null::integer;
    return;
  end if;
  if import_memory.compartments is distinct from policy.record_label() then
    return query select 'label_mismatch'::text, null::integer;
    return;
  end if;
  for envelope in select e -> 'body_enc' from jsonb_array_elements(import_memory.changes) e where e ->> 'change' = 'added' loop
    if not (jsonb_typeof(envelope) = 'object' and envelope ?& array['v', 'nonce', 'ciphertext', 'tag'] and (envelope - array['v', 'nonce', 'ciphertext', 'tag']) = '{}'::jsonb
        and envelope -> 'v' = '1'::jsonb and jsonb_typeof(envelope -> 'nonce') = 'string' and jsonb_typeof(envelope -> 'ciphertext') = 'string' and jsonb_typeof(envelope -> 'tag') = 'string'
        and envelope ->> 'nonce' <> '' and envelope ->> 'tag' <> '' and envelope ->> 'nonce' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' and envelope ->> 'ciphertext' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' and envelope ->> 'tag' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$'
        and octet_length(envelope::text) <= 65536) then
      return query select 'body_refused'::text, null::integer;
      return;
    end if;
  end loop;

  gone := exists (
    select 1 from ledger.read_log r cross join unnest(r.bound) as b (id)
    where r.session_id = import_memory.session_id
      and not exists (select 1 from vault.evidence_items e where e.id = b.id));

  for item in select t.e from jsonb_array_elements(import_memory.changes) with ordinality as t (e, n) order by t.n loop
    continue when exists (select 1 from ledger.memory_imports m where m.client_id = caller and m.request_id = item ->> 'request_id')
               or exists (select 1 from ledger.agent_writes w where w.client_id = caller and w.request_id = item ->> 'request_id');
    select coalesce(array_agg(p.id order by p.id collate "C"), '{}'::text[]),
           coalesce(bool_or(p.tainted_at is not null), false),
           coalesce(bool_or(p.ended_at is null), false)
    into matched_ids, any_tainted, any_live
    from ledger.memory_projections p
    where p.client_id = caller
      and (p.id in (select jsonb_array_elements_text(item -> 'stamps'))
           or p.line_fp in (select jsonb_array_elements_text(item -> 'line_fps')));
    item_mark := case
      when any_tainted or gone then 'refused'
      when any_live then 'echo'
      when cardinality(matched_ids) > 0 then 'stale'
      else 'new'
    end;
    stored_id := null;
    if item ->> 'change' = 'added' and item_mark <> 'refused' then
      insert into ledger.agent_writes (id, client_id, client_name, session_id, request_id, tool, kind, compartments, writer_views, content_fp, cites_fp, cites, body_enc)
      values (item ->> 'record_id', caller, caller_name, import_memory.session_id, item ->> 'request_id', 'import_memory', 'memory_change',
              policy.record_label(), caller_views, item ->> 'content_fp', item ->> 'cites_fp', '{}'::text[], item -> 'body_enc');
      stored_id := item ->> 'record_id';
    end if;
    insert into ledger.memory_imports (client_id, request_id, record_id, locator_fp, change, mark, matched_projection_ids, entry_time, created_at, compartments)
    values (caller, item ->> 'request_id', stored_id, item ->> 'locator_fp', item ->> 'change', item_mark, matched_ids,
            case when item ->> 'entry_time' is null then null else least((item ->> 'entry_time')::timestamptz, now()) end, now(), policy.record_label());
  end loop;
  return query select 'ok'::text, total;
end
$_$;

CREATE FUNCTION policy.is_restricted(compartments text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select exists (select 1 from pg_catalog.unnest(compartments) c where pg_catalog.starts_with(c, 'restricted:'))
$$;

CREATE FUNCTION policy.journal_mark() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select greatest(
    policy.erasure_mark(),
    (select coalesce(max(greatest(s.journal_seq, coalesce(s.lift_seq, 0))), 0) from knowledge.seals s
     where not exists (select 1 from policy.current_client()) or s.compartments <@ policy.client_clearance()),
    (select coalesce(max(r.journal_seq), 0) from policy.retention_rules r
     where not exists (select 1 from policy.current_client()) or r.compartments <@ policy.client_clearance()),
    (select coalesce(max(l.seq), 0) from knowledge.release_lifts l
     where not exists (select 1 from policy.current_client()) or l.compartments <@ policy.client_clearance()))
$$;

CREATE FUNCTION policy.known_identities() RETURNS TABLE(source text, id text, value_enc jsonb, compartments text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select 'alias', a.id, a.value_enc, a.compartments from knowledge.aliases a
  join knowledge.entities e on e.id = a.entity_id and e.kind in ('person', 'owner')
  where not policy.is_restricted(a.compartments)
  union all
  select 'account', c.id, c.value_enc, c.compartments from knowledge.accounts c
  join knowledge.entities e on e.id = c.entity_id and e.kind in ('person', 'owner')
  where c.kind = 'email' and not policy.is_restricted(c.compartments)
  order by 1, 2
$$;

CREATE FUNCTION policy.label_key(compartments text[]) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select string_agg(distinct one collate "C", '|' order by one collate "C") from unnest(label_key.compartments) as one
$$;

CREATE FUNCTION policy.labels_missing(keys text[]) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select count(distinct k)::integer from unnest(labels_missing.keys) k
  where k is not null and k <> '' and not exists (select 1 from policy.labels l where l.key = k)
$$;

CREATE FUNCTION policy.lens_vouch_once() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if old.backfill_vouched_at is not null
     and (new.backfill_vouch_from is distinct from old.backfill_vouch_from
          or new.backfill_vouch_to is distinct from old.backfill_vouch_to
          or new.backfill_vouched_at is distinct from old.backfill_vouched_at) then
    raise exception 'a backfill is vouched once' using errcode = '23514';
  end if;
  return new;
end
$$;

CREATE FUNCTION policy.levers_read() RETURNS TABLE(key text, value jsonb, set_by text, old_value jsonb, new_value jsonb, reason text, changed_at timestamp with time zone, changed_by text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_me text;
begin
  select 'client:' || r.client_id into v_me from ledger.agent_mail_reader('list_levers') r;
  return query
  select k.key, s.value,
    case when s.updated_by is null then null when s.updated_by = 'owner' then 'owner' when s.updated_by = v_me then 'you' else 'agent' end,
    c.old_value, c.new_value, c.reason, c.at,
    case when c.changed_by is null then null when c.changed_by = 'owner' then 'owner' when c.changed_by = v_me then 'you' else 'agent' end
  from (select a.key from policy.settings a union select b.key from policy.setting_changes b) k
  left join policy.settings s on s.key = k.key
  left join lateral (select h.id, h.old_value, h.new_value, h.reason, h.at, h.changed_by from policy.setting_changes h
                     where h.key = k.key order by h.id desc limit 1) c on true
  order by k.key collate "C"
  limit 500;
end
$$;

CREATE FUNCTION policy.live_corrections(p_ids text[]) RETURNS TABLE(root text, id text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_views text[];
  v_clearance text[];
  v_keys text[];
  v_view_keys text[];
begin
  select c.id, c.views into v_caller, v_views from policy.current_client() c;
  if v_caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  v_clearance := policy.client_clearance();
  v_view_keys := policy.view_keys();
  return query
    with recursive visible as not materialized (
      select w.id, w.created_at, w.supersedes, w.body_enc is not null as live
      from ledger.agent_writes w
      where w.supersedes is not null
        and w.compartments <@ v_clearance and policy.label_key(w.compartments) = any (v_keys)
        and w.writer_views <@ v_views and policy.label_key(w.writer_views) = any (v_view_keys)
        and w.flagged_at is null
    ),
    later (root, id, created_at, live) as (
      select v.supersedes, v.id, v.created_at, v.live from visible v where v.supersedes = any (live_corrections.p_ids)
      union
      select l.root, v.id, v.created_at, v.live from later l join visible v on v.supersedes = l.id
    )
    select l.root, l.id, l.created_at from later l where l.live;
end
$$;

CREATE FUNCTION policy.log_call(tool text, row_count integer, outcome text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  caller text;
begin
  select c.id into caller from policy.current_client() c;
  if caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  insert into policy.calls (client_id, tool, rows, outcome)
  values (caller, log_call.tool, log_call.row_count, log_call.outcome);
end
$$;

