  insert into policy.calls (client_id, tool, rows, outcome, chars)
  values (caller, log_call.tool, log_call.row_count, log_call.outcome, log_call.chars);
end
$$;

CREATE FUNCTION policy.log_call(tool text, row_count integer, outcome text, reason text, field text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  caller text;
begin
  select c.id into caller from policy.current_client() c;
  if caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  insert into policy.calls (client_id, tool, rows, outcome, reason, field)
