CREATE FUNCTION policy.log_pack(session_id text, purpose text, template text, selector text, pack_fp text, item_ids text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  caller text;
  clearance text[];
  held text[];
begin
  select c.id, c.compartments, c.tools into caller, clearance, held from policy.current_client() c;
  if caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  if not exists (select 1 from ledger.sessions s where s.id = log_pack.session_id and s.client_id = caller) then
    raise exception 'not this client''s session' using errcode = '42501';
  end if;
  if not ('build_context_pack' = any (held)) then
    raise exception 'not this client''s tool' using errcode = '42501';
  end if;
  insert into ledger.context_packs (client_id, session_id, purpose, template, selector, pack_fp, item_ids, compartments)
  values (caller, log_pack.session_id, log_pack.purpose, log_pack.template, log_pack.selector, log_pack.pack_fp, log_pack.item_ids, clearance);
end
$$;

CREATE FUNCTION policy.log_read(session_id text, tool text, bound text[], shown text[], fact_key_fps text[], goals text[] DEFAULT '{}'::text[], lessons text[] DEFAULT '{}'::text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  caller text;
  clearance text[];
  held text[];
begin
  select c.id, c.compartments, c.tools into caller, clearance, held from policy.current_client() c;
  if caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  if not exists (select 1 from ledger.sessions s where s.id = log_read.session_id and s.client_id = caller) then
    raise exception 'not this client''s session' using errcode = '42501';
  end if;
  if log_read.tool is null or not (log_read.tool = any (held)) then
    raise exception 'not this client''s tool' using errcode = '42501';
  end if;
  insert into ledger.read_log (session_id, client_id, tool, compartments, bound, shown, fact_key_fps, goals, lessons)
  values (log_read.session_id, caller, log_read.tool, clearance, log_read.bound, log_read.shown, log_read.fact_key_fps, log_read.goals, log_read.lessons);
end
$$;

CREATE FUNCTION policy.mirror_cursor(session_id text, cursor_id text) RETURNS TABLE(standing text, pass integer, rebuild boolean, section text, after_key text, completed_at timestamp with time zone, rebuilt_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_tools text[];
  v_latest ledger.mirror_cursors%rowtype;
  v_at ledger.mirror_cursors%rowtype;
  v_standing text;
begin
  select c.id, c.tools into v_caller, v_tools from policy.current_client() c;
  if v_caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  if not ('sync_mirror' = any (v_tools)) then
    raise exception 'not this client''s tool' using errcode = '42501';
  end if;
  if mirror_cursor.session_id is null
     or not exists (select 1 from ledger.sessions s where s.id = mirror_cursor.session_id and s.client_id = v_caller) then
    raise exception 'not this client''s session' using errcode = '42501';
  end if;
  if mirror_cursor.cursor_id is not null and mirror_cursor.cursor_id !~ '^mcr_[0-9A-HJKMNP-TV-Z]{26}$' then
    raise exception 'mirror_cursor_cursor_id' using errcode = '23514', constraint = 'mirror_cursor_cursor_id';
  end if;
  if mirror_cursor.cursor_id is null then
    return query select 'none'::text, null::integer, null::boolean, null::text, null::text, null::timestamptz, null::timestamptz;
    return;
  end if;
  select c.* into v_latest from ledger.mirror_cursors c
  where c.client_id = v_caller and not exists (select 1 from ledger.mirror_cursors d where d.client_id = v_caller and d.prior_id = c.id)
  limit 1;
  if v_latest.id = mirror_cursor.cursor_id then
    v_standing := 'latest';
    v_at := v_latest;
  elsif v_latest.prior_id = mirror_cursor.cursor_id then
    select c.* into v_at from ledger.mirror_cursors c where c.client_id = v_caller and c.id = mirror_cursor.cursor_id;
    if found then
      v_standing := 'prior';
    end if;
  end if;
  if v_standing is null then
    return query select 'stale'::text, null::integer, null::boolean, null::text, null::text, null::timestamptz, null::timestamptz;
    return;
  end if;
  return query select v_standing, v_at.pass, v_at.rebuild, v_at.section, v_at.after_key, v_at.completed_at, v_at.rebuilt_at;
end
$_$;

CREATE FUNCTION policy.mirror_tokens(session_id text, template text, section text, after_key text, last_key text) RETURNS TABLE(entry_key text, confirmed_token text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_tools text[];
  v_audience text[];
  v_form text;
begin
  select c.id, c.compartments, c.tools into v_caller, v_clearance, v_tools from policy.current_client() c;
  if v_caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  if not ('sync_mirror' = any (v_tools)) then
    raise exception 'not this client''s tool' using errcode = '42501';
  end if;
  if mirror_tokens.session_id is null
     or not exists (select 1 from ledger.sessions s where s.id = mirror_tokens.session_id and s.client_id = v_caller) then
    raise exception 'not this client''s session' using errcode = '42501';
  end if;
  if mirror_tokens.template is null or mirror_tokens.template !~ '^lens_mirror@[1-9][0-9]{0,3}$' then
    raise exception 'mirror_tokens_template' using errcode = '23514', constraint = 'mirror_tokens_template';
  end if;
  if mirror_tokens.section is null or mirror_tokens.section not in ('entities', 'beliefs', 'facts', 'events', 'captures') then
    raise exception 'mirror_tokens_section' using errcode = '23514', constraint = 'mirror_tokens_section';
  end if;
  v_form := case mirror_tokens.section
    when 'entities' then '^ent_[0-9A-HJKMNP-TV-Z]{26}$'
    when 'beliefs' then '^blf_[0-9a-f]{40}$'
    when 'facts' then '^[0-9a-f]{64}:[0-9a-f]{64}$'
    when 'events' then '^evt_[0-9A-HJKMNP-TV-Z]{26}$'
    else '^cap_[0-9A-HJKMNP-TV-Z]{26}$'
  end;
  if mirror_tokens.after_key is not null and mirror_tokens.after_key !~ v_form then
    raise exception 'mirror_tokens_after_key' using errcode = '23514', constraint = 'mirror_tokens_after_key';
  end if;
  if mirror_tokens.last_key is not null and mirror_tokens.last_key !~ v_form then
    raise exception 'mirror_tokens_last_key' using errcode = '23514', constraint = 'mirror_tokens_last_key';
  end if;
  v_audience := (select array_agg(d.x order by d.x collate "C") from (select distinct u.x from unnest(v_clearance) as u (x)) d);
  return query
    select m.entry_key, m.confirmed_token from ledger.mirror_entries m
    where m.client_id = v_caller and m.ended_at is null and m.audience = v_audience and m.template = mirror_tokens.template
      and m.section = mirror_tokens.section and m.confirmed_token is not null
      and (mirror_tokens.after_key is null or m.entry_key > (mirror_tokens.after_key collate "C"))
      and (mirror_tokens.last_key is null or m.entry_key <= (mirror_tokens.last_key collate "C"))
    order by m.entry_key collate "C";
end
$_$;

CREATE FUNCTION policy.moment_handle_names(p_evidence text, p_keys text[], p_names text[]) RETURNS TABLE(ordinal integer, alias_id text, value_enc jsonb, compartments text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with moment as (
    select c.compartments from knowledge.captures c
    where c.evidence_id = p_evidence and c.kind = 'moment' and c.source is not null
      and cardinality(p_keys) = cardinality(p_names) and cardinality(p_keys) <= 50
  ),
  handles as (select k.n::integer as n, k.fp as key_fp, p_names[k.n] as name_fp from unnest(p_keys) with ordinality as k (fp, n)),
  keyed as (
    select h.n, (array_agg(distinct a.entity_id))[1] as entity_id, count(distinct a.entity_id) as people
    from handles h cross join moment m
    join knowledge.accounts a on a.value_fp = h.key_fp and a.compartments <@ m.compartments
    join knowledge.entities e on e.id = a.entity_id and e.kind = 'person'
    group by h.n
  ),
  bound as (
    select h.n, (array_agg(distinct a.entity_id))[1] as entity_id, count(distinct a.entity_id) as people
    from handles h cross join moment m
    join knowledge.mention_bindings b on b.evidence_id = p_evidence and b.mention_fp = h.name_fp and b.lifted_at is null
    join knowledge.accounts a on a.value_fp = b.address_fp and a.compartments <@ m.compartments
    join knowledge.entities e on e.id = a.entity_id and e.kind = 'person'
    where not exists (select 1 from keyed k where k.n = h.n and k.people = 1)
    group by h.n
  ),
  resolved as (
    select n, entity_id from keyed where people = 1
    union all select n, entity_id from bound where people = 1
  )
  select r.n, l.id, l.value_enc, l.compartments
  from resolved r cross join moment m
  cross join lateral (
    select s.id, s.value_enc, s.compartments from knowledge.aliases s
    left join knowledge.contacts c on c.evidence_id = s.evidence_id
    left join vault.source_accounts a on a.id = c.account_id
    where s.entity_id = r.entity_id and s.compartments <@ m.compartments
    order by coalesce(a.connector = 'lens_contacts', false), c.updated_at desc nulls last, s.id collate "C"
    limit 1
  ) l
  order by r.n
$$;

CREATE FUNCTION policy.my_confirm_rates(p_at timestamp with time zone) RETURNS TABLE(kind text, granted boolean, answers integer, confirmed integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select r.kind, r.granted, r.answers, r.confirmed
  from policy.current_client() c
  cross join lateral policy.confirm_rates_within(p_at, policy.client_clearance(), policy.clearance_keys()) r
  where r.client_id = c.id
    and coalesce((select (o.details ->> 'on')::boolean from knowledge.owner_decisions o
                  where o.kind = 'learning_switch' and o.tainted_at is null and o.details ->> 'client' = c.id
                  order by o.decided_at desc, o.id desc limit 1), true)
  order by r.kind
$$;

CREATE FUNCTION policy.named_fps(p_evidence text, p_fps text[]) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select coalesce(array_agg(distinct a.value_fp order by a.value_fp), '{}'::text[])
  from knowledge.captures c
  join knowledge.aliases a on a.value_fp = any (p_fps) and a.compartments <@ c.compartments
  join knowledge.entities e on e.id = a.entity_id and e.kind in ('person', 'owner')
  where c.evidence_id = p_evidence and c.kind = 'block' and cardinality(p_fps) <= 20000
$$;

CREATE FUNCTION policy.note_labels() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_keys text[];
  v_key text;
begin
  if tg_level = 'ROW' then
    v_keys := array[policy.label_key(new.compartments)];
  else
    select array_agg(distinct policy.label_key(n.compartments)) into v_keys from new_rows n;
  end if;
  select array_agg(k order by k collate "C") into v_keys from unnest(v_keys) k
  where k is not null and k <> '' and not exists (select 1 from policy.labels l where l.key = k);
  if v_keys is null then
    return null;
  end if;
  foreach v_key in array v_keys loop
    begin
      insert into policy.labels (key, compartments) values (v_key, string_to_array(v_key, '|'))
      on conflict do nothing;
    exception when serialization_failure then
      null;
    end;
  end loop;
  return null;
end
$$;

CREATE FUNCTION policy.oauth_authorize(p_registration text, p_approval_hash text, p_code_hash text, p_redirect_uri text, p_challenge text, p_resource text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_client text;
begin
  select a.client_id into v_client
  from policy.oauth_approvals a join policy.clients c on c.id = a.client_id
  where a.code_hash = p_approval_hash and a.used_at is null and a.expires_at > now() and c.status = 'active'
    and a.registration = p_registration
    and c.kind <> 'device'
    and not exists (select 1 from policy.lens_devices d where c.id in (d.capture_client_id, d.mirror_client_id))
  for update of a;
  if v_client is null then
    return false;
  end if;
  update policy.oauth_registrations set client_id = v_client, bound_at = now() where id = p_registration;
  if not found then
    return false;
  end if;
  update policy.oauth_approvals set used_at = now() where code_hash = p_approval_hash;
  insert into policy.oauth_codes (code_hash, registration, client_id, redirect_uri, challenge, resource)
  values (p_code_hash, p_registration, v_client, p_redirect_uri, p_challenge, p_resource);
  delete from policy.oauth_codes where expires_at < now() - interval '1 day';
  delete from policy.oauth_tokens where expires_at < now() - interval '1 day';
  return true;
end
$$;

CREATE FUNCTION policy.oauth_exchange(p_registration text, p_code_hash text, p_challenge text, p_redirect_uri text, p_resource text, p_access_hash text, p_refresh_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_code policy.oauth_codes%rowtype;
begin
  select * into v_code from policy.oauth_codes where code_hash = p_code_hash for update;
  if not found then
    return false;
  end if;
  if v_code.used_at is not null then
    update policy.oauth_tokens set revoked_at = now() where family = v_code.family and revoked_at is null;
    return false;
  end if;
  update policy.oauth_codes set used_at = now() where code_hash = p_code_hash;
  if v_code.registration <> p_registration or v_code.redirect_uri <> p_redirect_uri or v_code.challenge <> p_challenge
     or v_code.expires_at <= now() or (p_resource is not null and v_code.resource is not null and p_resource <> v_code.resource)
     or not exists (select 1 from policy.clients c where c.id = v_code.client_id and c.status = 'active') then
    return false;
  end if;
  insert into policy.oauth_tokens (token_hash, kind, family, registration, client_id, expires_at) values
    (p_access_hash, 'access', v_code.family, v_code.registration, v_code.client_id, now() + interval '1 hour'),
    (p_refresh_hash, 'refresh', v_code.family, v_code.registration, v_code.client_id, now() + interval '30 days');
  return true;
end
$$;

CREATE FUNCTION policy.oauth_refresh(p_registration text, p_refresh_hash text, p_access_hash text, p_next_refresh_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_token policy.oauth_tokens%rowtype;
begin
  select * into v_token from policy.oauth_tokens where token_hash = p_refresh_hash and kind = 'refresh' for update;
  if not found then
    return false;
  end if;
  if v_token.used_at is not null or v_token.revoked_at is not null or v_token.registration <> p_registration then
    update policy.oauth_tokens set revoked_at = now() where family = v_token.family and revoked_at is null;
    return false;
  end if;
  if v_token.expires_at <= now() or not exists (select 1 from policy.clients c where c.id = v_token.client_id and c.status = 'active') then
    return false;
  end if;
  update policy.oauth_tokens set used_at = now() where token_hash = p_refresh_hash;
  insert into policy.oauth_tokens (token_hash, kind, family, registration, client_id, expires_at) values
    (p_access_hash, 'access', v_token.family, v_token.registration, v_token.client_id, now() + interval '1 hour'),
    (p_next_refresh_hash, 'refresh', v_token.family, v_token.registration, v_token.client_id, now() + interval '30 days');
  return true;
end
$$;

CREATE FUNCTION policy.oauth_register(p_registration text, p_redirect_uris text[], p_client_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  perform pg_advisory_xact_lock(hashtext('intelligence personal oauth registrations'));
  delete from policy.oauth_registrations where client_id is null and created_at < now() - interval '1 day';
  if (select count(*) from policy.oauth_registrations where client_id is null) >= 100 then
    delete from policy.oauth_registrations
    where id = (select r.id from policy.oauth_registrations r where r.client_id is null order by r.created_at, r.id limit 1);
  end if;
  insert into policy.oauth_registrations (id, redirect_uris, client_name) values (p_registration, p_redirect_uris, p_client_name);
end
$$;

CREATE FUNCTION policy.oauth_registration(p_registration text) RETURNS TABLE(redirect_uris text[], client_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select r.redirect_uris, r.client_name from policy.oauth_registrations r where r.id = p_registration
$$;

CREATE FUNCTION policy.open_item_closes(item_keys text[]) RETURNS TABLE(item_key text, match_key text, decision_id text, ending text, at text, due text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_reader boolean := session_user = 'pi_reader';
  v_caller text;
begin
  if v_reader then
    select c.id into v_caller from policy.current_client() c;
    if v_caller is null then
      raise exception 'no current client' using errcode = '42501';
    end if;
  end if;
  return query
    select d.details ->> 'key', d.details ->> 'match', d.id, d.answer, d.details ->> 'at', d.details ->> 'due'
    from knowledge.owner_decisions d
    where d.kind = 'open_item_close' and d.tainted_at is null
      and (d.details ->> 'key' = any (open_item_closes.item_keys) or d.details ->> 'match' = any (open_item_closes.item_keys))
      and not exists (select 1 from knowledge.owner_decisions r
                      where r.kind = 'open_item_reopen' and r.details ->> 'key' = d.details ->> 'key'
                        and (r.decided_at, r.id) > (d.decided_at, d.id) and r.tainted_at is null)
      and (not v_reader or d.compartments <@ policy.client_clearance()
           or (d.details ->> 'source' <> 'calendar' and d.details ->> 'key' = any (open_item_closes.item_keys)))
    order by 1, d.decided_at desc;
end
$$;

CREATE FUNCTION policy.open_session(session_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  caller text;
  clearance text[];
begin
  select c.id, c.compartments into caller, clearance from policy.current_client() c;
  if caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  insert into ledger.sessions (id, client_id, compartments)
  values (open_session.session_id, caller, clearance);
end
$$;

CREATE FUNCTION policy.owner_commitment_closes(fact_fps text[]) RETURNS TABLE(fact_fp text, decision_id text, ending text, at text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_reader boolean := session_user = 'pi_reader';
  v_caller text;
  v_keys text[];
begin
  if v_reader then
    select c.id into v_caller from policy.current_client() c;
    if v_caller is null then
      raise exception 'no current client' using errcode = '42501';
    end if;
  end if;
  v_keys := policy.clearance_keys();
  return query
    select t.fact_fp, t.id, t.answer, t.at
    from (
      select d.details ->> 'factKey' as fact_fp, d.id, d.answer, d.details ->> 'at' as at, d.decided_at
      from knowledge.owner_decisions d
      join knowledge.belief_rulings b on b.ruling_id = d.details ->> 'retire'
      where d.kind = 'commitment_close' and d.details ->> 'factKey' = any (owner_commitment_closes.fact_fps)
        and d.tainted_at is null and b.lifted_at is null
        and not exists (select 1 from knowledge.claims c where c.fact_key_fp = b.fact_key_fp and c.valid_from > b.created_at
                        and c.closes is not true
                        and (not v_reader or policy.label_key(c.compartments) = any (v_keys)))
        and (not v_reader or d.compartments <@ policy.client_clearance())
      union all
      select d.details ->> 'factKey', d.id, 'reopened',
             to_char(d.decided_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), d.decided_at
      from knowledge.owner_decisions d
      where d.kind = 'commitment_reopen' and d.details ->> 'factKey' = any (owner_commitment_closes.fact_fps)
        and d.tainted_at is null
        and (not v_reader or (d.compartments <@ policy.client_clearance()
                              and exists (select 1 from knowledge.claims c
                                          where c.fact_key_fp = d.details ->> 'factKey'
                                            and policy.label_key(c.compartments) = any (v_keys))))
    ) t
    order by 1, t.decided_at desc;
end
$$;

CREATE FUNCTION policy.owner_set_lever(key text, value jsonb, reason text, measure text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_old jsonb;
  v_change bigint;
begin
  if owner_set_lever.key is null or owner_set_lever.reason is null or owner_set_lever.measure is null
     or owner_set_lever.key !~ '^[a-z][a-z0-9_]{0,31}(\.[a-z][a-z0-9_]{0,31}){1,2}$'
     or owner_set_lever.reason !~ '^[a-z][a-z0-9_]{0,63}$' or owner_set_lever.measure !~ '^[a-z][a-z0-9_]{0,63}$'
     or (owner_set_lever.value is not null
         and not (jsonb_typeof(owner_set_lever.value) = 'number'
                  or (jsonb_typeof(owner_set_lever.value) = 'string' and owner_set_lever.value #>> '{}' ~ '^[a-z][a-z0-9_]{0,63}$'))) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('policy setting ' || owner_set_lever.key, 0));
  select s.value into v_old from policy.settings s where s.key = owner_set_lever.key;
  if v_old is not distinct from owner_set_lever.value then
    return null;
  end if;
  if owner_set_lever.value is null then
    delete from policy.settings s where s.key = owner_set_lever.key;
  else
    insert into policy.settings (key, value, updated_at, updated_by)
    values (owner_set_lever.key, owner_set_lever.value, now(), 'owner')
    on conflict (key) do update set value = excluded.value, updated_at = excluded.updated_at, updated_by = excluded.updated_by;
  end if;
  insert into policy.setting_changes (key, old_value, new_value, changed_by, reason, measure)
  values (owner_set_lever.key, v_old, owner_set_lever.value, 'owner', owner_set_lever.reason, owner_set_lever.measure)
  returning id into v_change;
  return v_change;
end
$_$;

CREATE FUNCTION policy.propose_about_you(session_id text, new_id text, request_id text, scope text, content_fp text, cites_fp text, cites text[], stamps text[], compartments text[], body_enc jsonb) RETURNS TABLE(outcome text, record_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  caller text;
  caller_name text;
  caller_views text[];
  caller_tools text[];
  earlier record;
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'an append runs read committed' using errcode = '42501';
  end if;
  select c.id, c.name, c.views, c.tools into caller, caller_name, caller_views, caller_tools from policy.current_client() c;
  if caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  if not ('propose_about_you' = any (caller_tools)) then
    raise exception 'not this client''s tool' using errcode = '42501';
  end if;
  if not exists (select 1 from ledger.sessions s where s.id = propose_about_you.session_id and s.client_id = caller) then
    raise exception 'not this client''s session' using errcode = '42501';
  end if;
  select w.id, w.kind, w.content_fp, w.cites_fp, w.proposal_scope into earlier
  from ledger.agent_writes w where w.client_id = caller and w.request_id = propose_about_you.request_id;
  if found then
    if earlier.kind = 'proposal' and earlier.content_fp = propose_about_you.content_fp and earlier.cites_fp = propose_about_you.cites_fp
       and earlier.proposal_scope is not distinct from propose_about_you.scope then
      return query select 'replayed'::text, earlier.id;
    else
      return query select 'request_reused'::text, null::text;
    end if;
    return;
  end if;
  insert into policy.record_quota as q (client_id) values (caller)
  on conflict (client_id) do update set attempts = q.attempts + 1, updated_at = now();
  if (select count(*) from ledger.agent_writes w where w.client_id = caller and w.kind <> 'memory_change' and w.created_at > now() - interval '24 hours') >= 200
     or (select count(*) from ledger.agent_writes w where w.client_id = caller and w.kind = 'proposal' and w.created_at > now() - interval '24 hours') >= 200 then
    return query select 'rate_limited'::text, null::text;
    return;
  end if;
  if propose_about_you.compartments is distinct from policy.record_label() then
    return query select 'label_mismatch'::text, null::text;
    return;
  end if;
  if propose_about_you.body_enc is null or not (jsonb_typeof(propose_about_you.body_enc) = 'object' and propose_about_you.body_enc ?& array['v', 'nonce', 'ciphertext', 'tag'] and (propose_about_you.body_enc - array['v', 'nonce', 'ciphertext', 'tag']) = '{}'::jsonb
      and propose_about_you.body_enc -> 'v' = '1'::jsonb and jsonb_typeof(propose_about_you.body_enc -> 'nonce') = 'string' and jsonb_typeof(propose_about_you.body_enc -> 'ciphertext') = 'string' and jsonb_typeof(propose_about_you.body_enc -> 'tag') = 'string'
      and propose_about_you.body_enc ->> 'nonce' <> '' and propose_about_you.body_enc ->> 'tag' <> '' and propose_about_you.body_enc ->> 'nonce' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' and propose_about_you.body_enc ->> 'ciphertext' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' and propose_about_you.body_enc ->> 'tag' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$') then
    return query select 'body_refused'::text, null::text;
    return;
  end if;
  if exists (
    select 1 from (
      select unnest(propose_about_you.cites) as id
      union
      select unnest(r.bound) from ledger.read_log r where r.session_id = propose_about_you.session_id
    ) rests
    where not exists (select 1 from vault.evidence_items e where e.id = rests.id)
  ) then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  if cardinality(propose_about_you.stamps) > 0
     and exists (select 1 from ledger.memory_projections m
                 where m.id = any (propose_about_you.stamps) and m.client_id = caller and m.tainted_at is not null) then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  insert into ledger.agent_writes (id, client_id, client_name, session_id, request_id, tool, kind, compartments, writer_views, content_fp, cites_fp, cites, body_enc, proposal_scope)
  values (propose_about_you.new_id, caller, caller_name, propose_about_you.session_id, propose_about_you.request_id, 'propose_about_you', 'proposal',
          policy.record_label(), caller_views, propose_about_you.content_fp, propose_about_you.cites_fp, propose_about_you.cites, propose_about_you.body_enc,
          propose_about_you.scope);
  return query select 'ok'::text, propose_about_you.new_id;
end
$_$;

CREATE FUNCTION policy.propose_person(session_id text, new_id text, request_id text, content_fp text, cites_fp text, cites text[], stamps text[], compartments text[], body_enc jsonb) RETURNS TABLE(outcome text, record_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
declare
  caller text;
  caller_name text;
  caller_views text[];
  caller_tools text[];
  earlier record;
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
