  end if;
  if propose_person.compartments is distinct from policy.record_label() then
    return query select 'label_mismatch'::text, null::text;
    return;
  end if;
  if propose_person.body_enc is null or not (jsonb_typeof(propose_person.body_enc) = 'object' and propose_person.body_enc ?& array['v', 'nonce', 'ciphertext', 'tag'] and (propose_person.body_enc - array['v', 'nonce', 'ciphertext', 'tag']) = '{}'::jsonb
      and propose_person.body_enc -> 'v' = '1'::jsonb and jsonb_typeof(propose_person.body_enc -> 'nonce') = 'string' and jsonb_typeof(propose_person.body_enc -> 'ciphertext') = 'string' and jsonb_typeof(propose_person.body_enc -> 'tag') = 'string'
      and propose_person.body_enc ->> 'nonce' <> '' and propose_person.body_enc ->> 'tag' <> '' and propose_person.body_enc ->> 'nonce' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' and propose_person.body_enc ->> 'ciphertext' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' and propose_person.body_enc ->> 'tag' ~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$') then
    return query select 'body_refused'::text, null::text;
    return;
  end if;
  if exists (
    select 1 from (
      select unnest(propose_person.cites) as id
      union
      select unnest(r.bound) from ledger.read_log r where r.session_id = propose_person.session_id
    ) rests
    where not exists (select 1 from vault.evidence_items e where e.id = rests.id)
  ) then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  if cardinality(propose_person.stamps) > 0
     and exists (select 1 from ledger.memory_projections m
                 where m.id = any (propose_person.stamps) and m.client_id = caller and m.tainted_at is not null) then
    return query select 'not_found'::text, null::text;
    return;
  end if;
  insert into ledger.agent_writes (id, client_id, client_name, session_id, request_id, tool, kind, compartments, writer_views, content_fp, cites_fp, cites, body_enc, proposal_scope)
  values (propose_person.new_id, caller, caller_name, propose_person.session_id, propose_person.request_id, 'propose_person', 'proposal',
          policy.record_label(), caller_views, propose_person.content_fp, propose_person.cites_fp, propose_person.cites, propose_person.body_enc, 'all');
  return query select 'ok'::text, propose_person.new_id;
end
$_$;

CREATE FUNCTION policy.push_capture(session_id text, batch text, items jsonb, ceiling boolean) RETURNS TABLE(ordinal integer, outcome text, code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_tools text[];
  v_kind text;
  v_max_calls integer;
  v_items integer;
  v_bytes bigint;
  v_day record;
  v_item jsonb;
  v_ord bigint;
  v_content text;
  v_scope text[];
  v_refused integer := 0;
  v_refused_day bigint;
  v_tasks boolean;
  v_contacts boolean;
  v_browsing text;
begin
  select c.id, c.tools into v_caller, v_tools from policy.current_client() c;
  select k.kind, k.max_calls_minute into v_kind, v_max_calls from policy.clients k where k.id = v_caller;
  if v_caller is null or v_kind is distinct from 'device' or not ('push_capture' = any (v_tools))
     or not exists (select 1 from policy.lens_devices d where d.capture_client_id = v_caller)
     or not exists (select 1 from ledger.sessions s where s.id = push_capture.session_id and s.client_id = v_caller) then
    raise exception 'not permitted' using errcode = '42501';
  end if;

  if push_capture.batch is null or push_capture.batch !~ '^[A-Za-z0-9_-]{8,64}$'
     or jsonb_typeof(push_capture.items) is distinct from 'array'
     or push_capture.ceiling is null
     or jsonb_array_length(push_capture.items) not between 1 and 50
     or exists (
       select 1 from jsonb_array_elements(push_capture.items) as e (v)
       where not coalesce(
         jsonb_typeof(e.v) = 'object'
         and e.v ->> 'id' ~ '^cin_[0-9A-HJKMNP-TV-Z]{26}$'
         and e.v ->> 'kind' in ('meeting', 'moment', 'block', 'task', 'forget', 'contact', 'contacts')
         and e.v ->> 'source_key_fp' ~ '^[0-9a-f]{64}$'
         and e.v ->> 'content_fp' ~ '^[0-9a-f]{64}$'
         and jsonb_typeof(e.v -> 'revision') = 'number' and e.v ->> 'revision' ~ '^[0-9]{1,4}$'
         and jsonb_typeof(e.v -> 'body_bytes') = 'number' and e.v ->> 'body_bytes' ~ '^[0-9]{1,9}$'
         and jsonb_typeof(e.v -> 'body_enc') = 'object' and (e.v -> 'body_enc') ?& array['v', 'nonce', 'ciphertext', 'tag']
         and ((e.v -> 'body_enc') - array['v', 'nonce', 'ciphertext', 'tag']) = '{}'::jsonb
         and octet_length((e.v -> 'body_enc')::text) <= 2097152
         and jsonb_typeof(e.v -> 'surfaces') = 'array'
         and (coalesce(jsonb_typeof(e.v -> 'source'), 'null') = 'null' or (e.v ->> 'kind' = 'moment' and e.v ->> 'source' in ('imessage')))
         and coalesce(jsonb_typeof(e.v -> 'source_bundle'), 'null') in ('null', 'boolean')
         and (e.v ->> 'kind' = 'moment' or coalesce(e.v ->> 'source_bundle', 'false') = 'false')
         and case e.v ->> 'kind'
               when 'forget' then jsonb_array_length(e.v -> 'surfaces') = 0 and e.v ->> 'revision' = '0'
               when 'task' then jsonb_array_length(e.v -> 'surfaces') = 0
               when 'contact' then jsonb_array_length(e.v -> 'surfaces') = 0
               when 'contacts' then jsonb_array_length(e.v -> 'surfaces') = 0 and e.v ->> 'revision' = '0'
               when 'block' then jsonb_array_length(e.v -> 'surfaces') between 1 and 500
               else jsonb_array_length(e.v -> 'surfaces') = 1 end
         and not exists (
           select 1 from jsonb_array_elements(e.v -> 'surfaces') as f (x)
           where not coalesce(
             jsonb_typeof(f.x) = 'object'
             and f.x ->> 'bundle_fp' ~ '^[0-9a-f]{64}$'
             and (coalesce(jsonb_typeof(f.x -> 'host_fp'), 'null') = 'null' or f.x ->> 'host_fp' ~ '^[0-9a-f]{64}$')
             and (coalesce(jsonb_typeof(f.x -> 'account_fp'), 'null') = 'null' or f.x ->> 'account_fp' ~ '^[0-9a-f]{64}$')
             and jsonb_typeof(f.x -> 'browser') = 'boolean'
             and jsonb_typeof(f.x -> 'multi_account') = 'boolean'
             and coalesce(jsonb_typeof(f.x -> 'never_default'), 'null') in ('null', 'boolean'), false)),
         false))
     or (select count(distinct e.v ->> 'source_key_fp') <> count(*) or count(distinct e.v ->> 'id') <> count(*)
         from jsonb_array_elements(push_capture.items) as e (v)) then
    raise exception 'invalid request' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('capture:' || v_caller, 0));
  select d.tasks, d.contacts, d.browsing into v_tasks, v_contacts, v_browsing from policy.lens_devices d where d.capture_client_id = v_caller;

  delete from policy.capture_push_refusals r where r.hour <= now() - interval '24 hours';

  if (select count(*) from policy.calls pc where pc.client_id = v_caller and pc.at > now() - interval '60 seconds') >= v_max_calls then
    return query select null::integer, 'rate_limited'::text, null::text;
    return;
  end if;
  select count(*)::integer, coalesce(sum((e.v ->> 'body_bytes')::bigint), 0) into v_items, v_bytes
  from jsonb_array_elements(push_capture.items) as e (v) where e.v ->> 'kind' <> 'forget';
  if v_items > 0 then
    select count(*) as items, coalesce(sum(i.body_bytes), 0) as bytes into v_day
    from ledger.capture_inbox i
    where i.client_id = v_caller and i.received_at > now() - interval '24 hours' and i.kind <> 'forget';
    select coalesce(sum(r.refused), 0) into v_refused_day
    from policy.capture_push_refusals r
    where r.client_id = v_caller and r.hour > now() - interval '24 hours';
    if v_day.items + v_items > 5000 or v_day.bytes + v_bytes > 52428800 or v_refused_day >= 20000 then
      return query select null::integer, 'rate_limited'::text, null::text;
      return;
    end if;
  end if;

  for v_item, v_ord in select e.v, e.n from jsonb_array_elements(push_capture.items) with ordinality as e (v, n) order by e.n loop
    if push_capture.ceiling and v_item ->> 'kind' <> 'forget' then
      return query select v_ord::integer, 'refused'::text, 'ceiling'::text;
      continue;
    end if;
    select i.content_fp into v_content from ledger.capture_inbox i
    where i.client_id = v_caller and i.source_key_fp = v_item ->> 'source_key_fp' and i.revision = (v_item ->> 'revision')::integer;
    if found then
      if v_content = v_item ->> 'content_fp' then
        return query select v_ord::integer, 'replayed'::text, null::text;
      else
        v_refused := v_refused + 1;
        return query select v_ord::integer, 'refused'::text, 'conflict'::text;
      end if;
      continue;
    end if;
    if exists (select 1 from ledger.capture_inbox i
               where i.client_id = v_caller and i.source_key_fp = v_item ->> 'source_key_fp' and i.revision > (v_item ->> 'revision')::integer) then
      v_refused := v_refused + 1;
      return query select v_ord::integer, 'refused'::text, 'out_of_order'::text;
      continue;
    end if;
    if v_item ->> 'kind' = 'task' and not v_tasks then
      v_refused := v_refused + 1;
      return query select v_ord::integer, 'refused'::text, 'out_of_scope'::text;
      continue;
    end if;
    if v_item ->> 'kind' in ('contact', 'contacts') and not v_contacts then
      v_refused := v_refused + 1;
      return query select v_ord::integer, 'refused'::text, 'out_of_scope'::text;
      continue;
    end if;
    if v_item ->> 'kind' = 'moment' and coalesce((v_item ->> 'source_bundle')::boolean, false) and v_item ->> 'source' is null then
      v_refused := v_refused + 1;
      return query select v_ord::integer, 'refused'::text, 'out_of_scope'::text;
      continue;
    end if;
    if v_item ->> 'kind' not in ('forget', 'task', 'contact', 'contacts', 'meeting') and not exists (
        select 1 from jsonb_array_elements(v_item -> 'surfaces') as f (x)
        join policy.capture_scope r on (v_item ->> 'kind') = any (r.kinds) and r.source is not distinct from (v_item ->> 'source')
          and case when f.x ->> 'host_fp' is not null then r.match = 'host' and r.value_fp = f.x ->> 'host_fp'
                   when (f.x ->> 'browser')::boolean then false
                   else r.match = 'bundle' and r.value_fp = f.x ->> 'bundle_fp' end
          and case when (f.x ->> 'multi_account')::boolean then r.account_fp = f.x ->> 'account_fp'
                   else r.account_fp is null or r.account_fp = f.x ->> 'account_fp' end)
       and not (v_item ->> 'kind' = 'block' and v_browsing = 'deny' and exists (
        select 1 from jsonb_array_elements(v_item -> 'surfaces') as f (x)
        where (f.x ->> 'browser')::boolean and f.x ->> 'host_fp' is not null and not coalesce((f.x ->> 'never_default')::boolean, true)
          and (not (f.x ->> 'multi_account')::boolean or f.x ->> 'account_fp' is not null))) then
      v_refused := v_refused + 1;
      return query select v_ord::integer, 'refused'::text, 'out_of_scope'::text;
      continue;
    end if;
    v_scope := array(
      select distinct p.fp from jsonb_array_elements(v_item -> 'surfaces') as f (x)
      cross join lateral unnest(array[f.x ->> 'bundle_fp', f.x ->> 'host_fp', f.x ->> 'account_fp']) as p (fp)
      where p.fp is not null order by p.fp);
    insert into ledger.capture_inbox (id, client_id, session_id, batch, source_key_fp, revision, kind, scope_fps, content_fp, body_bytes, compartments, body_enc, source)
    values (v_item ->> 'id', v_caller, push_capture.session_id, push_capture.batch, v_item ->> 'source_key_fp', (v_item ->> 'revision')::integer,
            v_item ->> 'kind', v_scope, v_item ->> 'content_fp', (v_item ->> 'body_bytes')::integer, array['own'], v_item -> 'body_enc', v_item ->> 'source');
    return query select v_ord::integer, 'accepted'::text, null::text;
  end loop;

  if v_refused > 0 then
    insert into policy.capture_push_refusals as r (client_id, hour, refused)
    values (v_caller, date_trunc('hour', now(), 'UTC'), v_refused)
    on conflict (client_id, hour) do update set refused = r.refused + excluded.refused;
  end if;
end
$_$;

CREATE FUNCTION policy.read_allowance(budget text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  text_tools constant text[] := array['read_message', 'read_item', 'get_evidence_span', 'get_document', 'fetch_template'];
  read_tools text[];
  caller text;
  items integer;
  chars_day bigint;
  rows_day integer;
  calls_minute integer;
  used_minute bigint;
  used_chars bigint;
  used_rows bigint;
begin
  select c.id into caller from policy.current_client() c;
  if caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  if budget is null or budget not in ('text', 'list') then
    raise exception 'unknown budget' using errcode = '22023';
  end if;
  select k.max_items_day, k.max_chars_day, k.max_rows_day, k.max_calls_minute
    into items, chars_day, rows_day, calls_minute
    from policy.clients k where k.id = caller;
  read_tools := array(select t.name from policy.tool_names t where t.read);

  select count(*) filter (where k.at > now() - interval '60 seconds'),
         coalesce(sum(k.chars), 0),
         coalesce(sum(k.rows) filter (where k.outcome = 'ok'), 0)
    into used_minute, used_chars, used_rows
    from policy.calls k
   where k.client_id = caller and k.at > now() - interval '24 hours' and k.tool = any (read_tools);

  if used_minute >= calls_minute then
    return 'rate_limited_minute';
  end if;
  if budget = 'list' then
    return case when used_rows >= rows_day then 'rate_limited_day' else 'ok' end;
  end if;
  if used_chars >= chars_day then
    return 'rate_limited_day';
  end if;
  if (select count(distinct b.id) from ledger.read_log r cross join lateral unnest(r.bound) as b(id)
      where r.client_id = caller and r.read_at > now() - interval '24 hours' and r.tool = any (text_tools)) >= items then
    return 'rate_limited_day';
  end if;
  return 'ok';
end
$$;

CREATE FUNCTION policy.read_connected(label text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select exists (select 1 from policy.secrets s
                 where s.name in ('google/' || read_connected.label || '/client', 'google/' || read_connected.label || '/refresh_token'))
$$;

CREATE FUNCTION policy.record_label() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  caller_name text;
  clearance text[];
  label text[];
begin
  select c.name, c.compartments into caller_name, clearance from policy.current_client() c;
  if caller_name is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  select array_agg(distinct x.compartment collate "C" order by x.compartment collate "C")
  into label
  from unnest(clearance || ('agent:' || caller_name)) as x(compartment);
  return label;
end
$$;

CREATE FUNCTION policy.record_reads(p_record_id text, p_limit integer) RETURNS TABLE(record_id text, kind text, created_at timestamp with time zone, superseded_by text, erased boolean, reader text, first_at timestamp with time zone, last_at timestamp with time zone, reads integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_views text[];
  v_tools text[];
  v_clearance text[];
  v_keys text[];
  v_view_keys text[];
begin
  select c.id, c.views, c.tools into v_caller, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('record_reads' = any (v_tools)) or not ('self' = any (v_views)) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_keys := policy.clearance_keys();
  v_clearance := policy.client_clearance();
  v_view_keys := policy.view_keys();
  return query
    with visible as not materialized (
      select w.id, w.kind, w.created_at, w.body_enc is null as erased
      from ledger.agent_writes w
      where w.client_id = v_caller and w.tool = 'record' and w.kind in ('note', 'finding', 'handoff')
        and w.compartments <@ v_clearance and policy.label_key(w.compartments) = any (v_keys)
        and w.writer_views <@ v_views and policy.label_key(w.writer_views) = any (v_view_keys)
        and w.flagged_at is null
    ),
    mine as materialized (
      select v.id, v.kind, v.created_at, v.erased
      from visible v
      where record_reads.p_record_id is null or v.id = record_reads.p_record_id
      order by v.created_at desc, v.id collate "C" desc
      limit record_reads.p_limit
    ),
    latest as (
      select distinct on (l.root) l.root, l.id
      from policy.live_corrections(array(select m.id from mine m)) l
      order by l.root, l.created_at desc, l.id collate "C" desc
    ),
    shown as (
      select m.id, r.client_id, min(r.read_at) as first_at, max(r.read_at) as last_at, count(*)::int as reads
      from mine m
      join ledger.read_log r on r.shown @> array[m.id] and r.client_id <> v_caller
      group by m.id, r.client_id
    )
    select m.id, m.kind, m.created_at, lt.id, m.erased, c.name, sh.first_at, sh.last_at, sh.reads
    from mine m
    left join latest lt on lt.root = m.id
    left join shown sh on sh.id = m.id
    left join policy.clients c on c.id = sh.client_id
    order by m.created_at desc, m.id collate "C" desc, c.name collate "C", sh.client_id collate "C";
end
$$;

CREATE FUNCTION policy.rejected_claims() RETURNS TABLE(source_account_id text, source_item_fp text, fact_key_fp text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select r.source_account_id, r.source_item_fp, r.fact_key_fp
  from knowledge.belief_rulings r
  where r.verdict = 'reject' and r.lifted_at is null
  order by r.created_at, r.ruling_id collate "C"
$$;

CREATE FUNCTION policy.relation_effective(p_relation bigint, p_judge text, p_kind text, p_judged_at timestamp with time zone, p_as_of timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select not starts_with(p_judge, 'model:')
    or coalesce((select w.switched_on from policy.relation_switches w
                 where w.kind = p_kind and w.judge = p_judge and w.decided_by = 'owner' and w.decided_at <= p_as_of
                 order by w.decided_at desc, w.id desc limit 1), false)
    or policy.census_held(p_relation, p_judge)
$$;

CREATE FUNCTION policy.relayed_claims(claim_keys text[]) RETURNS SETOF text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_reader boolean := session_user = 'pi_reader';
  v_restricted boolean := session_user = 'pi_restricted';
  v_clearance text[];
  v_keys text[];
begin
  if coalesce(cardinality(claim_keys), 0) > 1000 then
    raise exception 'too many keys' using errcode = '22023';
  end if;
  if v_reader then
    v_clearance := policy.client_clearance();
    v_keys := policy.clearance_keys();
  end if;
  return query
    select distinct k.key
    from unnest(relayed_claims.claim_keys) as k (key)
    where exists (
      select 1
      from ledger.cards c
      join knowledge.owner_decisions o on o.card_id = c.id
      join ledger.card_relays y on y.ruling_id = o.id and y.card_id = c.id and y.reopened_at is null
      where c.kind in ('agent_claim', 'about_you') and c.created_by = 'system:extract' and c.request_id = k.key and c.tainted_at is null
        and (not v_reader or (c.compartments <@ v_clearance and policy.label_key(c.compartments) = any (v_keys)))
        and (not v_restricted or policy.is_restricted(c.compartments))
        and o.kind = 'answer' and o.answer = 'confirm' and o.tainted_at is null
        and not exists (select 1 from knowledge.owner_decisions s where s.supersedes = o.id)
        and not exists (select 1 from ledger.restatement_checks r
                        where r.claim_key = k.key and r.answer in ('echo', 'stale') and r.cleared_at is null
                          and o.decided_at >= r.checked_at))
    order by 1;
end
$$;

CREATE FUNCTION policy.released_records() RETURNS TABLE(evidence_id text, ruling_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with reader as materialized (
    select policy.client_clearance() as clearance, policy.clearance_keys() as keys
    where session_user = 'pi_reader'
  )
  select r.evidence_id, r.ruling_id
  from knowledge.claim_releases r
  join knowledge.owner_decisions o on o.id = r.ruling_id
  where r.lifted_at is null and o.tainted_at is null
    and (not exists (select 1 from reader)
         or exists (select 1 from reader k
                    where r.compartments <@ k.clearance and policy.label_key(r.compartments) = any (k.keys)))
    and not exists (select 1 from knowledge.owner_decisions s where s.supersedes = o.id)
    and not exists (select 1 from knowledge.release_lifts l where l.ruling_id = r.ruling_id)
    and not exists (
      select 1 from knowledge.claims c join knowledge.belief_rulings b
        on b.fact_key_fp in (c.fact_key_fp, c.legacy_fact_key_fp, c.legacy_alt_fact_key_fp)
      where c.evidence_id = r.evidence_id
        and b.verdict in ('veto', 'retire') and b.lifted_at is null)
  order by r.evidence_id collate "C"
$$;

CREATE FUNCTION policy.request_restriction(evidence_id text, category text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text := session_user;
  v_account text;
  v_source text;
  v_label text[];
  v_alphabet constant text := '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
  v_ms bigint := floor(extract(epoch from clock_timestamp()) * 1000)::bigint;
  v_random bytea := uuid_send(gen_random_uuid());
  v_id text := 'rrq_';
  v_written integer;
begin
  if v_caller not in ('pi_pipeline', 'pi_restricted') then
    raise exception 'not a worker' using errcode = '42501';
  end if;
  select e.source_account_id, e.source_item_fp, e.compartments into v_account, v_source, v_label
  from vault.evidence_items e where e.id = request_restriction.evidence_id;
  if not found or (v_caller = 'pi_pipeline' and policy.is_restricted(v_label)) then
    raise exception 'no such item' using errcode = '42501';
  end if;
  if not exists (select 1 from policy.restricted_categories r where r.category = request_restriction.category) then
    raise exception 'category not on' using errcode = '42501';
  end if;
  if ('restricted:' || request_restriction.category) = any (v_label)
     or exists (select 1 from vault.restriction_lifts l
                where l.account_id = v_account and l.source_item_fp = v_source and l.category = request_restriction.category) then
    return;
  end if;

  for i in reverse 9..0 loop
    v_id := v_id || substr(v_alphabet, 1 + ((v_ms >> (5 * i)) & 31)::integer, 1);
  end loop;
  for i in 0..15 loop
    v_id := v_id || substr(v_alphabet, 1 + (get_byte(v_random, i) & 31), 1);
  end loop;

  begin
    insert into vault.restriction_requests (id, evidence_id, kind, category, requested_by, compartments)
    values (v_id, request_restriction.evidence_id, 'restrict', request_restriction.category, 'jev', v_label);
    v_written := 1;
  exception when unique_violation then
    v_written := 0;
  end;
  if v_written = 1 then
    update knowledge.messages m set restricting = true
    where m.evidence_id in (select e.id from vault.evidence_items e where e.source_account_id = v_account and e.source_item_fp = v_source);
  end if;
end
$$;

CREATE FUNCTION policy.serve_memory(template text, ids text[], fact_key_fps text[], state_fps text[], belief_ids text[], compartments jsonb, open_fact_key_fps text[], partial boolean, have text[], can_delete boolean, line_fps text[] DEFAULT NULL::text[], supports jsonb DEFAULT NULL::jsonb) RETURNS TABLE(kind text, projection_id text, ended_at timestamp with time zone, reason text, current_id text, evidence_ids text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  caller text;
  clearance text[];
  client_audience text[];
  held text[];
  served integer;
  foreign_belief boolean;
  stale_belief boolean;
  derived jsonb;
  labels_of jsonb;
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));

  select c.id, c.compartments, c.tools into caller, clearance, held from policy.current_client() c;
  if caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  if not ('sync_memory' = any (held)) then
    raise exception 'not this client''s tool' using errcode = '42501';
  end if;
  client_audience := (select array_agg(x order by x collate "C") from (select distinct x from unnest(clearance) as u (x)) d);

  if serve_memory.template is null or serve_memory.template !~ '^[a-z_]+@[1-9][0-9]*$' then
    raise exception 'serve_memory_template' using errcode = '23514', constraint = 'serve_memory_template';
  end if;
  served := cardinality(serve_memory.ids);
  if served is null or served > 40 or array_position(serve_memory.ids, null) is not null
     or exists (select 1 from unnest(serve_memory.ids) i where i !~ '^mpr_[0-9a-f]{40}$')
     or (select count(distinct i) from unnest(serve_memory.ids) i) <> served then
    raise exception 'serve_memory_ids' using errcode = '23514', constraint = 'serve_memory_ids';
  end if;
  if serve_memory.fact_key_fps is null or serve_memory.state_fps is null
     or exists (select 1 from unnest(serve_memory.fact_key_fps || serve_memory.state_fps) f where f is null or f !~ '^[0-9a-f]{64}$') then
    raise exception 'serve_memory_fingerprints' using errcode = '23514', constraint = 'serve_memory_fingerprints';
  end if;
  if serve_memory.belief_ids is null or exists (select 1 from unnest(serve_memory.belief_ids) b where b is null or b !~ '^blf_[0-9a-f]{40}$') then
    raise exception 'serve_memory_belief_ids' using errcode = '23514', constraint = 'serve_memory_belief_ids';
  end if;
  if serve_memory.compartments is null or jsonb_typeof(serve_memory.compartments) <> 'array' then
    raise exception 'serve_memory_compartments' using errcode = '23514', constraint = 'serve_memory_compartments';
  end if;
  if exists (
    select 1 from jsonb_array_elements(serve_memory.compartments) e
    where case
      when jsonb_typeof(e) <> 'array' then true
      when jsonb_array_length(e) = 0 then true
      when exists (select 1 from jsonb_array_elements(e) x where jsonb_typeof(x) <> 'string') then true
      else (select array_agg(x order by o) from jsonb_array_elements_text(e) with ordinality as t (x, o))
             is distinct from (select array_agg(x order by x collate "C") from (select distinct x from jsonb_array_elements_text(e) as u (x)) d)
        or not ((select array_agg(x) from jsonb_array_elements_text(e) as u (x)) <@ clearance)
    end) then
    raise exception 'serve_memory_compartments' using errcode = '23514', constraint = 'serve_memory_compartments';
  end if;
  if cardinality(serve_memory.fact_key_fps) <> served or cardinality(serve_memory.state_fps) <> served or cardinality(serve_memory.belief_ids) <> served
     or jsonb_array_length(serve_memory.compartments) <> served then
    raise exception 'serve_memory_lengths' using errcode = '23514', constraint = 'serve_memory_lengths';
  end if;
  if serve_memory.open_fact_key_fps is null or cardinality(serve_memory.open_fact_key_fps) > 5000
     or exists (select 1 from unnest(serve_memory.open_fact_key_fps) f where f is null or f !~ '^[0-9a-f]{64}$') then
    raise exception 'serve_memory_open_fact_key_fps' using errcode = '23514', constraint = 'serve_memory_open_fact_key_fps';
  end if;
  if serve_memory.have is null or cardinality(serve_memory.have) > 200 or array_position(serve_memory.have, null) is not null
     or exists (select 1 from unnest(serve_memory.have) h where h !~ '^mpr_[0-9a-f]{40}$')
     or (select count(distinct h) from unnest(serve_memory.have) h) <> cardinality(serve_memory.have) then
    raise exception 'serve_memory_have' using errcode = '23514', constraint = 'serve_memory_have';
  end if;
  if serve_memory.partial is null or serve_memory.can_delete is null then
    raise exception 'serve_memory_flags' using errcode = '23514', constraint = 'serve_memory_flags';
  end if;
  if serve_memory.line_fps is not null and (coalesce(cardinality(serve_memory.line_fps), 0) <> served
     or exists (select 1 from unnest(serve_memory.line_fps) f where f is null or f !~ '^[0-9a-f]{64}$')) then
    raise exception 'serve_memory_line_fps' using errcode = '23514', constraint = 'serve_memory_line_fps';
  end if;

  if serve_memory.supports is null or jsonb_typeof(serve_memory.supports) <> 'array' or jsonb_array_length(serve_memory.supports) <> served
     or exists (select 1 from jsonb_array_elements(serve_memory.supports) e
                where jsonb_typeof(e) <> 'array' or jsonb_array_length(e) > 5000
                  or exists (select 1 from jsonb_array_elements(e) x where jsonb_typeof(x) <> 'string' or (x #>> '{}') !~ '^[0-9a-f]{64}$')) then
    raise exception 'serve_memory_supports' using errcode = '23514', constraint = 'serve_memory_supports';
  end if;

  if exists (select 1 from ledger.memory_projections m where m.id = any (serve_memory.ids) and m.client_id <> caller) then
    raise exception 'not this client''s projection' using errcode = '42501';
  end if;

  select
    false,
    coalesce(bool_or(e.found <> p.given), false),
    coalesce(jsonb_agg(to_jsonb(coalesce(e.label, '{}'::text[])) order by s.n), '[]'::jsonb),
    coalesce(jsonb_agg(to_jsonb(coalesce(e.ids, '{}'::text[])) order by s.n), '[]'::jsonb)
  into foreign_belief, stale_belief, labels_of, derived
  from unnest(serve_memory.belief_ids, serve_memory.fact_key_fps, serve_memory.state_fps) with ordinality as s (belief, fact, state, n)
  cross join lateral (
    select array(select distinct x from jsonb_array_elements_text(serve_memory.supports -> (s.n::integer - 1)) as u (x)) as support
  ) q
  cross join lateral (select cardinality(q.support) as given) p
  left join lateral (
    select (select count(*)::integer from knowledge.claims c where c.id = any (q.support) and c.fact_key_fp = s.fact and c.compartments <@ clearance) as found,
      (select ledger.label(array_agg(u.x)) from knowledge.claims c cross join lateral unnest(c.compartments) as u (x)
       where c.id = any (q.support) and c.fact_key_fp = s.fact and c.compartments <@ clearance) as label,
      (select array_agg(d.evidence_id order by d.evidence_id collate "C") from (select distinct c.evidence_id from knowledge.claims c
       where c.id = any (q.support) and c.fact_key_fp = s.fact and c.compartments <@ clearance) d) as ids
  ) e on true;
  if foreign_belief then
    raise exception 'not this client''s belief' using errcode = '42501';
  end if;
  if stale_belief then
    raise exception 'serve_memory_beliefs' using errcode = '23514', constraint = 'serve_memory_beliefs';
  end if;
  if exists (select 1 from jsonb_array_elements(derived) d where jsonb_array_length(d) = 0 or jsonb_array_length(d) > 500) then
    raise exception 'serve_memory_evidence_ids' using errcode = '23514', constraint = 'serve_memory_evidence_ids';
  end if;
  if exists (select 1 from jsonb_array_elements(labels_of) l
             where jsonb_array_length(l) = 0 or not ((select array_agg(x) from jsonb_array_elements_text(l) as u (x)) <@ clearance)) then
    raise exception 'serve_memory_compartments' using errcode = '23514', constraint = 'serve_memory_compartments';
  end if;

  insert into ledger.memory_projections as m (id, client_id, audience, template, fact_key_fp, state_fp, belief_id, evidence_ids, compartments, first_served_at, last_served_at, line_fp)
  select s.id, caller, client_audience, serve_memory.template, s.fact, s.state, s.belief,
    array(select x from jsonb_array_elements_text(derived -> (s.n::integer - 1)) with ordinality as u (x, o) order by o),
    array(select x from jsonb_array_elements_text(labels_of -> (s.n::integer - 1)) with ordinality as u (x, o) order by o),
    now(), now(), serve_memory.line_fps[s.n::integer]
  from unnest(serve_memory.ids, serve_memory.fact_key_fps, serve_memory.state_fps, serve_memory.belief_ids) with ordinality as s (id, fact, state, belief, n)
  on conflict (id) do update set
    last_served_at = now(),
    audience = excluded.audience,
    state_fp = excluded.state_fp,
    belief_id = excluded.belief_id,
    compartments = excluded.compartments,
    evidence_ids = array(select x from unnest(m.evidence_ids || excluded.evidence_ids) as u (x) group by x order by x collate "C"),
    line_fp = coalesce(excluded.line_fp, m.line_fp),
    last_ended_at = coalesce(m.ended_at, m.last_ended_at),
    last_tainted_at = coalesce(m.tainted_at, m.last_tainted_at),
    reported_absent_at = case when m.ended_at is null and m.tainted_at is null then m.reported_absent_at end,
    ended_at = null,
    reason = null,
    next_id = null,
    tainted_at = null
  where m.client_id = caller;

  update ledger.memory_projections m
  set ended_at = now(),
      next_id = (select s.id from unnest(serve_memory.ids, serve_memory.fact_key_fps) as s (id, fact) where s.fact = m.fact_key_fp limit 1),
      reason = case
        when m.fact_key_fp = any (serve_memory.fact_key_fps) then 'changed'
        when m.fact_key_fp = any (serve_memory.open_fact_key_fps) or serve_memory.partial then 'dropped'
        else 'withdrawn'
      end
  where m.client_id = caller and m.ended_at is null and not (m.id = any (serve_memory.ids));

  update ledger.memory_projections m set reported_present_at = now()
  where m.client_id = caller and m.id = any (serve_memory.have);
  update ledger.memory_projections m set reported_absent_at = now()
  where m.client_id = caller and m.reported_present_at is not null
    and (m.reported_absent_at is null or m.reported_absent_at < m.reported_present_at) and not (m.id = any (serve_memory.have));
  update ledger.memory_exposures x
  set removal = r.latest,
      removal_at = case when r.latest = 'pending' then null else now() end,
      first_removal = coalesce(x.first_removal, nullif(r.latest, 'pending')),
      first_removal_at = case when x.first_removal is null and r.latest <> 'pending' then now() else x.first_removal_at end
  from (
    select y.id,
      case when not (y.projection_id = any (serve_memory.have)) then 'reported'
           when not serve_memory.can_delete then 'not_possible'
           else 'pending' end as latest
    from ledger.memory_exposures y join ledger.memory_projections p on p.id = y.projection_id
    where y.client_id = caller and p.tainted_at = y.recorded_at
  ) r
  where x.id = r.id and x.removal <> r.latest;

  return query
    select 'served'::text, s.id, null::timestamptz, null::text, null::text,
      array(select x from jsonb_array_elements_text(derived -> (s.n::integer - 1)) with ordinality as u (x, o) order by o)
    from unnest(serve_memory.ids) with ordinality as s (id, n)
    order by s.n;
  return query
    select 'remove'::text, h.id, null::timestamptz, null::text, null::text, null::text[]
    from unnest(serve_memory.have) as h (id)
    where not exists (select 1 from ledger.memory_projections m where m.id = h.id and m.client_id = caller and m.ended_at is null)
    order by h.id collate "C";
  return query
    select 'correction'::text, m.id, m.ended_at, m.reason, m.next_id, null::text[]
    from ledger.memory_projections m
    where m.client_id = caller and m.ended_at is not null
    order by m.ended_at desc, m.id collate "C"
    limit 20;
end
$_$;

CREATE FUNCTION policy.serve_mirror(session_id text, template text, cursor_id text, erased_done text[], section text, after_key text, last_key text, found_keys text[], entries jsonb, rebuild boolean, removal_limit integer, section_cap integer) RETURNS TABLE(kind text, projection_id text, entry_key text, state text, reason text, ended_at timestamp with time zone, capture_key text, new_cursor_id text, pass integer, pass_complete boolean, truncated boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_caller text;
  v_clearance text[];
  v_tools text[];
  v_audience text[];
  v_keys text[];
  v_form text;
  v_latest ledger.mirror_cursors%rowtype;
  v_at ledger.mirror_cursors%rowtype;
  v_standing text;
  v_new_pass boolean;
  v_pass integer;
  v_rebuild boolean;
  v_rebuilt_at timestamptz;
  v_next_section text;
  v_next_after text;
  v_completed_at timestamptz;
  v_last_completed timestamptz;
  v_e record;
  v_key text;
  v_kind text;
  v_label text[];
  v_evidence text[];
  v_entities text[];
  v_anchors text[];
  v_members text[];
  v_contacts text[];
  v_claimed text[];
  v_support text[];
  v_claims text[];
  v_state text;
  v_b_audience text[];
  v_fact text;
  v_ev text;
  v_fp text;
  v_count integer;
  v_hidden boolean;
  v_off boolean;
  v_checked jsonb := '[]'::jsonb;
  v_over text[] := '{}'::text[];
  v_oversize text[];
  v_truncated boolean := false;
  v_sent_ids text[] := '{}'::text[];
  v_sent_keys text[] := '{}'::text[];
  v_sent_states text[] := '{}'::text[];
  v_rem_ids text[];
  v_rem_reasons text[];
  v_rem_at timestamptz[];
  v_erased text[];
  v_hold boolean := false;
  v_new text;
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));

  select c.id, c.compartments, c.tools into v_caller, v_clearance, v_tools from policy.current_client() c;
  if v_caller is null then
    raise exception 'no current client' using errcode = '42501';
  end if;
  if not ('sync_mirror' = any (v_tools)) then
    raise exception 'not this client''s tool' using errcode = '42501';
  end if;
  if serve_mirror.session_id is null
     or not exists (select 1 from ledger.sessions s where s.id = serve_mirror.session_id and s.client_id = v_caller) then
    raise exception 'not this client''s session' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('mirror:' || v_caller, 0));
  v_keys := policy.clearance_keys();
  v_audience := (select array_agg(d.x order by d.x collate "C") from (select distinct u.x from unnest(v_clearance) as u (x)) d);

  if serve_mirror.template is null or serve_mirror.template !~ '^lens_mirror@[1-9][0-9]{0,3}$' then
    raise exception 'serve_mirror_template' using errcode = '23514', constraint = 'serve_mirror_template';
  end if;
  if serve_mirror.section is not null and serve_mirror.section not in ('entities', 'beliefs', 'facts', 'events', 'captures') then
    raise exception 'serve_mirror_section' using errcode = '23514', constraint = 'serve_mirror_section';
  end if;
  if serve_mirror.removal_limit is null or serve_mirror.removal_limit not between 1 and 500 then
    raise exception 'serve_mirror_removal_limit' using errcode = '23514', constraint = 'serve_mirror_removal_limit';
  end if;
  if serve_mirror.cursor_id is not null and serve_mirror.cursor_id !~ '^mcr_[0-9A-HJKMNP-TV-Z]{26}$' then
    raise exception 'serve_mirror_cursor_id' using errcode = '23514', constraint = 'serve_mirror_cursor_id';
  end if;
  if serve_mirror.erased_done is null or cardinality(serve_mirror.erased_done) > 500
     or exists (select 1 from unnest(serve_mirror.erased_done) k where k is null or k !~ '^(meeting|moment|block|task):[0-9A-HJKMNP-TV-Z]{26}$') then
    raise exception 'serve_mirror_erased_done' using errcode = '23514', constraint = 'serve_mirror_erased_done';
  end if;
  if serve_mirror.entries is null or jsonb_typeof(serve_mirror.entries) <> 'array' or jsonb_array_length(serve_mirror.entries) > 500 then
    raise exception 'serve_mirror_entries' using errcode = '23514', constraint = 'serve_mirror_entries';
  end if;
  if serve_mirror.found_keys is null or cardinality(serve_mirror.found_keys) > 2000 or array_position(serve_mirror.found_keys, null) is not null then
    raise exception 'serve_mirror_found_keys' using errcode = '23514', constraint = 'serve_mirror_found_keys';
  end if;
  if serve_mirror.section is null then
    if serve_mirror.after_key is not null or serve_mirror.last_key is not null then
      raise exception 'serve_mirror_after_key' using errcode = '23514', constraint = 'serve_mirror_after_key';
    end if;
    if cardinality(serve_mirror.found_keys) > 0 then
      raise exception 'serve_mirror_found_keys' using errcode = '23514', constraint = 'serve_mirror_found_keys';
    end if;
    if jsonb_array_length(serve_mirror.entries) > 0 then
      raise exception 'serve_mirror_entries' using errcode = '23514', constraint = 'serve_mirror_entries';
    end if;
  else
    v_form := case serve_mirror.section
      when 'entities' then '^ent_[0-9A-HJKMNP-TV-Z]{26}$'
      when 'beliefs' then '^blf_[0-9a-f]{40}$'
      when 'facts' then '^[0-9a-f]{64}:[0-9a-f]{64}$'
      when 'events' then '^evt_[0-9A-HJKMNP-TV-Z]{26}$'
      else '^cap_[0-9A-HJKMNP-TV-Z]{26}$'
    end;
    if serve_mirror.section_cap is null or serve_mirror.section_cap not between 1 and 1000000 then
      raise exception 'serve_mirror_section_cap' using errcode = '23514', constraint = 'serve_mirror_section_cap';
    end if;
    if serve_mirror.rebuild is null then
      raise exception 'serve_mirror_rebuild' using errcode = '23514', constraint = 'serve_mirror_rebuild';
    end if;
    if serve_mirror.after_key is not null and serve_mirror.after_key !~ v_form then
      raise exception 'serve_mirror_after_key' using errcode = '23514', constraint = 'serve_mirror_after_key';
    end if;
    if serve_mirror.last_key is not null and (serve_mirror.last_key !~ v_form
       or (serve_mirror.after_key is not null and serve_mirror.last_key <= (serve_mirror.after_key collate "C"))) then
      raise exception 'serve_mirror_last_key' using errcode = '23514', constraint = 'serve_mirror_last_key';
    end if;
    if exists (select 1 from unnest(serve_mirror.found_keys) k
               where k !~ v_form
                  or (serve_mirror.after_key is not null and k <= (serve_mirror.after_key collate "C"))
                  or (serve_mirror.last_key is not null and k > (serve_mirror.last_key collate "C")))
       or (select count(distinct k) from unnest(serve_mirror.found_keys) k) <> cardinality(serve_mirror.found_keys) then
      raise exception 'serve_mirror_found_keys' using errcode = '23514', constraint = 'serve_mirror_found_keys';
    end if;
    if exists (
      select 1 from jsonb_array_elements(serve_mirror.entries) as x (e)
      where case
        when jsonb_typeof(x.e) <> 'object' then true
        when jsonb_typeof(x.e -> 'id') is distinct from 'string' or (x.e ->> 'id') !~ '^mir_[0-9a-f]{40}$' then true
        when jsonb_typeof(x.e -> 'key') is distinct from 'string' or not ((x.e ->> 'key') = any (serve_mirror.found_keys)) then true
        when jsonb_typeof(x.e -> 'state') is distinct from 'string' or (x.e ->> 'state') !~ '^[0-9a-f]{64}$' then true
        when jsonb_typeof(x.e -> 'token') is distinct from 'string' or (x.e ->> 'token') !~ '^[0-9a-f]{64}$' then true
        when serve_mirror.section in ('beliefs', 'facts')
          then jsonb_typeof(x.e -> 'fact_key_fp') is distinct from 'string' or (x.e ->> 'fact_key_fp') !~ '^[0-9a-f]{64}$'
        when jsonb_typeof(x.e -> 'fact_key_fp') is distinct from 'null' then true
        else false
      end
      or case
        when jsonb_typeof(x.e -> 'evidence_ids') is distinct from 'array' or jsonb_typeof(x.e -> 'entity_ids') is distinct from 'array'
          or jsonb_typeof(x.e -> 'anchor_ids') is distinct from 'array' or jsonb_typeof(x.e -> 'compartments') is distinct from 'array' then true
        when jsonb_array_length(x.e -> 'compartments') = 0
          or exists (select 1 from jsonb_array_elements(x.e -> 'compartments') y where jsonb_typeof(y) <> 'string') then true
        when exists (select 1 from jsonb_array_elements(x.e -> 'evidence_ids') y
                     where jsonb_typeof(y) <> 'string' or (y #>> '{}') !~ '^([0-9a-f]{64}|rec_[0-9A-HJKMNP-TV-Z]{26})$') then true
        when exists (select 1 from jsonb_array_elements(x.e -> 'entity_ids') y
                     where jsonb_typeof(y) <> 'string' or (y #>> '{}') !~ '^ent_[0-9A-HJKMNP-TV-Z]{26}$') then true
        when exists (select 1 from jsonb_array_elements(x.e -> 'anchor_ids') y
                     where jsonb_typeof(y) <> 'string' or (y #>> '{}') !~ '^pan_[0-9A-HJKMNP-TV-Z]{26}$') then true
        when serve_mirror.section <> 'entities' and jsonb_array_length(x.e -> 'anchor_ids') > 0 then true
        when x.e ? 'source' and jsonb_typeof(x.e -> 'source') <> 'string' then true
        when x.e ? 'member_ids' and jsonb_typeof(x.e -> 'member_ids') <> 'array' then true
        when x.e ? 'contact_evidence_ids' and jsonb_typeof(x.e -> 'contact_evidence_ids') <> 'array' then true
        when exists (select 1 from jsonb_array_elements(coalesce(x.e -> 'member_ids', '[]'::jsonb)) y
                     where jsonb_typeof(y) <> 'string' or (y #>> '{}') !~ '^ent_[0-9A-HJKMNP-TV-Z]{26}$') then true
        when exists (select 1 from jsonb_array_elements(coalesce(x.e -> 'contact_evidence_ids', '[]'::jsonb)) y
                     where jsonb_typeof(y) <> 'string' or (y #>> '{}') !~ '^[0-9a-f]{64}$') then true
        when x.e ? 'claim_evidence_ids' and jsonb_typeof(x.e -> 'claim_evidence_ids') <> 'array' then true
        when exists (select 1 from jsonb_array_elements(coalesce(x.e -> 'claim_evidence_ids', '[]'::jsonb)) y
                     where jsonb_typeof(y) <> 'string' or (y #>> '{}') !~ '^[0-9a-f]{64}$') then true
        when serve_mirror.section <> 'entities'
          and (jsonb_array_length(coalesce(x.e -> 'member_ids', '[]'::jsonb)) > 0 or jsonb_array_length(coalesce(x.e -> 'contact_evidence_ids', '[]'::jsonb)) > 0
               or jsonb_array_length(coalesce(x.e -> 'claim_evidence_ids', '[]'::jsonb)) > 0) then true
        when x.e ? 'drop' and jsonb_typeof(x.e -> 'drop') <> 'boolean' then true
        else false
      end)
       or (select count(distinct x.e ->> 'key') from jsonb_array_elements(serve_mirror.entries) as x (e)) <> jsonb_array_length(serve_mirror.entries)
       or (select count(distinct x.e ->> 'id') from jsonb_array_elements(serve_mirror.entries) as x (e)) <> jsonb_array_length(serve_mirror.entries) then
      raise exception 'serve_mirror_entries' using errcode = '23514', constraint = 'serve_mirror_entries';
    end if;
  end if;

  select c.* into v_latest from ledger.mirror_cursors c
  where c.client_id = v_caller and not exists (select 1 from ledger.mirror_cursors d where d.client_id = v_caller and d.prior_id = c.id)
  limit 1;
  if serve_mirror.cursor_id is null then
    v_standing := 'none';
  elsif v_latest.id = serve_mirror.cursor_id then
    v_standing := 'latest';
    v_at := v_latest;
  elsif v_latest.prior_id = serve_mirror.cursor_id then
    select c.* into v_at from ledger.mirror_cursors c where c.client_id = v_caller and c.id = serve_mirror.cursor_id;
    if found then
      v_standing := 'prior';
    end if;
  end if;
  if v_standing is null then
    raise exception 'serve_mirror_cursor' using errcode = '23514', constraint = 'serve_mirror_cursor';
  end if;

  v_new_pass := v_standing = 'none' or (v_at.section is null and serve_mirror.section is not null);
  if v_new_pass then
    if v_standing = 'none' then
      select coalesce(max(c.pass), 0) + 1 into v_pass from ledger.mirror_cursors c where c.client_id = v_caller;
      v_rebuilt_at := case when coalesce(serve_mirror.rebuild, false) then now() end;
    else
      v_pass := v_at.pass + 1;
      v_rebuilt_at := case when coalesce(serve_mirror.rebuild, false) then now() else v_at.rebuilt_at end;
    end if;
    v_rebuild := coalesce(serve_mirror.rebuild, false);
  else
    v_pass := v_at.pass;
    v_rebuild := v_at.rebuild;
    v_rebuilt_at := v_at.rebuilt_at;
  end if;
  if serve_mirror.section is not null then
    if serve_mirror.section is distinct from (case when v_new_pass then 'entities' else v_at.section end) then
      raise exception 'serve_mirror_section' using errcode = '23514', constraint = 'serve_mirror_section';
    end if;
    if serve_mirror.after_key is distinct from (case when v_new_pass then null else v_at.after_key end) then
      raise exception 'serve_mirror_after_key' using errcode = '23514', constraint = 'serve_mirror_after_key';
    end if;
  end if;

  for v_e in select x.e from jsonb_array_elements(serve_mirror.entries) as x (e) loop
    v_key := v_e.e ->> 'key';
    v_evidence := '{}'::text[];
    v_entities := '{}'::text[];
    v_label := null;
    v_anchors := array(select y #>> '{}' from jsonb_array_elements(v_e.e -> 'anchor_ids') as y);
    if serve_mirror.section = 'entities' then
      v_kind := null;
      select n.kind into v_kind from knowledge.entities n where n.id = v_key;
      v_members := array(select d.x from (select y.x from jsonb_array_elements_text(coalesce(v_e.e -> 'member_ids', '[]'::jsonb)) as y (x)
                                          union select v_key) d (x) order by d.x collate "C");
      v_contacts := array(select d.x from (select distinct y.x from jsonb_array_elements_text(coalesce(v_e.e -> 'contact_evidence_ids', '[]'::jsonb)) as y (x)) d (x)
                          order by d.x collate "C");
      v_claimed := array(select d.x from (select distinct y.x from jsonb_array_elements_text(coalesce(v_e.e -> 'claim_evidence_ids', '[]'::jsonb)) as y (x)) d (x)
                         order by d.x collate "C");
      if (v_kind <> 'person' and cardinality(v_members) > 1) or (v_kind not in ('person', 'organization') and cardinality(v_contacts) > 0)
         or (v_kind <> 'organization' and cardinality(v_claimed) > 0) then
        raise exception 'serve_mirror_entries' using errcode = '23514', constraint = 'serve_mirror_entries';
      end if;
      if v_kind = 'project' then
        select p.compartments into v_label from knowledge.projects p where p.id = v_key;
        if v_label is null then
          raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
        end if;
        if not (v_label <@ v_clearance) then
          raise exception 'not within the clearance' using errcode = '42501';
        end if;
        if cardinality(v_anchors) > 0 then
          select count(*)::integer, coalesce(bool_or(not (pa.compartments <@ v_clearance)), false),
                 coalesce(bool_or(pa.project_id <> v_key or pa.lifted_at is not null or pa.value_enc is null), false)
            into v_count, v_hidden, v_off
            from knowledge.project_anchors pa where pa.id = any (v_anchors);
          if v_hidden then
            raise exception 'not within the clearance' using errcode = '42501';
          end if;
          if v_off or v_count <> (select count(distinct a) from unnest(v_anchors) a) then
            raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
          end if;
        end if;
      elsif v_kind in ('person', 'organization') then
        if cardinality(v_anchors) > 0 then
          raise exception 'serve_mirror_entries' using errcode = '23514', constraint = 'serve_mirror_entries';
        end if;
        if (select count(*) from knowledge.entities n where n.id = any (v_members)) <> cardinality(v_members) then
          raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
        end if;
        if cardinality(v_members) > 1 and exists (select 1 from knowledge.entities n where n.id = any (v_members) and n.kind <> 'person') then
          raise exception 'serve_mirror_entries' using errcode = '23514', constraint = 'serve_mirror_entries';
        end if;
        if exists (select 1 from unnest(v_members) as u (x)
                   where not exists (select 1 from knowledge.accounts a where a.entity_id = u.x and policy.label_key(a.compartments) = any (v_keys))
                     and not exists (select 1 from knowledge.domains dm where dm.entity_id = u.x and policy.label_key(dm.compartments) = any (v_keys))) then
          raise exception 'not within the clearance' using errcode = '42501';
        end if;
        v_label := array(select distinct u.x from knowledge.accounts a cross join lateral unnest(a.compartments) as u (x)
                         where a.entity_id = any (v_members) and policy.label_key(a.compartments) = any (v_keys))
                || array(select distinct u.x from knowledge.domains dm cross join lateral unnest(dm.compartments) as u (x)
                         where dm.entity_id = any (v_members) and policy.label_key(dm.compartments) = any (v_keys))
                || array(select distinct u.x from knowledge.aliases al cross join lateral unnest(al.compartments) as u (x)
                         where al.entity_id = any (v_members) and policy.label_key(al.compartments) = any (v_keys));
        v_evidence := array(select distinct al.evidence_id from knowledge.aliases al
                            where al.entity_id = any (v_members) and policy.label_key(al.compartments) = any (v_keys));
        if cardinality(v_contacts) > 0 then
          select count(*)::integer, coalesce(bool_or(not (policy.label_key(v.compartments) = any (v_keys))), false) into v_count, v_hidden
            from vault.evidence_items v where v.id = any (v_contacts) and v.source_kind = 'crm';
          if v_hidden then
            raise exception 'not within the clearance' using errcode = '42501';
          end if;
          if v_count <> cardinality(v_contacts) then
            raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
          end if;
          v_label := v_label || array(select distinct u.x from vault.evidence_items v cross join lateral unnest(v.compartments) as u (x)
                                      where v.id = any (v_contacts) and policy.label_key(v.compartments) = any (v_keys));
          v_evidence := v_evidence || v_contacts;
        end if;
        if cardinality(v_claimed) > 0 then
          select count(*)::integer, coalesce(bool_or(not (policy.label_key(v.compartments) = any (v_keys))), false) into v_count, v_hidden
            from vault.evidence_items v where v.id = any (v_claimed);
          if v_hidden then
            raise exception 'not within the clearance' using errcode = '42501';
          end if;
          if v_count <> cardinality(v_claimed) then
            raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
          end if;
          v_label := v_label || array(select distinct u.x from vault.evidence_items v cross join lateral unnest(v.compartments) as u (x)
                                      where v.id = any (v_claimed) and policy.label_key(v.compartments) = any (v_keys));
          v_evidence := v_evidence || v_claimed;
        end if;
        v_evidence := array(select d.x from (select distinct u.x from unnest(v_evidence) as u (x)) d (x) order by d.x collate "C");
      else
        raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
      end if;
      v_entities := v_members;
    elsif serve_mirror.section = 'beliefs' then
      v_fact := v_e.e ->> 'fact_key_fp';
      v_support := case when jsonb_typeof(v_e.e -> 'support_ids') = 'array'
        then array(select distinct x from jsonb_array_elements_text(v_e.e -> 'support_ids') as u (x)) end;
      if v_support is null or cardinality(v_support) not between 1 and 500 then
        raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
      end if;
      if exists (select 1 from knowledge.claims c where c.id = any (v_support) and not (c.compartments <@ v_clearance)) then
        raise exception 'not within the clearance' using errcode = '42501';
      end if;
      v_claims := array(select c.id from knowledge.claims c
                        where c.id = any (v_support) and c.fact_key_fp = v_fact and policy.label_key(c.compartments) = any (v_keys));
      if cardinality(v_claims) <> cardinality(v_support) then
        raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
      end if;
      v_label := (select ledger.label(array_agg(u.x)) from knowledge.claims c cross join lateral unnest(c.compartments) as u (x)
                  where c.id = any (v_claims));
      v_evidence := array(select d.x from (select distinct c.evidence_id as x from knowledge.claims c
                                           where c.id = any (v_claims) and policy.label_key(c.compartments) = any (v_keys)) d order by d.x collate "C");
      v_entities := array(select d.x from (select distinct n.entity_id as x from knowledge.claim_entities n
                                           where n.claim_id = any (v_claims) and policy.label_key(n.compartments) = any (v_keys)) d order by d.x collate "C");
    elsif serve_mirror.section = 'facts' then
      v_ev := split_part(v_key, ':', 1);
      v_fp := split_part(v_key, ':', 2);
      select v.compartments into v_label from vault.evidence_items v where v.id = v_ev;
      if v_label is null then
        raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
      end if;
      if not (v_label <@ v_clearance) then
        raise exception 'not within the clearance' using errcode = '42501';
      end if;
      if v_fp is distinct from (v_e.e ->> 'fact_key_fp') then
        raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
      end if;
      v_claims := array(select c.id from knowledge.claims c where c.evidence_id = v_ev and c.fact_key_fp = v_fp and policy.label_key(c.compartments) = any (v_keys));
      if cardinality(v_claims) = 0 or (v_e.e ? 'source' and not ((v_e.e ->> 'source') = any (v_claims))) then
        raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
      end if;
      v_label := array(select d.x from (select distinct u.x from knowledge.claims c cross join lateral unnest(c.compartments) as u (x)
                                        where c.id = any (v_claims) and policy.label_key(c.compartments) = any (v_keys)) d order by d.x collate "C");
      v_evidence := array[v_ev];
      v_entities := array(select d.x from (select distinct n.entity_id as x from knowledge.claim_entities n
                                           where n.claim_id = any (v_claims) and policy.label_key(n.compartments) = any (v_keys)) d order by d.x collate "C");
    elsif serve_mirror.section = 'events' then
      v_ev := null;
      select ev.evidence_id, ev.compartments into v_ev, v_label from knowledge.events ev where ev.id = v_key;
      if v_label is null then
        raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
      end if;
      if not (v_label <@ v_clearance) then
        raise exception 'not within the clearance' using errcode = '42501';
      end if;
      v_evidence := array[v_ev];
      v_entities := array(select d.x from (select distinct ep.entity_id as x from knowledge.event_participants ep
                                           where ep.event_id = v_key and policy.label_key(ep.compartments) = any (v_keys)) d order by d.x collate "C");
    else
      v_ev := null;
      select x.evidence_id, x.compartments into v_ev, v_label from knowledge.captures x where x.id = v_key;
      if v_label is null then
        raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
      end if;
      if not (v_label <@ v_clearance) then
        raise exception 'not within the clearance' using errcode = '42501';
      end if;
      v_evidence := case when v_ev is null then '{}'::text[] else array[v_ev] end;
    end if;
    if array(select d.x from (select distinct y.x from jsonb_array_elements_text(v_e.e -> 'evidence_ids') as y (x)) d order by d.x collate "C") is distinct from v_evidence
       or array(select d.x from (select distinct y.x from jsonb_array_elements_text(v_e.e -> 'entity_ids') as y (x)) d order by d.x collate "C") is distinct from v_entities then
      raise exception 'serve_mirror_stale' using errcode = '23514', constraint = 'serve_mirror_stale';
    end if;
    v_label := array(select d.x from (select distinct u.x from unnest(v_label) as u (x)) d order by d.x collate "C");
    v_checked := v_checked || jsonb_build_array(jsonb_build_object(
      'id', v_e.e ->> 'id', 'key', v_key, 'fact', v_e.e -> 'fact_key_fp', 'state', v_e.e ->> 'state', 'token', v_e.e ->> 'token',
      'evidence', to_jsonb(v_evidence), 'entities', to_jsonb(v_entities), 'label', to_jsonb(v_label),
      'dropped', coalesce((v_e.e ->> 'drop')::boolean, false)));
  end loop;

  update ledger.mirror_entries m set ended_at = now(), reason = 'replaced'
  where m.client_id = v_caller and m.ended_at is null and (m.audience is distinct from v_audience or m.template <> serve_mirror.template);

  if v_standing = 'latest' then
    update ledger.mirror_entries m set confirmed_state = m.sent_state, confirmed_token = m.sent_token
    where m.client_id = v_caller and m.id = any (v_at.page_ids) and m.ended_at is null and m.sent_token is not null
      and (m.confirmed_state is distinct from m.sent_state or m.confirmed_token is distinct from m.sent_token);
    update ledger.mirror_entries m set end_confirmed_at = now()
    where m.client_id = v_caller and m.id = any (v_at.page_ids) and m.ended_at is not null and m.end_sent_at is not null and m.end_confirmed_at is null;
  elsif v_standing = 'none' then
    update ledger.mirror_entries m set confirmed_state = null, confirmed_token = null
    where m.client_id = v_caller and (m.confirmed_state is not null or m.confirmed_token is not null);
  end if;
  update ledger.capture_erasures x set confirmed_at = now()
  where x.client_id = v_caller and x.confirmed_at is null and x.capture_key = any (serve_mirror.erased_done);

  delete from ledger.capture_erasures x where x.client_id = v_caller and x.confirmed_at < now() - interval '30 days';
  delete from ledger.mirror_entries m
  where m.client_id = v_caller and m.ended_at is not null and m.end_confirmed_at < now() - interval '30 days'
    and not exists (select 1 from ledger.erasure_exposures l where l.mirror_entry_id = m.id);

  if serve_mirror.section is not null then
    select count(*)::integer, coalesce(bool_or(m.reason = 'replaced'), false) into v_count, v_hold
      from ledger.mirror_entries m where m.client_id = v_caller and m.ended_at is not null and m.end_confirmed_at is null;
    v_hold := v_hold and v_count > serve_mirror.removal_limit;
  end if;

  if serve_mirror.section is not null and not v_hold then
    update ledger.mirror_entries m set ended_at = now(), reason = 'withdrawn'
    where m.client_id = v_caller and m.ended_at is null and m.section = serve_mirror.section
      and (serve_mirror.after_key is null or m.entry_key > (serve_mirror.after_key collate "C"))
      and (serve_mirror.last_key is null or m.entry_key <= (serve_mirror.last_key collate "C"))
      and not (m.entry_key = any (serve_mirror.found_keys));

    v_oversize := array(select c.key from jsonb_to_recordset(v_checked) as c (key text, dropped boolean) where c.dropped);
    update ledger.mirror_entries m set ended_at = now(), reason = 'dropped'
    where m.client_id = v_caller and m.section = serve_mirror.section and m.ended_at is null and m.entry_key = any (v_oversize);

    v_over := array(
      select r.k from (
        select u.k, row_number() over (order by u.k collate "C") as n
        from (select m.entry_key as k from ledger.mirror_entries m
              where m.client_id = v_caller and m.section = serve_mirror.section and m.ended_at is null
              union
              select c.key from jsonb_to_recordset(v_checked) as c (key text, dropped boolean) where not c.dropped) as u (k)
      ) r
      where r.n > serve_mirror.section_cap
        and (serve_mirror.after_key is null or r.k > (serve_mirror.after_key collate "C"))
        and (serve_mirror.last_key is null or r.k <= (serve_mirror.last_key collate "C")));
    v_truncated := cardinality(v_over) > 0;
    update ledger.mirror_entries m set ended_at = now(), reason = 'dropped'
    where m.client_id = v_caller and m.section = serve_mirror.section and m.ended_at is null and m.entry_key = any (v_over);
    v_over := v_over || v_oversize;

    if exists (select 1 from jsonb_to_recordset(v_checked) as c (id text, key text) join ledger.mirror_entries m on m.id = c.id
               where m.client_id <> v_caller or m.section <> serve_mirror.section or m.entry_key <> c.key
                  or m.template <> serve_mirror.template or m.audience is distinct from v_audience)
       or exists (select 1 from jsonb_to_recordset(v_checked) as c (id text, key text) join ledger.mirror_entries m
                    on m.client_id = v_caller and m.section = serve_mirror.section and m.entry_key = c.key and m.ended_at is null and m.id <> c.id
                  where not (c.key = any (v_over))) then
      raise exception 'not this client''s projection' using errcode = '42501';
    end if;

    insert into ledger.mirror_entries as m (id, client_id, audience, template, section, entry_key, fact_key_fp, sent_state, sent_token,
                                            evidence_ids, entity_ids, compartments, first_served_at, last_sent_at)
    select c.id, v_caller, v_audience, serve_mirror.template, serve_mirror.section, c.key, c.fact, c.state, c.token,
           c.evidence, c.entities, c.label, now(), now()
    from jsonb_to_recordset(v_checked) as c (id text, key text, fact text, state text, token text, evidence text[], entities text[], label text[])
    where not (c.key = any (v_over))
    on conflict (id) do update set
      fact_key_fp = excluded.fact_key_fp,
      compartments = excluded.compartments,
      evidence_ids = array(select d.x from (select distinct u.x from unnest(m.evidence_ids || excluded.evidence_ids) as u (x)) d order by d.x collate "C"),
      entity_ids = array(select d.x from (select distinct u.x from unnest(m.entity_ids || excluded.entity_ids) as u (x)) d order by d.x collate "C"),
      confirmed_state = case when m.ended_at is null then m.confirmed_state end,
      confirmed_token = case when m.ended_at is null then m.confirmed_token end,
      last_tainted_at = coalesce(m.tainted_at, m.last_tainted_at),
      ended_at = null,
      reason = null,
      end_sent_at = null,
      end_confirmed_at = null,
      tainted_at = null
    where m.client_id = v_caller;

    select coalesce(array_agg(m.id order by m.entry_key collate "C"), '{}'::text[]),
           coalesce(array_agg(m.entry_key order by m.entry_key collate "C"), '{}'::text[]),
           coalesce(array_agg(c.state order by m.entry_key collate "C"), '{}'::text[])
      into v_sent_ids, v_sent_keys, v_sent_states
      from jsonb_to_recordset(v_checked) as c (id text, state text) join ledger.mirror_entries m on m.id = c.id
      where m.client_id = v_caller and m.ended_at is null and m.confirmed_state is distinct from c.state;
    update ledger.mirror_entries m set sent_state = c.state, sent_token = c.token, last_sent_at = now()
    from jsonb_to_recordset(v_checked) as c (id text, state text, token text)
    where m.id = c.id and m.client_id = v_caller and m.id = any (v_sent_ids);
    update ledger.mirror_entries m set confirmed_token = c.token
    from jsonb_to_recordset(v_checked) as c (id text, state text, token text)
    where m.id = c.id and m.client_id = v_caller and m.ended_at is null and m.confirmed_state = c.state and not (m.id = any (v_sent_ids))
      and m.confirmed_token is distinct from c.token;
  end if;

  select coalesce(array_agg(r.id order by r.n), '{}'::text[]), coalesce(array_agg(r.reason order by r.n), '{}'::text[]),
         coalesce(array_agg(r.at order by r.n), '{}'::timestamptz[])
    into v_rem_ids, v_rem_reasons, v_rem_at
    from (select m.id, m.reason, m.ended_at as at, row_number() over (order by m.ended_at, m.id collate "C") as n
          from ledger.mirror_entries m
          where m.client_id = v_caller and m.ended_at is not null and m.end_confirmed_at is null
          order by m.ended_at, m.id collate "C"
          limit serve_mirror.removal_limit) r;
  update ledger.mirror_entries m set end_sent_at = now() where m.client_id = v_caller and m.id = any (v_rem_ids);
  v_erased := array(select x.capture_key from ledger.capture_erasures x where x.client_id = v_caller and x.confirmed_at is null
                    order by x.erased_at, x.id limit 500);

  v_last_completed := case when v_standing = 'none' then v_latest.last_completed_at else v_at.last_completed_at end;
  if serve_mirror.section is null or v_hold then
    if v_standing = 'none' then
      v_next_section := 'entities';
    else
      v_pass := v_at.pass;
      v_rebuild := v_at.rebuild;
      v_rebuilt_at := v_at.rebuilt_at;
      v_next_section := v_at.section;
      v_next_after := v_at.after_key;
      v_completed_at := v_at.completed_at;
    end if;
  elsif serve_mirror.last_key is not null then
    v_next_section := serve_mirror.section;
    v_next_after := serve_mirror.last_key;
  elsif serve_mirror.section = 'captures' then
    v_completed_at := now();
    v_last_completed := v_completed_at;
  else
    v_next_section := (array['entities', 'beliefs', 'facts', 'events', 'captures'])[array_position(array['entities', 'beliefs', 'facts', 'events', 'captures'], serve_mirror.section) + 1];
  end if;

  v_new := ledger.new_id('mcr');
  insert into ledger.mirror_cursors (id, client_id, pass, rebuild, section, after_key, completed_at, last_completed_at, rebuilt_at, prior_id, page_ids, erased_keys, issued_at)
  values (v_new, v_caller, v_pass, v_rebuild, v_next_section, v_next_after, v_completed_at, v_last_completed, v_rebuilt_at, serve_mirror.cursor_id,
          v_rem_ids || v_sent_ids, v_erased, now());
  delete from ledger.mirror_cursors c where c.client_id = v_caller and c.id <> v_new and c.id is distinct from serve_mirror.cursor_id;

  return query
    select 'removal'::text, r.id, null::text, null::text, r.reason, r.at, null::text, null::text, null::integer, null::boolean, null::boolean
    from unnest(v_rem_ids, v_rem_reasons, v_rem_at) with ordinality as r (id, reason, at, n) order by r.n;
  return query
    select 'erased'::text, null::text, null::text, null::text, null::text, null::timestamptz, r.k, null::text, null::integer, null::boolean, null::boolean
    from unnest(v_erased) with ordinality as r (k, n) order by r.n;
  return query
    select 'entry'::text, r.id, r.k, r.s, null::text, null::timestamptz, null::text, null::text, null::integer, null::boolean, null::boolean
    from unnest(v_sent_ids, v_sent_keys, v_sent_states) with ordinality as r (id, k, s, n) order by r.n;
  return query
    select 'cursor'::text, null::text, null::text, null::text, null::text, null::timestamptz, null::text, v_new, v_pass, v_next_section is null, v_truncated;
end
$_$;

CREATE FUNCTION policy.set_lever(key text, value jsonb, reason text, measure text, request_id text, session_id text) RETURNS TABLE(set_key text, set_value jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $_$
#variable_conflict use_column
declare
  v_author text;
  v_old jsonb;
begin
  select 'client:' || c.client_id into v_author from ledger.agent_mail_caller('set_lever', set_lever.session_id) c;
  if set_lever.key is null or set_lever.value is null or set_lever.reason is null or set_lever.measure is null
     or set_lever.request_id is null or set_lever.request_id !~ '^[A-Za-z0-9_-]{8,64}$'
     or set_lever.key !~ '^[a-z][a-z0-9_]{0,31}(\.[a-z][a-z0-9_]{0,31}){1,2}$'
     or set_lever.reason !~ '^[a-z][a-z0-9_]{0,63}$' or set_lever.measure !~ '^[a-z][a-z0-9_]{0,63}$'
     or not (jsonb_typeof(set_lever.value) = 'number'
             or (jsonb_typeof(set_lever.value) = 'string' and set_lever.value #>> '{}' ~ '^[a-z][a-z0-9_]{0,63}$')) then
    raise exception 'invalid request' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('policy setting ' || set_lever.key, 0));
  return query select c.key, c.new_value from policy.setting_changes c
    where c.changed_by = v_author and c.request_id = set_lever.request_id;
  if found then
    return;
  end if;
  select s.value into v_old from policy.settings s where s.key = set_lever.key;
  if v_old is not distinct from set_lever.value then
    return query select set_lever.key, set_lever.value;
    return;
  end if;
  insert into policy.settings (key, value, updated_at, updated_by)
  values (set_lever.key, set_lever.value, now(), v_author)
  on conflict (key) do update set value = excluded.value, updated_at = excluded.updated_at, updated_by = excluded.updated_by;
  insert into policy.setting_changes (key, old_value, new_value, changed_by, request_id, reason, measure)
  values (set_lever.key, v_old, set_lever.value, v_author, set_lever.request_id, set_lever.reason, set_lever.measure);
  return query select set_lever.key, set_lever.value;
end
$_$;

CREATE FUNCTION policy.settled_records(p_state text, p_limit integer) RETURNS TABLE(record_id text, kind text, answer text, settled_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_caller text;
  v_views text[];
  v_tools text[];
  v_clearance text[];
  v_keys text[];
  v_view_keys text[];
begin
  select c.id, c.views, c.tools into v_caller, v_views, v_tools from policy.current_client() c;
  if v_caller is null or not ('get_suggestions' = any (v_tools)) or not ('work' = any (v_views)) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if settled_records.p_state is null or settled_records.p_state not in ('open', 'closed', 'any') or settled_records.p_limit is null or settled_records.p_limit < 1 or settled_records.p_limit > 51 then
    raise exception 'invalid argument' using errcode = '22023';
  end if;
  if settled_records.p_state = 'open' then
    return;
  end if;
  v_keys := policy.clearance_keys();
  v_clearance := policy.client_clearance();
  v_view_keys := policy.view_keys();
  return query
    with mine as (
      select w.id, w.kind, w.evidence_id
      from ledger.agent_writes w
      where w.client_id = v_caller and w.kind in ('proposal', 'finding') and w.evidence_id is not null
        and w.tainted_at is null and w.flagged_at is null and w.body_enc is not null
        and w.compartments <@ v_clearance and policy.label_key(w.compartments) = any (v_keys)
        and w.writer_views <@ v_views and policy.label_key(w.writer_views) = any (v_view_keys)
    ),
    seen as (
      select m.id, m.kind, s.claim_key, s.answer, s.created_at, s.id as settlement, s.card_id, s.match_fp, s.reopened_at
      from mine m
      join ledger.fact_settlements s on s.evidence_id = m.evidence_id
      join ledger.cards c on c.id = s.card_id
      where c.compartments <@ v_clearance and policy.label_key(c.compartments) = any (v_keys)
    ),
    latest as (
      select distinct on (x.claim_key) x.*
      from seen x
      order by x.claim_key, x.created_at desc, x.settlement collate "C" desc
    ),
    told as (
      select distinct on (l.id, l.answer) l.id, l.kind, l.answer, l.created_at
      from latest l join ledger.cards c on c.id = l.card_id
      where l.answer in ('confirmed', 'rejected') and l.reopened_at is null and c.tainted_at is null
        and exists (select 1 from knowledge.owner_decisions o
                    where o.card_id = l.card_id and o.kind = 'answer' and o.tainted_at is null
                      and o.answer = case l.answer when 'confirmed' then 'confirm' else 'reject' end
                      and not exists (select 1 from knowledge.owner_decisions d where d.supersedes = o.id))
        and not exists (select 1 from knowledge.belief_rulings b where b.verdict in ('veto', 'retire') and b.lifted_at is null and b.fact_key_fp = l.match_fp)
      order by l.id, l.answer, l.created_at desc
    )
    select t.id, t.kind, t.answer, t.created_at from told t
    order by t.created_at desc, t.id collate "C" desc, t.answer
    limit settled_records.p_limit;
end
$$;

CREATE FUNCTION policy.tier_rulings_in(p_clearance text[]) RETURNS TABLE(entity_id text, tier text, ruled_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select distinct on (a.entity_id) a.entity_id, r.tier, r.created_at
  from knowledge.tier_rulings r
  cross join unnest(r.value_fps) as f (fp)
  join knowledge.accounts a on a.value_fp = f.fp and a.compartments <@ p_clearance
  join knowledge.entities e on e.id = a.entity_id and e.kind = 'person'
  where r.lifted_at is null
  order by a.entity_id, r.created_at desc, r.ruling_id collate "C" desc
$$;

CREATE FUNCTION policy.vetoed(ref_kinds text[], ref_ids text[], work_kind text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  select policy.vetoed_by(vetoed.ref_kinds, vetoed.ref_ids, vetoed.work_kind) is not null
$$;

CREATE FUNCTION policy.vetoed_by(ref_kinds text[], ref_ids text[], work_kind text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with recursive live as (
    select v.ruling_id, v.subject, v.value_fps, v.created_at
    from knowledge.vetoes v
    where v.lifted_at is null and (v.work_kind is null or v.work_kind = vetoed_by.work_kind)
  ),
  owned as (
    select a.value_fp from knowledge.accounts a join knowledge.entities e on e.id = a.entity_id where e.kind = 'owner'
  ),
  joined (ruling_id, fp) as (
    select v.ruling_id, one.fp from live v cross join unnest(v.value_fps) as one (fp) where v.subject = 'person'
    union
    select j.ruling_id, case when r.a_fp = j.fp then r.b_fp else r.a_fp end
    from joined j
    join knowledge.identity_rulings r on r.verdict = 'same' and r.lifted_at is null and (r.a_fp = j.fp or r.b_fp = j.fp)
    where not exists (select 1 from owned o where o.value_fp = r.a_fp or o.value_fp = r.b_fp)
  ),
  refs as (
    select r.kind, r.id from unnest(vetoed_by.ref_kinds, vetoed_by.ref_ids) as r (kind, id)
    where r.kind in ('message', 'event', 'entity', 'address', 'domain') and r.id is not null
  ),
  named as (
    select r.id as entity_id from refs r where r.kind = 'entity'
    union
    select i.entity_id from refs r
      join knowledge.messages m on m.id = r.id
      join knowledge.interaction_log i on i.evidence_id = m.evidence_id
    where r.kind = 'message'
    union
    select p.entity_id from refs r join knowledge.event_participants p on p.event_id = r.id where r.kind = 'event'
  ),
  hits as (
    select v.ruling_id, v.created_at from live v where v.subject = 'any' and exists (select 1 from refs)
    union all
    select v.ruling_id, v.created_at
    from live v
    join named n on true
    join knowledge.entities e on e.id = n.entity_id and e.kind <> 'owner'
    where (v.subject = 'person' and e.kind = 'person'
           and exists (select 1 from knowledge.accounts a join joined j on j.fp = a.value_fp
                       where a.entity_id = e.id and j.ruling_id = v.ruling_id))
       or (v.subject = 'organization' and e.kind = 'person'
           and exists (select 1 from knowledge.accounts a where a.entity_id = e.id and a.domain_fp = any (v.value_fps)))
       or (v.subject = 'organization' and e.kind = 'organization'
           and exists (select 1 from knowledge.domains d where d.entity_id = e.id and d.domain_fp = any (v.value_fps)))
    union all
    select v.ruling_id, v.created_at
    from live v
    join refs r on r.kind = 'message'
    join knowledge.messages m on m.id = r.id and m.direction = 'inbound'
    where (v.subject = 'person' and exists (select 1 from joined j where j.ruling_id = v.ruling_id and j.fp = m.sender_fp))
       or (v.subject = 'organization' and m.sender_domain_fp = any (v.value_fps))
    union all
    select v.ruling_id, v.created_at
    from live v
    join refs r on (r.kind = 'address' and v.subject = 'person') or (r.kind = 'domain' and v.subject = 'organization')
    where (v.subject = 'person' and exists (select 1 from joined j where j.ruling_id = v.ruling_id and j.fp = r.id))
       or (v.subject = 'organization' and r.id = any (v.value_fps))
  )
  select h.ruling_id from hits h order by h.created_at, h.ruling_id collate "C" limit 1
$$;

CREATE FUNCTION policy.view_keys() RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with one as (
    select x.one, (row_number() over (order by x.one collate "C"))::integer - 1 as bit
    from (select distinct v collate "C" as one from policy.current_client() c join policy.clients k on k.id = c.id cross join lateral unnest(c.views) as v
          where k.kind <> 'device') x
  ),
  n as (select count(*)::integer as n from one)
  select coalesce(array_agg(s.key order by s.key collate "C"), '{}'::text[])
  from n cross join lateral generate_series(1, case when n.n between 1 and 10 then (1 << n.n) - 1 else 0 end) as m (mask)
  cross join lateral (select string_agg(o.one, '|' order by o.one collate "C") as key from one o where (m.mask >> o.bit) & 1 = 1) s
$$;

CREATE FUNCTION policy.warmth_ignored() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if cardinality(policy.clearance_keys()) = 0 then
    return '{}'::text[];
  end if;
  return policy.ignored_people_in(policy.client_clearance());
end
$$;

CREATE FUNCTION policy.warmth_rulings() RETURNS TABLE(entity_id text, tier text, ruled_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
begin
  if cardinality(policy.clearance_keys()) = 0 then
    return;
  end if;
  return query select * from policy.tier_rulings_in(policy.client_clearance());
end
$$;

CREATE FUNCTION policy.withheld_entities() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_keys text[];
  v_clearance text[];
  v_out text[];
begin
  v_keys := policy.clearance_keys();
  v_clearance := policy.client_clearance();
  with live as (select r.subject, r.value_fps, r.address_fps from knowledge.ignore_rulings r where r.lifted_at is null),
  owner_fps as (
    select a.value_fp from knowledge.accounts a
    where a.entity_id = (select e.id from knowledge.entities e where e.kind = 'owner')
      and policy.label_key(a.compartments) = any (v_keys) and a.compartments <@ v_clearance),
  people as (
    select u.entity_id from knowledge.accounts u
    where u.kind in ('role', 'bulk') and policy.label_key(u.compartments) = any (v_keys) and u.compartments <@ v_clearance
      and not exists (
        select 1 from knowledge.accounts a
        where policy.label_key(a.compartments) = any (v_keys) and a.entity_id = u.entity_id
          and a.compartments <@ v_clearance and a.kind in ('email', 'shared'))
    union
    select a.entity_id from owner_fps o, knowledge.accounts a
    where policy.label_key(a.compartments) = any (v_keys) and a.value_fp = o.value_fp and a.compartments <@ v_clearance
    union
    select a.entity_id from live r, unnest(r.value_fps) as f (fp), knowledge.accounts a
    where r.subject = 'address' and policy.label_key(a.compartments) = any (v_keys) and a.value_fp = f.fp
      and a.compartments <@ v_clearance
    union
    select a.entity_id from live r, unnest(r.value_fps) as f (fp), knowledge.accounts a
    where r.subject = 'domain' and policy.label_key(a.compartments) = any (v_keys) and a.domain_fp = f.fp
      and a.compartments <@ v_clearance
    union
    select a.entity_id from live r, unnest(r.address_fps) as f (fp), knowledge.accounts a
    where r.subject = 'domain' and policy.label_key(a.compartments) = any (v_keys) and a.value_fp = f.fp
      and a.compartments <@ v_clearance),
  orgs as (
    select d.entity_id from live r, unnest(r.value_fps) as f (fp), knowledge.domains d
    where r.subject = 'domain' and policy.label_key(d.compartments) = any (v_keys) and d.domain_fp = f.fp
      and d.compartments <@ v_clearance)
  select coalesce(array_agg(distinct w.id), '{}'::text[]) into v_out from (
    select p.entity_id as id from people p join knowledge.entities e on e.id = p.entity_id and e.kind = 'person'
    union
    select o.entity_id from orgs o join knowledge.entities e on e.id = o.entity_id and e.kind = 'organization') w;
  return v_out;
end
$$;

CREATE FUNCTION policy.withheld_items(ids text[]) RETURNS TABLE(evidence_id text, withheld boolean, screened boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
#variable_conflict use_column
begin
  if cardinality(ids) > 1000 then
    raise exception 'too many ids' using errcode = '22023';
  end if;
  return query
    select p.evidence_id, p.withheld, p.screened from vault.pipeline_items p
    where p.evidence_id = any (withheld_items.ids) and not p.waiting;
end
$$;

CREATE FUNCTION policy.write_typed_claims(p_session_id text, p_record_id text, p_evidence jsonb, p_claims jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  v_caller text;
  v_name text;
  v_tools text[];
  v_clearance text[];
  v_keys text[];
  v_record record;
  v_account text;
  v_evidence_id text;
  v_claim jsonb;
  v_refused jsonb := '[]'::jsonb;
  v_duplicates jsonb := '[]'::jsonb;
  v_known jsonb := '[]'::jsonb;
  v_read text[] := '{}';
  v_subjects text[];
  v_subject text;
  v_fks text[];
  v_match text;
  v_match_fp text;
  v_reply jsonb;
  v_bound text[] := '{}';
begin
  perform pg_advisory_xact_lock_shared(hashtext('intelligence personal ledger taint'));
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'a typed write runs read committed' using errcode = '42501';
  end if;
  select c.id, c.name, c.tools into v_caller, v_name, v_tools from policy.current_client() c;
  if v_caller is null or not ('record' = any (v_tools)) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_clearance := policy.client_clearance();
  v_keys := policy.clearance_keys();
  select w.id, w.compartments, w.evidence_id, w.typed_reply, w.content_fp, w.created_at, w.project_id into v_record
  from ledger.agent_writes w
  where w.id = write_typed_claims.p_record_id and w.client_id = v_caller
    and w.tool = 'record' and w.kind = 'finding' and w.body_enc is not null
    and w.compartments <@ v_clearance and policy.label_key(w.compartments) = any (v_keys)
  for update;
  if not found then
    raise exception 'not this client''s finding' using errcode = '42501';
  end if;
  if v_record.typed_reply is not null then
    return v_record.typed_reply;
  end if;
  if v_record.created_at <> now() or not exists (select 1 from ledger.agent_writes w where w.id = v_record.id and w.session_id = write_typed_claims.p_session_id) then
    raise exception 'not a finding of this call' using errcode = '42501';
  end if;
  select a.id into v_account from vault.source_accounts a where a.label = 'agent:' || v_name and a.connector = 'agent';
  if p_evidence is null then
    return jsonb_build_object('account', v_account, 'client', v_name, 'recordedAt', v_record.created_at, 'label', to_jsonb(v_record.compartments),
      'labels', (select coalesce(jsonb_agg(to_jsonb(l.compartments) order by l.key collate "C"), '[]'::jsonb) from policy.labels l where l.compartments <@ v_clearance));
  end if;
  if v_account is null or v_record.evidence_id is not null then
    raise exception 'the finding has no account or is taken in' using errcode = '42501';
  end if;

  v_evidence_id := encode(sha256(convert_to(format('["personal",%s,%s,0]', to_json(v_account)::text, to_json('record:' || v_record.id)::text), 'UTF8')), 'hex');
  if p_evidence ->> 'id' is distinct from v_evidence_id then
    raise exception 'not the finding''s evidence id' using errcode = '22023';
  end if;
  insert into vault.evidence_blobs (blob_ref, envelope, compartments)
  values (p_evidence ->> 'blobRef', p_evidence -> 'blob', v_record.compartments);
  insert into vault.evidence_items (id, source_account_id, source_kind, source_item_fp, revision_tag_fp, revision, supersedes, next_revision_id,
    thread_fp, content_hash, media_type, observed_at, change_kind, participant_members, sender_member, system_originated, answers_system,
    hold_released_at, blob_ref, payload_state, compartments, readers, item_enc, typed)
  values (v_evidence_id, v_account, 'agent_record', p_evidence ->> 'sourceItemFp', p_evidence ->> 'revisionTagFp', 0, null, p_evidence ->> 'nextRevisionId',
    null, v_record.content_fp, 'text/plain', v_record.created_at, 'live', '{}', null, false, false,
    null, p_evidence ->> 'blobRef', 'present', v_record.compartments, array['m-owner']::text[], p_evidence -> 'item', true);
  update ledger.agent_writes set evidence_id = v_evidence_id where id = v_record.id;

  v_refused := coalesce(p_claims -> 'refused', '[]'::jsonb);

  v_subjects := array(
    select s.id from (select distinct x ->> 'subject' as id from jsonb_array_elements(coalesce(p_claims -> 'claims', '[]'::jsonb)) x) s
    where exists (
      select 1 from knowledge.entities e
      where e.id = s.id
        and (exists (select 1 from knowledge.accounts a where a.entity_id = e.id and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys))
          or exists (select 1 from knowledge.domains d where d.entity_id = e.id and d.compartments <@ v_clearance and policy.label_key(d.compartments) = any (v_keys))
          or exists (select 1 from knowledge.projects p where p.id = e.id and p.compartments <@ v_clearance and policy.label_key(p.compartments) = any (v_keys)))
        and not (e.id = any (policy.withheld_entities())))
    order by s.id collate "C");
  foreach v_subject in array v_subjects loop
    v_fks := array(
      select k.fp from (
        select distinct c.fact_key_fp as fp from knowledge.claims c
        where c.id in (select n.claim_id from knowledge.claim_entities n where n.entity_id = v_subject and n.compartments <@ v_clearance and policy.label_key(n.compartments) = any (v_keys))
          and c.compartments <@ v_clearance and policy.label_key(c.compartments) = any (v_keys)) k
      order by k.fp collate "C"
      limit 200);
    v_known := v_known || jsonb_build_array(jsonb_build_object('subject', v_subject, 'factKeys', to_jsonb(v_fks)));
    v_read := v_read || v_fks;
  end loop;

  perform pg_advisory_xact_lock(hashtext('intelligence personal typed claim'), hashtext(k.fp))
  from (select distinct x ->> 'factKeyFp' as fp from jsonb_array_elements(coalesce(p_claims -> 'claims', '[]'::jsonb)) x) k
  order by k.fp collate "C";

  for v_claim in select x from jsonb_array_elements(coalesce(p_claims -> 'claims', '[]'::jsonb)) x order by (x ->> 'index')::int loop
    if not coalesce(v_claim ->> 'type' = any (array['goal', 'need', 'capability', 'preference', 'constraint', 'situation', 'view', 'visited', 'role', 'affiliation', 'commitment', 'relationship', 'consent', 'contact_rule']), false)
       and not coalesce(v_claim ->> 'type' in ('project.status', 'project.next_step', 'project.decision'), false) then
      v_refused := v_refused || jsonb_build_array(jsonb_build_object('index', (v_claim ->> 'index')::int, 'code', 'fields_invalid'));
      continue;
    end if;
    if v_claim ->> 'type' in ('project.status', 'project.next_step', 'project.decision')
       and (v_record.project_id is null or v_claim ->> 'subject' is distinct from v_record.project_id) then
      v_refused := v_refused || jsonb_build_array(jsonb_build_object('index', (v_claim ->> 'index')::int, 'code', 'fields_invalid'));
      continue;
    end if;
    if exists (
      select 1 from (select v_claim ->> 'subject' as id union select jsonb_array_elements_text(v_claim -> 'entities')) n
      where not exists (
        select 1 from knowledge.entities e
        where e.id = n.id
          and (exists (select 1 from knowledge.accounts a where a.entity_id = e.id and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys))
            or exists (select 1 from knowledge.domains d where d.entity_id = e.id and d.compartments <@ v_clearance and policy.label_key(d.compartments) = any (v_keys))
            or exists (select 1 from knowledge.projects p where p.id = e.id and p.compartments <@ v_clearance and policy.label_key(p.compartments) = any (v_keys)))
          and not (e.id = any (policy.withheld_entities())))) then
      v_refused := v_refused || jsonb_build_array(jsonb_build_object('index', (v_claim ->> 'index')::int, 'code', 'subject_unknown'));
      continue;
    end if;
    if exists (select 1 from knowledge.entities e where e.id = v_claim ->> 'subject' and e.kind = 'owner')
       or (exists (select 1 from knowledge.accounts a where a.entity_id = v_claim ->> 'subject' and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys))
           and not exists (select 1 from knowledge.accounts a where a.entity_id = v_claim ->> 'subject' and a.compartments <@ v_clearance and policy.label_key(a.compartments) = any (v_keys)
                           and not exists (select 1 from knowledge.accounts o join knowledge.entities w on w.id = o.entity_id and w.kind = 'owner'
                                           where o.value_fp = a.value_fp and o.compartments <@ v_clearance and policy.label_key(o.compartments) = any (v_keys)))) then
      v_refused := v_refused || jsonb_build_array(jsonb_build_object('index', (v_claim ->> 'index')::int, 'code', 'subject_is_owner'));
      continue;
    end if;
    if exists (
      select 1 from jsonb_array_elements_text(coalesce(v_claim -> 'cites', '[]'::jsonb)) as x (id)
      where not exists (
        select 1 from vault.evidence_items e
        where e.id = x.id and e.compartments <@ v_clearance and policy.label_key(e.compartments) = any (v_keys) and e.payload_state = 'present'
          and not exists (select 1 from knowledge.messages m where m.evidence_id = e.id and m.held and m.compartments <@ v_clearance and policy.label_key(m.compartments) = any (v_keys))
          and not exists (select 1 from knowledge.documents d where d.evidence_id = e.id and d.held and d.compartments <@ v_clearance and policy.label_key(d.compartments) = any (v_keys)))) then
      v_refused := v_refused || jsonb_build_array(jsonb_build_object('index', (v_claim ->> 'index')::int, 'code', 'fields_invalid'));
      continue;
    end if;
    v_match := null;
    v_match_fp := null;
    select v.claim_key, c.fact_key_fp into v_match, v_match_fp
    from knowledge.claims c
    join knowledge.claim_values v on v.claim_id = c.id and v.compartments <@ v_clearance and policy.label_key(v.compartments) = any (v_keys)
    where c.fact_key_fp = any (array(select jsonb_array_elements_text(v_claim -> 'matchFps'))) and v.value_fp = v_claim ->> 'valueFp'
      and v_claim ->> 'type' <> 'project.status'
      and c.compartments <@ v_clearance and policy.label_key(c.compartments) = any (v_keys)
    order by v.claim_key collate "C"
    limit 1;
    if v_match is not null then
      insert into ledger.restatement_checks (client_id, record_id, claim_key, answer, reached, matched_fact_key_fp, decision_version, checked_at, compartments)
      values (v_caller, v_record.id, v_claim -> 'claimKeys' ->> 0, 'duplicate', 'read', v_match_fp, 1, now(), v_record.compartments)
      on conflict (claim_key) do nothing;
      v_duplicates := v_duplicates || jsonb_build_array(jsonb_build_object('claimKey', v_match, 'factKey', v_match_fp));
      v_read := v_read || v_match_fp;
      continue;
    end if;
    insert into knowledge.claims (id, evidence_id, type, valid_from, fact_key_fp, extractor_generation, readers, content_enc, compartments, valid_to, due_at, review_at)
    values (v_claim ->> 'id', v_evidence_id, v_claim ->> 'type', (v_claim ->> 'validFrom')::timestamptz, v_claim ->> 'factKeyFp', 5,
      array['m-owner']::text[], v_claim -> 'content', v_record.compartments,
      (v_claim ->> 'validTo')::timestamptz, (v_claim ->> 'dueAt')::timestamptz, (v_claim ->> 'reviewAt')::timestamptz);
    insert into knowledge.claim_values (claim_id, claim_key, value_fp, compartments)
    select v_claim ->> 'id', k.key, v_claim ->> 'valueFp', v_record.compartments
    from jsonb_array_elements_text(v_claim -> 'claimKeys') as k (key) order by k.key collate "C";
    insert into knowledge.claim_entities (claim_id, entity_id, compartments)
    select v_claim ->> 'id', n.id, v_record.compartments
    from (select v_claim ->> 'subject' as id union select jsonb_array_elements_text(v_claim -> 'entities')) n
    on conflict do nothing;
    v_bound := v_bound || array(select jsonb_array_elements_text(coalesce(v_claim -> 'cites', '[]'::jsonb)));
  end loop;

  v_reply := jsonb_build_object(
    'duplicates', v_duplicates,
    'known', v_known,
    'refused', (select coalesce(jsonb_agg(r order by (r ->> 'index')::int), '[]'::jsonb) from jsonb_array_elements(v_refused) r));
  v_read := array(select d.f from (select distinct f from unnest(v_read) f) d order by d.f collate "C" limit 1000);
  insert into ledger.read_log (session_id, client_id, tool, compartments, bound, shown, fact_key_fps)
  values (write_typed_claims.p_session_id, v_caller, 'record', v_clearance,
          array(select d.f from (select distinct f from unnest(v_bound) f) d order by d.f collate "C"), '{}', v_read);
  update ledger.agent_writes set typed_reply = v_reply where id = v_record.id;
  return v_reply;
end
$$;

CREATE FUNCTION projections.drop_declassified(claim_fps text[]) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
  with dropped as (
    delete from projections.declassified_facts d where d.claim_fp = any (drop_declassified.claim_fps) returning 1
  )
  select count(*)::integer from dropped
$$;

CREATE FUNCTION vault.compartments_valid(compartments text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select array_position(compartments_valid.compartments, null) is null
    and coalesce(bool_and(
      c in ('own', 'public', 'declassified', 'canary')
      or c ~ '^agent:[a-z][a-z0-9-]{1,39}$'
      or c ~ '^restricted:(health|money|legal|intimate)$'
      or (c ~ '^employer:[a-z][a-z0-9-]{1,39}$' and c !~ '-released$')
      or (c ~ '^employer:[a-z][a-z0-9-]{1,39}-released$' and c !~ '-released-released$')
    ), true)
  from unnest(compartments_valid.compartments) as c
$_$;

CREATE FUNCTION vault.evidence_blobs_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if new.blob_ref is distinct from old.blob_ref or new.envelope is distinct from old.envelope then
    raise exception 'evidence content is kept unchanged' using errcode = '23514';
  end if;
  return new;
end
$$;

CREATE FUNCTION vault.evidence_items_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if new.content_hash is distinct from old.content_hash then
    raise exception 'evidence content is kept unchanged' using errcode = '23514';
  end if;
  if new.blob_ref is distinct from old.blob_ref and new.blob_ref is not null then
    raise exception 'evidence content is kept unchanged' using errcode = '23514';
  end if;
  if new.item_enc is distinct from old.item_enc
     and not (new.payload_state <> 'present' and new.blob_ref is null)
     and not (old.source_kind in ('transcript', 'screen_activity')
              and session_user::text in ('pi_admin', 'pi_writer')
              and coalesce(current_setting('pi.evidence_rewrite', true), '') = 'capture_facts') then
    raise exception 'evidence content is kept unchanged' using errcode = '23514';
  end if;
  return new;
end
$$;

CREATE FUNCTION vault.mark_recovery(evidence_id text, hold boolean, seen_xmin text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'policy', 'pg_temp'
    AS $$
declare
  message text;
  released timestamptz;
  current_xmin text;
begin
  if mark_recovery.hold is null then
    raise exception 'hold is null' using errcode = '22004';
  end if;
  select m.id into message from knowledge.messages m
  where m.evidence_id = mark_recovery.evidence_id
  for update;
  if message is null then
    return false;
  end if;
  select e.hold_released_at, e.xmin::text into released, current_xmin from vault.evidence_items e
  where e.id = mark_recovery.evidence_id and e.source_kind = 'email'
  for update;
  if not found then
    return false;
  end if;
  if mark_recovery.seen_xmin is not null and current_xmin <> mark_recovery.seen_xmin then
    raise exception 'item_changed' using errcode = 'PIC01';
  end if;
  update vault.evidence_items e set recovery_screened_at = now() where e.id = mark_recovery.evidence_id;
  if not mark_recovery.hold or released is not null then
    return false;
  end if;
  update vault.evidence_items e set model_hold_at = coalesce(e.model_hold_at, now()) where e.id = mark_recovery.evidence_id;
  update knowledge.messages m set held = true where m.id = message;
  return true;
end
$$;

CREATE FUNCTION vault.restrict_screens_label() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  item_compartments text[];
begin
  if cardinality(new.compartments) = 0 then
    return new;
  end if;
  select e.compartments into item_compartments from vault.evidence_items e where e.id = new.evidence_id;
  if not found or new.compartments is distinct from item_compartments then
    raise exception 'screen label differs from its evidence' using errcode = '23514';
  end if;
  return new;
end
$$;

CREATE TABLE knowledge.accounts (
    id text NOT NULL,
    entity_id text NOT NULL,
    kind text NOT NULL,
    value_fp text NOT NULL,
    domain_fp text NOT NULL,
    value_enc jsonb NOT NULL,
    compartments text[] NOT NULL,
    local_name_fps text[],
    CONSTRAINT accounts_kind_check CHECK ((kind = ANY (ARRAY['email'::text, 'role'::text, 'shared'::text, 'bulk'::text]))),
    CONSTRAINT accounts_local_name_fps CHECK (((local_name_fps IS NULL) OR (array_position(local_name_fps, NULL::text) IS NULL))),
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1))
);

ALTER TABLE ONLY knowledge.accounts FORCE ROW LEVEL SECURITY;

CREATE TABLE knowledge.agent_anchors (
    id text NOT NULL,
    project_id text NOT NULL,
    kind text NOT NULL,
    anchor_fp text NOT NULL,
    value_enc jsonb NOT NULL,
    client_id text NOT NULL,
    request_id text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    lifted_at timestamp with time zone,
    lifted_by text,
    owner_mark text,
    marked_at timestamp with time zone,
    compartments text[] NOT NULL,
    CONSTRAINT agent_anchors_anchor_fp CHECK ((anchor_fp ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT agent_anchors_id CHECK ((id ~ '^aan_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT agent_anchors_kind CHECK ((kind = ANY (ARRAY['repository'::text, 'host'::text, 'document'::text, 'app'::text]))),
    CONSTRAINT agent_anchors_lift CHECK (((lifted_at IS NULL) = (lifted_by IS NULL))),
    CONSTRAINT agent_anchors_lifted_by CHECK (((lifted_by = 'owner'::text) OR (lifted_by ~ '^client:cli_[0-9A-HJKMNP-TV-Z]{26}$'::text))),
    CONSTRAINT agent_anchors_mark CHECK ((owner_mark = ANY (ARRAY['right'::text, 'wrong'::text]))),
    CONSTRAINT agent_anchors_marked CHECK (((owner_mark IS NULL) = (marked_at IS NULL))),
    CONSTRAINT agent_anchors_request CHECK ((request_id ~ '^[A-Za-z0-9_-]{8,64}$'::text)),
    CONSTRAINT agent_anchors_value CHECK ((jsonb_typeof(value_enc) = 'object'::text)),
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1))
);

ALTER TABLE ONLY knowledge.agent_anchors FORCE ROW LEVEL SECURITY;

CREATE TABLE knowledge.agent_time_rulings (
    id text NOT NULL,
    project_id text NOT NULL,
    from_at timestamp with time zone NOT NULL,
    to_at timestamp with time zone NOT NULL,
    proposal_id text,
    tool text NOT NULL,
    client_id text NOT NULL,
    request_id text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    lifted_at timestamp with time zone,
    lifted_by text,
    owner_mark text,
    marked_at timestamp with time zone,
    compartments text[] NOT NULL,
    reach text[] NOT NULL,
    CONSTRAINT agent_time_rulings_id CHECK ((id ~ '^atr_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT agent_time_rulings_lift CHECK (((lifted_at IS NULL) = (lifted_by IS NULL))),
    CONSTRAINT agent_time_rulings_lifted_by CHECK (((lifted_by = 'owner'::text) OR (lifted_by ~ '^client:cli_[0-9A-HJKMNP-TV-Z]{26}$'::text))),
    CONSTRAINT agent_time_rulings_mark CHECK ((owner_mark = ANY (ARRAY['right'::text, 'wrong'::text]))),
    CONSTRAINT agent_time_rulings_marked CHECK (((owner_mark IS NULL) = (marked_at IS NULL))),
    CONSTRAINT agent_time_rulings_proposal CHECK ((proposal_id ~ '^tpr_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT agent_time_rulings_range CHECK (((to_at > from_at) AND ((to_at - from_at) <= '24:00:00'::interval))),
    CONSTRAINT agent_time_rulings_reach CHECK (((cardinality(reach) >= 1) AND (compartments <@ reach))),
    CONSTRAINT agent_time_rulings_request CHECK ((request_id ~ '^[A-Za-z0-9_-]{8,64}$'::text)),
    CONSTRAINT agent_time_rulings_tool CHECK ((tool = ANY (ARRAY['rule_time'::text, 'judge_time_proposal'::text]))),
    CONSTRAINT agent_time_rulings_tool_proposal CHECK (((tool = 'judge_time_proposal'::text) = (proposal_id IS NOT NULL))),
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1))
);

ALTER TABLE ONLY knowledge.agent_time_rulings FORCE ROW LEVEL SECURITY;

CREATE TABLE knowledge.aliases (
    id text NOT NULL,
    entity_id text NOT NULL,
    value_fp text NOT NULL,
    evidence_id text NOT NULL,
    value_enc jsonb NOT NULL,
    compartments text[] NOT NULL,
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1))
);

ALTER TABLE ONLY knowledge.aliases FORCE ROW LEVEL SECURITY;

CREATE TABLE knowledge.areas (
    id text NOT NULL,
    key text NOT NULL,
    name_enc jsonb NOT NULL,
    "position" integer NOT NULL,
    state text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    compartments text[] DEFAULT ARRAY['own'::text] NOT NULL,
    CONSTRAINT areas_id_form CHECK ((id ~ '^are_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT areas_key_form CHECK ((key ~ '^[a-z][a-z0-9-]{1,31}$'::text)),
    CONSTRAINT areas_label_own CHECK ((compartments = ARRAY['own'::text])),
    CONSTRAINT areas_name_object CHECK ((jsonb_typeof(name_enc) = 'object'::text)),
    CONSTRAINT areas_position CHECK ((("position" >= 1) AND ("position" <= 100000))),
    CONSTRAINT areas_state CHECK ((state = ANY (ARRAY['active'::text, 'retired'::text]))),
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1))
);

ALTER TABLE ONLY knowledge.areas FORCE ROW LEVEL SECURITY;

CREATE TABLE knowledge.belief_rulings (
    ruling_id text NOT NULL,
    verdict text NOT NULL,
    claim_fp text NOT NULL,
    source_account_id text,
    source_item_fp text,
    fact_key_fp text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    lifted_at timestamp with time zone,
    lift_ruling_id text,
    compartments text[] NOT NULL,
    value_enc jsonb,
    item_account_ids text[],
    item_fps text[],
    claim_type text,
    evidence_ids text[],
    entity_ids text[],
    shown_enc jsonb,
    CONSTRAINT belief_rulings_anchor CHECK ((((claim_type IS NULL) = (evidence_ids IS NULL)) AND ((claim_type IS NULL) = (entity_ids IS NULL)))),
    CONSTRAINT belief_rulings_items CHECK ((((item_account_ids IS NULL) = (item_fps IS NULL)) AND ((item_fps IS NULL) OR ((verdict = ANY (ARRAY['veto'::text, 'retire'::text])) AND (cardinality(item_account_ids) = cardinality(item_fps)))))),
    CONSTRAINT belief_rulings_lift CHECK (((lifted_at IS NULL) = (lift_ruling_id IS NULL))),
    CONSTRAINT belief_rulings_source CHECK ((((verdict = 'reject'::text) AND (source_account_id IS NOT NULL) AND (source_item_fp IS NOT NULL)) OR ((verdict = ANY (ARRAY['veto'::text, 'retire'::text, 'domain'::text, 'kind'::text])) AND (source_account_id IS NULL) AND (source_item_fp IS NULL)))),
    CONSTRAINT belief_rulings_value CHECK (((verdict = ANY (ARRAY['domain'::text, 'kind'::text])) = (value_enc IS NOT NULL))),
    CONSTRAINT belief_rulings_verdict CHECK ((verdict = ANY (ARRAY['reject'::text, 'veto'::text, 'retire'::text, 'domain'::text, 'kind'::text]))),
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1))
);

ALTER TABLE ONLY knowledge.belief_rulings FORCE ROW LEVEL SECURITY;

CREATE TABLE knowledge.captures (
    id text NOT NULL,
    evidence_id text NOT NULL,
    source_account_id text NOT NULL,
    capture_key text NOT NULL,
    revision integer NOT NULL,
    kind text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    ended_at timestamp with time zone NOT NULL,
    event_id text,
    first_pushed_at timestamp with time zone NOT NULL,
    local_day date NOT NULL,
    minutes numeric,
    bundle_fp text,
    host_fp text,
    account_fp text,
    thread_fp text,
    match_fps text[] DEFAULT '{}'::text[] NOT NULL,
    facts_enc jsonb NOT NULL,
    compartments text[] NOT NULL,
    agent_app boolean DEFAULT false NOT NULL,
    work_enc jsonb,
    work_titles boolean DEFAULT false NOT NULL,
    work_tried_at timestamp with time zone,
    source text,
    lines_fp text,
    CONSTRAINT captures_account_fp CHECK ((account_fp ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT captures_agent_app CHECK (((NOT agent_app) OR (kind = 'moment'::text))),
    CONSTRAINT captures_block_keys CHECK (((kind <> 'block'::text) OR (match_fps = '{}'::text[]))),
    CONSTRAINT captures_block_minutes CHECK (((kind = 'block'::text) = (minutes IS NOT NULL))),
    CONSTRAINT captures_bundle_fp CHECK ((bundle_fp ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT captures_capture_key_form CHECK ((capture_key ~ '^(meeting|moment|block|task):[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT captures_host_fp CHECK ((host_fp ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT captures_id_form CHECK ((id ~ '^cap_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT captures_kind CHECK ((kind = ANY (ARRAY['meeting'::text, 'moment'::text, 'block'::text, 'task'::text]))),
    CONSTRAINT captures_kind_of_key CHECK ((capture_key ~~ (kind || ':%'::text))),
    CONSTRAINT captures_lines_fp CHECK ((lines_fp ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT captures_match_fps CHECK (((array_position(match_fps, NULL::text) IS NULL) AND (array_to_string(match_fps, ' '::text) ~ '^([0-9a-f]{64}( [0-9a-f]{64})*)?$'::text))),
    CONSTRAINT captures_minutes CHECK ((minutes >= (0)::numeric)),
    CONSTRAINT captures_revision CHECK ((revision >= 0)),
    CONSTRAINT captures_source CHECK (((source IS NULL) OR ((source = 'imessage'::text) AND (kind = 'moment'::text)))),
    CONSTRAINT captures_span CHECK ((ended_at >= started_at)),
    CONSTRAINT captures_thread_fp CHECK ((thread_fp ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1))
);

ALTER TABLE ONLY knowledge.captures FORCE ROW LEVEL SECURITY;

