    CONSTRAINT agent_writes_cites CHECK (((cardinality(cites) <= 20) AND (array_position(cites, NULL::text) IS NULL) AND (array_to_string(cites, ''::text) !~ ','::text) AND ((cardinality(cites) = 0) OR (array_to_string(cites, ','::text) ~ '^[0-9a-f]{64}(,[0-9a-f]{64})*$'::text)))),
    CONSTRAINT agent_writes_cites_fp CHECK ((cites_fp ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT agent_writes_close CHECK ((((kind = 'close'::text) = (close_fact_fp IS NOT NULL)) AND ((kind = 'close'::text) = (close_ending IS NOT NULL)) AND ((close_fact_fp IS NULL) OR (close_fact_fp ~ '^[0-9a-f]{64}$'::text)) AND ((close_ending IS NULL) OR (close_ending = ANY (ARRAY['done'::text, 'cancelled'::text, 'released'::text]))))),
    CONSTRAINT agent_writes_content_fp CHECK ((content_fp ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT agent_writes_fill CHECK ((((kind = 'fill'::text) = (fill_node IS NOT NULL)) AND ((kind = 'fill'::text) = (fill_move IS NOT NULL)) AND ((fill_node IS NULL) OR (fill_node ~ '^ent_[0-9A-HJKMNP-TV-Z]{26}$'::text)) AND ((fill_move IS NULL) OR (fill_move ~ '^mov_[0-9A-HJKMNP-TV-Z]{26}$'::text)))),
    CONSTRAINT agent_writes_id_form CHECK ((id ~ '^rec_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT agent_writes_kind CHECK ((kind = ANY (ARRAY['note'::text, 'finding'::text, 'handoff'::text, 'proposal'::text, 'memory_change'::text, 'answer'::text, 'close'::text, 'fill'::text, 'lesson'::text, 'capability'::text]))),
    CONSTRAINT agent_writes_memory_cites CHECK (((kind <> 'memory_change'::text) OR (cardinality(cites) = 0))),
    CONSTRAINT agent_writes_project CHECK (((project_id IS NULL) OR ((kind = 'finding'::text) AND (project_id ~ '^ent_[0-9A-HJKMNP-TV-Z]{26}$'::text)))),
    CONSTRAINT agent_writes_proposal_scope CHECK ((((kind = 'proposal'::text) = (proposal_scope IS NOT NULL)) AND ((proposal_scope IS NULL) OR (proposal_scope = ANY (ARRAY['all'::text, 'this_client'::text]))))),
    CONSTRAINT agent_writes_refused_code CHECK (((refused_code IS NULL) OR (refused_code ~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*$'::text))),
    CONSTRAINT agent_writes_request_id_form CHECK ((request_id ~ '^[A-Za-z0-9_-]{8,64}$'::text)),
    CONSTRAINT agent_writes_supersedes CHECK (((supersedes IS NULL) OR ((tool = 'record'::text) AND (kind = ANY (ARRAY['note'::text, 'finding'::text])) AND (supersedes <> id)))),
    CONSTRAINT agent_writes_tool CHECK (((((((((((((tool = 'record'::text) AND (kind = 'note'::text)) OR ((tool = 'record'::text) AND (kind = 'finding'::text))) OR ((tool = 'record'::text) AND (kind = 'handoff'::text))) OR ((tool = 'record'::text) AND (kind = 'lesson'::text))) OR ((tool = 'record'::text) AND (kind = 'capability'::text))) OR ((tool = 'propose_about_you'::text) AND (kind = 'proposal'::text))) OR ((tool = 'import_memory'::text) AND (kind = 'memory_change'::text))) OR ((tool = 'answer_owner_question'::text) AND (kind = 'answer'::text))) OR ((tool = 'propose_person'::text) AND (kind = 'proposal'::text))) OR ((tool = 'close_commitment'::text) AND (kind = 'close'::text))) OR ((tool = 'report_move'::text) AND (kind = 'fill'::text)))),
    CONSTRAINT agent_writes_typed_reply CHECK (((typed_reply IS NULL) OR ((kind = 'finding'::text) AND (tool = 'record'::text) AND (jsonb_typeof(typed_reply) = 'object'::text) AND (octet_length((typed_reply)::text) <= 65536)))),
    CONSTRAINT agent_writes_writer_views CHECK (((cardinality(writer_views) >= 1) AND (array_position(writer_views, NULL::text) IS NULL))),
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1))
