    id text NOT NULL,
    request_id text NOT NULL,
    created_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    session_id text,
    change text NOT NULL,
    goal_id text,
    statement_fp text,
    statement_enc jsonb,
    proposed_compartment text,
    body_enc jsonb,
    details_enc jsonb,
    card_id text,
    tainted_at timestamp with time zone,
    compartments text[] NOT NULL,
    target_entity_id text,
    target_org boolean DEFAULT false NOT NULL,
    target_holders text[],
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1)),
    CONSTRAINT goal_proposals_by_form CHECK ((created_by ~ '^client:cli_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT goal_proposals_change CHECK ((change = ANY (ARRAY['add'::text, 'reword'::text, 'pause'::text, 'done'::text, 'drop'::text, 'target'::text]))),
    CONSTRAINT goal_proposals_compartment CHECK (((change = 'add'::text) OR (proposed_compartment IS NULL))),
    CONSTRAINT goal_proposals_details_size CHECK (((details_enc IS NULL) OR (octet_length((details_enc)::text) <= 16384))),
    CONSTRAINT goal_proposals_fp_form CHECK ((statement_fp ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT goal_proposals_goal CHECK (((change = 'add'::text) = (goal_id IS NULL))),
    CONSTRAINT goal_proposals_goal_form CHECK ((goal_id ~ '^gol_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT goal_proposals_id_form CHECK ((id ~ '^gpr_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT goal_proposals_request_form CHECK ((request_id ~ '^[A-Za-z0-9_-]{8,64}$'::text)),
    CONSTRAINT goal_proposals_statement CHECK (
CASE change
    WHEN 'target'::text THEN ((target_entity_id IS NULL) <> (statement_fp IS NULL))
    ELSE (((change = ANY (ARRAY['add'::text, 'reword'::text])) = (statement_fp IS NOT NULL)) AND (target_entity_id IS NULL))
END),
    CONSTRAINT goal_proposals_target_form CHECK ((target_entity_id ~ '^ent_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT goal_proposals_target_org CHECK (((NOT target_org) OR ((change = 'target'::text) AND (statement_fp IS NOT NULL))))
);

