    applies_roles text[],
    supersedes text,
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1)),
    CONSTRAINT hypotheses_about CHECK ((((about_kind = 'owner'::text) = (about_id IS NULL)) AND (about_owner = (about_kind = 'owner'::text)))),
    CONSTRAINT hypotheses_about_kind CHECK ((about_kind = ANY (ARRAY['owner'::text, 'message'::text, 'event'::text, 'entity'::text, 'goal'::text]))),
    CONSTRAINT hypotheses_applies CHECK (((kind = 'lesson'::text) OR ((applies_kinds IS NULL) AND (applies_roles IS NULL) AND (supersedes IS NULL)))),
    CONSTRAINT hypotheses_applies_kinds CHECK (((applies_kinds IS NULL) OR ((cardinality(applies_kinds) <= 9) AND (array_position(applies_kinds, NULL::text) IS NULL) AND (applies_kinds <@ ARRAY['follow_up'::text, 'reply'::text, 'meeting_prep'::text, 'investigate'::text, 'goal_step'::text, 'life_admin'::text, 'owner_question'::text, 'research'::text, 'introduction'::text])))),
    CONSTRAINT hypotheses_applies_roles CHECK (((applies_roles IS NULL) OR ((cardinality(applies_roles) <= 16) AND (array_position(applies_roles, NULL::text) IS NULL) AND (array_to_string(applies_roles, ''::text) !~ ','::text) AND (array_to_string(applies_roles, ','::text) ~ '^([a-z][a-z0-9-]{1,31}(,[a-z][a-z0-9-]{1,31})*)?$'::text)))),
    CONSTRAINT hypotheses_body CHECK (((body_enc IS NULL) OR (jsonb_typeof(body_enc) = 'object'::text))),
    CONSTRAINT hypotheses_id_form CHECK ((id ~ '^hyp_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT hypotheses_kind CHECK ((kind = ANY (ARRAY['open_loop'::text, 'needs_preparation'::text, 'at_risk'::text, 'preference'::text, 'idea'::text, 'lesson'::text]))),
    CONSTRAINT hypotheses_planner_about CHECK ((((kind <> 'idea'::text) OR (NOT about_owner)) AND ((kind <> 'lesson'::text) OR about_owner))),
    CONSTRAINT hypotheses_request_id_form CHECK ((request_id ~ '^[A-Za-z0-9_-]{8,64}$'::text)),
    CONSTRAINT hypotheses_supersedes CHECK (((supersedes IS NULL) OR ((supersedes ~ '^hyp_[0-9A-HJKMNP-TV-Z]{26}$'::text) AND (supersedes <> id))))
);

