    CONSTRAINT memory_imports_matched CHECK (((array_position(matched_projection_ids, NULL::text) IS NULL) AND (array_to_string(matched_projection_ids, ''::text) !~ ','::text) AND ((cardinality(matched_projection_ids) = 0) OR (array_to_string(matched_projection_ids, ','::text) ~ '^mpr_[0-9a-f]{40}(,mpr_[0-9a-f]{40})*$'::text)))),
    CONSTRAINT memory_imports_record CHECK (((record_id IS NULL) OR ((change = 'added'::text) AND (mark <> 'refused'::text)))),
