    CONSTRAINT memory_projections_fact_key_fp CHECK ((fact_key_fp ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT memory_projections_id CHECK ((id ~ '^mpr_[0-9a-f]{40}$'::text)),
