    CONSTRAINT mirror_entries_ended CHECK (((reason IS NULL) = (ended_at IS NULL))),
    CONSTRAINT mirror_entries_entity_ids CHECK (((array_position(entity_ids, NULL::text) IS NULL) AND (array_to_string(entity_ids, ''::text) !~ ','::text) AND ((cardinality(entity_ids) = 0) OR (array_to_string(entity_ids, ','::text) ~ '^ent_[0-9A-HJKMNP-TV-Z]{26}(,ent_[0-9A-HJKMNP-TV-Z]{26})*$'::text)))),
    CONSTRAINT mirror_entries_entry_key CHECK ((((section = 'entities'::text) AND (entry_key ~ '^ent_[0-9A-HJKMNP-TV-Z]{26}$'::text)) OR ((section = 'beliefs'::text) AND (entry_key ~ '^blf_[0-9a-f]{40}$'::text)) OR ((section = 'facts'::text) AND (entry_key ~ '^[0-9a-f]{64}:[0-9a-f]{64}$'::text)) OR ((section = 'events'::text) AND (entry_key ~ '^evt_[0-9A-HJKMNP-TV-Z]{26}$'::text)) OR ((section = 'captures'::text) AND (entry_key ~ '^cap_[0-9A-HJKMNP-TV-Z]{26}$'::text)))),
    CONSTRAINT mirror_entries_evidence_ids CHECK (((array_position(evidence_ids, NULL::text) IS NULL) AND (array_to_string(evidence_ids, ''::text) !~ ','::text) AND ((cardinality(evidence_ids) = 0) OR (array_to_string(evidence_ids, ','::text) ~ '^([0-9a-f]{64}|rec_[0-9A-HJKMNP-TV-Z]{26})(,([0-9a-f]{64}|rec_[0-9A-HJKMNP-TV-Z]{26}))*$'::text)))),
    CONSTRAINT mirror_entries_fact CHECK (((fact_key_fp IS NOT NULL) = (section = ANY (ARRAY['beliefs'::text, 'facts'::text])))),
    CONSTRAINT mirror_entries_fact_key_fp CHECK ((fact_key_fp ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT mirror_entries_id CHECK ((id ~ '^mir_[0-9a-f]{40}$'::text)),
    CONSTRAINT mirror_entries_reason CHECK ((reason = ANY (ARRAY['withdrawn'::text, 'replaced'::text, 'dropped'::text]))),
    CONSTRAINT mirror_entries_section CHECK ((section = ANY (ARRAY['entities'::text, 'beliefs'::text, 'facts'::text, 'events'::text, 'captures'::text]))),
    CONSTRAINT mirror_entries_sent_state CHECK ((sent_state ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT mirror_entries_sent_token CHECK ((sent_token ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT mirror_entries_tainted CHECK (((tainted_at IS NULL) OR (ended_at IS NOT NULL))),
    CONSTRAINT mirror_entries_template CHECK ((template ~ '^lens_mirror@[1-9][0-9]{0,3}$'::text))
);

