CREATE TABLE ledger.opportunities (
    id text NOT NULL,
    request_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text NOT NULL,
    run_id text,
    session_id text,
    compartments text[] NOT NULL,
    tainted_at timestamp with time zone,
    body_enc jsonb,
    case_id text NOT NULL,
    kind text NOT NULL,
    hypothesis_id text,
    about_kind text NOT NULL,
    about_id text,
    goal_id text,
    due_at timestamp with time zone,
    proposed_by_class text NOT NULL,
    probability real,
    probability_if_waiting real,
    gap_trigger text,
    gap_subject text,
    gap_source text,
    tier text DEFAULT 'opportunity'::text NOT NULL,
    role text,
    details_enc jsonb,
    gap_missing text[],
    gap_value double precision,
    gap_parts double precision[],
    project_id text,
    parent_id text,
    question_tools text[],
    question_sources text[],
    question_paid_at timestamp with time zone,
    bet_at timestamp with time zone,
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1)),
    CONSTRAINT opportunities_about CHECK (((about_kind = 'owner'::text) = (about_id IS NULL))),
    CONSTRAINT opportunities_about_kind CHECK ((about_kind = ANY (ARRAY['owner'::text, 'message'::text, 'event'::text, 'entity'::text, 'goal'::text]))),
    CONSTRAINT opportunities_body CHECK (((body_enc IS NULL) OR (jsonb_typeof(body_enc) = 'object'::text))),
    CONSTRAINT opportunities_class CHECK ((proposed_by_class = ANY (ARRAY['run'::text, 'client'::text, 'system'::text, 'owner'::text]))),
    CONSTRAINT opportunities_details_size CHECK (((details_enc IS NULL) OR (octet_length((details_enc)::text) <= 16384))),
    CONSTRAINT opportunities_explore CHECK ((((NOT (gap_trigger IS DISTINCT FROM 'explore'::text)) = (gap_missing IS NOT NULL)) AND ((gap_missing IS NULL) = (gap_value IS NULL)) AND ((gap_missing IS NULL) = (gap_parts IS NULL)) AND ((gap_missing IS NULL) OR (((cardinality(gap_missing) >= 1) AND (cardinality(gap_missing) <= 6)) AND (array_position(gap_missing, NULL::text) IS NULL) AND (gap_missing <@ ARRAY['identity'::text, 'role'::text, 'affiliation'::text, 'domain'::text, 'relations'::text, 'links'::text]) AND (gap_value > (0)::double precision) AND (gap_value < 'Infinity'::double precision) AND (cardinality(gap_parts) = 5) AND (array_position(gap_parts, NULL::double precision) IS NULL) AND ((0)::double precision <= ALL (gap_parts)) AND ('Infinity'::double precision > ALL (gap_parts)))))),
    CONSTRAINT opportunities_gap CHECK ((((gap_trigger IS NULL) = (gap_subject IS NULL)) AND ((gap_trigger IS NULL) = (gap_source IS NULL)) AND ((gap_trigger IS NOT NULL) = (proposed_by_class = 'system'::text)) AND ((kind <> 'research'::text) OR (gap_trigger IS NOT NULL) OR (proposed_by_class = 'owner'::text)) AND ((gap_trigger IS NULL) OR ((gap_trigger = ANY (ARRAY['unresolved_mention'::text, 'no_warm_path'::text, 'unknown_attendee'::text, 'close_no_role'::text, 'meeting_soon'::text, 'commitment_due'::text, 'reply_owed'::text, 'close_no_tie'::text, 'intro_path'::text, 'explore'::text, 'deadline_soon'::text, 'same_person'::text, 'defect'::text, 'defect_untriaged'::text, 'card_question'::text, 'merge_audit'::text, 'card_relay'::text, 'dream_finding'::text, 'owner_queue'::text, 'goal_review'::text, 'meeting_followup'::text])) AND (gap_subject ~ '^[A-Za-z0-9_]{1,128}$'::text) AND (kind = 'research'::text))))),
    CONSTRAINT opportunities_id_form CHECK ((id ~ '^opp_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT opportunities_kind CHECK ((kind = ANY (ARRAY['follow_up'::text, 'reply'::text, 'meeting_prep'::text, 'investigate'::text, 'goal_step'::text, 'life_admin'::text, 'owner_question'::text, 'research'::text, 'introduction'::text]))),
    CONSTRAINT opportunities_owner CHECK (((proposed_by_class = 'owner'::text) = (created_by = 'owner'::text))),
    CONSTRAINT opportunities_parent_not_self CHECK ((parent_id <> id)),
    CONSTRAINT opportunities_parent_task CHECK (((parent_id IS NULL) OR (tier = 'task'::text))),
    CONSTRAINT opportunities_probability CHECK (((probability >= (0)::double precision) AND (probability <= (1)::double precision))),
    CONSTRAINT opportunities_probability_if_waiting CHECK (((probability_if_waiting >= (0)::double precision) AND (probability_if_waiting <= (1)::double precision))),
    CONSTRAINT opportunities_question_hypothesis CHECK (((kind <> 'owner_question'::text) OR (hypothesis_id IS NOT NULL))),
    CONSTRAINT opportunities_question_paid CHECK ((((question_tools IS NULL) = (question_sources IS NULL)) AND ((question_tools IS NULL) = (question_paid_at IS NULL)))),
    CONSTRAINT opportunities_question_sources CHECK (((question_sources IS NULL) OR ((cardinality(question_sources) <= 10) AND (array_position(question_sources, NULL::text) IS NULL) AND ((cardinality(question_sources) = 0) OR (array_to_string(question_sources, ','::text) ~ '^([0-9a-f]{64}|rec_[0-9A-HJKMNP-TV-Z]{26})(,([0-9a-f]{64}|rec_[0-9A-HJKMNP-TV-Z]{26}))*$'::text))))),
    CONSTRAINT opportunities_question_tools CHECK (((question_tools IS NULL) OR (((cardinality(question_tools) >= 1) AND (cardinality(question_tools) <= 5)) AND (array_position(question_tools, NULL::text) IS NULL)))),
    CONSTRAINT opportunities_request_id_form CHECK ((request_id ~ '^[A-Za-z0-9_-]{8,64}$'::text)),
    CONSTRAINT opportunities_role_form CHECK ((role ~ '^[a-z][a-z0-9-]{1,31}$'::text)),
    CONSTRAINT opportunities_role_task CHECK (((role IS NULL) OR (tier = 'task'::text))),
    CONSTRAINT opportunities_task_kind CHECK (((tier = 'opportunity'::text) OR ledger.task_kind(kind))),
    CONSTRAINT opportunities_tier CHECK ((tier = ANY (ARRAY['task'::text, 'opportunity'::text])))
);

