    CONSTRAINT read_log_fact_key_fps CHECK (((cardinality(fact_key_fps) <= 1000) AND (array_position(fact_key_fps, NULL::text) IS NULL) AND (array_to_string(fact_key_fps, ''::text) !~ ','::text) AND ((cardinality(fact_key_fps) = 0) OR (array_to_string(fact_key_fps, ','::text) ~ '^[0-9a-f]{64}(,[0-9a-f]{64})*$'::text)))),
    CONSTRAINT read_log_goals CHECK (((cardinality(goals) <= 1000) AND (array_position(goals, NULL::text) IS NULL) AND (array_to_string(goals, ''::text) !~ ','::text) AND ((cardinality(goals) = 0) OR (array_to_string(goals, ','::text) ~ '^gol_[0-9A-HJKMNP-TV-Z]{26}(,gol_[0-9A-HJKMNP-TV-Z]{26})*$'::text)))),
    CONSTRAINT read_log_lessons CHECK (((cardinality(lessons) <= 1000) AND (array_position(lessons, NULL::text) IS NULL) AND (array_to_string(lessons, ''::text) !~ ','::text) AND ((cardinality(lessons) = 0) OR (array_to_string(lessons, ','::text) ~ '^hyp_[0-9A-HJKMNP-TV-Z]{26}(,hyp_[0-9A-HJKMNP-TV-Z]{26})*$'::text)))),
    CONSTRAINT read_log_shown CHECK (((cardinality(shown) <= 1000) AND (array_position(shown, NULL::text) IS NULL) AND (array_to_string(shown, ''::text) !~ ','::text) AND ((cardinality(shown) = 0) OR (array_to_string(shown, ','::text) ~ '^([0-9a-f]{64}|rec_[0-9A-HJKMNP-TV-Z]{26})(,([0-9a-f]{64}|rec_[0-9A-HJKMNP-TV-Z]{26}))*$'::text))))
);

