    CONSTRAINT recall_checks_filter CHECK ((filter = ANY (ARRAY['mail_no_deadline_word'::text, 'mail_says_done'::text, 'mail_advertises'::text, 'mail_restated'::text, 'says_time_suits'::text, 'says_conditional'::text, 'bar_not_a_promise'::text, 'bar_wrong_direction'::text]))),
