    CONSTRAINT recall_checks_population CHECK ((population >= 0)),
    CONSTRAINT recall_checks_shape CHECK (((verdict IS NULL) <> (code IS NULL))),
    CONSTRAINT recall_checks_target_key CHECK ((target_key ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT recall_checks_verdict CHECK (((verdict IS NULL) OR (verdict = ANY (ARRAY['missed'::text, 'rightly_dropped'::text]))))
);

