CREATE TABLE ledger.relation_checks (
    id bigint NOT NULL,
    claim_key text NOT NULL,
    claim_id text NOT NULL,
    other_key text,
    judge text NOT NULL,
    state text NOT NULL,
    first_answer text,
    second_answer text,
    agreed boolean,
    written text,
    code text,
    compartments text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    judged_at timestamp with time zone,
    dream boolean DEFAULT false NOT NULL,
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1)),
    CONSTRAINT relation_checks_claim CHECK ((claim_key ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT relation_checks_claim_id CHECK ((claim_id <> ''::text)),
    CONSTRAINT relation_checks_code CHECK (((code IS NULL) OR (code ~ '^[a-z][a-z0-9_]{0,31}$'::text))),
    CONSTRAINT relation_checks_first CHECK (((first_answer IS NULL) OR (first_answer ~ '^((supersedes|fulfils|refines|prevails):(claim|other)|same_fact|contradicts|unrelated)$'::text))),
    CONSTRAINT relation_checks_judge CHECK ((judge ~ '^model:[A-Za-z0-9_./:-]{1,100}@[A-Za-z0-9_.-]{1,64}(@[1-9][0-9]{0,3})?$'::text)),
    CONSTRAINT relation_checks_other CHECK (((other_key IS NULL) OR ((other_key ~ '^[0-9a-f]{64}$'::text) AND (other_key <> claim_key)))),
    CONSTRAINT relation_checks_second CHECK (((second_answer IS NULL) OR (second_answer ~ '^((supersedes|fulfils|refines|prevails):(claim|other)|same_fact|contradicts|unrelated)$'::text))),
    CONSTRAINT relation_checks_shape CHECK ((((other_key IS NULL) AND (first_answer IS NULL) AND (second_answer IS NULL) AND (agreed IS NULL) AND (written IS NULL)) OR ((other_key IS NOT NULL) AND (state = 'judged'::text)))),
    CONSTRAINT relation_checks_state CHECK ((state = ANY (ARRAY['unjudged'::text, 'judged'::text]))),
    CONSTRAINT relation_checks_written CHECK (((written IS NULL) OR (written = ANY (ARRAY['supersedes'::text, 'contradicts'::text, 'fulfils'::text, 'refines'::text, 'same_fact'::text, 'prevails'::text]))))
);

