    CONSTRAINT run_steps_result_code_points CHECK ((result_code_points >= 0)),
    CONSTRAINT run_steps_result_size CHECK (((kind = 'tool_call'::text) OR (result_code_points IS NULL))),
    CONSTRAINT run_steps_shape CHECK ((((kind = 'model_call'::text) AND (cost_microusd IS NOT NULL) AND (tool IS NULL) AND (status IS NULL) AND (prompt_id IS NOT NULL) AND (prompt_version IS NOT NULL) AND (model_id IS NOT NULL)) OR ((kind = 'tool_call'::text) AND (cost_microusd IS NULL) AND (status IS NOT NULL) AND (prompt_id IS NULL) AND (prompt_version IS NULL) AND (model_id IS NULL) AND ((tool IS NOT NULL) OR (status = 'refused'::text))) OR ((kind = 'output_check'::text) AND (status = 'refused'::text) AND (code IS NOT NULL) AND (tool IS NULL) AND (cost_microusd IS NULL) AND (prompt_id IS NULL) AND (prompt_version IS NULL) AND (model_id IS NULL)) OR ((kind = ANY (ARRAY['web_search'::text, 'web_fetch'::text])) AND (status IS NULL) AND (code IS NULL) AND (tool IS NULL) AND (cost_microusd IS NULL) AND (prompt_id IS NULL) AND (prompt_version IS NULL) AND (model_id IS NULL)))),
    CONSTRAINT run_steps_status CHECK ((status = ANY (ARRAY['ok'::text, 'refused'::text, 'failed'::text, 'too_large'::text])))
);

