);

CREATE TABLE ledger.runs (
    id text NOT NULL,
    request_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text NOT NULL,
    run_id text,
    session_id text,
    compartments text[] NOT NULL,
    tainted_at timestamp with time zone,
    wake_source text NOT NULL,
    wake_key text NOT NULL,
    decision_point text NOT NULL,
    definition_version integer NOT NULL,
    prompt_id text NOT NULL,
    prompt_version text NOT NULL,
    covered_keys text[] DEFAULT '{}'::text[] NOT NULL,
    cards jsonb,
    trial_model text,
    trial_effort text,
    answers jsonb,
    lessons text[],
    predict_model text,
    decisions text[],
    decisions_cursor text,
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1)),
    CONSTRAINT runs_answers CHECK (((answers IS NULL) OR (jsonb_typeof(answers) = 'array'::text))),
    CONSTRAINT runs_cards CHECK (((cards IS NULL) OR (jsonb_typeof(cards) = 'array'::text))),
    CONSTRAINT runs_decisions CHECK (((decisions IS NULL) OR ((cardinality(decisions) <= 60) AND (array_position(decisions, NULL::text) IS NULL) AND (prompt_id = 'personal_lessons'::text) AND ((cardinality(decisions) = 0) OR (array_to_string(decisions, ','::text) ~ '^rul_[0-9A-HJKMNP-TV-Z]{26}(,rul_[0-9A-HJKMNP-TV-Z]{26})*$'::text))))),
    CONSTRAINT runs_decisions_cursor CHECK (((decisions_cursor IS NULL) OR ((decisions_cursor ~ '^rul_[0-9A-HJKMNP-TV-Z]{26}$'::text) AND (decisions IS NOT NULL) AND (trial_model IS NULL)))),
    CONSTRAINT runs_id_form CHECK ((id ~ '^run_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT runs_lessons CHECK (((lessons IS NULL) OR ((cardinality(lessons) <= 50) AND (array_position(lessons, NULL::text) IS NULL) AND ((cardinality(lessons) = 0) OR (array_to_string(lessons, ','::text) ~ '^hyp_[0-9A-HJKMNP-TV-Z]{26}(,hyp_[0-9A-HJKMNP-TV-Z]{26})*$'::text))))),
    CONSTRAINT runs_predict_model CHECK (((predict_model IS NULL) OR ((prompt_id = 'personal_predict'::text) AND (trial_model IS NULL)))),
    CONSTRAINT runs_predict_model_form CHECK ((predict_model ~ '^[a-z0-9][a-z0-9._-]{0,63}/[a-z0-9][a-z0-9._-]{0,63}$'::text)),
    CONSTRAINT runs_request_id_form CHECK ((request_id ~ '^[A-Za-z0-9_-]{8,64}$'::text)),
    CONSTRAINT runs_trial CHECK ((((trial_model IS NULL) = (trial_effort IS NULL)) AND ((trial_model IS NULL) OR (prompt_id = ANY (ARRAY['personal_ideas'::text, 'personal_translate'::text, 'personal_lessons'::text, 'personal_predict'::text]))))),
    CONSTRAINT runs_trial_effort CHECK ((trial_effort = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text]))),
    CONSTRAINT runs_trial_model_form CHECK ((trial_model ~ '^[a-z0-9][a-z0-9._-]{0,63}/[a-z0-9][a-z0-9._-]{0,63}$'::text)),
    CONSTRAINT runs_wake_source CHECK ((wake_source = ANY (ARRAY['daily_sweep'::text, 'calendar'::text, 'goal_changed'::text, 'owner_request'::text, 'commitment_due'::text, 'belief_changed'::text, 'idea_pursued'::text, 'lessons_due'::text, 'predict_due'::text])))
);

