    CONSTRAINT sent_messages_request_id_form CHECK ((request_id ~ '^[A-Za-z0-9_-]{8,64}$'::text)),
    CONSTRAINT sent_messages_source_item_fp CHECK ((source_item_fp ~ '^[0-9a-f]{64}$'::text)),
