    CONSTRAINT signal_marks_question_sources CHECK (((question_sources IS NULL) OR (((cardinality(question_sources) >= 1) AND (cardinality(question_sources) <= 10)) AND (array_position(question_sources, NULL::text) IS NULL) AND (array_to_string(question_sources, ','::text) ~ '^([0-9a-f]{64}|rec_[0-9A-HJKMNP-TV-Z]{26})(,([0-9a-f]{64}|rec_[0-9A-HJKMNP-TV-Z]{26}))*$'::text)))),
    CONSTRAINT signal_marks_question_tools CHECK (((question_tools IS NULL) OR (((cardinality(question_tools) >= 1) AND (cardinality(question_tools) <= 5)) AND (array_position(question_tools, NULL::text) IS NULL)))),
    CONSTRAINT signal_marks_ref_kind CHECK ((ref_kind = ANY (ARRAY['commitment'::text, 'next_step'::text, 'plan'::text, 'calendar'::text, 'message'::text, 'event'::text, 'entity'::text, 'opportunity'::text]))),
    CONSTRAINT signal_marks_request_id_form CHECK ((request_id ~ '^[A-Za-z0-9_-]{8,64}$'::text)),
    CONSTRAINT signal_marks_state CHECK ((state = ANY (ARRAY['handled'::text, 'drafted'::text, 'needs_owner'::text])))
);

