CREATE TABLE ledger.source_checks (
    id bigint NOT NULL,
    target text NOT NULL,
    kind text NOT NULL,
    target_key text NOT NULL,
    relation_id bigint,
    relation_judge text,
    judge text NOT NULL,
    verdict text,
    code text,
    cited integer,
    on_cited boolean DEFAULT false NOT NULL,
    claim_keys text[] NOT NULL,
    evidence_ids text[] DEFAULT '{}'::text[] NOT NULL,
    compartments text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    hot text,
    census boolean DEFAULT false NOT NULL,
    live boolean NOT NULL,
    owner_new boolean,
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1)),
    CONSTRAINT source_checks_census CHECK (((NOT census) OR (starts_with(judge, 'model:'::text) AND (target = ANY (ARRAY['relation'::text, 'identity'::text])) AND (hot IS NULL)))),
    CONSTRAINT source_checks_cited CHECK (((cited IS NULL) OR ((cited >= 1) AND (cited <= 20)))),
    CONSTRAINT source_checks_claim_keys CHECK ((((cardinality(claim_keys) = 0) AND starts_with(judge, 'owner:'::text)) OR (((cardinality(claim_keys) >= 1) AND (cardinality(claim_keys) <= 20)) AND (array_to_string(claim_keys, ','::text) ~ '^[0-9a-f]{64}(,[0-9a-f]{64})*$'::text)))),
    CONSTRAINT source_checks_code CHECK (((code IS NULL) OR (code ~ '^[a-z][a-z0-9_]{0,31}$'::text))),
    CONSTRAINT source_checks_evidence_ids CHECK ((cardinality(evidence_ids) <= 20)),
    CONSTRAINT source_checks_hot CHECK (((hot IS NULL) OR ((hot = ANY (ARRAY['served'::text, 'new_evidence'::text])) AND (target = 'belief'::text) AND starts_with(judge, 'model:'::text)))),
    CONSTRAINT source_checks_judge CHECK (((judge ~ '^model:[A-Za-z0-9_./:-]{1,100}@[A-Za-z0-9_.-]{1,64}(@[1-9][0-9]{0,3})?$'::text) OR (judge ~ '^owner:rul_[0-9A-HJKMNP-TV-Z]{26}$'::text) OR (judge ~ '^owner:mrk_[0-9A-HJKMNP-TV-Z]{26}$'::text))),
    CONSTRAINT source_checks_kind CHECK ((kind ~ '^[a-z][a-z0-9_]{0,31}$'::text)),
    CONSTRAINT source_checks_owner_new CHECK (((owner_new IS NULL) OR starts_with(judge, 'owner:mrk_'::text))),
    CONSTRAINT source_checks_relation CHECK ((((target = ANY (ARRAY['relation'::text, 'identity'::text])) = (relation_judge IS NOT NULL)) AND ((target <> ALL (ARRAY['relation'::text, 'identity'::text])) OR (relation_id IS NOT NULL) OR (cardinality(claim_keys) = 0)) AND ((target = ANY (ARRAY['relation'::text, 'identity'::text])) OR (relation_id IS NULL)))),
    CONSTRAINT source_checks_relation_judge CHECK (((relation_judge IS NULL) OR (relation_judge ~ '^model:[A-Za-z0-9_./:-]{1,100}@[A-Za-z0-9_.-]{1,64}(@[1-9][0-9]{0,3})?$'::text))),
    CONSTRAINT source_checks_shape CHECK (((verdict IS NULL) <> (code IS NULL))),
    CONSTRAINT source_checks_target CHECK ((target = ANY (ARRAY['belief'::text, 'relation'::text, 'identity'::text]))),
    CONSTRAINT source_checks_target_key CHECK ((target_key ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT source_checks_verdict CHECK (((verdict IS NULL) OR (verdict = ANY (ARRAY['supported'::text, 'unsupported'::text, 'wrong'::text]))))
);

ALTER TABLE ONLY ledger.source_checks FORCE ROW LEVEL SECURITY;

ALTER TABLE ledger.source_checks ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME ledger.source_checks_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

