    CONSTRAINT trigger_log_clearance CHECK ((clearance_key <> ''::text)),
    CONSTRAINT trigger_log_none CHECK (((raise <> 'none'::text) OR (raised_at IS NOT NULL))),
    CONSTRAINT trigger_log_outcome CHECK ((((raise = 'outcome'::text) = (outcome_link_id IS NOT NULL)) AND ((raise = 'outcome'::text) = (cause = 'outcome'::text)))),
    CONSTRAINT trigger_log_raise CHECK ((raise = ANY (ARRAY['changed'::text, 'due'::text, 'none'::text, 'outcome'::text]))),
    CONSTRAINT trigger_log_state_form CHECK ((state_fp ~ '^[0-9a-f]{64}$'::text))
);

ALTER TABLE ONLY ledger.trigger_log FORCE ROW LEVEL SECURITY;

