    CONSTRAINT trigger_rechecks_clearance CHECK (((clearance_key IS NULL) OR (clearance_key <> ''::text))),
    CONSTRAINT trigger_rechecks_clock CHECK (((cause <> 'due'::text) OR ((clearance_key IS NOT NULL) AND (window_from IS NOT NULL) AND (window_to IS NOT NULL)))),
    CONSTRAINT trigger_rechecks_failures CHECK ((failures >= 0))
);

ALTER TABLE ONLY ledger.trigger_rechecks FORCE ROW LEVEL SECURITY;

