CREATE TABLE ledger.work_notices (
    id text NOT NULL,
    client_id text,
    opportunity_id text,
    event text,
    tier text,
    kind text,
    role text,
    txid bigint NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    last_code text,
    next_try_at timestamp with time zone DEFAULT now() NOT NULL,
    delivered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    due_at timestamp with time zone,
    outcome_kind text,
    outcome_link_id bigint,
    outcome_ref_kind text,
    outcome_ref_id text,
    ping_rung integer,
    batched boolean DEFAULT false NOT NULL,
    CONSTRAINT work_notices_attempts CHECK ((attempts >= 0)),
    CONSTRAINT work_notices_error CHECK (
CASE
    WHEN (client_id IS NULL) THEN ((state = 'failed'::text) AND (last_code = 'notice_error'::text))
    ELSE ((opportunity_id IS NOT NULL) AND (event IS NOT NULL) AND (tier IS NOT NULL) AND (kind IS NOT NULL) AND (last_code IS DISTINCT FROM 'notice_error'::text))
END),
    CONSTRAINT work_notices_event CHECK ((event = ANY (ARRAY['task_go'::text, 'routed'::text, 'returned'::text, 'opportunity_go'::text, 'stage_cleared'::text, 'intention_due'::text, 'outcome'::text, 'fallback'::text]))),
    CONSTRAINT work_notices_id_form CHECK ((id ~ '^ntc_[0-9A-HJKMNP-TV-Z]{26}$'::text)),
    CONSTRAINT work_notices_last_code CHECK ((last_code ~ '^([a-z][a-z0-9]*(_[a-z0-9]+)*|http_[0-9]{3})$'::text)),
    CONSTRAINT work_notices_outcome CHECK ((((COALESCE(event, ''::text) = 'outcome'::text) = ((outcome_kind IS NOT NULL) AND (outcome_link_id IS NOT NULL))) AND ((outcome_ref_kind IS NULL) = (outcome_ref_id IS NULL)) AND ((outcome_kind IS NOT NULL) OR (outcome_ref_kind IS NULL)))),
    CONSTRAINT work_notices_outcome_kind CHECK ((outcome_kind = ANY (ARRAY['met'::text, 'not_met'::text, 'partial'::text, 'advances'::text]))),
    CONSTRAINT work_notices_outcome_ref_kind CHECK ((outcome_ref_kind = ANY (ARRAY['message'::text, 'event'::text]))),
    CONSTRAINT work_notices_ping_rung CHECK ((ping_rung >= 0)),
