CREATE TABLE ledger.work_watches (
    id bigint NOT NULL,
    opportunity_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text NOT NULL,
    kind text NOT NULL,
    watch_key text NOT NULL,
    account_id text,
    send_id text,
    evidence_id text,
    until timestamp with time zone,
    compartments text[] NOT NULL,
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1)),
    CONSTRAINT work_watches_by CHECK ((created_by ~ '^(client:cli_[0-9A-HJKMNP-TV-Z]{26}|system:[a-z][a-z0-9_]*)$'::text)),
    CONSTRAINT work_watches_key CHECK (
CASE kind
    WHEN 'thread'::text THEN ((watch_key ~ '^[0-9a-f]{64}$'::text) AND (account_id IS NOT NULL))
    WHEN 'series'::text THEN (watch_key ~ '^[0-9a-f]{64}$'::text)
    WHEN 'entity'::text THEN ((watch_key ~ '^ent_[0-9A-HJKMNP-TV-Z]{26}$'::text) AND (account_id IS NULL))
    ELSE ((watch_key ~ '^doc_[0-9A-HJKMNP-TV-Z]{26}$'::text) AND (account_id IS NULL))
END),
    CONSTRAINT work_watches_kind CHECK ((kind = ANY (ARRAY['thread'::text, 'entity'::text, 'document'::text, 'series'::text])))
);

ALTER TABLE ONLY ledger.work_watches FORCE ROW LEVEL SECURITY;

