CREATE VIEW projections.reverse_dependency_index WITH (security_invoker='true') AS
 SELECT 'draft'::text AS dependent_kind,
    b.draft_id AS dependent_id,
    b.fact_key_fp,
    b.state_fp,
    ( SELECT min(r.at) AS min
           FROM (ledger.sent_messages s
             JOIN ledger.record_events r ON (((r.row_kind = 'send'::text) AND (r.row_id = s.id) AND (r.event = 'sent'::text))))
          WHERE (s.draft_id = b.draft_id)) AS left_at,
    b.compartments
   FROM ledger.draft_beliefs b
UNION ALL
 SELECT 'memory_entry'::text AS dependent_kind,
    p.id AS dependent_id,
    p.fact_key_fp,
    p.state_fp,
    p.first_served_at AS left_at,
    p.compartments
   FROM ledger.memory_projections p;

