CREATE TABLE vault.source_accounts (
    id text NOT NULL,
    label text NOT NULL,
    connector text NOT NULL,
    source_kind text NOT NULL,
    compartments text[] NOT NULL,
    address_fp text,
    address_enc jsonb,
    cursor_enc jsonb,
    cursor_updated_at timestamp with time zone,
    last_sync_at timestamp with time zone,
    last_outcome text,
    skipped_items integer DEFAULT 0 NOT NULL,
    send_as_enc jsonb,
    CONSTRAINT compartments_not_empty CHECK ((cardinality(compartments) >= 1)),
    CONSTRAINT compartments_single CHECK ((cardinality(compartments) = 1)),
    CONSTRAINT compartments_syntax CHECK (vault.compartments_valid(compartments)),
    CONSTRAINT source_accounts_agent_address CHECK ((((connector = ANY (ARRAY['agent'::text, 'web'::text, 'lens_meetings'::text, 'lens_activity'::text, 'lens_blocks'::text, 'contacts_import'::text, 'agent_people'::text, 'lens_tasks'::text, 'lens_contacts'::text, 'owner_command'::text])) AND (address_fp IS NULL) AND (address_enc IS NULL)) OR ((connector <> ALL (ARRAY['agent'::text, 'web'::text, 'lens_meetings'::text, 'lens_activity'::text, 'lens_blocks'::text, 'contacts_import'::text, 'agent_people'::text, 'lens_tasks'::text, 'lens_contacts'::text, 'owner_command'::text])) AND (address_fp IS NOT NULL) AND (address_enc IS NOT NULL)))),
    CONSTRAINT source_accounts_agent_people CHECK (((connector <> 'agent_people'::text) OR ((label ~ '^agent-people:[a-z][a-z0-9-]{1,39}$'::text) AND (compartments = ARRAY['own'::text])))),
    CONSTRAINT source_accounts_connector_check CHECK ((connector = ANY (ARRAY['google_mail'::text, 'google_calendar'::text, 'google_docs'::text, 'agent'::text, 'google_contacts'::text, 'web'::text, 'lens_meetings'::text, 'lens_activity'::text, 'lens_blocks'::text, 'contacts_import'::text, 'agent_people'::text, 'lens_tasks'::text, 'lens_contacts'::text, 'owner_command'::text]))),
    CONSTRAINT source_accounts_import CHECK (((connector <> 'contacts_import'::text) OR ((label ~ '^import:[a-z][a-z0-9-]{1,39}$'::text) AND (compartments = ARRAY['own'::text])))),
    CONSTRAINT source_accounts_kind_of_connector CHECK ((((connector = 'google_mail'::text) AND (source_kind = 'email'::text)) OR ((connector = 'google_calendar'::text) AND (source_kind = 'calendar'::text)) OR ((connector = 'google_docs'::text) AND (source_kind = 'document'::text)) OR ((connector = 'agent'::text) AND (source_kind = 'agent_record'::text)) OR ((connector = 'google_contacts'::text) AND (source_kind = 'crm'::text)) OR ((connector = 'web'::text) AND (source_kind = 'web_research'::text)) OR ((connector = 'lens_meetings'::text) AND (source_kind = 'transcript'::text)) OR ((connector = 'lens_activity'::text) AND (source_kind = 'screen_activity'::text)) OR ((connector = 'lens_blocks'::text) AND (source_kind = 'time_block'::text)) OR ((connector = 'contacts_import'::text) AND (source_kind = 'crm'::text)) OR ((connector = 'agent_people'::text) AND (source_kind = 'crm'::text)) OR ((connector = 'lens_tasks'::text) AND (source_kind = 'owner_task'::text)) OR ((connector = 'lens_contacts'::text) AND (source_kind = 'crm'::text)) OR ((connector = 'owner_command'::text) AND (source_kind = 'owner_command'::text)))),
    CONSTRAINT source_accounts_last_outcome_check CHECK ((last_outcome ~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*$'::text)),
    CONSTRAINT source_accounts_lens CHECK (((connector <> ALL (ARRAY['lens_meetings'::text, 'lens_activity'::text, 'lens_blocks'::text, 'lens_tasks'::text, 'lens_contacts'::text])) OR ((label ~ '^device:[a-z][a-z0-9-]{1,39}$'::text) AND (compartments = ARRAY['own'::text])))),
    CONSTRAINT source_accounts_owner_command CHECK (((connector <> 'owner_command'::text) OR (label = ('owner:'::text || compartments[1])))),
    CONSTRAINT source_accounts_skipped_items_check CHECK ((skipped_items >= 0)),
    CONSTRAINT source_accounts_web CHECK (((connector <> 'web'::text) OR ((label = ANY (ARRAY['public'::text, 'own'::text])) AND (compartments = ARRAY[label]))))
);

