CREATE POLICY pi_reader_select ON projections.declassified_facts FOR SELECT TO pi_reader USING (((compartments <@ ( SELECT policy.client_clearance() AS client_clearance)) AND (policy.label_key(compartments) = ANY (( SELECT policy.clearance_keys() AS clearance_keys)::text[]))));

CREATE POLICY pi_reader_select ON projections.goal_state FOR SELECT TO pi_reader USING (((compartments <@ ( SELECT policy.client_clearance() AS client_clearance)) AND (policy.label_key(compartments) = ANY (( SELECT policy.clearance_keys() AS clearance_keys)::text[])) AND ((( SELECT policy.current_client_kind() AS current_client_kind) = 'reasoner'::text) OR ( SELECT (('list_goals'::text = ANY (c.tools)) AND ('work'::text = ANY (c.views)))
   FROM policy.current_client() c(id, name, compartments, views, tools)) OR (( SELECT ('work'::text = ANY (c.views))
   FROM policy.current_client() c(id, name, compartments, views, tools)) AND (EXISTS ( SELECT 1
   FROM (ledger.opportunities o
     JOIN queue.leases l ON (((l.resource_kind = 'opportunity'::text) AND (l.resource_id = o.id))))
  WHERE ((o.goal_id = goal_state.goal_id) AND (l.holder = ( SELECT c.id
           FROM policy.current_client() c(id, name, compartments, views, tools))) AND (l.lease_until >= now()))))))));

